#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include "external_logging_library.h" // Placeholder for an actual logging library

typedef struct {
    int value;
} record;

// Custom memory pool (simplified version)
#define POOL_SIZE 1024 * 1024 // Example size, adjust based on needs
char custom_memory_pool[POOL_SIZE];
size_t pool_offset = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&pool_lock);
    if (pool_offset + size > POOL_SIZE) {
        pthread_mutex_unlock(&pool_lock);
        return NULL; // Pool is exhausted
    }
    void* ptr = custom_memory_pool + pool_offset;
    pool_offset += size;
    pthread_mutex_unlock(&pool_lock);
    return ptr;
}

void free_all(void** array, int count) {
    for (int i = 0; i < count; ++i) {
        if (array[i]) {
            free(array[i]);
            array[i] = NULL;
        }
    }
}

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t offset_size;
    size_t key_size;
    size_t record_size;
} data_structures;

data_structures init_data_structures(size_t offset_size, size_t key_size, size_t record_size, 
                                     int key_min, int key_max) {
    pthread_mutex_lock(&pool_lock); // Ensure thread safety during initialization

    data_structures ds = {0};
    ds.offsets = (long*)allocate_from_pool(offset_size * sizeof(long));
    if (!ds.offsets) goto cleanup;

    ds.keys = (int*)allocate_from_pool(key_size * sizeof(int));
    if (!ds.keys) goto cleanup;

    ds.records = (record*)allocate_from_pool(record_size * sizeof(record));
    if (!ds.records) goto cleanup;

    ds.offset_size = offset_size;
    ds.key_size = key_size;
    ds.record_size = record_size;

    for (size_t i = 0; i < offset_size; ++i) {
        ds.offsets[i] = rand() % key_max + key_min; // Example initialization
    }

    for (size_t i = 0; i < key_size; ++i) {
        ds.keys[i] = rand() % (key_max - key_min + 1) + key_min;
    }

    int used_keys[record_size];
    for (int i = 0; i < record_size; ++i) {
        used_keys[i] = -1;
    }

    for (size_t i = 0; i < record_size; ) {
        int value = rand() % (key_max - key_min + 1) + key_min;
        int found = 0;
        for (int j = 0; j < record_size; ++j) {
            if (used_keys[j] == value) {
                found = 1;
                break;
            }
        }

        if (!found) {
            ds.records[i].value = value;
            used_keys[i] = value;
            i++;
        }
    }

    pthread_mutex_unlock(&pool_lock);
    return ds;

cleanup:
    free_all((void*[]){ds.offsets, ds.keys, ds.records}, 3);
    pthread_mutex_unlock(&pool_lock);
    log_error("Memory allocation failed."); // Use external logging library
    return (data_structures){0};
}

// Function to dynamically resize arrays if needed
int resize_data_structures(data_structures* ds, size_t new_offset_size, size_t new_key_size, 
                           size_t new_record_size) {
    pthread_mutex_lock(&pool_lock);

    long* new_offsets = realloc(ds->offsets, new_offset_size * sizeof(long));
    int* new_keys = realloc(ds->keys, new_key_size * sizeof(int));
    record* new_records = realloc(ds->records, new_record_size * sizeof(record));

    if (!new_offsets || !new_keys || !new_records) {
        free_all((void*[]){new_offsets, new_keys, new_records}, 3);
        pthread_mutex_unlock(&pool_lock);
        log_error("Memory reallocation failed.");
        return -1;
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;

    ds->offset_size = new_offset_size;
    ds->key_size = new_key_size;
    ds->record_size = new_record_size;

    pthread_mutex_unlock(&pool_lock);
    log_info("Data structures resized successfully.");
    return 0;
}

// Usage example
int main() {
    data_structures ds = init_data_structures(100, 50, 30, 1, 100);

    // Example of resizing
    if (resize_data_structures(&ds, 200, 100, 60) != 0) {
        log_error("Failed to resize data structures.");
    }

    // Clean up
    free_all((void*[]){ds.offsets, ds.keys, ds.records}, 3);

    return 0;
}
```

