#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_THREADS 4

typedef struct {
    char *filename;
} FileTask;

void *process_file(void *arg) {
    FileTask *task = (FileTask *)arg;
    FILE *file = fopen(task->filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file %s: %s\n", task->filename, strerror(errno));
        free(task);
        return NULL;
    }

    int line_count = 0, word_count = 0, char_count = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file)) {
        line_count++;
        char *ptr = buffer;
        while (*ptr) {
            if (*ptr == ' ' || *ptr == '\n' || *ptr == '\t') {
                word_count++;
            }
            char_count++;
            ptr++;
        }
    }

    fclose(file);

    printf("File: %s, Lines: %d, Words: %d, Characters: %d\n",
           task->filename, line_count, word_count + 1, char_count);

    free(task);
    return NULL;
}

void display_help() {
    printf("Usage:\n");
    printf("  program [options] file...\n");
    printf("\nOptions:\n");
    printf("  -h, --help          Display this help information.\n");
    printf("  -c, --count         Print the total number of lines in the input files.\n");
    printf("  -s, --statistics    Print statistics about the input files.\n");
    printf("  -o, --output        Specify an output file to write results to.\n");
    printf("  -m, --manpage       Display detailed documentation similar to man pages.\n");
}

void display_manpage() {
    printf("Detailed Documentation:\n");
    // Add more detailed information here
}

int main(int argc, char *argv[]) {
    int opt;
    FILE *output_file = stdout;
    char *output_filename = NULL;
    int count_mode = 0, stats_mode = 0;

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"count", no_argument, 0, 'c'},
        {"statistics", no_argument, 0, 's'},
        {"output", required_argument, 0, 'o'},
        {"manpage", no_argument, 0, 'm'},
        {0, 0, 0, 0}
    };

    while ((opt = getopt_long(argc, argv, "hcsom:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                display_help();
                return 0;
            case 'c':
                count_mode = 1;
                break;
            case 's':
                stats_mode = 1;
                break;
            case 'o':
                output_filename = optarg;
                if ((output_file = fopen(optarg, "w")) == NULL) {
                    fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
                    return EXIT_FAILURE;
                }
                break;
            case 'm':
                display_manpage();
                return 0;
            default:
                display_help();
                return EXIT_FAILURE;
        }
    }

    if (optind >= argc) {
        fprintf(stderr, "Expected argument after options.\n");
        display_help();
        return EXIT_FAILURE;
    }

    int file_count = argc - optind;
    pthread_t threads[MAX_THREADS];
    FileTask *tasks[file_count];

    for (int i = 0; i < file_count; ++i) {
        tasks[i] = malloc(sizeof(FileTask));
        if (!tasks[i]) {
            fprintf(stderr, "Memory allocation failed.\n");
            return EXIT_FAILURE;
        }
        tasks[i]->filename = argv[optind + i];
    }

    int active_threads = 0;
    for (int i = 0; i < file_count; ++i) {
        while (active_threads >= MAX_THREADS) {
            pthread_join(threads[0], NULL);
            memmove(&threads[0], &threads[1], sizeof(pthread_t) * --active_threads);
        }
        pthread_create(&threads[active_threads++], NULL, process_file, tasks[i]);
    }

    for (int i = 0; i < active_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (output_filename && output_file != stdout) {
        fclose(output_file);
    }

    return EXIT_SUCCESS;
}
```']

