#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/socket.h>

#define MAX_HOSTNAME_LENGTH 256
#define DNS_CACHE_SIZE 10
#define MAX_LOG_LINE_LENGTH 1024
#define MAX_CONCURRENT_QUERIES 5

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    char ip_address[INET6_ADDRSTRLEN];
} DnsCacheEntry;

DnsCacheEntry dns_cache[DNS_CACHE_SIZE];
int cache_index = 0;
pthread_mutex_t lock;

void init_dns_cache() {
    memset(dns_cache, 0, sizeof(dns_cache));
}

char* resolve_hostname(const char *hostname) {
    pthread_mutex_lock(&lock);

    // Check DNS Cache
    for (int i = 0; i < DNS_CACHE_SIZE; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            pthread_mutex_unlock(&lock);
            return dns_cache[i].ip_address;
        }
    }

    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        pthread_mutex_unlock(&lock);
        return "DNS resolution failed";
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        char ipstr[INET6_ADDRSTRLEN];
        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));

        strncpy(dns_cache[cache_index].hostname, hostname, MAX_HOSTNAME_LENGTH - 1);
        strncpy(dns_cache[cache_index].ip_address, ipstr, INET6_ADDRSTRLEN - 1);

        cache_index = (cache_index + 1) % DNS_CACHE_SIZE;

        freeaddrinfo(res);
        pthread_mutex_unlock(&lock);
        return dns_cache[cache_index - 1].ip_address;
    }

    freeaddrinfo(res);
    pthread_mutex_unlock(&lock);
    return "DNS resolution failed";
}

void process_log_line(char *line) {
    char *token, *rest = line;
    char output[MAX_LOG_LINE_LENGTH] = {0};
    int field_count = 0;

    while ((token = strtok_r(rest, ",", &rest))) {
        if (field_count > 0) {
            strcat(output, ",");
        }
        strcat(output, token);
        ++field_count;

        if (field_count == line - output && isdigit(token[0])) {
            int num1 = atoi(token), num2 = field_count < strlen(line) ? atoi(strtok_r(NULL, ",", &rest)) : 0;
            if (num2 != 0) {
                double average = ((double)num1 + num2) / 2.0;
                char avg_str[32];
                snprintf(avg_str, sizeof(avg_str), "%f", average);
                strcat(output, ",");
                strcat(output, avg_str);
                break; // Processed the line
            }
        }
    }

    printf("%s\n", output);
}

int main() {
    FILE *file = fopen("log.txt", "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    init_dns_cache();
    pthread_mutex_init(&lock, NULL);

    char *line = NULL;
    size_t len = 0;

    while (getline(&line, &len, file) != -1) {
        process_log_line(line);
    }

    free(line);
    fclose(file);
    pthread_mutex_destroy(&lock);

    return EXIT_SUCCESS;
}
```

This C program includes a DNS resolution function with caching and processes log entries to calculate averages. It uses standard library functions for network operations and file handling, managing resources efficiently.']

