#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define BUFFER_SIZE 1024

int findLargestInteger(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return INT_MIN;
    }

    int largest = INT_MIN;
    int buffer[BUFFER_SIZE];
    size_t bytesRead, numbersRead;

    while ((bytesRead = fread(buffer, sizeof(int), BUFFER_SIZE, file)) > 0) {
        numbersRead = bytesRead; // Assuming valid input

        for (size_t i = 0; i < numbersRead; ++i) {
            if (buffer[i] > largest) {
                largest = buffer[i];
            }
        }
    }

    if (ferror(file)) {
        perror("Error reading file");
        fclose(file);
        return INT_MIN;
    }

    fclose(file);
    return largest;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int result = findLargestInteger(argv[1]);

    if (result == INT_MIN) {
        fprintf(stderr, "An error occurred or no valid integers found.\n");
        return EXIT_FAILURE;
    }

    printf("The largest integer is: %d\n", result);
    return EXIT_SUCCESS;
}
