```c
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    char *logFilePath;
    int logLevel;
    pthread_mutex_t lock;
    size_t maxLogSize;
} LoggerConfig;

LoggerConfig globalLogger = {"/var/log/app.log", LOG_LEVEL_WARNING, PTHREAD_MUTEX_INITIALIZER, 10485760}; // Default to 10MB

void setLogFilePath(const char *filePath) {
    if (globalLogger.logFilePath != NULL) free(globalLogger.logFilePath);
    globalLogger.logFilePath = strdup(filePath);
}

void setLogLevel(int level) {
    globalLogger.logLevel = level;
}

void setMaxLogSize(size_t size) {
    globalLogger.maxLogSize = size;
}

const char* getLogLevelString(int level) {
    switch (level) {
        case LOG_LEVEL_INFO: return "INFO";
        case LOG_LEVEL_WARNING: return "WARNING";
        case LOG_LEVEL_ERROR: return "ERROR";
        default: return "UNKNOWN";
    }
}

void rotateLogFile(const char *filePath) {
    // Simple file rotation strategy
    FILE *source = fopen(filePath, "r");
    if (source == NULL) return;

    struct stat fileInfo;
    if (fstat(fileno(source), &fileInfo) != 0 || fileInfo.st_size <= globalLogger.maxLogSize)
        return;

    fclose(source);

    char newFilePath[256];
    snprintf(newFilePath, sizeof(newFilePath), "%s.%ld", filePath, time(NULL));
    rename(filePath, newFilePath);
}

void logMessage(int level, const char *format, ...) {
    if (level < globalLogger.logLevel) return;

    pthread_mutex_lock(&globalLogger.lock);

    rotateLogFile(globalLogger.logFilePath);

    FILE *logFile = fopen(globalLogger.logFilePath, "a");
    if (!logFile) {
        pthread_mutex_unlock(&globalLogger.lock);
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

    va_list args;
    va_start(args, format);

    fprintf(logFile, "[%s] [%s] ", timestamp, getLogLevelString(level));
    vfprintf(logFile, format, args);
    fprintf(logFile, "\n");

    va_end(args);
    fclose(logFile);

    pthread_mutex_unlock(&globalLogger.lock);
}

// Example usage
int main() {
    setLogFilePath("/tmp/app.log");
    setLogLevel(LOG_LEVEL_INFO);
    setMaxLogSize(1024 * 1024); // 1MB

    logMessage(LOG_LEVEL_INFO, "Application started.");
    logMessage(LOG_LEVEL_WARNING, "This is a warning message.");
    logMessage(LOG_LEVEL_ERROR, "An error occurred: %s", "File not found");

    return 0;
}
```

### Key Features:
