import os
import time
import queue
from threading import Thread
from typing import List

def read_log_file(file_path: str, encoding='utf-8', noise_words=None) -> List[str]:
    if noise_words is None:
        noise_words = {"INFO", "DEBUG"}

    error_codes = set()
    seen_lines = set()

    def process_line(line):
        parts = line.split()
        for word in parts:
            if word.startswith("ERROR") and word not in noise_words:
                error_codes.add(word)

    def read_file():
        with open(file_path, 'r', encoding=encoding) as f:
            while True:
                line = f.readline()
                if not line:
                    time.sleep(0.1)
                    continue
                if line not in seen_lines:
                    process_line(line.strip())
                    seen_lines.add(line)

    def integrate_with_logging_service():
        q = queue.Queue(maxsize=100)
        while True:
            try:
                error_code = q.get(timeout=1)
                # Simulate sending to an external logging service
                print(f"Sending {error_code} to logging service...")
                time.sleep(0.5)  # Simulate network delay
            except queue.Empty:
                continue

    reader_thread = Thread(target=read_file, daemon=True)
    logger_thread = Thread(target=integrate_with_logging_service, daemon=True)

    reader_thread.start()
    logger_thread.start()

    try:
        while True:
            for error_code in error_codes:
                if q.full():
                    time.sleep(0.1)  # Handle backpressure
                q.put(error_code)
            time.sleep(5)  # Adjust batch processing interval
    except KeyboardInterrupt:
        pass

    reader_thread.join(timeout=1)
    logger_thread.join(timeout=1)

    return sorted(error_codes)

# Example usage
if __name__ == "__main__":
    log_file_path = "path/to/your/logfile.log"
    unique_error_codes = read_log_file(log_file_path)
    print(unique_error_codes)
