#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>

// External logging framework headers (hypothetical)
#include "external_logging.h"
#include "cipher_library.h"

#define MAX_KEY_SIZE 32
#define LOG_FILE "encryption_log.txt"

typedef struct {
    char *input_file;
    char *output_file;
    int mode; // 0 for encryption, 1 for decryption
    char *cipher_mode;
    size_t key_size;
    char *key;
    char *iv;
    int use_custom_iv;
    int async_mode;
    int generate_checksum;
} EncryptionOptions;

typedef struct {
    pthread_mutex_t lock;
    FILE *log_file;
} LoggerContext;

LoggerContext logger_ctx;

void log_message(const char *message) {
    pthread_mutex_lock(&logger_ctx.lock);
    fprintf(logger_ctx.log_file, "%s\n", message);
    fflush(logger_ctx.log_file);
    pthread_mutex_unlock(&logger_ctx.lock);
}

int validate_input_file(const char *file_path, const char *expected_ext) {
    struct stat file_stat;
    if (lstat(file_path, &file_stat) != 0) {
        log_message("File does not exist or cannot be accessed.");
        return -1;
    }
    if ((file_stat.st_mode & S_IFMT) == S_IFLNK) {
        log_message("Symbolic links are not supported.");
        return -1;
    }
    char *ext = strrchr(file_path, '.');
    if (!ext || strcmp(ext, expected_ext)) {
        log_message("File does not have the correct extension.");
        return -1;
    }
    return 0;
}

void process_file(EncryptionOptions *options) {
    if (validate_input_file(options->input_file, options->mode == 0 ? ".enc" : ".dec")) {
        exit(EXIT_FAILURE);
    }

    FILE *in = fopen(options->input_file, "rb");
    FILE *out = fopen(options->output_file, "wb");
    if (!in || !out) {
        log_message("Failed to open input or output file.");
        exit(EXIT_FAILURE);
    }

    // Initialize cipher
    CipherContext cipher;
    init_cipher(&cipher, options->cipher_mode, options->key_size, options->key, options->iv, options->use_custom_iv);

    size_t buffer_size = 4096;
    unsigned char *buffer = malloc(buffer_size);
    if (!buffer) {
        log_message("Memory allocation failed.");
        exit(EXIT_FAILURE);
    }

    while (1) {
        size_t bytes_read = fread(buffer, 1, buffer_size, in);
        if (bytes_read == 0) break;

        unsigned char *processed_data;
        size_t processed_length;
        if (options->mode == 0) { // Encryption
            process_encryption(&cipher, buffer, bytes_read, &processed_data, &processed_length);
        } else { // Decryption
            process_decryption(&cipher, buffer, bytes_read, &processed_data, &processed_length);
        }

        fwrite(processed_data, 1, processed_length, out);
        free(processed_data);
    }

    fclose(in);
    fclose(out);
    free(buffer);

    if (options->generate_checksum) {
        // Generate and log checksum
        unsigned char *checksum;
        size_t checksum_size;
        generate_checksum(options->output_file, &checksum, &checksum_size);
        log_message("Checksum generated.");
        free(checksum);
    }

    destroy_cipher(&cipher);
}

void *async_process(void *arg) {
    EncryptionOptions *options = (EncryptionOptions *)arg;
    process_file(options);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <input> <output> <mode> <cipher_mode> [key] [iv] [use_custom_iv]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    EncryptionOptions options = {0};
    options.input_file = argv[1];
    options.output_file = argv[2];
    options.mode = strcmp(argv[3], "encrypt") == 0 ? 0 : 1;
    options.cipher_mode = argv[4];

    if (argc > 5) options.key = argv[5];
    if (argc > 6) options.iv = argv[6];
    if (argc > 7) options.use_custom_iv = atoi(argv[7]);

    pthread_mutex_init(&logger_ctx.lock, NULL);
    logger_ctx.log_file = fopen(LOG_FILE, "a");
    if (!logger_ctx.log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    pthread_t thread;
    if (options.async_mode) {
        pthread_create(&thread, NULL, async_process, &options);
        pthread_join(thread, NULL);
    } else {
        process_file(&options);
    }

    fclose(logger_ctx.log_file);
    pthread_mutex_destroy(&logger_ctx.lock);

    return 0;
}
```

