int num_semaphores = 0;

// Function prototypes
Semaphore* create_semaphore(const char* name, int init_value);
void destroy_semaphore(Semaphore* sem);
char* semaphore_to_string(Semaphore* sem);
void cleanup_all_semaphores();
void adjust_semaphore_value(Semaphore* sem, int new_value);
void log_error(const char* message);

// Function to initialize a semaphore
Semaphore* create_semaphore(const char* name, int init_value) {
    pthread_mutex_lock(&name_mutex);

    for (int i = 0; i < num_semaphores; ++i) {
        if (strcmp(semaphores[i].name, name) == 0) {
            log_error("Semaphore with the same name already exists.");
            pthread_mutex_unlock(&name_mutex);
            return NULL;
        }
    }

    // Resize the semaphore storage
    Semaphore* new_semaphores = realloc(semaphores, sizeof(Semaphore) * (num_semaphores + 1));
    if (!new_semaphores) {
        log_error("Failed to allocate memory for new semaphore.");
        pthread_mutex_unlock(&name_mutex);
        return NULL;
    }

    semaphores = new_semaphores;

    // Create and initialize the semaphore
    Semaphore* sem = &semaphores[num_semaphores];
    if (sem_init(&sem->sem, 0, init_value) != 0) {
        log_error("Failed to initialize semaphore.");
        pthread_mutex_unlock(&name_mutex);
        return NULL;
    }

    strncpy(sem->name, name, sizeof(sem->name));
    sem->value = init_value;

    num_semaphores++;
    pthread_mutex_unlock(&name_mutex);

    return sem;
}

// Function to destroy a semaphore
void destroy_semaphore(Semaphore* sem) {
    if (sem_destroy(&sem->sem) != 0) {
        log_error("Failed to destroy semaphore.");
    }

    pthread_mutex_lock(&name_mutex);
    for (int i = 0; i < num_semaphores; ++i) {
        if (&semaphores[i] == sem) {
            memmove(&semaphores[i], &semaphores[i + 1], sizeof(Semaphore) * (num_semaphores - i - 1));
            num_semaphores--;
            break;
        }
    }
    pthread_mutex_unlock(&name_mutex);
}

// Convert semaphore value to a string for logging
char* semaphore_to_string(Semaphore* sem) {
    static char buffer[256];
    snprintf(buffer, sizeof(buffer), "Semaphore '%s': Value = %d", sem->name, sem->value);
    return buffer;
}

// Cleanup all semaphores in the system
void cleanup_all_semaphores() {
    for (int i = 0; i < num_semaphores; ++i) {
        destroy_semaphore(&semaphores[i]);
    }
    free(semaphores);
    semaphores = NULL;
    num_semaphores = 0;
}

// Adjust semaphore value dynamically
void adjust_semaphore_value(Semaphore* sem, int new_value) {
    if (sem->value != new_value) {
        while (sem_trywait(&sem->sem) == 0 && sem->value > new_value);
        while (sem_post(&sem->sem) == 0 && sem->value < new_value);
        sem->value = new_value;
    }
}

// Log errors to a centralized logging service
void log_error(const char* message) {
    // Placeholder for integration with an external logging service
    fprintf(stderr, "Error: %s\n", message);
}

// Integration point for configuration management (stub)
void integrate_with_config_service() {
    // Stub function for integrating with a config service to adjust semaphore values dynamically.
}

int main() {
    Semaphore* sem = create_semaphore("exampleSem", 5);

    if (sem) {
        printf("%s\n", semaphore_to_string(sem));
        destroy_semaphore(sem);
    }

    cleanup_all_semaphores();
    return 0;
}
```']

