    private const string LogDirectoryName = "AppLogs";

    public (bool success, string message) ParseXmlAndGetFirstElement(string xmlFilePath, string elementName)
    {
        // Ensure the log directory is created and environment variable is set
        SetupLogPath();

        try
        {
            if (!File.Exists(xmlFilePath))
                return (false, "XML file does not exist.");

            var xDoc = XDocument.Load(xmlFilePath);
            var elements = xDoc.XPathSelectElements($"//{elementName}");

            if (elements.Count() == 0)
                return (false, $"No elements found with name '{elementName}'.");
            if (elements.Count() > 1)
                return (false, $"Multiple elements found with name '{elementName}'.");

            var firstElement = elements.First();
            // Process the element as needed
            // For now, we just return success and a message indicating retrieval

            return (true, "First matching element retrieved successfully.");
        }
        catch (Exception ex)
        {
            return (false, $"An error occurred: {ex.Message}");
        }
    }

    private void SetupLogPath()
    {
        var logDirectory = Path.Combine(Directory.GetCurrentDirectory(), LogDirectoryName);

        // Use a lock to manage concurrent access
        lock (this)
        {
            if (!Directory.Exists(logDirectory))
                Directory.CreateDirectory(logDirectory);

            var logPathEnvVar = Environment.GetEnvironmentVariable("LOG_PATH");
            if (string.IsNullOrEmpty(logPathEnvVar) || !Directory.Exists(logPathEnvVar))
            {
                Environment.SetEnvironmentVariable("LOG_PATH", logDirectory, EnvironmentVariableTarget.Process);
            }
        }
    }
}
