    $dbPool = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password', [
        PDO::ATTR_PERSISTENT => true,
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION
    ]);

    // Input validation and sanitization
    if (!isset($_REQUEST['name'], $_REQUEST['email'])) {
        return json_encode(['status' => 'error', 'message' => 'Missing required fields']);
    }

    $name = filter_var(trim($_REQUEST['name']), FILTER_SANITIZE_STRING);
    $email = filter_var(trim($_REQUEST['email']), FILTER_VALIDATE_EMAIL);

    if (empty($name) || strlen($name) > 50 || !$email) {
        return json_encode(['status' => 'error', 'message' => 'Invalid name or email']);
    }

    $password = isset($_REQUEST['password']) ? trim($_REQUEST['password']) : '';
    if (!empty($password) && (strlen($password) < 8 || !preg_match('/\d/', $password) || !preg_match('/[^\w]/', $password))) {
        return json_encode(['status' => 'error', 'message' => 'Invalid password']);
    }

    $id = isset($_REQUEST['id']) ? (int)$_REQUEST['id'] : null;
    if ($id && $id <= 0) {
        return json_encode(['status' => 'error', 'message' => 'Invalid user ID']);
    }

    $subAction = isset($_REQUEST['sub_action']) ? $_REQUEST['sub_action'] : '';

    try {
        // Begin transaction
        $dbPool->beginTransaction();

        switch ($subAction) {
            case 'delete':
                if (!$id) {
                    throw new Exception('ID required for deletion');
                }

                $stmt = $dbPool->prepare("DELETE FROM users WHERE id = ?");
                $stmt->execute([$id]);
                if ($stmt->rowCount() === 0) {
                    throw new Exception('User not found');
                }

                // Invalidate cache
                $cacheKey = "user_{$id}";
                // Assume a function `deleteCache` exists to handle cache invalidation
                deleteCache($cacheKey);

                break;

            case 'update':
                if (!$id || !is_numeric($name) || !$email) {
                    throw new Exception('Invalid ID for update');
                }

                $stmt = $dbPool->prepare("SELECT * FROM users WHERE id = ?");
                $stmt->execute([$id]);
                $user = $stmt->fetch(PDO::FETCH_ASSOC);

                if (!$user) {
                    throw new Exception('User not found');
                }

                // Update logic
                $updateFields = [];
                $params = [$id];

                if (!empty($name)) {
                    $updateFields[] = "name = ?";
                    $params[] = $name;
                }

                if (!empty($email)) {
                    $updateFields[] = "email = ?";
                    $params[] = $email;
                }

                if (!empty($password)) {
                    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);
                    $updateFields[] = "password = ?";
                    $params[] = $hashedPassword;
                }

                $updateQuery = "UPDATE users SET " . implode(', ', $updateFields) . " WHERE id = ?";
                $stmt = $dbPool->prepare($updateQuery);
                $stmt->execute($params);

                // Invalidate cache
                $cacheKey = "user_{$id}";
                deleteCache($cacheKey);

                break;

            default:
                if (empty($password)) {
                    throw new Exception('Password required for creation');
                }

                $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

                $stmt = $dbPool->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
                $stmt->execute([$name, $email, $hashedPassword]);
                $id = $dbPool->lastInsertId();

                // Cache new user data
                $cacheKey = "user_{$id}";
                // Assume a function `setCache` exists to handle cache storage
                setCache($cacheKey, ['id' => $id, 'name' => $name, 'email' => $email]);

        }

        // Commit transaction
        $dbPool->commit();

        $response = [
            'status' => 'success',
            'message' => 'Operation successful',
            'data' => ['id' => $id, 'name' => $name, 'email' => $email]
        ];

    } catch (Exception $e) {
        // Rollback transaction on error
        $dbPool->rollBack();
        $response['message'] = $e->getMessage();
    }

    return json_encode($response);
}

