using System;
using System.Collections.Concurrent;
using System.Text.RegularExpressions;
using Microsoft.AspNetCore.Mvc;
using HtmlSanitizer;

[ApiController]
public class PageUpdateController : ControllerBase
{
    private static readonly TimeSpan RateLimitInterval = TimeSpan.FromMinutes(1);
    private static readonly int MaxRequestsPerMinute = 5;

    private readonly ConcurrentDictionary<string, (DateTime lastRequestTime, int requestCount)> _rateLimits = new();
    private readonly IPageService _pageService;
    private readonly ILogger<PageUpdateController> _logger;
    private readonly IMessagingService _messagingService;
    private readonly ICacheProvider _cacheProvider;

    public PageUpdateController(IPageService pageService, ILogger<PageUpdateController> logger, 
                                IMessagingService messagingService, ICacheProvider cacheProvider)
    {
        _pageService = pageService ?? throw new ArgumentNullException(nameof(pageService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _messagingService = messagingService ?? throw new ArgumentNullException(nameof(messagingService));
        _cacheProvider = cacheProvider ?? throw new ArgumentNullException(nameof(cacheProvider));
    }

    [HttpPost("update")]
    public IActionResult UpdateElement(string userId, int pageSectionId, int elementId, string htmlContent)
    {
        if (!IsValidId(pageSectionId) || !IsValidId(elementId))
        {
            return BadRequest("Invalid IDs.");
        }

        if (RateLimitExceeded(userId))
        {
            return TooManyRequests();
        }

        var sanitizedHtml = SanitizeHtml(htmlContent);
        if (string.IsNullOrEmpty(sanitizedHtml))
        {
            return BadRequest("Invalid HTML content.");
        }

        bool success = false;
        for (int attempt = 0; attempt < 3 && !success; attempt++)
        {
            try
            {
                _pageService.UpdateElement(pageSectionId, elementId, sanitizedHtml);

                // Cache the updated content
                _cacheProvider.Set($"Page_{pageSectionId}_Element_{elementId}", sanitizedHtml);

                _logger.LogInformation("Updated Element {0} in Page Section {1} for User {2}.", 
                                      elementId, pageSectionId, userId);
                success = true;
            }
            catch (TransientException ex)
            {
                _logger.LogWarning(ex, "Transient error encountered. Retrying...");
                if (attempt == 2) // Last attempt failed
                {
                    _messagingService.NotifyFailure(userId, pageSectionId, elementId, sanitizedHtml);
                }
            }
        }

        if (!success)
        {
            return StatusCode(500, "Failed to update after several attempts.");
        }

        var shouldRefresh = DeterminePageRefresh();
        return Ok(new { Refresh = shouldRefresh });
    }

    private bool IsValidId(int id) => id > 0; // Implement actual validation logic

    private string SanitizeHtml(string html)
    {
        var sanitizer = new HtmlSanitizer();
        return sanitizer.Sanitize(html);
    }

    private bool RateLimitExceeded(string userId)
    {
        if (_rateLimits.TryGetValue(userId, out var rateInfo))
        {
            if ((DateTime.UtcNow - rateInfo.lastRequestTime) < RateLimitInterval)
            {
                if (rateInfo.requestCount >= MaxRequestsPerMinute)
                    return true;

                _rateLimits[userId] = (rateInfo.lastRequestTime, rateInfo.requestCount + 1);
                return false;
            }
        }

        _rateLimits[userId] = (DateTime.UtcNow, 1);
        return false;
    }

    private IActionResult TooManyRequests() => StatusCode(429);

    private bool DeterminePageRefresh()
    {
        // Implement logic to determine if a page refresh is necessary
        return true; 
    }
}

public interface IPageService
{
    void UpdateElement(int pageSectionId, int elementId, string htmlContent);
}

public class TransientException : Exception { }

public interface IMessagingService
{
    void NotifyFailure(string userId, int pageSectionId, int elementId, string htmlContent);
}

public interface ICacheProvider
{
    void Set(string key, object value);
}
