public class ThemeLoader {
    private static final String DEFAULT_THEME_DIR = "default_theme";
    private static final ReentrantLock lock = new ReentrantLock();
    private static MoSTState cachedTheme = null;

    public MoSTState loadAndCacheTheme(String filePath) throws IOException {
        if (filePath == null || filePath.isEmpty()) {
            filePath = getDefaultThemeFilePath();
        }

        lock.lock();
        try {
            if (cachedTheme != null && isThemeValid(cachedTheme)) {
                return cachedTheme;
            }

            File file = new File(filePath);
            BufferedImage image = ImageIO.read(file);

            if (image == null) {
                throw new IOException("Failed to load theme from " + filePath);
            }

            MoSTState theme = parseTheme(image, filePath);

            // Set bitmap to null after use
            image.flush();

            cachedTheme = theme;
            return cachedTheme;
        } finally {
            lock.unlock();
        }
    }

    private String getDefaultThemeFilePath() {
        File defaultDir = new File(DEFAULT_THEME_DIR);
        if (!defaultDir.exists()) {
            defaultDir.mkdirs();
        }
        return new File(defaultDir, "theme.png").getAbsolutePath();
    }

    private boolean isThemeValid(MoSTState theme) {
        // Implement logic to check if the cached theme is still valid
        return true;
    }

    private MoSTState parseTheme(BufferedImage image, String filePath) throws IOException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            // Assuming MoSTState can be deserialized from the file
