```javascript
const fs = require('fs');
const path = require('path');
const util = require('util');
const { promisify } = require('util');

// Promisify necessary functions for async/await use
const readdirAsync = promisify(fs.readdir);
const statAsync = promisify(fs.stat);
const readFileAsync = promisify(fs.readFile);

/**
 * Asynchronously reads files from a directory, filters them by extension,
 * and returns an array of their contents.
 *
 * @param {string} dirPath - The path to the directory containing files.
 * @param {string} ext - The file extension to filter by (e.g., '.txt').
 * @returns {Promise<Array<string>>} A promise that resolves to an array of file contents.
 */
async function readFilesByExtension(dirPath, ext) {
  try {
    const files = await readdirAsync(dirPath);
    const results = [];

    for (const file of files) {
      const filePath = path.join(dirPath, file);

      try {
        const stats = await statAsync(filePath);

        if (stats.isFile() && path.extname(file).toLowerCase() === ext.toLowerCase()) {
          // Log the file operation
          console.log(`Reading file: ${filePath}`);

          const content = await readFileAsync(filePath, 'utf8');
          results.push(content);

          // Handle potential networked storage latency or issues here if needed
        }
      } catch (err) {
        // Log error without disrupting logging framework performance
        console.error(`Error accessing file ${file}:`, err);
      }
    }

    return results;
  } catch (err) {
    console.error('Error reading directory:', err);
    throw err;  // Rethrow after logging
  }
}

// Example usage:
(async () => {
  try {
    const contents = await readFilesByExtension('./myDirectory', '.txt');
    console.log(contents);
  } catch (error) {
    console.error('Failed to read files:', error);
  }
})();

module.exports = readFilesByExtension;

```

### Key Considerations:

- **Error Handling**: Errors are logged using `console.error`, which can be swapped out with the existing logging framework.
- **Asynchronous Operations**: Promises and async/await ensure that file operations do not block execution.
- **Memory Management**: The function processes files one-by-one, keeping memory usage minimal. This is important for large directories.
- **Modularity**: The filtering logic based on extension can be easily modified or extended to support more complex criteria.
- **Scalability & Performance**: By processing each file asynchronously and independently, the solution scales well with a large number of files.

### Testing:

For testing, you would write unit tests using a framework like Jest. Below is an example structure for such tests:

```javascript
const readFilesByExtension = require('./readFilesByExtension');
const fs = require('fs').promises;

// Mocking the file system and console.log for testing purposes

jest.mock('fs', () => ({
  readdir: jest.fn(),
  stat: jest.fn(),
  readFile: jest.fn(),
}));

jest.spyOn(console, 'log').mockImplementation(() => {});
jest.spyOn(console, 'error').mockImplementation(() => {});

describe('readFilesByExtension', () => {
  beforeEach(() => {
    // Reset mocks before each test
    fs.readdir.mockClear();
    fs.stat.mockClear();
    fs.readFile.mockClear();
  });

  it('should return contents of files with the specified extension', async () => {
    const mockDir = '/testDirectory';
    fs.readdir.mockResolvedValue(['file1.txt', 'file2.log', 'file3.txt']);

    fs.stat.mockImplementation((filePath) =>
      Promise.resolve({ isFile: () => filePath.endsWith('.txt') })
    );

    fs.readFile.mockImplementation((_, encoding) =>
      Promise.resolve('Mock file content')
    );

    const contents = await readFilesByExtension(mockDir, '.txt');

    expect(contents).toEqual(['Mock file content', 'Mock file content']);
  });

  it('should handle errors gracefully', async () => {
    const mockDir = '/errorDirectory';
    fs.readdir.mockResolvedValue(['file1.txt']);

    fs.stat.mockRejectedValue(new Error('Permission denied'));

    await expect(readFilesByExtension(mockDir, '.txt')).resolves.toEqual([]);

    // Ensure an error message is logged
    expect(console.error).toHaveBeenCalledWith(expect.stringContaining('Error accessing file file1.txt:'));
  });
});
