    mockFrameworkCleanup();
    console.error(`Test ${testName} failed with error:`, error);
    return { testName, status: 'fail', timeTaken: performance.now() - performance.now(), errorMessage: error.message };
  }
}

async function runTests(modulePath, testsConfig) {
  const module = require(modulePath);

  let testResults = [];

  for (const testName of Object.keys(testsConfig)) {
    if (process.env.SKIPTESTS && process.env.SKIPTESTS.includes(testName)) {
      console.log(`Skipping test ${testName}`);
      continue;
    }

    const { fn, skip } = testsConfig[testName];

    if (skip) {
      console.log(`Test ${testName} is skipped.`);
      testResults.push({ testName, status: 'skipped' });
      continue;
    }

    console.log(`Running test ${testName} for module ${modulePath}`);
    const result = await runTest(module, testName, fn);
    testResults.push(result);

    console.log(`${new Date().toISOString()} - Test ${result.testName}: ${result.status}, Time: ${result.timeTaken.toFixed(2)}ms`);
  }

  const passCount = testResults.filter(res => res.status === 'pass').length;
  const failCount = testResults.filter(res => res.status === 'fail').length;
  const avgTime = testResults.reduce((acc, curr) => acc + curr.timeTaken, 0) / testResults.length;

  console.log(`Test suite completed for module ${modulePath}`);
  console.log(`Passed: ${passCount}, Failed: ${failCount}, Average Time: ${(avgTime / 1000).toFixed(2)}s`);

  await logResults({ serviceName: 'MockLoggingService' }, {
    passRate: (passCount / testResults.length) * 100,
    failRate: (failCount / testResults.length) * 100,
    avgExecutionTime: avgTime
  });

  return { modulePath, results: testResults };
}

(async () => {
  const args = process.argv.slice(2);
  if (args.length < 1) {
    console.error('Please provide the module path as a command-line argument.');
    process.exit(1);
  }

  const modulePath = args[0];
  const testsConfig = require(`${modulePath}/testConfig.js`);

  try {
    await runTests(modulePath, testsConfig);
  } catch (error) {
    console.error(`Error running test suite: ${error.message}`, error.stack);
  }
})();
```

### Key Considerations:
1. **Mock Framework**: The `blueslip` mock framework is initialized and cleaned up before and after each test to prevent side effects.
2. **Timeout Management**: Each test has a 5-second timeout using promises with `setTimeout`.
3. **Logging & Reporting**: Logs are printed to the console, including timestamps for when tests run. Results are sent to an external logging service at the end.
4. **Selective Skipping**: Tests can be skipped based on environment variables (`SKIPTESTS`).
5. **Error Handling**: Comprehensive error handling ensures informative messages and stack traces for debugging.
6. **Memory Optimization**: Minimal variable scope, efficient data structures, and careful management of imports help optimize memory usage.
7. **Thread Safety Consideration**: While JavaScript (Node.js) is single-threaded per process, this code manages shared state carefully to avoid side effects in test execution.']

