const EventEmitter = require('events');
const fs = require('fs').promises;

class ServiceManager extends EventEmitter {
  constructor(config) {
    super();
    this.config = config;
    this.buffer = [];
    this.isPaused = false;
    this.isRunning = false;
    this.pauseNotificationInterval = null;
    this.stopTimer = null;
    this.concurrencyControl = new Set();

    // Initial setup
    this.setupListeners();
  }

  async start() {
    if (this.isRunning) return;

    this.isRunning = true;
    console.log('Service started.');

    while (this.isRunning) {
      const randomDelay = this.getRandomDelay(this.config.delayRange);
      await new Promise(resolve => setTimeout(resolve, randomDelay));

      try {
        await this.collectDataFromStream();
        await this.logBufferState();

        if (!this.isPaused) {
          await this.notifyMonitoringService();
        }

        this.stopService(randomDelay);
      } catch (error) {
        console.error('Error during service execution:', error);
      }
    }
  }

  async stop() {
    if (!this.isRunning) return;

    this.isRunning = false;
    console.log('Service stopping...');
    clearInterval(this.pauseNotificationInterval);

    await this.logBufferState();
    await this.notifyMonitoringService(true);

    console.log('Service stopped.');
  }

  pause() {
    if (this.isPaused) return;

    this.isPaused = true;
    console.log('Service paused.');

    this.pauseNotificationInterval = setInterval(() => {
      console.log(`Buffer state: ${JSON.stringify(this.buffer)}`);
    }, this.config.notifyInterval);

    clearInterval(this.stopTimer);
  }

  resume() {
    if (!this.isPaused) return;

    this.isPaused = false;
    console.log('Service resumed.');
    clearInterval(this.pauseNotificationInterval);

    // Restart the stop timer
    const randomDelay = this.getRandomDelay(this.config.delayRange);
    this.scheduleStop(randomDelay);
  }

  async collectDataFromStream() {
    if (this.concurrencyControl.size >= this.config.maxConcurrentOperations) {
      console.log('Max concurrent operations reached.');
      return;
    }

    this.concurrencyControl.add(Date.now());

    // Simulate data collection
    const newData = `data-${Date.now()}`;
    this.buffer.push(newData);

    if (this.isPaused) {
      await new Promise(resolve => setTimeout(resolve, 100));
    }

    this.concurrencyControl.delete(Date.now());
  }

  async logBufferState() {
    try {
      const bufferString = JSON.stringify(this.buffer);
      await fs.writeFile(this.config.storagePath, bufferString, { flag: 'w' });
    } catch (error) {
      console.error('Error logging buffer state:', error);
    }
  }

  async notifyMonitoringService(isStopping = false) {
    try {
      // Simulate notifying an external monitoring service
      const message = isStopping ? 'Service stopping...' : 'Service running';
      console.log(`Notification to monitoring service: ${message}`);
    } catch (error) {
      console.error('Error notifying monitoring service:', error);
    }
  }

  getRandomDelay(range) {
    const [min, max] = range;
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  scheduleStop(delay) {
    this.stopTimer = setTimeout(() => this.stop(), delay);
  }

  setupListeners() {
    this.on('pause', this.pause.bind(this));
    this.on('resume', this.resume.bind(this));
    this.on('stop', this.stop.bind(this));
  }
}

// Example configuration
const config = {
  delayRange: [1000, 5000],
  storagePath: './bufferState.json',
  notifyInterval: 2000,
  bufferMaxSize: 100,
  maxConcurrentOperations: 5,
};

const serviceManager = new ServiceManager(config);

serviceManager.start();

// For testing purposes
setTimeout(() => serviceManager.emit('pause'), 5000);
setTimeout(() => serviceManager.emit('resume'), 8000);
setTimeout(() => serviceManager.emit('stop'), 12000);
```"]

