async function mergeBuffers(buffers) {
    if (!Array.isArray(buffers) || buffers.some(buffer => !(buffer instanceof Uint8Array))) {
        throw new Error("Invalid input format: Expected an array of Uint8Arrays.");
    }

    // Fetch the maximum allowed buffer size from an external data source.
    const MAX_BUFFER_SIZE = await fetchMaxBufferSize();

    let totalSize = 0;
    for (const buffer of buffers) {
        if (!buffer || !Buffer.isBuffer(buffer)) {
            throw new Error("Invalid input format: All elements must be Uint8Arrays.");
        }
        totalSize += buffer.length;
    }

    // Ensure the final buffer size doesn't exceed the maximum allowed.
    if (totalSize > MAX_BUFFER_SIZE) {
        throw new RangeError(`Total buffer size exceeds maximum allowed limit of ${MAX_BUFFER_SIZE} bytes.`);
    }

    const resultBuffer = new Uint8Array(totalSize);
    let offset = 0;

    for (const buffer of buffers) {
        if (offset + buffer.length > totalSize) {
            throw new Error("Internal error: Buffer merge logic failed.");
        }
        resultBuffer.set(buffer, offset);
        offset += buffer.length;
    }

    return resultBuffer;
}

