import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class WordProcessor {

    private static final Logger logger = LogManager.getLogger(WordProcessor.class);

    public void processFile(String filePath, Set<String> stopWords) {
        HashMap<String, Integer> wordCountMap = new HashMap<>();
        long startTime = System.currentTimeMillis();

        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] words = line.toLowerCase().split("\\W+");

                for (String word : words) {
                    if (!stopWords.contains(word)) {
                        wordCountMap.put(word, wordCountMap.getOrDefault(word, 0) + 1);
                    }
                }
            }

            long endTime = System.currentTimeMillis();
            logger.info("Processing completed in {} milliseconds", endTime - startTime);

        } catch (IOException e) {
            logger.error("Error reading file: {}", e.getMessage());
        }

        Set<String> uniqueWordsAppearingTwice = new HashSet<>();

        for (String word : wordCountMap.keySet()) {
            if (wordCountMap.get(word) == 2) {
                uniqueWordsAppearingTwice.add(word);
            }
        }

        logger.info("Unique words appearing exactly twice: {}", uniqueWordsAppearingTwice.size());
    }

    public Set<String> fetchStopWordsFromDatabase() {
        Set<String> stopWords = new HashSet<>();
        // Simulate fetching stop words from a database
        // Implement retry logic and error handling for network latency or unavailability

        try {
            // Simulated delay to mimic data fetching
            Thread.sleep(100);

            // Add common stop words as an example
            stopWords.add("the");
            stopWords.add("is");
            stopWords.add("at");
            stopWords.add("of");

            logger.info("Fetched {} stop words from database", stopWords.size());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logger.error("Interrupted while fetching stop words: {}", e.getMessage());
        }

        return stopWords;
    }

    public static void main(String[] args) {
        WordProcessor processor = new WordProcessor();

        // Simulate concurrent access to the database for stop words
        Set<String> stopWords = processor.fetchStopWordsFromDatabase();

        String filePath = "path/to/large/textfile.txt";
        processor.processFile(filePath, stopWords);
    }
}
```

This code provides a solution that processes large text files efficiently and logs processing times. It includes handling for fetching common stop words from an external source with basic error management. The code is designed to be scalable and resilient, accommodating potential data source unavailability or network latency.']

['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.util.concurrent.*;
import java.util.*;
import java.util.logging.Logger;

public class HttpConnectionPoolService {

    private static final Logger logger = Logger.getLogger(HttpConnectionPoolService.class.getName());

    private final ExecutorService clientExecutor = Executors.newCachedThreadPool();
    private final BlockingQueue<HttpChannel> pool;
    private final int maxConnections;
    private final int connectionTimeoutMillis;
    private final ScheduledExecutorService monitorScheduler;

    public HttpConnectionPoolService(int initialSize, int maxConnections, int connectionTimeoutMillis) {
        this.maxConnections = maxConnections;
        this.connectionTimeoutMillis = connectionTimeoutMillis;
        this.pool = new LinkedBlockingQueue<>(maxConnections);
        this.monitorScheduler = Executors.newScheduledThreadPool(1);

        initializeConnectionPool(initialSize);
        startMonitoring();
    }

    private void initializeConnectionPool(int initialSize) {
        for (int i = 0; i < initialSize; i++) {
            createAndAddChannelToPool();
        }
    }

    private void createAndAddChannelToPool() {
        try {
            SocketChannel socketChannel = SocketChannel.open();
            HttpChannel channel = new HttpChannel(socketChannel);
            pool.offer(channel, connectionTimeoutMillis, TimeUnit.MILLISECONDS);
        } catch (IOException | InterruptedException e) {
            logger.warning("Failed to create a channel: " + e.getMessage());
        }
    }

    public HttpChannel acquireConnection() throws InterruptedException, ExecutionException {
        while (true) {
            HttpChannel channel = pool.poll();
            if (channel != null) {
                return channel;
            } else if (pool.size() < maxConnections) {
                createAndAddChannelToPool();
            } else {
                Future<HttpChannel> futureChannel = clientExecutor.submit(this::createAndAddChannelToPool);
                HttpChannel newChannel = futureChannel.get(connectionTimeoutMillis, TimeUnit.MILLISECONDS);
                return newChannel;
            }
        }
    }

    public void releaseConnection(HttpChannel channel) {
        pool.offer(channel);
    }

    private void startMonitoring() {
        monitorScheduler.scheduleAtFixedRate(this::monitorIdleConnections, 1, 5, TimeUnit.MINUTES);
    }

    private void monitorIdleConnections() {
        List<HttpChannel> idleChannels = new ArrayList<>();
        for (HttpChannel channel : pool) {
            if (channel.isIdle()) {
                idleChannels.add(channel);
            }
        }
        logger.info("Monitoring: Found " + idleChannels.size() + " idle connections.");
        cleanupIdleConnections(idleChannels);
    }

    private void cleanupIdleConnections(List<HttpChannel> idleChannels) {
        for (HttpChannel channel : idleChannels) {
            try {
                if (!channel.isInUse()) {
                    pool.remove(channel);
                    channel.close();
                    logger.info("Closed idle connection: " + channel);
                }
            } catch (IOException e) {
                logger.warning("Failed to close an idle connection: " + e.getMessage());
            }
        }
    }

    public void shutdown() throws InterruptedException {
        clientExecutor.shutdown();
        monitorScheduler.shutdown();

        for (HttpChannel channel : pool) {
            try {
                if (!channel.isClosed()) {
                    channel.close();
                }
            } catch (IOException e) {
                logger.warning("Failed to close connection during shutdown: " + e.getMessage());
            }
        }

        if (!clientExecutor.awaitTermination(60, TimeUnit.SECONDS)) {
            clientExecutor.shutdownNow();
        }

        if (!monitorScheduler.awaitTermination(60, TimeUnit.SECONDS)) {
            monitorScheduler.shutdownNow();
        }
    }

    private static class HttpChannel {
        private final SocketChannel socketChannel;
        private long lastUsedTime;

        public HttpChannel(SocketChannel socketChannel) throws IOException {
            this.socketChannel = socketChannel;
            this.lastUsedTime = System.currentTimeMillis();
        }

        public boolean isIdle() {
            return System.currentTimeMillis() - lastUsedTime > 60000; // 1 minute idle
        }

        public boolean isInUse() {
            return socketChannel.isOpen();
        }

        public void close() throws IOException {
            if (socketChannel != null) {
                socketChannel.close();
            }
        }

        public boolean isClosed() {
            return !socketChannel.isOpen();
        }

        public void updateLastUsedTime() {
            lastUsedTime = System.currentTimeMillis();
        }
    }
}
```

This code provides a basic implementation of an HTTP connection pool service using Java NIO Channels. It includes mechanisms for acquiring, releasing, and monitoring connections to manage resource utilization efficiently. The class also supports dynamic resizing based on demand, handles idle connection cleanup, and can integrate with external logging or monitoring tools as needed.']

