import os
import threading
from collections import OrderedDict
from PIL import Image
from datetime import datetime, timedelta

class ThemeCache:
    def __init__(self, config):
        self.cache = OrderedDict()
        self.default_theme_dir = config.get('default_theme_dir', './themes')
        self.max_file_size_kb = config.get('max_file_size_kb', 500)
        self.memory_limit_mb = config.get('memory_limit_mb', 100)
        self.eviction_interval_seconds = config.get('eviction_interval_seconds', 3600)
        self.lock = threading.Lock()

        # Start cache eviction thread
        threading.Thread(target=self._evict_cache_periodically, daemon=True).start()

    def _parse_theme_directory(self):
        for root, _, files in os.walk(self.default_theme_dir):
            for file_name in files:
                if file_name.endswith('.png'):
                    file_path = os.path.join(root, file_name)
                    self.add_to_cache(file_path)

    def add_to_cache(self, file_path):
        if not os.path.exists(file_path) or os.path.getsize(file_path) > self.max_file_size_kb * 1024:
            print(f"Warning: File {file_path} exceeds size limit and will be ignored.")
            return

        with Image.open(file_path) as img:
            bitmap = img.tobytes()

        with self.lock:
            if len(self.cache) >= self.memory_limit_mb * (1024 ** 2):
                self._evict_oldest_cache_entry()

            self.cache[file_path] = {
                'bitmap': bitmap,
                'last_accessed': datetime.now()
            }

    def get_bitmap(self, file_name):
        with self.lock:
            if file_name in self.cache:
                entry = self.cache.pop(file_name)
                entry['last_accessed'] = datetime.now()
                self.cache[file_name] = entry
                return entry['bitmap']

        # If not found, try to add it from the default directory
        potential_path = os.path.join(self.default_theme_dir, file_name)
        if os.path.exists(potential_path):
            self.add_to_cache(potential_path)
            return self.get_bitmap(file_name)

    def invalidate_theme(self, file_name):
        with self.lock:
            if file_name in self.cache:
                del self.cache[file_name]

    def _evict_oldest_cache_entry(self):
        oldest_file = min(self.cache.items(), key=lambda x: x[1]['last_accessed'])[0]
        print(f"Evicting {oldest_file} from cache.")
        with self.lock:
            del self.cache[oldest_file]

    def set_theme_directory(self, new_dir):
        self.default_theme_dir = new_dir
        self._parse_theme_directory()

    def _evict_cache_periodically(self):
        while True:
            time.sleep(self.eviction_interval_seconds)
            with self.lock:
                current_time = datetime.now()
                for file_name, entry in list(self.cache.items()):
                    if (current_time - entry['last_accessed']) > timedelta(seconds=self.eviction_interval_seconds):
                        print(f"Evicting {file_name} due to inactivity.")
                        del self.cache[file_name]

    def integrate_with_monitoring_service(self, monitoring_service):
        def on_theme_change(change_type, file_path):
            if change_type == 'modified' or change_type == 'created':
                self.add_to_cache(file_path)
            elif change_type == 'deleted':
                self.invalidate_theme(os.path.basename(file_path))

        monitoring_service.register_callback(on_theme_change)

# Example configuration
config = {
    'default_theme_dir': './themes',
    'max_file_size_kb': 500,
    'memory_limit_mb': 100,
    'eviction_interval_seconds': 3600
}

theme_cache = ThemeCache(config)
theme_cache._parse_theme_directory()

# Mock monitoring service integration
class MonitoringService:
    def register_callback(self, callback):
        # This should be implemented to notify the callback on file changes.
        pass

monitoring_service = MonitoringService()
theme_cache.integrate_with_monitoring_service(monitoring_service)

