class FileAndHashUtility {
    /**
     * Generates a random string of specified length using the given character set.
     *
     * @param int $length Length of the string to generate.
     * @param string $charset Character set from which to pick characters.
     * @return string Randomly generated string.
     */
    public static function generateRandomString($length, $charset) {
        if ($length <= 0 || empty($charset)) {
            throw new InvalidArgumentException("Invalid length or character set provided.");
        }

        // Using a widely accepted hashing library for performance and maintenance
        require 'vendor/autoload.php'; // Assuming Composer's autoloader

        try {
            $randomString = '';
            $maxIndex = strlen($charset) - 1;

            for ($i = 0; $i < $length; ++$i) {
                $randomString .= $charset[random_int(0, $maxIndex)];
            }

            // Example of hashing the random string
            $hasher = \password_hash($randomString, PASSWORD_DEFAULT);

            return $hasher;
        } catch (\Exception $e) {
            throw new RuntimeException("Error generating random string: " . $e->getMessage());
        }
    }
}

// Usage example:
// echo FileAndHashUtility::generateRandomString(10, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789');

