const fs = require('fs/promises');
const path = require('path');

class FileAndHashUtility {
    /**
     * Reads a file asynchronously from the specified path and returns its contents.
     *
     * @param {string} filePath Path to the file to read.
     * @returns {Promise<string>} Contents of the file as a string.
     */
    static async readFileContents(filePath) {
        try {
            if (!fs.accessSync(filePath, fs.constants.F_OK)) {
                throw new Error(`File not found: ${filePath}`);
            }

            const data = await fs.readFile(filePath, 'utf-8');
            return data;
        } catch (error) {
            console.error(`Error reading file at ${filePath}:`, error);
            throw new Error(`Failed to read file: ${error.message}`);
        }
    }
}

// Usage example:
