["```javascript
const https = require('https');
const fs = require('fs').promises;
const { exec } = require('child_process');

async function generatePEMCertificate(oauthRequest) {
  const storagePath = oauthRequest.storageLocation;

  try {
    let certificate, privateKey;

    if (await isRemoteLocation(storagePath)) {
      ({ certificate, privateKey } = await fetchFromRemote(storagePath));
    } else {
      ({ certificate, privateKey } = await readFromLocal(storagePath));
    }

    const pemCertificate = `-----BEGIN CERTIFICATE-----\n${bufferToPEM(certificate)}\n-----END CERTIFICATE-----`;
    const pemPrivateKey = `-----BEGIN PRIVATE KEY-----\n${bufferToPEM(privateKey)}\n-----END PRIVATE KEY-----`;

    log('INFO', 'PEM certificate and private key generated successfully.');

    return { pemCertificate, pemPrivateKey };
  } catch (error) {
    log('ERROR', `Error generating PEM certificate: ${error.message}`);
    throw new Error('Failed to generate PEM certificate');
  }
}

async function isRemoteLocation(path) {
  try {
    const parsedUrl = new URL(path);
    return ['http:', 'https:'].includes(parsedUrl.protocol);
  } catch {
    return false;
  }
}

function bufferToPEM(buffer, lineLength = 64) {
  let hex = buffer.toString('hex').match(/.{1,2}/g).join(' ');
  while (hex.length) {
    yield `${hex.slice(0, lineLength * 2)}\n`;
    hex = hex.slice(lineLength * 2);
  }
}

async function* fetchFromRemote(url) {
  const options = new URL(url);
  let remainingData = Buffer.alloc(0);

  return new Promise((resolve, reject) => {
    https.get(options, (res) => {
      if (res.statusCode !== 200) {
        return reject(new Error(`Failed to load remote resource: ${res.statusCode}`));
      }

      res.on('data', (chunk) => {
        remainingData = Buffer.concat([remainingData, chunk]);
        yield* streamBuffers(remainingData);
      });

      res.on('end', () => resolve({ certificate: remainingData.slice(0, remainingData.length / 2), privateKey: remainingData.slice(remainingData.length / 2) }));

      res.on('error', (err) => reject(err));
    });
  });
}

function* streamBuffers(buffer) {
  const certSplit = buffer.indexOf(b'-----BEGIN CERTIFICATE-----');
  const keyStart = certSplit + b'-----END CERTIFICATE-----'.length;

  if (certSplit > -1 && keyStart < buffer.length) {
    yield { certificate: buffer.slice(0, certSplit), privateKey: buffer.slice(keyStart) };
  }
}

async function readFromLocal(path) {
  const data = await fs.readFile(path);
  return parseCertificateData(data);
}

function parseCertificateData(buffer) {
  const [certPart, keyPart] = buffer.split(b'-----BEGIN PRIVATE KEY-----');
  return { certificate: certPart + b'-----END CERTIFICATE-----', privateKey: b'-----BEGIN PRIVATE KEY-----'.length + keyPart };
}

function log(level, message) {
  console.log(`[${level}] ${new Date().toISOString()}: ${message}`);
}
```"]

