### C Extension (DNS Resolution)

Create a `dns_resolver.c` file to handle DNS resolution and cache results:

```c
#include <php.h>
#include <ext/standard/php_string.h>
#include <ext/pcre/php_pcre.h>

#define CACHE_SIZE 100

typedef struct {
    char ip[16];
    char hostname[256];
} dns_cache_entry;

static zend_array *dns_cache;
static mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

PHP_FUNCTION(dns_resolve_hostname);

ZEND_BEGIN_ARG_INFO_EX(arginfo_dns_resolve_hostname, 0, 0, 1)
    ZEND_ARG_INFO(0, hostname)
ZEND_END_ARG_INFO()

const zend_function_entry dns_resolver_functions[] = {
    PHP_FE(dns_resolve_hostname, arginfo_dns_resolve_hostname)
    PHP_FE_END
};

zend_module_entry dns_resolver_module_entry = {
    STANDARD_MODULE_HEADER,
    "dns_resolver",
    dns_resolver_functions,
    NULL,
    NULL,
    NULL,
    NULL,
    NULL,
    NO_VERSION_YET,
    STANDARD_MODULE_PROPERTIES
};
ZEND_GET_MODULE(dns_resolver)

PHP_FUNCTION(dns_resolve_hostname) {
    char *hostname;
    size_t hostname_len;

    if (zend_parse_parameters(ZEND_NUM_ARGS(), "s", &hostname, &hostname_len) == FAILURE) {
        RETURN_FALSE;
    }

    pthread_mutex_lock(&cache_mutex);

    // Check cache first
    for (int i = 0; i < zend_array_count(dns_cache); ++i) {
        dns_cache_entry *entry = (dns_cache_entry *)zend_array_index_fetch(dns_cache, i, NULL);
        if (strcmp(entry->hostname, hostname) == 0) {
            RETURN_STRING(entry->ip);
        }
    }

    // Perform DNS resolution
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;

    if (getaddrinfo(hostname, NULL, &hints, &res) == 0) {
        struct sockaddr_in *sock_addr = (struct sockaddr_in *)res->ai_addr;
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &(sock_addr->sin_addr), ip, INET_ADDRSTRLEN);

        // Cache result
        dns_cache_entry entry;
        strncpy(entry.hostname, hostname, sizeof(entry.hostname) - 1);
        strncpy(entry.ip, ip, sizeof(entry.ip) - 1);

        add_assoc_stringl(dns_cache, (char *)ip, sizeof(ip), entry.ip, sizeof(entry.ip));
    }

    pthread_mutex_unlock(&cache_mutex);
    RETURN_STRING("0.0.0.0"); // Default return in case of failure
}
```

