<?php

class PasswordUpdateService {
    private $authProvider;
    private $notificationService;
    private $databaseConnection;
    private const MAX_ATTEMPTS = 5; // Max login attempts before lockout

    public function __construct($authProvider, $notificationService, $databaseConnection) {
        $this->authProvider = $authProvider;
        $this->notificationService = $notificationService;
        $this->databaseConnection = $databaseConnection;
    }

    public function updatePassword($userId, $newPassword) {
        try {
            // Start transaction
            $this->databaseConnection->beginTransaction();

            if (!$this->validatePasswordStrength($newPassword)) {
                throw new Exception("Password does not meet strength requirements.");
            }

            if ($this->isPasswordUnique($userId, $newPassword)) {
                throw new Exception("Password is already used by another account.");
            }

            if (!$this->checkAttemptLimit($userId)) {
                throw new Exception("Too many password change attempts. Please try again later.");
            }

            // Update the password
            $encryptedPassword = $this->authProvider->encryptPassword($newPassword);
            $this->databaseConnection->executeStatement("UPDATE users SET password = ? WHERE id = ?", [$encryptedPassword, $userId]);

            // Increment attempt counter or reset if successful
            $this->resetAttemptCounter($userId);

            // Notify user of the change
            $this->notificationService->sendUpdateNotification($userId);

            // Commit transaction
            $this->databaseConnection->commit();

            $this->logPasswordChange($userId, true);
        } catch (Exception $e) {
            // Rollback transaction on error
            $this->databaseConnection->rollBack();

            $this->incrementAttemptCounter($userId);
            $this->logPasswordChange($userId, false, $e->getMessage());

            return [
                'status' => 'error',
                'message' => $e->getMessage()
            ];
        }

        return [
            'status' => 'success',
            'message' => 'Password updated successfully.'
        ];
    }

    private function validatePasswordStrength($password) {
        // Implement password strength validation logic
        return preg_match('/[A-Za-z]/', $password) && strlen($password) >= 8;
    }

    private function isPasswordUnique($userId, $newPassword) {
        // Check for uniqueness across services or database tables
        return !$this->databaseConnection->fetchOne("SELECT id FROM users WHERE password = ?", [$newPassword]);
    }

    private function checkAttemptLimit($userId) {
        // Fetch attempt count and compare with MAX_ATTEMPTS
        $attempts = $this->databaseConnection->fetchOne("SELECT attempts FROM login_attempts WHERE user_id = ? LIMIT 1", [$userId]);
        return $attempts < self::MAX_ATTEMPTS;
    }

    private function incrementAttemptCounter($userId) {
        // Increment the attempt counter in the database
        $stmt = $this->databaseConnection->prepare("INSERT INTO login_attempts (user_id, attempts) VALUES (?, 1)
            ON DUPLICATE KEY UPDATE attempts = attempts + 1");
        $stmt->execute([$userId]);
    }

    private function resetAttemptCounter($userId) {
        // Reset attempt counter after successful password change
        $this->databaseConnection->executeStatement("UPDATE login_attempts SET attempts = 0 WHERE user_id = ?", [$userId]);
    }

    private function logPasswordChange($userId, $success, $errorMessage = null) {
        // Log the attempt with timestamp and result
        $logMessage = $success ? "Successful password change." : "Failed password change: {$errorMessage}";
        error_log("User ID {$userId}: {$logMessage}");
    }
}
