#include <iostream>
#include <vector>
#include <unordered_map>
#include <fstream>
#include <string>

class OctreeNode {
public:
    std::vector<std::unique_ptr<OctreeNode>> children;
    std::vector<float> points;
    float center[3];
    float halfSize;

    OctreeNode(const float* c, float hs) : halfSize(hs) {
        for (int i = 0; i < 3; ++i) center[i] = c[i];
        children.resize(8, nullptr);
    }

    ~OctreeNode() {}
};

class DiskBackedStorage {
private:
    std::unordered_map<int, std::string> nodeToFile;
    int nextFileId;

public:
    DiskBackedStorage() : nextFileId(0) {}

    void saveNode(const OctreeNode& node, const std::string& filename) {
        std::ofstream ofs(filename);
        if (!ofs.is_open()) throw std::runtime_error("Could not open file for writing");

        ofs.write(reinterpret_cast<const char*>(&node.halfSize), sizeof(float));
        for (int i = 0; i < 3; ++i)
            ofs.write(reinterpret_cast<const char*>(node.center + i), sizeof(float));

        int numPoints = node.points.size() / 3;
        ofs.write(reinterpret_cast<const char*>(&numPoints), sizeof(int));

        for (const auto& p : node.points) {
            ofs.write(reinterpret_cast<const char*>(&p), sizeof(float));
        }

        for (int i = 0; i < 8; ++i) {
            if (node.children[i]) {
                int fileId;
                if (nodeToFile.count(i)) {
                    fileId = nodeToFile.at(i);
                } else {
                    std::string newFilename = "node_" + std::to_string(nextFileId++) + ".dat";
                    saveNode(*node.children[i], newFilename);
                    fileId = nextFileId - 1;
                    nodeToFile[i] = newFilename;
                }
                ofs.write(reinterpret_cast<const char*>(&fileId), sizeof(int));
            } else {
                ofs.write(reinterpret_cast<const char*>(&(-1)), sizeof(int)); // Marker for null child
            }
        }

        ofs.close();
    }

    OctreeNode loadNode(const std::string& filename) {
        std::ifstream ifs(filename);
        if (!ifs.is_open()) throw std::runtime_error("Could not open file for reading");

        float halfSize;
        ifs.read(reinterpret_cast<char*>(&halfSize), sizeof(float));

        float center[3];
        for (int i = 0; i < 3; ++i)
            ifs.read(reinterpret_cast<char*>(center + i), sizeof(float));

        OctreeNode node(center, halfSize);

        int numPoints;
        ifs.read(reinterpret_cast<char*>(&numPoints), sizeof(int));
        for (int i = 0; i < numPoints * 3; ++i) {
            float p;
            ifs.read(reinterpret_cast<char*>(&p), sizeof(float));
            node.points.push_back(p);
        }

        for (int i = 0; i < 8; ++i) {
            int fileId;
            ifs.read(reinterpret_cast<char*>(&fileId), sizeof(int));
            if (fileId != -1) {
                std::string childFilename = "node_" + std::to_string(fileId) + ".dat";
                node.children[i] = std::make_unique<OctreeNode>(loadNode(childFilename));
            }
        }

        ifs.close();
        return node;
    }
};

class Octree {
private:
    OctreeNode* root;
    float bounds[3];
    float initialSize;
    int maxPointsPerNode;

    bool insertPointRecursive(OctreeNode*& node, const float* point);
    void subdivideNode(OctreeNode*& node);

public:
    Octree(float minX, float minY, float minZ, float size, int maxPoints)
        : bounds{minX, minY, minZ}, initialSize(size), maxPointsPerNode(maxPoints) {
        root = new OctreeNode(bounds, initialSize);
    }

    ~Octree() { delete root; }

    void insertPoint(const float* point) {
        if (!insertPointRecursive(root, point)) {
            // Handle spillover or disk storage
        }
    }

    bool queryRange(const float* minBound, const float* maxBound, std::vector<float>& results);
};

bool Octree::insertPointRecursive(OctreeNode*& node, const float* point) {
    if (!node) return false;

    if (std::distance(node->points.begin(), node->points.end()) < maxPointsPerNode) {
        // Insert point directly
        node->points.insert(node->points.end(), point, point + 3);
        return true;
    }

    if (node->children[0] == nullptr) subdivideNode(node);

    int index = 0;
    for (int i = 0; i < 3; ++i) {
        if (point[i] > node->center[i]) index |= 1 << i;
    }

    return insertPointRecursive(node->children[index], point);
}

void Octree::subdivideNode(OctreeNode*& node) {
    float newSize = node->halfSize / 2.0f;

    for (int i = 0; i < 8; ++i) {
        float newCenter[3];
        for (int j = 0; j < 3; ++j)
            newCenter[j] = node->center[j] + ((i & (1 << j)) ? newSize : -newSize);

        node->children[i] = std::make_unique<OctreeNode>(newCenter, newSize);
    }
}

bool Octree::queryRange(const float* minBound, const float* maxBound, std::vector<float>& results) {
    // Implement range query logic
    return true;
}
```

This code provides a basic framework for an octree with disk-based storage support. It includes methods for inserting points and querying spatial ranges, with considerations for handling large datasets that exceed memory capacity by leveraging disk storage. The `DiskBackedStorage` class manages saving and loading nodes to/from disk files.']

