```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_MEMORY_PACKETS 2000
#define PACKET_SIZE 1024

typedef struct {
    int id;
    char data[PACKET_SIZE];
    bool isCritical;
    unsigned long timestamp;
} Packet;

typedef struct Node {
    Packet packet;
    struct Node* next;
} Node;

Node* priorityQueue = NULL;

void processExternalDataFeed(Packet** packets, size_t* count) {
    // Simulate external data feed
    for (size_t i = 0; i < *count; ++i) {
        if (packets[i]->isCritical) {
            packets[i]->timestamp = time(NULL);  // Update timestamp for critical packets
        }
    }
}

void enqueue(Packet packet) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;

    newNode->packet = packet;
    newNode->next = priorityQueue;

    Node** current = &priorityQueue;
    while (*current && ((*current)->packet.timestamp < packet.timestamp || 
                       (*current)->packet.isCritical == packet.isCritical &&
                       !(*current)->packet.isCritical)) {
        current = &((*current)->next);
    }

    newNode->next = *current;
    *current = newNode;
}

Packet dequeue() {
    if (!priorityQueue) return (Packet){0};

    Node* tempNode = priorityQueue;
    Packet packet = tempNode->packet;

    priorityQueue = priorityQueue->next;
    free(tempNode);

    return packet;
}

void processPackets(Packet** packets, size_t count) {
    unsigned long totalProcessingTime = 0;
    int criticalCount = 0;
    int maxPayloadSize = 0;
    int packetWithMaxPayloadId = -1;

    for (size_t i = 0; i < count; ++i) {
        Packet* packet = &packets[i];

        if (!packet->isCritical && priorityQueue != NULL && 
            ((Packet*)priorityQueue)->timestamp > packet->timestamp) {
            continue;
        }

        enqueue(*packet);
    }

    while (priorityQueue && maxPayloadSize < MAX_MEMORY_PACKETS) {
        Packet packet = dequeue();
        time_t startTime = clock();

        // Simulate processing
        if (packet.isCritical) criticalCount++;

        // Calculate payload size and check for maximum
        int currentPayloadSize = strlen(packet.data);
        if (currentPayloadSize > maxPayloadSize) {
            maxPayloadSize = currentPayloadSize;
            packetWithMaxPayloadId = packet.id;
        }

        time_t endTime = clock();
        totalProcessingTime += endTime - startTime;
    }

    double avgProcessingTime = priorityQueue ? (double)totalProcessingTime / count : 0.0;

    printf("Max Payload Size: %d, Packet ID: %d\n", maxPayloadSize, packetWithMaxPayloadId);
    printf("Critical Packets Handled: %d\n", criticalCount);
    printf("Average Processing Time per Packet: %.2f ms\n", avgProcessingTime / (double)CLOCKS_PER_SEC * 1000.0);
}

int main() {
    size_t totalPackets = 10000;
    Packet* packets = (Packet*)malloc(totalPackets * sizeof(Packet));

    // Simulate packet generation
    for (size_t i = 0; i < totalPackets; ++i) {
        packets[i].id = i;
        snprintf(packets[i].data, PACKET_SIZE, "Data %zu", i);
        packets[i].isCritical = (i % 100 == 0);  // Mark every 100th packet as critical
    }

    processExternalDataFeed(packets, &totalPackets);

    processPackets(packets, totalPackets);

    free(packets);
    return 0;
}
```

### Key Points:
- **Priority Queue:** Uses a linked list to prioritize packets based on timestamp and critical flag.
- **Critical Handling:** Critical packets are prioritized over non-critical ones.
- **Packet Statistics:** Tracks maximum payload size, packet ID, number of critical packets, and average processing time.
- **Scalability:** Designed to allow horizontal scaling by adding more nodes without modifying the core logic.']

