#include <iostream>
#include <chrono>
#include <mutex>
#include <thread>

class AttackSelector {
public:
    AttackSelector() : last_used_times({0, 0, 0, 0}) {}

    void selectAttack() {
        static std::once_flag flag;

        // Initialize cooldown durations in seconds
        const int cooldowns[] = {9, 12, 6, 15};
        constexpr size_t num_attacks = sizeof(cooldowns) / sizeof(cooldowns[0]);

        std::call_once(flag, [this] {
            for (auto& t : last_used_times) {
                t = std::chrono::steady_clock::now();
            }
        });

        // Ensure thread-safety using a mutex
        static std::mutex mtx;

        std::lock_guard<std::mutex> lock(mtx);

        auto current_time = std::chrono::steady_clock::now();
        for (size_t i = 0; i < num_attacks; ++i) {
            if (canUseAttack(i, current_time)) {
                useAttack(i);
                return;
            }
        }

        // If no attacks can be used yet
        std::cout << "No attack available at this moment.\n";
    }

private:
    struct TimePoint {
        std::chrono::steady_clock::time_point last_used;
    };

    TimePoint last_used_times[4];

    bool canUseAttack(size_t attack_index, const std::chrono::steady_clock::time_point& current_time) {
        int cooldown = 9 + (attack_index * 3); // Cooldown durations: [9, 12, 6, 15]

        auto duration_since_last_use = std::chrono::duration_cast<std::chrono::seconds>(current_time - last_used_times[attack_index].last_used).count();

        return duration_since_last_use >= cooldown;
    }

    void useAttack(size_t attack_index) {
        last_used_times[attack_index].last_used = std::chrono::steady_clock::now();

        // Print the selected attack
        std::cout << "Using Attack: " << (attack_index + 1) << "\n";
    }
};

int main() {
    AttackSelector selector;

    // Simulating concurrent attacks
    std::vector<std::thread> threads;
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back([&selector]() {
            while(true) {
                selector.selectAttack();
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        });
    }

    for (auto& t : threads) {
        t.join();
    }

    return 0;
}
```

This code defines a `AttackSelector` class that manages attack cooldowns and selection in a thread-safe manner. It uses a mutex to protect shared state, allowing concurrent access from multiple threads without interference. The cooldown logic ensures each attack can only be used after its specific cooldown period has elapsed since the last use.']

['```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class DynamicRandom
{
    private double _min, _max;
    private readonly object _lock = new object();

    public DynamicRandom(double min, double max)
    {
        SetRange(min, max);
    }

    public void SetRange(double min, double max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        lock (_lock)
        {
            _min = min;
            _max = max;
        }
    }

    private Random _random = new Random();

    public double NextDouble()
    {
        lock (_lock)
        {
            return _random.NextDouble() * (_max - _min) + _min;
        }
    }

    public int NextInt(int inclusiveBound)
    {
        lock (_lock)
        {
            if (inclusiveBound < 0 || inclusiveBound > (int)(_max - _min))
                throw new ArgumentOutOfRangeException(nameof(inclusiveBound), "Bound is out of the range defined by min and max.");

            return (int)(NextDouble() * inclusiveBound);
        }
    }

    public double NextNormal(double mean = 0.0, double stddev = 1.0)
    {
        lock (_lock)
        {
            // Box-Muller transform to generate normally distributed numbers
            var u1 = _random.NextDouble();
            var u2 = _random.NextDouble();

            return Math.Sqrt(-2.0 * Math.Log(u1)) *
                   Math.Cos(2.0 * Math.PI * u2) * stddev + mean;
        }
    }

    public IEnumerable<double> Sample(int count, bool allowDuplicates)
    {
        lock (_lock)
        {
            if (count <= 0) yield break;

            var result = new HashSet<double>();
            while (result.Count < count || allowDuplicates)
            {
                var sample = NextDouble();
                if (allowDuplicates || !result.Contains(sample))
                {
                    result.Add(sample);
                    yield return sample;
                }
            }
        }
    }

    public override string ToString()
    {
        lock (_lock)
        {
            return $"Range: [{_min}, {_max}]";
        }
    }
}
```

This `DynamicRandom` class is designed to provide a robust, thread-safe solution for generating random numbers with customizable ranges. It supports floating-point and integer generation, allows dynamic range updates, provides normal distribution sampling using the Box-Muller transform, ensures no memory overload during sampling through efficient use of `HashSet`, and handles concurrent access safely with locks.']

