async function customReduce(array, initialValue, callback, logFunction) {
  if (typeof array !== 'object' || !Array.isArray(array)) {
    return Promise.reject(new TypeError('Input must be an array'));
  }
  if (typeof callback !== 'function') {
    return Promise.reject(new TypeError('Callback must be a function'));
  }

  let accumulator = initialValue;
  const logIntermediateState = async (acc, index) => {
    try {
      await logFunction(acc, index);
    } catch (error) {
      console.error(`Logging error at index ${index}:`, error);
    }
  };

  for (let i = 0; i < array.length; i++) {
    try {
      accumulator = await callback(accumulator, array[i]);
      await logIntermediateState(accumulator, i + 1); // Log intermediate state after each step
    } catch (error) {
      console.error(`Error processing element at index ${i}:`, error);
      return Promise.reject(error);
    }
  }

  return accumulator;
}

// Example usage:

async function mockLogFunction(acc, index) {
  await new Promise(resolve => setTimeout(() => resolve(), 100)); // Simulate delay
  console.log(`Intermediate result at step ${index}: ${acc}`);
}

const callback = async (accumulator, currentValue) => {
  if (!Number.isFinite(currentValue)) throw new Error('Invalid number in array');
  return accumulator + currentValue;
};

(async () => {
  try {
    const result = await customReduce([1, -2, 3, -4], 0, callback, mockLogFunction);
    console.log(`Final result: ${result}`);
  } catch (error) {
    console.error('Reduction failed:', error);
  }
})();
