        config_cache = section;
    } else {
        Section *current = config_cache;
        while (current->next) current = current->next;
        current->next = section;
    }
    return true;
}

void freeConfig(Section *sec) {
    KeyValue *kv, *tmp;
    for (; sec; sec = sec->next) {
        kv = sec->settings;
        while (kv) {
            tmp = kv;
            kv = kv->next;
            free(tmp->key);
            free(tmp->value);
            free(tmp);
        }
