void fetch_theme_dir() {
    // Simulated fetching from external service
    char *theme_dir = getenv("THEME_DIR");
    if (theme_dir) {
        config.theme_dir = strdup(theme_dir);
    } else {
        config.theme_dir = DEFAULT_THEME_DIR;
    }
