float compute_average(const char *line, size_t start_idx) {
    float num1, num2;
    sscanf(line + start_idx, "%f,%f", &num1, &num2);
    return (num1 + num2) / 2.0;
}

void process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        // Find the last two numeric fields
        const char *p = line + strlen(line);
        float avg = 0.0f;

        if (strchr(p, ',') || strchr(p, '\n')) {
            p = strrchr(line, ',');
            if (!p) p = line;
            else p++;

            size_t next_comma = strcspn(p, ",\n");
            if (next_comma > 0 && sscanf(p + next_comma, "%f", &avg) == 1) {
                // Found one number
                next_comma += strcspn(p + next_comma, ",\n") + 1;
                float second_num = 0.0f;

                if (sscanf(p + next_comma, "%f", &second_num) == 1) {
                    avg = compute_average(line, strlen(line) - strlen(p) + next_comma);
                }
            }
        }

        printf("%s%.2f\n", line, avg); // Output with the average
    }

    free(line);
    fclose(file);
}

void *thread_function(void *arg) {
    const char *filename = (const char *)arg;
    process_file(filename);
    return NULL;
}

BitmapCache* get_bitmap_from_cache() {
    pthread_mutex_lock(&bitmaps.lock);

    for (size_t i = 0; i < bitmaps.cache_size; ++i) {
        if (!bitmaps.bitmap_cache[i]) {
            // Simulate bitmap loading
            char *bitmap = malloc(1024); // Placeholder size
            strcpy(bitmap, "BitmapData");
            bitmaps.bitmap_cache[i] = bitmap;
            pthread_mutex_unlock(&bitmaps.lock);
            return &bitmaps;
        }
    }

    pthread_mutex_unlock(&bitmaps.lock);
    return NULL; // No available slot
}

void recycle_bitmaps() {
    pthread_mutex_lock(&bitmaps.lock);

    for (size_t i = 0; i < bitmaps.cache_size; ++i) {
        if (bitmaps.bitmap_cache[i]) {
            free(bitmaps.bitmap_cache[i]);
            bitmaps.bitmap_cache[i] = NULL;
        }
    }

    pthread_mutex_unlock(&bitmaps.lock);
}

int main(int argc, char *argv[]) {
    fetch_theme_dir();
    printf("Theme directory: %s\n", config.theme_dir);

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    pthread_t threads[MAX_THREADS];
    size_t thread_count = 0;

    for (int i = 1; i < argc; ++i) {
        if (thread_count >= MAX_THREADS) break;
        pthread_create(&threads[thread_count++], NULL, thread_function, argv[i]);
    }

    for (size_t i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Manage bitmaps
    BitmapCache *cache = get_bitmap_from_cache();
    if (cache) {
        recycle_bitmaps();
    }

    return EXIT_SUCCESS;
}
