```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <tiffio.h>
#include <openssl/md5.h>

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int num_extra_samples;
    char md5_hash[MD5_DIGEST_LENGTH * 2 + 1];
} TIFFInfo;

TIFFInfo* parse_tiff_image(const char *filename) {
    TIFF *tiff = TIFFOpen(filename, "r");
    if (!tiff) {
        fprintf(stderr, "Error opening TIFF file: %s\n", filename);
        return NULL;
    }

    uint32 imageWidth, imageLength;
    uint16 samplesPerPixel, bitsPerSample[4], sampleFormat[4];
    uint32 photometricInterpretation, extraSamples;

    if (TIFFGetField(tiff, TIFFTAG_IMAGEWIDTH, &imageWidth) &&
        TIFFGetField(tiff, TIFFTAG_IMAGELENGTH, &imageLength) &&
        TIFFGetField(tiff, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel) &&
        TIFFGetField(tiff, TIFFTAG_BITSPERSAMPLE, bitsPerSample, 4) &&
        TIFFGetField(tiff, TIFFTAG_SAMPLEFORMAT, sampleFormat, 4) &&
        TIFFGetField(tiff, TIFFTAG_PHOTOMETRIC, &photometricInterpretation) &&
        TIFFGetField(tiff, TIFFTAG_EXTRASAMPLES, &extraSamples)) {

        // Validate the number of bits per sample
        int validBits = 0;
        for (int i = 0; i < samplesPerPixel; ++i) {
            if (bitsPerSample[i] == 1 || bitsPerSample[i] == 2 ||
                bitsPerSample[i] == 4 || bitsPerSample[i] == 8 ||
                bitsPerSample[i] == 16) {
                validBits++;
            }
        }

        // Validate samples per pixel
        if (samplesPerPixel < 1 || samplesPerPixel > 4) {
            fprintf(stderr, "Invalid samples per pixel: %u\n", samplesPerPixel);
            TIFFClose(tiff);
            return NULL;
        }

        if (validBits != samplesPerPixel) {
            fprintf(stderr, "Mismatch in valid bits per sample and samples per pixel.\n");
            TIFFClose(tiff);
            return NULL;
        }

        // Allocate memory for storing the image data
        uint32 rowstride;
        tsize_t imagelength = TIFFScanlineSize(tiff);
        uint8* buffer = (uint8*) _TIFFmalloc(imagelength * imageLength);

        if (!buffer) {
            fprintf(stderr, "Memory allocation error.\n");
            TIFFClose(tiff);
            return NULL;
        }

        // Read the image data
        for (uint32 row = 0; row < imageLength; ++row) {
            if (TIFFReadScanline(tiff, buffer + row * imagelength, row, 0)) {
                // Process scanline if needed
            } else {
                fprintf(stderr, "Error reading scanline %u.\n", row);
                free(buffer);
                TIFFClose(tiff);
                return NULL;
            }
        }

        // Calculate MD5 hash of the image data
        unsigned char md5_hash[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)buffer, imagelength * imageLength, md5_hash);

        // Convert binary MD5 to hexadecimal string
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            sprintf(&TIFFInfo.md5_hash[i*2], "%02x", md5_hash[i]);
        }
        TIFFInfo.md5_hash[MD5_DIGEST_LENGTH * 2] = '\0';

        // Free allocated buffer
        free(buffer);

    } else {
        fprintf(stderr, "Failed to read essential TIFF tags.\n");
        TIFFClose(tiff);
        return NULL;
    }

    TIFFClose(tiff);

    // Allocate and fill the result struct
    TIFFInfo* info = (TIFFInfo*)malloc(sizeof(TIFFInfo));
    if (!info) {
        fprintf(stderr, "Memory allocation error for result struct.\n");
        return NULL;
    }

    info->bits_per_sample = bitsPerSample[0];
    info->samples_per_pixel = samplesPerPixel;
    info->num_extra_samples = extraSamples;

    // Validate the calculated MD5 hash (pseudo-code, replace with actual check if needed)
    char predefined_md5_hash[] = "predefined_md5_string_here";
    if (strncmp(info->md5_hash, predefined_md5_hash, MD5_DIGEST_LENGTH * 2) != 0) {
        fprintf(stderr, "MD5 hash mismatch indicating potential data corruption.\n");
        free(info);
        return NULL;
    }

    return info;
}
```

This code uses the `libtiff` library to parse TIFF files and OpenSSL's `md5()` function to calculate MD5 hashes. It includes error handling for opening the file, reading tags, and memory allocation failures. Additionally, it validates bits per sample, samples per pixel, and checks for potential data corruption via an MD5 hash comparison. Remember to link against both `libtiff` and OpenSSL when compiling this code (`-ltiff -lssl -lcrypto`).']

