    time_t last_modified;
} FileAttributes;

FileAttributes get_file_attributes(const char *filename) {
    // Simulate a call to an external metadata service
    FileAttributes attrs = { .size = 12345, .last_modified = time(NULL) };
    return attrs; // In reality, handle errors and incomplete data here
