int count_vowels(const char *str) {
    int vowels = 0;
    while (*str) {
        if (strchr("aeiouAEIOU", *str)) {
            ++vowels;
        }
        ++str;
    }
    return vowels;
}

void modify_filename(char *original, char *new) {
    if (!original || !*original) {
        fprintf(stderr, "Error: Invalid input filename.\n");
        return;
    }

    // Validate to prevent path traversal
    if (strncmp(original, "..", 2) == 0 || original[0] == '.') {
        fprintf(stderr, "Error: Invalid filename due to path traversal attempt.\n");
        return;
    }

    char *dot = strrchr(original, '.');
    const char *file_type = dot && isalnum(dot[-1]) ? dot : ".txt";

    int vowels = count_vowels(original);
    int num_digits = vowels > 0 ? vowels : 1;

    // Truncate filename if too long
    size_t original_len = strlen(original);
    if (original_len > 100) {
        fprintf(stderr, "Warning: Filename truncated due to length.\n");
        original[99] = '\0';
    }

    FileAttributes attrs = get_file_attributes(original);

    // Construct the timestamp
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "_%Y%m%d_%H%M%S", tstruct);

    // Prepare new filename components
    char sequence[MAX_FILENAME_LENGTH - original_len - strlen(file_type) - strlen(timestamp) - 2];
    snprintf(sequence, sizeof(sequence), "%0*d", num_digits, rand());

    // Construct the final filename
    snprintf(new, MAX_FILENAME_LENGTH, "%.*s_%zu%s%s%s",
             (int)(original_len > 100 ? 99 : original_len),
             original,
             attrs.size,
             timestamp,
             sequence,
             file_type);
}

int main() {
    char new_filename[MAX_FILENAME_LENGTH];
    modify_filename("examplefile.txt", new_filename);

    if (*new_filename) {
        printf("Modified filename: %s\n", new_filename);
    }

    return 0;
}
```

