    int enable_camellia;
    int enable_md5;
    int enable_sha1;
    int enable_rsa_sha1;
} Config;

Config config = {1, 1, 1, 1, 1}; // Default configuration

// Logging function
void log_operation(const char *message) {
    FILE *log_file = fopen("crypto_operations.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

// Function to load a dynamic module
void* load_module(const char *module_path) {
    void *handle = dlopen(module_path, RTLD_LAZY);
    if (!handle) {
        log_operation("Failed to load module: " + std::string(dlerror()));
        return NULL;
    }
    return handle;
}

// Function to dynamically add ciphers and digests
void dynamic_add_cryptos(const char *module_dir) {
    DIR *dir = opendir(module_dir);
    struct dirent *entry;

    if (!dir) {
        log_operation("Failed to open module directory.");
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strstr(entry->d_name, ".so") || strstr(entry->d_name, ".dylib")) {
            void *handle = load_module(entry->d_name);
            if (!handle) continue;

            // Assuming the module has a function to register itself
            typedef int (*register_func)(void);
            register_func reg = (register_func)dlsym(handle, "register_crypto");

            if (reg && reg() != 1) {
                log_operation("Failed to register crypto from module: " + std::string(entry->d_name));
            }
        }
    }

    closedir(dir);
}

// Function to initialize cryptographic library
int init_crypto_lib(const char *config_file_path, const char *module_dir) {
    // Load configuration (simplified)
    FILE *file = fopen(config_file_path, "r");
    if (!file) {
        log_operation("Failed to open config file.");
        return 0;
    }
    fscanf(file, "%d %d %d %d %d", &config.enable_aes, &config.enable_camellia,
           &config.enable_md5, &config.enable_sha1, &config.enable_rsa_sha1);
    fclose(file);

    // Add AES and Camellia ciphers
    if (config.enable_aes) {
        EVP_add_cipher(EVP_aes_128_cbc());
        log_operation("Added AES cipher.");
    }
    if (config.enable_camellia) {
        EVP_add_cipher(EVP_camellia_128_cbc());
        log_operation("Added Camellia cipher.");
    }

    // Add MD5 and SHA1 digests
    if (config.enable_md5) {
        EVP_add_digest(EVP_MD_mdc2());
        EVP_add_digest_alias(EVP_sha(), "sha1");
        log_operation("Added MD5 digest.");
    }
    if (config.enable_sha1) {
        EVP_add_digest(EVP_sha1());
        log_operation("Added SHA1 digest.");
    }

    // Add RSA with SHA1 for digital signatures
    if (config.enable_rsa_sha1) {
        OpenSSL_add_all_algorithms();
        log_operation("Enabled RSA with SHA1.");
    }

    // Dynamically load additional modules
    dynamic_add_cryptos(module_dir);

    return 1;
}

// Thread-safe wrapper around cryptographic operations
void perform_crypto_operations() {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&mutex);
    // Perform cryptographic operation (placeholder)
    log_operation("Performing cryptographic operation.");
    pthread_mutex_unlock(&mutex);
}

// Unit tests for cryptographic functions
void run_tests() {
    printf("Running unit tests...\n");
    perform_crypto_operations();
    printf("Tests completed.\n");

    // Additional test cases would be implemented here.
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <config_file> <module_dir>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (!init_crypto_lib(argv[1], argv[2])) {
        log_operation("Failed to initialize crypto library.");
        return EXIT_FAILURE;
    }

    run_tests();

    // Simulate cryptographic operations
    perform_crypto_operations();

    return EXIT_SUCCESS;
}
