#define MAX_COMMANDS 10
#define RESOURCE_LIMIT 80 // Example resource limit percentage

struct Command {
    char **args;
    uid_t uid;
    gid_t gid;
    int shouldRun; // flag to manage dependencies
};

void handle_sigchld(int sig) {
    while (waitpid((pid_t)(-1), 0, WNOHANG) > 0);
}

int checkResourceUsage() {
    // Dummy function: Implement actual resource monitoring logic here
    return rand() % 100; // Simulate a random resource usage percentage
}

void executeCommand(struct Command *cmd, int cmdIndex, struct Command commands[], int numCommands) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    if (pid > 0) { // Parent process
        return; // Parent will continue to the next command or manage dependencies
    } else { // Child process
        setgid(cmd->gid); 
        setuid(cmd->uid);

        struct rlimit rl;
        getrlimit(RLIMIT_AS, &rl);

        if (checkResourceUsage() > RESOURCE_LIMIT) {
            printf("Resource limit exceeded for command %d\n", cmdIndex + 1);
            exit(EXIT_FAILURE);
        }

        execvp(cmd->args[0], cmd->args);
        perror("execvp");
        exit(EXIT_FAILURE);
    }
}

void runCommands(struct Command commands[], int numCommands) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = &handle_sigchld;
    sigaction(SIGCHLD, &sa, NULL);

    for (int i = 0; i < numCommands; ++i) {
        if (commands[i].shouldRun) {
            executeCommand(&commands[i], i, commands, numCommands);

            // Example dependency management
            if (i + 1 < numCommands && commands[i + 1].shouldRun == -1)
                commands[i + 1].shouldRun = WEXITSTATUS(wait(NULL)) == 0 ? 1 : 0;
        }
    }

    // Wait for all child processes to finish
    while (wait(NULL) > 0);
}

int main() {
    struct Command commands[MAX_COMMANDS] = {
        { .args = (char *[]){"ls", "-l", NULL}, .uid = 1000, .gid = 1000, .shouldRun = 1 },
        { .args = (char *[]){"grep", "main.c", NULL}, .uid = 1001, .gid = 1001, .shouldRun = -1 }, // Depends on the first command
        // Add more commands as needed
    };

    runCommands(commands, 2);
    return 0;
}
