public class WebsiteManager
{
    private static readonly ConcurrentDictionary<string, bool> AddedSites = new();
    private readonly ILogger<WebsiteManager> _logger;
    private readonly int _maxConcurrentAdditions;

    public WebsiteManager(ILogger<WebsiteManager> logger)
    {
        _logger = logger;
        _maxConcurrentAdditions = int.Parse(System.Configuration.ConfigurationManager.AppSettings["MaxConcurrentSiteAdditions"]);
    }

    public string AddWebsiteToDirectory(string directoryPath, string siteName)
    {
        if (string.IsNullOrWhiteSpace(directoryPath) || string.IsNullOrWhiteSpace(siteName))
            return null;

        try
        {
            // 1. Validate Directory Path
            if (!Directory.Exists(directoryPath) || !HasReadWritePermissions(directoryPath))
                throw new UnauthorizedAccessException("Invalid directory path or insufficient permissions.");

            // 2. Check for web.config file
            var configFilePath = Path.Combine(directoryPath, "web.config");
            if (!File.Exists(configFilePath))
            {
                _logger.LogWarning($"[{DateTime.UtcNow}] Web.config not found in {directoryPath}.");
                return null;
            }

            // 3. Ensure Unique Site Name
            if (AddedSites.ContainsKey(siteName))
                throw new ArgumentException("Site name already exists.");

            // 4. Handle Concurrent Access & 5. Log Actions
            var semaphore = new SemaphoreSlim(_maxConcurrentAdditions);
            using (semaphore)
            {
                return Task.Run(async () =>
                {
                    try
                    {
                        _logger.LogInformation($"[{DateTime.UtcNow}] Adding site '{siteName}' to directory '{directoryPath}'.");

                        // 7. Validate web.config file with external service
                        if (!await ValidateConfigFileAsync(configFilePath))
                            throw new InvalidOperationException("web.config validation failed.");

                        // Add the site
                        AddedSites.TryAdd(siteName, true);

                        // Start the website using Process class
                        var process = Process.Start(new ProcessStartInfo("cmd", $"/c appcmd start site {siteName}")
                        {
                            CreateNoWindow = true,
                            UseShellExecute = false
                        });
                        _logger.LogInformation($"[{DateTime.UtcNow}] Successfully started site '{siteName}'.");

                        return siteName;
