            futures.add(executor.submit(task));
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.HOURS);

        generateReport(futures);
    }

    private static List<Command> loadCommands(Path filePath) throws IOException {
        // Load command and metadata from file
        List<Command> commands = new ArrayList<>();
        try (BufferedReader reader = Files.newBufferedReader(filePath)) {
            String line;
            while ((line = reader.readLine()) != null) {
                JSONObject json = new JSONObject(line);
                String name = json.getString("name");
                long timestamp = json.getLong("timestamp");
                commands.add(new Command(name, timestamp));
            }
        }
        return commands;
    }

    private static void generateReport(List<Future<CommandExecutionResult>> futures) {
        System.out.println("Summary Report:");
        for (Future<CommandExecutionResult> future : futures) {
            try {
                CommandExecutionResult result = future.get();
                System.out.println(result.toString());
            } catch (ExecutionException | InterruptedException e) {
                System.err.println("Error retrieving execution result: " + e.getMessage());
            }
        }
    }

    private static class CommandExecutionTask implements Callable<CommandExecutionResult> {
        private final Command command;

        public CommandExecutionTask(Command command) {
            this.command = command;
        }

        @Override
        public CommandExecutionResult call() throws Exception {
            long startTime = System.currentTimeMillis();
            double startMemoryUsage = getUsedMemory();
            double cpuLoadStart = getCpuLoad();

            ProcessBuilder builder = new ProcessBuilder(command.name.split(" "));
            Process process = builder.start();

            int exitCode;
            try {
                exitCode = process.waitFor();
            } finally {
                cleanupTemporaryFiles(process);
            }

            long endTime = System.currentTimeMillis();
            double endMemoryUsage = getUsedMemory();
            double cpuLoadEnd = getCpuLoad();

            String status = exitCode == 0 ? "Success" : "Failed";
            command.status = status;

            return new CommandExecutionResult(command.name, startTime, endTime,
                    startMemoryUsage, endMemoryUsage, cpuLoadStart, cpuLoadEnd, status);
        }

        private void cleanupTemporaryFiles(Process process) {
            // Implement logic to clean up temporary files created by the command
            ProcessHandle currentProcess = ProcessHandle.current();
            for (ProcessHandle.Info info : currentProcess.children()) {
                if (info.command().isPresent() && info.command().get().contains("command")) { // Replace "command" with actual identification criteria
                    info.delete();
                }
            }
        }

        private double getUsedMemory() {
            Runtime runtime = Runtime.getRuntime();
            return (runtime.totalMemory() - runtime.freeMemory()) / 1048576.0; // Return memory usage in MB
        }

        private double getCpuLoad() {
            // Implement CPU load retrieval logic, or use a library like SIGAR for more accurate results
            return 0.0;
        }
    }

    private static class CommandExecutionResult {
        String commandName;
        long startTime;
        long endTime;
        double startMemoryUsage;
        double endMemoryUsage;
        double cpuLoadStart;
        double cpuLoadEnd;
        String status;

        public CommandExecutionResult(String commandName, long startTime, long endTime,
                                      double startMemoryUsage, double endMemoryUsage,
                                      double cpuLoadStart, double cpuLoadEnd, String status) {
            this.commandName = commandName;
            this.startTime = startTime;
            this.endTime = endTime;
            this.startMemoryUsage = startMemoryUsage;
            this.endMemoryUsage = endMemoryUsage;
            this.cpuLoadStart = cpuLoadStart;
            this.cpuLoadEnd = cpuLoadEnd;
            this.status = status;
        }

        @Override
        public String toString() {
            return "Command: " + commandName +
                    ", Start Time: " + startTime +
                    ", End Time: " + endTime +
                    ", Memory Usage (MB): " + startMemoryUsage + " -> " + endMemoryUsage +
                    ", CPU Load: " + cpuLoadStart + " -> " + cpuLoadEnd +
                    ", Status: " + status;
        }
    }
}
```

This Java application processes shell commands read from a file, executing them in parallel using an `ExecutorService`. It tracks execution metrics like start/end times, memory usage, and CPU load. Commands are encapsulated with metadata for logging purposes. The application includes cleanup logic for temporary files and provides robust error handling, ensuring the batch process continues even if individual commands fail. The design supports future extensibility by incorporating external configuration services and additional command types.']

