// Predefined log levels
const char* LOG_LEVELS[] = {"DEBUG", "INFO", "WARN", "ERROR", "CRITICAL"};
#define NUM_LOG_LEVELS (sizeof(LOG_LEVELS) / sizeof(LOG_LEVELS[0]))

// Function to check if a string is a valid file path
int is_valid_file_path(const char *path) {
    // Simple heuristic: check if the path is not NULL and has a non-zero length
    return path != NULL && strlen(path) > 0;
}

// Function to validate log level
int is_valid_log_level(const char *level) {
    for (int i = 0; i < NUM_LOG_LEVELS; ++i) {
        if (strcmp(level, LOG_LEVELS[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

// Function to process and validate JSON configuration
int validate_logging_config(const char *json_data) {
    json_error_t error;
    json_t *root = json_loads(json_data, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return 0;
    }

    // Validate log_level
    json_t *log_level_json = json_object_get(root, "log_level");
    if (!json_is_string(log_level_json)) {
        fprintf(stderr, "'log_level' must be a string.\n");
        goto cleanup;
    }
    const char *log_level = json_string_value(log_level_json);
    if (!is_valid_log_level(log_level)) {
        fprintf(stderr, "'log_level' value is invalid. Allowed values are: DEBUG, INFO, WARN, ERROR, CRITICAL.\n");
        goto cleanup;
    }

    // Validate log_file_path
    json_t *log_file_path_json = json_object_get(root, "log_file_path");
    if (!json_is_string(log_file_path_json)) {
        fprintf(stderr, "'log_file_path' must be a string.\n");
        goto cleanup;
    }
    const char *log_file_path = json_string_value(log_file_path_json);
    if (!is_valid_file_path(log_file_path)) {
        fprintf(stderr, "'log_file_path' is not a valid file path.\n");
        goto cleanup;
    }

    // Validate log_rotation_interval (optional)
    json_t *log_rotation_interval_json = json_object_get(root, "log_rotation_interval");
    if (json_is_integer(log_rotation_interval_json)) {
        int interval = json_integer_value(log_rotation_interval_json);
        if (interval <= 0) {
            fprintf(stderr, "'log_rotation_interval' must be a positive integer.\n");
            goto cleanup;
        }
    }

    // If all validations pass
    printf("Configuration is valid.\n");
    json_decref(root);
    return 1;

cleanup:
    json_decref(root);
    return 0;
}

// Example usage
int main() {
    const char *json_config = "{\"log_level\":\"INFO\", \"log_file_path\":\"/var/log/app.log\"}";
    if (validate_logging_config(json_config)) {
        printf("Configuration processed successfully.\n");
    } else {
        printf("Invalid configuration.\n");
    }
    return 0;
}
