```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class TripleDESDecryptor
{
    public static string DecryptMessage(string base64EncryptedMessage, string key, string iv, string salt, string format)
    {
        try
        {
            // Decode the encrypted message from Base64
            byte[] encryptedBytes = Convert.FromBase64String(base64EncryptedMessage);

            // Determine the format and convert the key, IV, and salt to bytes
            byte[] keyBytes = ParseFormat(key, format);
            byte[] ivBytes = ParseFormat(iv, format);
            byte[] saltBytes = ParseFormat(salt, format);

            // Check lengths for Triple DES (key: 24 bytes, IV: 8 bytes)
            if (keyBytes.Length != 24) throw new ArgumentException("Invalid key length. Key must be 24 bytes.");
            if (ivBytes.Length != 8) throw new ArgumentException("Invalid IV length. IV must be 8 bytes.");

            // Prepare the DES provider with Triple DES
            using TripleDESCryptoServiceProvider tripleDES = new TripleDESCryptoServiceProvider
            {
                Mode = CipherMode.CBC,
                Padding = PaddingMode.PKCS7
            };

            // Set key and IV
            tripleDES.Key = keyBytes;
            tripleDES.IV = ivBytes;

            // Create a decryptor object
            using ICryptoTransform decryptor = tripleDES.CreateDecryptor(tripleDES.Key, tripleDES.IV);

            // Decrypt the encrypted bytes
            using MemoryStream msDecrypt = new MemoryStream(encryptedBytes);
            using CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
            using StreamReader srDecrypt = new StreamReader(csDecrypt);

            // Read and return decrypted message
            string decryptedMessage = srDecrypt.ReadToEnd();
            return decryptedMessage;
        }
        catch (Exception ex)
        {
            return $"Decryption failed: {ex.Message}";
        }
    }

    private static byte[] ParseFormat(string input, string format)
    {
        switch (format.ToLower())
        {
            case "hex":
                // Convert hex to bytes
                return HexToBytes(input);
            case "base64":
                // Convert Base64 to bytes
                return Convert.FromBase64String(input);
            case "ascii":
                // Convert ASCII string to bytes
                return Encoding.ASCII.GetBytes(input);
            default:
                throw new ArgumentException("Invalid format specified. Use 'hex', 'base64', or 'ascii'.");
        }
    }

    private static byte[] HexToBytes(string hex)
    {
        if (hex.Length % 2 != 0) throw new ArgumentException("Hex string must have an even length.");

        var bytes = new byte[hex.Length / 2];
        for (int i = 0; i < bytes.Length; i++)
        {
            bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
        }
        return bytes;
    }

    // Example usage
    public static void Main(string[] args)
    {
        string base64EncryptedMessage = "YourBase64EncryptedData";
        string key = "HexOrBase64OrAsciiKey";
        string iv = "HexOrBase64OrAsciiIV";
        string salt = "SaltValue"; // Salt not directly used in Triple DES, but could be for pre-processing
        string format = "hex";     // Can be 'hex', 'base64', or 'ascii'

        string decryptedMessage = DecryptMessage(base64EncryptedMessage, key, iv, salt, format);
        Console.WriteLine("Decrypted Message: " + decryptedMessage);
    }
}
```

### Key Considerations:
- **Error Handling:** The code includes error handling to manage invalid keys, IVs, and malformed inputs with descriptive error messages.
- **Format Parsing:** A helper function `ParseFormat` converts key, IV, and salt from hex, Base64, or ASCII formats into bytes.
- **Triple DES Decryption:** It uses Triple DES in CBC mode with PKCS7 padding for decryption, following best practices for cryptographic security. 
- **Modularity and Maintenance:** The code is structured to allow easy updates or changes in the encryption algorithm by modifying or extending the `TripleDESDecryptor` class.

This solution balances usability, efficiency, and maintainability while allowing for potential future scaling and integration with additional components.']

