public class TextFileProcessor
{
    private static readonly Regex WordRegex = new Regex(@"\b[\w']+\b", RegexOptions.Compiled | RegexOptions.IgnoreCase);

    public async Task<ConcurrentDictionary<string, int>> ProcessFileAsync(string filePath, CancellationToken cancellationToken)
    {
        var wordFrequency = new ConcurrentDictionary<string, int>(StringComparer.OrdinalIgnoreCase);

        using (var reader = new StreamReader(filePath))
        {
            string line;
            while ((line = await reader.ReadLineAsync()) != null && !cancellationToken.IsCancellationRequested)
            {
                ProcessLine(line, wordFrequency);
            }
        }

        // Optionally save intermediate results to a temporary database here
        SaveIntermediateResults(wordFrequency);

        return wordFrequency;
    }

    private void ProcessLine(string line, ConcurrentDictionary<string, int> wordFrequency)
    {
        var matches = WordRegex.Matches(line);
        Parallel.ForEach(matches.Cast<Match>(), match =>
        {
            string word = match.Value.ToLower();
            wordFrequency.AddOrUpdate(word, 1, (key, oldValue) => oldValue + 1);
        });
    }

    private void SaveIntermediateResults(ConcurrentDictionary<string, int> results)
