using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class AesCbcDecryptionManager : IDisposable
{
    private readonly ConcurrentDictionary<string, (byte[] Key, byte[] IV)> keyStore = new();
    private readonly SemaphoreSlim semaphore;
    private bool disposed = false;

    public AesCbcDecryptionManager(int maxDegreeOfParallelism)
    {
        semaphore = new(maxDegreeOfParallelism);
    }

    public void AddKey(string identifier, byte[] key, byte[] iv)
    {
        if (key == null || iv == null || key.Length != 32 || iv.Length != 16)
            throw new ArgumentException("Invalid key or IV size.");

        keyStore[identifier] = (key, iv);
    }

    public void RotateKey(string identifier, byte[] newKey, byte[] newIV)
    {
        if (!keyStore.ContainsKey(identifier) || newKey == null || newIV == null)
            throw new ArgumentException("Identifier not found or invalid parameters.");

        keyStore[identifier] = (newKey, newIV);
    }

    public async Task<ConcurrentBag<byte[]>> DecryptBatchAsync(IEnumerable<(string KeyId, byte[] Ciphertext)> ciphertexts)
    {
        var decryptedData = new ConcurrentBag<byte[]>();
        await Task.Run(() =>
        {
            Parallel.ForEach(ciphertexts, ciphertext =>
            {
                semaphore.Wait();

                try
                {
                    if (!keyStore.TryGetValue(ciphertext.KeyId, out var keyInfo))
                        throw new InvalidOperationException("Key not found.");

                    using (Aes aesAlg = Aes.Create())
                    {
                        aesAlg.Key = keyInfo.Key;
                        aesAlg.IV = keyInfo.IV;
                        aesAlg.Mode = CipherMode.CBC;

                        ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                        using (var msDecrypt = new System.IO.MemoryStream(ciphertext.Ciphertext))
                        {
                            using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                            {
                                var plaintextBytes = new byte[ciphertext.Ciphertext.Length];
                                int bytesRead = csDecrypt.Read(plaintextBytes, 0, plaintextBytes.Length);
                                if (bytesRead > 0)
                                    decryptedData.Add(plaintextBytes[..bytesRead]);
                            }
                        }
                    }
                }
                catch (Exception ex) when (!(ex is OperationCanceledException))
                {
                    // Log the error
                    Console.WriteLine($"Decryption failed: {ex.Message}");
                }
                finally
                {
                    semaphore.Release();
                }
            });
        });

        return decryptedData;
    }

    public void ConfigureThreadPool(int maxDegreeOfParallelism)
    {
        if (semaphore.CurrentCount != 0)
            throw new InvalidOperationException("Cannot reconfigure pool while tasks are running.");

        semaphore = new SemaphoreSlim(maxDegreeOfParallelism);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!disposed)
        {
            if (disposing)
            {
                // Free any other managed objects here.
            }
            disposed = true;
        }
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }
}

