    public static async Task LoadDataAsync(string filePath, Func<byte[], DataStructure> deserializeFunc)
    {
        await Task.Run(() =>
        {
            using (var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            using (var decompressionStream = new GZipStream(fileStream, CompressionMode.Decompress))
            using (var memoryStream = new MemoryStream())
            {
                decompressionStream.CopyTo(memoryStream);
                var data = memoryStream.ToArray();

                // Deserialize the data
                var deserializedData = deserializeFunc(data);

                // Further processing can be done here

                TaskQueue.Enqueue(Task.CompletedTask);  // Example to manage task queue, adapt as needed.
            }
        });
    }

    public static async Task LoadAndProcessAsync(string filePath)
    {
        await LoadDataAsync(filePath, bytes =>
        {
            try
            {
                return MessagePackSerializer.Deserialize<DataStructure>(bytes);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"MessagePack deserialization failed: {ex.Message}");

                // Fallback to JSON if needed
                return JsonConvert.DeserializeObject<DataStructure>(System.Text.Encoding.UTF8.GetString(bytes));
            }
        });
    }

    public static async Task LoadMultipleFilesAsync(string[] filePaths)
    {
        var tasks = new Task[filePaths.Length];

        for (int i = 0; i < filePaths.Length; i++)
        {
