#include <iostream>
#include <vector>
#include <string>
#include <mutex>
#include <thread>
#include <memory>
#include <unordered_map>
#include "TLVEncoder.h" // Assume this is the TLVEncoder library header.
#include "NAS_Message.h" // Assume NAS_Message structure or class definition.
#include "ExternalDataService.h" // External service interface for fetching message templates.
#include "FileUploadLibrary.h" // File upload library interface.

// Structure to represent LTE Downlink Common Control Channel Message Type 1
struct LTE_DL_CCCH_Message_Type1_T {
    TLVEncoder encoder;
    NAS_Message nasMessage;

    LTE_DL_CCCH_Message_Type1_T() : encoder(), nasMessage() {}
};

class URLProcessor {
private:
    std::vector<std::unique_ptr<LTE_DL_CCCH_Message_Type1_T>> messageArray;
    std::unordered_map<std::string, std::string> templateCache;
    std::mutex cacheMutex;
    std::mutex arrayMutex;

    // Fetch and decode a NAS message template from the external service.
    bool fetchAndDecodeTemplate(const std::string& url, LTE_DL_CCCH_Message_Type1_T& message) {
        try {
            std::string templateData = ExternalDataService::fetchTemplate(url);
            if (templateData.empty()) return false;

            // Cache the fetched template for future use
            {
                std::lock_guard<std::mutex> lock(cacheMutex);
                templateCache[url] = templateData;
            }

            // Decode using TLVEncoder and NAS_Message
            message.encoder.encode(templateData); 
            message.nasMessage.setContent(templateData);

            return true;
        } catch (...) {
            logError("Failed to fetch or decode template from URL: " + url);
            return false;
        }
    }

    void logError(const std::string& errorMessage) {
        // Logging mechanism
        std::cerr << "[ERROR] " << errorMessage << std::endl;
    }

public:
    URLProcessor(size_t maxCapacity) {
        messageArray.reserve(maxCapacity);
    }

    bool processURLs(const std::vector<std::string>& urls) {
        for (const auto& url : urls) {
            if (messageArray.size() >= messageArray.capacity()) {
                logError("Memory budget exceeded, cannot process more URLs.");
                return false;
            }

            std::unique_ptr<LTE_DL_CCCH_Message_Type1_T> message = std::make_unique<LTE_DL_CCCH_Message_Type1_T>();
            if (!fetchAndDecodeTemplate(url, *message)) {
                continue; // Skip this URL if failed to fetch/decode
            }

            {
                std::lock_guard<std::mutex> lock(arrayMutex);
                messageArray.push_back(std::move(message));
            }
        }

        return true;
    }

    std::string uploadProcessedFiles() {
        try {
            FileUploadLibrary fileUploader;
            for (const auto& message : messageArray) {
                // Assume serialize method is available to convert the message into a format suitable for uploading
                std::string serializedData = message->nasMessage.serialize();
                fileUploader.addFile(serializedData);
            }

            return fileUploader.uploadAll();  // Returns URL of uploaded files.
        } catch (...) {
            logError("Failed during file upload process.");
            return "";
        }
    }
};

int main() {
    std::vector<std::string> urls = {"http://example.com/template1", "http://example.com/template2"};
    URLProcessor processor(10); // Assuming a max capacity of 10 messages

    if (processor.processURLs(urls)) {
        std::string uploadedFileURL = processor.uploadProcessedFiles();
        if (!uploadedFileURL.empty()) {
            std::cout << "Uploaded files available at: " << uploadedFileURL << std::endl;
        }
    }

    return 0;
}
```

### Key Considerations:

- **Memory Management**: The use of `std::vector` with a pre-reserved capacity ensures efficient memory allocation while maintaining a limit on the maximum number of processed messages.

- **Concurrency**: Mutexes (`cacheMutex`, `arrayMutex`) ensure thread-safe operations on shared resources, preventing race conditions during template fetching and message array modification.

- **Caching Strategy**: Templates are cached in an unordered map to speed up repeated access. The cache is guarded by a mutex for safe concurrent access.

- **Error Handling**: Comprehensive error logging is used throughout the code to capture and report issues at various stages of processing, including data fetching and file upload failures.

- **Robustness**: Graceful handling of memory limits and errors ensures the system remains stable under high load or failure conditions.']

["```javascript
const { exec } = require('child_process');
const EventEmitter = require('events');

class CommandExecutor extends EventEmitter {
  constructor(maxConcurrent = 5) {
    super();
    this.maxConcurrent = Math.min(parseInt(process.env.MAX_CONCURRENT, 10) || maxConcurrent, require('os').cpus().length * 4);
    this.activeTasks = 0;
    this.queue = [];
  }

  executeCommands(commands, timeout = 5000) {
    const results = new Map();

    commands.forEach((commandConfig, index) => {
      this.runCommand(commandConfig, index, timeout)
        .then(result => {
          results.set(index, result);
          if (results.size === commands.length) {
            this.emit('done', Array.from(results.entries()));
          }
        })
        .catch(err => {
          results.set(index, { error: err.message });
          if (results.size === commands.length) {
            this.emit('done', Array.from(results.entries()));
          }
        });
    });

    return new Promise(resolve => {
      this.on('done', resolve);
    });
  }

  runCommand(commandConfig, index, timeout) {
    return new Promise((resolve, reject) => {
      if (this.activeTasks >= this.maxConcurrent) {
        this.queue.push({ commandConfig, index, resolve, reject, timeout });
        return;
      }

      this.executeTask(commandConfig, index, resolve, reject, timeout);
    }).then(result => this.retryIfNeeded(commandConfig, result))
      .catch(error => this.retryIfNeeded(commandConfig, { error }, true));
  }

  executeTask(commandConfig, index, resolve, reject, timeout) {
    const command = commandConfig.command;
    const maxRetries = commandConfig.retries || 3;
    const delay = commandConfig.delay || 1000;

    let retries = 0;

    const attemptExecution = () => {
      this.activeTasks++;

      const timer = setTimeout(() => {
        reject(new Error(`Command timed out: ${command}`));
        process.nextTick(() => {
          this.completeTask();
          cleanup();
        });
      }, timeout);

      exec(command, (error, stdout, stderr) => {
        clearTimeout(timer);

        if (error || !stdout.trim()) {
          if (retries < maxRetries) {
            retries++;
            setTimeout(attemptExecution, delay * Math.pow(2, retries - 1));
            return;
          } else {
            reject(new Error(`Command failed after ${maxRetries} attempts: ${stderr}`));
          }
        }

        resolve({ stdout, stderr });
      });

      const cleanup = () => {
        this.activeTasks--;
        if (this.queue.length > 0) {
          const nextTask = this.queue.shift();
          this.executeTask(nextTask.commandConfig, nextTask.index, nextTask.resolve, nextTask.reject, nextTask.timeout);
        }
      };

      process.nextTick(() => {
        this.completeTask();
        cleanup();
      });
    };

    attemptExecution();

    this.emit('taskStarted', { command: commandConfig.command, index });
  }

  completeTask() {
    if (this.activeTasks < this.maxConcurrent && this.queue.length > 0) {
      const nextTask = this.queue.shift();
      this.executeTask(nextTask.commandConfig, nextTask.index, nextTask.resolve, nextTask.reject, nextTask.timeout);
    }
  }

  retryIfNeeded(commandConfig, result, isFailed = false) {
    if (!isFailed && (result.error || !result.stdout.trim())) {
      return new Promise((resolve, reject) => {
        const delay = commandConfig.delay || 1000;
        setTimeout(() => this.runCommand(commandConfig, commandConfig.index, commandConfig.timeout)
          .then(resolve).catch(reject), delay);
      });
    }

    return result;
  }
}

module.exports = CommandExecutor;

// Usage Example
(async () => {
  const executor = new CommandExecutor();

  executor.on('taskStarted', data => console.log(`Starting: ${data.command} [${data.index}]`));

  try {
    const commands = [
      { command: 'echo Hello World' },
      { command: 'ls -la', retries: 2, delay: 2000 },
      // Add more commands as needed
    ];

    const results = await executor.executeCommands(commands);
    console.log('Results:', results);
  } catch (error) {
    console.error('Execution failed:', error);
  }
})();
```"]

