    *size = 0;
    int largest = -2147483648; // INT_MIN
    int count = 0;
    int value;

    // Efficiently read integers and find the maximum
    while (scanf("%d", &value) == 1 && count < MAX_INPUT_SIZE) {
        if (count > 0 && value > largest)
            largest = value;
        count++;
    }

    if (largest == -2147483648) { // No valid input or only empty input
        *size = 0;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus)
        return NULL;

    unsigned int RX_UE_INFORMATION_TAG = random.randint(1, 1000);
    unsigned int RNTI = largest & 0xFFFF; // Example operation to derive RNTI

    for (int i = 0; i < num_pdus; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdus[i].RNTI = RNTI;
        for (int j = 0; j < 4; ++j)
            pdus[i].CRC_INDICATION_REL8_TAG[j] = random.randint(0, 255);
    }

    *size = num_pdus;
    return pdus;
}

