typedef struct {
    LTE_DL_CCCH_Message_Type1_T *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MessageManager;

// Logging function
void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

// Initialize the message manager
int init_message_manager(MessageManager *manager, size_t initial_capacity) {
    if (initial_capacity == 0 || manager == NULL) return -1;

    manager->messages = malloc(initial_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!manager->messages) {
        log_error("Memory allocation failed for messages");
        return -1;
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return 0;
}

// Populate the message array
int populate_messages(MessageManager *manager) {
    if (!manager || manager->messages == NULL) return -1;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < MAX_MESSAGES && manager->count < manager->capacity; ++i) {
        LTE_DL_CCCH_Message_Type1_T *msg = &manager->messages[manager->count];

        msg->nas_message_id = rand() % 100;
        snprintf(msg->encoder.content, sizeof(msg->encoder.content), "Message content for ID %d", msg->nas_message_id);
        msg->encoder.message_type = rand() % 10; // Example range of message types

        manager->count++;
    }

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

// Resize the message array
int resize_messages(MessageManager *manager, size_t new_capacity) {
    if (!manager || manager->messages == NULL || new_capacity <= manager->capacity) return -1;

    LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(manager->messages, new_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!new_messages) {
        log_error("Memory reallocation failed for messages");
        return -1;
    }

    manager->messages = new_messages;
    manager->capacity = new_capacity;

    return 0;
}

// Periodic health check function
void* health_check(void *arg) {
    MessageManager *manager = (MessageManager*)arg;

    while (1) {
        sleep(5); // Check every 5 seconds

        pthread_mutex_lock(&manager->lock);

        printf("Active Messages: %zu\n", manager->count);

        if (manager->count >= manager->capacity) {
            size_t new_capacity = manager->capacity * 2;
            if (resize_messages(manager, new_capacity) != 0) {
                log_error("Failed to resize messages during health check");
            }
        }

        pthread_mutex_unlock(&manager->lock);
    }

    return NULL;
}

// Example usage
int main() {
    MessageManager manager;

    if (init_message_manager(&manager, 100) != 0) {
        log_error("Failed to initialize message manager");
        return -1;
    }

    // Launch health check in a separate thread
    pthread_t health_thread;
    pthread_create(&health_thread, NULL, health_check, &manager);

    // Simulate concurrent execution by multiple threads
    pthread_t worker_threads[10];
    for (int i = 0; i < 10; ++i) {
        pthread_create(&worker_threads[i], NULL, (void*)populate_messages, &manager);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(worker_threads[i], NULL);
    }

    // Cleanup
    free(manager.messages);
    pthread_mutex_destroy(&manager.lock);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutex locks are used to protect shared resources.
- **Dynamic Resizing**: The array is resized when the capacity is reached, doubling its size each time.
- **Logging**: Simple logging mechanism for error reporting.
- **Health Check**: Periodic checks on message count and resizing if necessary.

This implementation considers thread safety, memory efficiency, and performance optimization suitable for embedded systems. Adjust sizes and parameters as needed based on specific requirements.']

