        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < record_count; ++i) {
        int rand_value;
        do {
            rand_value = min_val + rand() % (max_val - min_val + 1);
        } while (rand_value < min_val || rand_value > max_val); // Ensure within range
        (*records)[i].value = rand_value;
    }
}

