namespace DataManagement {

    struct record {
        int value;

        record(int v) : value(v) {}
    };

    class DataHandler {
    public:
        using RecordArray = std::vector<record>;
        using OffsetArray = std::vector<long>;
        using KeyArray = std::vector<int>;

        static std::mt19937 rng;

        DataHandler(size_t size, int minValue, int maxValue)
            : size_(size), minValue_(minValue), maxValue_(maxValue) {
            initialize();
        }

        ~DataHandler() noexcept {
            Logger::log("Destructor called. Cleaning up resources.");
            clearResources();
        }

        static void seedRandomGenerator(unsigned long seed) {
            std::lock_guard<std::mutex> lock(rng_mutex);
            rng.seed(seed);
        }

    private:
        size_t size_;
        int minValue_, maxValue_;

        OffsetArray offsetValues;
        KeyArray keys;
        RecordArray records;

        std::mutex allocationMutex;
        static std::mutex rng_mutex; // Ensure thread safety for the random generator

        void initialize() {
            try {
                std::lock_guard<std::mutex> lock(allocationMutex);

                std::uniform_int_distribution<int> keyDist(minValue_, maxValue_);
                std::unordered_set<int> uniqueKeys;

                while (uniqueKeys.size() < size_) {
                    int key = keyDist(rng);
                    if (uniqueKeys.insert(key).second) {
                        keys.push_back(key);
                    }
                }

                for (size_t i = 0; i < size_; ++i) {
                    offsetValues.emplace_back(static_cast<long>(keys[i]));
                    records.emplace_back(keys[i]); // Assuming API call or similar logic can be incorporated here
                }

                Logger::log("DataHandler initialized successfully.");
            } catch (const std::bad_alloc& e) {
                errorHandling(e.what());
            }
        }

        void clearResources() noexcept {
            offsetValues.clear();
            keys.clear();
            records.clear();
        }

        static void errorHandling(const char* msg) noexcept {
            Logger::error(std::string("Memory allocation failed: ") + msg);
            // No further actions needed, resources will be cleaned up by the destructor
        }
    };

    std::mt19937 DataHandler::rng{std::random_device{}()};
