```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Measurement {
    char type[20];
    double value;
} Measurement;

typedef struct NetworkPerformanceMetrics {
    time_t timestamp;
    int session_id;
    Measurement *measurements;
    size_t measurement_count;
    struct NetworkPerformanceMetrics *next;
} NetworkPerformanceMetrics;

typedef struct {
    NetworkPerformanceMetrics *head;
    pthread_mutex_t lock;
    size_t count;
} MetricsList;

void initialize_metrics_list(MetricsList *list, time_t retention_time) {
    list->head = NULL;
    list->lock = PTHREAD_MUTEX_INITIALIZER;
    list->count = 0;
}

NetworkPerformanceMetrics* create_metric_entry(time_t timestamp, int session_id, Measurement *measurements, size_t count) {
    NetworkPerformanceMetrics *new_entry = (NetworkPerformanceMetrics*)malloc(sizeof(NetworkPerformanceMetrics));
    if (!new_entry) {
        perror("Failed to allocate memory for new metric entry");
        return NULL;
    }

    new_entry->timestamp = timestamp;
    new_entry->session_id = session_id;
    new_entry->measurements = measurements ? malloc(count * sizeof(Measurement)) : NULL;
    if (measurements && !new_entry->measurements) {
        perror("Failed to allocate memory for measurements");
        free(new_entry);
        return NULL;
    }
    new_entry->measurement_count = count;
    new_entry->next = NULL;

    if (measurements) {
        for (size_t i = 0; i < count; ++i) {
            new_entry->measurements[i] = measurements[i];
        }
    }

    return new_entry;
}

void add_metric(MetricsList *list, NetworkPerformanceMetrics *entry) {
    pthread_mutex_lock(&list->lock);

    entry->next = list->head;
    list->head = entry;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void cleanup_metrics(MetricsList *list, time_t current_time, time_t retention_time) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics **current = &list->head;

    while (*current) {
        if (difftime(current_time, (*current)->timestamp) > retention_time) {
            NetworkPerformanceMetrics *to_delete = *current;
            *current = to_delete->next;

            free(to_delete->measurements);
            free(to_delete);

            list->count--;
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_metrics_list(MetricsList *list) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics *entry = list->head;

    while (entry) {
        NetworkPerformanceMetrics *to_free = entry;
        entry = entry->next;

        free(to_free->measurements);
        free(to_free);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
}

// Example usage of periodic cleanup
void* periodic_cleanup(void *arg) {
    MetricsList *metrics_list = (MetricsList*) arg;

    while (1) {
        time_t current_time = time(NULL);
        // Define retention period in seconds, e.g., 3600 for one hour.
        time_t retention_time = 3600;

        cleanup_metrics(metrics_list, current_time, retention_time);

        // Sleep or wait for a suitable duration before next cleanup
        sleep(60); 
    }

    return NULL;
}
```

### Key Points:
- **Thread Safety**: The use of `pthread_mutex` ensures that the linked list is accessed safely across multiple threads.
- **Dynamic Resizing and Memory Management**: Metrics are dynamically allocated with appropriate error checks. Use `free()` to manage memory efficiently.
- **Scalability & Performance**: Thread-safe operations and periodic cleanup help maintain performance under concurrent access.
- **Data Consistency**: Mutex locks ensure data integrity during read/write operations.
- **Error Handling**: Error messages printed using `perror()` for better diagnostics.

This code should be integrated into a larger system where network monitoring metrics are collected, processed, and utilized. The design allows flexibility in handling different measurement types and concurrent updates without performance degradation.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_INPUT 10000

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* buffer;
    size_t capacity;
    size_t count;
    FILE* disk_file;
} BufferManager;

BufferManager buffer_manager = {PTHREAD_MUTEX_INITIALIZER, NULL, 0, 0, NULL};

void flush_to_disk() {
    pthread_mutex_lock(&buffer_manager.lock);
    if (buffer_manager.disk_file == NULL) {
        buffer_manager.disk_file = fopen("flushed_data.bin", "wb");
        if (!buffer_manager.disk_file) {
            perror("Failed to open disk file");
            exit(EXIT_FAILURE);
        }
    }
    fwrite(buffer_manager.buffer, sizeof(NFAPI_CRC_INDICATION_PDU_T), buffer_manager.count, buffer_manager.disk_file);
    buffer_manager.count = 0;
    pthread_mutex_unlock(&buffer_manager.lock);
}

void* read_and_populate(void* arg) {
    int value;
    size_t index = 0;

    while (fscanf(arg, "%d", &value) == 1) {
        if (index >= MAX_INPUT) break;

        pthread_mutex_lock(&buffer_manager.lock);
        if (buffer_manager.count < buffer_manager.capacity) {
            NFAPI_CRC_INDICATION_PDU_T* buf = &buffer_manager.buffer[buffer_manager.count++];
            buf->RX_UE_INFORMATION_TAG = rand() % 10000;
            buf->RNTI = rand() % 10000;
            buf->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

            if (buffer_manager.count >= buffer_manager.capacity / 2) {
                flush_to_disk();
            }
        } else {
            pthread_mutex_unlock(&buffer_manager.lock);
            usleep(1000); // Sleep to allow disk flushing
            continue;
        }
        pthread_mutex_unlock(&buffer_manager.lock);

