    printf("Largest CRCFLAG: %d at index: %zu\n", largest_value, largest_index);

    if (buffer_manager.disk_file) {
        fclose(buffer_manager.disk_file);
    }

    free(buffer_manager.buffer);
    return largest_index;
}

int main() {
    srand(time(NULL));
    size_t total_structures = find_largest_and_process();
    printf("Total structures successfully created: %zu\n", total_structures);
    return 0;
}
