// Define constants and structures
#define MAX_ARRAY_SIZE 10000
#define TIME_LIMIT_MS 5000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Union-Find data structure
int parent[MAX_ARRAY_SIZE];
int rank[MAX_ARRAY_SIZE];

void make_set(int x) {
    parent[x] = x;
    rank[x] = 0;
}

int find(int x) {
    if (parent[x] != x) {
        parent[x] = find(parent[x]);
    }
    return parent[x];
}

void union_sets(int x, int y) {
    int rootX = find(x);
    int rootY = find(y);

    if (rootX != rootY) {
        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }
}

// Mock function to validate tags
int validate_tag(int tag) {
    // Simulate latency
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    // Simulated validation logic
    int valid = (tag % 2 == 0); // Example condition

    clock_gettime(CLOCK_MONOTONIC, &end);
    double elapsed_time_ms = ((end.tv_sec - start.tv_sec) * 1000.0) + ((end.tv_nsec - start.tv_nsec) / 1e6);

    printf("Tag validation took %.2f ms\n", elapsed_time_ms);

    return valid;
}

// Function to process NFAPairs
int processNFAPairs(int arr[], int size, NFAPI_CRC_INDICATION_PDU_T *output, int *num_pairs) {
    if (size > MAX_ARRAY_SIZE) {
        fprintf(stderr, "Array size exceeds maximum limit.\n");
        return -1;
    }

    for (int i = 0; i < size; i++) {
        make_set(i);
    }

    int pair_count = 0;
    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    for (int i = 0; i < size - 1; i++) {
        if ((clock_gettime(CLOCK_MONOTONIC, &end_time), 
             ((end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000)) > TIME_LIMIT_MS) {
            printf("Time limit exceeded.\n");
            break;
        }

        for (int j = i + 1; j < size; j++) {
            if ((clock_gettime(CLOCK_MONOTONIC, &end_time), 
                 ((end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000)) > TIME_LIMIT_MS) {
                printf("Time limit exceeded.\n");
                break;
            }

            if (find(i) != find(j)) {
                if (validate_tag(arr[i]) && validate_tag(arr[j])) {
                    union_sets(i, j);
                    int rx_ue_info_tag = arr[i];
                    int rnti = arr[j];

                    output[pair_count].RX_UE_INFORMATION_TAG = rx_ue_info_tag;
                    output[pair_count].RNTI = rnti;
                    output[pair_count].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

                    pair_count++;
                }
            }
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end_time);
    double total_elapsed_time_ms = ((end_time.tv_sec - start_time.tv_sec) * 1000.0) + ((end_time.tv_nsec - start_time.tv_nsec) / 1e6);
    printf("Total processing time: %.2f ms\n", total_elapsed_time_ms);

    *num_pairs = pair_count;
    return 0;
}

// Example usage
int main() {
    int arr[] = {1, 2, 3, 4, 5, 6};
    int size = sizeof(arr) / sizeof(arr[0]);
    NFAPI_CRC_INDICATION_PDU_T output[MAX_ARRAY_SIZE];
    int num_pairs;

    processNFAPairs(arr, size, output, &num_pairs);

    printf("Number of disjoint pairs: %d\n", num_pairs);
    for (int i = 0; i < num_pairs; i++) {
        printf("Pair %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n",
               i + 1,
               output[i].RX_UE_INFORMATION_TAG,
               output[i].RNTI,
               output[i].CRCFLAG);
    }

    return 0;
}
