#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

// Define maximum number of UEs and configuration parameters
#define MAX_UES 1000000

typedef struct {
    int ue_id;
    double measurement_result;
    time_t timestamp;
} UEContext;

typedef struct Node {
    UEContext context;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} UEList;

// Function prototypes
void init_ue_list(UEList* list);
int add_ue_context(UEList* list, int ue_id, double measurement_result);
int update_ue_context(UEList* list, int ue_id, double measurement_result);
UEContext* get_latest_measurement(UEList* list, int ue_id);
void free_ue_list(UEList* list);

// Function implementations
void init_ue_list(UEList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int add_ue_context(UEList* list, int ue_id, double measurement_result) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->context.ue_id == ue_id) {
            pthread_mutex_unlock(&list->lock);
            return 0; // UE already exists
        }
        current = current->next;
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    new_node->context.ue_id = ue_id;
    new_node->context.measurement_result = measurement_result;
    new_node->context.timestamp = time(NULL);
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 1; // Success
}

int update_ue_context(UEList* list, int ue_id, double measurement_result) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->context.ue_id == ue_id) {
            current->context.measurement_result = measurement_result;
            current->context.timestamp = time(NULL);
            pthread_mutex_unlock(&list->lock);
            return 1; // Success
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // UE not found
}

UEContext* get_latest_measurement(UEList* list, int ue_id) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->context.ue_id == ue_id) {
            UEContext* context = malloc(sizeof(UEContext));
            if (!context) {
                pthread_mutex_unlock(&list->lock);
                return NULL; // Memory allocation failure
            }
            *context = current->context;
            pthread_mutex_unlock(&list->lock);
            return context; // Return a copy of the context
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // UE not found
}

void free_ue_list(UEList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    UEList ue_list;
    init_ue_list(&ue_list);

    add_ue_context(&ue_list, 1, 10.0);
    update_ue_context(&ue_list, 1, 15.5);

    UEContext* context = get_latest_measurement(&ue_list, 1);
    if (context) {
        printf("UE ID: %d, Measurement: %.2f, Timestamp: %ld\n", 
               context->ue_id, context->measurement_result, context->timestamp);
        free(context);
    }

    free_ue_list(&ue_list);
    return 0;
}
