#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define necessary structures
typedef struct {
    double x;
    double y;
} Point;

typedef struct {
    unsigned char red;
    unsigned char green;
    unsigned char blue;
} Color;

typedef struct {
    Color *pixels; // Dynamic array of pixels
    int width;
    int height;
} Image;

// Function declarations for memory management and initialization
double* allocate_double_array(size_t size, double start_value, double step);
Point* initialize_points(size_t count, Point transformation(Point));
Color* initialize_colors(size_t count, Color gradient(Color, size_t index));
Image* allocate_images(size_t image_count, int width, int height);
void free_resources(double *doubles, Point *points, Color *colors, Image *images);

// Main function implementing the task
int manage_memory_and_initialize(size_t double_size, double start_value, double step,
                                 size_t point_count, Point (*point_transform)(Point),
                                 size_t color_count, Color (*color_gradient)(Color, size_t),
                                 size_t image_count, int width, int height) {
    // Allocate and initialize doubles array
    double *doubles = allocate_double_array(double_size, start_value, step);
    if (!doubles) return -1;

    // Initialize points array
    Point *points = initialize_points(point_count, point_transform);
    if (!points) goto cleanup_doubles;

    // Initialize colors array
    Color *colors = initialize_colors(color_count, color_gradient);
    if (!colors) goto cleanup_points;

    // Allocate and initialize images array
    Image *images = allocate_images(image_count, width, height);
    if (!images) goto cleanup_colors;

    // Successful allocation and initialization
    return 0;

cleanup_colors:
    free(points);
cleanup_points:
    free(doubles);

cleanup_doubles:
    fprintf(stderr, "Memory allocation failed.\n");
    return -1;
}

// Implementations of helper functions

double* allocate_double_array(size_t size, double start_value, double step) {
    double *array = (double*)malloc(size * sizeof(double));
    if (!array) return NULL;

    for (size_t i = 0; i < size; ++i) {
        array[i] = start_value + i * step;
    }

    return array;
}

Point* initialize_points(size_t count, Point (*transform)(Point)) {
    Point *points = (Point*)malloc(count * sizeof(Point));
    if (!points) return NULL;

    for (size_t i = 0; i < count; ++i) {
        Point p = { .x = (double)i, .y = (double)i };
        points[i] = transform(p);
    }

    return points;
}

Color* initialize_colors(size_t count, Color (*gradient)(Color, size_t)) {
    Color *colors = (Color*)malloc(count * sizeof(Color));
    if (!colors) return NULL;

    Color base_color = { .red = 0, .green = 0, .blue = 0 };
    for (size_t i = 0; i < count; ++i) {
        colors[i] = gradient(base_color, i);
    }

    return colors;
}

Image* allocate_images(size_t image_count, int width, int height) {
    Image *images = (Image*)malloc(image_count * sizeof(Image));
    if (!images) return NULL;

    for (size_t i = 0; i < image_count; ++i) {
        images[i].width = width;
        images[i].height = height;
        images[i].pixels = (Color*)calloc(width * height, sizeof(Color));
        if (!images[i].pixels) {
            free(images);
            return NULL;
        }
    }

    return images;
}

void free_resources(double *doubles, Point *points, Color *colors, Image *images) {
    if (doubles) free(doubles);
    if (points) free(points);
    if (colors) free(colors);

    for (size_t i = 0; images && i < sizeof(images) / sizeof(images[0]); ++i) {
        if (images[i].pixels) free(images[i].pixels);
    }

    if (images) free(images);
}

// Example transformation and gradient functions
Point example_transform(Point p) {
    return (Point){ .x = p.x * 2, .y = p.y + 1 };
}

Color example_gradient(Color c, size_t index) {
    return (Color){
        .red = index % 256,
        .green = (index * 2) % 256,
        .blue = (index * 3) % 256
    };
}
