typedef struct {
    int rx_UE_information_tag;
    int rnti;
    unsigned char crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct UnionFind {
    int *parent;
    size_t size;
} UnionFind;

UnionFind* create_union_find(size_t size) {
    UnionFind *uf = malloc(sizeof(UnionFind));
    uf->size = size;
    uf->parent = malloc(size * sizeof(int));
    for (size_t i = 0; i < size; ++i) {
        uf->parent[i] = -1;
    }
    return uf;
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] < 0)
        return x;
    return uf->parent[x] = find(uf, uf->parent[x]);
}

void union_sets(UnionFind *uf, int x, int y) {
    x = find(uf, x);
    y = find(uf, y);

    if (x != y) {
        if (uf->parent[y] < uf->parent[x]) {
            int temp = x;
            x = y;
            y = temp;
        }
        uf->parent[x] += uf->parent[y];
        uf->parent[y] = x;
    }
}

int validate_environment() {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    } else if (pid == 0) { // Child process
        execlp("/path/to/valid_command", "command_name", NULL);
        exit(EXIT_FAILURE); // If exec fails
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0);
        return WEXITSTATUS(status);
    }
}

int processNfaPairs(int *arr, size_t n) {
    if (validate_environment() != 0) {
        fprintf(stderr, "Environment validation failed.\n");
        return -1;
    }

    UnionFind *uf = create_union_find(n);

    NFAPI_CRC_INDICATION_PDU_T *pfds = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pfds) {
        free(uf->parent);
        free(uf);
        return -1;
    }

    for (size_t i = 0; i < n; ++i) {
        pfds[i].rx_UE_information_tag = arr[i];
        pfds[i].rnti = arr[i] ^ 0xAAAAAA; // Example XOR
        pfds[i].crc_flag = rand() % 256;
    }

    int disjoint_pairs_count = 0;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    struct timespec start, end;

    for (size_t i = 0; i < n; ++i) {
        for (size_t j = i + 1; j < n; ++j) {
            clock_gettime(CLOCK_MONOTONIC, &start);

            pthread_mutex_lock(&lock);

            if (find(uf, i) != find(uf, j)) {
                disjoint_pairs_count++;
                union_sets(uf, i, j);
            }

            pthread_mutex_unlock(&lock);

            clock_gettime(CLOCK_MONOTONIC, &end);
            long elapsed = 1000000 * (end.tv_sec - start.tv_sec) + end.tv_nsec / 1000 - start.tv_nsec / 1000;
            printf("Disjointness check for pair (%zu, %zu) took %ld ms\n", i, j, elapsed / 1000);
        }
    }

    free(pfds->parent);
    free(uf);

    pthread_mutex_destroy(&lock);

    return disjoint_pairs_count;
}
