typedef struct {
    int value;
    char str_value[20];
    time_t timestamp;
} record;

// External logging interface (mock implementation)
void log_operation(const char *message) {
    printf("LOG: %s\n", message);
}

int allocate_and_initialize(long num_offsets, int key_range_min, int key_range_max, long *offsets, int *keys, record **records) {
    if (num_offsets <= 0 || key_range_max <= key_range_min) return -1;

    // Allocate memory for offsets
    offsets = malloc(num_offsets * sizeof(long));
    if (!offsets) {
        log_operation("Failed to allocate memory for offsets");
        return -1;
    }

    // Allocate memory for keys
    keys = malloc(num_offsets * sizeof(int));
    if (!keys) {
        free(offsets);
        log_operation("Failed to allocate memory for keys");
        return -1;
    }

    // Allocate memory for records
    *records = malloc(num_offsets * sizeof(record));
    if (!*records) {
        free(offsets);
        free(keys);
        log_operation("Failed to allocate memory for records");
        return -1;
    }

    srand((unsigned int)time(NULL));

    int used_values[key_range_max - key_range_min + 1] = {0};
    int unique_keys_count = 0;

    time_t last_timestamp = 0;

    for (long i = 0; i < num_offsets; ++i) {
        offsets[i] = rand() % 10000; // Example offset value

        int key;
        do {
            key = key_range_min + rand() % (key_range_max - key_range_min + 1);
        } while (used_values[key - key_range_min]);

        used_values[key - key_range_min] = 1;
        keys[unique_keys_count++] = key;

        record *rec = &((*records)[i]);
        rec->value = key;

        snprintf(rec->str_value, sizeof(rec->str_value), "%d", key);
        rec->timestamp = time(NULL);

        if (rec->timestamp <= last_timestamp) {
            log_operation("Timestamp error: Non-monotonic timestamps detected");
            free(offsets);
            free(keys);
            free(*records);
            return -1;
        }

        last_timestamp = rec->timestamp;

        log_operation("Record created successfully");

        // Check if all unique keys are used
        if (unique_keys_count == num_offsets) break;
    }

    if (unique_keys_count != num_offsets) {
        log_operation("Failed to generate enough unique keys");
        free(offsets);
        free(keys);
        free(*records);
        return -1;
    }

    return 0;
}

void free_resources(long *offsets, int *keys, record **records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records && *records) free(*records);
}

