// Error log file path and size limit for rotation (in bytes)
const char *error_log_path = "error.log";
const size_t error_log_size_limit = 1024 * 1024; // 1MB
pthread_mutex_t log_file_mutex = PTHREAD_MUTEX_INITIALIZER;

void rotate_log_file() {
    pthread_mutex_lock(&log_file_mutex);
    FILE *current_log = fopen(error_log_path, "r");
    if (current_log) {
        fseek(current_log, 0, SEEK_END);
        long current_size = ftell(current_log);
        fclose(current_log);

        if (current_size >= error_log_size_limit) {
            char new_filename[256];
            time_t now = time(NULL);
            strftime(new_filename, sizeof(new_filename), "error_%Y%m%d%H%M%S.log", localtime(&now));
            rename(error_log_path, new_filename);
        }
    }

    FILE *new_log = fopen(error_log_path, "a");
    if (new_log) fclose(new_log);
    pthread_mutex_unlock(&log_file_mutex);
}

void log_error(const char *message) {
    rotate_log_file();
    pthread_mutex_lock(&log_file_mutex);
    FILE *file = fopen(error_log_path, "a");
    if (file) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
    pthread_mutex_unlock(&log_file_mutex);
}

