void log_error(const char* message) {
    pthread_mutex_lock(&lock);
    FILE* file = fopen(ERROR_LOG_FILE, "a+");
    if (file != NULL) {
        fseek(file, 0, SEEK_END);
        long size = ftell(file);
        if (size > LOG_MAX_SIZE) {
            freopen("error_log.txt.new", "w+", file);
            strcpy((char*)file_gets(), message); // Create new log starting with this message
        } else {
            fprintf(file, "%s\n", message);
        }
        fclose(file);
    }
    pthread_mutex_unlock(&lock);
}

char* get_random_string(size_t max_length) {
    char* str = malloc(max_length + 1);
    if (str == NULL) {
        log_error("Failed to allocate memory for dynamic string");
        return NULL;
    }
    size_t length = rand() % (max_length + 1);
    for (size_t i = 0; i < length; ++i) {
        str[i] = 'a' + rand() % 26;
    }
    str[length] = '\0';
    return str;
}

void* initialize_records(void* arg) {
    int num_records = *(int*)arg;
    Record** records = malloc(num_records * sizeof(Record*));
    if (records == NULL) {
        log_error("Failed to allocate memory for record pointers");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) {
