        snprintf(records[i]->buffer, sizeof(records[i]->buffer), "Buffer_%d", i);

        records[i]->dynamic_string = get_random_string(MAX_STRING_LENGTH);
        if (records[i]->dynamic_string == NULL) {
            free(records[i]);
            records[i] = NULL;
        }
    }

    // Verify integrity
    for (int i = 0; i < num_records; ++i) {
        if (records[i]) {
            if (!records[i]->dynamic_string || strlen(records[i]->dynamic_string) > MAX_STRING_LENGTH) {
                log_error("Data integrity issue found");
            }
        }
    }

    return records;
}

void free_records(Record** records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i]) {
            free(records[i]->dynamic_string);
            free(records[i]);
        }
    }
    free(records);
}

int main() {
    const int num_records = 10000;
    Record** records = initialize_records(&num_records);

    // Use the records...

    free_records(records, num_records);
    pthread_mutex_destroy(&lock);
    return 0;
}
