#define MIN_VAL 0
#define MAX_VAL 100

typedef struct {
    int *array;
    size_t size;
} IntArray;

IntArray* read_and_validate_integers(const char *filename, int min_val, int max_val) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return NULL;
    }

    IntArray *result = malloc(sizeof(IntArray));
    if (!result) {
        fprintf(stderr, "Memory allocation failed for IntArray\n");
        fclose(file);
        return NULL;
    }
    result->array = NULL;
    result->size = 0;

    int value;
    while (fscanf(file, "%d", &value) == 1) {
        if (value >= min_val && value <= max_val) {
            result->array = realloc(result->array, sizeof(int) * (result->size + 1));
            if (!result->array) {
                fprintf(stderr, "Memory allocation failed during integer storage\n");
                free(result);
                fclose(file);
                return NULL;
            }
            result->array[result->size++] = value;
        }
    }

    fclose(file);

    if (result->size < 2) {
        printf("Insufficient valid integers in file %s\n", filename);
        free(result->array);
        free(result);
        return NULL;
    }

    return result;
}

void find_and_print_largest_integer(IntArray *arr) {
    int largest = arr->array[0];
    for (size_t i = 1; i < arr->size; ++i) {
        if (arr->array[i] > largest) {
            largest = arr->array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

void free_int_array(IntArray *arr) {
    free(arr->array);
    free(arr);
}

// Example usage with concurrent processing support
#include <pthread.h>

typedef struct {
    const char *filename;
    int min_val;
    int max_val;
} ThreadData;

void* process_file(void *arg) {
    ThreadData *data = (ThreadData *)arg;
    IntArray *arr = read_and_validate_integers(data->filename, data->min_val, data->max_val);
    if (arr) {
        find_and_print_largest_integer(arr);
        free_int_array(arr);
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> [<file2> ...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_files = argc - 1;
    pthread_t threads[num_files];
    ThreadData thread_data[num_files];

    for (size_t i = 0; i < num_files; ++i) {
        thread_data[i].filename = argv[i + 1];
        thread_data[i].min_val = MIN_VAL;
        thread_data[i].max_val = MAX_VAL;

        if (pthread_create(&threads[i], NULL, process_file, &thread_data[i]) != 0) {
            fprintf(stderr, "Failed to create thread for file %s\n", argv[i + 1]);
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
