void parseCSV(const char *filename, long **timestamps, float **temperatures,
              char ***sensorIDs, SensorData **dataStructures, int *count) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    char line[256];
    float validTemperatureRangeMin = -50.0;
    float validTemperatureRangeMax = 150.0;

    while (fgets(line, sizeof(line), file)) {
        if (*count >= 1000) { // Reached estimated maximum records
            printf("Reached estimated max record limit.\n");
            break;
        }

        char *token = strtok(line, ",");
        if (token == NULL)
            continue; // Malformed line

        long timestamp = strtol(token, NULL, 10);

        token = strtok(NULL, ",");
        if (token == NULL || sscanf(token, "%f", &(*temperatures)[*count]) != 1
            || (*temperatures)[*count] < validTemperatureRangeMin
            || (*temperatures)[*count] > validTemperatureRangeMax)
        {
            continue; // Missing or invalid temperature
        }

        token = strtok(NULL, ",");
        if (token == NULL || strlen(token) >= 10)
            continue; // Missing or malformed sensor ID

        (*timestamps)[*count] = timestamp;
        strncpy((*sensorIDs)[*count], token, 9);
        (*sensorIDs)[*count][9] = '\0'; // Ensure null-termination

        (*dataStructures)[*count].timestamp = timestamp;
        (*dataStructures)[*count].temperature = (*temperatures)[*count];
        strncpy((*dataStructures)[*count].sensorID, token, 9);
        (*dataStructures)[*count].sensorID[9] = '\0';

        (*count)++;
    }

    fclose(file);
}

void freeResources(long *timestamps, float *temperatures, char **sensorIDs,
                   SensorData *dataStructures) {
    free(timestamps);
    free(temperatures);

    for (int i = 0; sensorIDs[i] != NULL; ++i)
        free(sensorIDs[i]);
    free(sensorIDs);

    free(dataStructures);
}

int main() {
    long *timestamps;
    float *temperatures;
    char **sensorIDs;
    SensorData *dataStructures;
    int count;

    initializeArrays(&timestamps, &temperatures, &sensorIDs, &dataStructures, &count);

    parseCSV("sensors.csv", &timestamps, &temperatures, &sensorIDs, &dataStructures, &count);

    // Use data here...

    freeResources(timestamps, temperatures, sensorIDs, dataStructures);

    return 0;
}
