#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_CACHE_SIZE 1000
#define LOG_FILE "dns_log.txt"
#define RETRY_LIMIT 5

typedef enum {
    SUCCESS,
    ERROR_DNS_SERVER_UNREACHABLE,
    ERROR_NETWORK_TIMEOUT,
    ERROR_DNS_FAILURE,
    ERROR_MALFORMED_RESPONSE,
    ERROR_MEMORY_ALLOCATION,
} StatusCode;

typedef struct CacheNode {
    char hostname[256];
    u_char ip_address[16]; // Supports both IPv4 and IPv6
    time_t timestamp;
    struct CacheNode* next;
} CacheNode;

typedef struct {
    CacheNode* head;
    CacheNode* tail;
    int size;
    pthread_mutex_t lock;
} LRUCache;

LRUCache cache = {NULL, NULL, 0, PTHREAD_MUTEX_INITIALIZER};
int cache_size = MAX_CACHE_SIZE;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

void loadConfig() {
    // Mock loading from a configuration file
    FILE* config_file = fopen("config.txt", "r");
    if (config_file) {
        fscanf(config_file, "%d", &cache_size);
        fclose(config_file);
    }
}

void writeLog(const char* hostname, const u_char* ip_address, StatusCode status) {
    pthread_mutex_lock(&log_lock);
    FILE* log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "Hostname: %s, IP Address: ", hostname);
        for (int i = 0; i < 16; ++i) {
            fprintf(log, "%02x", ip_address[i]);
            if (i == 3 || i == 7 || i == 11) fprintf(log, ":");
        }
        fprintf(log, ", Status: %d\n", status);
        fclose(log);
    }
    pthread_mutex_unlock(&log_lock);
}

void evictLRU() {
    if (cache.size > cache_size) {
        CacheNode* old = cache.head;
        cache.head = cache.head->next;
        free(old);
        --cache.size;
    }
}

StatusCode resolveHostname(const char* hostname, u_char* ip_address) {
    loadConfig();

    pthread_mutex_lock(&cache.lock);

    // Check cache first
    for (CacheNode* node = cache.head; node != NULL; node = node->next) {
        if (strcmp(node->hostname, hostname) == 0) {
            memcpy(ip_address, node->ip_address, sizeof(u_char[16]));
            pthread_mutex_unlock(&cache.lock);
            writeLog(hostname, ip_address, SUCCESS);
            return SUCCESS;
        }
    }

    pthread_mutex_unlock(&cache.lock);

    struct addrinfo hints = {0}, *res, *p;
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    for (int attempt = 0; attempt < RETRY_LIMIT; ++attempt) {
        int err = getaddrinfo(hostname, NULL, &hints, &res);
        if (err == 0) {
            break;
        }
        sleep(1 << attempt); // Exponential backoff
    }

    if (res == NULL) {
        writeLog(hostname, ip_address, ERROR_DNS_SERVER_UNREACHABLE);
        return ERROR_DNS_SERVER_UNREACHABLE;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
            inet_pton(AF_INET, inet_ntoa(ipv4->sin_addr), ip_address);
        } else if (p->ai_family == AF_INET6) { // IPv6
            struct sockaddr_in6* ipv6 = (struct sockaddr_in6*)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            inet_pton(AF_INET6, inet_ntop(AF_INET6, &ipv6->sin6_addr, ip_address + 12, sizeof(ip_address) - 12), ip_address);
        } else {
            continue;
        }

        // Cache the result
        pthread_mutex_lock(&cache.lock);

        CacheNode* new_node = (CacheNode*)malloc(sizeof(CacheNode));
        if (!new_node) {
            freeaddrinfo(res);
            writeLog(hostname, ip_address, ERROR_MEMORY_ALLOCATION);
            return ERROR_MEMORY_ALLOCATION;
        }

        strcpy(new_node->hostname, hostname);
        memcpy(new_node->ip_address, addr, sizeof(u_char[16]));
        new_node->timestamp = time(NULL);

        if (cache.head == NULL) {
            cache.head = cache.tail = new_node;
            new_node->next = NULL;
        } else {
            cache.tail->next = new_node;
            cache.tail = new_node;
            new_node->next = NULL;
        }
        ++cache.size;

        evictLRU();

        pthread_mutex_unlock(&cache.lock);
        writeLog(hostname, ip_address, SUCCESS);
        freeaddrinfo(res);
        return SUCCESS;
    }

    freeaddrinfo(res);
    writeLog(hostname, ip_address, ERROR_DNS_FAILURE);
    return ERROR_DNS_FAILURE;
}

void resetMockLibrary() {
    // Placeholder for mock library cleanup
}

int main() {
    u_char ip[16];
    StatusCode status = resolveHostname("example.com", ip);

    if (status == SUCCESS) {
        printf("Resolved IP: ");
        for (int i = 0; i < 16; ++i) {
            printf("%02x", ip[i]);
            if (i == 3 || i == 7 || i == 11) printf(":");
        }
        printf("\n");
    } else {
        printf("Failed to resolve hostname. Status code: %d\n", status);
    }

    resetMockLibrary();
    return 0;
}
