#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RNTI 1048575 // Example maximum RNTI value based on typical constraints

typedef struct {
    int crcFlag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long rnti;              // RNTI must be within the range [0, MAX_RNTI]
    void* rxUeInformationTag;        // Placeholder for RX_UE_INFORMATION_TAG
    CRC_INDICATION_REL8_TAG crcIndication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t size;
    size_t capacity;
} NFList;

// Function prototypes
NFList* createNFList(size_t capacity);
int addElement(NFList* list, unsigned long rnti);
void updateElement(NFList* list, size_t index, int newCrcFlag);
void cleanupNFList(NFList* list);

// Helper functions
static void initializeCRC_INDICATION_REL8_TAG(CRC_INDICATION_REL8_TAG* tag);
static void generateRandomCrcFlag(int* crcFlag);

NFList* createNFList(size_t capacity) {
    NFList* list = (NFList*)malloc(sizeof(NFList));
    if (!list) return NULL;

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = capacity;
    srand((unsigned int)time(NULL)); // Seed random number generator

    for (size_t i = 0; i < capacity; ++i) {
        initializeCRC_INDICATION_REL8_TAG(&list->elements[i].crcIndication);
        generateRandomCrcFlag(&list->elements[i].crcIndication.crcFlag);
    }

    return list;
}

int addElement(NFList* list, unsigned long rnti) {
    if (rnti > MAX_RNTI || list->size >= list->capacity) return -1;

    NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[list->size];
    element->rnti = rnti;
    initializeCRC_INDICATION_REL8_TAG(&element->crcIndication);
    generateRandomCrcFlag(&element->crcIndication.crcFlag);

    list->size++;
    return 0;
}

void updateElement(NFList* list, size_t index, int newCrcFlag) {
    if (index >= list->size) return;

    list->elements[index].crcIndication.crcFlag = newCrcFlag;
}

void cleanupNFList(NFList* list) {
    free(list->elements);
    free(list);
}

// Helper function implementations
static void initializeCRC_INDICATION_REL8_TAG(CRC_INDICATION_REL8_TAG* tag) {
    if (tag) memset(tag, 0, sizeof(*tag));
}

static void generateRandomCrcFlag(int* crcFlag) {
    if (crcFlag) *crcFlag = rand() % 2; // Randomly set to 0 or 1
}
