```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <openssl/evp.h>

// Error codes
#define SUCCESS 0
#define FAILURE -1

typedef struct {
    sem_t *sem;
    int blocking_mode; // 1 for blocking, 0 for non-blocking
} SemaphoreConfig;

typedef enum {
    ECB_MODE,
    EDE_MODE,
    EDE3_MODE,
    CFB_MODE,
    NULL_MODE
} EncryptionMode;

// Function to initialize semaphore
int init_semaphore(SemaphoreConfig *config, int initial_value, int blocking_mode) {
    config->sem = malloc(sizeof(sem_t));
    if (config->sem == NULL) return FAILURE;
    sem_init(config->sem, 0, initial_value);
    config->blocking_mode = blocking_mode;
    return SUCCESS;
}

// Function to destroy semaphore
void destroy_semaphore(SemaphoreConfig *config) {
    if (config && config->sem) {
        sem_destroy(config->sem);
        free(config->sem);
    }
}

// Function to acquire semaphore
int acquire_semaphore(SemaphoreConfig *config) {
    return config->blocking_mode ? sem_wait(config->sem) : sem_trywait(config->sem);
}

// Function to release semaphore
void release_semaphore(SemaphoreConfig *config) {
    sem_post(config->sem);
}

// Function to initialize encryption
EVP_CIPHER_CTX* init_encryption(EncryptionMode mode, const unsigned char *key, int key_len, int block_size) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    switch (mode) {
        case ECB_MODE:
            if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, NULL)) goto err;
            break;
        case EDE_MODE:
            if (1 != EVP_EncryptInit_ex(ctx, EVP_des_ede3(), NULL, key, NULL)) goto err;
            break;
        case EDE3_MODE:
            if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cfb128(), NULL, key, NULL)) goto err;
            break;
        case CFB_MODE:
            if (1 != EVP_EncryptInit_ex(ctx, EVP_des_cfb8(), NULL, key, NULL)) goto err;
            break;
        case NULL_MODE:
            // Handle null encryption
            return ctx;
    }

    if (1 != EVP_CIPHER_CTX_set_key_length(ctx, block_size)) goto err;

    return ctx;

err:
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

// Function to clean up encryption context
void cleanup_encryption(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

int main(int argc, char **argv) {
    // Example usage
    SemaphoreConfig sem_config;
    init_semaphore(&sem_config, 1, 1); // Initialize semaphore with blocking mode

    const unsigned char key[] = "0123456789abcdef"; // Example key
    EVP_CIPHER_CTX *ctx = init_encryption(ECB_MODE, key, sizeof(key), 128);

    if (!ctx) {
        fprintf(stderr, "Failed to initialize encryption\n");
        destroy_semaphore(&sem_config);
        return FAILURE;
    }

    acquire_semaphore(&sem_config);
    printf("Semaphore acquired\n");

    // Perform file processing here...

    release_semaphore(&sem_config);
    printf("Semaphore released\n");

    cleanup_encryption(ctx);
    destroy_semaphore(&sem_config);

    return SUCCESS;
}
```

### Key Features:
- **Semaphore Management**: Supports blocking and non-blocking modes.
- **Encryption Modes**: Supports ECB, EDE, EDE3, CFB, and null encryption.
- **Flexible Configuration**: Allows setting of semaphore behavior and encryption parameters.
- **Thread Safety**: Uses semaphores to ensure thread safety.
- **Performance Optimizations**: Minimizes latency by using efficient OpenSSL functions.
- **External Data Source Integration**: Can be extended to read/write from/to different sources via command-line or environment variables.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#ifdef _WIN32
#include <windows.h>
#else
#include <pthread.h>
#endif

#include "openssl/evp.h"
#include "openssl/rand.h"

#define AES_KEY_LENGTH 256
#define AES_BLOCK_SIZE 16

typedef enum {
    MODE_GCM = 1,
    MODE_CBC
} EncryptionMode;

typedef struct {
    unsigned char key[AES_KEY_LENGTH / 8];
    unsigned char iv[AES_BLOCK_SIZE];
} KeyIVPair;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    int mode;
} CryptoContext;

// Function prototypes
int generate_key_iv(KeyIVPair *keyiv);
void free_crypto_context(CryptoContext *context);
CryptoContext* create_crypto_context(EncryptionMode mode, const unsigned char *key, const unsigned char *iv);
int encrypt_data(CryptoContext *ctx, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int *ciphertext_len, const unsigned char *ad,
                 int ad_len);
int decrypt_data(CryptoContext *ctx, const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext, int *plaintext_len, const unsigned char *ad,
                 int ad_len);

// Error handling and logging
void log_error(const char *message) {
    time_t now = time(NULL);
    fprintf(stderr, "[%s] ERROR: %s\n", ctime(&now), message);
}

int generate_key_iv(KeyIVPair *keyiv) {
    if (!RAND_bytes(keyiv->key, sizeof(keyiv->key)) ||
        !RAND_bytes(keyiv->iv, sizeof(keyiv->iv))) {
        log_error("Key or IV generation failed");
        return 0;
    }
    return 1;
}

CryptoContext* create_crypto_context(EncryptionMode mode, const unsigned char *key, const unsigned char *iv) {
    CryptoContext *ctx = (CryptoContext*) malloc(sizeof(CryptoContext));
    if (!ctx) {
        log_error("Memory allocation failed for CryptoContext");
        return NULL;
    }

#ifdef _WIN32
    HANDLE hProcess = GetCurrentProcess();
    if (!VirtualAllocEx(hProcess, NULL, sizeof(EVP_CIPHER_CTX), MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE)) {
        free(ctx);
        log_error("Protected memory allocation failed");
        return NULL;
    }
#endif

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx);
        log_error("EVP_CIPHER_CTX initialization failed");
        return NULL;
    }

    ctx->mode = mode;
    switch (mode) {
        case MODE_GCM:
            if (1 != EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
                free_crypto_context(ctx);
                log_error("AES-GCM initialization failed");
                return NULL;
            }
            break;
        case MODE_CBC:
            if (1 != EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
                free_crypto_context(ctx);
                log_error("AES-CBC initialization failed");
                return NULL;
            }
            break;
    }

#ifdef _WIN32
    VirtualProtectEx(hProcess, ctx->ctx, sizeof(EVP_CIPHER_CTX), PAGE_READWRITE | PAGE_EXECUTE_READWRITE, NULL);
#endif

    return ctx;
}

void free_crypto_context(CryptoContext *context) {
    if (context && context->ctx) {
        EVP_CIPHER_CTX_free(context->ctx);
#ifdef _WIN32
        HANDLE hProcess = GetCurrentProcess();
        VirtualFreeEx(hProcess, context->ctx, 0, MEM_RELEASE);
#endif
        free(context);
    }
}

int encrypt_data(CryptoContext *ctx, const unsigned char *plaintext, int plaintext_len,
                 unsigned char *ciphertext, int *ciphertext_len, const unsigned char *ad, int ad_len) {
    if (1 != EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, NULL, NULL)) {
        log_error("Encryption initialization failed");
        return 0;
    }

    if (ctx->mode == MODE_GCM && ad) {
        if (1 != EVP_AuthDigestUpdate(ctx->ctx, ad, ad_len)) {
            log_error("AD update failed during encryption");
            return 0;
        }
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        log_error("Encryption update failed");
        return 0;
    }
    *ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len)) {
        log_error("Encryption finalization failed");
        return 0;
    }
    *ciphertext_len += len;

    if (ctx->mode == MODE_GCM) {
        unsigned int tag_len = 16; // Tag length
        unsigned char tag[tag_len];
        if (1 != EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_GET_TAG, tag_len, tag)) {
            log_error("Tag retrieval failed");
            return 0;
        }
        memcpy(ciphertext + *ciphertext_len, tag, tag_len);
        *ciphertext_len += tag_len;
    }

    return 1;
}

int decrypt_data(CryptoContext *ctx, const unsigned char *ciphertext, int ciphertext_len,
                 unsigned char *plaintext, int *plaintext_len, const unsigned char *ad, int ad_len) {
    if (1 != EVP_DecryptInit_ex(ctx->ctx, NULL, NULL, NULL, NULL)) {
        log_error("Decryption initialization failed");
        return 0;
    }

    if (ctx->mode == MODE_GCM && ad) {
        if (1 != EVP_AuthDigestUpdate(ctx->ctx, ad, ad_len)) {
            log_error("AD update failed during decryption");
            return 0;
        }
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len - (ctx->mode == MODE_GCM ? 16 : 0))) {
        log_error("Decryption update failed");
        return 0;
    }
    *plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len)) {
        log_error("Decryption finalization failed");
        return 0;
    }
    *plaintext_len += len;

    if (ctx->mode == MODE_GCM) {
        unsigned char tag[16];
        memcpy(tag, ciphertext + ciphertext_len - 16, 16);
        if (1 != EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_TAG, 16, tag)) {
            log_error("Tag setting failed during decryption");
            return 0;
        }
    }

    return 1;
}

// Example usage
int main() {
    KeyIVPair keyiv;
    if (!generate_key_iv(&keyiv)) {
        return EXIT_FAILURE;
    }

    unsigned char plaintext[] = "Sensitive data that needs encryption";
    int plaintext_len = strlen((char *)plaintext);
    unsigned char ciphertext[1024];
    int ciphertext_len;

    CryptoContext *ctx = create_crypto_context(MODE_GCM, keyiv.key, keyiv.iv);
    if (!ctx) {
        return EXIT_FAILURE;
    }

    if (encrypt_data(ctx, plaintext, plaintext_len, ciphertext, &ciphertext_len, NULL, 0)) {
        printf("Encryption successful\n");
    } else {
        log_error("Encryption failed");
        free_crypto_context(ctx);
        return EXIT_FAILURE;
    }

    unsigned char decryptedtext[1024];
    int decryptedtext_len;

    if (decrypt_data(ctx, ciphertext, ciphertext_len, decryptedtext, &decryptedtext_len, NULL, 0)) {
        printf("Decryption successful: %s\n", decryptedtext);
    } else {
        log_error("Decryption failed");
    }

    free_crypto_context(ctx);
    return EXIT_SUCCESS;
}
