['```c
#include <openssl/evp.h>
#include <openssl/chacha20.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    pthread_mutex_t lock;
} CipherContext;

typedef enum {
    CIPHER_DES_ECB,
    CIPHER_DES_3DES_EDE,
    CIPHER_AES,
    CIPHER_CHACHA20
} CipherType;

CipherContext* init_cipher(CipherType type, const unsigned char *key, int key_len) {
    CipherContext *cipher_ctx = malloc(sizeof(CipherContext));
    if (!cipher_ctx) return NULL;

    pthread_mutex_init(&cipher_ctx->lock, NULL);
    cipher_ctx->ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx->ctx) {
        free(cipher_ctx);
        return NULL;
    }

    switch (type) {
        case CIPHER_DES_ECB:
            if (!EVP_EncryptInit_ex(cipher_ctx->ctx, EVP_des_ecb(), NULL, key, NULL)) goto err;
            break;

        case CIPHER_DES_3DES_EDE:
            if (!EVP_EncryptInit_ex(cipher_ctx->ctx, EVP_des_ede3_cbc(), NULL, key, NULL)) goto err;
            break;

        case CIPHER_AES:
            if (!EVP_EncryptInit_ex(cipher_ctx->ctx, EVP_aes_256_cbc(), NULL, key, NULL)) goto err;
            break;

        case CIPHER_CHACHA20:
            // ChaCha20 doesn't use EVP directly; initialize manually
            if (!chacha20_init(cipher_ctx->ctx, key, key_len, NULL, 0)) goto err;
            break;

        default:
            goto err;
    }

    return cipher_ctx;

err:
    EVP_CIPHER_CTX_free(cipher_ctx->ctx);
    free(cipher_ctx);
    pthread_mutex_destroy(&cipher_ctx->lock);
    return NULL;
}

int encrypt(CipherContext *cipher_ctx, const unsigned char *plaintext, int plaintext_len,
            unsigned char *ciphertext) {
    pthread_mutex_lock(&cipher_ctx->lock);

    if (!EVP_EncryptUpdate(cipher_ctx->ctx, ciphertext, NULL, plaintext, plaintext_len)) {
        pthread_mutex_unlock(&cipher_ctx->lock);
        return 0;
    }

    int len = EVP_EncryptFinal_ex(cipher_ctx->ctx, ciphertext + plaintext_len, NULL);
    pthread_mutex_unlock(&cipher_ctx->lock);

    return plaintext_len + len;
}

int decrypt(CipherContext *cipher_ctx, const unsigned char *ciphertext, int ciphertext_len,
            unsigned char *plaintext) {
    pthread_mutex_lock(&cipher_ctx->lock);

    if (!EVP_DecryptUpdate(cipher_ctx->ctx, plaintext, NULL, ciphertext, ciphertext_len)) {
        pthread_mutex_unlock(&cipher_ctx->lock);
        return 0;
    }

    int len = EVP_DecryptFinal_ex(cipher_ctx->ctx, plaintext + ciphertext_len, NULL);
    pthread_mutex_unlock(&cipher_ctx->lock);

    return ciphertext_len + len;
}

void cleanup_cipher(CipherContext *cipher_ctx) {
    pthread_mutex_lock(&cipher_ctx->lock);
    EVP_CIPHER_CTX_free(cipher_ctx->ctx);
    pthread_mutex_unlock(&cipher_ctx->lock);
    pthread_mutex_destroy(&cipher_ctx->lock);
    free(cipher_ctx);
}

// Metrics collection and reporting functions
void collect_metrics() {
    // Placeholder for metrics collection logic
}

int main() {
    unsigned char key[32] = { /* Key material */ };
    const unsigned char *plaintext = (unsigned char *)"Hello, World!";
    int plaintext_len = strlen((char *)plaintext);
    unsigned char ciphertext[128];
    unsigned char decryptedtext[128];

    CipherContext *cipher_ctx = init_cipher(CIPHER_AES, key, sizeof(key));
    if (!cipher_ctx) {
        fprintf(stderr, "Cipher initialization failed\n");
        return 1;
    }

    int ciphertext_len = encrypt(cipher_ctx, plaintext, plaintext_len, ciphertext);
    if (ciphertext_len == 0) {
        fprintf(stderr, "Encryption failed\n");
        cleanup_cipher(cipher_ctx);
        return 1;
    }

    int decryptedtext_len = decrypt(cipher_ctx, ciphertext, ciphertext_len, decryptedtext);
    if (decryptedtext_len == 0) {
        fprintf(stderr, "Decryption failed\n");
        cleanup_cipher(cipher_ctx);
        return 1;
    }

    decryptedtext[decryptedtext_len] = '\0';
    printf("Original text: %s\n", plaintext);
    printf("Decrypted text: %s\n", decryptedtext);

    cleanup_cipher(cipher_ctx);
    collect_metrics();

    return 0;
}
