    if (manager.count >= MAX_ELEMENTS) {
        log_message("Maximum number of elements reached");
        pthread_mutex_unlock(&manager.lock);
        return -1;
    }

    if (!manager.array) {
        manager.array = allocate_pdu_array(10); // Initial allocation
        if (!manager.array) {
            pthread_mutex_unlock(&manager.lock);
            return -1;
        }
    } else if (manager.count == sizeof(manager.array) / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        size_t new_size = manager.count * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = allocate_pdu_array(new_size);
        if (!new_array) {
            pthread_mutex_unlock(&manager.lock);
            return -1;
        }
        memcpy(new_array, manager.array, manager.count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(manager.array);
        manager.array = new_array;
    }

    manager.array[manager.count++] = *element;

    pthread_cond_signal(&manager.cond_var);
    pthread_mutex_unlock(&manager.lock);
    return 0;
}

void* thread_function(void* arg) {
