typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        bool CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTIS 1024

typedef struct PriorityQueueNode {
    uint32_t tag;
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct PriorityQueueNode *next;
} PriorityQueueNode;

typedef struct {
    PriorityQueueNode *head;
    pthread_mutex_t lock;
} PriorityQueue;

typedef struct {
    uint16_t rnti_pool[MAX_RNTIS];
    size_t pool_size;
    pthread_mutex_t lock;
} RNTIManager;

void log_message(const char *level, const char *message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", level, ctime(&now));
}

RNTIManager* create_rnti_manager() {
    RNTIManager *manager = (RNTIManager*)malloc(sizeof(RNTIManager));
    if (!manager) return NULL;

    for (size_t i = 0; i < MAX_RNTIS; ++i) {
        manager->rnti_pool[i] = i + 1;
    }
    manager->pool_size = MAX_RNTIS;

    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

uint16_t get_unique_rnti(RNTIManager *manager, uint16_t rnti) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->pool_size; ++i) {
        if (manager->rnti_pool[i] == rnti) continue;

        uint16_t unique_rnti = manager->rnti_pool[i];
        memmove(manager->rnti_pool + i, manager->rnti_pool + i + 1,
                (manager->pool_size - i - 1) * sizeof(uint16_t));
        manager->pool_size--;

        pthread_mutex_unlock(&manager->lock);
        return unique_rnti;
    }

    pthread_mutex_unlock(&manager->lock);
    log_message("ERROR", "RNTI pool exhausted");
    return 0; // Pool exhausted
}

PriorityQueue* create_priority_queue() {
    PriorityQueue *queue = (PriorityQueue*)malloc(sizeof(PriorityQueue));
    if (!queue) return NULL;

    queue->head = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void enqueue(PriorityQueue *queue, uint32_t tag, NFAPI_CRC_INDICATION_PDU_T *data) {
    PriorityQueueNode *new_node = (PriorityQueueNode*)malloc(sizeof(PriorityQueueNode));
    if (!new_node) return;

    new_node->tag = tag;
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->lock);

    if (!queue->head || queue->head->tag > tag) {
        new_node->next = queue->head;
        queue->head = new_node;
    } else {
        PriorityQueueNode *current = queue->head;
        while (current->next && current->next->tag <= tag) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&queue->lock);
}

NFAPI_CRC_INDICATION_PDU_T* dequeue(PriorityQueue *queue) {
    pthread_mutex_lock(&queue->lock);

    if (!queue->head) {
        pthread_mutex_unlock(&queue->lock);
        return NULL;
    }

    PriorityQueueNode *node = queue->head;
    NFAPI_CRC_INDICATION_PDU_T *data = node->data;
    queue->head = node->next;

    free(node);
    pthread_mutex_unlock(&queue->lock);

    return data;
}

void cleanup_priority_queue(PriorityQueue *queue) {
    PriorityQueueNode *current = queue->head;
    while (current) {
        PriorityQueueNode *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(size_t count, RNTIManager *rnti_manager, PriorityQueue *priority_queue) {
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    for (size_t i = 0; i < count; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 10000;
