        array[i].RNTI = get_unique_rnti(rnti_manager, rnti);

        if (!array[i].RNTI) {
            free(array);
            log_message("ERROR", "Failed to allocate unique RNTI");
            return NULL;
        }

        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 == 0;

        // Enqueue for priority processing
        enqueue(priority_queue, array[i].RX_UE_INFORMATION_TAG, &array[i]);

        // Simulate broker integration (pseudo-code)
        // send_to_broker(array[i]);
    }

    return array;
}

void cleanup_resources(NFAPI_CRC_INDICATION_PDU_T *array, size_t count, RNTIManager *rnti_manager, PriorityQueue *priority_queue) {
    if (array) free(array);
    pthread_mutex_destroy(&rnti_manager->lock);
