#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <pthread.h>
#include <time.h>

#define MAX_SAMPLES 1000

typedef struct {
    int SNR;
} LINK_LAYER_STATS_T;

typedef struct {
    float TX_POWER_LEVELS;
    float RECEIVED_SIGNAL_STRENGTH;
    LINK_LAYER_STATS_T LINK_LAYER_STATS;
} PHY_STATS_PDU_T;

typedef struct {
    PHY_STATS_PDU_T* data;
    size_t count;
    pthread_mutex_t mutex;
} StatsArrayManager;

void log_message(const char *message) {
    // Implement logging mechanism
    fprintf(stderr, "%s\n", message);
}

static void compute_aggregated_stats(PHY_STATS_PDU_T *data, size_t count, float *mean, float *variance, float *std_dev) {
    if (count == 0) return;

    float sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += data[i].RECEIVED_SIGNAL_STRENGTH;
    }
    *mean = sum / count;

    float sq_sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sq_sum += pow(data[i].RECEIVED_SIGNAL_STRENGTH - *mean, 2);
    }
    *variance = sq_sum / count;
    *std_dev = sqrt(*variance);
}

int add_pdu(StatsArrayManager *manager, PHY_STATS_PDU_T pdu) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count >= MAX_SAMPLES) {
        log_message("Maximum number of samples exceeded.");
        pthread_mutex_unlock(&manager->mutex);
        return -1;
    }

    manager->data = realloc(manager->data, (manager->count + 1) * sizeof(PHY_STATS_PDU_T));
    if (!manager->data) {
        log_message("Memory allocation failed.");
        pthread_mutex_unlock(&manager->mutex);
        return -2;
    }

    manager->data[manager->count] = pdu;
    manager->count++;

    float mean, variance, std_dev;
    compute_aggregated_stats(manager->data, manager->count, &mean, &variance, &std_dev);

    printf("Mean: %f, Variance: %f, Std Dev: %f\n", mean, variance, std_dev);

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void free_resources(StatsArrayManager *manager) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->data != NULL) {
        free(manager->data);
        manager->data = NULL;
    }
    manager->count = 0;
    pthread_mutex_unlock(&manager->mutex);
}

void initialize_manager(StatsArrayManager *manager) {
    manager->data = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

int main() {
    StatsArrayManager manager;
    initialize_manager(&manager);

    srand(time(NULL));

    for (size_t i = 0; i < MAX_SAMPLES + 5; ++i) { // Attempt to add more than MAX_SAMPLES
        PHY_STATS_PDU_T pdu = {
            .TX_POWER_LEVELS = rand() % 100,
            .RECEIVED_SIGNAL_STRENGTH = rand() % 100,
            .LINK_LAYER_STATS = {.SNR = rand() % 50}
        };

        if (add_pdu(&manager, pdu) != 0) {
            printf("Failed to add PDU %zu\n", i);
        }
    }

    free_resources(&manager);

    return 0;
}
