#include <stdio.h>
#include <stdlib.h>
import threading

typedef struct {
    // Example fields; modify as needed for actual use case
    int TLVEncoder;
    char NAS_Message[256];
} LTE_DL_CCCH_Message_Type1_T;

#define MAX_THREADS 10

// Thread-safe logging function using a global lock.
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

void safe_log(const char *message) {
    pthread_mutex_lock(&log_lock);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_lock);
}

int compare_ints(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

// Function to initialize memory for the arrays and LTE structures
void init_memory(long num_offsets, int num_keys, int num_messages,
                 long offset_min, long offset_max, 
                 int key_min, int key_max, 
                 int message_type_min, int message_type_max) {

    if (num_offsets <= 0 || num_keys <= 0 || num_messages <= 0) {
        safe_log("Invalid input sizes.");
        return;
    }

    pthread_mutex_t offset_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_t key_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_t nas_message_lock = PTHREAD_MUTEX_INITIALIZER;

    long *offsets = (long *)calloc(num_offsets, sizeof(long));
    int *keys = (int *)malloc(num_keys * sizeof(int));

    if (!offsets || !keys) {
        safe_log("Memory allocation failed.");
        free(offsets);
        free(keys);
        return;
    }

    LTE_DL_CCCH_Message_Type1_T *lte_messages = 
        (LTE_DL_CCCH_Message_Type1_T *)malloc(num_messages * sizeof(LTE_DL_CCCH_Message_Type1_T));

    if (!lte_messages) {
        safe_log("Memory allocation failed.");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize offsets
    for (long i = 0; i < num_offsets; ++i) {
        pthread_mutex_lock(&offset_lock);
        offsets[i] = offset_min + rand() % (offset_max - offset_min + 1);
        pthread_mutex_unlock(&offset_lock);
    }

    qsort(offsets, num_offsets, sizeof(long), compare_ints);

    // Initialize keys
    for (int i = 0; i < num_keys; ++i) {
        pthread_mutex_lock(&key_lock);
        keys[i] = key_min + rand() % (key_max - key_min + 1);
        pthread_mutex_unlock(&key_lock);
    }

    qsort(keys, num_keys, sizeof(int), compare_ints);

    int used_types[num_messages];
    for (int i = 0; i < num_messages; ++i) {
        used_types[i] = message_type_min + rand() % (message_type_max - message_type_min + 1);
    }

    qsort(used_types, num_messages, sizeof(int), compare_ints);

    // Ensure unique NAS message types
    for (int i = 0; i < num_messages - 1; ++i) {
        if (used_types[i] == used_types[i + 1]) {
            safe_log("Duplicate NAS message type detected.");
            free(offsets);
            free(keys);
            free(lte_messages);
            return;
        }
    }

    // Initialize LTE_DL_CCCH_Message_Type1_T
    for (int i = 0; i < num_messages; ++i) {
        pthread_mutex_lock(&nas_message_lock);
        lte_messages[i].TLVEncoder = used_types[i];

        snprintf(lte_messages[i].NAS_Message, sizeof(lte_messages[i].NAS_Message),
                 "Message Type: %d, Content: RandomData%d", 
                 lte_messages[i].TLVEncoder, i);

        pthread_mutex_unlock(&nas_message_lock);
    }

    safe_log("Memory initialized successfully.");

    // Simulate operation logging
    printf("Offsets array size: %ld\n", num_offsets * sizeof(long));
    printf("Keys array size: %d\n", num_keys * sizeof(int));
    printf("LTE messages array size: %d\n", num_messages * sizeof(LTE_DL_CCCH_Message_Type1_T));

    // Free allocated resources
    free(offsets);
    free(keys);
    free(lte_messages);
}

int main() {
    long num_offsets = 100;
    int num_keys = 50;
    int num_messages = 30;

    init_memory(num_offsets, num_keys, num_messages,
                10, 20, 
                1, 100, 
                0, 5);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutexes are used to ensure thread safety for critical sections during initialization.
- **Logging**: A simple logging function ensures thread-safe log messages.
- **Memory Management**: Memory is allocated and checked; any failure leads to immediate cleanup.
- **Unique NAS Message Types**: Ensures no duplicate message types within the specified range.
- **Error Handling**: Checks for invalid input parameters and logs errors accordingly.']

