#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int cell_id;
    time_t timestamp;
    char status[20];
} NetworkEvent;

#define MAX_EVENTS 1000

// Global structure to manage network events
typedef struct {
    NetworkEvent *events;
    size_t count;
    pthread_mutex_t lock;
    FILE *log_file;
    char log_buffer[MAX_EVENTS][256];
    size_t log_count;
    pthread_mutex_t log_lock;
} NetworkManager;

void init_network_manager(NetworkManager *manager, const char *logfile) {
    manager->events = malloc(MAX_EVENTS * sizeof(NetworkEvent));
    if (!manager->events) {
        perror("Failed to allocate memory for events");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;

    pthread_mutex_init(&manager->lock, NULL);
    manager->log_file = fopen(logfile, "a");
    if (!manager->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    manager->log_count = 0;
    pthread_mutex_init(&manager->log_lock, NULL);
}

void add_network_event(NetworkManager *manager, int cell_id, const char *status) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count < MAX_EVENTS) {
        NetworkEvent event;
        event.cell_id = cell_id;
        event.timestamp = time(NULL);
        strncpy(event.status, status, sizeof(event.status));

        manager->events[manager->count++] = event;

        // Log the event
        pthread_mutex_lock(&manager->log_lock);
        snprintf(manager->log_buffer[manager->log_count], 256,
                 "Cell ID: %d, Timestamp: %ld, Status: %s\n",
                 cell_id, event.timestamp, status);

        if (++manager->log_count >= MAX_EVENTS) {
            for (size_t i = 0; i < manager->log_count; ++i) {
                fputs(manager->log_buffer[i], manager->log_file);
            }
            fflush(manager->log_file); // Ensure data is written to disk
            manager->log_count = 0;
        }
        pthread_mutex_unlock(&manager->log_lock);

    } else {
        printf("Event log full. Consider increasing MAX_EVENTS.\n");
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_network_manager(NetworkManager *manager) {
    free(manager->events);
    fclose(manager->log_file);
    pthread_mutex_destroy(&manager->lock);
    pthread_mutex_destroy(&manager->log_lock);
}

// Example usage
int main() {
    NetworkManager manager;
    init_network_manager(&manager, "network_log.txt");

    // Simulate adding events from multiple threads
    add_network_event(&manager, 1, "Link up");
    add_network_event(&manager, 2, "Throughput threshold exceeded");

    // Perform cleanup
    cleanup_network_manager(&manager);

    return 0;
}
```

This code sets up a thread-safe mechanism for managing network events using mutexes to prevent race conditions. It uses a buffer to log events and writes them in bulk to reduce the performance impact of frequent I/O operations. Adjust `MAX_EVENTS` as needed to balance between memory usage and logging frequency.']

