    if (!records) {
        *status_code = -2; // Memory allocation failed
        return NULL;
    }

    srand((unsigned int)time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = rand_range(key_min, key_max);
        records[i].score = (float)rand() / RAND_MAX;
        const char *statuses[] = {'A', 'B', 'C'};
        records[i].status = statuses[rand() % 3];
    }

    *allocated_size = num_records;
    *status_code = 0; // Success
    return records;
}

// Function to free allocated memory for records
void free_records(record *records) {
    if (records) {
        free(records);
    }
}
