#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <chrono>
#include <memory>
#include <atomic>
#include <iomanip>

// Transaction structure
struct Transaction {
    int value;
    std::chrono::time_point<std::chrono::system_clock> timestamp;

    Transaction(int val, std::chrono::time_point<std::chrono::system_clock> ts)
        : value(val), timestamp(ts) {}
};

class TransactionManager {
private:
    std::unordered_map<std::string, Transaction> transactions;
    std::vector<double> doubleArray;
    std::vector<std::string> stringKeys;
    std::mutex mtx;

public:
    // Allocate and initialize memory safely
    bool allocateMemory(size_t numDoubles, size_t numStrings) {
        try {
            doubleArray.reserve(numDoubles);
            for (size_t i = 0; i < numDoubles; ++i) {
                doubleArray.push_back(0.0);
            }

            stringKeys.reserve(numStrings);
            for (size_t i = 0; i < numStrings; ++i) {
                stringKeys.emplace_back("key" + std::to_string(i));
            }

            return true;
        } catch (const std::bad_alloc&) {
            logError("Memory allocation failed.");
            releaseResources();
            return false;
        }
    }

    // Release any allocated resources
    void releaseResources() {
        doubleArray.clear();
        stringKeys.clear();
        transactions.clear();
    }

    // Add transaction with thread safety
    void addTransaction(const std::string& key, int value) {
        auto timestamp = std::chrono::system_clock::now();

        std::lock_guard<std::mutex> lock(mtx);
        if (transactions.find(key) == transactions.end()) {
            transactions[key] = Transaction(value, timestamp);
            logOperation("Transaction added: " + key);
        } else {
            logWarning("Duplicate transaction for key: " + key);
        }
    }

    // Remove transaction with thread safety
    void removeTransaction(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        if (transactions.erase(key)) {
            logOperation("Transaction removed: " + key);
        } else {
            logWarning("Attempted to remove non-existent transaction for key: " + key);
        }
    }

    // Query a transaction with thread safety
    Transaction* queryTransaction(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = transactions.find(key);
        if (it != transactions.end()) {
            logOperation("Queried transaction: " + key);
            return &it->second;
        } else {
            logWarning("Transaction not found for key: " + key);
            return nullptr;
        }
    }

    // Logging functions
    void logOperation(const std::string& message) const {
        std::cout << "[" << getCurrentTime() << "] INFO: " << message << std::endl;
    }

    void logWarning(const std::string& message) const {
        std::cerr << "[" << getCurrentTime() << "] WARNING: " << message << std::endl;
    }

    void logError(const std::string& message) const {
        std::cerr << "[" << getCurrentTime() << "] ERROR: " << message << std::endl;
    }

    // Get the current time as a formatted string
    static std::string getCurrentTime() {
        auto now = std::chrono::system_clock::now();
        auto in_time_t = std::chrono::system_clock::to_time_t(now);
        std::stringstream ss;
        ss << std::put_time(std::localtime(&in_time_t), "%Y-%m-%d %X");
        return ss.str();
    }
};

int main() {
    TransactionManager manager;

    if (!manager.allocateMemory(1000, 500)) {
        return EXIT_FAILURE; // Exit if memory allocation fails
    }

    std::thread t1([&]() { manager.addTransaction("tx1", 100); });
    std::thread t2([&]() { manager.queryTransaction("tx1"); });
    std::thread t3([&]() { manager.removeTransaction("tx1"); });

    t1.join();
    t2.join();
    t3.join();

    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of the task requirements, utilizing C++ features like `std::mutex` for thread safety and logging operations to track execution. The memory allocation is handled with exception handling to manage potential failures gracefully.']

