#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        _Atomic unsigned char CRCFLAG; // Using atomic for lock-free read/write
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t cache_lock; // Fine-grained lock for LRU eviction
    size_t max_size;
    size_t current_size;
} Cache;

static pthread_rwlock_t array_rwlock = PTHREAD_RWLOCK_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *array[MAX_ELEMENTS];
static int element_count = 0;
static Cache cache = {NULL, PTHREAD_MUTEX_INITIALIZER, 10, 0};

// Utility functions
void log_message(const char* message) {
    fprintf(stderr, "%s\n", message);
}

void generate_random_crcflag() {
    srand(time(NULL));
    _Atomic unsigned char crc_flag = (unsigned char)(rand() % 256);
}

void init_cache(Cache *cache, size_t max_size) {
    cache->max_size = max_size;
    cache->current_size = 0;
    cache->head = NULL;
    pthread_mutex_init(&cache->cache_lock, NULL);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T& data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_message("Memory allocation failed for node");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void free_cache(Cache *cache) {
    Node* current = cache->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&cache->cache_lock);
}

// Cache eviction policy: LRU
NFAPI_CRC_INDICATION_PDU_T fetch_from_cache(Cache *cache, int index) {
    pthread_mutex_lock(&cache->cache_lock);

    Node** curr = &cache->head;
    while (*curr != NULL && (*curr)->data.RX_UE_INFORMATION_TAG != index) {
        curr = &(*curr)->next;
    }

    if (*curr == NULL) { // Not found
        pthread_mutex_unlock(&cache->cache_lock);
        return (NFAPI_CRC_INDICATION_PDU_T){0, 0, {.CRCFLAG = 0}};
    }

    NFAPI_CRC_INDICATION_PDU_T data = (*curr)->data;
    Node* temp = *curr;
    *curr = (*curr)->next;
    cache->current_size--;
    free(temp);

    pthread_mutex_unlock(&cache->cache_lock);
    return data;
}

void add_to_cache(Cache *cache, const NFAPI_CRC_INDICATION_PDU_T& data) {
    pthread_mutex_lock(&cache->cache_lock);

    if (cache->current_size >= cache->max_size) {
        Node* current = cache->head;
        cache->head = cache->head->next;
        free(current);
        cache->current_size--;
    }

    Node* new_node = create_node(data);
    if (!new_node) return;

    new_node->next = cache->head;
    cache->head = new_node;
    cache->current_size++;

    pthread_mutex_unlock(&cache->cache_lock);
}

// Core functions
NFAPI_CRC_INDICATION_PDU_T* allocate_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = fetch_from_cache(&cache, -1); // Fetch from cache
    if (pdu) return pdu;

    pthread_rwlock_wrlock(&array_rwlock);

    if (element_count >= MAX_ELEMENTS) {
        log_message("Maximum number of elements exceeded");
        pthread_rwlock_unlock(&array_rwlock);
        return NULL;
    }

    int index = element_count++;
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        log_message("Memory allocation failed for PDU");
        pthread_rwlock_unlock(&array_rwlock);
        return NULL;
    }

    new_pdu->RX_UE_INFORMATION_TAG = index; // Example tag
    new_pdu->RNTI = rand() % 1000;         // Example RNTI
    generate_random_crcflag();
    __atomic_store_n(&(new_pdu->CRC_INDICATION_REL8_TAG.CRCFLAG), (unsigned char)(rand() % 256), __ATOMIC_SEQ_CST);

    array[index] = new_pdu;

    pthread_rwlock_unlock(&array_rwlock);
    add_to_cache(&cache, *new_pdu); // Add to cache

    return new_pdu;
}

NFAPI_CRC_INDICATION_PDU_T* read_pdu(int index) {
    if (index < 0 || index >= MAX_ELEMENTS) {
        log_message("Invalid index for reading PDU");
        return NULL;
    }

    pthread_rwlock_rdlock(&array_rwlock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = array[index];
    pthread_rwlock_unlock(&array_rwlock);

    if (!pdu)
        pdu = &fetch_from_cache(&cache, index); // Try to fetch from cache

    return pdu;
}

void free_pdu(int index) {
    if (index < 0 || index >= MAX_ELEMENTS) {
        log_message("Invalid index for freeing PDU");
        return;
    }

    pthread_rwlock_wrlock(&array_rwlock);
    NFAPI_CRC_INDICATION_PDU_T* pdu = array[index];
    if (!pdu) {
        pthread_rwlock_unlock(&array_rwlock);
        return;
    }

    free(pdu);
    array[index] = NULL;

    pthread_rwlock_unlock(&array_rwlock);
}

void cleanup() {
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        if (array[i]) {
            free(array[i]);
        }
    }
    free_cache(&cache);
}

int main() {
    init_cache(&cache, cache.max_size);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu();
    if (pdu) {
        printf("Allocated PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
        free_pdu(pdu->RX_UE_INFORMATION_TAG);
    }

    cleanup();

    return 0;
}
```

### Key Concepts Implemented:
1. **Concurrency Management**: Use of `pthread_rwlock_t` for read-write locks to manage concurrent access.
2. **Memory Handling and Cache**: Simple LRU cache implemented with a linked list, ensuring memory efficiency by reusing previously freed elements.
3. **Error Logging**: Basic logging mechanism using `fprintf` to stderr for error messages.
4. **Random CRCFLAG Generation**: Using atomic operations for thread-safe random flag setting.
5. **Resilience and Fault Tolerance**: Checks for allocation failures and array bounds with appropriate logging.

