int validate_record(int value) {
    // Check if the value is within a specified range and divisible by 3
    return (value >= 10 && value <= 100 && value % 3 == 0);
}

void generate_random_int(int *value) {
    unsigned int min = RAND_MAX / 2 + 1;
    unsigned int max = RAND_MAX;
    if (min > max || max - min < 100) { // Check for overflow risk
        log_failure("Integer overflow detected in random generation.");
        exit(EXIT_FAILURE);
    }
    *value = rand() % (max - min + 1) + min;
}

