    int *allocated_keys = malloc(count * sizeof(int));
    record *allocated_records = malloc(count * sizeof(record));

    if (!allocated_offsets || !allocated_keys || !allocated_records) {
        log_failure("Memory allocation failed.");
        free(allocated_offsets);
        free(allocated_keys);
        free(allocated_records);
        return -1;
    }

    int max_retries = 1000; // Max retries to avoid excessive processing

    for (size_t i = 0; i < count; ++i) {
        offsets[i] = rand() % 10000; // Example offset value
        keys[i] = rand() % 1000;     // Example key value
        allocated_records[i].value = -1;

