            if (validate_record(allocated_records[i].value)) {
                for (size_t j = 0; j < i; ++j) {
                    if (allocated_records[j].value == allocated_records[i].value) {
                        allocated_records[i].value = -1;
                        break;
                    }
                }

                if (allocated_records[i].value != -1) {
                    log_success(i, allocated_records[i].value);
                    break;
