            } else {
                log_attempt(retries, 0); // Log failed attempt
            }
            retries++;
        }

        if (retries >= max_retries) {
            log_failure("Max retries reached for generating valid record.");
            free(allocated_offsets);
            free(allocated_keys);
            free(allocated_records);
            return -1;
        }
    }

    *offsets = allocated_offsets;
    *keys = allocated_keys;
    *records = allocated_records;

    return 0;
}

