    size_t count;
    int error_code; // 0 for success, non-zero for failure
    pthread_mutex_t lock;
    uint8_t max_crc_flag;
    uint8_t min_crc_flag;
} CRCArrayManager;

int allocate_and_initialize_array(CRCArrayManager *manager, size_t N) {
    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        return -1; // Error initializing mutex
    }

    manager->count = N;
    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!manager->array) {
        pthread_mutex_destroy(&manager->lock);
        return -2; // Memory allocation failed
    }

    srand((unsigned int)time(NULL)); // Seed for random number generation

    manager->max_crc_flag = 0;
    manager->min_crc_flag = UINT8_MAX;

    for (size_t i = 0; i < N; ++i) {
