        }
        if (crc_flag < manager->min_crc_flag) {
            manager->min_crc_flag = crc_flag;
        }
        pthread_mutex_unlock(&manager->lock);

        manager->array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crc_flag;
    }

    manager->error_code = 0; // Success
    return 0;
}

void free_array(CRCArrayManager *manager) {
