}

char* generate_random_content() {
    static char content[256];
    snprintf(content, sizeof(content), "RandomContent_%d", rand());
    return content;
}

void initialize_NAS_Message(NAS_Message *message) {
    message->message_type = generate_random_message_type();
    strncpy(message->content, generate_random_content(), sizeof(message->content));
}

int initialize_DL_CCCH_Messages(LTE_DL_CCCH_Message_Type1_T **messages, size_t max_num_messages) {
    if (max_num_messages == 0 || messages == NULL) return 0;

    *messages = malloc(INITIAL_ARRAY_SIZE * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (*messages == NULL) {
        log_error("Memory allocation failed");
        return 0;
    }

    size_t current_size = INITIAL_ARRAY_SIZE;
    int initialized_count = 0;

    for (size_t i = 0; i < max_num_messages && initialized_count < current_size; ++i) {
        (*messages)[initialized_count].encoder.sequence_number = rand(); // Unique sequence number
        initialize_NAS_Message(&(*messages)[initialized_count].nas_message);

        if (++initialized_count == current_size) { // Array overflow handling
            size_t new_size = (current_size < MAX_MESSAGES) ? current_size * 2 : MAX_MESSAGES;
            LTE_DL_CCCH_Message_Type1_T *new_array = realloc(*messages, new_size * sizeof(LTE_DL_CCCH_Message_Type1_T));
            if (new_array == NULL) {
                log_error("Memory reallocation failed");
                break; // Exit the loop on failure
            }
            *messages = new_array;
            current_size = new_size;
        }
    }

    return initialized_count;
}

void serialize_messages(const LTE_DL_CCCH_Message_Type1_T *messages, size_t num_messages, unsigned char **buffer, size_t *buffer_size) {
    if (num_messages == 0 || messages == NULL || buffer == NULL || buffer_size == NULL) return;

    *buffer_size = sizeof(TLVEncoder) + sizeof(NAS_Message) * num_messages;
    *buffer = malloc(*buffer_size);
    if (*buffer == NULL) {
        log_error("Buffer allocation failed");
        return;
    }

    unsigned char *ptr = *buffer;
    for (size_t i = 0; i < num_messages; ++i) {
        memcpy(ptr, &messages[i].encoder, sizeof(TLVEncoder));
        ptr += sizeof(TLVEncoder);
        memcpy(ptr, &messages[i].nas_message, sizeof(NAS_Message));
        ptr += sizeof(NAS_Message);
    }
}

int deserialize_messages(const unsigned char *buffer, size_t buffer_size, LTE_DL_CCCH_Message_Type1_T **messages, size_t *num_messages) {
    if (buffer == NULL || messages == NULL || num_messages == NULL) return 0;

    size_t estimated_num_messages = buffer_size / (sizeof(TLVEncoder) + sizeof(NAS_Message));
    *messages = malloc(estimated_num_messages * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (*messages == NULL) {
        log_error("Memory allocation failed");
        return 0;
    }

    unsigned char *ptr = (unsigned char *)buffer;
    for (size_t i = 0; i < estimated_num_messages; ++i) {
        memcpy(&(*messages)[i].encoder, ptr, sizeof(TLVEncoder));
        ptr += sizeof(TLVEncoder);
        memcpy(&(*messages)[i].nas_message, ptr, sizeof(NAS_Message));
        ptr += sizeof(NAS_Message);

        if (ptr - buffer > buffer_size) { // Validation check for data corruption
            log_error("Data corruption detected during deserialization");
            free(*messages);
            return 0;
        }
    }

    *num_messages = estimated_num_messages;
    return 1;
}

void free_resources(LTE_DL_CCCH_Message_Type1_T *messages, unsigned char *buffer) {
    if (messages != NULL) free(messages);
    if (buffer != NULL) free(buffer);
}
