        if (!ctx) {
            fprintf(stderr, "Error creating cipher context\n");
            exit(EXIT_FAILURE);
        }

        int encrypt_ok = EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
        if (!encrypt_ok) {
            fprintf(stderr, "Encryption initialization failed\n");
            EVP_CIPHER_CTX_free(ctx);
            exit(EXIT_FAILURE);
        }

        // Dummy data for encryption demonstration (replace these with real data)
