typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG; // Randomly set to 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RNTI_LIMIT 65535

pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;

// Mock external API for RNTI management
int allocate_rnti(uint16_t *rnti) {
    // Simulate allocation logic, returning 0 on success or -1 if exhausted
    static uint16_t allocated_rntis[MAX_RNTI_LIMIT] = {0};
    static int next_rnti = 100;

    pthread_mutex_lock(&rnti_lock);
    for (int i = next_rnti; i < MAX_RNTI_LIMIT; ++i) {
        if (!allocated_rntis[i]) {
            *rnti = i;
            allocated_rntis[i] = 1;
            next_rnti = i + 1;
            pthread_mutex_unlock(&rnti_lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&rnti_lock);
    return -1; // No RNTI available
}

// Function to create and populate NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_list(int n, int seed, uint16_t max_rnti_limit) {
    if (n <= 0 || max_rnti_limit > MAX_RNTI_LIMIT) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    srand(seed);

    int rnti_count = 0;
    uint16_t allocated_rntis[n] = {0};
    time_t start_time = time(NULL);

    for (int i = 0; i < n; ++i) {
        // Randomly set CRCFLAG
        list[i].CRCFLAG = rand() % 2;

        // Allocate a unique RNTI
        int allocated = 0;
        while (!allocated && rnti_count < max_rnti_limit) {
            uint16_t rnti;
            if (allocate_rnti(&rnti) == 0) {
                for (int j = 0; j < i; ++j) {
                    if (allocated_rntis[j] == rnti) break;
                    if (j == i - 1) {
                        list[i].RNTI = rnti;
                        allocated_rntis[rnti_count++] = rnti;
                        allocated = 1;
                        printf("[%ld] Allocated RNTI %d for element %d\n", time(NULL), rnti, i);
                    }
                }
            } else {
                // Fallback: allocate temporary RNTI
                uint16_t temp_rnti = (rand() % max_rnti_limit) + 1;
                printf("[%ld] Allocating temporary RNTI %d for element %d\n", time(NULL), temp_rnti, i);
                list[i].RNTI = temp_rnti; // Assign a random temporary RNTI
                allocated_rntis[rnti_count++] = temp_rnti;
                allocated = 1;
            }
        }

        if (!allocated) {
            printf("[%ld] Failed to allocate RNTI for element %d\n", time(NULL), i);
            break; // Exhausted RNTI pool
        }

        list[i].RX_UE_INFORMATION_TAG = rand(); // Simulate generating a tag
        list[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    printf("[%ld] Finished creating NFAPI_CRC_INDICATION_PDU_T list with %d elements\n", time(NULL), rnti_count);
    return list;
}

// Main function for demonstration purposes
int main() {
    int n = 100; // Number of elements to create
    int seed = 42; // Seed for RNG
    uint16_t max_rnti_limit = 200; // Max RNTI allocation limit

    NFAPI_CRC_INDICATION_PDU_T *list = create_nfa_crc_list(n, seed, max_rnti_limit);

    if (list) {
        printf("Created list of %d elements.\n", n);

        for (int i = 0; i < n && list[i].RNTI != 0; ++i) {
            printf("Element %d: RNTI=%d, CRCFLAG=%d\n", i, list[i].RNTI, list[i].CRCFLAG);
        }

        free(list); // Free allocated memory
    } else {
        printf("Failed to create the NFAPI_CRC_INDICATION_PDU_T list.\n");
    }

    return 0;
}
