['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Measurement {
    double latency;
    double throughput;
    int packet_loss;
} Measurement;

typedef struct NetworkPerformanceMetrics {
    time_t timestamp;
    char session_id[64];
    Measurement measurements;
    struct NetworkPerformanceMetrics* prev;
    struct NetworkPerformanceMetrics* next;
} NetworkPerformanceMetrics;

typedef struct {
    NetworkPerformanceMetrics* head;
    NetworkPerformanceMetrics* tail;
    size_t count;
    pthread_mutex_t lock;
    time_t retention_period; // 7 days in seconds
} MetricsList;

// Initialize the doubly linked list
void init_metrics_list(MetricsList* list, time_t retention_days) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->retention_period = retention_days * 24 * 60 * 60; // Convert days to seconds
}

// Add a new metric to the list
void add_metric(MetricsList* list, const char* session_id, double latency, double throughput, int packet_loss) {
    NetworkPerformanceMetrics* new_node = (NetworkPerformanceMetrics*)malloc(sizeof(NetworkPerformanceMetrics));
    if (!new_node) {
        perror("Failed to allocate memory");
        return;
    }

    time_t current_time = time(NULL);
    new_node->timestamp = current_time;
    strncpy(new_node->session_id, session_id, sizeof(new_node->session_id) - 1);
    new_node->measurements.latency = latency;
    new_node->measurements.throughput = throughput;
    new_node->measurements.packet_loss = packet_loss;

    pthread_mutex_lock(&list->lock);

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        list->head = new_node;
        list->tail = new_node;
        new_node->prev = NULL;
        new_node->next = NULL;
    }
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

// Periodically clean up outdated metrics
void cleanup_metrics(MetricsList* list) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics *current = list->head, *to_delete;

    while (current) {
        if ((current_time - current->timestamp) > list->retention_period) {
            to_delete = current;
            current = current->next;

            if (to_delete->prev)
                to_delete->prev->next = to_delete->next;
            else
                list->head = to_delete->next;

            if (to_delete->next)
                to_delete->next->prev = to_delete->prev;
            else
                list->tail = to_delete->prev;

            free(to_delete);
            list->count--;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Log an operation (simplified)
void log_operation(const char* message) {
    // Implement logging logic here
    printf("%s\n", message);  // For demonstration purposes
}

// Cleanup and destroy the list
void destroy_metrics_list(MetricsList* list) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics *current = list->head, *next;

    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    MetricsList metrics_list;
    init_metrics_list(&metrics_list, 7); // Retention period of 7 days

    add_metric(&metrics_list, "session_1", 50.0, 100.0, 5);
    cleanup_metrics(&metrics_list);

    destroy_metrics_list(&metrics_list);
    return 0;
}
