import threading

typedef struct Entry {
    long timestamp;
    int status_code;
    char* message;
    struct Entry* next;
} Entry;

Entry* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Fetch initial entries from an external data source
void fetch_initial_entries() {
    // Simulated network call to fetch initial entries
    printf("Fetching initial entries...\n");
    // Handle potential network failures gracefully
}

// Add a new entry
void add_entry(long timestamp, int status_code, const char* message) {
    pthread_mutex_lock(&mutex);

    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    if (!new_entry) return;

    new_entry->timestamp = timestamp;
    new_entry->status_code = status_code;
    new_entry->message = strdup(message);
    new_entry->next = head;
    head = new_entry;

    pthread_mutex_unlock(&mutex);
}

// Remove an entry by timestamp
void remove_entry_by_timestamp(long timestamp) {
    pthread_mutex_lock(&mutex);

    Entry *current = head, *prev = NULL;

    while (current != NULL && current->timestamp != timestamp) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->message);
    free(current);

    pthread_mutex_unlock(&mutex);
}

// Retrieve the most recent entry
Entry* get_most_recent_entry() {
    pthread_mutex_lock(&mutex);

    Entry *current = head, *most_recent = NULL;

    while (current != NULL) {
        if (!most_recent || current->timestamp > most_recent->timestamp) {
            most_recent = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&mutex);

    return most_recent;
}

// Serialize the list to disk
void serialize_to_disk(const char* filename) {
    pthread_mutex_lock(&mutex);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        pthread_mutex_unlock(&mutex);
        return;
    }

    Entry* current = head;

    while (current != NULL) {
        fwrite(current, sizeof(Entry), 1, file);

        // Manually serialize the message pointer as a string
        size_t len = strlen(current->message) + 1;
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(current->message, sizeof(char), len, file);

        current = current->next;
    }

    fclose(file);

    pthread_mutex_unlock(&mutex);
}

// Deserialize the list from disk
void deserialize_from_disk(const char* filename) {
    pthread_mutex_lock(&mutex);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Free current list
    Entry* current = head;
    while (current != NULL) {
        Entry* next = current->next;
        free(current->message);
        free(current);
        current = next;
    }
    head = NULL;

    Entry buffer_entry;
    size_t len;

    while (fread(&buffer_entry, sizeof(Entry), 1, file)) {
        buffer_entry.message = (char*)malloc(len + 1);
        fread(&len, sizeof(size_t), 1, file);
        fread(buffer_entry.message, sizeof(char), len, file);

        Entry* new_entry = (Entry*)malloc(sizeof(Entry));
        *new_entry = buffer_entry;
        new_entry->next = head;
        head = new_entry;
    }

    fclose(file);
    pthread_mutex_unlock(&mutex);
}

int main() {
    fetch_initial_entries();

    // Example usage
    add_entry(1627849200, 200, "Initial entry");
    Entry* most_recent = get_most_recent_entry();
    if (most_recent) {
        printf("Most recent entry: %s\n", most_recent->message);
    }

    serialize_to_disk("entries.dat");

    // Simulate restart
    deserialize_from_disk("entries.dat");

    return 0;
}
