#include <hiredis/hiredis.h>

#define MAX_INPUT_LENGTH 1024

void compute_md5_hash_and_cache(const char *input, redisContext *redis);
void log_error(const char *message);
int find_largest_integer(const char **inputs, int count);

void process_strings() {
    const char *inputs[10000000];
    int input_count = 0;
    char buffer[MAX_INPUT_LENGTH + 1];

    while (fgets(buffer, sizeof(buffer), stdin)) {
        if (strlen(buffer) > MAX_INPUT_LENGTH || strchr(buffer, '\n')) {
            log_error("Invalid input length or newline found");
            continue;
        }

        inputs[input_count++] = strdup(buffer);
    }

    redisContext *redis = redisConnect("127.0.0.1", 6379);
    if (redis->err) {
        log_error(redis->errstr);
        return;
    }

    for (int i = 0; i < input_count; ++i) {
        compute_md5_hash_and_cache(inputs[i], redis);
    }

    printf("Largest integer: %d\n", find_largest_integer((const char **)inputs, input_count));

    for (int i = 0; i < input_count; ++i) {
        free((void *)inputs[i]);
    }

    redisFree(redis);
}

void compute_md5_hash_and_cache(const char *input, redisContext *redis) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)input, strlen(input), hash);

    char hex_output[33];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(hex_output + (i * 2), "%02x", hash[i]);
    }

    redisReply *reply;
    reply = (redisReply *)redisCommand(redis, "SET %s %b EX 3600", input, hex_output, strlen(hex_output));
    if (!reply || reply->type == REDIS_REPLY_ERROR) {
        log_error("Redis error: Unable to set key");
        freeReplyObject(reply);
        return;
    }

    freeReplyObject(reply);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int find_largest_integer(const char **inputs, int count) {
    int largest = INT_MIN;

    for (int i = 0; i < count; ++i) {
        char *endptr;
        long value = strtol(inputs[i], &endptr, 10);

        if (*endptr == '\0' && value > largest) {
            largest = (int)value;
        }
    }

    return largest;
}
