```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t count;
    pthread_mutex_t lock;
} DataStructure;

int is_unique(int key, const DataStructure* ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        if (ds->keys[i] == key)
            return 0;
    }
    return 1;
}

void initialize_data_structure(DataStructure *ds, size_t initial_size) {
    pthread_mutex_init(&ds->lock, NULL);
    ds->offsets = calloc(initial_size, sizeof(long));
    ds->keys = calloc(initial_size, sizeof(int));
    ds->records = malloc(initial_size * sizeof(record));
    if (!ds->offsets || !ds->keys || !ds->records) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    ds->count = 0;
}

void resize_data_structure(DataStructure *ds, size_t new_size) {
    pthread_mutex_lock(&ds->lock);

    long *new_offsets = realloc(ds->offsets, new_size * sizeof(long));
    int *new_keys = realloc(ds->keys, new_size * sizeof(int));
    record *new_records = realloc(ds->records, new_size * sizeof(record));

    if (!new_offsets || !new_keys || !new_records) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;

    pthread_mutex_unlock(&ds->lock);
}

int add_record(DataStructure *ds, int key, record rec) {
    if (key < 0 || !is_unique(key, ds)) return -1;

    pthread_mutex_lock(&ds->lock);

    if (ds->count >= MAX_ELEMENTS) {
        resize_data_structure(ds, ds->count * 2);
    }

    ds->offsets[ds->count] = rand();
    ds->keys[ds->count] = key;
    ds->records[ds->count++] = rec;

    pthread_mutex_unlock(&ds->lock);

    return 0;
}

void free_data_structure(DataStructure *ds) {
    pthread_mutex_lock(&ds->lock);

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);

    pthread_mutex_unlock(&ds->lock);
    pthread_mutex_destroy(&ds->lock);
}

record generate_random_record(int min, int max) {
    record rec;
    if (min >= max) {
        fprintf(stderr, "Invalid range for random number generation.\n");
        exit(EXIT_FAILURE);
    }
    rec.value = rand() % (max - min + 1) + min;
    return rec;
}

int main() {
    srand(time(NULL));

    DataStructure ds;
    initialize_data_structure(&ds, 10);

    // Example usage
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        record new_rec = generate_random_record(1, 100);
        if (add_record(&ds, rand() % 200, new_rec) != 0) {
            fprintf(stderr, "Failed to add record.\n");
        }
    }

    free_data_structure(&ds);

    return 0;
}
```

### Key Points:
- **Concurrency**: A mutex is used for thread-safe operations on the data structure.
- **Memory Management**: Memory allocation and resizing are handled safely with checks for failures.
- **Uniqueness Check**: Ensures no duplicate keys are added to the data structure.
- **Dynamic Resizing**: The array can be resized dynamically as needed, doubling its size when full.
- **Fault Tolerance & Recovery**: Graceful handling of memory allocation failures.
- **Randomization**: Records have randomly generated values within a specified range.

This example covers basic requirements but should be extended with additional error checking, logging, and monitoring for production environments.']

