void initialize_arrays(long offset[], int keys[], record_t records[], size_t num_records, long offset_range_start, long offset_range_end, int key_range_start, int key_range_end) {
    for (size_t i = 0; i < num_records; ++i) {
        offset[i] = rand() % (offset_range_end - offset_range_start + 1) + offset_range_start;
        keys[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        records[i].value = rand() % 100; // Example range for random value
    }
}

crypto_library_t* initialize_crypto_library(size_t initial_count) {
    crypto_library_t *library = malloc(sizeof(crypto_library_t));
    if (!library) return NULL;

    library->active_algorithms = calloc(initial_count, sizeof(crypto_algorithm));
    if (!library->active_algorithms) {
        free(library);
        return NULL;
    }

    library->count = initial_count;
    pthread_mutex_init(&library->lock, NULL);

    log_message("Crypto library initialized.");
    return library;
}

void add_crypto_algorithm(crypto_library_t *library, crypto_algorithm algorithm) {
    pthread_mutex_lock(&library->lock);

    if (library->count >= MAX_ALGORITHMS) {
        log_message("Error: Maximum number of algorithms reached.");
        pthread_mutex_unlock(&library->lock);
        return;
    }

    library->active_algorithms[library->count++] = algorithm;
    log_message("Algorithm added.");

    pthread_mutex_unlock(&library->lock);
}

void remove_crypto_algorithm(crypto_library_t *library, crypto_algorithm algorithm) {
    pthread_mutex_lock(&library->lock);

    for (size_t i = 0; i < library->count; ++i) {
        if (library->active_algorithms[i] == algorithm) {
            memmove(&library->active_algorithms[i], &library->active_algorithms[i + 1], (library->count - i - 1) * sizeof(crypto_algorithm));
            --library->count;
            log_message("Algorithm removed.");
            break;
        }
    }

    pthread_mutex_unlock(&library->lock);
}

void free_crypto_library(crypto_library_t *library) {
    if (!library) return;

    free(library->active_algorithms);
    pthread_mutex_destroy(&library->lock);
    free(library);
    log_message("Crypto library freed.");
}

