        printf("Warning: Filename truncated due to length.\n");
        strncpy(new_name, original, MAX_ORIGINAL_LENGTH);
        new_name[MAX_ORIGINAL_LENGTH] = '\0';
    } else {
        strcpy(new_name, original);
    }

    int vowel_count = 0;
    for (const char *p = original; *p; ++p) {
        if (is_vowel(*p)) ++vowel_count;
    }

    int sequence_length = vowel_count ? vowel_count : 1;
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", time_info);

    snprintf(new_name + strlen(new_name) - (strlen(original) > MAX_FILENAME_LENGTH ? strlen(original) : 3),
             MAX_FILENAME_LENGTH - strlen(new_name) + 1,
             "_%d_%s",
             rand() % (int)(pow(10, sequence_length)) / (int)(pow(10, sequence_length - 1)),
             timestamp);

    // Simulate metadata retrieval
    log_message("Metadata retrieved.");

