        Logger::log("ERROR: " + error_message);
    }

    template <typename T>
    static T* safe_alloc(size_t size) {
        try {
            return new T[size];
        } catch (const std::bad_alloc&) {
            handle_error("Memory allocation failed");
            return nullptr;
        }
    }

    static void safe_delete(T*& ptr) {
        delete[] ptr;
        ptr = nullptr;
    }
};

namespace MemoryManager {

    constexpr int MAX_SAMPLES = 1000;

    struct Record {
        int value;
    };

    struct LinkLayerStats {
        double SNR;
    };

    struct PHY_STATS_PDU_T {
        int TX_POWER_LEVELS;
        int RECEIVED_SIGNAL_STRENGTH;
        LinkLayerStats LINK_LAYER_STATS;
    };

    class DataManager {
    public:
        static std::mt19937 rng;

        DataManager(size_t array_size)
            : keys_array(nullptr), records_array(nullptr),
              phy_stats_array(nullptr) {

            init_rng();
            allocate_arrays(array_size);
            initialize_unique_values(array_size);

            Logger::log("DataManager initialized successfully.");
        }

        ~DataManager() {
            deallocate_arrays();
        }

        void dynamic_resize(size_t new_size) {
            std::lock_guard<std::mutex> lock(data_mutex);
            if (new_size > array_size && new_size <= MAX_SAMPLES) {
                allocate_arrays(new_size);
                initialize_unique_values(array_size, new_size);
                Logger::log("Resized DataManager arrays to " + std::to_string(new_size));
            } else {
                ErrorHandler::handle_error("Resize failed: Invalid size or exceeded maximum limit.");
            }
        }

    private:
        int* keys_array;
        Record* records_array;
        PHY_STATS_PDU_T* phy_stats_array;

        std::mutex data_mutex;
        size_t array_size = 0;

        static void init_rng() {
            rng.seed(std::random_device{}());
        }

        void allocate_arrays(size_t new_size) {
            std::lock_guard<std::mutex> lock(data_mutex);

            ErrorHandler::safe_delete(keys_array);
            ErrorHandler::safe_delete(records_array);
            ErrorHandler::safe_delete(phy_stats_array);

            keys_array = ErrorHandler::safe_alloc<int>(new_size);
            records_array = ErrorHandler::safe_alloc<Record>(new_size);
            phy_stats_array = ErrorHandler::safe_alloc<PHY_STATS_PDU_T>(MAX_SAMPLES);

            if (!keys_array || !records_array || !phy_stats_array) {
                array_size = 0;
                throw std::runtime_error("Allocation failed during resize.");
            }

            array_size = new_size;

            for (size_t i = 0; i < MAX_SAMPLES; ++i) {
                phy_stats_array[i].LINK_LAYER_STATS.SNR = generate_random_snr();
            }
        }

        void initialize_unique_values(size_t start_index, size_t end_index = 0) {
            std::uniform_int_distribution<int> dist(1, 100000);

            for (size_t i = start_index; i < (end_index ? end_index : array_size); ++i) {
                int value;
                do {
                    value = dist(rng);
                } while (std::find(keys_array, keys_array + i, value) != keys_array + i);

                keys_array[i] = value;
                records_array[i].value = value;

                Logger::log("Initialized unique values for index " + std::to_string(i));
            }
        }

        double generate_random_snr() {
            std::normal_distribution<double> snr_dist(0.0, 10.0);
            return snr_dist(rng);
        }

        void deallocate_arrays() {
            ErrorHandler::safe_delete(keys_array);
            ErrorHandler::safe_delete(records_array);
            ErrorHandler::safe_delete(phy_stats_array);

            Logger::log("Deallocated all arrays.");
        }
    };

    std::mt19937 DataManager::rng;
}

int main() {
    try {
        size_t initial_size = 500;

        MemoryManager::DataManager manager(initial_size);

        // Simulate dynamic resizing
        std::thread resize_thread([&manager]() {
            size_t new_size = 750;
            manager.dynamic_resize(new_size);
        });

        resize_thread.join();

        // Further operations can be added here...

    } catch (const std::exception& e) {
        Logger::log(std::string("Exception: ") + e.what());
    }

    return 0;
}
