int validate_metadata_uniqueness(char **metadata, int count) {
    for (int i = 0; i < count; ++i) {
        for (int j = i + 1; j < count; ++j) {
            if (strcmp(metadata[i], metadata[j]) == 0) {
                return 0;
            }
        }
    }
    return 1;
}

void generate_random_values(int *keys, int num_records, double *probability_distribution, int value_range) {
    int unique_values[num_records];
    for (int i = 0; i < num_records; ++i) {
        unique_values[i] = -1;
    }

    int generated_count = 0;
    while (generated_count < num_records) {
        double rand_prob = ((double)rand() / RAND_MAX);
        int cumulative_prob = 0;
        for (int i = 0; i < value_range && cumulative_prob <= rand_prob; ++i) {
            cumulative_prob += probability_distribution[i];
            if (cumulative_prob > rand_prob) {
                int value = i + 1;
                int is_unique = 1;
                for (int j = 0; j < generated_count; ++j) {
                    if (unique_values[j] == value) {
                        is_unique = 0;
                        break;
                    }
                }
                if (is_unique) {
                    unique_values[generated_count++] = value;
                    keys[i] = value;
                    sprintf(keys[i], "%d", value);
                }
                break;
            }
        }
    }
}

void initialize_arrays(long **offsets, int **keys, record **records, char ***metadata_strings, int num_records, double *probability_distribution, int value_range) {
    // Allocate memory
    *offsets = (long *)malloc(num_records * sizeof(long));
    if (*offsets == NULL) { perror("Failed to allocate offsets"); exit(EXIT_FAILURE); }

    *keys = (int *)malloc(num_records * sizeof(int));
    if (*keys == NULL) { perror("Failed to allocate keys"); free(*offsets); exit(EXIT_FAILURE); }

    *records = (record *)malloc(num_records * sizeof(record));
    if (*records == NULL) { perror("Failed to allocate records"); free(*offsets); free(*keys); exit(EXIT_FAILURE); }

    *metadata_strings = (char **)malloc(num_records * sizeof(char *));
    if (*metadata_strings == NULL) { perror("Failed to allocate metadata strings"); free(*offsets); free(*keys); free(*records); exit(EXIT_FAILURE); }

    // Predefined set of keywords for metadata
    const char *keywords[] = {"Alpha", "Beta", "Gamma", "Delta", "Epsilon"};
    int num_keywords = sizeof(keywords) / sizeof(keywords[0]);

    if (num_records > num_keywords) {
        fprintf(stderr, "Not enough unique metadata strings available.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize metadata strings ensuring uniqueness
    for (int i = 0; i < num_records; ++i) {
        (*metadata_strings)[i] = strdup(keywords[i]);
        if ((*metadata_strings)[i] == NULL) { perror("Failed to duplicate metadata string"); exit(EXIT_FAILURE); }
    }

    // Validate uniqueness of metadata strings
    if (!validate_metadata_uniqueness(*metadata_strings, num_records)) {
        fprintf(stderr, "Metadata strings are not unique.\n");
        exit(EXIT_FAILURE);
    }

    // Generate random keys and initialize records
    generate_random_values(*keys, num_records, probability_distribution, value_range);

    time_t last_timestamp = 0;
    for (int i = 0; i < num_records; ++i) {
        (*records)[i].value = *keys[i];
        snprintf((*records)[i].string, sizeof((*records)[i].string), "%d", (*records)[i].value);
        (*records)[i].timestamp = time(NULL);

        if ((*records)[i].timestamp <= last_timestamp) {
            fprintf(stderr, "Timestamps are not monotonically increasing.\n");
            exit(EXIT_FAILURE);
        }
        last_timestamp = (*records)[i].timestamp;

        (*records)[i].metadata = (*metadata_strings)[i];
        async_log((char *)malloc(256));
        sprintf(async_log_buffer, "Record created with value: %d, timestamp: %ld", (*records)[i].value, (*records)[i].timestamp);
    }
}

void free_resources(long *offsets, int *keys, record *records, char **metadata_strings, int num_records) {
    free(offsets);
    free(keys);
    for (int i = 0; i < num_records; ++i) {
        free(records[i].metadata);
        free(metadata_strings[i]);
    }
    free(records);
    free(metadata_strings);
}

int main() {
    srand(time(NULL));

    int num_records = 5;
    double probability_distribution[10] = {0.1, 0.2, 0.3, 0.4}; // Example distribution
    long *offsets;
    int *keys;
    record *records;
    char **metadata_strings;

    initialize_arrays(&offsets, &keys, &records, &metadata_strings, num_records, probability_distribution, 10);

    // Use the arrays...

    free_resources(offsets, keys, records, metadata_strings, num_records);
    return 0;
}
