int initialize_and_populate_ccch_messages(LTE_DL_CCCH_Message_Type1_T** messages, int* num_messages) {
    if (messages == NULL || num_messages == NULL) return -1;

    *num_messages = 0;
    *messages = malloc(MAX_MESSAGES * sizeof(LTE_DL_CCCH_Message_Type1_T));

    if (*messages == NULL) {
        log_error("Failed to allocate memory for messages");
        return -1;
    }

    pthread_mutex_lock(&lock);

    int message_limit = MAX_MESSAGES; // Dynamic adjustment can be added here
    int supported_types_count = 0;
    SupportedMessageType* supported_types = get_supported_message_types_from_registry(&supported_types_count);

    if (supported_types == NULL) {
        log_error("Failed to fetch supported message types from remote registry");
        pthread_mutex_unlock(&lock);
        free(*messages);
        return -1;
    }

    for (int i = 0; i < message_limit && *num_messages < MAX_MESSAGES; ++i) {
        LTE_DL_CCCH_Message_Type1_T* msg = &((*messages)[*num_messages]);

        int rand_type_index = rand() % supported_types_count;
        SupportedMessageType rand_type = supported_types[rand_type_index];

        if (!tlv_encoder_init(&msg->encoder, rand_type.max_size)) {
            log_error("Failed to initialize TLVEncoder");
            pthread_mutex_unlock(&lock);
            free(*messages);
            return -1;
        }

        msg->message.type = rand_type.message_type;
        // Populate message content
        if (!populate_nas_message(&msg->message, rand_type.max_size)) {
            log_error("Failed to populate NAS Message");
            tlv_encoder_free(&msg->encoder);
            pthread_mutex_unlock(&lock);
            free(*messages);
            return -1;
        }

        (*num_messages)++;
    }

    free(supported_types);

    pthread_mutex_unlock(&lock);
    return 0;
}

void cleanup_ccch_messages(LTE_DL_CCCH_Message_Type1_T* messages, int num_messages) {
    if (messages == NULL) return;

    for (int i = 0; i < num_messages; ++i) {
        tlv_encoder_free(&messages[i].encoder);
    }

    free(messages);
}

