#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_TASKS 1000

typedef enum {
    ARRAY_OF_LONGS,
    MAP_OF_STRINGS,
    GRAPH_NODE
} DataStructureType;

typedef struct {
    long *array;
    size_t length;
} ArrayOfLongs;

typedef struct {
    char **map;
    size_t count;
} MapOfStrings;

typedef struct {
    int node_id;
    // Define graph structure specifics here
} GraphNode;

typedef union {
    ArrayOfLongs array_of_longs;
    MapOfStrings map_of_strings;
    GraphNode graph_node;
} DataStructure;

typedef struct Task {
    int task_id;
    int priority_level;
    DataStructureType type;
    DataStructure data;
    struct Task *next;
} Task;

typedef struct {
    Task *head;
    Task *tail;
    pthread_mutex_t lock;
    size_t task_count;
} TaskQueue;

TaskQueue* create_task_queue() {
    TaskQueue *queue = (TaskQueue*)malloc(sizeof(TaskQueue));
    if (!queue) return NULL;

    queue->head = queue->tail = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    queue->task_count = 0;

    return queue;
}

void destroy_task_queue(TaskQueue *queue) {
    Task *current = queue->head;
    while (current != NULL) {
        Task *temp = current;
        current = current->next;

        switch(temp->type) {
            case ARRAY_OF_LONGS:
                free(temp->data.array_of_longs.array);
                break;
            case MAP_OF_STRINGS:
                for(size_t i = 0; i < temp->data.map_of_strings.count; ++i) {
                    free(temp->data.map_of_strings.map[i]);
                }
                free(temp->data.map_of_strings.map);
                break;
            case GRAPH_NODE:
                // Free GraphNode specific memory if needed
                break;
        }

        free(temp);
    }

    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

int add_task(TaskQueue *queue, int task_id, int priority_level, DataStructureType type) {
    pthread_mutex_lock(&queue->lock);

    if (queue->task_count >= MAX_TASKS) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue full
    }

    Task **tracer = &queue->head;
    while (*tracer != NULL && ((*tracer)->task_id < task_id)) {
        tracer = &(*tracer)->next;
    }

    if (*tracer != NULL && (*tracer)->task_id == task_id) {
        pthread_mutex_unlock(&queue->lock);
        return -2; // Duplicate Task_ID
    }

    Task *new_task = (Task*)malloc(sizeof(Task));
    if (!new_task) {
        pthread_mutex_unlock(&queue->lock);
        return -3; // Memory allocation failed
    }

    new_task->task_id = task_id;
    new_task->priority_level = priority_level;
    new_task->type = type;

    switch (type) {
        case ARRAY_OF_LONGS:
            new_task->data.array_of_longs.array = (long*)malloc(sizeof(long) * 10); // Example size
            if (!new_task->data.array_of_longs.array) {
                free(new_task);
                pthread_mutex_unlock(&queue->lock);
                return -3;
            }
            break;
        case MAP_OF_STRINGS:
            new_task->data.map_of_strings.count = 5; // Example count
            new_task->data.map_of_strings.map = (char**)malloc(sizeof(char*) * new_task->data.map_of_strings.count);
            if (!new_task->data.map_of_strings.map) {
                free(new_task);
                pthread_mutex_unlock(&queue->lock);
                return -3;
            }
            for (size_t i = 0; i < new_task->data.map_of_strings.count; ++i) {
                new_task->data.map_of_strings.map[i] = strdup("example_string");
                if (!new_task->data.map_of_strings.map[i]) {
                    // Free already allocated strings
                    while (--i >= 0) free(new_task->data.map_of_strings.map[i]);
                    free(new_task->data.map_of_strings.map);
                    free(new_task);
                    pthread_mutex_unlock(&queue->lock);
                    return -3;
                }
            }
            break;
        case GRAPH_NODE:
            new_task->data.graph_node.node_id = task_id; // Example initialization
            break;
    }

    new_task->next = *tracer;
    if (*tracer == NULL) {
        queue->tail = new_task;
    }
    *tracer = new_task;

    ++queue->task_count;

    pthread_mutex_unlock(&queue->lock);

    return 0; // Success
}

void print_queue(TaskQueue *queue) {
    pthread_mutex_lock(&queue->lock);

    Task *current = queue->head;
    while (current != NULL) {
        printf("Task ID: %d, Priority Level: %d\n", current->task_id, current->priority_level);
        current = current->next;
    }

    pthread_mutex_unlock(&queue->lock);
}

int main() {
    TaskQueue *queue = create_task_queue();
    if (!queue) {
        fprintf(stderr, "Failed to create task queue.\n");
        return EXIT_FAILURE;
    }

    add_task(queue, 1, 10, ARRAY_OF_LONGS);
    add_task(queue, 2, 20, MAP_OF_STRINGS);

    print_queue(queue);

    destroy_task_queue(queue);

    return EXIT_SUCCESS;
}
