char* compress_data(const char* data, size_t original_size, size_t *compressed_size) {
    uLongf dest_size = compressBound(original_size);
    void *buffer = malloc(dest_size);

    if (compress(buffer, &dest_size, (const Bytef*)data, original_size) != Z_OK) {
        free(buffer);
        return NULL;
    }

    char* compressed_data = malloc(dest_size + 1);
    memcpy(compressed_data, buffer, dest_size);
