    while (1) {
        sem_wait(&manager->semaphore);

        pthread_mutex_lock(&manager->mutex);
        if (manager->count < manager->capacity && manager->active_threads < ENCODING_THRESHOLD) {
            size_t idx = manager->count++;
            LTE_DL_CCCH_Message_Type1_T *message = &manager->messages[idx];

            // Generate random message type and content
            srand(time(NULL) ^ pthread_self());
            message->nas_message.message_type = rand() % 100;
            snprintf(message->nas_message.content, sizeof(message->nas_message.content), "Random content #%d", rand());

            encode_message(message);

            manager->active_threads++;
        }
        pthread_mutex_unlock(&manager->mutex);

        if (manager->count >= manager->capacity) {
            break; // Stop thread if capacity is reached
        }

        sem_post(&manager->semaphore);
    }

    return NULL;
}

void initAndEncodeMessages() {
    MessageManager manager;
    manager.capacity = INITIAL_CAPACITY;
    manager.count = 0;
    manager.active_threads = 0;

    pthread_mutex_init(&manager.mutex, NULL);
    sem_init(&manager.semaphore, 0, ENCODING_THRESHOLD);

    // Initialize logger
    if (!logger_init(&manager.log)) {
        perror("Logger initialization failed");
        return;
    }

    // Allocate initial memory for messages
    manager.messages = malloc(sizeof(LTE_DL_CCCH_Message_Type1_T) * manager.capacity);
    if (!manager.messages) {
        logger_log(manager.log, "Memory allocation failed.");
        return;
    }

    // Start encoding threads
    const int num_threads = 10; // Hypothetical number of threads
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, message_encoder, &manager) != 0) {
            logger_log(manager.log, "Failed to create thread.");
        }
    }

    // Monitor and log
    while (1) {
        sleep(LOG_INTERVAL);
        pthread_mutex_lock(&manager.mutex);
        logger_log(manager.log, "Active threads: %d, Encoded messages: %zu", manager.active_threads, manager.count);

        if (manager.count >= MAX_MESSAGES || manager.capacity <= manager.count) {
            break;
        }

        // Dynamic resizing
        size_t new_capacity = manager.capacity * 2;
        if (new_capacity > MAX_MESSAGES) new_capacity = MAX_MESSAGES;

        LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(manager.messages, sizeof(LTE_DL_CCCH_Message_Type1_T) * new_capacity);
        if (!new_messages) {
            logger_log(manager.log, "Memory reallocation failed.");
            break;
        }

        manager.capacity = new_capacity;
        manager.messages = new_messages;

        pthread_mutex_unlock(&manager.mutex);

        // Fetch employee data example
        fetchEmployeeData(rand() % 100); // Hypothetical supervisor ID for demonstration

        // Compress and store encoded messages as needed (hypothetical file storage)
        for (size_t i = 0; i < manager.count; ++i) {
            size_t compressed_size;
            char* compressed_data = compress_data(manager.messages[i].nas_message.content, strlen(manager.messages[i].nas_message.content), &compressed_size);

            if (compressed_data) {
                // Store or transmit compressed data
                free(compressed_data);
            }
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(manager.messages);
    sem_destroy(&manager.semaphore);
    pthread_mutex_destroy(&manager.mutex);

    logger_cleanup(manager.log);
}
