void resize_session(SessionManager *session) {
    pthread_mutex_lock(&session->lock);
    size_t new_capacity = session->capacity * 2;
    LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(session->messages, new_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!new_messages) {
