                               (success_count * sizeof(char *));
    log_message(f"Total memory used: {total_memory_used} bytes");

    // Verify that all files were processed successfully
    if (success_count != file_list.count) {
        handle_error("Mismatch in number of input and successfully processed files.");
    }

    for (size_t i = 0; i < success_count; ++i) {
        free(converted_files[i]);
    }
