#define MAX_RECORDS 1000000

typedef struct {
    double timestamp;
    int sensor_id;
    float temperature;
} TemperatureSensorReading;

void log_message(const char* message) {
    // Integrate with existing logging framework
    printf("%s\n", message);
}

int read_and_process_csv(FILE *file, TemperatureSensorReading readings[], size_t *valid_count, float *average_temperature) {
    if (!file || !readings || !valid_count || !average_temperature) {
        log_message("Invalid input parameters");
        return -1;
    }

    char buffer[256];
    int min_index = 0, max_index = 0;
    float min_temp = FLT_MAX, max_temp = -FLT_MAX;
    float total_temp = 0.0;

    *valid_count = 0;

    while (fgets(buffer, sizeof(buffer), file) && *valid_count < MAX_RECORDS) {
        char* token = strtok(buffer, ",");
        if (!token || sscanf(token, "%lf", &readings[*valid_count].timestamp) != 1) {
            log_message("Malformed timestamp");
            continue;
        }

        token = strtok(NULL, ",");
        if (!token || sscanf(token, "%d", &readings[*valid_count].sensor_id) != 1) {
            log_message("Malformed sensor ID");
            continue;
        }

        token = strtok(NULL, ",");
        if (!token || sscanf(token, "%f", &readings[*valid_count].temperature) != 1) {
            log_message("Malformed temperature");
            continue;
        }

        // Validate data
        if (readings[*valid_count].timestamp < 0 || readings[*valid_count].sensor_id <= 0) {
            log_message("Invalid data found, skipping entry");
            continue;
        }

        total_temp += readings[*valid_count].temperature;

        if (readings[*valid_count].temperature < min_temp) {
            min_temp = readings[*valid_count].temperature;
            min_index = *valid_count;
        }

        if (readings[*valid_count].temperature > max_temp) {
            max_temp = readings[*valid_count].temperature;
            max_index = *valid_count;
        }

        (*valid_count)++;
    }

    if (*valid_count == 0) {
        log_message("No valid records found");
        return -1;
    }

    *average_temperature = total_temp / *valid_count;

    log_message("Data processing completed successfully");

    // Return indices of smallest and largest temperatures
    printf("Smallest Temperature Index: %d\n", min_index);
    printf("Largest Temperature Index: %d\n", max_index);

    return 0;
}

int main() {
    FILE *file = fopen("temperature_data.csv", "r");
    if (!file) {
        log_message("Failed to open file");
        return -1;
    }

    TemperatureSensorReading readings[MAX_RECORDS];
    size_t valid_count = 0;
    float average_temperature = 0.0;

    int result = read_and_process_csv(file, readings, &valid_count, &average_temperature);
    if (result == 0) {
        printf("Valid Records: %zu\n", valid_count);
        printf("Average Temperature: %.2f\n", average_temperature);
    }

    fclose(file);

    return result;
}
