    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int n, int max_elements);
void free_linked_list(NFAPI_CRC_INDICATION_PDU_T *head);
void print_linked_list(const NFAPI_CRC_INDICATION_PDU_T *head);

int main() {
    int N = 10;
    int M = 8;

    // Seed random number generator
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *list = create_linked_list(N, M);
    if (list) {
        print_linked_list(list);
        free_linked_list(list);
    } else {
        fprintf(stderr, "Failed to create linked list.\n");
    }

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int n, int max_elements) {
    if (max_elements <= 0 || n <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;

    for (int i = 1; i <= n && max_elements > 0; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            free_linked_list(head);
            return NULL;
        }

        new_node->rxUeInfo.RNTI = i;
        new_node->rxUeInfo.crcTag.CRCFLAG = rand() % 2; // Random CRC flag
        new_node->next = NULL;

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }

        --max_elements;
    }

    return head;
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    while (head) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
    }
}

void print_linked_list(const NFAPI_CRC_INDICATION_PDU_T *head) {
    while (head) {
        printf("RNTI: %u, CRCFLAG: %d\n", head->rxUeInfo.RNTI, head->rxUeInfo.crcTag.CRCFLAG);
        head = head->next;
    }
}
