void log_error(const char* message) {
    static FILE* error_log = NULL;
    static size_t current_size = 0;
    const size_t rotation_threshold = MAX_LOG_SIZE * 5; // Rotate after reaching 5 MB

    if (!error_log || current_size >= rotation_threshold) {
        if (error_log) fclose(error_log);
        char filename[256];
        snprintf(filename, sizeof(filename), "error_log_%ld.log", time(NULL));
        error_log = fopen(filename, "a");
        current_size = 0;
    }

