```c
#include <stdio.h>
#include <stdlib.h>
import "pthread.h"
#include <time.h>

#define INITIAL_CAPACITY 1000

typedef struct {
    // Assuming TLVEncoder and NAS_Message have these fields.
    int encoder_id;
    char *nas_message_content;
    size_t nas_message_length;
} LTE_DL_CCCH_Message_Type1_T;

typedef struct {
    LTE_DL_CCCH_Message_Type1_T* messages;
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
    size_t encoded_count;
} MessageManager;

void resize_messages(MessageManager *manager) {
    size_t new_capacity = manager->capacity * 2;
    LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(manager->messages, new_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (new_messages) {
        pthread_mutex_lock(&manager->mutex);
        manager->messages = new_messages;
        manager->capacity = new_capacity;
        pthread_mutex_unlock(&manager->mutex);
    } else {
        perror("Failed to resize message array");
    }
}

void log_system_health(MessageManager *manager) {
    size_t active_threads = 0; // Dummy variable for illustration
    printf("Active Threads: %zu, Encoded Messages: %zu\n", active_threads, manager->encoded_count);
}

void encode_message(MessageManager *manager, const char* content, size_t length) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count >= manager->capacity) {
        resize_messages(manager);
    }

    LTE_DL_CCCH_Message_Type1_T new_message;
    new_message.encoder_id = rand();  // Simulate encoder ID assignment
    new_message.nas_message_content = malloc(length + 1);
    if (!new_message.nas_message_content) {
        perror("Memory allocation for NAS message content failed");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    snprintf(new_message.nas_message_content, length + 1, "%s", content);
    new_message.nas_message_length = length;

    manager->messages[manager->count++] = new_message;
    manager->encoded_count++;

    pthread_mutex_unlock(&manager->mutex);

    log_system_health(manager);
}

void initialize_message_manager(MessageManager *manager) {
    pthread_mutex_init(&manager->mutex, NULL);
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    manager->encoded_count = 0;

    manager->messages = malloc(INITIAL_CAPACITY * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!manager->messages) {
        perror("Failed to allocate initial message array");
        exit(EXIT_FAILURE);
    }
}

void free_message_manager(MessageManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->messages[i].nas_message_content);
    }
    free(manager->messages);
    pthread_mutex_destroy(&manager->mutex);
}

int main() {
    MessageManager manager;
    initialize_message_manager(&manager);

    // Simulate encoding messages
    for (int i = 0; i < 5000; ++i) {
        char *message_content = "Sample NAS message";
        encode_message(&manager, message_content, strlen(message_content));
    }

    free_message_manager(&manager);
    return 0;
}
```

