['```java
package com.example.resourcemanagement;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import net.pcg.random.PCG32;

public class ResourceManager {

    private static final Logger logger = LogManager.getLogger(ResourceManager.class);
    private int[] keysArray;
    private double[] valuesArray;
    private List<Item> itemsList;

    // Static member for memory-intensive operations
    private static volatile ResourceManager instance; 

    public ResourceManager(int size) {
        this.keysArray = new int[size];
        this.valuesArray = new double[size];
        this.itemsList = new ArrayList<>(size);

        try {
            initializeResources(size);
        } catch (Exception e) {
            logger.error("Resource initialization failed: " + e.getMessage(), e);
            cleanup();
        }
    }

    private void initializeResources(int size) throws Exception {
        PCG32 random = new PCG32();
        Set<String> uniqueNames = new HashSet<>();

        for (int i = 0; i < size; i++) {
            keysArray[i] = i;
            valuesArray[i] = Math.abs(random.nextUniform());

            String name;
            double value;
            do {
                name = generateUniqueName(uniqueNames, random);
                value = Math.abs(random.nextDouble());
            } while (!uniqueNames.add(name));

            synchronized (this) {
                itemsList.add(new Item(name, value));
            }
        }

        logger.info("Resources initialized successfully with size: " + size);
    }

    private String generateUniqueName(Set<String> uniqueNames, PCG32 random) {
        StringBuilder name = new StringBuilder();
        for (int i = 0; i < 10; i++) {
            name.append((char) ('a' + random.nextInt(26)));
        }
        return name.toString();
    }

    @Override
    protected void finalize() throws Throwable {
        try {
            cleanup();
        } finally {
            super.finalize();
        }
    }

    private synchronized void cleanup() {
        keysArray = null;
        valuesArray = null;
        itemsList.clear();

        logger.info("Resources have been cleaned up");
    }

    public static ResourceManager getInstance(int size) throws Exception {
        if (instance == null) {
            synchronized (ResourceManager.class) {
                if (instance == null) {
                    instance = new ResourceManager(size);
                }
            }
        }
        return instance;
    }

    private static class Item {
        String name;
        double value;

        public Item(String name, double value) {
            this.name = name;
            this.value = value;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            Item item = (Item) obj;
            return Double.compare(item.value, value) == 0 &&
                   Objects.equals(name, item.name);
        }

        @Override
        public int hashCode() {
            return Objects.hash(name, value);
        }
    }
}
```

**Notes:**
- The code integrates the PCG32 random number generator for generating unique names and values.
- It uses `Logger` from Apache Log4j for logging.
- Thread safety is ensured using synchronized blocks around list modifications.
- Resource cleanup is performed in case of initialization failure or during finalization.']

