#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_INT 1000
#define MIN_INT -1000

typedef struct {
    int rnti;
    unsigned char rx_ue_information_tag[10];
    unsigned char crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    int value;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t size;
    pthread_mutex_t lock;
} ConcurrentHashMap;

ConcurrentHashMap* create_map(size_t size) {
    ConcurrentHashMap* map = malloc(sizeof(ConcurrentHashMap));
    map->buckets = calloc(size, sizeof(Node*));
    map->size = size;
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

unsigned long hash(int value, size_t size) {
    return (value % size + size) % size;
}

void insert(ConcurrentHashMap* map, int value) {
    unsigned long index = hash(value, map->size);
    pthread_mutex_lock(&map->lock);

    Node* node = map->buckets[index];
    while (node != NULL) {
        if (node->value == value) {
            pthread_mutex_unlock(&map->lock);
            return;
        }
        node = node->next;
    }

    Node* new_node = malloc(sizeof(Node));
    new_node->value = value;
    new_node->next = map->buckets[index];
    map->buckets[index] = new_node;

    pthread_mutex_unlock(&map->lock);
}

bool contains(ConcurrentHashMap* map, int value) {
    unsigned long index = hash(value, map->size);
    pthread_mutex_lock(&map->lock);

    Node* node = map->buckets[index];
    while (node != NULL) {
        if (node->value == value) {
            pthread_mutex_unlock(&map->lock);
            return true;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&map->lock);
    return false;
}

void free_map(ConcurrentHashMap* map) {
    for (size_t i = 0; i < map->size; ++i) {
        Node* node = map->buckets[i];
        while (node != NULL) {
            Node* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(map->buckets);
    pthread_mutex_destroy(&map->lock);
    free(map);
}

