    for (char* token = strtok(input, " "); token != NULL; token = strtok(NULL, " ")) {
        if (sscanf(token, "%d", &value) == 1 && value >= MIN_INT && value <= MAX_INT) {
            if (!contains(map, value)) {
                buffer[buffer_count++] = value;
                insert(map, value);
            }
        } else {
            free(buffer);
            return -1; // Invalid input or out of range
        }
    }

    *integers = realloc(buffer, buffer_count * sizeof(int));
    *count = buffer_count;
    return 0;
}

void populate_nfaapi_list(NFAPI_CRC_INDICATION_PDU_T* list, size_t count) {
