import json-c/json.h
#include <pthread.h>

typedef struct Measurement {
    double latency;
    double throughput;
    double packet_loss;
} Measurement;

typedef struct Node {
    int timestamp;
    char session_id[64];
    Measurement measurements;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* init_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void cleanup_metrics(DoublyLinkedList* list, int retention_period) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *next;

    while (current != NULL) {
        next = current->next;
        if ((time(NULL) - current->timestamp) > retention_period) {
            if (current == list->head) {
                list->head = next;
            }
            if (current == list->tail) {
                list->tail = current->prev;
            }
            if (current->prev != NULL) {
                current->prev->next = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            }
            free(current);
        }
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
}

void* parse_and_update_list(void* args) {
    // Simulate parsing and updating from JSON
    json_object *parsed_json, *session_id_obj, *latency_obj, *throughput_obj, *packet_loss_obj;

    pthread_mutex_lock(((DoublyLinkedList*)args)->lock);

    Node* current = ((DoublyLinkedList*)args)->head;
    int found = 0;

    while (current != NULL) {
        if (strcmp(current->session_id, "unique_session_id") == 0) { // Replace with actual parsed session ID
            found = 1;
            break;
        }
        current = current->next;
    }

    if (!found) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        strcpy(new_node->session_id, "unique_session_id"); // Use parsed value
        new_node->timestamp = time(NULL);
        pthread_mutex_unlock(((DoublyLinkedList*)args)->lock);

        // Add to list
        pthread_mutex_lock(((DoublyLinkedList*)args)->lock);
        if (((DoublyLinkedList*)args)->tail == NULL) {
            ((DoublyLinkedList*)args)->head = new_node;
            ((DoublyLinkedList*)args)->tail = new_node;
            new_node->next = NULL;
            new_node->prev = NULL;
        } else {
            ((DoublyLinkedList*)args)->tail->next = new_node;
            new_node->prev = ((DoublyLinkedList*)args)->tail;
            new_node->next = NULL;
            ((DoublyLinkedList*)args)->tail = new_node;
        }
    } else {
        current->measurements.latency = 50.0; // Use parsed value
        current->measurements.throughput = 100.0; // Use parsed value
        current->measurements.packet_loss = 1.5; // Use parsed value
    }

    pthread_mutex_unlock(((DoublyLinkedList*)args)->lock);

    return NULL;
}

void delete_metric(DoublyLinkedList* list, const char* session_id) {
    pthread_mutex_lock(list->lock);

    Node *current = list->head, *to_delete = NULL;

    while (current != NULL) {
        if (strcmp(current->session_id, session_id) == 0) {
            to_delete = current;
            break;
        }
        current = current->next;
    }

    if (to_delete) {
        if (to_delete->prev) {
            to_delete->prev->next = to_delete->next;
        } else {
            list->head = to_delete->next; // Deleting head
        }
        if (to_delete->next) {
            to_delete->next->prev = to_delete->prev;
        } else {
            list->tail = to_delete->prev; // Deleting tail
        }
        free(to_delete);
    }

    pthread_mutex_unlock(list->lock);
}

int main() {
    DoublyLinkedList* metrics_list = init_list();

    // Simulate periodic cleanup (you might use a separate thread or timer in production)
    while (1) {
        cleanup_metrics(metrics_list, 3600); // Retain data for 1 hour
        sleep(60); // Run every minute
    }

    return 0;
}
