#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <time.h>

#define MAX_HOSTNAME_LENGTH 256
#define MAX_IP_ADDRESS_LENGTH 16
#define CACHE_SIZE 100

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    u_char ip_address[4]; // IPv4 address
} DNSCacheEntry;

typedef struct {
    DNSCacheEntry entries[CACHE_SIZE];
    int count;
    pthread_mutex_t lock;
} DNSCache;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16]; // Assuming size
    unsigned char CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

// Function prototypes
DNSCache* init_dns_cache(int cache_size);
int add_to_dns_cache(DNSCache *cache, const char *hostname, u_char ip_address[4]);
int get_from_dns_cache(DNSCache *cache, const char *hostname, u_char ip_address[4]);
void free_dns_cache(DNSCache *cache);

NFAPI_CRC_INDICATION_PDU_T* populateNFAPIListAndResolveHostnames(int num_entries, int cache_size, int enable_cache);
u_char resolve_hostname(const char *hostname, DNSCache *cache);
void log_info(const char *message);
int exponential_backoff_retry(int (*func)(const char *, u_char[4]), const char *hostname, u_char ip_address[4]);

DNSCache* init_dns_cache(int cache_size) {
    DNSCache *cache = malloc(sizeof(DNSCache));
    if (!cache) return NULL;

    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

int add_to_dns_cache(DNSCache *cache, const char *hostname, u_char ip_address[4]) {
    pthread_mutex_lock(&cache->lock);

    if (cache->count < CACHE_SIZE) {
        strncpy(cache->entries[cache->count].hostname, hostname, MAX_HOSTNAME_LENGTH);
        memcpy(cache->entries[cache->count].ip_address, ip_address, 4);
        cache->count++;
        pthread_mutex_unlock(&cache->lock);
        return 0;
    }

    pthread_mutex_unlock(&cache->lock);
    return -1; // Cache full
}

int get_from_dns_cache(DNSCache *cache, const char *hostname, u_char ip_address[4]) {
    pthread_mutex_lock(&cache->lock);

    for (int i = 0; i < cache->count; ++i) {
        if (strcmp(cache->entries[i].hostname, hostname) == 0) {
            memcpy(ip_address, cache->entries[i].ip_address, 4);
            pthread_mutex_unlock(&cache->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return -1; // Not found
}

void free_dns_cache(DNSCache *cache) {
    if (cache) {
        pthread_mutex_destroy(&cache->lock);
        free(cache);
    }
}

NFAPI_CRC_INDICATION_PDU_T* populateNFAPIListAndResolveHostnames(int num_entries, int cache_size, int enable_cache) {
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    DNSCache *cache = enable_cache ? init_dns_cache(cache_size) : NULL;
    if (cache && pthread_mutex_init(&cache->lock, NULL) != 0) {
        free(list);
        return NULL;
    }

    for (int i = 0; i < num_entries; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
        list[i].RNTI = rand() % USHRT_MAX;
        for (int j = 0; j < 16; ++j) {
            list[i].CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }
        list[i].CRCFLAG = rand() % 2;

        // Example hostname
        char hostname[MAX_HOSTNAME_LENGTH];
        snprintf(hostname, sizeof(hostname), "example%d.com", i);

        u_char ip_address[4];
        if (enable_cache) {
            int found = get_from_dns_cache(cache, hostname, ip_address);
            if (found != 0) {
                resolve_hostname(hostname, cache); // Resolve and add to cache
            }
        } else {
            resolve_hostname(hostname, NULL);
        }

        log_info("Resolved: Hostname - %s, IP - %d.%d.%d.%d", hostname,
                 ip_address[0], ip_address[1], ip_address[2], ip_address[3]);
    }

    if (cache) free_dns_cache(cache);

    return list;
}

u_char resolve_hostname(const char *hostname, DNSCache *cache) {
    struct addrinfo hints, *res, *p;
    int status;
    u_char ip_address[4] = {0};

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_info("DNS resolution failed for %s: %s", hostname, gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip_address, &(ipv4->sin_addr), 4);
        if (cache) add_to_dns_cache(cache, hostname, ip_address);
    }

    freeaddrinfo(res);
    return 0;
}

void log_info(const char *message) {
    FILE *log_file = fopen("nfaapi_log.txt", "a");
    if (!log_file) return;

    pthread_mutex_t log_lock;
    static int initialized = 0;
    if (!initialized) {
        pthread_mutex_init(&log_lock, NULL);
        initialized = 1;
    }

    pthread_mutex_lock(&log_lock);
    fprintf(log_file, "%s\n", message);
    pthread_mutex_unlock(&log_lock);

    fclose(log_file);
}

int exponential_backoff_retry(int (*func)(const char *, u_char[4]), const char *hostname, u_char ip_address[4]) {
    int retries = 0;
    while (retries < 5) { // Retry up to 5 times
        if ((*func)(hostname, ip_address) == 0) {
            return 0; // Success
        }
        sleep(1 << retries); // Exponential backoff
        retries++;
    }

    log_info("Exponential backoff failed for %s", hostname);
    return -1;
}
```

### Key Features:

- **DNS Cache**: Implements an LRU cache with thread-safe operations.
- **Concurrency**: Uses mutexes to ensure thread safety in DNS cache and logging.
- **Error Handling**: Includes retry logic with exponential backoff for DNS resolution failures.
- **Logging**: Thread-safe logging mechanism that appends messages to a shared log file.
- **Configuration**: Allows enabling/disabling the cache via function parameters.

This code provides a foundation, which can be extended further based on specific application needs and system integration requirements.']

