#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_PDUS 1000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} PduList;

typedef struct MemoryPool {
    size_t element_size;
    size_t pool_size;
    void** free_list;
    pthread_mutex_t lock;
} MemoryPool;

PduList pdu_list = {NULL, PTHREAD_MUTEX_INITIALIZER};
MemoryPool memory_pool = {sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_PDUS, NULL, PTHREAD_MUTEX_INITIALIZER};

void init_memory_pool(MemoryPool* pool) {
    pool->free_list = malloc(pool->pool_size * sizeof(void*));
    for (size_t i = 0; i < pool->pool_size; ++i) {
        void* block = malloc(pool->element_size);
        pool->free_list[i] = block;
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->free_list[0]) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)pool->free_list[0];
        for (size_t i = 1; i < pool->pool_size && pool->free_list[i]; ++i) {
            pool->free_list[i - 1] = pool->free_list[i];
        }
        pool->free_list[--pool->pool_size] = NULL;
        pthread_mutex_unlock(&pool->lock);
        return pdu;
    } else {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool exhausted
    }
}

void deallocate_pdu(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pool->lock);
    if (pool->pool_size < MAX_PDUS) {
        pool->free_list[pool->pool_size++] = (void*)pdu;
    }
    pthread_mutex_unlock(&pool->lock);
}

int validate_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Example validation logic
    return pdu->RX_UE_INFORMATION_TAG != 0 && pdu->RNTI != 0;
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void add_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&pdu_list.lock);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        log_error("Memory allocation failed for list node");
        pthread_mutex_unlock(&pdu_list.lock);
        return;
    }
    new_node->pdu = *pdu;
    new_node->next = pdu_list.head;
    pdu_list.head = new_node;

    pthread_mutex_unlock(&pdu_list.lock);
}

void populate_pdu_list(size_t count) {
    init_memory_pool(&memory_pool);

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_pdu(&memory_pool);
        if (!pdu) {
            log_error("Failed to allocate PDU from memory pool");
            continue;
        }

        // Populate fields
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (validate_pdu(pdu)) {
            add_pdu_to_list(pdu);
        } else {
            log_error("Invalid PDU detected");
            deallocate_pdu(&memory_pool, pdu);
        }
    }
}

void free_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < MAX_PDUS && pool->free_list[i]; ++i) {
        free(pool->free_list[i]);
    }
    free(pool->free_list);
}

int main() {
    populate_pdu_list(100);

    // Clean up
    Node* current = pdu_list.head;
    while (current) {
        Node* next = current->next;
        deallocate_pdu(&memory_pool, &current->pdu);
        free(current);
        current = next;
    }
    free_memory_pool(&memory_pool);

    return 0;
}
```

### Key Points:
- **Memory Pooling**: Efficiently manages memory allocation and deallocation to minimize fragmentation.
- **Thread Safety**: Uses mutexes for synchronization, ensuring safe concurrent access.
- **Validation**: Checks each PDU before adding it to the list.
- **Error Logging**: Logs errors when invalid PDUs are detected or memory allocation fails.
- **Data Structure**: Utilizes a linked list for dynamic resizing and easy insertion.']

