#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MAC_CONTEXTS 1024

typedef struct {
    // Placeholder for LMAC_CONFIG structure
} LMAC_CONFIG;

typedef struct {
    // Placeholder for MAC_FRAME structure
} MAC_FRAME;

typedef struct {
    LMAC_CONFIG config;
    MAC_FRAME *frames;
    size_t frame_count;
} MAC_CONTEXT_T;

typedef struct {
    MAC_CONTEXT_T *contexts;
    size_t count;
    pthread_mutex_t lock;
} MAC_CONTEXT_ARRAY;

// Initialize the dynamic array of MAC_CONTEXT_T structures
void init_mac_context_array(MAC_CONTEXT_ARRAY *array) {
    array->contexts = NULL;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

// Add a new MAC_CONTEXT_T to the array
int add_mac_context(MAC_CONTEXT_ARRAY *array, const LMAC_CONFIG *config) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= MAX_MAC_CONTEXTS) {
        fprintf(stderr, "Maximum number of MAC_CONTEXT_T instances reached.\n");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    // Allocate memory for a new context
    MAC_CONTEXT_T *new_context = malloc(sizeof(MAC_CONTEXT_T));
    if (!new_context) {
        fprintf(stderr, "Memory allocation failed for new MAC_CONTEXT_T.\n");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    // Copy configuration and initialize frames list
    new_context->config = *config;
    new_context->frames = NULL;
    new_context->frame_count = 0;

    // Resize the array to accommodate the new context
    MAC_CONTEXT_T **new_array = realloc(array->contexts, (array->count + 1) * sizeof(MAC_CONTEXT_T *));
    if (!new_array) {
        fprintf(stderr, "Memory allocation failed for expanding contexts array.\n");
        free(new_context);
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    new_array[array->count] = new_context;
    array->contexts = new_array;
    array->count++;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Remove a MAC_CONTEXT_T from the array
int remove_mac_context(MAC_CONTEXT_ARRAY *array, size_t index) {
    if (index >= array->count) {
        fprintf(stderr, "Invalid index for removing MAC_CONTEXT_T.\n");
        return -1;
    }

    pthread_mutex_lock(&array->lock);

    // Free the frames list and the context itself
    free(array->contexts[index]->frames);
    free(array->contexts[index]);

    // Shift remaining contexts down
    for (size_t i = index; i < array->count - 1; i++) {
        array->contexts[i] = array->contexts[i + 1];
    }

    MAC_CONTEXT_T **new_array = realloc(array->contexts, (array->count - 1) * sizeof(MAC_CONTEXT_T *));
    if (!new_array && array->count > 1) {
        fprintf(stderr, "Memory reallocation failed for contexts array.\n");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->contexts = new_array;
    array->count--;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Clean up the dynamic array
void cleanup_mac_context_array(MAC_CONTEXT_ARRAY *array) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; i++) {
        free(array->contexts[i]->frames);
        free(array->contexts[i]);
    }

    free(array->contexts);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

int main() {
    MAC_CONTEXT_ARRAY array;
    init_mac_context_array(&array);

    LMAC_CONFIG config = {}; // Initialize with appropriate values
    add_mac_context(&array, &config);

    cleanup_mac_context_array(&array);
    return 0;
}
```

This code includes dynamic array management, thread safety using a mutex, and basic error handling. It allows adding and removing `MAC_CONTEXT_T` instances while managing memory efficiently. Adjustments can be made for performance optimization, integration with external systems, and other advanced features as needed.']

