    srand((unsigned int)time(NULL));
    time_t lastTimestamp = 0;

    for (size_t i = 0; i < numRecords; ++i) {
        int randomValue;
        do {
            randomValue = RANDOM_VALUE_RANGE_MIN + rand() % (RANDOM_VALUE_RANGE_MAX - RANDOM_VALUE_RANGE_MIN + 1);
        } while (usedRandomValues[randomValue]);

        usedRandomValues[randomValue] = 1;

        records[i].value = randomValue;
        snprintf(records[i].stringRep, sizeof(records[i].stringRep), "%d", randomValue);

        time(&records[i].timestamp);
        if (records[i].timestamp <= lastTimestamp) {
            logOperation("Non-monotonic timestamp");
            goto cleanup;
        }
        lastTimestamp = records[i].timestamp;

        // Simulate resource usage
        resourceMetrics->cpuUsage = ((float)rand() / RAND_MAX) * 100.0f;
        resourceMetrics->memoryUsage = ((float)rand() / RAND_MAX) * 80.0f; 
