        } while (used_keys[key]);
        used_keys[key] = 1;
        keys_local[i] = key;
    }

    // Initialize LTE messages
    for (size_t i = 0; i < lte_count; ++i) {
        lte_messages_local[i] = malloc(sizeof(LTE_DL_CCCH_Message_Type1_T));
