    int resolved;
} DNSCacheEntry;

typedef struct {
    DNSCacheEntry entries[CACHE_SIZE];
    pthread_mutex_t lock;
    int size;
} DNSCache;

DNSCache cache = {{{0}}, PTHREAD_MUTEX_INITIALIZER, 0};

int add_to_cache(const char *hostname, const u_char *ip_address) {
    pthread_mutex_lock(&cache.lock);
    if (cache.size >= CACHE_SIZE) {
        // Simple LRU eviction: remove the oldest entry
        memmove(cache.entries, cache.entries + 1, sizeof(DNSCacheEntry) * (CACHE_SIZE - 1));
    }
    strncpy(cache.entries[cache.size].hostname, hostname, sizeof(cache.entries[0].hostname));
    memcpy(cache.entries[cache.size].ip_address, ip_address, sizeof(u_char) * 4);
    cache.entries[cache.size].resolved = 1;
    cache.size++;
    pthread_mutex_unlock(&cache.lock);
    return 0;
}

int get_from_cache(const char *hostname, u_char *ip_address) {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < cache.size; ++i) {
        if (strcmp(cache.entries[i].hostname, hostname) == 0 && cache.entries[i].resolved) {
            memcpy(ip_address, cache.entries[i].ip_address, sizeof(u_char) * 4);
            pthread_mutex_unlock(&cache.lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cache.lock);
    return 0;
}

void log_status(const char *hostname, const u_char *ip_address, int status) {
