}

int resolve_hostname(const char *hostname, u_char *ip_address) {
    struct hostent *host;
    int retries = 5;
    while (retries--) {
        if ((host = gethostbyname(hostname)) != NULL) {
            memcpy(ip_address, host->h_addr, sizeof(u_char) * 4);
            return 0; // Success
        }
        sleep((6 - retries) * 100); // Exponential backoff
    }
    return -1; // Failure
}

void *dns_worker(void *arg) {
