typedef struct {
    time_t timestamp;
    int sensorID;
    double measurementData;
} SensorLogEntry;

typedef struct EnvironmentalMonitoringGraphNode {
    char *location;
    float elevation;
    SensorLogEntry sensorMetadata[10]; // Adjust size as needed
    int pollutionIndexThreshold;
    struct EnvironmentalMonitoringGraphNode **neighbors;
    int neighborCount;
    pthread_mutex_t lock;
} EnvironmentalMonitoringGraphNode;

typedef struct {
    EnvironmentalMonitoringGraphNode **nodes;
    int nodeCount;
    pthread_rwlock_t graphLock; // Read-write lock for graph access
} EnvironmentalMonitoringGraph;

// Function prototypes
EnvironmentalMonitoringGraph* initializeGraph(int initialSize);
void freeGraph(EnvironmentalMonitoringGraph *graph);
int addNode(EnvironmentalMonitoringGraph *graph, const char *location, float elevation);
void removeNode(EnvironmentalMonitoringGraph *graph, int nodeId);
void updateNodeWithRealTimeData(EnvironmentalMonitoringGraph *graph, int nodeId, SensorLogEntry data);

// Function to manage dynamic memory allocation for an array of SensorLogEntry
SensorLogEntry* allocateSensorEntries(int count) {
    return (SensorLogEntry*)malloc(count * sizeof(SensorLogEntry));
}

void freeSensorEntries(SensorLogEntry* entries) {
    if(entries != NULL) {
        free(entries);
    }
}

EnvironmentalMonitoringGraph* initializeGraph(int initialSize) {
    EnvironmentalMonitoringGraph *graph = malloc(sizeof(EnvironmentalMonitoringGraph));
    graph->nodes = malloc(initialSize * sizeof(EnvironmentalMonitoringGraphNode *));
    graph->nodeCount = 0;
    pthread_rwlock_init(&graph->graphLock, NULL);

    for (int i = 0; i < initialSize; ++i) {
        graph->nodes[i] = NULL;
    }

    return graph;
}

void freeGraph(EnvironmentalMonitoringGraph *graph) {
    if (!graph) return;

    for (int i = 0; i < graph->nodeCount; ++i) {
        EnvironmentalMonitoringGraphNode *node = graph->nodes[i];
        pthread_mutex_destroy(&node->lock);
        free(node->location);
        free(node->neighbors);
        free(node);
    }
    free(graph->nodes);
    pthread_rwlock_destroy(&graph->graphLock);
    free(graph);
}

int addNode(EnvironmentalMonitoringGraph *graph, const char *location, float elevation) {
    pthread_rwlock_wrlock(&graph->graphLock);

    int nodeId = graph->nodeCount++;
    EnvironmentalMonitoringGraphNode *newNode = malloc(sizeof(EnvironmentalMonitoringGraphNode));

    newNode->location = strdup(location);
    newNode->elevation = elevation;
    newNode->sensorMetadata = allocateSensorEntries(10); // Allocate memory for sensor metadata
    newNode->pollutionIndexThreshold = rand() % 101; // Random pollution index between 0-100

    newNode->neighbors = malloc(1 * sizeof(EnvironmentalMonitoringGraphNode*));
    newNode->neighborCount = 0;

    pthread_mutex_init(&newNode->lock, NULL);

    graph->nodes[nodeId] = newNode;

    pthread_rwlock_unlock(&graph->graphLock);
    return nodeId;
}

void removeNode(EnvironmentalMonitoringGraph *graph, int nodeId) {
    if (nodeId < 0 || nodeId >= graph->nodeCount) return;

    pthread_rwlock_wrlock(&graph->graphLock);

    EnvironmentalMonitoringGraphNode *node = graph->nodes[nodeId];

    // Remove node from all neighbors
    for(int i = 0; i < node->neighborCount; ++i) {
        EnvironmentalMonitoringGraphNode *neighbor = node->neighbors[i];
        pthread_mutex_lock(&neighbor->lock);

        for(int j = 0; j < neighbor->neighborCount; ++j) {
            if(neighbor->neighbors[j] == node) {
                memmove(&neighbor->neighbors[j], &neighbor->neighbors[j+1],
                        (neighbor->neighborCount - j - 1) * sizeof(EnvironmentalMonitoringGraphNode*));
                --neighbor->neighborCount;
                break;
            }
        }

        pthread_mutex_unlock(&neighbor->lock);
    }

    free(node->location);
    freeSensorEntries(node->sensorMetadata);
    free(node->neighbors);

    pthread_mutex_destroy(&node->lock);
    free(node);

    // Shift remaining nodes
    memmove(&graph->nodes[nodeId], &graph->nodes[nodeId + 1],
            (graph->nodeCount - nodeId - 1) * sizeof(EnvironmentalMonitoringGraphNode *));
    --graph->nodeCount;

    pthread_rwlock_unlock(&graph->graphLock);
}

void updateNodeWithRealTimeData(EnvironmentalMonitoringGraph *graph, int nodeId, SensorLogEntry data) {
    if (nodeId < 0 || nodeId >= graph->nodeCount) return;

    EnvironmentalMonitoringGraphNode *node = graph->nodes[nodeId];

    pthread_mutex_lock(&node->lock);

    // Assuming we just want to update the first entry for simplicity
    node->sensorMetadata[0] = data;

    pthread_mutex_unlock(&node->lock);
}

// Initialize random seed
void initializeRandomSeed() {
    srand(time(NULL));
}
