```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000000

typedef struct {
    char *data;
    int value;
    double timestamp;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    size_t count;
    pthread_mutex_t lock;
} DataManager;

// Initialize external logging library (mock)
void init_logging_library() { /* Initialization logic */ }
void log_access(const char *message) { /* Logging logic */ }

DataManager* initialize_data_manager(size_t initial_size) {
    DataManager *dm = malloc(sizeof(DataManager));
    if (!dm) return NULL;

    dm->offsets = calloc(initial_size, sizeof(long));
    dm->keys = calloc(initial_size, sizeof(int));
    dm->records = calloc(initial_size, sizeof(record));
    dm->count = 0;
    pthread_mutex_init(&dm->lock, NULL);

    if (!dm->offsets || !dm->keys || !dm->records) {
        free_data_manager(dm);
        return NULL;
    }

    init_logging_library();
    log_access("Data manager initialized");

    return dm;
}

void add_record(DataManager *dm, const char *string_data, int value, double timestamp) {
    pthread_mutex_lock(&dm->lock);

    if (dm->count >= MAX_RECORDS) {
        log_access("Attempt to exceed max record count");
        pthread_mutex_unlock(&dm->lock);
        return;
    }

    size_t string_len = strlen(string_data) + 1;
    dm->records[dm->count].data = malloc(string_len);
    if (!dm->records[dm->count].data) {
        log_access("Failed to allocate memory for record data");
        pthread_mutex_unlock(&dm->lock);
        return;
    }

    strcpy(dm->records[dm->count].data, string_data);
    dm->records[dm->count].value = value;
    dm->records[dm->count].timestamp = timestamp;

    dm->offsets[dm->count] = (long)dm->records[dm->count].data - (long)dm->records;
    dm->keys[dm->count] = value;  // Example: using 'value' as key

    dm->count++;
    log_access("Record added");

    pthread_mutex_unlock(&dm->lock);
}

void free_data_manager(DataManager *dm) {
    pthread_mutex_lock(&dm->lock);

    for (size_t i = 0; i < dm->count; ++i) {
        if (dm->records[i].data) {
            free(dm->records[i].data);
        }
    }

    free(dm->offsets);
    free(dm->keys);
    free(dm->records);
    pthread_mutex_destroy(&dm->lock);

    log_access("Data manager freed");
    free(dm);
}

// Example usage
