#include <string.h>
#include <pthread.h>

// Structure Definitions
typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned long RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct RX_UE_INFORMATION_TAG {
    // Placeholder for real data
} RX_UE_INFORMATION_TAG;

// Node and List Structures
struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
};

typedef struct {
    struct ListNode* head;
    pthread_mutex_t lock;
} CRCLinkedList;

// Function Prototypes
CRCLinkedList* create_list(void);
void destroy_list(CRCLinkedList* list);
int add_or_update_element(CRCLinkedList* list, RX_UE_INFORMATION_TAG rx_ue_info_tag, unsigned long rnti, CRC_INDICATION_REL8_TAG crc_tag);
int remove_element_by_rnti(CRCLinkedList* list, unsigned long rnti);
void iterate_forward(CRCLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*));
void iterate_backward(CRCLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*));

// Helper Functions
static struct ListNode* find_node_by_rnti(struct ListNode* head, unsigned long rnti);
static void merge_crc_flags(CRC_INDICATION_REL8_TAG* existing, CRC_INDICATION_REL8_TAG new_tag);

// Function Implementations

CRCLinkedList* create_list(void) {
    CRCLinkedList* list = (CRCLinkedList*)malloc(sizeof(CRCLinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(CRCLinkedList* list) {
    struct ListNode *current = list->head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_or_update_element(CRCLinkedList* list, RX_UE_INFORMATION_TAG rx_ue_info_tag, unsigned long rnti, CRC_INDICATION_REL8_TAG crc_tag) {
    pthread_mutex_lock(&list->lock);

    struct ListNode *current = list->head;
    struct ListNode *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) { // Not found, add new
        struct ListNode* new_node = (struct ListNode*)malloc(sizeof(struct ListNode));
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Out of memory
        }
        new_node->data.RNTI = rnti;
        new_node->data.crc_tag = crc_tag;
        new_node->next = list->head;
        list->head = new_node;
    } else { // Found, update existing
        merge_crc_flags(&current->data.crc_tag, crc_tag);
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_element_by_rnti(CRCLinkedList* list, unsigned long rnti) {
    pthread_mutex_lock(&list->lock);

    struct ListNode *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Not found
    }

    if (prev == NULL) { // Head node
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void iterate_forward(CRCLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    struct ListNode *current = list->head;
    while (current != NULL) {
        callback(&current->data);
        current = current->next;
    }
}

void iterate_backward(CRCLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    // For singly linked lists, we need a different approach for reverse iteration.
    struct ListNode **indirect = &list->head;

    while (*indirect != NULL) {
        indirect = &(*indirect)->next;
    }

    while (indirect != &(list->head)) {
        indirect = &(*indirect)->next;
        callback(&((*indirect)->data));
    }
}

static struct ListNode* find_node_by_rnti(struct ListNode* head, unsigned long rnti) {
    while (head != NULL && head->data.RNTI != rnti) {
        head = head->next;
    }
    return head;
}

static void merge_crc_flags(CRC_INDICATION_REL8_TAG* existing, CRC_INDICATION_REL8_TAG new_tag) {
    // Example: Perform bitwise OR to combine flags
    existing->CRCFLAG |= new_tag.CRCFLAG; 
}

// Usage example function for callbacks in iteration
void print_nfa_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RNTI: %lu, CRCFLAG: %u\n", pdu->RNTI, pdu->crc_tag.CRCFLAG);
}
```

### Key Points

- **Memory Management**: The list uses dynamic memory allocation for both the list structure and its nodes. The `destroy_list` function ensures all allocated memory is freed.

- **Concurrency**: A mutex (`pthread_mutex_t`) is used to ensure thread-safe operations on the list, allowing safe concurrent access.

- **Error Handling**: The functions handle out-of-memory situations gracefully by returning error codes.

- **Iterating the List**: Forward iteration uses a simple loop. For reverse iteration, an indirect pointer is used due to the singly linked nature of the list.

- **Merging Entries**: When updating entries with the same `RNTI`, CRC flags are merged using bitwise OR.

This implementation provides a foundation for managing and manipulating a dynamic list in C, addressing memory management, concurrency, and modularity.']

