G_NAS_Message* initialize_5g_nas_messages(EnvironmentSettings settings, int max_message_size, const char **supported_message_types, size_t num_supported_types) {
    G_NAS_Message *messages = (G_NAS_Message *)malloc(MAX_MESSAGES * sizeof(G_NAS_Message));
    if (!messages) {
        log_error("Failed to allocate memory for NAS messages");
        return NULL;
    }

    // Initialize TLVEncoder based on environment settings
    for (int i = 0; i < MAX_MESSAGES; ++i) {
        messages[i].encoder.encoding_behavior = settings.compression_enabled ? 1 : 0;

        // Randomly select a message type from supported types
        if (num_supported_types == 0) {
            log_error("No supported message types provided");
            free(messages);
            return NULL;
        }

        int random_type_index = rand() % num_supported_types;
        messages[i].nas_message.message_type = strdup(supported_message_types[random_type_index]);

        // Generate a random content size
        size_t content_size = rand() % (max_message_size - 1) + 1; 
        messages[i].nas_message.content = malloc(content_size);
        if (!messages[i].nas_message.content) {
            log_error("Failed to allocate memory for message content");
            free(messages[i].nas_message.message_type);
            // Free previously allocated resources
            for (int j = 0; j < i; ++j) {
                free(messages[j].nas_message.message_type);
                free(messages[j].nas_message.content);
            }
            free(messages);
            return NULL;
        }

        // Populate the message content with random data
        memset(messages[i].nas_message.content, rand() % 256, content_size);
        messages[i].nas_message.content_length = content_size;
    }

    return messages;
}

void cleanup_5g_nas_messages(G_NAS_Message *messages) {
    if (!messages) return;

    for (int i = 0; i < MAX_MESSAGES; ++i) {
        free(messages[i].nas_message.message_type);
        free(messages[i].nas_message.content);
    }
    free(messages);
}

// Example usage
int main() {
    EnvironmentSettings settings = { .priority_level = 1, .compression_enabled = 1 };
    const char *supported_types[] = {"TypeA", "TypeB", "TypeC"};
    G_NAS_Message *messages = initialize_5g_nas_messages(settings, MAX_MESSAGE_SIZE, supported_types, 3);

    if (messages) {
        // Use messages as needed
        cleanup_5g_nas_messages(messages);
    }

    return 0;
}
