#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    unsigned char ip[4];
    uint16_t port;
    bool status;
} Node;

typedef struct NodeList {
    Node* nodes;
    size_t count;
    pthread_mutex_t lock;
} NodeList;

NodeList* create_node_list() {
    NodeList* list = (NodeList*)malloc(sizeof(NodeList));
    if (!list) return NULL;

    list->nodes = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

bool add_node(NodeList* list, unsigned char ip[4], uint16_t port, bool status) {
    pthread_mutex_lock(&list->lock);

    size_t new_count = list->count + 1;
    Node* new_nodes = (Node*)realloc(list->nodes, new_count * sizeof(Node));
    if (!new_nodes) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    memcpy(new_nodes[list->count].ip, ip, 4);
    new_nodes[list->count].port = port;
    new_nodes[list->count].status = status;

    list->nodes = new_nodes;
    list->count = new_count;

    pthread_mutex_unlock(&list->lock);
    return true;
}

bool remove_node(NodeList* list, unsigned char ip[4]) {
    pthread_mutex_lock(&list->lock);

    size_t i, j;
    bool found = false;
    for (i = 0; i < list->count && !found; ++i) {
        if (memcmp(list->nodes[i].ip, ip, 4) == 0) {
            found = true;
        } else if (found) {
            list->nodes[j] = list->nodes[i];
            j++;
        }
    }

    if (!found) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    size_t new_count = list->count - 1;
    Node* new_nodes = (Node*)realloc(list->nodes, new_count * sizeof(Node));
    if (!new_nodes && new_count > 0) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    list->nodes = new_nodes;
    list->count = new_count;

    pthread_mutex_unlock(&list->lock);
    return true;
}

void update_status(NodeList* list, bool status) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        list->nodes[i].status = status;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_node_list(NodeList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    free(list->nodes);
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}
