#include <iostream>
#include <vector>
#include <string>
#include <mutex>
#include <random>
#include <memory>
#include <chrono>
#include <fstream>

// Mock external logging library
namespace Logger {
    void log(const std::string& message) {
        std::cout << "LOG: " << message << std::endl;
    }
}

struct Transaction {
    int value;
    std::chrono::time_point<std::chrono::system_clock> timestamp;

    Transaction(int val, std::chrono::time_point<std::chrono::system_clock> ts)
        : value(val), timestamp(ts) {}
};

namespace DataManagement {

class DataManager {
private:
    static std::mt19937 gen;
    static std::mutex mtx;
    double* valuesArray;
    size_t valuesSize;
    std::string* keyIdentifiers;
    size_t keysSize;
    std::vector<Transaction> transactions;

public:
    DataManager(size_t initialValues, size_t initialKeys)
        : valuesSize(initialValues), keysSize(initialKeys) {
        try {
            valuesArray = new double[valuesSize];
            keyIdentifiers = new std::string[keysSize];

            for (size_t i = 0; i < valuesSize; ++i) {
                valuesArray[i] = static_cast<double>(gen());
            }

            for (size_t i = 0; i < keysSize; ++i) {
                keyIdentifiers[i] = "Key_" + std::to_string(i);
            }

            Logger::log("DataManager initialized successfully.");
        } catch (const std::bad_alloc& e) {
            Logger::log("Memory allocation failed: " + std::string(e.what()));
            cleanup();
            throw;
        }
    }

    ~DataManager() {
        delete[] valuesArray;
        delete[] keyIdentifiers;
        transactions.clear();
        Logger::log("DataManager destroyed.");
    }

    void addTransaction(int value) {
        std::lock_guard<std::mutex> lock(mtx);
        auto timestamp = std::chrono::system_clock::now();

        if (std::find_if(transactions.begin(), transactions.end(),
                         [value](const Transaction& t) { return t.value == value; }) != transactions.end()) {
            Logger::log("Duplicate transaction value: " + std::to_string(value));
            return;
        }

        try {
            transactions.emplace_back(value, timestamp);
            Logger::log("Transaction added: Value=" + std::to_string(value));
        } catch (const std::bad_alloc& e) {
            Logger::log("Memory allocation failed while adding transaction: " + std::string(e.what()));
        }
    }

    void resizeValuesArray(size_t newSize) {
        if (newSize == valuesSize) return;

        try {
            double* newArray = new double[newSize];
            size_t minSize = (newSize > valuesSize) ? valuesSize : newSize;
            for (size_t i = 0; i < minSize; ++i) {
                newArray[i] = valuesArray[i];
            }

            delete[] valuesArray;
            valuesArray = newArray;
            valuesSize = newSize;

            Logger::log("Values array resized to: " + std::to_string(newSize));
        } catch (const std::bad_alloc& e) {
            Logger::log("Memory allocation failed during resize: " + std::string(e.what()));
        }
    }

    void cleanup() {
        if (valuesArray) delete[] valuesArray;
        if (keyIdentifiers) delete[] keyIdentifiers;
        transactions.clear();
    }
};

std::mt19937 DataManager::gen(std::random_device{}());
std::mutex DataManager::mtx;

} // namespace DataManagement

int main() {
    try {
        DataManagement::DataManager manager(10, 5);
        manager.addTransaction(42);

        for (int i = 0; i < 100; ++i) {
            manager.addTransaction(i);
        }

        manager.resizeValuesArray(20);
    } catch (...) {
        Logger::log("Exception occurred in main.");
    }
}
```

