#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16

typedef struct {
    int offset;
    int key;
} Message;

typedef struct {
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordArray;

unsigned long hash(int key) {
    return (unsigned long)key; // Simple hash function for demonstration
}

int is_unique(RecordArray *record_array, int value) {
    for (size_t i = 0; i < record_array->count; ++i) {
        if (record_array->records[i].value == value) {
            return 0;
        }
    }
    return 1;
}

void serialize(const RecordArray *record_array, const char **data, size_t *length) {
    *length = sizeof(size_t) + record_array->count * sizeof(Record);
    *data = malloc(*length);

    if (*data != NULL) {
        char *ptr = (char *)*data;
        memcpy(ptr, &record_array->count, sizeof(size_t));
        ptr += sizeof(size_t);
        for (size_t i = 0; i < record_array->count; ++i) {
            memcpy(ptr, &record_array->records[i], sizeof(Record));
            ptr += sizeof(Record);
        }
    }
}

int deserialize(const char *data, size_t length, RecordArray *record_array) {
    if (length < sizeof(size_t)) return -1;

    const char *ptr = data;
    size_t count;
    memcpy(&count, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    if (length != sizeof(size_t) + count * sizeof(Record)) return -1;

    pthread_mutex_lock(&record_array->lock);
    record_array->records = realloc(record_array->records, count * sizeof(Record));
    record_array->capacity = count;
    record_array->count = count;

    for (size_t i = 0; i < count; ++i) {
        memcpy(&record_array->records[i], ptr, sizeof(Record));
        ptr += sizeof(Record);
    }
    pthread_mutex_unlock(&record_array->lock);

    return 0;
}

void initialize_records_with_messages(Message *messages, size_t num_messages, RecordArray *record_array) {
    pthread_mutex_init(&record_array->lock, NULL);
    record_array->capacity = INITIAL_CAPACITY;
    record_array->count = 0;
    record_array->records = malloc(record_array->capacity * sizeof(Record));

    for (size_t i = 0; i < num_messages; ++i) {
        pthread_mutex_lock(&record_array->lock);

        if (is_unique(record_array, messages[i].key)) {
            if (record_array->count == record_array->capacity) {
                size_t new_capacity = record_array->capacity * 2;
                Record *new_records = realloc(record_array->records, new_capacity * sizeof(Record));

                if (new_records != NULL) {
                    record_array->records = new_records;
                    record_array->capacity = new_capacity;
                } else {
                    fprintf(stderr, "Memory allocation failed.\n");
                    pthread_mutex_unlock(&record_array->lock);
                    continue;
                }
            }

            record_array->records[record_array->count].value = messages[i].key;
            record_array->count++;
        }

        pthread_mutex_unlock(&record_array->lock);
    }
}

void cleanup_record_array(RecordArray *record_array) {
    free(record_array->records);
    pthread_mutex_destroy(&record_array->lock);
}
```

### Key Points:

- **Concurrency**: Uses `pthread_mutex_t` for synchronization to handle concurrent modifications.
- **Dynamic Memory Management**: Allocates and resizes the records array dynamically.
- **Hashing & Uniqueness Check**: Implements a simple hash function and checks for uniqueness before adding records.
- **Serialization/Deserialization**: Provides functions to serialize and deserialize the record data into/from binary format, ensuring integrity with size checks.
- **Error Handling**: Gracefully handles memory allocation failures and ensures that processing continues despite errors.

This implementation considers performance constraints by using efficient data structures and synchronization mechanisms. It is designed for integration into larger systems, with clear interfaces and error handling.']

