['Here's an implementation outline for managing a dynamic list of `NFAPI_CRC_INDICATION_PDU_T` structures, meeting your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RNTI;
    char RX_UE_INFORMATION_TAG[256];
    // Add CRC_INDICATION_REL8_TAG structure members here
    unsigned int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    size_t max_size;  // Maximum number of elements
} CRCList;

// Utility function to allocate a new node
Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    memcpy(&new_node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;
    return new_node;
}

// Initialize the CRCList
void init_crc_list(CRCList* list, size_t max_size) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->max_size = max_size;
}

// Function to add or update a node based on RNTI
void add_or_update_crc(CRCList* list, const NFAPI_CRC_INDICATION_PDU_T* new_data) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    // Search for existing RNTI or end of list
    while (current && current->data.RNTI != new_data->RNTI) {
        prev = current;
        current = current->next;
    }

    if (current) {  // Update existing node's CRCFLAG
        current->data.CRCFLAG = new_data->CRCFLAG;
    } else {
        Node* new_node = create_node(new_data);
        if (!new_node) {
            pthread_mutex_unlock(&list->lock);
            return;  // Handle memory allocation failure
        }

        if (prev) {
            prev->next = new_node;
        } else {
            list->head = new_node;
        }

        list->count++;
        // Trim the list if it exceeds max_size
        if (list->count > list->max_size) trim_list(list);
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to remove a node based on RNTI
void remove_crc(CRCList* list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current) {
        if (prev) {
            prev->next = current->next;
        } else {
            list->head = current->next;
        }
        free(current);
        list->count--;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to trim the list when exceeding max size
void trim_list(CRCList* list) {
    Node **current = &list->head, *to_free;

    while (*current && list->count > list->max_size) {
        to_free = *current;
        *current = (*current)->next;
        free(to_free);
        list->count--;
    }
}

// Function to iterate over the list in forward order
void for_each_forward(CRCList* list, void (*func)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        func(&(current->data));
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to iterate over the list in reverse order
void for_each_reverse(CRCList* list, void (*func)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    Node **current = &list->head, *prev = NULL;

    while (*current) prev = *current, current = &(*current)->next;

    pthread_mutex_lock(&list->lock);

    while (prev) {
        func(&(prev->data));
        // Move backward
        Node* temp = list->head;
        if (!temp) break;  // Should not happen in correct implementation
        while (temp && temp->next != prev) temp = temp->next;

        if (temp) {
            *current = temp;
            prev = temp;
        } else break;  // End of list reached
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to free the entire list and its resources
void destroy_crc_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Sample function to be called during iteration
void print_crc(const NFAPI_CRC_INDICATION_PDU_T* data) {
    printf("RNTI: %d, CRCFLAG: %u\n", data->RNTI, data->CRCFLAG);
}
