} TaskQueue;

TaskQueue* create_task_queue() {
    TaskQueue *queue = (TaskQueue *)malloc(sizeof(TaskQueue));
    if (!queue) return NULL;

    queue->head = NULL;
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

void destroy_task_queue(TaskQueue *queue) {
    Task *current = queue->head;
    while (current != NULL) {
        Task *next = current->next;
        // Free specific data based on type
        switch (current->data_type) {
            case ARRAY_OF_LONGS:
                free(current->data.array_of_longs.array);
                break;
            case MAP_OF_STRINGS:
                for (size_t i = 0; i < current->data.map_of_strings.count; ++i) {
                    free(current->data.map_of_strings.map[i]);
                }
                free(current->data.map_of_strings.map);
