            case GRAPH_NODE:
                for (size_t i = 0; i < current->data.graph_node.adj_count; ++i) {
                    free(current->data.graph_node.adjacent_nodes[i]);
                }
                free(current->data.graph_node.adjacent_nodes);
                break;
        }
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}

int add_task(TaskQueue *queue, unsigned long task_id, int priority_level, DataStructureType data_type, void *data) {
    pthread_mutex_lock(&queue->lock);

    // Check for duplicate Task_ID
    Task *current = queue->head;
    while (current != NULL) {
        if (current->task_id == task_id) {
            pthread_mutex_unlock(&queue->lock);
            return -1; // Task ID already exists
        }
        current = current->next;
    }

    Task *new_task = (Task *)malloc(sizeof(Task));
    if (!new_task) {
        pthread_mutex_unlock(&queue->lock);
        return -2; // Memory allocation failure
    }

    new_task->task_id = task_id;
    new_task->priority_level = priority_level;
    new_task->data_type = data_type;

    switch (data_type) {
        case ARRAY_OF_LONGS:
            new_task->data.array_of_longs.array = (long *)malloc(data ? sizeof(long) * ((ArrayOfLongs *)data)->length : 0);
            if (!new_task->data.array_of_longs.array) {
                free(new_task);
                pthread_mutex_unlock(&queue->lock);
                return -2;
            }
            new_task->data.array_of_longs.length = data ? ((ArrayOfLongs *)data)->length : 0;
            if (data) memcpy(new_task->data.array_of_longs.array, ((ArrayOfLongs *)data)->array, sizeof(long) * new_task->data.array_of_longs.length);
            break;
        case MAP_OF_STRINGS:
            new_task->data.map_of_strings.count = data ? ((MapOfStrings *)data)->count : 0;
            new_task->data.map_of_strings.map = (char **)malloc(new_task->data.map_of_strings.count * sizeof(char *));
            if (!new_task->data.map_of_strings.map) {
                free(new_task);
                pthread_mutex_unlock(&queue->lock);
                return -2;
            }
            for (size_t i = 0; i < new_task->data.map_of_strings.count; ++i) {
                new_task->data.map_of_strings.map[i] = strdup(data ? ((MapOfStrings *)data)->map[i] : "");
            }
            break;
        case GRAPH_NODE:
            new_task->data.graph_node.node_id = data ? ((GraphNode *)data)->node_id : 0;
            new_task->data.graph_node.adj_count = data ? ((GraphNode *)data)->adj_count : 0;
            new_task->data.graph_node.adjacent_nodes = (GraphNode **)malloc(new_task->data.graph_node.adj_count * sizeof(GraphNode *));
            if (!new_task->data.graph_node.adjacent_nodes) {
                free(new_task);
                pthread_mutex_unlock(&queue->lock);
                return -2;
            }
            for (size_t i = 0; i < new_task->data.graph_node.adj_count; ++i) {
                new_task->data.graph_node.adjacent_nodes[i] = strdup(data ? ((GraphNode *)data)->adjacent_nodes[i]->node_id : "");
            }
            break;
    }

    new_task->next = queue->head;
    queue->head = new_task;
    queue->count++;

    pthread_mutex_unlock(&queue->lock);
    return 0; // Success
}

// Implement dynamic resizing and monitoring functions as needed

int main() {
    TaskQueue *queue = create_task_queue();
    if (!queue) {
        fprintf(stderr, "Failed to create task queue\n");
        return EXIT_FAILURE;
    }

    // Example usage
    ArrayOfLongs array_data = { .array = (long[]){1, 2, 3}, .length = 3 };
    add_task(queue, 12345, 10, ARRAY_OF_LONGS, &array_data);

    destroy_task_queue(queue);
    return EXIT_SUCCESS;
}
```

This code provides a basic implementation of a multi-threaded task queue with memory management for different data types. It includes mechanisms to handle concurrent access using mutexes and ensures no duplicate task IDs. The function `add_task` handles dynamic memory allocation and initialization based on the provided data type, and it cleans up resources in case of failure. Further enhancements can be added for dynamic resizing, monitoring, and logging as needed.']

