int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char* generate_metadata(size_t index, size_t total_records) {
    char *metadata = malloc(50);
    if (!metadata) {
        sync_log("Failed to allocate memory for metadata");
        return NULL;
    }
    snprintf(metadata, 50, "meta_%zu_%zu", index, total_records);
    return metadata;
}

void archive_record(DataManager* dm, size_t idx);

// Thread-safe function to initialize data manager
DataManager* init_data_manager(size_t num_records, time_t archive_threshold) {
    DataManager *dm = malloc(sizeof(DataManager));
    if (!dm) {
        sync_log("Failed to allocate memory for DataManager");
        return NULL;
    }

    pthread_mutex_init(&dm->lock, NULL);

    dm->offsets = malloc(num_records * sizeof(long));
    dm->keys = malloc(num_records * sizeof(int));
    dm->records = malloc(num_records * sizeof(record*));
    dm->metadata_strings = malloc(num_records * sizeof(char*));

    if (!dm->offsets || !dm->keys || !dm->records || !dm->metadata_strings) {
        sync_log("Memory allocation failed during initialization");
        free(dm->offsets);
        free(dm->keys);
        free(dm->records);
        free(dm->metadata_strings);
        free(dm);
        return NULL;
    }

    dm->num_records = num_records;
    dm->archive_threshold = archive_threshold;

    pthread_t archiver_thread;
    pthread_create(&archiver_thread, NULL, (void*)[]{
        while (1) {
            sleep(60);  // Archive every minute
            time_t now = time(NULL);
            for (size_t i = 0; i < num_records; ++i) {
                if (now - dm->records[i]->timestamp > archive_threshold) {
                    archive_record(dm, i);
                }
            }
        }
    }, dm);

    return dm;
}

void finalize_data_manager(DataManager* dm) {
    pthread_mutex_lock(&dm->lock);
    for (size_t i = 0; i < dm->num_records; ++i) {
        free(dm->records[i]->str);
        free(dm->records[i]->metadata);
        free(dm->records[i]);
    }
    free(dm->offsets);
    free(dm->keys);
    free(dm->records);
    for (size_t i = 0; i < dm->num_records; ++i) {
        free(dm->metadata_strings[i]);
    }
    free(dm->metadata_strings);

    pthread_mutex_unlock(&dm->lock);
    pthread_mutex_destroy(&dm->lock);
    free(dm);
}

void add_record(DataManager* dm, int key, const char* str_rep) {
    pthread_mutex_lock(&dm->lock);

    if (key < 0 || key >= dm->num_records) {
        sync_log("Invalid key for record addition");
        pthread_mutex_unlock(&dm->lock);
        return;
    }

    time_t current_time = time(NULL);
    record *new_record = malloc(sizeof(record));
    new_record->value = random_int(1, 1000); // Example range
    strncpy(new_record->str, str_rep, sizeof(new_record->str) - 1);

    new_record->timestamp = current_time;
    char* metadata = generate_metadata(key, dm->num_records);
    if (!metadata) {
        free(new_record);
        pthread_mutex_unlock(&dm->lock);
        return;
    }

    for (size_t i = 0; i < dm->num_records; ++i) {
        if (strcmp(dm->metadata_strings[i], metadata) == 0) {
            sync_log("Metadata conflict detected");
            free(metadata);
            free(new_record);
            pthread_mutex_unlock(&dm->lock);
            return;
        }
    }

    new_record->metadata = metadata;
    dm->records[key] = new_record;
    dm->keys[key] = key; // Example of how keys are managed
    dm->metadata_strings[key] = metadata;

    async_log("Record created successfully");

    pthread_mutex_unlock(&dm->lock);
}

void archive_record(DataManager* dm, size_t idx) {
    if (idx >= dm->num_records) return;

    // Mock archiving logic; in practice, this would save to disk or another storage medium
    free(dm->records[idx]->str);
    free(dm->records[idx]->metadata);

    record *archived_record = malloc(sizeof(record));
    if (!archived_record) {
        sync_log("Failed to allocate memory for archived record");
        return;
    }

    // Copy data into the new structure as an example
    archived_record->value = dm->records[idx]->value;
    time(&archived_record->timestamp);
    archived_record->metadata = strdup(dm->metadata_strings[idx]);

    free(dm->records[idx]);
    dm->records[idx] = archived_record;

    async_log("Record archived");
}

int main() {
    srand(time(NULL));

    DataManager *dm = init_data_manager(10, 3600); // Example values
    if (!dm) return EXIT_FAILURE;

    add_record(dm, 0, "First record");
    add_record(dm, 1, "Second record");

    sleep(5);

    finalize_data_manager(dm);
    return EXIT_SUCCESS;
}
