```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RETENTION_DAYS 7
#define MAX_CACHE_ITEMS 1000000

typedef struct Measurement {
    double *results;
    size_t result_count;
} Measurement;

typedef struct NetworkPerformanceMetrics {
    time_t timestamp;
    char session_id[64];
    Measurement measurement;
    struct Node* next;
    struct Node* prev;
} MetricsNode, *MetricsNodePtr;

typedef struct {
    MetricsNodePtr head;
    MetricsNodePtr tail;
    size_t count;
    pthread_mutex_t lock;
    int retention_days; // Configurable at runtime
    time_t last_cleanup_time;
} DoublyLinkedList;

DoublyLinkedList* create_metrics_list(int retention_days) {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->count = 0;
    list->retention_days = retention_days;
    time(&list->last_cleanup_time);

    // Initialize cache and logging (omitted for brevity)

    return list;
}

void cleanup_outdated_metrics(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    if ((time(NULL) - list->last_cleanup_time) < MAX_RETENTION_DAYS * 24 * 60 * 60)
        goto unlock;

    MetricsNodePtr current = list->head;
    while (current) {
        if ((time(NULL) - current->timestamp) > list->retention_days * 24 * 60 * 60) {
            MetricsNodePtr to_delete = current;
            current = current->next;

            // Log deletion
            printf("Deleting outdated metric for session ID: %s\n", to_delete->session_id);

            if (to_delete->prev)
                to_delete->prev->next = to_delete->next;
            else
                list->head = to_delete->next;

            if (to_delete->next)
                to_delete->next->prev = to_delete->prev;
            else
                list->tail = to_delete->prev;

            free(to_delete->measurement.results);
            free(to_delete);

            list->count--;
        } else {
            current = current->next;
        }
    }

unlock:
    list->last_cleanup_time = time(NULL);
    pthread_mutex_unlock(&list->lock);
}

int insert_metric(DoublyLinkedList* list, const char* session_id, double* results, size_t result_count) {
    MetricsNodePtr new_node = (MetricsNodePtr)malloc(sizeof(MetricsNode));
    if (!new_node)
        return -1;

    time(&new_node->timestamp);
    strncpy(new_node->session_id, session_id, sizeof(new_node->session_id) - 1);
    new_node->measurement.results = (double*)malloc(result_count * sizeof(double));
    memcpy(new_node->measurement.results, results, result_count * sizeof(double));
    new_node->measurement.result_count = result_count;
    new_node->next = new_node->prev = NULL;

    pthread_mutex_lock(&list->lock);

    if (!list->head)
        list->head = list->tail = new_node;
    else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    list->count++;
    printf("Inserted metric for session ID: %s\n", session_id);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void destroy_metrics_list(DoublyLinkedList* list) {
    MetricsNodePtr current = list->head;
    while (current) {
        MetricsNodePtr to_delete = current;
        current = current->next;

        free(to_delete->measurement.results);
        free(to_delete);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Additional functions for querying, caching, and logging would be implemented here.

int main() {
    DoublyLinkedList* metrics_list = create_metrics_list(3); // Retention of 3 days

    double results[5] = {100.0, 200.0, 150.0, 300.0, 250.0};
    insert_metric(metrics_list, "session_1", results, 5);

    cleanup_outdated_metrics(metrics_list);

    destroy_metrics_list(metrics_list);
    return 0;
}
