#include <iostream>
#include <vector>
#include <memory>
#include <random>
#include <mutex>
#include <algorithm>
#include <numeric> // For accumulate
#include <cmath>    // For sqrt

// External logging library simulation
#define LOG_INFO(msg) std::cout << "INFO: " << msg << std::endl;
#define LOG_ERROR(msg) std::cerr << "ERROR: " << msg << std::endl;

namespace AdvancedMemoryManagement {

class MemoryManager {
public:
    struct record {
        int value;
    };

    struct PHY_STATS_PDU_T {
        int TX_POWER_LEVELS;
        int RECEIVED_SIGNAL_STRENGTH;
        struct LINK_LAYER_STATS {
            double SNR;
        } LINK_LAYER_STATS;
    };

private:
    static const size_t MAX_SAMPLES = 1000;

    std::vector<long> offsetArray;
    std::vector<int> keyArray;
    std::vector<record> recordArray;
    std::vector<PHY_STATS_PDU_T> phyStatsArray;

    std::mt19937 rng;
    std::mutex mtx; // Mutex for thread safety

public:
    MemoryManager() : rng(std::random_device{}()) {
        if (!initializeMemory(MAX_SAMPLES)) {
            LOG_ERROR("Initialization failed");
        }
    }

    ~MemoryManager() {
        offsetArray.clear();
        keyArray.clear();
        recordArray.clear();
        phyStatsArray.clear();
    }

    bool initializeMemory(size_t size) {
        std::lock_guard<std::mutex> lock(mtx);

        try {
            offsetArray.resize(size);
            keyArray.resize(size);
            recordArray.resize(size);

            // Initialize offsets, keys, and records with unique values
            for (size_t i = 0; i < size; ++i) {
                offsetArray[i] = static_cast<long>(rng());
                keyArray[i] = rng() % 10000;
                recordArray[i].value = static_cast<int>(rng() % 100);
            }

            phyStatsArray.reserve(MAX_SAMPLES);

            for (size_t i = 0; i < size && phyStatsArray.size() < MAX_SAMPLES; ++i) {
                PHY_STATS_PDU_T pdu;
                pdu.TX_POWER_LEVELS = rng() % 5;
                pdu.RECEIVED_SIGNAL_STRENGTH = rng() % 100;
                pdu.LINK_LAYER_STATS.SNR = static_cast<double>(rng()) / rng.max();

                phyStatsArray.push_back(pdu);
            }

            LOG_INFO("Memory initialized successfully");
            return true;
        } catch (const std::bad_alloc& e) {
            LOG_ERROR("Memory allocation failed: " + std::string(e.what()));
            return false;
        }
    }

    void addSample(const PHY_STATS_PDU_T& sample) {
        std::lock_guard<std::mutex> lock(mtx);

        if (phyStatsArray.size() >= MAX_SAMPLES) {
            LOG_INFO("Maximum number of samples reached");
            return;
        }

        phyStatsArray.push_back(sample);
    }

    void computeStatistics() const {
        std::lock_guard<std::mutex> lock(mtx);

        if (phyStatsArray.empty()) {
            LOG_ERROR("No data to compute statistics");
            return;
        }

        double mean = 0.0, variance = 0.0;

        auto strengths = std::vector<int>(phyStatsArray.size());
        std::transform(phyStatsArray.begin(), phyStatsArray.end(), strengths.begin(),
                       [](const PHY_STATS_PDU_T& pdu) { return pdu.RECEIVED_SIGNAL_STRENGTH; });

        mean = std::accumulate(strengths.begin(), strengths.end(), 0.0) / strengths.size();

        variance = std::inner_product(strengths.begin(), strengths.end(), strengths.begin(), 0.0,
                                      [](double a, double b) { return a + b; },
                                      [mean](int x, int y) { return (x - mean) * (y - mean); }) / strengths.size();

        double stddev = std::sqrt(variance);

        LOG_INFO("Mean: " + std::to_string(mean));
        LOG_INFO("Variance: " + std::to_string(variance));
        LOG_INFO("Standard Deviation: " + std::to_string(stddev));
    }
};

} // namespace AdvancedMemoryManagement

int main() {
    AdvancedMemoryManagement::MemoryManager manager;
    manager.computeStatistics();

    return 0;
}
