#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <stdint.h>

#define INITIAL_CAPACITY 1000
#define MAX_MESSAGES 10000
#define LOG_INTERVAL_SECONDS 60

typedef struct {
    int message_type;
    char content[256];
} NAS_Message;

typedef struct {
    // Placeholder for TLVEncoder structure
    int encoder_state;
} TLVEncoder;

typedef struct {
    TLVEncoder tlv_encoder;
    NAS_Message nas_message;
} LTE_DL_CCCH_Message_Type1_T;

typedef struct {
    LTE_DL_CCCH_Message_Type1_T *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MessageArray;

static volatile int active_threads = 0;
static volatile int encoded_messages = 0;

void log_message(const char *message) {
    printf("%s\n", message);
}

int random_nas_message_type() {
    return rand() % 10; // Example range for NAS message types
}

void generate_random_content(char *content, size_t size) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < size - 1; ++i) {
        content[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    content[size - 1] = '\0';
}

void resize_message_array(MessageArray *array, size_t new_capacity) {
    pthread_mutex_lock(&array->lock);
    LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(array->messages, new_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (new_messages) {
        array->messages = new_messages;
        array->capacity = new_capacity;
    } else {
        log_message("Failed to resize message array.");
    }
    pthread_mutex_unlock(&array->lock);
}

void initialize_nas_message(NAS_Message *message) {
    message->message_type = random_nas_message_type();
    generate_random_content(message->content, sizeof(message->content));
}

void encode_message(LTE_DL_CCCH_Message_Type1_T *msg) {
    // Placeholder for encoding logic
    msg->tlv_encoder.encoder_state = 1; // Simulate encoding
}

void *thread_function(void *arg) {
    MessageArray *array = (MessageArray *)arg;
    active_threads++;

    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        if (array->capacity < MAX_MESSAGES) {
            resize_message_array(array, array->capacity * 2);
        } else {
            log_message("Maximum message capacity reached.");
            pthread_mutex_unlock(&array->lock);
            active_threads--;
            return NULL;
        }
    }

    LTE_DL_CCCH_Message_Type1_T *msg = &array->messages[array->count++];
    initialize_nas_message(&msg->nas_message);
    encode_message(msg);

    encoded_messages++;
    pthread_mutex_unlock(&array->lock);

    active_threads--;
    return NULL;
}

void log_system_state() {
    while (1) {
        sleep(LOG_INTERVAL_SECONDS);
        printf("Active threads: %d, Encoded messages: %d\n", active_threads, encoded_messages);
    }
}

void initAndEncodeMessages(size_t num_threads) {
    MessageArray array = {NULL, INITIAL_CAPACITY, 0};
    pthread_mutex_init(&array.lock, NULL);

    pthread_t *threads = malloc(num_threads * sizeof(pthread_t));
    if (!threads) {
        log_message("Failed to allocate memory for threads.");
        return;
    }

    pthread_t logger_thread;
    pthread_create(&logger_thread, NULL, (void *(*)(void *))log_system_state, NULL);

    for (size_t i = 0; i < num_threads; ++i) {
        array.messages = malloc(INITIAL_CAPACITY * sizeof(LTE_DL_CCCH_Message_Type1_T));
        if (!array.messages) {
            log_message("Failed to allocate initial memory for messages.");
            break;
        }
        pthread_create(&threads[i], NULL, thread_function, (void *)&array);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(array.messages);
    free(threads);
    pthread_mutex_destroy(&array.lock);
}

int main() {
    srand(time(NULL));
    initAndEncodeMessages(10); // Example with 10 concurrent threads
    return 0;
}
