// Function prototypes for utility functions used within the main function.
bool allocate_and_check(int *array, size_t size);
void free_all(void **allocations, size_t count);

// Mutex lock for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int manage_memory_allocation(size_t num_offsets, long offset_min, long offset_max,
                             size_t num_keys, int key_min, int key_max,
                             size_t num_records, int record_min, int record_max) {

    pthread_mutex_lock(&mutex);

    // Log function entry
    printf("Entering memory management function.\n");

    void *allocations[5];  // To track all allocations for cleanup.
    long *offsets;
    int *keys;
    Record *records;

    bool success = true;

    // Allocate and initialize offset array
    if (!(offsets = malloc(num_offsets * sizeof(long)))) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    allocations[0] = offsets;

    srand(time(NULL));
    bool unique_offset_found;
    for (size_t i = 0; i < num_offsets; ++i) {
        do {
            unique_offset_found = true;
            long offset_value = rand() % (offset_max - offset_min + 1) + offset_min;

            // Check uniqueness
            for (size_t j = 0; j < i; ++j) {
                if (offsets[j] == offset_value) {
                    unique_offset_found = false;
                    break;
                }
            }

        } while (!unique_offset_found);

        offsets[i] = offset_value;
    }

    // Allocate and initialize key array
    if (!(keys = malloc(num_keys * sizeof(int)))) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        success = false;
        goto cleanup;
    }
    allocations[1] = keys;

    bool unique_key_found;
    for (size_t i = 0; i < num_keys; ++i) {
        do {
            unique_key_found = true;
            int key_value = rand() % (key_max - key_min + 1) + key_min;

            // Check uniqueness
            for (size_t j = 0; j < i; ++j) {
                if (keys[j] == key_value) {
                    unique_key_found = false;
                    break;
                }
            }

        } while (!unique_key_found);

        keys[i] = key_value;
    }

    // Allocate and initialize records array
    if (!(records = malloc(num_records * sizeof(Record)))) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        success = false;
        goto cleanup;
    }
    allocations[2] = records;

    bool unique_record_found;
    for (size_t i = 0; i < num_records; ++i) {
        do {
            unique_record_found = true;
            int record_value = rand() % (record_max - record_min + 1) + record_min;

            // Check uniqueness
            for (size_t j = 0; j < i; ++j) {
                if (records[j].value == record_value) {
                    unique_record_found = false;
                    break;
                }
            }

        } while (!unique_record_found);

        records[i].value = record_value;
    }

    // Log successful memory allocation and initialization
    printf("Memory allocation and initialization successful.\n");

cleanup:
    if (!success) {
        free_all(allocations, 3);  // Only three allocations were attempted.
    }

    pthread_mutex_unlock(&mutex);

    return success ? 0 : -1;
}

// Utility function to check allocation status
bool allocate_and_check(int *array, size_t size) {
    if (array == NULL && size != 0) {
        fprintf(stderr, "Allocation failed\n");
        return false;
    }
    return true;
}

// Free all allocated memory and log details
void free_all(void **allocations, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (allocations[i] != NULL) {
            free(allocations[i]);
        }
    }

    // Log cleanup completion
    printf("Memory deallocation completed.\n");
}

int main() {
