                                 num_keys, key_min, key_max,
                                 num_records, record_min, record_max) != 0) {
        fprintf(stderr, "Memory management failed.\n");
        return EXIT_FAILURE;
    }

    printf("Memory management completed successfully.\n");

    return EXIT_SUCCESS;
}
