#define MAX_MEMORY_LIMIT 1024 * 1024 // Define maximum memory limit, e.g., 1MB for example
#define POOL_SIZE 10                 // Adjust as necessary based on performance evaluation

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned int CRCFLAG;         // Randomly set CRC flag
        // Additional fields can be added here in the future without major refactoring
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data_array;
    size_t array_size;
    pthread_mutex_t lock;  // Mutex for thread safety
    pthread_cond_t cond_var;
    int available_slots;
} SharedDataPool;

SharedDataPool pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, POOL_SIZE};

void log_message(const char *message) {
    printf("%s\n", message); // Simple logging for demonstration
}

int initialize_pool(size_t num_elements) {
    if (num_elements > MAX_MEMORY_LIMIT / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        log_message("Memory limit exceeded.");
        return -1;
    }

    pool.data_array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool.data_array) {
        log_message("Memory allocation failed.");
        return -1;
    }

    pool.array_size = num_elements;
    pool.available_slots = POOL_SIZE; // Start with the maximum number of concurrent slots
    for (size_t i = 0; i < num_elements; ++i) {
        pool.data_array[i].RX_UE_INFORMATION_TAG = rand();  // Placeholder: Replace with real data source
        pool.data_array[i].RNTI = rand();                    // Placeholder: Replace with real data source
        pool.data_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;  // Randomly set CRC flag to 0 or 1
    }

    log_message("Pool initialized successfully.");
    return 0;
}

void *populate_data(void *arg) {
    size_t index;

    pthread_mutex_lock(&pool.lock);
    while (pool.available_slots == 0) {
        pthread_cond_wait(&pool.cond_var, &pool.lock);
    }

    // Simulate delay and variability from external data source
    if (rand() % 10 < 3) {  // Simulate occasional delay
        sleep(1);
    }

    index = rand() % pool.array_size;
    pool.available_slots--;

    pthread_mutex_unlock(&pool.lock);

    // Perform validation on the retrieved structure
    if (pool.data_array[index].RX_UE_INFORMATION_TAG == 0 || 
        pool.data_array[index].RNTI == 0) {
        log_message("Data integrity check failed.");
    } else {
        log_message("Data integrity check passed.");
    }

    // Release resources, adjust available slots
    pthread_mutex_lock(&pool.lock);
    pool.available_slots++;
    pthread_cond_signal(&pool.cond_var);
    pthread_mutex_unlock(&pool.lock);

    return NULL;
}

int main() {
    srand(time(NULL));  // Seed random number generator

    size_t num_elements = POOL_SIZE;  // Initial size, can be tuned
    if (initialize_pool(num_elements) != 0) {
        return EXIT_FAILURE;
    }

    pthread_t threads[POOL_SIZE];
    for (int i = 0; i < POOL_SIZE; ++i) {
        if (pthread_create(&threads[i], NULL, populate_data, NULL) != 0) {
            log_message("Thread creation failed.");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < POOL_SIZE; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(pool.data_array);
    log_message("Program completed successfully.");
    return EXIT_SUCCESS;
}
