    char **headers;
    size_t header_count;
} HttpRequest;

typedef struct {
    RequestEncoder encoder;
    HttpRequest request;
} HTTP_Request;

typedef struct {
    HTTP_Request *requests;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond_var;
    pthread_rwlock_t rwlock;
} HTTP_RequestPool;

HTTP_RequestPool *create_request_pool() {
    HTTP_RequestPool *pool = malloc(sizeof(HTTP_RequestPool));
    pool->requests = malloc(INITIAL_CAPACITY * sizeof(HTTP_Request));
    pool->count = 0;
    pool->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond_var, NULL);
    pthread_rwlock_init(&pool->rwlock, NULL);

    return pool;
}

void destroy_request_pool(HTTP_RequestPool *pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->requests[i].request.url);
        for (size_t j = 0; j < pool->requests[i].request.header_count; ++j) {
            free(pool->requests[i].request.headers[j]);
        }
        free(pool->requests[i].request.headers);
    }
    free(pool->requests);
    pthread_mutex_destroy(&pool->mutex);
    pthread_cond_destroy(&pool->cond_var);
    pthread_rwlock_destroy(&pool->rwlock);
    free(pool);
}

void resize_request_pool(HTTP_RequestPool *pool, size_t new_capacity) {
    HTTP_Request *new_requests = realloc(pool->requests, new_capacity * sizeof(HTTP_Request));
    if (new_requests) {
        pool->requests = new_requests;
        pool->capacity = new_capacity;
    }
}

void add_http_request(HTTP_RequestPool *pool, const char *url, char **headers, size_t header_count) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->count == pool->capacity) {
        resize_request_pool(pool, pool->capacity * 2);
    }

    HTTP_Request new_request;
    new_request.request.url = strdup(url);
    new_request.request.headers = malloc(header_count * sizeof(char *));
    new_request.request.header_count = header_count;

    for (size_t i = 0; i < header_count; ++i) {
        new_request.request.headers[i] = strdup(headers[i]);
    }

    pool->requests[pool->count++] = new_request;

    pthread_mutex_unlock(&pool->mutex);
}

void log_metrics(HTTP_RequestPool *pool) {
    // Dummy implementation for logging
    printf("Active clients: %zu\n", pool->count);
    printf("Current memory usage: ... (bytes)\n");
}

int main() {
    HTTP_RequestPool *request_pool = create_request_pool();

    char *headers[] = {"Host: example.com", "Content-Type: application/json"};
    add_http_request(request_pool, "http://example.com/api/resource", headers, 2);

    log_metrics(request_pool);

    destroy_request_pool(request_pool);
    return 0;
}
