namespace FileProcessor {

class FileMetadata {
public:
    std::string filePath;
    size_t fileSize;
    std::chrono::system_clock::time_point lastModified;

    FileMetadata() = default;

    FileMetadata(const std::string& path, size_t size, 
                 const std::chrono::system_clock::time_point& modified)
        : filePath(path), fileSize(size), lastModified(modified) {}

    // Ensure thread-safe access
    std::mutex mutex;

    void updateMetadata(const std::string& path, size_t size, 
                        const std::chrono::system_clock::time_point& modified) {
        std::lock_guard<std::mutex> lock(mutex);
        filePath = path;
        fileSize = size;
        lastModified = modified;
        log("File metadata updated.");
    }

    void readMetadata() const {
        std::lock_guard<std::mutex> lock(mutex);
        log("Reading file metadata: " + filePath);
    }
};

class FileReaderWriter {
public:
    static std::mt19937 rng;

    double* valuesArray;
    size_t valueCapacity, valueCount;
    std::string* keysArray;
    size_t keyCapacity, keyCount;
    std::vector<FileMetadata> fileMetadatas;

    FileReaderWriter(size_t initialSize)
        : valueCapacity(initialSize), valueCount(0),
          keyCapacity(initialSize), keyCount(0) {

        try {
            valuesArray = new double[initialSize];
            keysArray = new std::string[initialSize];
            log("Memory allocated for arrays.");
        } catch (const std::bad_alloc& e) {
            log("Failed to allocate memory: " + std::string(e.what()));
            // Clean up any partially initialized resources
            if (valuesArray) delete[] valuesArray;
            if (keysArray) delete[] keysArray;
            throw; // Re-throw after cleanup
        }
    }

    ~FileReaderWriter() {
        delete[] valuesArray;
        delete[] keysArray;
        log("Memory deallocated.");
    }

    void addMetadata(const std::string& filePath, size_t fileSize,
                     const std::chrono::system_clock::time_point& modified) {
        if (fileMetadatas.size() >= fileMetadatas.capacity()) {
            expandCapacity();
        }

        FileMetadata metadata(filePath, fileSize, modified);
        fileMetadatas.push_back(metadata);
        log("Added new file metadata.");
    }

private:
    void expandCapacity() {
        size_t newSize = fileMetadatas.capacity() == 0 ? 1 : fileMetadatas.capacity() * 2;
        fileMetadatas.reserve(newSize);
        log("Expanded vector capacity to " + std::to_string(newSize) + ".");
    }

public:
    void addValue(double value, const std::string& key) {
        if (valueCount >= valueCapacity || keyCount >= keyCapacity) {
            expandArrays();
        }

        valuesArray[valueCount++] = value;
        keysArray[keyCount++] = key;
        log("Added value and key.");
    }

private:
    void expandArrays() {
        size_t newSize = std::max(valueCapacity, keyCapacity) == 0 ? 1 : std::max(valueCapacity, keyCapacity) * 2;

        double* newValues = new double[newSize];
        std::string* newKeys = new std::string[newSize];

        if (valuesArray) {
            std::memcpy(newValues, valuesArray, valueCount * sizeof(double));
            delete[] valuesArray;
        }

        if (keysArray) {
            for (size_t i = 0; i < keyCount; ++i) {
                newKeys[i] = keysArray[i];
            }
            delete[] keysArray;
        }

        valuesArray = newValues;
        keysArray = newKeys;

        valueCapacity = newSize;
        keyCapacity = newSize;
        log("Expanded arrays to capacity " + std::to_string(newSize) + ".");
    }
};

std::mt19937 FileReaderWriter::rng(std::random_device{}());

} // namespace FileProcessor

int main() {
    try {
        FileProcessor::FileReaderWriter reader(10);

        for (int i = 0; i < 20; ++i) { // Demonstrate dynamic resizing
            double randomValue = static_cast<double>(rand()) / RAND_MAX;
            std::string key = "Key" + std::to_string(i);

            reader.addValue(randomValue, key);
        }

        auto now = std::chrono::system_clock::now();
        for (int i = 0; i < 5; ++i) { // Adding metadata entries
            FileProcessor::FileMetadata metadata(
                "file_" + std::to_string(i), 
                rand() % 10000, 
                now);
            reader.addMetadata(metadata.filePath, metadata.fileSize, metadata.lastModified);
        }
    } catch (const std::exception& e) {
        log("Error occurred: " + std::string(e.what()));
    }

    return 0;
}
