#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MESSAGES 1024
#define CACHE_LIMIT 2048

typedef struct {
    int sequence_number;
} TLVEncoder;

typedef struct {
    int message_type;
    char content[256];
} NAS_Message;

typedef struct {
    TLVEncoder encoder;
    NAS_Message nas_message;
} LTE_DL_CCCH_Message_Type1_T;

pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
int cache_counter = 0;
LTE_DL_CCCH_Message_Type1_T* message_cache[CACHE_LIMIT];

void log_error(const char* error) {
    printf("Error: %s\n", error);
}

int generate_random_message_type() {
    return rand() % 100; // Example range
}

void generate_random_content(char *content, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    if (length) {
        --length;
        for (size_t n = 0; n < length; n++) {
            content[n] = charset[rand() % (sizeof(charset) - 1)];
        }
        content[length] = '\0';
    }
}

void initialize_NAS_Message(NAS_Message* message) {
    message->message_type = generate_random_message_type();
    generate_random_content(message->content, sizeof(message->content));
}

void serialize_messages(const LTE_DL_CCCH_Message_Type1_T *messages, size_t count, unsigned char **buffer, size_t *size) {
    size_t total_size = sizeof(size_t) + count * (sizeof(TLVEncoder) + sizeof(NAS_Message));
    *buffer = malloc(total_size);
    if (!*buffer) {
        log_error("Failed to allocate memory for serialization.");
        return;
    }

    unsigned char *ptr = *buffer;
    memcpy(ptr, &count, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < count; ++i) {
        memcpy(ptr, &messages[i].encoder, sizeof(TLVEncoder));
        ptr += sizeof(TLVEncoder);
        memcpy(ptr, &messages[i].nas_message, sizeof(NAS_Message));
        ptr += sizeof(NAS_Message);
    }

    *size = total_size;
}

void deserialize_messages(const unsigned char *buffer, size_t size, LTE_DL_CCCH_Message_Type1_T **messages) {
    if (size < sizeof(size_t)) {
        log_error("Corrupted binary data: insufficient size.");
        return;
    }

    const unsigned char *ptr = buffer;
    size_t count;
    memcpy(&count, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    if ((size - sizeof(size_t)) != (count * (sizeof(TLVEncoder) + sizeof(NAS_Message)))) {
        log_error("Corrupted binary data: mismatched sizes.");
        return;
    }

    *messages = malloc(count * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!*messages) {
        log_error("Failed to allocate memory for deserialization.");
        return;
    }

    ptr = buffer + sizeof(size_t);
    for (size_t i = 0; i < count; ++i) {
        memcpy(&((*messages)[i].encoder), ptr, sizeof(TLVEncoder));
        ptr += sizeof(TLVEncoder);
        memcpy(&((*messages)[i].nas_message), ptr, sizeof(NAS_Message));
        ptr += sizeof(NAS_Message);
    }
}

int initialize_DL_CCCH_Messages(LTE_DL_CCCH_Message_Type1_T **messages_out, size_t max_messages) {
    if (max_messages > MAX_MESSAGES || !messages_out) return -1;

    pthread_mutex_lock(&cache_lock);

    *messages_out = malloc(max_messages * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!*messages_out) {
        log_error("Failed to allocate memory for messages.");
        pthread_mutex_unlock(&cache_lock);
        return -2;
    }

    int initialized_count = 0;
    for (size_t i = 0; i < max_messages && cache_counter + max_messages <= CACHE_LIMIT; ++i) {
        (*messages_out)[i].encoder.sequence_number = rand(); // Unique sequence number
        initialize_NAS_Message(&(*messages_out)[i].nas_message);

        message_cache[cache_counter++] = &(*messages_out)[i];
        initialized_count++;
    }

    pthread_mutex_unlock(&cache_lock);

    return initialized_count;
}

void evict_from_cache() {
    if (cache_counter > 0) {
        free(message_cache[--cache_counter]);
    }
}

void manage_cache_on_eviction(size_t max_messages) {
    while (cache_counter >= CACHE_LIMIT / 2 && cache_counter > max_messages) {
        evict_from_cache();
    }
}
```

