```cpp
#include <iostream>
#include <vector>
#include <unordered_set>
#include <random>
#include <mutex>
#include <thread>
#include <fstream>
#include <memory>
#include <chrono>
#include <sstream>

// Custom allocator example (simple pool allocator)
template<typename T>
class PoolAllocator {
public:
    using value_type = T;

    PoolAllocator() noexcept : pool(nullptr), next(nullptr) {}

    template<class U> constexpr PoolAllocator(const PoolAllocator<U>&) noexcept {}

    [[nodiscard]] T* allocate(std::size_t n) {
        if (n != 1) throw std::bad_alloc();
        if (!next) refill(32);
        T* result = next;
        next = reinterpret_cast<T*>(reinterpret_cast<uint8_t*>(next) + sizeof(T));
        return result;
    }

    void deallocate(T* p, std::size_t n) noexcept {
        // In a real pool allocator, you would add the memory back to the pool
    }

private:
    struct Obj {
        union { Obj* next; char payload[1]; };
    };

    static PoolAllocator* globalPool;

    void refill(size_t n) {
        auto const ptr = reinterpret_cast<Obj*>(::operator new(n * sizeof(T)));
        for (size_t i = 0; i < n - 1; ++i) {
            ptr[i].next = &ptr[i + 1];
        }
        ptr[n - 1].next = nullptr;
        Obj* oldNext = next;
        next = reinterpret_cast<T*>(ptr);
        pool = oldNext;
    }

    T* pool;
    T* next;
};

template<typename T>
PoolAllocator<T>* PoolAllocator<T>::globalPool = nullptr;

// Event structure
struct Event {
    int id;
    double probability;
};

// Logger class (placeholder for external logging framework)
class Logger {
public:
    void log(const std::string& message) {
        std::lock_guard<std::mutex> lock(mutex_);
        std::cout << "[LOG] " << message << std::endl;
    }

private:
    std::mutex mutex_;
};

// Main application class
class EventStreamProcessor {
public:
    EventStreamProcessor() : rng(std::random_device{}()) {}

    void processEvents(size_t numEvents) {
        try {
            for (size_t i = 0; i < numEvents; ++i) {
                double prob = generateUniqueProbability();
                events.emplace_back(Event{static_cast<int>(i), prob});
            }
            exportToCSV("events.csv");
        } catch (const std::exception& e) {
            logger.log(std::string("Error: ") + e.what());
        }
    }

private:
    std::vector<Event, PoolAllocator<Event>> events;
    std::unordered_set<double> probabilities;
    std::mt19937 rng;
    Logger logger;

    double generateUniqueProbability() {
        std::uniform_real_distribution<> dis(0.0, 1.0);
        double prob;
        do {
            prob = dis(rng);
        } while (!probabilities.insert(prob).second);
        return prob;
    }

    void exportToCSV(const std::string& filename) {
        std::ofstream file(filename);
        if (file.is_open()) {
            for (const auto& event : events) {
                file << event.id << "," << event.probability << "\n";
            }
            file.close();
        } else {
            logger.log("Failed to open CSV file.");
        }
    }
};

int main() {
    EventStreamProcessor processor;
    std::thread t1(&EventStreamProcessor::processEvents, &processor, 100000);
    std::thread t2(&EventStreamProcessor::processEvents, &processor, 100000);

    t1.join();
    t2.join();

    return 0;
}
```

