#define PRIORITY_LEVELS 3
#define LOG_INTERVAL 5  // seconds
#define PROCESSING_THRESHOLD 10

typedef struct {
    int message_type;
    char content[256];
} NAS_Message;

typedef struct {
    TLVEncoder encoder;
    NAS_Message nas_message;
    int urgency;  // Priority level: 0 (low) to PRIORITY_LEVELS-1 (high)
} LTE_DL_CCCH_Message_Type1_T;

typedef struct {
    LTE_DL_CCCH_Message_Type1_T *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    sem_t semaphore;
    pthread_cond_t cond_var;
    int active_threads;
    int processed_messages;
} MessageProcessor;

MessageProcessor processor = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER, SEM_INITIALIZER(0), PTHREAD_COND_INITIALIZER(), 0, 0};

void initialize_message_processor() {
    processor.capacity = INITIAL_CAPACITY;
    processor.messages = malloc(processor.capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
}

void destroy_message_processor() {
    free(processor.messages);
    pthread_mutex_destroy(&processor.mutex);
    sem_destroy(&processor.semaphore);
    pthread_cond_destroy(&processor.cond_var);
}

void resize_messages(size_t new_capacity) {
    LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(processor.messages, new_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (new_messages) {
        processor.capacity = new_capacity;
        processor.messages = new_messages;
    } else {
        log_error("Memory allocation failed during resizing.");
    }
}

void generate_random_message(NAS_Message *message) {
    message->message_type = rand() % 100;  // Example random type
    snprintf(message->content, sizeof(message->content), "Random Content %d", rand());
}

void compress_and_store(LTE_DL_CCCH_Message_Type1_T *msg) {
    // Simulate compression and storage (use external database client)
    char compressed_content[128]; // Placeholder for actual compression logic
    snprintf(compressed_content, sizeof(compressed_content), "%s (compressed)", msg->nas_message.content);

    if (!store_in_database(compressed_content)) {  // Assume this function is from the DB client library
        log_error("Failed to store compressed message in database.");
    }
}

void *process_messages_thread(void *arg) {
    while (1) {
        sem_wait(&processor.semaphore);

        pthread_mutex_lock(&processor.mutex);

        if (processor.count == 0) {
            pthread_mutex_unlock(&processor.mutex);
            break; // Exit thread if no more messages to process
        }

        LTE_DL_CCCH_Message_Type1_T *msg = &processor.messages[processor.count - 1];
        processor.count--;

        generate_random_message(&msg->nas_message);

        compress_and_store(msg);

        processor.processed_messages++;

        pthread_mutex_unlock(&processor.mutex);
    }
    return NULL;
}

void monitor_performance() {
    while (1) {
        sleep(LOG_INTERVAL);
        pthread_mutex_lock(&processor.mutex);

        log_info("Active threads: %d, Processed messages: %zu", processor.active_threads, processor.processed_messages);

        pthread_mutex_unlock(&processor.mutex);
    }
}

void *message_producer(void *arg) {
    while (1) {
        pthread_mutex_lock(&processor.mutex);

        if (processor.count >= processor.capacity && processor.capacity < MAX_MESSAGES) {
            resize_messages(processor.capacity * 2);
        }

        if (processor.count >= processor.capacity) {
            log_warning("Message buffer full. Waiting for space...");
            pthread_cond_wait(&processor.cond_var, &processor.mutex);
        } else {
            LTE_DL_CCCH_Message_Type1_T *msg = &processor.messages[processor.count++];
            msg->urgency = rand() % PRIORITY_LEVELS;  // Assign random priority level

            sem_post(&processor.semaphore);

            pthread_cond_signal(&processor.cond_var);  // Signal any waiting threads
        }

        pthread_mutex_unlock(&processor.mutex);
    }
    return NULL;
}

void processMessages() {
    initialize_message_processor();

    pthread_t monitor_thread, producer_thread;
    pthread_create(&monitor_thread, NULL, monitor_performance, NULL);

    while (1) {
        if (processor.active_threads < PROCESSING_THRESHOLD) {
            pthread_t consumer_thread;
            processor.active_threads++;
            pthread_create(&consumer_thread, NULL, process_messages_thread, NULL);
        } else {
            sleep(1);  // Wait before checking again
        }

        message_producer(NULL);
    }

    destroy_message_processor();
}

int main() {
    srand(time(NULL));
    log_info("Starting message processor...");

    processMessages();

    return 0;
}
