['Here's a C code implementation for managing memory for your described data structure, including functions to initialize, populate with random data, update, and ensure thread safety using mutexes.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRING_LENGTH 256

typedef struct Node {
    double value;
    char str[MAX_STRING_LENGTH];
} Node;

typedef struct DataBlock {
    Node* node;
    size_t counter;
} DataBlock;

typedef struct DataManager {
    DataBlock** data_blocks;
    size_t num_data_blocks;
    pthread_mutex_t lock;
} DataManager;

DataManager* create_manager(size_t initial_capacity) {
    DataManager* manager = (DataManager*)malloc(sizeof(DataManager));
    manager->data_blocks = (DataBlock**)calloc(initial_capacity, sizeof(DataBlock*));
    manager->num_data_blocks = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void free_manager(DataManager* manager) {
    for (size_t i = 0; i < manager->num_data_blocks; ++i) {
        if (manager->data_blocks[i]) {
            free(manager->data_blocks[i]->node);
            free(manager->data_blocks[i]);
        }
    }
    free(manager->data_blocks);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

Node* create_node(double value, const char* str) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->value = value;
    strncpy(node->str, str, MAX_STRING_LENGTH - 1);
    node->str[MAX_STRING_LENGTH - 1] = '\0';
    return node;
}

void populate_random_data(DataManager* manager, size_t num_blocks) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < num_blocks; ++i) {
        double value = ((double)rand() / RAND_MAX) * 100.0; // Random value between 0 and 100
        char str[MAX_STRING_LENGTH];
        snprintf(str, sizeof(str), "String %zu", rand());

        Node* node = create_node(value, str);
        DataBlock* block = (DataBlock*)malloc(sizeof(DataBlock));
        block->node = node;
        block->counter = 1; // Start with a counter of 1

        manager->data_blocks[manager->num_data_blocks++] = block;
    }

    pthread_mutex_unlock(&manager->lock);
}

void update_node_value(DataManager* manager, size_t index, double new_value) {
    if (index >= manager->num_data_blocks) return;

    pthread_mutex_lock(&manager->lock);

    Node* node = manager->data_blocks[index]->node;
    node->value = new_value;

    pthread_mutex_unlock(&manager->lock);
}

void increment_counter(DataManager* manager, size_t index) {
    if (index >= manager->num_data_blocks) return;

    pthread_mutex_lock(&manager->lock);

    manager->data_blocks[index]->counter++;

    pthread_mutex_unlock(&manager->lock);
}

int main() {
    DataManager* manager = create_manager(10);

    populate_random_data(manager, 5);

    // Example updates
    update_node_value(manager, 2, 42.0);
    increment_counter(manager, 2);

    for (size_t i = 0; i < manager->num_data_blocks; ++i) {
        printf("Block %zu: Value = %.2f, String = %s, Counter = %zu\n",
               i,
               manager->data_blocks[i]->node->value,
               manager->data_blocks[i]->node->str,
               manager->data_blocks[i]->counter);
    }

    free_manager(manager);

    return 0;
}
```

