        (*records)[i].number = ((double)rand() / RAND_MAX) * 100.0; // Random double between 0 and 100
        if ((unsigned int)i > INT_MAX - 1) { // Safeguard against integer overflow
            fprintf(stderr, "Integer key overflow\n");
            return -1;
