            size_t count = data_blocks[i]->count;
            data_blocks[i]->node_ptr = NULL;

            if (backup_nodes == NULL) {
                backup_nodes = malloc(num_blocks * max_elements_per_block * sizeof(node));
            }

            for (size_t j = 0; j < count; ++j) {
                backup_nodes[i * max_elements_per_block + j] = *(data_blocks[i]->node_ptr + j);
            }
        }
    }

    // Free resources
    free_resources(data_blocks, num_blocks, &backup_nodes);

    if (backup_nodes != NULL) {
        free(backup_nodes);
    }
}

// Initialize data blocks with random nodes
void initialize_data_blocks(data_block **data_blocks, size_t num_blocks, size_t max_elements) {
    for (size_t i = 0; i < num_blocks; ++i) {
        data_blocks[i] = malloc(sizeof(data_block));
        if (!data_blocks[i]) {
            perror("Failed to allocate memory for data block");
            exit(EXIT_FAILURE);
        }

        data_blocks[i]->node_ptr = malloc(max_elements * sizeof(node));
        if (!data_blocks[i]->node_ptr) {
            perror("Failed to allocate memory for nodes");
            free(data_blocks[i]);
            exit(EXIT_FAILURE);
        }

        // Populate nodes with random values
        populate_nodes_randomly(data_blocks[i]->node_ptr, max_elements, 0.0, 100.0);

        data_blocks[i]->count = max_elements;
        data_blocks[i]->active = rand() % 2 == 0; // Randomly mark as active or inactive
    }
}

// Free allocated resources
void free_resources(data_block *data_blocks[], size_t num_blocks, node *backup_nodes[]) {
    for (size_t i = 0; i < num_blocks; ++i) {
        if (data_blocks[i] != NULL) {
            if (data_blocks[i]->node_ptr != NULL) {
                free(data_blocks[i]->node_ptr);
            }
            free(data_blocks[i]);
        }
    }

    *backup_nodes = NULL;
}

// Populate nodes with random values
void populate_nodes_randomly(node *nodes, size_t num_nodes, double min_val, double max_val) {
    for (size_t i = 0; i < num_nodes; ++i) {
        nodes[i].value = min_val + ((double)rand() / RAND_MAX) * (max_val - min_val);
        nodes[i].str = strdup("Random String");
        nodes[i].type = rand() % 2;
    }
}
