    reading.timestamp = 1234567890.0; // Example timestamp
    reading.sensorID = rand() % 100;   // Example sensor ID
    reading.temperature = (float)(rand() % 171 - 50); // Random temperature between -50 and 120

    return reading;
}

int isValidReading(TemperatureSensorReading *reading) {
    if (reading->temperature < MIN_TEMP || reading->temperature > MAX_TEMP) {
        return 0; // Invalid
    }
    return 1; // Valid
}

void findSmallestLargestIndices(const TemperatureSensorReading *readings, int count, int *smallestIndex, int *largestIndex) {
    if (count == 0) {
        *smallestIndex = -1;
        *largestIndex = -1;
        return;
    }

    int smallest = 0, largest = 0;

    for (int i = 1; i < count; ++i) {
        if (readings[i].temperature < readings[smallest].temperature) {
            smallest = i;
        }
        if (readings[i].temperature > readings[largest].temperature) {
            largest = i;
        }
    }

    *smallestIndex = smallest;
    *largestIndex = largest;
}
