#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define entry structure
typedef struct Entry {
    long timestamp;
    int status_code;
    char *message;
    time_t expiration_time;  // Optional expiration duration in seconds
} Entry;

// Linked list node
typedef struct Node {
    Entry data;
    struct Node* next;
} Node;

// Dynamic list structure with locks for concurrency
typedef struct DynamicList {
    Node* head;
    size_t max_entries;
    pthread_mutex_t lock;
    void (*hash_init)(void);
    void (*hash_cleanup)(void);
} DynamicList;

// Global variables for logging and memory leak detection
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
unsigned long allocated_memory = 0;  // For tracking allocations

// Function prototypes
DynamicList* create_list(size_t max_entries, void (*hash_init)(void), void (*hash_cleanup)(void));
void destroy_list(DynamicList* list);
int add_entry(DynamicList* list, long timestamp, int status_code, const char *message, time_t expiration_duration);
int remove_entry_by_timestamp(DynamicList* list, long timestamp);
Entry get_most_recent_entry(const DynamicList* list, int (*comparator)(const Entry*, const Entry*) );
void log_operation(const char* operation_type, int error_code);

// Implementations
DynamicList* create_list(size_t max_entries, void (*hash_init)(void), void (*hash_cleanup)(void)) {
    if (!max_entries) return NULL;

    DynamicList* list = malloc(sizeof(DynamicList));
    allocated_memory += sizeof(DynamicList);
    pthread_mutex_lock(&log_lock);
    log_file = fopen("operations.log", "a");
    pthread_mutex_unlock(&log_lock);

    if (list == NULL || !pthread_mutex_init(&(list->lock), NULL) || !log_file) {
        destroy_list(list);  // Cleanup on failure
        return NULL;
    }

    list->head = NULL;
    list->max_entries = max_entries;
    list->hash_init = hash_init ? hash_init : NULL;
    list->hash_cleanup = hash_cleanup ? hash_cleanup : NULL;

    if (list->hash_init) {
        list->hash_init();
    }

    return list;
}

void destroy_list(DynamicList* list) {
    pthread_mutex_lock(&log_lock);
    if (log_file) {
        fclose(log_file);
    }
    pthread_mutex_unlock(&log_lock);

    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current->data.message);
        free(current);
        allocated_memory -= sizeof(Node) + strlen(current->data.message) + 1;
        current = next;
    }

    if (list->hash_cleanup) {
        list->hash_cleanup();
    }

    pthread_mutex_destroy(&(list->lock));
    free(list);
    allocated_memory -= sizeof(DynamicList);

    // Report memory leaks
    if (allocated_memory > 0) {
        fprintf(stderr, "Memory leak detected: %lu bytes unaccounted for.\n", allocated_memory);
    }
}

int add_entry(DynamicList* list, long timestamp, int status_code, const char *message, time_t expiration_duration) {
    pthread_mutex_lock(&(list->lock));

    if (expansion_needed(list)) {  // Custom function to determine need for expansion
        log_operation("add", -1);  // Error: List full
        pthread_mutex_unlock(&(list->lock));
        return -1;  // Return error code indicating failure
    }

    Node *new_node = malloc(sizeof(Node));
    allocated_memory += sizeof(Node);
    if (new_node == NULL) {
        log_operation("add", -2);  // Error: Memory allocation failed
        pthread_mutex_unlock(&(list->lock));
        return -2;
    }

    new_node->data.timestamp = timestamp;
    new_node->data.status_code = status_code;
    new_node->data.message = strdup(message);
    allocated_memory += strlen(message) + 1;
    if (new_node->data.message == NULL) {
        free(new_node);
        allocated_memory -= sizeof(Node);
        log_operation("add", -3);  // Error: Message duplication failed
        pthread_mutex_unlock(&(list->lock));
        return -3;
    }

    new_node->data.expiration_time = expiration_duration ? (time(NULL) + expiration_duration) : 0;
    new_node->next = list->head;
    list->head = new_node;

    log_operation("add", 0);  // Successful operation

    pthread_mutex_unlock(&(list->lock));
    return 0;  // Success
}

int remove_entry_by_timestamp(DynamicList* list, long timestamp) {
    pthread_mutex_lock(&(list->lock));

    Node *current = list->head;
    Node *prev = NULL;

    while (current != NULL && current->data.timestamp != timestamp) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        log_operation("remove", -1);  // Error: Entry not found
        pthread_mutex_unlock(&(list->lock));
        return -1;  // Return error code indicating failure
    }

    if (prev == NULL) {  // Removing head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->data.message);
    allocated_memory -= strlen(current->data.message) + 1;
    free(current);
    allocated_memory -= sizeof(Node);

    log_operation("remove", 0);  // Successful operation

    pthread_mutex_unlock(&(list->lock));
    return 0;  // Success
}

Entry get_most_recent_entry(const DynamicList* list, int (*comparator)(const Entry*, const Entry*)) {
    pthread_mutex_lock(&((DynamicList*)list)->lock);

    if (list->head == NULL) {
        log_operation("get", -1);  // Error: List is empty
        pthread_mutex_unlock(&((DynamicList*)list)->lock);
        return (Entry){0};  // Return an empty entry as error indication
    }

    Node *current = list->head;
    Entry* most_recent = &current->data;

    while (current->next != NULL) {
        if (!comparator || comparator(&current->data, most_recent) > 0) {
            most_recent = &current->data;
        }
        current = current->next;
    }

    log_operation("get", 0);  // Successful operation

    pthread_mutex_unlock(&((DynamicList*)list)->lock);
    return *most_recent;  // Return the most recent entry
}

void log_operation(const char* operation_type, int error_code) {
    time_t now = time(NULL);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));

    pthread_mutex_lock(&log_lock);
    fprintf(log_file, "[%s] Operation: %s, Error Code: %d\n", time_str, operation_type, error_code);
    fflush(log_file);  // Ensure the log is written immediately
    pthread_mutex_unlock(&log_lock);
}

// Helper function to determine if list expansion (or entry removal) is needed
int expansion_needed(DynamicList* list) {
    size_t count = 0;
    Node *current = list->head;

    while (current != NULL && count < list->max_entries) {
        if ((time(NULL) > current->data.expiration_time)) {
            // Automatically remove expired entries to make space
            Node *expired_node = current;
            current = current->next;
            free(expired_node->data.message);
            allocated_memory -= strlen(expired_node->data.message) + 1;
            free(expired_node);
            allocated_memory -= sizeof(Node);
        } else {
            count++;
            current = current->next;
        }
    }

    return (count >= list->max_entries);
}
