import <pthread.h>
import <string.h>

#define INITIAL_SIZE 10
#define RESIZE_FACTOR 2
#define MAX_MESSAGES 1000

typedef struct {
    int messageType;
    char content[256];
} NAS_Message;

typedef struct {
    // Placeholder for TLVEncoder structure and methods
} TLVEncoder;

typedef struct {
    TLVEncoder encoder;
    NAS_Message nasMessage;
} LTE_DL_CCCH_Message_Type1_T;

typedef struct {
    LTE_DL_CCCH_Message_Type1_T *messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MessageArray;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int generate_random_message_type() {
    return rand() % 10; // Example range
}

char* generate_random_content(size_t length) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *random_string = malloc(length + 1);
    if (!random_string) {
        log_error("Failed to allocate memory for random content");
        return NULL;
    }

    for (size_t i = 0; i < length; ++i) {
        int key = rand() % (int)(sizeof(charset) - 1);
        random_string[i] = charset[key];
    }
    random_string[length] = '\0';
    return random_string;
}

void resize_message_array(MessageArray *array) {
    size_t new_capacity = array->capacity * RESIZE_FACTOR;
    if (new_capacity > MAX_MESSAGES) {
        log_error("Reached maximum capacity, cannot resize further");
        return;
    }

    LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(array->messages, new_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!new_messages) {
        log_error("Failed to reallocate memory for message array");
        return;
    }

    array->messages = new_messages;
    array->capacity = new_capacity;
}

void init_message_array(MessageArray *array) {
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
    array->capacity = INITIAL_SIZE;
    array->messages = malloc(array->capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!array->messages) {
        log_error("Failed to allocate initial memory for message array");
        pthread_mutex_destroy(&array->lock);
    }
}

void populate_message_array(MessageArray *array) {
    pthread_mutex_lock(&array->lock);

    while (array->count < array->capacity) {
        LTE_DL_CCCH_Message_Type1_T *message = &array->messages[array->count];

        // Initialize TLVEncoder (placeholder)
        // message->encoder = initialize_encoder();

        message->nasMessage.messageType = generate_random_message_type();
        char *content = generate_random_content(128);
        if (!content) {
            pthread_mutex_unlock(&array->lock);
            return;
        }
        strncpy(message->nasMessage.content, content, sizeof(message->nasMessage.content));

        array->count++;
    }

    if (array->count == array->capacity) {
        resize_message_array(array);
    }

    pthread_mutex_unlock(&array->lock);
}

void cleanup_message_array(MessageArray *array) {
    free(array->messages);
    pthread_mutex_destroy(&array->lock);
}

// Thread function
void* thread_function(void *arg) {
    MessageArray *array = (MessageArray *)arg;
    populate_message_array(array);
    return NULL;
}

int main() {
    srand(time(NULL));

    const int num_threads = 4;
    pthread_t threads[num_threads];
    MessageArray message_arrays[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        init_message_array(&message_arrays[i]);
        pthread_create(&threads[i], NULL, thread_function, &message_arrays[i]);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
        cleanup_message_array(&message_arrays[i]);
    }

    return 0;
}
