#include <chrono>
#include <unordered_map>
#include <atomic>
#include <fstream>

// Using an external logging library (e.g., spdlog)
#define SPDLOG_STATIC
#include "spdlog/spdlog.h"
#include "spdlog/sinks/basic_file_sink.h"

namespace DataManagement {

class Transaction {
public:
    int value;
    std::chrono::system_clock::time_point timestamp;

    Transaction(int val) : value(val), timestamp(std::chrono::system_clock::now()) {}
};

class DataManager {
private:
    static std::mt19937 rng; // Static member for Mersenne Twister RNG
    std::array<double, 100> doublesArray;
    std::vector<std::string> stringKeys;
    std::vector<Transaction> transactions;

    mutable std::mutex mtx;
    std::condition_variable cv;
    size_t cacheLimit = 1000; // Example cache limit

public:
    DataManager() {
        spdlog::info("DataManager initialized");
    }

    ~DataManager() {
        spdlog::info("DataManager destroyed");
    }

    void updateData(std::vector<Transaction>& newTransactions) {
        std::unique_lock<std::mutex> lock(mtx);
        transactions.insert(transactions.end(), newTransactions.begin(), newTransactions.end());
        if (transactions.size() > cacheLimit) {
            evictOldTransactions();
        }
        spdlog::info("Updated data with {} new transactions", newTransactions.size());
    }

    void readData(size_t index, double& resultDouble, std::string& resultString) {
        std::shared_lock<std::mutex> lock(mtx);
        if (index < doublesArray.size()) {
            resultDouble = doublesArray[index];
        } else {
            spdlog::error("Invalid index for double array: {}", index);
            throw std::out_of_range("Index out of range");
        }

        if (index < stringKeys.size()) {
            resultString = stringKeys[index];
        } else {
            spdlog::error("Invalid index for string keys: {}", index);
            throw std::out_of_range("Index out of range");
        }

        spdlog::info("Read data at index {}", index);
    }

    void evictOldTransactions() {
        if (transactions.size() > cacheLimit) {
            transactions.erase(transactions.begin(), transactions.begin() + (transactions.size() - cacheLimit));
            spdlog::warn("Evicted old transactions to maintain cache limit");
        }
    }

    static std::mt19937& getRNG() {
        return rng;
    }
};

// Initialize the static RNG member
std::mt19937 DataManager::rng(std::random_device{}());

void configureLogging() {
    auto logger = spdlog::basic_logger_mt("file_logger", "logs/log.txt");
    spdlog::set_default_logger(logger);
    spdlog::set_level(spdlog::level::info); // Set global log level to info
}

void periodicUpdate(DataManager& manager) {
    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(5)); // Simulate delay

        try {
            std::vector<Transaction> newTransactions;
            for (int i = 0; i < 10; ++i) { // Simulate fetching transactions
                newTransactions.emplace_back(DataManager::getRNG()());
            }
            manager.updateData(newTransactions);
        } catch (const std::exception& e) {
            spdlog::error("Error during periodic update: {}", e.what());
        }
    }
}

} // namespace DataManagement

int main() {
    using namespace DataManagement;

    configureLogging();

    DataManager dataManager;

    // Launch a thread to simulate external updates
    std::thread updaterThread(periodicUpdate, std::ref(dataManager));

    try {
        double resultDouble;
        std::string resultString;

        dataManager.readData(0, resultDouble, resultString);
        spdlog::info("Read double: {}, string: {}", resultDouble, resultString);
    } catch (const std::exception& e) {
        spdlog::error("Error during read operation: {}", e.what());
    }

    if (updaterThread.joinable()) {
        updaterThread.detach(); // Detach the thread for periodic updates
    }

    return 0;
}
```

### Key Features:

- **Concurrency Control**: Uses `std::mutex` and `std::shared_lock` for thread-safe read/write operations.
- **Memory Management**: Dynamic resizing of vectors, with eviction logic to maintain cache limits.
- **Logging**: Utilizes the `spdlog` library for logging operations, errors, and memory usage.
- **Random Number Generation**: Uses a static Mersenne Twister RNG.
- **Periodic Updates**: Simulates external data updates in a separate thread.
- **Error Handling**: Includes basic error handling with meaningful logs.

### Notes:

- This code assumes the presence of `spdlog` for logging. You need to include it in your project.
- The periodic update function simulates fetching new transactions every 5 seconds.
- Error handling is minimal and can be expanded based on specific requirements.
- Adjust cache limits, array sizes, and other parameters as needed for your use case.']

