#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
import time.h

// Define constants
#define MAX_SESSIONS 100000000
#define MAX_CONCURRENT_USERS_PER_SERVER 100
#define TOTAL_ACTIVE_SERVERS 500
#define MAX_INACTIVITY_THRESHOLD 1800 // 30 minutes in seconds

// Session structure
typedef struct {
    char session_id[256];
    time_t timestamp;
    char *attributes; // JSON or other complex data structures
} Session;

// Global variables
Session **sessions = NULL;
pthread_mutex_t session_mutexes[MAX_SESSIONS] = {0};
int current_sessions = 0;
time_t inactivity_threshold = MAX_INACTIVITY_THRESHOLD;
char log_verbosity = 'M'; // M: Minimal, D: Detailed

// Logging function
void log_operation(const char *operation, const char *session_id) {
    if (log_verbosity == 'D' || (log_verbosity == 'M' && time(NULL) % 10 == 0)) {
        printf("[%s] Operation: %s on Session ID: %s\n", __func__, operation, session_id);
    }
}

// Function to initialize session storage
void init_session_storage() {
    sessions = malloc(MAX_SESSIONS * sizeof(Session *));
    for (int i = 0; i < MAX_SESSIONS; ++i) {
        pthread_mutex_init(&session_mutexes[i], NULL);
        sessions[i] = NULL;
    }
}

// Function to clean up inactive sessions
void cleanup_inactive_sessions() {
    time_t current_time = time(NULL);
    for (int i = 0; i < current_sessions; ++i) {
        if (sessions[i]) {
            pthread_mutex_lock(&session_mutexes[i]);
            if ((current_time - sessions[i]->timestamp) > inactivity_threshold) {
                free(sessions[i]->attributes);
                free(sessions[i]);
                sessions[i] = NULL;
                log_operation("Cleanup", sessions[i]->session_id);
            }
            pthread_mutex_unlock(&session_mutexes[i]);
        }
    }
}

// Function to insert a session
void insert_session(const char *session_id, const char *attributes) {
    pthread_mutex_lock(&session_mutexes[0]); // Example of managing access
    for (int i = 0; i < current_sessions; ++i) {
        if (!sessions[i]) {
            sessions[i] = malloc(sizeof(Session));
            strcpy(sessions[i]->session_id, session_id);
            sessions[i]->timestamp = time(NULL);
            sessions[i]->attributes = strdup(attributes);
            log_operation("Insert", session_id);
            pthread_mutex_unlock(&session_mutexes[0]);
            return;
        }
    }

    // If no empty slot, expand the array
    if (current_sessions < MAX_SESSIONS) {
        sessions[current_sessions] = malloc(sizeof(Session));
        strcpy(sessions[current_sessions]->session_id, session_id);
        sessions[current_sessions]->timestamp = time(NULL);
        sessions[current_sessions]->attributes = strdup(attributes);
        log_operation("Insert", session_id);
        current_sessions++;
    }
    pthread_mutex_unlock(&session_mutexes[0]);
}

// Function to retrieve a session
Session* get_session(const char *session_id) {
    for (int i = 0; i < current_sessions; ++i) {
        if (sessions[i]) {
            pthread_mutex_lock(&session_mutexes[i]);
            if (strcmp(sessions[i]->session_id, session_id) == 0) {
                sessions[i]->timestamp = time(NULL);
                log_operation("Get", session_id);
                pthread_mutex_unlock(&session_mutexes[i]);
                return sessions[i];
            }
            pthread_mutex_unlock(&session_mutexes[i]);
        }
    }
    return NULL;
}

// Function to delete a session
void delete_session(const char *session_id) {
    for (int i = 0; i < current_sessions; ++i) {
        if (sessions[i]) {
            pthread_mutex_lock(&session_mutexes[i]);
            if (strcmp(sessions[i]->session_id, session_id) == 0) {
                free(sessions[i]->attributes);
                free(sessions[i]);
                sessions[i] = NULL;
                log_operation("Delete", session_id);
                pthread_mutex_unlock(&session_mutexes[i]);
                return;
            }
            pthread_mutex_unlock(&session_mutexes[i]);
        }
    }
}

// Function to set inactivity threshold
void set_inactivity_threshold(time_t new_threshold) {
    if (new_threshold <= MAX_INACTIVITY_THRESHOLD) {
        log_operation("SetThreshold", "N/A");
        inactivity_threshold = new_threshold;
    }
}

// Main function for demonstration
int main() {
    init_session_storage();
    // Example usage
    insert_session("session1", "{\"key\":\"value\"}");
    Session *s = get_session("session1");
    if (s) printf("Session Retrieved: %s\n", s->attributes);
    delete_session("session1");

    set_inactivity_threshold(600); // 10 minutes

    cleanup_inactive_sessions();

    free(sessions);
    return 0;
}
```

**Key Considerations:**
- **Thread Safety**: Mutexes are used to protect session operations.
- **Logging**: A simple logging mechanism records operations with verbosity control.
