// Implementation
NetworkGraphNode* createNode(int deviceID, const char* status) {
    NetworkGraphNode* newNode = (NetworkGraphNode*)malloc(sizeof(NetworkGraphNode));
    if (!newNode) return NULL;

    newNode->deviceID = deviceID;
    strncpy(newNode->status, status, sizeof(newNode->status) - 1);
    newNode->status[sizeof(newNode->status) - 1] = '\0';

    // Assign a random threshold value
    srand(time(NULL) + deviceID); 
    newNode->trafficThreshold = (double)(rand() % 100) / 10.0;

    newNode->connectedPeers = NULL;
    newNode->peerCount = 0;

    return newNode;
}

void deleteNode(NetworkGraphNode* node) {
    if (!node) return;

    for (size_t i = 0; i < node->peerCount; ++i) {
        removePeer(node, node->connectedPeers[i]);
    }

    free(node->connectedPeers);
    free(node);
}

void addPeer(NetworkGraphNode* node1, NetworkGraphNode* node2) {
    if (!node1 || !node2) return;

    node1->connectedPeers = (NetworkGraphNode**)realloc(node1->connectedPeers,
                                                       (node1->peerCount + 1) * sizeof(NetworkGraphNode*));
    node2->connectedPeers = (NetworkGraphNode**)realloc(node2->connectedPeers,
                                                       (node2->peerCount + 1) * sizeof(NetworkGraphNode*));

    if (!node1->connectedPeers || !node2->connectedPeers) {
        // Handle memory allocation failure
        perror("Failed to allocate memory for peer connection");
        exit(EXIT_FAILURE);
    }

    node1->connectedPeers[node1->peerCount] = node2;
    node2->connectedPeers[node2->peerCount] = node1;

    ++node1->peerCount;
    ++node2->peerCount;
}

void removePeer(NetworkGraphNode* node1, NetworkGraphNode* node2) {
    if (!node1 || !node2) return;

    for (size_t i = 0; i < node1->peerCount; ++i) {
        if (node1->connectedPeers[i] == node2) {
            memmove(&node1->connectedPeers[i], &node1->connectedPeers[i + 1],
                    (--node1->peerCount - i) * sizeof(NetworkGraphNode*));

            for (size_t j = 0; j < node2->peerCount; ++j) {
                if (node2->connectedPeers[j] == node1) {
                    memmove(&node2->connectedPeers[j], &node2->connectedPeers[j + 1],
                            (--node2->peerCount - j) * sizeof(NetworkGraphNode*));
                    break;
                }
            }

            break;
        }
    }
}

void updateGraphWithRealTimeData(NetworkGraphNode** graph, size_t numDevices) {
    if (!graph || !numDevices) return;

    for (size_t i = 0; i < numDevices; ++i) {
        double traffic = fetchTrafficStatistics(graph[i]->deviceID);

        // Update node status or connections based on fetched traffic
        if (traffic > graph[i]->trafficThreshold) {
            strcpy(graph[i]->status, "overloaded");
            // Optionally: remove some peers to reduce load
        } else {
            strcpy(graph[i]->status, "active");
        }
    }

    // Further update logic for adding/removing nodes based on real-time data can be implemented here
}

double fetchTrafficStatistics(int deviceID) {
    // Mock implementation of fetching traffic statistics from an external API
    return (double)(rand() % 100);
}
