#include <stdio.h>
#include <stdlib.h>
import pthread.h
#include <string.h>
#include <time.h>

#define MAX_LIST_INSTANCES 10000
#define MEMORY_LIMIT (1024 * 1024 * 50) // 50 MB for example

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG data;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

// Hash table for quick lookup of RNTIs
#define HASH_TABLE_SIZE 10000
typedef struct Node {
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    struct Node* next;
} Node;

Node* hash_table[HASH_TABLE_SIZE];
pthread_mutex_t hash_table_lock = PTHREAD_MUTEX_INITIALIZER;
size_t current_memory_usage = 0;
pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned int hash_function(uint16_t rnti) {
    return rnti % HASH_TABLE_SIZE;
}

void init_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        hash_table[i] = NULL;
    }
}

void destroy_node(Node* node) {
    if (node) {
        free(node);
    }
}

void cleanup_hash_table() {
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        Node* current = hash_table[i];
        while (current) {
            Node* to_free = current;
            current = current->next;
            destroy_node(to_free);
        }
    }
}

void free_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        pthread_mutex_lock(&memory_mutex);
        current_memory_usage -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
        pthread_mutex_unlock(&memory_mutex);

        destroy_node((Node*)hash_table[hash_function(current->RNTI)]);
        free(current);
        current = next;
    }
}

int check_memory_limit(size_t size) {
    pthread_mutex_lock(&memory_mutex);
    if (current_memory_usage + size > MEMORY_LIMIT) {
        printf("Error: Memory limit exceeded\n");
        pthread_mutex_unlock(&memory_mutex);
        return 0;
    }
    current_memory_usage += size;
    pthread_mutex_unlock(&memory_mutex);
    return 1;
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* new_node) {
    if (!check_memory_limit(sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
        free(new_node);
        return;
    }

    pthread_mutex_lock(&hash_table_lock);
    unsigned int hash_index = hash_function(new_node->RNTI);

    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        printf("Memory allocation failed\n");
        free(new_node);
        pthread_mutex_unlock(&hash_table_lock);
        return;
    }

    node->RNTI = new_node->RNTI;
    node->pdu = new_node;
    node->next = hash_table[hash_index];
    hash_table[hash_index] = node;
    pthread_mutex_unlock(&hash_table_lock);

    new_node->next = *head;
    *head = new_node;
}

int find_pdu(NFAPI_CRC_INDICATION_PDU_T* head, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        if (current->RNTI == rnti) {
            return 1; // Found
        }
        current = current->next;
    }
    pthread_mutex_lock(&hash_table_lock);
    unsigned int hash_index = hash_function(rnti);
    Node* node = hash_table[hash_index];
    while (node) {
        if (node->RNTI == rnti) {
            pthread_mutex_unlock(&hash_table_lock);
            return 1; // Found
        }
        node = node->next;
    }
    pthread_mutex_unlock(&hash_table_lock);
    return 0; // Not found
}

void update_crcflag(NFAPI_CRC_INDICATION_PDU_T* head, uint32_t rx_ue_tag) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current) {
        if (current->RX_UE_INFORMATION_TAG == rx_ue_tag) {
            current->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            break;
        }
        current = current->next;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(uint32_t rx_ue_tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    new_node->RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_node->RNTI = rnti;
    new_node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;

    return new_node;
}

void log_error_and_cleanup(const char* message) {
    printf("%s\n", message);
    cleanup_hash_table();
    pthread_mutex_destroy(&hash_table_lock);
    pthread_mutex_destroy(&memory_mutex);
    exit(EXIT_FAILURE);
}

int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    init_hash_table();

    // Example usage
    for (int i = 0; i < 10000; ++i) {
        uint32_t rx_ue_tag = rand();
        uint16_t rnti = rand() % HASH_TABLE_SIZE;

