    return ds;
}

int add_record_to_dataset(dataset* ds, int value) {
    pthread_mutex_lock(&log_mutex);

    // Reallocate memory for the new record
    ds->records = realloc(ds->records, sizeof(record*) * (ds->count + 1));
    if (!ds->records) {
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    // Create a new record
    record* rec = malloc(sizeof(record));
    if (!rec) {
        ds->records[ds->count] = NULL; // Free previous allocation in case of failure
        pthread_mutex_unlock(&log_mutex);
        return -1;
    }

    rec->value = value;
    asprintf(&rec->string_value, "%d", value);
    rec->timestamp = time(NULL);

    pthread_mutex_lock(&metadata_mutex);
    for (int i = 0; i < MAX_METADATA; ++i) {
        if (!strchr(ds->records[ds->count]->metadata, METADATA_KEYWORDS[i][0])) {
            rec->metadata = strdup(METADATA_KEYWORDS[i]);
            break;
        }
    }
    pthread_mutex_unlock(&metadata_mutex);

    // Initialize audit events
    rec->audit_event_count = 0;
    rec->audit_events = NULL;

    ds->records[ds->count] = rec;
    ++(ds->count);

    async_log("Record created");

    pthread_mutex_unlock(&log_mutex);
    return 0;
}

void free_dataset(dataset* ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        if (ds->records[i]) {
            free(ds->records[i]->string_value);
            free(ds->records[i]->metadata);
            free(ds->records[i]->audit_events);
            free(ds->records[i]);
        }
    }
    free(ds->records);
    free(ds);
}

void async_log(const char *message) {
    pthread_mutex_lock(&log_mutex);
    // Simulate asynchronous logging
    printf("Log: %s\n", message);
    pthread_mutex_unlock(&log_mutex);
}
```

