#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 1024 * 1024 * 100 // 100 MB threshold
#define TIME_WINDOW_SECONDS 60

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t current_memory_usage;
    uint16_t unique_rnti_count;
    time_t start_time;
    pthread_mutex_t lock;
} CRCListManager;

CRCListManager* create_crc_list_manager() {
    CRCListManager* manager = (CRCListManager*)malloc(sizeof(CRCListManager));
    manager->head = NULL;
    manager->current_memory_usage = 0;
    manager->unique_rnti_count = 0;
    manager->start_time = time(NULL);
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void log_error(const char* message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

int is_unique_rnti(CRCListManager* manager, uint16_t rnti) {
    Node* current = manager->head;
    while (current) {
        if (current->data.RNTI == rnti) return 0;
        current = current->next;
    }
    return 1;
}

void add_pdu(CRCListManager* manager, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&manager->lock);

    if (!is_unique_rnti(manager, pdu->RNTI)) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (manager->current_memory_usage + pdu_size > MAX_MEMORY_USAGE) {
        log_error("Memory limit exceeded");
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    new_node->next = manager->head;
    manager->head = new_node;

    manager->current_memory_usage += pdu_size;
    if (is_unique_rnti(manager, pdu->RNTI)) {
        manager->unique_rnti_count++;
    }

    pthread_mutex_unlock(&manager->lock);
}

void report_unique_rnti_count(CRCListManager* manager) {
    time_t current_time = time(NULL);
    if (current_time - manager->start_time >= TIME_WINDOW_SECONDS) {
        printf("Unique RNTI count in the last %d seconds: %u\n", TIME_WINDOW_SECONDS, manager->unique_rnti_count);
        manager->unique_rnti_count = 0;
        manager->start_time = current_time;
    }
}

void cleanup_crc_list_manager(CRCListManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Simulated external data retrieval function
void fetch_data_from_external_source(CRCListManager* manager) {
    // Simulation of data fetching and processing
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 10000; // Simulate RNTI values
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        add_pdu(manager, &pdu);
        report_unique_rnti_count(manager);

        sleep(1); // Simulate delay between data fetches
    }
}

int main() {
    CRCListManager* manager = create_crc_list_manager();

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, (void*)fetch_data_from_external_source, manager) != 0) {
        log_error("Failed to create thread");
        cleanup_crc_list_manager(manager);
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);

    cleanup_crc_list_manager(manager);
    return EXIT_SUCCESS;
}
