['```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <thread>
#include <random>
#include <numeric>
#include <cmath>
#include <cstring>
#include <unordered_map>
#include <chrono>
#include <arpa/inet.h>
#include <netdb.h>

constexpr size_t MAX_SAMPLES = 1000;

struct PhyStats {
    double powerLevel;
    double signalStrength;
    int linkLayerStat;
};

class PhyStatsManager {
public:
    PhyStatsManager() : data(MAX_SAMPLES) {}

    void initializeRecord(size_t index) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (index < data.size()) {
            rng_.seed(std::chrono::system_clock::now().time_since_epoch().count());
            data[index] = {rng_(powerDist_), rng_(signalDist_), static_cast<int>(rng_(linkLayerDist_))};
            logInfo("Record initialized at index: ", index);
        }
    }

    void addOrUpdateRecord(size_t index) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (index >= data.size()) resizeData(index + 1);
        initializeRecord(index);
    }

    void computeAggregates() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (!data.empty()) {
            double mean = calculateMean();
            double variance = calculateVariance(mean);
            double stddev = std::sqrt(variance);

            logInfo("Mean: ", mean, " Variance: ", variance, " Std Dev: ", stddev);
        }
    }

    int resolveHostname(const char* hostname) {
        struct addrinfo hints{}, *res;
        int err;

        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_INET; // IPv4

        if ((err = getaddrinfo(hostname, nullptr, &hints, &res)) != 0) {
            logError("getaddrinfo: ", gai_strerror(err));
            return -1;
        }

        for (struct addrinfo* p = res; p != nullptr; p = p->ai_next) {
            if (p->ai_family == AF_INET) {
                char ipstr[INET_ADDRSTRLEN];
                inet_ntop(p->ai_family, &(((struct sockaddr_in*)p->ai_addr)->sin_addr), ipstr, sizeof(ipstr));
                logInfo("Resolved ", hostname, " to IP: ", ipstr);
                freeaddrinfo(res);
                return 0;
            }
        }

        freeaddrinfo(res);
        logError("Hostname resolution failed for: ", hostname);
        return -1;
    }

private:
    void resizeData(size_t newSize) {
        if (newSize <= data.size()) return;

        std::lock_guard<std::mutex> lock(mutex_);
        data.resize(newSize);

        for (size_t i = data.size() / 2; i < data.size(); ++i) {
            initializeRecord(i);
        }
    }

    double calculateMean() const {
        double sum = std::accumulate(data.begin(), data.end(), 0.0,
                                     [](double acc, const PhyStats& record) { return acc + record.signalStrength; });
        return data.empty() ? 0 : sum / data.size();
    }

    double calculateVariance(double mean) const {
        double accum = 0.0;
        for (const auto& record : data) {
            accum += std::pow(record.signalStrength - mean, 2);
        }
        return data.empty() ? 0 : accum / data.size();
    }

    void logInfo(const char* message, size_t index = 0, double val1 = 0.0, const char* val2 = nullptr) {
        std::cout << message;
        if (index > 0) std::cout << index;
        if (val1 != 0.0) std::cout << " " << val1;
        if (val2) std::cout << " " << val2;
        std::cout << std::endl;
    }

    void logError(const char* message, const char* error = nullptr) {
        std::cerr << "ERROR: ";
        std::cerr << message;
        if (error) std::cerr << " - " << error;
        std::cerr << std::endl;
    }

    std::vector<PhyStats> data;
    mutable std::mutex mutex_;
    std::mt19937 rng_;
    std::uniform_real_distribution<> powerDist_{-30.0, 0.0}; // Power level range in dBm
    std::uniform_real_distribution<> signalDist_{-100.0, -50.0}; // Signal strength range in dBm
    std::uniform_int_distribution<> linkLayerDist_{1, 100}; // Link layer stats range
};

int main() {
    PhyStatsManager manager;

    std::vector<std::thread> threads;
    for (size_t i = 0; i < MAX_SAMPLES; ++i) {
        threads.emplace_back(&PhyStatsManager::addOrUpdateRecord, &manager, i);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    manager.computeAggregates();

    if (manager.resolveHostname("www.example.com") == -1) {
        std::cerr << "Failed to resolve hostname." << std::endl;
    }

    return 0;
}
```']

