#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <string.h>

#define INITIAL_CAPACITY 1000
#define MAX_MESSAGES 10000

typedef struct {
    int message_type;
    char content[256];
} NAS_Message;

typedef struct {
    // Dummy TLVEncoder structure for demonstration purposes
    void *encoder;
} TLVEncoder;

typedef struct {
    TLVEncoder encoder;
    NAS_Message nas_message;
} LTE_DL_CCCH_Message_Type1_T;

typedef struct {
    LTE_DL_CCCH_Message_Type1_T *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} MessageArray;

MessageArray* init_message_array(size_t initial_capacity) {
    MessageArray *array = (MessageArray *)malloc(sizeof(MessageArray));
    if (!array) return NULL;

    array->messages = (LTE_DL_CCCH_Message_Type1_T *)malloc(initial_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!array->messages) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    pthread_cond_init(&array->cond_var, NULL);

    return array;
}

void resize_message_array(MessageArray *array) {
    size_t new_capacity = array->capacity * 2;
    LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(array->messages, new_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!new_messages) return; // Handle allocation failure gracefully

    array->messages = new_messages;
    array->capacity = new_capacity;
}

void log_error(const char *error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}

int populate_random_nas_message(NAS_Message *nas_message) {
    nas_message->message_type = rand() % 10; // Example message type
    snprintf(nas_message->content, sizeof(nas_message->content), "Message content for type %d", nas_message->message_type);
    return 0;
}

void* manage_messages(void *arg) {
    MessageArray *array = (MessageArray *)arg;

    while (1) {
        pthread_mutex_lock(&array->lock);

        if (array->count == array->capacity) {
            resize_message_array(array);
        }

        LTE_DL_CCCH_Message_Type1_T *msg = &array->messages[array->count];

        msg->encoder.encoder = malloc(sizeof(void)); // Simulate TLVEncoder allocation
        if (!msg->encoder.encoder) {
            log_error("Failed to allocate TLVEncoder");
            pthread_mutex_unlock(&array->lock);
            continue;
        }

        populate_random_nas_message(&msg->nas_message);

        array->count++;

        pthread_cond_signal(&array->cond_var);
        pthread_mutex_unlock(&array->lock);

        sleep(1); // Simulate processing time
    }
}

int main() {
    size_t num_threads = 4;
    MessageArray *message_array = init_message_array(INITIAL_CAPACITY);
    if (!message_array) {
        log_error("Failed to initialize message array");
        return EXIT_FAILURE;
    }

    pthread_t threads[num_threads];

    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, manage_messages, message_array)) {
            log_error("Failed to create thread");
            continue;
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(message_array->messages);
    free(message_array);

    return EXIT_SUCCESS;
}
