#define MAX_PACKETS 10000
#define MAX_MEMORY_PACKETS 2000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
    unsigned char HEADER_FLAG; // Used to identify critical packets
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T packet) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    new_node->data = packet;
    new_node->next = NULL;
    return new_node;
}

void insert_packet(Node** head, NFAPI_CRC_INDICATION_PDU_T packet, int* count, int max_elements) {
    if (*count >= max_elements) return;

    Node** current = head;
    while (*current && (*current)->data.RNTI < packet.RNTI) {
        current = &(*current)->next;
    }

    if (*current && (*current)->data.RNTI == packet.RNTI) return; // No duplicates

    Node* new_node = create_node(packet);
    new_node->next = *current;
    *current = new_node;
    (*count)++;
}

void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

void print_list(Node* head) {
    Node* current = head;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRC_INDICATION_REL8_TAG,
               current->data.CRCFLAG);
        current = current->next;
    }
}

void process_packets(NFAPI_CRC_INDICATION_PDU_T* packets, int packet_count, int max_elements) {
    Node* head = NULL;
    int count = 0;
    int critical_packet_count = 0;
    int total_processing_time = 0;
    NFAPI_CRC_INDICATION_PDU_T max_payload_packet = {0};
    int max_payload_size = 0;

    for (int i = 0; i < packet_count; ++i) {
        clock_t start_time = clock();

        if (packets[i].HEADER_FLAG == 1) {
            critical_packet_count++;
        }

        if (strlen(&packets[i]) > max_payload_size) {
            max_payload_size = strlen(&packets[i]);
            max_payload_packet = packets[i];
        }

        insert_packet(&head, packets[i], &count, max_elements);

        clock_t end_time = clock();
        total_processing_time += (end_time - start_time);
    }

    print_list(head);

    printf("Max Payload Size: %d, Packet Identifier: %d\n",
           max_payload_size,
           max_payload_packet.RNTI);

    printf("Critical Packets Handled: %d\n", critical_packet_count);
    printf("Average Processing Time per Packet: %.2f ms\n",
           (double)total_processing_time / CLOCKS_PER_SEC * 1000.0 / packet_count);

    free_list(head);
}

int main() {
    int max_elements = MAX_MEMORY_PACKETS;
    NFAPI_CRC_INDICATION_PDU_T packets[MAX_PACKETS];

    // Simulate incoming packets
    for (int i = 0; i < MAX_PACKETS; ++i) {
        packets[i].RX_UE_INFORMATION_TAG = rand();
        packets[i].RNTI = rand() % 100 + 1;
        packets[i].CRC_INDICATION_REL8_TAG = rand();
        packets[i].CRCFLAG = rand() & 0x01;
        packets[i].HEADER_FLAG = (rand() % 10 == 0) ? 1 : 0; // Randomly mark some as critical
    }

    process_packets(packets, MAX_PACKETS, max_elements);

    return 0;
}
