#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define CACHE_LINE_SIZE 64

typedef struct {
    // Assume this is a predefined structure.
} LMAC_CONFIG;

typedef struct {
    // Assume this is a predefined structure.
} MAC_FRAME;

typedef struct MAC_CONTEXT_T_ {
    LMAC_CONFIG config;
    MAC_FRAME *frames;
    size_t frame_count;
    size_t frame_capacity;
} MAC_CONTEXT_T;

// Memory pool for MAC_CONTEXT_T instances
typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    MAC_CONTEXT_T **contexts;
} ContextPool;

ContextPool *create_context_pool(size_t initial_capacity) {
    ContextPool *pool = malloc(sizeof(ContextPool));
    if (!pool) return NULL;

    pool->lock = PTHREAD_MUTEX_INITIALIZER;
    pool->capacity = initial_capacity;
    pool->count = 0;
    pool->contexts = calloc(initial_capacity, sizeof(MAC_CONTEXT_T*));

    return pool;
}

void destroy_context_pool(ContextPool *pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->contexts[i]->frames);
        free(pool->contexts[i]);
    }
    free(pool->contexts);
    pthread_mutex_unlock(&pool->lock);

    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

MAC_CONTEXT_T *acquire_context(ContextPool *pool, LMAC_CONFIG config) {
    if (!pool) return NULL;

    MAC_CONTEXT_T *context = NULL;

    pthread_mutex_lock(&pool->lock);

    // Check if there's a reusable context
    for (size_t i = 0; i < pool->count; ++i) {
        if (!memcmp(pool->contexts[i]->config, &config, sizeof(LMAC_CONFIG))) {
            context = pool->contexts[i];
            break;
        }
    }

    // If not found, create a new one
    if (!context) {
        if (pool->count == pool->capacity) {
            size_t new_capacity = pool->capacity * 2;
            MAC_CONTEXT_T **new_contexts = realloc(pool->contexts, new_capacity * sizeof(MAC_CONTEXT_T*));
            if (!new_contexts) {
                pthread_mutex_unlock(&pool->lock);
                return NULL; // Handle reallocation failure
            }

            memset(new_contexts + pool->capacity, 0, (new_capacity - pool->capacity) * sizeof(MAC_CONTEXT_T*));
            pool->contexts = new_contexts;
            pool->capacity = new_capacity;
        }

        context = malloc(sizeof(MAC_CONTEXT_T));
        if (!context) {
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Handle allocation failure
        }

        memcpy(&context->config, &config, sizeof(LMAC_CONFIG));
        context->frame_count = 0;
        context->frame_capacity = INITIAL_CAPACITY;
        context->frames = malloc(context->frame_capacity * sizeof(MAC_FRAME));
        if (!context->frames) {
            free(context);
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Handle allocation failure
        }

        pool->contexts[pool->count++] = context;
    }

    pthread_mutex_unlock(&pool->lock);

    return context;
}

void release_context(ContextPool *pool, MAC_CONTEXT_T *context) {
    if (!pool || !context) return;

    pthread_mutex_lock(&pool->lock);

    // Reset the frame list
    free(context->frames);
    context->frame_count = 0;
    context->frame_capacity = INITIAL_CAPACITY;
    context->frames = malloc(context->frame_capacity * sizeof(MAC_FRAME));
    if (!context->frames) {
        pthread_mutex_unlock(&pool->lock);
        return; // Handle allocation failure
    }

    pthread_mutex_unlock(&pool->lock);
}

// Dummy external logging system for demonstration
void log_action(const char *message) {
    printf("Log: %s\n", message);
}

// Example usage of the context pool with logging integration.
MAC_CONTEXT_T *get_or_create_context(ContextPool *pool, LMAC_CONFIG config) {
    MAC_CONTEXT_T *context = acquire_context(pool, config);

    if (context) {
        log_action("Context acquired or created.");
    } else {
        log_action("Failed to acquire or create context.");
    }

    return context;
}

void free_and_log(ContextPool *pool, MAC_CONTEXT_T **contexts, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        release_context(pool, contexts[i]);
        log_action("Context released.");
    }
}

// Example test function
void test_function() {
    LMAC_CONFIG config;
    ContextPool *pool = create_context_pool(INITIAL_CAPACITY);

    if (!pool) {
        printf("Failed to create context pool.\n");
        return;
    }

    MAC_CONTEXT_T *context1 = get_or_create_context(pool, config);
    MAC_CONTEXT_T *context2 = get_or_create_context(pool, config);

    free_and_log(pool, (MAC_CONTEXT_T*[]){context1, context2}, 2);

    destroy_context_pool(pool);
}

int main() {
    test_function();
    return 0;
}
```

