typedef struct {
    int valid_RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    pthread_mutex_t lock;
} List;

// Function to initialize the list
void init_list(List* list) {
    list->head = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Function to deallocate a node
void free_node(Node* node) {
    free(node);
}

// Function to add a structure to the list
int add_structure(List* list, int valid_RX_UE_INFORMATION_TAG, unsigned long RNTI, int CRC_INDICATION_REL8_TAG) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return 0;

    new_node->data.valid_RX_UE_INFORMATION_TAG = valid_RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;

    // Randomly set CRCFLAG
    new_node->data.CRC_INDICATION_REL8_TAG |= (rand() % 2) << 1; 

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);

    return 1;
}

// Function to clean up the entire list
void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    list->head = NULL;
    list->count = 0;
}

// Function to create and manage a list of structures
void manage_nfa_crc_indications(size_t num_structures, int log_errors) {
    List list;
    init_list(&list);

    size_t total_attempted = 0;
    size_t successfully_created = 0;

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < num_structures; ++i) {
        int valid_RX_UE_INFORMATION_TAG = rand() % 2;
        unsigned long RNTI = rand();
        int CRC_INDICATION_REL8_TAG = rand();

        total_attempted++;

        if (add_structure(&list, valid_RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG)) {
            successfully_created++;
        } else if (log_errors) {
            fprintf(stderr, "Error creating structure at index %zu\n", i);
        }
    }

    printf("Total attempted: %zu\nSuccessfully created: %zu\n", total_attempted, successfully_created);

    // Clean up
    free_list(&list);
}

// Example usage in a multi-threaded environment
void* thread_func(void* arg) {
    size_t num_structures = *(size_t*)arg;
    manage_nfa_crc_indications(num_structures, 1);
    return NULL;
}

int main() {
    const int NUM_THREADS = 4;
    pthread_t threads[NUM_THREADS];
    size_t structures_per_thread = 1000;

    for (int i = 0; i < NUM_THREADS; ++i) {
