```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 50000

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    unsigned long RNTI;
    unsigned long RX_UE_INFORMATION_TAG;
    CRC_INDICATION_REL8_TAG_T crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPICRCList;

NFAPICRCList* create_list() {
    NFAPICRCList* list = malloc(sizeof(NFAPICRCList));
    if (!list) return NULL;
    list->entries = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void resize_list(NFAPICRCList* list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_entries) {
        list->entries = new_entries;
        list->capacity = new_capacity;
    } else {
        // Handle allocation failure
        fprintf(stderr, "Memory reallocation failed\n");
    }
}

void populate_list(NFAPICRCList* list, size_t n) {
    pthread_mutex_lock(&list->lock);

    if (n > MAX_ENTRIES) n = MAX_ENTRIES;

    if (list->capacity < n) {
        resize_list(list, n);
    }

    srand(time(NULL)); // Use current time as seed for randomness
    for (size_t i = 0; i < n; ++i) {
        list->entries[i].RNTI = rand() % 100000;
        list->entries[i].RX_UE_INFORMATION_TAG = rand() % 100000;
        list->entries[i].crcTag.CRCFLAG = rand() & 1; // Random CRCFLAG as either 0 or 1
    }

    list->count = n;

    pthread_mutex_unlock(&list->lock);
}

void free_list(NFAPICRCList* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->entries);
        free(list);
    }
}

// Usage example in main function
int main() {
    NFAPICRCList* nfaList = create_list();
    if (!nfaList) {
        fprintf(stderr, "Failed to create NFA list\n");
        return 1;
    }

    populate_list(nfaList, 50000);

    // Example access (thread-safe)
    pthread_mutex_lock(&nfaList->lock);
    printf("First RNTI: %lu\n", nfaList->entries[0].RNTI);
    pthread_mutex_unlock(&nfaList->lock);

    free_list(nfaList);

    return 0;
}
