#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

typedef struct {
    int value;
    long *offset;
    int *key;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} RecordsManager;

void initialize_random() {
    srand(time(NULL));
}

long generate_random_long(long min, long max) {
    return min + rand() % (max - min + 1);
}

int generate_random_int(int min, int max) {
    return min + rand() % (max - min + 1);
}

void load_offsets_and_keys(const char *offsets_file, const char *keys_file, long **offsets, size_t *offset_count, int **keys, size_t *key_count) {
    FILE *fp;

    fp = fopen(offsets_file, "r");
    if (!fp) {
        perror("Failed to open offsets file");
        exit(EXIT_FAILURE);
    }
    fscanf(fp, "%zu", offset_count);
    *offsets = malloc(*offset_count * sizeof(long));
    for (size_t i = 0; i < *offset_count; ++i) {
        fscanf(fp, "%ld", &((*offsets)[i]));
    }
    fclose(fp);

    fp = fopen(keys_file, "r");
    if (!fp) {
        perror("Failed to open keys file");
        exit(EXIT_FAILURE);
    }
    fscanf(fp, "%zu", key_count);
    *keys = malloc(*key_count * sizeof(int));
    for (size_t i = 0; i < *key_count; ++i) {
        fscanf(fp, "%d", &((*keys)[i]));
    }
    fclose(fp);
}

RecordsManager* create_records_manager(size_t initial_capacity) {
    RecordsManager *manager = malloc(sizeof(RecordsManager));
    manager->records = malloc(initial_capacity * sizeof(Record));
    if (!manager->records) {
        perror("Memory allocation failed for records");
        free(manager);
        exit(EXIT_FAILURE);
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void resize_records(RecordsManager *manager, size_t new_capacity) {
    pthread_mutex_lock(&manager->lock);
    Record *new_records = realloc(manager->records, new_capacity * sizeof(Record));
    if (!new_records) {
        perror("Memory reallocation failed for records");
        exit(EXIT_FAILURE);
    }
    manager->records = new_records;
    manager->capacity = new_capacity;
    pthread_mutex_unlock(&manager->lock);
}

int add_record(RecordsManager *manager, long offset, int key, int min_val, int max_val) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        resize_records(manager, manager->capacity * 2);
    }

    Record *record = &manager->records[manager->count];
    record->offset = malloc(sizeof(long));
    if (!record->offset) {
        perror("Memory allocation failed for offset");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    *(record->offset) = offset;

    record->key = malloc(sizeof(int));
    if (!record->key) {
        perror("Memory allocation failed for key");
        free(record->offset);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    *(record->key) = key;

    record->value = generate_random_int(min_val, max_val);

    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void free_records_manager(RecordsManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i].offset);
        free(manager->records[i].key);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int validate_records(RecordsManager *manager, long *offsets, size_t offset_count, int *keys, size_t key_count) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].offset == NULL || manager->records[i].key == NULL) {
            return -1;
        }
        long *offset = manager->records[i].offset;
        int *key = manager->records[i].key;

        for (size_t j = 0; j < offset_count; ++j) {
            if (*offset == offsets[j]) break;
            if (j == offset_count - 1) return -1;
        }

        for (size_t k = 0; k < key_count; ++k) {
            if (*key == keys[k]) break;
            if (k == key_count - 1) return -1;
        }
    }
    return 0;
}

void track_memory_usage(RecordsManager *manager) {
    size_t records_size = sizeof(Record) * manager->count;
    printf("Memory usage: %zu bytes for records\n", records_size);

    size_t offsets_keys_size = (sizeof(long) + sizeof(int)) * manager->count;
    printf("Memory usage: %zu bytes for offset and key pointers\n", offsets_keys_size);

    size_t total_memory_usage = records_size + offsets_keys_size;
    printf("Total memory usage: %zu bytes\n", total_memory_usage);
}

int main() {
    const char *offsets_file = "offsets.txt";
    const char *keys_file = "keys.txt";

    long *offsets = NULL, *keys = NULL;
    size_t offset_count = 0, key_count = 0;

    load_offsets_and_keys(offsets_file, keys_file, &offsets, &offset_count, &keys, &key_count);

    RecordsManager *manager = create_records_manager(10);
    initialize_random();

    for (size_t i = 0; i < manager->count; ++i) {
        add_record(manager, offsets[i % offset_count], keys[i % key_count], 1, 100);
    }

    track_memory_usage(manager);

    if (validate_records(manager, offsets, offset_count, keys, key_count)) {
        fprintf(stderr, "Validation failed!\n");
    } else {
        printf("All records are valid.\n");
    }

    free(offsets);
    free(keys);
    free_records_manager(manager);

    return 0;
}
