#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <jansson.h> // For JSON parsing
#include <curl/curl.h> // For HTTP requests
#include <sqlite3.h>  // For database connection

// Define structures for Network Performance Metrics and LTE Message
typedef struct {
    double timestamp;
    char session_id[32];
    double *measurements; // Array of measurement results
    size_t num_measurements;
} NetworkPerformanceMetrics;

typedef struct LTE_DL_CCCH_Message_Type1_T {
    int message_type;
    char content[256];
} LTE_DL_CCCH_Message_Type1;

// Define a linked list node for network metrics
typedef struct MetricNode {
    NetworkPerformanceMetrics data;
    struct MetricNode *next;
} MetricNode;

// Global variables
MetricNode *head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sqlite3 *db = NULL;

// Function prototypes
void initializeNetworkMetricsAndMessages();
void cleanupOutdatedMetrics();
void updateMetric(const char *json_payload);
void removeMetric(const char *session_id);
void secureDatabaseConnection(int supervisor_id);
int executeSQLQuery(sqlite3_stmt *stmt, int supervisor_id);

// Helper function to allocate memory safely
void* safeMalloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// HTTP PUT request handler
static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    // Implement callback logic for handling response data from HTTP requests
    return size * nmemb;
}

void initializeNetworkMetricsAndMessages() {
    pthread_t cleanup_thread;

    // Start a thread to periodically clean up outdated metrics
    if (pthread_create(&cleanup_thread, NULL, (void *(*)(void *))cleanupOutdatedMetrics, NULL) != 0) {
        perror("Failed to create cleanup thread");
        exit(EXIT_FAILURE);
    }

    // Initialize database connection
    if (sqlite3_open("employee_data.db", &db)) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return;
    }
}

void cleanupOutdatedMetrics() {
    while (1) {
        pthread_mutex_lock(&mutex);

        // Logic to remove outdated metrics based on retention policy
        MetricNode *current = head, *prev = NULL;

        while (current != NULL) {
            double current_time = /* Get current timestamp */;
            if (current_time - current->data.timestamp > /* Retention period */) {
                if (prev == NULL) {
                    head = current->next;
                } else {
                    prev->next = current->next;
                }
                MetricNode *temp = current;
                current = current->next;
                free(temp->data.measurements);
                free(temp);
            } else {
                prev = current;
                current = current->next;
            }
        }

        pthread_mutex_unlock(&mutex);

        // Sleep for a specified interval before next cleanup
        sleep(/* Cleanup interval */);
    }
}

void updateMetric(const char *json_payload) {
    pthread_mutex_lock(&mutex);

    json_error_t error;
    json_t *root = json_loads(json_payload, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Parse and validate the incoming JSON payload
    const char *session_id = json_string_value(json_object_get(root, "session_id"));
    double timestamp = json_real_value(json_object_get(root, "timestamp"));

    if (!session_id || !json_is_real(timestamp)) {
        fprintf(stderr, "Invalid JSON data\n");
        json_decref(root);
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Find or create a metric node
    MetricNode *current = head, *prev = NULL;

    while (current != NULL) {
        if (strcmp(current->data.session_id, session_id) == 0) {
            break; // Found the existing node
        }
        prev = current;
        current = current->next;
    }

    if (!current) { // Create a new node if not found
        current = safeMalloc(sizeof(MetricNode));
        strncpy(current->data.session_id, session_id, sizeof(current->data.session_id) - 1);
        current->data.timestamp = timestamp;

        if (prev == NULL) {
            current->next = head;
            head = current;
        } else {
            prev->next = current;
            current->next = NULL;
        }
    }

    // Parse measurements
    json_t *measurements_array = json_object_get(root, "measurements");
    if (json_is_array(measurements_array)) {
        size_t index;
        double *new_measurements = safeMalloc(json_array_size(measurements_array) * sizeof(double));

        for (index = 0; index < json_array_size(measurements_array); ++index) {
            new_measurements[index] = json_real_value(json_array_get(measurements_array, index));
        }

        free(current->data.measurements);
        current->data.measurements = new_measurements;
        current->data.num_measurements = json_array_size(measurements_array);
    }

    // Send HTTP PUT request to update the metric
    CURL *curl = curl_easy_init();
    if (curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        char postfields[1024];
        snprintf(postfields, sizeof(postfields), "{\"session_id\":\"%s\",\"timestamp\":%.2f}", session_id, timestamp);

        curl_easy_setopt(curl, CURLOPT_URL, "http://api.example.com/update_metric");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, postfields);

        CURLcode res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }

    json_decref(root);
    pthread_mutex_unlock(&mutex);
}

void removeMetric(const char *session_id) {
    pthread_mutex_lock(&mutex);

    MetricNode *current = head, *prev = NULL;

    while (current != NULL) {
        if (strcmp(current->data.session_id, session_id) == 0) {
            break; // Found the node to remove
        }
        prev = current;
        current = current->next;
    }

    if (!current) {
        fprintf(stderr, "Session ID not found\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->data.measurements);
    free(current);

    pthread_mutex_unlock(&mutex);
}

void secureDatabaseConnection(int supervisor_id) {
    char *sql = "SELECT name, city, address FROM employees WHERE supervisor_id = ?";
    sqlite3_stmt *stmt;

    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare SQL statement: %s\n", sqlite3_errmsg(db));
        return;
    }

    executeSQLQuery(stmt, supervisor_id);
}

int executeSQLQuery(sqlite3_stmt *stmt, int supervisor_id) {
    int retries = 3;

    while (retries--) {
        if (sqlite3_bind_int(stmt, 1, supervisor_id) != SQLITE_OK ||
            sqlite3_step(stmt) != SQLITE_ROW) {
            fprintf(stderr, "Failed to execute SQL query: %s\n", sqlite3_errmsg(db));
            sqlite3_reset(stmt);
            sleep(1); // Retry after a delay
        } else {
            const char *name = (const char *)sqlite3_column_text(stmt, 0);
            const char *city = (const char *)sqlite3_column_text(stmt, 1);
            const char *address = (const char *)sqlite3_column_text(stmt, 2);

            printf("Executed SQL: %s\n", sqlite3_sql(stmt));
            printf("Name: %s, City: %s, Address: %s\n", name, city, address);

            sqlite3_reset(stmt);
            return SQLITE_OK;
        }
    }

    fprintf(stderr, "All retries failed for executing SQL query.\n");
    return SQLITE_ERROR;
}

int main() {
    initializeNetworkMetricsAndMessages();

    // Example usage
    const char *json_payload = "{\"session_id\":\"abc123\",\"timestamp\":1633072800,\"measurements\":[10.5, 20.3, 30.7]}";
    updateMetric(json_payload);

    secureDatabaseConnection(1);

    return 0;
}
