// Dynamic list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t count;
    size_t capacity;
} CRCList;

// Function prototypes
CRCList* create_crc_list(size_t initial_capacity);
bool append_element(CRCList* crc_list, const RX_UE_INFORMATION_TAG* ue_info_tag, bool allow_duplicates);
NFAPI_CRC_INDICATION_PDU_T* get_element_by_rnti(const CRCList* crc_list, uint16_t rnti);
void clear_and_reset_crc_list(CRCList* crc_list);

// Implementation
CRCList* create_crc_list(size_t initial_capacity) {
    CRCList* crc_list = (CRCList*)malloc(sizeof(CRCList));
    if (!crc_list) {
        log_message("Memory allocation failed for CRC list");
        return NULL;
    }

    crc_list->elements = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(16, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_list->elements) {
        free(crc_list);
        log_message("Memory allocation failed for CRC elements");
        return NULL;
    }

    crc_list->count = 0;
    crc_list->capacity = initial_capacity;

    return crc_list;
}

bool append_element(CRCList* crc_list, const RX_UE_INFORMATION_TAG* ue_info_tag, bool allow_duplicates) {
    if (crc_list->count >= crc_list->capacity) {
        size_t new_capacity = crc_list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(crc_list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            log_message("Memory reallocation failed for CRC elements");
            return false;
        }
        crc_list->elements = new_elements;
        crc_list->capacity = new_capacity;
    }

    uint16_t rnti = ue_info_tag->RNTI;
    if (!allow_duplicates) {
        for (size_t i = 0; i < crc_list->count; ++i) {
            if (crc_list->elements[i].ue_info_tag.RNTI == rnti) {
                log_message("Duplicate RNTI found, skipping append");
                return false;
            }
        }
    }

    NFAPI_CRC_INDICATION_PDU_T new_element = { *ue_info_tag, {.CRCFLAG = rand() % 2} };
    crc_list->elements[crc_list->count++] = new_element;

    log_message("Element appended successfully");
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* get_element_by_rnti(const CRCList* crc_list, uint16_t rnti) {
    for (size_t i = 0; i < crc_list->count; ++i) {
        if (crc_list->elements[i].ue_info_tag.RNTI == rnti) {
            log_message("Element found by RNTI");
            return &crc_list->elements[i];
        }
    }

    log_message("Element not found by RNTI");
    return NULL;
}

void clear_and_reset_crc_list(CRCList* crc_list) {
    if (crc_list && crc_list->elements) {
        free(crc_list->elements);
        crc_list->elements = NULL;
        crc_list->count = 0;
        crc_list->capacity = 0;

        log_message("CRC list cleared and reset");
    }
}

// Logging function implementation
void log_message(const char* message) {
    printf("%s\n", message);
}
