#include "Logger.h" // Assume this is the third-party logging library

#define INITIAL_CAPACITY 10
#define MEMORY_THRESHOLD (1024 * 1024) // Example threshold in bytes

typedef struct {
    LTE_DL_CCCH_Message_Type1_T messages;
    size_t count;
    size_t capacity;
} MessageArray;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_memory_usage(size_t used_memory) {
    Logger_Log("Memory usage: %zu bytes", used_memory);
}

size_t calculate_memory_usage(MessageArray *array) {
    return sizeof(LTE_DL_CCCH_Message_Type1_T) * array->capacity;
}

void resize_array(MessageArray *array, size_t new_capacity) {
    LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(array->messages, new_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!new_messages) {
        Logger_Log("Error: Memory allocation failed during resizing.");
        return;
    }
    array->messages = new_messages;
    array->capacity = new_capacity;
}

int initialize_message_array(MessageArray *array, size_t initial_count) {
    pthread_mutex_lock(&lock);
    array->count = 0;
    array->capacity = INITIAL_CAPACITY;

    array->messages = malloc(array->capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!array->messages) {
        Logger_Log("Error: Initial memory allocation failed.");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    for (size_t i = 0; i < initial_count; ++i) {
        if (array->count >= array->capacity) {
            resize_array(array, array->capacity * 2);
            if (!array->messages) {
                pthread_mutex_unlock(&lock);
                return -1;
            }
        }

        LTE_DL_CCCH_Message_Type1_T *message = &array->messages[array->count];
        message->TLVEncoder = TLVEncoder_Create();
        if (!message->TLVEncoder) {
            Logger_Log("Error: Failed to create TLV Encoder.");
            pthread_mutex_unlock(&lock);
            return -1;
        }

        // Randomly generate NAS message type and content
        message->NAS_Message.type = rand() % 100; // Example random type
        message->NAS_Message.content = malloc(128); // Example size
        if (!message->NAS_Message.content) {
            Logger_Log("Error: Memory allocation for NAS message content failed.");
            TLVEncoder_Destroy(message->TLVEncoder);
            pthread_mutex_unlock(&lock);
            return -1;
        }
        memset(message->NAS_Message.content, rand() % 256, 128);

        array->count++;
    }

    log_memory_usage(calculate_memory_usage(array));
    pthread_mutex_unlock(&lock);
    return 0;
}

void free_message_array(MessageArray *array) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < array->count; ++i) {
        TLVEncoder_Destroy(array->messages[i].TLVEncoder);
        free(array->messages[i].NAS_Message.content);
    }
    free(array->messages);
    pthread_mutex_unlock(&lock);
}

void monitor_memory_usage(MessageArray *array) {
    while (1) {
        size_t used_memory = calculate_memory_usage(array);
        if (used_memory > MEMORY_THRESHOLD) {
            Logger_Log("Warning: Memory usage exceeded threshold.");
        }
        log_memory_usage(used_memory);
        sleep(5); // Monitor every 5 seconds
    }
}

int main() {
    srand(time(NULL));
    MessageArray array;
    initialize_message_array(&array, 20);

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, (void *(*)(void *))monitor_memory_usage, &array);
    pthread_join(monitor_thread, NULL);

    free_message_array(&array);
    return 0;
}
```

### Key Features:
- **Dynamic Resizing**: The array resizes dynamically based on the number of messages.
- **Memory Monitoring**: Logs memory usage and warns if it exceeds a threshold.
- **Thread Safety**: Uses mutexes to ensure thread-safe operations.
- **Error Handling**: Logs errors during allocation or initialization failures.
- **Extensibility**: Designed for easy modification and extension.']

