#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_TX_MODE 3
#define MIN_TX_MODE 1
#define MAX_CHANNEL_BANDWIDTH 100
#define MIN_CHANNEL_BANDWIDTH 10

typedef struct {
    int TX_MODE;
    int CHANNEL_BANDWIDTH;
} TRANSMISSION_CONFIG_REL15_TAG;

typedef struct {
    int RRC_INSTANCE_ID;
    TRANSMISSION_CONFIG_REL15_TAG transmissionConfigRel15Tag;
} NFAPI_TX_COMMAND_PDU_T;

typedef struct Node {
    NFAPI_TX_COMMAND_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to log errors
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Function to create a new node
Node* create_node(int rrcInstanceId) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        log_error("Memory allocation failed for Node");
        return NULL;
    }

    newNode->data.RRC_INSTANCE_ID = rrcInstanceId;
    newNode->data.transmissionConfigRel15Tag.TX_MODE = rand() % (MAX_TX_MODE - MIN_TX_MODE + 1) + MIN_TX_MODE;
    newNode->data.transmissionConfigRel15Tag.CHANNEL_BANDWIDTH = rand() % (MAX_CHANNEL_BANDWIDTH - MIN_CHANNEL_BANDWIDTH + 1) + MIN_CHANNEL_BANDWIDTH;

    newNode->prev = NULL;
    newNode->next = NULL;

    return newNode;
}

// Function to check if the list has reached its capacity
int is_full(Node* head, int maxElements) {
    Node* current = head;
    int count = 0;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count >= maxElements;
}

// Function to add a node to the list
int add_node(Node** head, Node** tail, int rrcInstanceId, int maxElements) {
    if (is_full(*head, maxElements)) {
        log_error("Maximum capacity reached");
        return 0;
    }

    Node* newNode = create_node(rrcInstanceId);
    if (!newNode) {
        return 0; // Memory allocation failed
    }

    if (*head == NULL) { // Empty list
        *head = newNode;
        *tail = newNode;
    } else { // Non-empty list
        (*tail)->next = newNode;
        newNode->prev = *tail;
        *tail = newNode;
    }

    return 1; // Success
}

// Function to free the linked list memory
void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }
}

// Function to validate all allocated memory has been freed correctly
int validate_memory_freed(Node* head) {
    return head == NULL; // If head is NULL, the list is empty and memory is freed
}

// Function to print the linked list contents
void print_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("RRC_INSTANCE_ID: %d\n", current->data.RRC_INSTANCE_ID);
        printf("  TX_MODE: %d\n", current->data.transmissionConfigRel15Tag.TX_MODE);
        printf("  CHANNEL_BANDWIDTH: %d\n", current->data.transmissionConfigRel15Tag.CHANNEL_BANDWIDTH);
        printf("\n");
        current = current->next;
    }
}

// Main function to create and manage the linked list
void create_and_manage_list(int maxElements) {
    Node* head = NULL;
    Node* tail = NULL;

    srand(time(NULL)); // Seed for random number generation

    for (int i = 1; i <= maxElements; ++i) {
        add_node(&head, &tail, i, maxElements);
    }

    print_list(head);

    if (validate_memory_freed(head)) {
        printf("Memory has been successfully freed.\n");
    } else {
        log_error("Memory validation failed");
    }

    free_list(head);
}

int main() {
    int M = 10; // Maximum number of elements
    create_and_manage_list(M);

    return 0;
}
```

### Key Points:
- **Error Handling:** The `log_error` function is used to log memory allocation failures. This helps track errors without significantly impacting performance.
- **Capacity Check:** The `is_full` function ensures the list does not exceed its capacity, minimizing overhead by checking only when a new node addition is attempted.
- **Memory Management:** Proper freeing of allocated memory is ensured with `free_list`, and validation is performed using `validate_memory_freed`.
- **Output Formatting:** The `print_list` function provides human-readable output for debugging purposes.']

