```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_FILES 100
#define LINE_BUFFER_SIZE 256

typedef struct {
    double min;
    double max;
    double sum;
    int count;
} SensorStats;

typedef struct {
    char sensor_id[32];
    time_t first_timestamp;
    time_t last_timestamp;
    SensorStats stats;
} SensorData;

// Thread-safe map structure
typedef struct Node {
    char key[32];
    SensorData data;
    struct Node* next;
} Node;

Node* create_node(const char* key, const SensorData* data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    strcpy(node->key, key);
    node->data = *data;
    node->next = NULL;
    return node;
}

void insert_sensor_data(Node** map, const char* key, const SensorData* data) {
    Node* current = *map;
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            SensorStats* stats = &current->data.stats;
            if (stats->count == 0 || data->stats.min < stats->min)
                stats->min = data->stats.min;
            if (stats->count == 0 || data->stats.max > stats->max)
                stats->max = data->stats.max;
            stats->sum += data->stats.sum;
            stats->count += data->stats.count;
            current->data.first_timestamp = (current->data.first_timestamp < data->first_timestamp) ? 
                                            current->data.first_timestamp : data->first_timestamp;
            current->data.last_timestamp = (current->data.last_timestamp > data->last_timestamp) ? 
                                           current->data.last_timestamp : data->last_timestamp;
            return;
        }
        if (strcmp(key, current->key) < 0)
            break;
        current = current->next;
    }

    Node* new_node = create_node(key, data);
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->next = *map;
    *map = new_node;
}

pthread_mutex_t map_mutex = PTHREAD_MUTEX_INITIALIZER;

void process_file(const char* filename, Node** sensor_map, int* valid_records) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Error opening file %s\n", filename);
        return;
    }

    char line[LINE_BUFFER_SIZE];
    while (fgets(line, LINE_BUFFER_SIZE, file)) {
        time_t timestamp;
        char sensor_id[32];
        double measurement;

        if (sscanf(line, "%ld,%31[^,],%lf", &timestamp, sensor_id, &measurement) == 3) {
            pthread_mutex_lock(&map_mutex);
            SensorData data = {0};
            strcpy(data.sensor_id, sensor_id);
            data.first_timestamp = data.last_timestamp = timestamp;
            if (data.stats.count == 0 || measurement < data.stats.min)
                data.stats.min = measurement;
            if (data.stats.count == 0 || measurement > data.stats.max)
                data.stats.max = measurement;
            data.stats.sum = measurement;
            data.stats.count = 1;

            insert_sensor_data(sensor_map, sensor_id, &data);
            pthread_mutex_unlock(&map_mutex);

            (*valid_records)++;
        }
    }

    fclose(file);
}

void* worker_thread(void* args) {
    int thread_num = *(int*)args;
    const char** filenames = (const char**)((char*)args + sizeof(int));
    Node** sensor_map = (Node**)((char*)args + sizeof(int) + MAX_FILES * sizeof(char*));
    int* valid_records = (int*)((char*)args + sizeof(int) + MAX_FILES * sizeof(char*) + sizeof(Node*));

    for (int i = thread_num; i < MAX_FILES; i += 4) { // Assuming 4 threads
        process_file(filenames[i], sensor_map, valid_records);
    }

    return NULL;
}

int process_sensor_data(const char** filenames, int num_files, int async_mode) {
    Node* sensor_map = NULL;
    int valid_records = 0;

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) { // Assuming 4 CPU cores
        int thread_num = i;
        pthread_create(&threads[i], NULL, worker_thread, &thread_num);
    }

    if (!async_mode) {
        for (int i = 0; i < 4; ++i)
            pthread_join(threads[i], NULL);
    } else {
        for (int i = 0; i < 4; ++i)
            pthread_detach(threads[i]);
    }

    // Print results
    Node* current = sensor_map;
    while (current != NULL) {
        printf("Sensor ID: %s, Min: %.2f, Max: %.2f, Avg: %.2f\n",
               current->key,
               current->data.stats.min,
               current->data.stats.max,
               current->data.stats.count > 0 ? current->data.stats.sum / current->data.stats.count : 0);
        printf("First Timestamp: %ld, Last Timestamp: %ld\n",
               current->data.first_timestamp,
               current->data.last_timestamp);
        current = current->next;
    }

    return valid_records;
}

int main(int argc, char* argv[]) {
    const char* filenames[MAX_FILES] = {/* Populate with file paths */};
    int num_files = /* Number of files */;
    int async_mode = 1; // Set based on system load

    int processed_records = process_sensor_data(filenames, num_files, async_mode);
    printf("Total valid records processed: %d\n", processed_records);

    return 0;
}
```

### Key Features:
- **Thread Management**: Uses pthreads for concurrent file processing.
- **Load Balancing**: Distributes workload across threads based on file index.
- **Thread-Safe Map**: Manages sensor data using a linked list with mutex protection.
- **Memory Management**: Allocates memory dynamically and checks for allocation failures.
- **Error Handling**: Logs errors during file operations and continues processing.
- **Asynchronous Mode**: Supports both synchronous (blocking) and asynchronous (non-blocking) modes.

This code is designed to efficiently process large-scale sensor data streams, ensuring scalability and reliability. Adjust the number of threads based on your system's CPU core count for optimal performance.']

