int get_log_level() {
    return 1; // Example log level
}

// Memory pool for efficient allocation
#define POOL_SIZE 100
LTE_DL_CCCH_Message_Type1_T memory_pool[POOL_SIZE];
size_t pool_index = 0;
pthread_mutex_t pool_mutex;

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index + size > POOL_SIZE) {
        pthread_mutex_unlock(&pool_mutex);
        log_error("Memory pool overflow");
        return NULL;
    }
    void *ptr = &memory_pool[pool_index];
    pool_index += size;
    pthread_mutex_unlock(&pool_mutex);
    return ptr;
}

void initialize_and_populate_ccch_messages(LTE_DL_CCCH_Message_Type1_T **messages, size_t count) {
    if (!messages || count == 0) {
        log_error("Invalid input parameters");
        return;
    }

    *messages = (LTE_DL_CCCH_Message_Type1_T *)allocate_from_pool(count);
    if (*messages == NULL) {
        return; // Memory pool overflow handled by allocate_from_pool
    }

    pthread_mutex_t init_mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_lock(&init_mutex);

        // Simulate network and configuration delay
        if (get_log_level() > 1) { // Example condition based on log level
            printf("Initializing message %zu\n", i);
        }

        (*messages)[i].encoder = (TLVEncoder){};
        (*messages)[i].nas_message.message_type = rand() % 100; // Simulate dynamic generation
        const size_t content_size = snprintf(NULL, 0, "Message Content %zu") + 1;
        char *content = malloc(content_size);

        if (!content) {
            log_error("Memory allocation failed for NAS message content");
            pthread_mutex_unlock(&init_mutex);
            continue; // Skip this iteration on failure
        }

        snprintf(content, content_size, "Message Content %zu", i);
        (*messages)[i].nas_message.content = content;

        pthread_mutex_unlock(&init_mutex);
    }

    pthread_mutex_destroy(&init_mutex);

    if (get_log_level() > 1) {
        printf("Initialization completed for %zu messages\n", count);
    }
}

void cleanup_ccch_messages(LTE_DL_CCCH_Message_Type1_T *messages, size_t count) {
    if (!messages) return;

    for (size_t i = 0; i < count; ++i) {
        free(messages[i].nas_message.content);
    }

    // Reset pool index
    pthread_mutex_lock(&pool_mutex);
    pool_index = 0;
    pthread_mutex_unlock(&pool_mutex);

    if (get_log_level() > 1) {
        printf("Cleanup completed for %zu messages\n", count);
    }
}

int main() {
    LTE_DL_CCCH_Message_Type1_T *messages;
    size_t message_count = 10;

    initialize_and_populate_ccch_messages(&messages, message_count);

    if (messages) {
        // Use the initialized messages
    }

    cleanup_ccch_messages(messages, message_count);
    return 0;
}
```

### Key Features:
- **Memory Pool**: A simple memory pool is used to manage allocations efficiently and avoid fragmentation.
- **Thread Safety**: Mutexes are employed to ensure thread-safe operations during initialization and allocation from the pool.
- **Logging**: Basic logging is integrated, with log levels affecting verbosity.
- **Dynamic Message Generation**: Each message's type and content are dynamically generated.
- **Resource Cleanup**: Proper cleanup of allocated resources ensures no memory leaks.']

