#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

record* allocate_and_populate_records(size_t N, long predetermined_offset, int predetermined_key, int min_value, int max_value) {
    if (N <= 0) return NULL; // Handle invalid input

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Allocate memory for the array of records
    record* records = (record*)malloc(N * sizeof(record));
    if (!records) return NULL; // Check for allocation failure

    for (size_t i = 0; i < N; ++i) {
        records[i].offset = predetermined_offset + i; // Set offset
        records[i].key = predetermined_key + i;       // Set key
        records[i].value = rand() % (max_value - min_value + 1) + min_value; // Random value within range
    }

    return records;
}

void free_records(record* records) {
    if (records) {
        free(records);
    }
}

int main() {
    size_t N = 10;
    long predetermined_offset = 1000;
    int predetermined_key = 200;
    int min_value = 1, max_value = 100;

    record* records = allocate_and_populate_records(N, predetermined_offset, predetermined_key, min_value, max_value);
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return EXIT_FAILURE;
    }

    // Example usage: Print the records
    for (size_t i = 0; i < N; ++i) {
        printf("Record %zu: Offset = %ld, Key = %d, Value = %d\n", i, records[i].offset, records[i].key, records[i].value);
    }

    free_records(records);
    return EXIT_SUCCESS;
}
