// Define structures for network performance metrics and LTE message types
typedef struct Measurement {
    char type[20];
    double value;
} Measurement;

typedef struct NetworkPerformanceMetric {
    time_t timestamp;
    int session_id;
    int num_measurements;
    Measurement *measurements;
    struct NetworkPerformanceMetric *next;
} NetworkPerformanceMetric;

