    NAS_Message nas_message;
} LTE_DL_CCCH_Message_Type1;

// Logging mechanism setup
#define LOG_LEVEL_DEBUG 0
#define LOG_LEVEL_ERROR 1

void log_message(int level, const char *format, ...) {
    va_list args;
    if (level <= LOG_LEVEL_ERROR) { // Customize based on configuration
        va_start(args, format);
        vprintf(format, args);
        printf("\n");
        va_end(args);
    }
}

// Global variables for the linked list and LTE message types
NetworkPerformanceMetric *metrics_head = NULL;
LTE_DL_CCCH_Message_Type1 *lte_messages = NULL;

pthread_mutex_t metrics_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t metrics_cond = PTHREAD_COND_INITIALIZER;

void handle_signal(int signal) {
    log_message(LOG_LEVEL_DEBUG, "Signal %d received. Cleaning up.", signal);
    // Cleanup resources and terminate gracefully
    exit(EXIT_SUCCESS);
}

// Memory pool management for linked list
#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB Pool

char memory_pool[MEMORY_POOL_SIZE];
size_t pool_offset = 0;

void* allocate_from_pool(size_t size) {
    if (pool_offset + size > MEMORY_POOL_SIZE) {
        log_message(LOG_LEVEL_ERROR, "Memory pool exhausted.");
        return NULL;
    }
    void *ptr = &memory_pool[pool_offset];
    pool_offset += size;
    return ptr;
}

// Function to initialize network performance metrics
void initialize_and_manage_network_performance_metrics() {
    // Setup signal handling for graceful termination
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGHUP, &sa, NULL);

    pthread_t background_thread;
    int result = pthread_create(&background_thread, NULL, [] (void *arg) -> void* {
        // Placeholder for dynamic execution of background tasks
        while (1) {
            pthread_mutex_lock(&metrics_mutex);
            // Simulated task: log metrics and manage resources
            log_message(LOG_LEVEL_DEBUG, "Background task running.");
            sleep(5);  // Simulate work by sleeping
            pthread_mutex_unlock(&metrics_mutex);
        }
        return NULL;
    }, NULL);

    if (result != 0) {
        log_message(LOG_LEVEL_ERROR, "Failed to create background thread: %s", strerror(errno));
    }

    while (1) {  // Continuous loop for managing metrics
        NetworkPerformanceMetric *new_metric = allocate_from_pool(sizeof(NetworkPerformanceMetric));
        if (!new_metric) break;

        pthread_mutex_lock(&metrics_mutex);

        new_metric->timestamp = time(NULL);
        new_metric->session_id = rand() % 1000;  // Random session ID
        new_metric->num_measurements = rand() % 5 + 1;  // Up to 5 measurements

        new_metric->measurements = allocate_from_pool(new_metric->num_measurements * sizeof(Measurement));
        if (!new_metric->measurements) {
            log_message(LOG_LEVEL_ERROR, "Failed to allocate memory for measurements.");
            free(new_metric);
            pthread_mutex_unlock(&metrics_mutex);
            continue;
        }

        for (int i = 0; i < new_metric->num_measurements; ++i) {
            snprintf(new_metric->measurements[i].type, sizeof(new_metric->measurements[i].type), "Metric_%d", i + 1);
            new_metric->measurements[i].value = rand() % 100 / 10.0;
        }

        // Insert at head of linked list
        new_metric->next = metrics_head;
        metrics_head = new_metric;

        log_message(LOG_LEVEL_DEBUG, "New network performance metric added with session ID: %d", new_metric->session_id);

        pthread_mutex_unlock(&metrics_mutex);

        sleep(10);  // Simulate time interval between metric updates
    }
}

int main() {
    initialize_and_manage_network_performance_metrics();
    return 0;
}
```

### Key Points:
