#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int macAddress;
} MAC_ADDRESS_T;

typedef struct {
    // Assume LMAC_CONFIG is defined here
    int dummyConfigField; 
} LMAC_CONFIG_T;

typedef struct {
    LMAC_CONFIG_T config;
    MAC_ADDRESS_T* macAddresses;
    size_t macAddressCount;
} MAC_CONTEXT_T;

typedef struct {
    // Assume RX_UE_INFORMATION_TAG is defined here
    int dummyRxUeTag; 

    int rnti;

    struct {
        bool crcFlag;
    } crcIndicationRel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Union-Find structure and functions
typedef struct {
    int* parent;
    size_t size;
} UnionFind;

UnionFind* uf_create(size_t n) {
    UnionFind* uf = (UnionFind*)malloc(sizeof(UnionFind));
    if (!uf) return NULL;
    uf->parent = (int*)malloc(n * sizeof(int));
    uf->size = n;
    for (size_t i = 0; i < n; ++i) {
        uf->parent[i] = i;
    }
    return uf;
}

void uf_free(UnionFind* uf) {
    free(uf->parent);
    free(uf);
}

int find(UnionFind* uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void union_sets(UnionFind* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);
    if (rootX != rootY) {
        uf->parent[rootY] = rootX;
    }
}

int processNfaPairs(int* array, size_t length) {
    if (!array || length < 2) return 0;

    UnionFind* uf = uf_create(length);
    int disjointPairsCount = 0;

    for (size_t i = 0; i < length - 1; ++i) {
        for (size_t j = i + 1; j < length; ++j) {
            if (find(uf, array[i]) != find(uf, array[j])) {
                union_sets(uf, array[i], array[j]);
                disjointPairsCount++;
            }
        }
    }

    uf_free(uf);
    return disjointPairsCount;
}

void* manageDynamicArray(void* arg) {
    MAC_CONTEXT_T** contextArray = (MAC_CONTEXT_T**)arg;

    // Dynamic memory management logic here
    // Example: Add a new context to the array

    MAC_CONTEXT_T* newContext = malloc(sizeof(MAC_CONTEXT_T));
    if (!newContext) return NULL;

    // Initialize LMAC_CONFIG and MAC addresses for the new context
    newContext->config.dummyConfigField = 0; 
    newContext->macAddresses = NULL;
    newContext->macAddressCount = 0;

    size_t newSize = (size_t)(*contextArray == NULL ? 1 : (*(*contextArray)).length + 1);
    *contextArray = realloc(*contextArray, newSize * sizeof(MAC_CONTEXT_T*));

    if (*contextArray) {
        (*contextArray)[newSize - 1] = newContext;
    }

    return NULL;
}

void constructNfaPairsList(int* array, size_t length, NFAPI_CRC_INDICATION_PDU_T** pduList, size_t* listLength) {
    if (!array || !pduList || !listLength) return;

    *pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pduList) return;

    for (size_t i = 0; i < length; ++i) {
        (*pduList)[i].dummyRxUeTag = rand() % 100;
        (*pduList)[i].rnti = array[i];
        (*pduList)[i].crcIndicationRel8.crcFlag = rand() % 2 == 0;

        if (i > 0) {
            clock_t start = clock();

            int disjointPairsCount = processNfaPairs(array, i + 1);

            clock_t end = clock();
            double timeTakenMs = ((double)(end - start)) * 1000.0 / CLOCKS_PER_SEC;
            printf("Milliseconds taken for %zu elements: %.2f ms\n", i + 1, timeTakenMs);
        }
    }

    *listLength = length;
}

int main() {
    pthread_t thread;

    MAC_CONTEXT_T* contexts[1] = {NULL};

    if (pthread_create(&thread, NULL, manageDynamicArray, &contexts)) {
        fprintf(stderr, "Error creating thread\n");
        return 1;
    }

    pthread_join(thread, NULL);

    int inputArray[] = {1, 2, 3, 4, 5};
    size_t arrayLength = sizeof(inputArray) / sizeof(inputArray[0]);

    NFAPI_CRC_INDICATION_PDU_T* pduList;
    size_t listLength;

    constructNfaPairsList(inputArray, arrayLength, &pduList, &listLength);

    free(pduList);
    for (size_t i = 0; contexts[i] != NULL; ++i) {
        free(contexts[i]);
    }

    return 0;
}
