#define MAX_LINE_LENGTH 1024

typedef struct {
    int *integers;
    char **strings;
    size_t num_integers;
    size_t num_strings;
} ResourceBundle;

ResourceBundle* load_resource_bundle(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) return NULL;

    ResourceBundle *bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        fclose(file);
        return NULL;
    }

    bundle->integers = NULL;
    bundle->strings = NULL;
    bundle->num_integers = 0;
    bundle->num_strings = 0;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        if (line[0] == '\n') continue; // Skip empty lines

        char *endptr;
        long int_value = strtol(line, &endptr, 10);

        if (*endptr != '\n' && *endptr != '\r') { // Not a valid integer
            bundle->num_strings++;
            bundle->strings = realloc(bundle->strings, bundle->num_strings * sizeof(char *));
            if (!bundle->strings) {
                free_resources(bundle);
                fclose(file);
                return NULL;
            }
            bundle->strings[bundle->num_strings - 1] = strdup(line);
        } else { // Valid integer
            bundle->num_integers++;
            bundle->integers = realloc(bundle->integers, bundle->num_integers * sizeof(int));
            if (!bundle->integers) {
                free_resources(bundle);
                fclose(file);
                return NULL;
            }
            bundle->integers[bundle->num_integers - 1] = (int)int_value;
        }
    }

    fclose(file);
    return bundle;
}

void free_resources(ResourceBundle *bundle) {
    if (!bundle) return;

    free(bundle->integers);
    for (size_t i = 0; i < bundle->num_strings; ++i) {
        free(bundle->strings[i]);
    }
    free(bundle->strings);

    free(bundle);
}

int find_max_in_array(int *array, size_t size) {
    if (size == 0) return -1;

    int max_value = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }
    return max_value;
}

int* read_input_integers(size_t *num_integers) {
    int buffer_size = 10;
    char line[MAX_LINE_LENGTH];
    int *input_array = malloc(buffer_size * sizeof(int));
    if (!input_array) return NULL;

    size_t count = 0;
    while (fgets(line, sizeof(line), stdin)) {
        if (count >= buffer_size) {
            buffer_size *= 2;
            input_array = realloc(input_array, buffer_size * sizeof(int));
            if (!input_array) return NULL;
        }

        char *endptr;
        int value = strtol(line, &endptr, 10);

        if (*endptr == '\n' || *endptr == '\r') { // Valid integer
            input_array[count++] = value;
        }
    }

    *num_integers = count;
    return input_array;
}

int processResourcesAndFindMax(const char *file_path) {
    ResourceBundle *bundle = load_resource_bundle(file_path);
    if (!bundle) {
        fprintf(stderr, "Error loading resource bundle.\n");
        return -1;
    }

    size_t num_input_integers;
    int *input_array = read_input_integers(&num_input_integers);
    if (!input_array) {
        free_resources(bundle);
        fprintf(stderr, "Error reading input integers.\n");
        return -2;
    }

    int max_from_bundle = (bundle->num_integers > 0) ? find_max_in_array(bundle->integers, bundle->num_integers) : -1;
    int max_from_input = (num_input_integers > 0) ? find_max_in_array(input_array, num_input_integers) : -1;

    int overall_max = (max_from_bundle >= 0 && max_from_input >= 0) 
                      ? (max_from_bundle > max_from_input ? max_from_bundle : max_from_input)
                      : (max_from_bundle >= 0 ? max_from_bundle : max_from_input);

    free_resources(bundle);
    free(input_array);

    return overall_max;
}

int main() {
    const char *file_path = "resource_bundle.txt";
    int result = processResourcesAndFindMax(file_path);

    if (result >= 0) {
        printf("Maximum integer found: %d\n", result);
    } else {
        fprintf(stderr, "An error occurred during processing.\n");
    }

    return result < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}
