            array[i] = t;
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate(int n, int *error_code) {
    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    size_t capacity = 2 * n; // Start with a larger capacity
    array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        *error_code = -1;
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    int rnti_set[MAX_RNTI] = {0};
    size_t count = 0;

    srand(time(NULL)); // Seed for randomness

    while (count < n) {
