            if (count == capacity) {
                capacity *= 2;
                NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                if (!new_array) {
                    free(array);
                    *error_code = -1;
                    pthread_mutex_unlock(&mutex);
                    return NULL;
                }
                array = new_array;
            }
        }
    }

    shuffle_array(array, n);

    // Trim the excess allocated memory
    NFAPI_CRC_INDICATION_PDU_T *trimmed_array = realloc(array, n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (trimmed_array) {
        array = trimmed_array;
    } else {
        free(array);
        *error_code = -1;
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    *error_code = 0;
    pthread_mutex_unlock(&mutex);
    return array;
}

void free_memory(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (array) {
        free(array);
    }
}
