#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_FRAMES 10000

typedef struct {
    int rnti;
    // Other DL_FRAME_TX_TAG fields
} DL_FRAME_TX_RNTI_TAG;

typedef struct {
    // Other DL_FRAME_TX_TAG fields
} DL_FRAME_TX_TAG;

typedef struct LTE_DL_FRAME_MSG_T {
    DL_FRAME_TX_TAG tx_tag;
    DL_FRAME_TX_RNTI_TAG rnti_tag;
} LTE_DL_FRAME_MSG_T;

typedef struct FrameManager {
    LTE_DL_FRAME_MSG_T *frames;
    size_t count;
    pthread_mutex_t lock;
} FrameManager;

FrameManager* create_frame_manager() {
    FrameManager *manager = malloc(sizeof(FrameManager));
    if (!manager) return NULL;

    manager->frames = calloc(MAX_FRAMES, sizeof(LTE_DL_FRAME_MSG_T));
    if (!manager->frames) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;

    return manager;
}

int add_frame(FrameManager *manager, LTE_DL_FRAME_MSG_T frame) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_FRAMES) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // No space to add a new frame
    }

    manager->frames[manager->count++] = frame;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_frame_by_rnti(FrameManager *manager, int rnti) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->frames[i].rnti_tag.rnti == rnti) {
            // Shift elements to fill the gap
            memmove(&manager->frames[i], &manager->frames[i + 1],
                    (manager->count - i - 1) * sizeof(LTE_DL_FRAME_MSG_T));
            manager->count--;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Successfully removed
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Frame not found
}

size_t get_frame_count(FrameManager *manager) {
    pthread_mutex_lock(&manager->lock);
    size_t count = manager->count;
    pthread_mutex_unlock(&manager->lock);

    return count;
}

void destroy_frame_manager(FrameManager *manager) {
    if (manager) {
        free(manager->frames);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
