NFAPI_CRC_INDICATION_PDU_T* create_and_populate_array(size_t N) {
    if (N == 0) return NULL;

    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    const char *key = "0123456789abcdef"; // Example key
    const char *iv = "1234567890abcdef";  // Example IV

    EVP_CIPHER *cipher = select_cipher("ECB"); // Choose desired mode: ECB, EDE, etc.
    if (!cipher) {
        fprintf(stderr, "Cipher selection failed.\n");
        free_resources(NULL, cipher_ctx, key, iv);
        return NULL;
    }

    size_t len;
    unsigned int *rnti_set = (unsigned int*) calloc(N, sizeof(unsigned int));
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

    size_t count = 0;
    while (count < N) {
        if (!array || count == N) {
            len = sizeof(NFAPI_CRC_INDICATION_PDU_T) * (N + count);
            array = realloc(array, len);
            rnti_set = realloc(rnti_set, (N + count) * sizeof(unsigned int));
        }

        unsigned int new_rnti = rand() % 0xFFFFFFFF;
        if (!is_unique(new_rnti, rnti_set, count)) {
            continue; // Duplicate found, retry
        }

        array[count].RX_UE_INFORMATION_TAG = rand();
        array[count].RNTI = new_rnti;
        array[count].CRC_INDICATION_REL8_TAG = rand();

        rnti_set[count] = new_rnti;
        count++;
    }

    shuffle_array(array, N);

    EVP_CIPHER_CTX_free(cipher_ctx);
    return array;
}

void free_resources(NFAPI_CRC_INDICATION_PDU_T* array, EVP_CIPHER_CTX *cipher_ctx, const char *key, const char *iv) {
    if (array) free(array);
    if (cipher_ctx) EVP_CIPHER_CTX_free(cipher_ctx);
}

EVP_CIPHER* select_cipher(const char *mode) {
    if (strcmp(mode, "ECB") == 0) return EVP_des_ecb();
    else if (strcmp(mode, "EDE") == 0) return EVP_des_ede3(); // Assuming EDE and EDE3 use same function
    else if (strcmp(mode, "CFB") == 0) {
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        if (!ctx) return NULL;
        int ok = EVP_CipherInit_ex(ctx, EVP_des_cfb8(), NULL, NULL, NULL, 1);
        if (ok > 0) return EVP_CIPHER_CTX_cipher(ctx);
    }
    else if (strcmp(mode, "NULL") == 0) {
        return EVP_null();
    }
    return NULL;
}

static int is_unique(unsigned int RNTI, unsigned int *array, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        if (array[i] == RNTI) return 0;
    }
    return 1;
}

static void shuffle_array(NFAPI_CRC_INDICATION_PDU_T *array, size_t N) {
    if (!array || N <= 1) return;

    for (size_t i = N - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);

        // Swap array[i] with array[j]
        NFAPI_CRC_INDICATION_PDU_T temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}
