// Helper function to generate cryptographically secure random number
int cs_rand(int min, int max) {
    int range = max - min + 1;
    unsigned long rand_val;
    if (RAND_bytes((unsigned char*)&rand_val, sizeof(rand_val)) != 1) {
        fprintf(stderr, "Failed to generate random bytes\n");
        exit(EXIT_FAILURE);
    }
    return min + (int)(rand_val % range);
}

// Helper function to format int into string
