    snprintf(str, len, "%d", num);
}

// Function to allocate and initialize arrays
void allocate_and_initialize_arrays(long num_records, LoggerInterface* logger) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Number of records exceeds the maximum allowed limit\n");
        return;
    }

    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    Record* records = malloc(num_records * sizeof(Record));
    EventLog* event_logs = malloc(num_records * 10 * sizeof(EventLog)); // Assume max 10 operations per record

    if (!offsets || !keys || !records || !event_logs) {
        free(offsets);
        free(keys);
        free(records);
        free(event_logs);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    int unique_keys[MAX_RECORDS] = {0};
    time_t last_timestamp = 0;

    for (long i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&lock);

        // Generate a unique random key
        int key;
        do {
            key = cs_rand(1, KEY_RANGE);
        } while (unique_keys[key - 1]);

        unique_keys[key - 1] = 1;

        // Set record fields
        records[i].value = key;
        int_to_str(key, records[i].str_value, CHAR_ARRAY_SIZE);
        records[i].timestamp = time(NULL);

        if (records[i].timestamp <= last_timestamp) {
            fprintf(stderr, "Timestamps must be monotonically increasing\n");
            exit(EXIT_FAILURE);
        }
        last_timestamp = records[i].timestamp;

        snprintf(records[i].source, sizeof(records[i].source), "input_%ld", i);

        // Log the creation of the record
        if (logger && logger->log_operation) {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Record %d created at %ld", key, records[i].timestamp);
            logger->log_operation(log_message);
        }

        pthread_mutex_unlock(&lock);

        offsets[i] = i; // Example offset
        keys[i] = key;
    }

    free(offsets);
    free(keys);
    free(records);
    free(event_logs);
}

// Dummy logging function for demonstration purposes
