    free(cache);
}

int get_next_sequence_number(SequenceCache* cache) {
    pthread_mutex_lock(&cache->lock);

    // Simulate retrieving from an external data source
    int new_seq_num = rand() % 1000 + 1; // Example range

    if (cache->count < CACHE_SIZE) {
        for (int i = 0; i < cache->count; ++i) {
            if (cache->sequence_numbers[i] == -1) {
                cache->sequence_numbers[i] = new_seq_num;
                pthread_mutex_unlock(&cache->lock);
                return new_seq_num;
            }
        }
        cache->sequence_numbers[cache->count++] = new_seq_num;
    } else {
        // Evict the least recently used item
        int lru_index = 0; // Simplified LRU eviction strategy for demo purposes
        cache->sequence_numbers[lru_index] = new_seq_num;
    }

    pthread_mutex_unlock(&cache->lock);
    return new_seq_num;
}

// Custom shuffle algorithm (Fisher-Yates shuffle)
void custom_shuffle(TX_MESSAGE_T* array, size_t n) {
    if (n > 1) {
        for (size_t i = 0; i < n - 1; ++i) {
            size_t j = i + rand() / (RAND_MAX / (n - i) + 1);
            TX_MESSAGE_T temp = array[j];
            array[j] = array[i];
            array[i] = temp;
        }
    }
}

// Thread-safe dynamic memory management for the TX_MESSAGE_T array
TX_MESSAGE_T* initialize_tx_message_array(int M, SequenceCache* cache) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    TX_MESSAGE_T *array = malloc(M * sizeof(TX_MESSAGE_T));
    if (!array) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    int seq_numbers[M];
    for (int i = 0; i < M; ++i) {
        do {
            seq_numbers[i] = get_next_sequence_number(cache);
        } while (seq_numbers[i] == -1); // Retry on failure
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < M; ++i) {
        array[i].SEQUENCE_NUMBER = seq_numbers[i];
        array[i].PUSCH資源配置指示.TRANSPORT_FORMAT_AND_MIMO_MODE = rand() % 10;
        array[i].PUSCH資源配置指示.MODULATION_AND_CODEWORD_INDEX = rand() % 20; // Example range
    }

    pthread_mutex_unlock(&lock);
    custom_shuffle(array, M); // Shuffle the array

    return array;
}

void free_tx_message_array(TX_MESSAGE_T* array) {
