#define MAX_ELEMENTS 10000000
#define CACHE_SIZE 1000000

typedef struct Measurement {
    double value;
} Measurement;

typedef struct NetworkPerformanceMetrics {
    time_t timestamp;
    uint64_t session_id;
    Measurement *measurements;
    size_t num_measurements;
    struct NetworkPerformanceMetrics *prev, *next;
} NetworkPerformanceMetrics;

// Cache entry structure
typedef struct CacheEntry {
    NetworkPerformanceMetrics metrics;
    time_t expiry_time;
    struct CacheEntry *next;
} CacheEntry;

// Doubly linked list for network performance metrics
typedef struct {
    NetworkPerformanceMetrics *head;
    NetworkPerformanceMetrics *tail;
    size_t count;
    pthread_mutex_t lock;
    // Other members for external services, storage backends, etc.
} PerformanceList;

// Global cache and its lock
CacheEntry *cache = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void initPerformanceList(PerformanceList *list);
void addMetrics(PerformanceList *list, NetworkPerformanceMetrics metrics);
NetworkPerformanceMetrics* findMetrics(PerformanceList *list, uint64_t session_id, time_t start_time, time_t end_time, const char *measurement_type);
void cacheMetrics(NetworkPerformanceMetrics metrics, int ttl_seconds);
void freeList(PerformanceList *list);

// Initialize the performance list
void initPerformanceList(PerformanceList *list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Add metrics to the performance list
void addMetrics(PerformanceList *list, NetworkPerformanceMetrics metrics) {
    pthread_mutex_lock(&list->lock);

    metrics.prev = list->tail;
    metrics.next = NULL;

    if (list->count == 0) {
        list->head = &metrics;
    } else {
        list->tail->next = &metrics;
    }
    list->tail = &metrics;
    list->count++;

    pthread_mutex_unlock(&list->lock);

    // Cache the metrics
    cacheMetrics(metrics, 3600); // TTL set to 1 hour as an example
}

// Find metrics in the list based on session ID and timestamp range
NetworkPerformanceMetrics* findMetrics(PerformanceList *list, uint64_t session_id, time_t start_time, time_t end_time, const char *measurement_type) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics *current = list->head;
    while (current != NULL) {
        if (current->session_id == session_id && current->timestamp >= start_time && current->timestamp <= end_time) {
            // Implement measurement type filtering if necessary
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Cache the metrics with a TTL
void cacheMetrics(NetworkPerformanceMetrics metrics, int ttl_seconds) {
    pthread_mutex_lock(&cache_lock);

    CacheEntry *new_entry = malloc(sizeof(CacheEntry));
    if (new_entry == NULL) {
        fprintf(stderr, "Memory allocation failed for cache entry\n");
        return;
    }

    new_entry->metrics = metrics;
    new_entry->expiry_time = time(NULL) + ttl_seconds;

    // Append to the end of the cache
    if (cache == NULL) {
        cache = new_entry;
    } else {
        CacheEntry *current = cache;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_entry;
    }

    pthread_mutex_unlock(&cache_lock);
}

// Free all elements in the list
void freeList(PerformanceList *list) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics *current = list->head;
    while (current != NULL) {
        NetworkPerformanceMetrics *next = current->next;
        free(current->measurements);
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);

    // Free cache
    pthread_mutex_lock(&cache_lock);
    CacheEntry *current_cache = cache, *next_cache;
    while (current_cache != NULL) {
        next_cache = current_cache->next;
        free(current_cache);
        current_cache = next_cache;
    }
    cache = NULL;
    pthread_mutex_unlock(&cache_lock);

    pthread_mutex_destroy(&list->lock);
}

// Example main function
int main() {
    PerformanceList list;
    initPerformanceList(&list);

    // Simulate adding metrics
    NetworkPerformanceMetrics metric;
    time_t now = time(NULL);
    metric.timestamp = now;
    metric.session_id = 12345678; // Unique session ID example
    metric.num_measurements = 1;
    metric.measurements = malloc(sizeof(Measurement));
    if (metric.measurements == NULL) {
        fprintf(stderr, "Memory allocation failed for measurements\n");
        return EXIT_FAILURE;
    }
    metric.measurements[0].value = 100.0; // Example measurement value

    addMetrics(&list, metric);

    NetworkPerformanceMetrics *found_metrics = findMetrics(&list, 12345678, now - 3600, now + 3600, NULL);
    if (found_metrics != NULL) {
        printf("Found metrics with session ID: %llu\n", found_metrics->session_id);
    }

    freeList(&list);

    return EXIT_SUCCESS;
}
