bool processNetworkStream(int socket, float **dataArray, size_t *size) {
    const int bufferSize = 1024;
    char buffer[bufferSize];
    float tempData;
    *dataArray = NULL;
    *size = 0;

    while (recv(socket, buffer, bufferSize, 0) > 0) {
        // Assuming data is sent in newline separated format
        char *token = strtok(buffer, "\n");
        while (token != NULL) {
            if (sscanf(token, "%f", &tempData) == 1 && tempData >= -100.0f && tempData <= 100.0f) { // Validate range
                float *newArray = realloc(*dataArray, (*size + 1) * sizeof(float));
                if (!newArray) {
                    free(*dataArray);
                    return false;
                }
                *dataArray = newArray;
                (*dataArray)[*size] = tempData;
                ++(*size);
            } else {
                // Handle invalid data
            }

            token = strtok(NULL, "\n");
        }
    }

    if (socket < 0) { // Error handling for socket
        free(*dataArray);
        return false;
    }

    // Sort using QuickSort
    qsort(*dataArray, *size, sizeof(float), compareFloats);

    return true;
}

float findMedian(float *array, size_t size) {
    if (size == 0)
        return 0.0f;

    size_t midIndex = size / 2;
    return array[midIndex];
}

int compareFloats(const void *a, const void *b) {
    float fa = *(const float *)a;
    float fb = *(const float *)b;
    return (fa > fb) - (fa < fb);
}

void populateLtePhyConfigs(LtePhyConfig **configs, size_t *configCount) {
    // Assume externalDBFetch is a function that fetches configurations
    extern int externalDBFetch(LtePhyConfig **configs, size_t *configCount);

    if (externalDBFetch(configs, configCount) != 0) { // Error handling for DB access
        return;
    }

    // Populate LtePhyConfigs with data from the database
    for (size_t i = 0; i < *configCount; ++i) {
        (*configs)[i] = malloc(sizeof(LtePhyConfig));
        if (!(*configs)[i]) { 
            for (size_t j = 0; j < i; ++j)
                free((*configs)[j]);
            free(*configs);
            *configs = NULL;
            return;
        }

        // Assume these functions fetch configuration parameters
        (*configs)[i]->bandwidth = /* fetch bandwidth */;
        (*configs)[i]->numerology = /* fetch numerology */;
        (*configs)[i]->cellID = /* fetch cell ID */;
    }
}
