#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 4000
#define PACKET_PROCESSING_RATE 20000 // packets per second

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    uint32_t CRCFLAG;
    int HEADER_FLAG; // Unique flag for critical packets
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T packet;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    double totalProcessingTime;
    int criticalPacketCount;
} PacketList;

void initializePacketList(PacketList* list) {
    list->head = NULL;
    list->count = 0;
    list->totalProcessingTime = 0.0;
    list->criticalPacketCount = 0;
}

int addPacket(PacketList* list, NFAPI_CRC_INDICATION_PDU_T packet, int maxElements) {
    if (list->count >= maxElements) return -1;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -2; // Memory allocation failed

    newNode->packet = packet;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
    return 0;
}

void freePacketList(PacketList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

void processPackets(PacketList* list, int maxElements) {
    // Simulate packet processing
    Node* current = list->head;
    while (current != NULL) {
        double startTime = clock() / (double)CLOCKS_PER_SEC;

        // Process packet
        if (current->packet.HEADER_FLAG == 1) {
            list->criticalPacketCount++;
        }

        // Simulate latency handling and critical packet processing

        double endTime = clock() / (double)CLOCKS_PER_SEC;
        list->totalProcessingTime += (endTime - startTime);

        current = current->next;
    }
}

void printPacketList(PacketList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %u\n",
               current->packet.RX_UE_INFORMATION_TAG,
               current->packet.RNTI,
               current->packet.CRC_INDICATION_REL8_TAG,
               current->packet.CRCFLAG);
        current = current->next;
    }
}

void logPerformanceMetrics(PacketList* list) {
    printf("Critical Packets Handled: %d\n", list->criticalPacketCount);
    if (list->count > 0) {
        double avgProcessingTime = list->totalProcessingTime / list->count;
        printf("Average Processing Time per Packet: %.6f seconds\n", avgProcessingTime);
    }
}

void processIncomingPackets(int maxElements) {
    PacketList packetList;
    initializePacketList(&packetList);

    // Simulate incoming packets
    for (int i = 0; i < PACKET_PROCESSING_RATE / 2; ++i) { // Simulate half the rate for demonstration
        NFAPI_CRC_INDICATION_PDU_T packet = {
            .RX_UE_INFORMATION_TAG = rand() % 100,
            .RNTI = rand() % 100 + 1, // RNTI ranges from 1 to N
            .CRC_INDICATION_REL8_TAG = rand() % 100,
            .CRCFLAG = rand() & 0xFFFFFFFF,
            .HEADER_FLAG = (rand() % 10 == 0) ? 1 : 0 // 10% chance of being critical
        };

        int result = addPacket(&packetList, packet, maxElements);
        if (result != 0) {
            printf("Failed to add packet: %d\n", result);
        }
    }

    processPackets(&packetList, maxElements);
    printPacketList(&packetList);
    logPerformanceMetrics(&packetList);

    freePacketList(&packetList);
}

int main() {
    srand(time(NULL));
    int maxElements = MAX_PACKETS;
    processIncomingPackets(maxElements);
    return 0;
}
