import <sys/wait.h>

typedef struct {
    int value;
} record;

#define MAX_CHILDREN 10
#define MAX_TASKS 5

void *task_function(void *arg);
void handle_signal(int signum);

typedef struct {
    pid_t child_pid;
    int task_id;
    // Additional fields if necessary
} TaskInfo;

TaskInfo tasks[MAX_CHILDREN];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int active_tasks = 0;

void run_concurrent_tasks(int user_id, int group_id, int offset_count, long *offsets, int key_count, int *keys) {
    pid_t pids[MAX_TASKS] = {0};
    signal(SIGCHLD, handle_signal);

    for (int i = 0; i < MAX_TASKS && i < active_tasks; ++i) {
        if (pids[i] == 0) {
            pids[i] = fork();
            if (pids[i] == -1) {
                perror("fork");
                exit(EXIT_FAILURE);
            }
            if (pids[i] == 0) { // Child process
                setuid(user_id);   // Set UID for the task
                setgid(group_id);  // Set GID for the task

                // Task-specific code goes here

                exit(0); // Exit after completing the task
            } else {
                tasks[i].child_pid = pids[i];
                tasks[i].task_id = i;
                active_tasks++;
            }
        }
    }

    monitor_resources();

    while (active_tasks > 0) {
        pause(); // Wait for signal to process child status change
    }
}

void handle_signal(int signum) {
    int status;
    pid_t pid;

    if (signum == SIGCHLD) {
        while ((pid = waitpid(-1, &status, WNOHANG)) > 0) {
            pthread_mutex_lock(&lock);
            for (int i = 0; i < MAX_CHILDREN; ++i) {
                if (tasks[i].child_pid == pid) {
                    tasks[i].child_pid = 0;
                    active_tasks--;
