IDataReader generateAndInsertNFAPICRCIndications(int N, SQLConnection* conn, const char* sqlCommand) {
    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Allocate memory for structures
    NFAPI_CRC_INDICATION_PDU_T* nfaArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaArray) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    char** placeholders = (char**)malloc(N * sizeof(char*));

    // Generate data
    for (int i = 0; i < N; ++i) {
        nfaArray[i].crc_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        // Prepare SQL placeholders
