            i + 1,             // Example RNTI
            rand() % 1000000,  // Random RX_UE_INFORMATION_TAG
            nfaArray[i].crc_tag.CRCFLAG);
    }

    // Construct batch SQL insert statement
    char* query = (char*)malloc(10 * N * sizeof(char));
    snprintf(query, 10 * N, "INSERT INTO your_table_name VALUES %s", placeholders[0]);

    for (int i = 1; i < N; ++i) {
        strncat(query, ", ", 2);
        strncat(query, placeholders[i], strlen(placeholders[i]));
    }

    // Execute SQL command
    IDataReader* dataReader = NULL;
    if (conn != NULL && sqlCommand != NULL) {
        int status = SQLExecuteWithQuery(conn, query);
        if (status == SQL_SUCCESS) {
            dataReader = SQLGetDataResult(conn);  // Assume this gets the result set
        } else {
            fprintf(stderr, "SQL execution failed with error: %d\n", status);
        }
    }

    // Free allocated memory
    freeMemory(query);
    for (int i = 0; i < N; ++i) {
        freeMemory(placeholders[i]);
    }
    freeMemory(placeholders);
    freeMemory(nfaArray);

    return dataReader;
}
