typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG; // Randomly set CRC flag
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char hostname[256];
    char ip_address[INET6_ADDRSTRLEN];
    time_t timestamp;
} DNSCacheEntry;

DNSCacheEntry dns_cache[DNS_CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
int cache_count = 0;

NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_pdu(int tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu) {
        pdu->RX_UE_INFORMATION_TAG = tag;
        pdu->RNTI = rnti;
        pdu->CRCFLAG = rand() % 2; // Randomly set CRC flag
    }
    return pdu;
}

void free_nfa_crc_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        free(pdu);
    }
}

int resolve_dns(const char* hostname, char* ip_address) {
    struct hostent* he = gethostbyname(hostname);
    if (he && he->h_addr_list[0]) {
        inet_ntop(AF_INET, he->h_addr_list[0], ip_address, INET6_ADDRSTRLEN);
        return 0; // Success
    }
    return -1; // Failure
}

void* dns_resolver_thread(void* arg) {
    char* hostnames[MAX_HOSTNAMES] = {"example.com", "test.net", "sample.org"};
    while (1) {
        for (int i = 0; i < MAX_HOSTNAMES; ++i) {
            char ip_address[INET6_ADDRSTRLEN];
            if (resolve_dns(hostnames[i], ip_address) == 0) {
                pthread_mutex_lock(&cache_lock);
                DNSCacheEntry* entry = NULL;
                for (int j = 0; j < cache_count; ++j) {
                    if (strcmp(dns_cache[j].hostname, hostnames[i]) == 0) {
                        entry = &dns_cache[j];
                        break;
                    }
                }
                if (!entry || difftime(time(NULL), dns_cache[j].timestamp) > 3600) { // Refresh every hour
                    if (!entry) {
                        if (cache_count < DNS_CACHE_SIZE) {
                            entry = &dns_cache[cache_count++];
                        } else {
                            continue; // Cache is full, skip this resolution
                        }
                    }
                    strncpy(entry->hostname, hostnames[i], sizeof(entry->hostname));
                    strncpy(entry->ip_address, ip_address, INET6_ADDRSTRLEN);
                    entry->timestamp = time(NULL);
                }
                pthread_mutex_unlock(&cache_lock);
            } else {
                fprintf(stderr, "DNS resolution failed for %s\n", hostnames[i]);
            }
        }
        sleep(60); // Wait a minute before next batch
    }
    return NULL;
}

int manage_nfa_crc_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdus[], int count) {
    pthread_t dns_thread;
    if (pthread_create(&dns_thread, NULL, dns_resolver_thread, NULL) != 0) {
        perror("Failed to create DNS resolver thread");
        return -1;
    }

    for (int i = 0; i < count; ++i) {
        pdus[i] = create_nfa_crc_pdu(i + 1, rand() % 100);
        if (!pdus[i]) {
            fprintf(stderr, "Failed to allocate NFAPI_CRC_INDICATION_PDU_T structure\n");
            return -1;
        }
    }

    // Simulate some operation with the list
    for (int i = 0; i < count; ++i) {
        printf("PDU[%d]: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%u\n",
               i, pdus[i]->RX_UE_INFORMATION_TAG, pdus[i]->RNTI, pdus[i]->CRCFLAG);
    }

    // Cleanup
    for (int i = 0; i < count; ++i) {
        free_nfa_crc_pdu(pdus[i]);
    }
    pthread_cancel(dns_thread);
    pthread_join(dns_thread, NULL);

    return 0;
}
