typedef struct Edge {
    int from;
    int to;
    float weight;
    struct Edge* next;
} Edge;

typedef struct Vertex {
    int id;
    char properties[256];
    Edge* edges;
    struct Vertex* next;
} Vertex;

typedef struct Graph {
    Vertex* vertices;
    int vertex_count;
    int edge_count;
} Graph;

Graph* create_graph(int vertex_count) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->vertices = NULL;
    graph->vertex_count = 0;
    graph->edge_count = 0;

    for (int i = 0; i < vertex_count; ++i) {
        Vertex* vertex = (Vertex*)malloc(sizeof(Vertex));
        vertex->id = i;
        snprintf(vertex->properties, sizeof(vertex->properties), "Property_%d", rand());
        vertex->edges = NULL;
        vertex->next = graph->vertices;
        graph->vertices = vertex;
    }
    graph->vertex_count = vertex_count;

    return graph;
}

void add_edge(Graph* graph, int from, int to) {
    if (from >= graph->vertex_count || to >= graph->vertex_count)
        return;

    Edge* edge = (Edge*)malloc(sizeof(Edge));
    edge->from = from;
    edge->to = to;
    edge->weight = (float)(rand() % 100) / 10.0f;
    edge->next = NULL;

    Vertex* vertex = graph->vertices;
    while (vertex != NULL && vertex->id != from)
        vertex = vertex->next;

    if (vertex != NULL) {
        edge->next = vertex->edges;
        vertex->edges = edge;
        graph->edge_count++;
    }
}

void simulate_graph_operations(int n_vertices, int n_edges) {
    srand(time(NULL));
    Graph* graph = create_graph(n_vertices);

    for (int i = 0; i < n_edges; ++i) {
        int from = rand() % n_vertices;
        int to = rand() % n_vertices;
        add_edge(graph, from, to);
    }

    // Free the graph
    Vertex* vertex = graph->vertices;
    while (vertex != NULL) {
        Edge* edge = vertex->edges;
        while (edge != NULL) {
            Edge* temp_edge = edge;
            edge = edge->next;
            free(temp_edge);
        }
        Vertex* temp_vertex = vertex;
        vertex = vertex->next;
        free(temp_vertex);
    }
    free(graph);
}

