        list[i].RNTI = rand();
        list[i].crc_tag.CRCFLAG = rand() & 1;
    }
    *size = n;
    return list;
}

void free_nfa_pcr_indications(NFAPI_CRC_INDICATION_PDU_T* list, int size) {
    free(list);
}

