void append_md5_node(MD5Node **head, MD5Node *new_node) {
    if (*head == NULL) {
        *head = new_node;
    } else {
        MD5Node *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void free_md5_list(MD5Node *head) {
