#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_MESSAGE_TYPE 100
#define CACHE_SIZE_LIMIT 1000

typedef struct {
    int sequence_number;
} TLVEncoder;

typedef struct {
    int message_type;
    char *content;
} NAS_Message;

typedef struct {
    TLVEncoder encoder;
    NAS_Message nas_message;
} LTE_DL_CCCH_Message_Type1_T;

typedef enum { SUCCESS, MEMORY_ERROR, INVALID_PARAM } ErrorCode;

static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t total_messages_processed = 0;

// Helper function to generate random message type and content
void generate_random_NAS_Message(NAS_Message *message) {
    if (!message) return;

    message->message_type = rand() % MAX_MESSAGE_TYPE;
    const char alphabet[] = "abcdefghijklmnopqrstuvwxyz";
    size_t length = rand() % 20 + 1; // Random length between 1 and 20
    message->content = malloc(length + 1);
    if (message->content) {
        for (size_t i = 0; i < length; ++i) {
            message->content[i] = alphabet[rand() % (sizeof(alphabet) - 1)];
        }
        message->content[length] = '\0';
    }
}

// Function to initialize messages
ErrorCode initialize_DL_CCCH_Messages(LTE_DL_CCCH_Message_Type1_T **messages, size_t max_messages, size_t *actual_count) {
    if (!messages || !max_messages || !actual_count) return INVALID_PARAM;

    *messages = NULL;
    *actual_count = 0;

    srand(time(NULL));

    for (size_t i = 0; i < max_messages; ++i) {
        LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(*messages, sizeof(LTE_DL_CCCH_Message_Type1_T) * (*actual_count + 1));
        if (!new_messages) return MEMORY_ERROR;

        *messages = new_messages;
        TLVEncoder *encoder = &((*messages)[*actual_count].encoder);
        NAS_Message *nas_message = &((*messages)[*actual_count].nas_message);

        encoder->sequence_number = (int)(*actual_count + 1);
        generate_random_NAS_Message(nas_message);

        pthread_mutex_lock(&cache_lock);
        if (++total_messages_processed > CACHE_SIZE_LIMIT) {
            // Implement eviction policy here, e.g., LRU or LFU
            total_messages_processed--; // Placeholder for actual eviction logic
        }
        pthread_mutex_unlock(&cache_lock);

        (*actual_count)++;
    }

    return SUCCESS;
}

// Function to serialize messages into binary format
int serialize_DL_CCCH_Messages(const LTE_DL_CCCH_Message_Type1_T *messages, size_t message_count, unsigned char **binary_data) {
    if (!messages || !message_count || !binary_data) return -1;

    size_t total_size = 0;
    for (size_t i = 0; i < message_count; ++i) {
        const NAS_Message *nas_message = &messages[i].nas_message;
        total_size += sizeof(int) + sizeof(size_t) + strlen(nas_message->content) + 1;
    }

    unsigned char *data = malloc(total_size);
    if (!data) return -1;

    size_t offset = 0;
    for (size_t i = 0; i < message_count; ++i) {
        const LTE_DL_CCCH_Message_Type1_T *msg = &messages[i];
        memcpy(data + offset, &(msg->encoder.sequence_number), sizeof(int));
        offset += sizeof(int);
        size_t content_len = strlen(msg->nas_message.content) + 1;
        memcpy(data + offset, &content_len, sizeof(size_t));
        offset += sizeof(size_t);
        memcpy(data + offset, msg->nas_message.content, content_len);
        offset += content_len;
    }

    *binary_data = data;
    return total_size;
}

// Function to deserialize messages from binary format
ErrorCode deserialize_DL_CCCH_Messages(const unsigned char *binary_data, size_t data_size, LTE_DL_CCCH_Message_Type1_T **messages) {
    if (!binary_data || !data_size || !messages) return INVALID_PARAM;

    const unsigned char *ptr = binary_data;
    size_t message_count = 0;

    while (ptr < binary_data + data_size) {
        int sequence_number;
        memcpy(&sequence_number, ptr, sizeof(int));
        ptr += sizeof(int);

        size_t content_len;
        memcpy(&content_len, ptr, sizeof(size_t));
        ptr += sizeof(size_t);

        if (ptr + content_len > binary_data + data_size) return INVALID_PARAM;

        NAS_Message nas_message;
        nas_message.message_type = rand() % MAX_MESSAGE_TYPE; // Placeholder for real message type
        nas_message.content = malloc(content_len);
        if (!nas_message.content) return MEMORY_ERROR;

        memcpy(nas_message.content, ptr, content_len);
        ptr += content_len;

        LTE_DL_CCCH_Message_Type1_T new_message = {
            .encoder = { .sequence_number = sequence_number },
            .nas_message = nas_message
        };

        *messages = realloc(*messages, sizeof(LTE_DL_CCCH_Message_Type1_T) * (message_count + 1));
        if (!*messages) {
            free(nas_message.content);
            return MEMORY_ERROR;
        }

        (*messages)[message_count] = new_message;
        message_count++;
    }

    return SUCCESS;
}

// Function to free allocated memory for messages
void cleanup_DL_CCCH_Messages(LTE_DL_CCCH_Message_Type1_T *messages, size_t count) {
    if (!messages) return;

    for (size_t i = 0; i < count; ++i) {
        free(messages[i].nas_message.content);
    }

    free(messages);
}

// Example usage
int main() {
    LTE_DL_CCCH_Message_Type1_T *messages;
    size_t actual_count;
    ErrorCode result = initialize_DL_CCCH_Messages(&messages, 10, &actual_count);

    if (result == SUCCESS) {
        unsigned char *binary_data;
        int data_size = serialize_DL_CCCH_Messages(messages, actual_count, &binary_data);

        LTE_DL_CCCH_Message_Type1_T *deserialized_messages = NULL;
        result = deserialize_DL_CCCH_Messages(binary_data, data_size, &deserialized_messages);

        if (result == SUCCESS) {
            cleanup_DL_CCCH_Messages(deserialized_messages, actual_count);
        }

        free(binary_data);
    }

    cleanup_DL_CCCH_Messages(messages, actual_count);
    return 0;
}
