#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

#define INITIAL_CAPACITY 10
#define CACHE_LINE_SIZE 64

typedef struct {
    // Example fields for LMAC_CONFIG
    int config_id;
} LMAC_CONFIG;

typedef struct {
    // Example fields for MAC_FRAME
    int frame_id;
} MAC_FRAME;

typedef struct MAC_FRAME_NODE {
    MAC_FRAME mac_frame;
    struct MAC_FRAME_NODE* next;
} MAC_FRAME_NODE;

typedef struct {
    LMAC_CONFIG lmac_config;
    MAC_FRAME_NODE* frames_head;
} MAC_CONTEXT_T;

typedef struct {
    MAC_CONTEXT_T** array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Memory management system
void* aligned_alloc(size_t alignment, size_t size) {
    void* ptr = NULL;
    posix_memalign(&ptr, alignment, size);
    return ptr;
}

DynamicArray* create_dynamic_array() {
    DynamicArray* dynamic_array = (DynamicArray*)aligned_alloc(CACHE_LINE_SIZE, sizeof(DynamicArray));
    if (!dynamic_array) {
        fprintf(stderr, "Failed to allocate memory for dynamic array\n");
        return NULL;
    }
    pthread_mutex_init(&dynamic_array->lock, NULL);
    dynamic_array->capacity = INITIAL_CAPACITY;
    dynamic_array->count = 0;
    dynamic_array->array = (MAC_CONTEXT_T**)aligned_alloc(CACHE_LINE_SIZE, sizeof(MAC_CONTEXT_T*) * dynamic_array->capacity);
    if (!dynamic_array->array) {
        fprintf(stderr, "Failed to allocate memory for array elements\n");
        pthread_mutex_destroy(&dynamic_array->lock);
        free(dynamic_array);
        return NULL;
    }
    return dynamic_array;
}

void destroy_dynamic_array(DynamicArray* dynamic_array) {
    if (!dynamic_array) return;

    pthread_mutex_lock(&dynamic_array->lock);
    for (size_t i = 0; i < dynamic_array->count; ++i) {
        MAC_FRAME_NODE* current = dynamic_array->array[i]->frames_head;
        while (current) {
            MAC_FRAME_NODE* temp = current;
            current = current->next;
            free(temp);
        }
        free(dynamic_array->array[i]);
    }
    pthread_mutex_unlock(&dynamic_array->lock);

    free(dynamic_array->array);
    pthread_mutex_destroy(&dynamic_array->lock);
    free(dynamic_array);
}

int add_mac_context(DynamicArray* dynamic_array, MAC_CONTEXT_T* context) {
    if (!dynamic_array || !context) return -1;

    pthread_mutex_lock(&dynamic_array->lock);
    if (dynamic_array->count == dynamic_array->capacity) {
        size_t new_capacity = dynamic_array->capacity * 2;
        MAC_CONTEXT_T** new_array = (MAC_CONTEXT_T**)aligned_alloc(CACHE_LINE_SIZE, sizeof(MAC_CONTEXT_T*) * new_capacity);
        if (!new_array) {
            pthread_mutex_unlock(&dynamic_array->lock);
            fprintf(stderr, "Failed to reallocate memory for array elements\n");
            return -1;
        }
        for (size_t i = 0; i < dynamic_array->count; ++i) {
            new_array[i] = dynamic_array->array[i];
        }
        free(dynamic_array->array);
        dynamic_array->array = new_array;
        dynamic_array->capacity = new_capacity;
    }

    dynamic_array->array[dynamic_array->count++] = context;
    pthread_mutex_unlock(&dynamic_array->lock);

    return 0;
}

MAC_CONTEXT_T* create_mac_context(int config_id) {
    MAC_CONTEXT_T* context = (MAC_CONTEXT_T*)aligned_alloc(CACHE_LINE_SIZE, sizeof(MAC_CONTEXT_T));
    if (!context) {
        fprintf(stderr, "Failed to allocate memory for MAC_CONTEXT_T\n");
        return NULL;
    }
    context->lmac_config.config_id = config_id;
    context->frames_head = NULL;
    return context;
}

void add_mac_frame_to_context(MAC_CONTEXT_T* context, MAC_FRAME frame) {
    if (!context) return;

    MAC_FRAME_NODE* new_node = (MAC_FRAME_NODE*)aligned_alloc(CACHE_LINE_SIZE, sizeof(MAC_FRAME_NODE));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for MAC_FRAME_NODE\n");
        return;
    }
    new_node->mac_frame = frame;
    new_node->next = context->frames_head;
    context->frames_head = new_node;
}

// Example usage
int main() {
    DynamicArray* dynamic_array = create_dynamic_array();
    if (!dynamic_array) return EXIT_FAILURE;

    MAC_CONTEXT_T* context1 = create_mac_context(1);
    add_mac_frame_to_context(context1, (MAC_FRAME){.frame_id = 101});
    add_mac_context(dynamic_array, context1);

    MAC_CONTEXT_T* context2 = create_mac_context(2);
    add_mac_frame_to_context(context2, (MAC_FRAME){.frame_id = 202});
    add_mac_context(dynamic_array, context2);

    destroy_dynamic_array(dynamic_array);
    return EXIT_SUCCESS;
}
```

