typedef struct {
    double number;
    char character;
} element;

element* read_elements_from_file(const char* filename, int* count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        *count = 0;
        return NULL;
    }

    element *elements = NULL;
    int capacity = 10;
    elements = (element*) malloc(capacity * sizeof(element));
    if (!elements) {
        fclose(file);
        perror("Memory allocation failed");
        *count = 0;
        return NULL;
    }

    int size = 0;
    double number;
    char character;

    while (fscanf(file, "%lf %c", &number, &character) == 2) {
        if (size >= capacity) {
            capacity *= 2;
            element* temp = realloc(elements, capacity * sizeof(element));
            if (!temp) {
                free(elements);
                fclose(file);
                perror("Memory reallocation failed");
                *count = 0;
                return NULL;
            }
            elements = temp;
        }

        elements[size].number = number;
        elements[size].character = character;
        size++;
    }

    if (ferror(file)) {
        free(elements);
        fclose(file);
        perror("Error reading file");
        *count = 0;
        return NULL;
    }

    fclose(file);

    element* final_elements = realloc(elements, size * sizeof(element));
    if (!final_elements && size > 0) {
        free(elements);
        perror("Memory reallocation failed");
        *count = 0;
        return NULL;
    }

    elements = final_elements;
    *count = size;

    return elements;
}

void free_elements_array(element* array) {
    free(array);
}
