    NetworkPerformanceMetrics data;
    struct ListNode *next;
} ListNode;

// Linked list with thread-safe access and dynamic resizing
typedef struct {
    ListNode *head;
    pthread_mutex_t lock;
    size_t length;
} LinkedList;

// Memory pool management system (simplified)
typedef struct {
    void **pool;
    size_t capacity;
    size_t used;
    pthread_mutex_t mem_lock;
} MemoryPool;

// Global configuration for retention policy and grace period
#define RETENTION_POLICY_HOURS 24
#define GRACE_PERIOD_MINUTES 30

// Function prototypes
void initialize_list(LinkedList *list);
void insert_metrics(LinkedList *list, NetworkPerformanceMetrics metrics);
void cleanup_outdated_metrics(LinkedList *list);
void* background_cleanup_task(void *args);
NetworkPerformanceMetrics create_metrics(int session_id, float *measurements, size_t count);
MemoryPool* create_memory_pool(size_t capacity);

// Initialize the linked list
void initialize_list(LinkedList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->length = 0;
}

// Insert metrics into the list
void insert_metrics(LinkedList *list, NetworkPerformanceMetrics metrics) {
    ListNode *new_node = malloc(sizeof(ListNode));
    new_node->data = metrics;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    list->length++;
    pthread_mutex_unlock(&list->lock);
}

// Cleanup outdated metrics based on retention policy
void cleanup_outdated_metrics(LinkedList *list) {
    time_t now = time(NULL);
    ListNode **curr = &list->head;

    while (*curr != NULL) {
        if ((now - (*curr)->data.timestamp) > (RETENTION_POLICY_HOURS * 3600 + GRACE_PERIOD_MINUTES * 60)) {
            ListNode *temp = *curr;
            *curr = (*curr)->next;
            free(temp);
            list->length--;
        } else {
            curr = &(*curr)->next;
        }
    }
}

// Background task for periodic cleanup
void* background_cleanup_task(void *args) {
    LinkedList *list = (LinkedList *)args;

    while (1) {
        sleep(60); // Run every minute
        cleanup_outdated_metrics(list);
        // Log statistics or send to monitoring system here
    }

    return NULL;
}

// Create a NetworkPerformanceMetrics instance
NetworkPerformanceMetrics create_metrics(int session_id, float *measurements, size_t count) {
    NetworkPerformanceMetrics metrics;
    metrics.timestamp = time(NULL);
    metrics.session_id = session_id;
    metrics.measurements = malloc(count * sizeof(float));
    memcpy(metrics.measurements, measurements, count * sizeof(float));
    metrics.measurement_count = count;

    return metrics;
}

// Create a memory pool
MemoryPool* create_memory_pool(size_t capacity) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->capacity = capacity;
    pool->used = 0;
    pool->pool = calloc(capacity, sizeof(void *));
    pthread_mutex_init(&pool->mem_lock, NULL);

    return pool;
}

