#include <stdio.h>
#include <stdlib.h>
import <string.h>
#include <pthread.h>
#include <time.h>

typedef enum {
    INFO,
    WARNING,
    ERROR,
    DEBUG
} statusType;

typedef struct logEntry {
    time_t timestamp;
    statusType status;
    const char* message;
    struct logEntry* next;
} logEntry;

logEntry* head = NULL;
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void addLogEntry(time_t timestamp, statusType status, const char* message) {
    pthread_mutex_lock(&logMutex);

    // Check for duplicate timestamps
    logEntry* current = head;
    while (current != NULL) {
        if (current->timestamp == timestamp) {
            printf("Duplicate timestamp detected. Skipping entry.\n");
            pthread_mutex_unlock(&logMutex);
            return;
        }
        current = current->next;
    }

    // Create new log entry
    logEntry* newEntry = (logEntry*)malloc(sizeof(logEntry));
    newEntry->timestamp = timestamp;
    newEntry->status = status;
    newEntry->message = message;
    newEntry->next = head;
    head = newEntry;

    pthread_mutex_unlock(&logMutex);
}

void filterLogEntriesByStatus(statusType status, void (*callback)(logEntry*)) {
    pthread_mutex_lock(&logMutex);

    logEntry* current = head;
    while (current != NULL) {
        if (current->status == status) {
            callback(current);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&logMutex);
}

void retrieveLogsInTimeRange(time_t start, time_t end, void (*callback)(logEntry*)) {
    pthread_mutex_lock(&logMutex);

    logEntry* current = head;
    while (current != NULL) {
        if (current->timestamp >= start && current->timestamp <= end) {
            callback(current);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&logMutex);
}

void freeLogEntries() {
    pthread_mutex_lock(&logMutex);

    logEntry* current = head;
    while (current != NULL) {
        logEntry* next = current->next;
        free((void*)current->message); // Assuming message was dynamically allocated
        free(current);
        current = next;
    }

    head = NULL;

    pthread_mutex_unlock(&logMutex);
}

// Placeholder for compression and decompression functions
