    srand(seed++);

    while (1) {
        int value = rand() % (max - min + 1) + min;
        int is_unique = 1;

        for (int i = 0; i < MAX_RECORDS && used_values[i] != 0; ++i) {
            if (used_values[i] == value) {
                is_unique = 0;
                break;
            }
        }

