} ConnectionManager;

// Utility functions
void log_metrics(const char *message, int active_connections, int successful_connections) {
    printf("Log: %s | Active Connections: %d | Successful Connections: %d\n",
           message, active_connections, successful_connections);
}

size_t generate_random_message_content(size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *message = malloc(length + 1);

    if (message) {
        for (size_t i = 0; i < length; i++) {
            message[i] = charset[rand() % (sizeof(charset) - 1)];
        }
        message[length] = '\0';
    }

    return (size_t)message;
}

// Connection Manager functions
ConnectionManager* create_connection_manager(size_t initial_capacity) {
    ConnectionManager *manager = malloc(sizeof(ConnectionManager));
    manager->connections = malloc(initial_capacity * sizeof(TCPConnection));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);

    return manager;
}

void free_connection_manager(ConnectionManager *manager) {
    for (size_t i = 0; i < manager->count; i++) {
        // Free any dynamically allocated memory in ApplicationData if needed
    }
    free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
    free(manager);
}

int add_connection(ConnectionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_CONNECTIONS) new_capacity = MAX_CONNECTIONS;

        TCPConnection *new_connections = realloc(manager->connections, new_capacity * sizeof(TCPConnection));
        if (!new_connections) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }

        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }

    // Initialize a random message for the connection
    size_t content_length = rand() % 256; // Random length up to 255 bytes
    char *message_content = (char *)generate_random_message_content(content_length);

    TCPConnection *connection = &manager->connections[manager->count++];
    memset(&connection->encoder, 0, sizeof(TLVEncoder));
    connection->data.content = message_content; // Assume ApplicationData has a content field

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_connection(ConnectionManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == 0) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // No connections to remove
    }

    manager->count--;
    free(manager->connections[manager->count].data.content); // Free dynamic content

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void monitor_connections(ConnectionManager *manager) {
    while (1) {
        sleep(5); // Log every 5 seconds
        int active_connections = manager->count; // Assume successful connections are tracked elsewhere
        log_metrics("Monitoring", active_connections, active_connections);

        pthread_mutex_lock(&manager->lock);
        if (manager->capacity > INITIAL_CAPACITY && manager->count < manager->capacity / 4) {
            size_t new_capacity = manager->capacity / 2;
            TCPConnection *new_connections = realloc(manager->connections, new_capacity * sizeof(TCPConnection));
            if (new_connections) {
                manager->connections = new_connections;
                manager->capacity = new_capacity;
            }
        }
        pthread_mutex_unlock(&manager->lock);
    }
}

// Example usage
int main() {
    srand(time(NULL));

    ConnectionManager *manager = create_connection_manager(INITIAL_CAPACITY);

    // Simulate adding connections
    for (int i = 0; i < 5000; i++) {
        if (add_connection(manager) != 0) break;
    }

    // Start monitoring in a separate thread
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, (void *(*)(void *))monitor_connections, manager);

    // Simulate removing connections
    for (int i = 0; i < 2500; i++) {
        remove_connection(manager);
    }

    // Clean up and exit
    pthread_cancel(monitor_thread);
    free_connection_manager(manager);

    return 0;
}
