```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define the Network Performance Metrics structure
typedef struct Measurement {
    char *name;
    double value;
} Measurement;

typedef struct NPMetrics {
    time_t timestamp;
    char session_id[64];
    Measurement *measurements;
    size_t measurement_count;
    struct NPMetrics *next;
} NPMetrics;

// Memory pool management for efficient scaling
#define POOL_SIZE 1024

typedef struct MemoryPool {
    void *pool[POOL_SIZE];
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool metrics_pool = { .used = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

void init_memory_pool() {
    for (int i = 0; i < POOL_SIZE; ++i) {
        metrics_pool.pool[i] = malloc(sizeof(NPMetrics));
    }
}

NPMetrics* allocate_metrics(size_t count) {
    pthread_mutex_lock(&metrics_pool.lock);
    if (metrics_pool.used >= POOL_SIZE) {
        printf("Memory pool exhausted.\n");
        pthread_mutex_unlock(&metrics_pool.lock);
        return NULL;
    }

    NPMetrics *metrics = (NPMetrics *)metrics_pool.pool[metrics_pool.used++];
    metrics->measurements = malloc(count * sizeof(Measurement));
    metrics->measurement_count = count;
    metrics->next = NULL;

    pthread_mutex_unlock(&metrics_pool.lock);

    return metrics;
}

void free_metrics(NPMetrics *metrics) {
    if (metrics) {
        free(metrics->measurements);
        // Return to pool
        pthread_mutex_lock(&metrics_pool.lock);
        metrics_pool.pool[--metrics_pool.used] = metrics;
        pthread_mutex_unlock(&metrics_pool.lock);
    }
}

