}

// Periodic cleanup task for outdated metrics
void* cleanup_task(void *arg) {
    while (1) {
        // Simulate cleanup based on retention policy
        sleep(60); // Assume a grace period of 1 minute

        pthread_mutex_lock(&metrics_pool.lock);
        size_t i = 0;
        while (i < metrics_pool.used) {
            NPMetrics *metric = (NPMetrics *)metrics_pool.pool[i];
            if ((time(NULL) - metric->timestamp) > 3600) { // Assume a retention policy of 1 hour
                free_metrics(metric);
            } else {
                i++;
            }
        }
        pthread_mutex_unlock(&metrics_pool.lock);
    }
}

int main() {
