        for (size_t i = 0; i < head->measurement_count; ++i) {
            head->measurements[i].name = "metric";
            head->measurements[i].value = rand() / (double)RAND_MAX;
        }
    }

    // Initialize graph
    Graph *graph = initialize_graph(10000);
    add_node(graph, 1);

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, cleanup_task, NULL);

    // Join the cleanup thread for demonstration purposes; in a real system this would run indefinitely.
    pthread_join(cleanup_thread, NULL);

    free_metrics(head);
    free(graph->nodes);
    free(graph);

    return 0;
}
