    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_LOG_SIZE 1024 * 1024 // Maximum log file size in bytes
#define LOG_FILE "error_log.txt"
#define BATCH_SIZE 1000

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void rotate_log_file() {
    char rotated_filename[256];
    snprintf(rotated_filename, sizeof(rotated_filename), "%s.%ld", LOG_FILE, time(NULL));
    rename(LOG_FILE, rotated_filename);
}

void log_error(const char *message) {
    pthread_mutex_lock(&lock);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        pthread_mutex_unlock(&lock);
        return;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    if (size > MAX_LOG_SIZE) {
        fclose(file);
        rotate_log_file();
        file = fopen(LOG_FILE, "a");
    }

    fprintf(file, "%s\n", message);
    fclose(file);

    pthread_mutex_unlock(&lock);
}

uint8_t get_random_crcflag() {
    // Use external source if available, otherwise fallback to rand()
    return rand() % 2;
}

void initialize_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = (uint16_t)(rand() % 65536);
    pdu->RNTI = (uint16_t)(rand() % 65536);
    for (int i = 0; i < 4; ++i) {
        pdu->CRC_INDICATION_REL8_TAG[i] = rand() % 256;
    }
    pdu->CRCFLAG = get_random_crcflag();
}

void *allocate_and_initialize_pdus(void *arg) {
    size_t num_pdus = *(size_t *)arg;

    NFAPI_CRC_INDICATION_PDU_T **pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (pdus == NULL) {
        log_error("Memory allocation failed for pdu pointers");
        return NULL;
    }

    size_t allocated = 0;
    while (allocated < num_pdus) {
        size_t batch_size = BATCH_SIZE < (num_pdus - allocated) ? BATCH_SIZE : (num_pdus - allocated);

        NFAPI_CRC_INDICATION_PDU_T *batch = malloc(batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (batch == NULL) {
            log_error("Memory allocation failed for pdu batch");
            break;
        }

        for (size_t i = 0; i < batch_size; ++i) {
            initialize_pdu(&batch[i]);
        }

        pdus[allocated] = batch;
        allocated += batch_size;
    }

    // Verify data integrity
    for (size_t i = 0; i < allocated; ++i) {
        if (pdus[i][0].CRCFLAG != get_random_crcflag()) {
            log_error("Data integrity check failed");
        }
    }

    *(NFAPI_CRC_INDICATION_PDU_T **)(arg + sizeof(size_t)) = pdus;
    return NULL;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t num_pdus) {
    for (size_t i = 0; i < num_pdus; ++i) {
        free(pdus[i]);
    }
    free(pdus);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <number_of_pdus>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t num_pdus = strtoul(argv[1], NULL, 10);
    pthread_t thread;

    srand(time(NULL)); // Seed the random number generator

    void *ptrs[2] = { &num_pdus, malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *)) };
    if (pthread_create(&thread, NULL, allocate_and_initialize_pdus, ptrs)) {
        log_error("Failed to create thread");
        free(ptrs[1]);
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);
    NFAPI_CRC_INDICATION_PDU_T **pdus = *(NFAPI_CRC_INDICATION_PDU_T **)ptrs[1];
    free(ptrs[1]);

    // Use the pdus as needed...

    free_pdus(pdus, num_pdus);

    return EXIT_SUCCESS;
}
