// Define record structure
typedef struct {
    int value;
} Record;

// Mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate and initialize arrays
void* manage_memory(size_t offset_size, int min_offset, int max_offset,
                    size_t key_size, int min_key, int max_key,
                    size_t record_size, int min_record_value, int max_record_value) {
    if (offset_size == 0 || key_size == 0 || record_size == 0) return NULL;

    // Allocate memory for offset array
    long *offsets = malloc(offset_size * sizeof(long));
    if (!offsets) return NULL;

    // Initialize offsets with random values within the given range
    srand((unsigned int)time(NULL)); // Seed for randomness
    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = min_offset + rand() % ((max_offset - min_offset) + 1);
    }

    // Allocate memory for key array
    int *keys = malloc(key_size * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Initialize keys with random values within the given range
    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = min_key + rand() % ((max_key - min_key) + 1);
    }

    // Allocate and initialize records array using a hash set to ensure uniqueness
    Record *records = malloc(record_size * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    pthread_mutex_lock(&mutex); // Ensure thread safety for record initialization

    int range = max_record_value - min_record_value + 1;
    if (record_size > range) {
        fprintf(stderr, "Requested unique records exceed possible values in the given range.\n");
        free(offsets);
        free(keys);
        free(records);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    int *hash_table = calloc(range, sizeof(int));
    for (size_t i = 0; i < record_size; ++i) {
        int value;
        do {
            value = min_record_value + rand() % range;
        } while (hash_table[value - min_record_value] != 0);

        records[i].value = value;
        hash_table[value - min_record_value] = 1;
    }

    free(hash_table);
    pthread_mutex_unlock(&mutex);

    // Logging
    printf("Memory allocation successful:\n");
    printf("Offsets array size: %" PRIu64 "\n", (uint64_t)offset_size);
    printf("Keys array size: %zu\n", key_size);
    printf("Records array size: %zu\n", record_size);

    return malloc(sizeof(long*) * 3 + sizeof(int*) + sizeof(Record*));
}

// Dummy logging function to simulate integration with third-party library
