}

// Function for dynamic resizing of arrays
void resize_memory(void **memory, size_t *size, size_t new_size, size_t elem_size) {
    if (*size == 0 && new_size == 0) return;

    void *new_mem = realloc(*memory, new_size * elem_size);
    if (new_mem) {
        pthread_mutex_lock(&mutex); // Ensure thread safety
        free(*memory);
        *memory = new_mem;
        *size = new_size;
        pthread_mutex_unlock(&mutex);

        printf("Resized memory allocation to new size: %zu\n", new_size);
    } else {
        fprintf(stderr, "Failed to resize memory.\n");
    }
}

// Example usage
int main() {
    void *memory_handle = manage_memory(10, 0, 100, 5, -50, 50, 3, 1, 3);

    if (memory_handle) {
        long *offsets = *(long**)((char*)memory_handle + sizeof(long*));
        int *keys = *((int**)((char*)memory_handle + sizeof(long*) * 2));
        Record *records = *((Record**)((char*)memory_handle + sizeof(long*) * 2 + sizeof(int*)));

        // Access and use memory
        printf("First offset: %ld\n", offsets[0]);
        printf("First key: %d\n", keys[0]);
        printf("First record value: %d\n", records[0].value);

        // Simulate resizing
        size_t new_offset_size = 20;
        resize_memory((void**)&offsets, (size_t[]){10}, new_offset_size, sizeof(long));

        free(memory_handle);
    }

    return 0;
}
```

### Key Features:
