void insert_frame(UE_MANAGER *manager, NFAPI_RX_FRAME_INFO *new_frame) {
    pthread_mutex_lock(&manager->lock);

    // Free the oldest frame to maintain rolling storage of MAX_FRAMES frames
    free_frame_info(&(manager->frames[manager->frame_count % MAX_FRAMES]));

    // Insert new frame
    manager->frames[manager->frame_count % MAX_FRAMES] = *new_frame;

    // Update signal strength and calculate rolling average
    int new_signal_strength = new_frame->ue_context.signal_strength;
    if (manager->frame_count >= MAX_FRAMES) {
        double old_sum = manager->rolling_avg_signal_strength * MAX_FRAMES;
        old_sum -= manager->frames[(manager->frame_count - MAX_FRAMES + 1) % MAX_FRAMES].ue_context.signal_strength;
        manager->rolling_avg_signal_strength = (old_sum + new_signal_strength) / MAX_FRAMES;
    } else {
        double current_sum = manager->rolling_avg_signal_strength * manager->frame_count;
        manager->rolling_avg_signal_strength = ((current_sum + new_signal_strength) / ++manager->frame_count);
    }

    pthread_mutex_unlock(&manager->lock);
}

// Retrieve the rolling average signal strength
double get_rolling_avg_signal_strength(const UE_MANAGER *manager) {
    pthread_mutex_lock((pthread_mutex_t *)&manager->lock);

    double avg = manager->rolling_avg_signal_strength;

    pthread_mutex_unlock((pthread_mutex_t *)&manager->lock);
    return avg;
}

// Cleanup and free all resources associated with the manager
void cleanup_ue_manager(UE_MANAGER *manager) {
    for (int i = 0; i < MAX_FRAMES; ++i) {
        free_frame_info(&manager->frames[i]);
    }
    pthread_mutex_destroy(&manager->lock);
}
