    if (!frame_list || frame_list->count >= MAX_FRAMES) return;

    pthread_mutex_lock(&frame_list->lock);

    NFAPI_RX_FRAME_INFO *new_frame = (NFAPI_RX_FRAME_INFO *)malloc(sizeof(NFAPI_RX_FRAME_INFO));
    new_frame->ue_context = context;
    new_frame->signal_average = 0.0f;
