        new_frame->frame_indices[i] = -1; // Initialize to invalid index
        new_frame->last_averages[i] = 0.0f;
    }

    frame_list->frames[frame_list->count++] = new_frame;

    pthread_mutex_unlock(&frame_list->lock);
}

