    if (!frame_list || index >= MAX_FRAMES || !frame_list->frames[index]) return;

    pthread_mutex_lock(&frame_list->lock);

    NFAPI_RX_FRAME_INFO *frame = frame_list->frames[index];

    // Update rolling average
    int i;
    for (i = 0; i < 9; ++i) {
        frame->frame_indices[i] = frame->frame_indices[i + 1];
        frame->last_averages[i] = frame->last_averages[i + 1];
