        if (frame->frame_indices[i] != -1) {
            sum += frame->last_averages[i];
        }
    }

    frame->signal_average = sum / 10.0f;

    // Optionally log signal average
    printf("Signal Average for Frame %zu: %.2f\n", index, frame->signal_average);

    pthread_mutex_unlock(&frame_list->lock);
}

