#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <time.h>

#define MAX_POOL_SIZE 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned char CRC_INDICATION_REL8_TAG;
    _Atomic int CRCFLAG; // Atomic for lock-free access
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    atomic_int size;
    pthread_mutex_t lock;
} Pool;

Pool pool = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

unsigned long generate_random_rnti() {
    return rand() % (1 << 16);
}

int is_duplicate_rnti(unsigned long rnti) {
    Node* current = pool.head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structure() {
    pthread_mutex_lock(&pool.lock);
    if (atomic_load(&pool.size) >= MAX_POOL_SIZE) {
        pthread_mutex_unlock(&pool.lock);
        return NULL;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&pool.lock);
        return NULL;
    }

    unsigned long rnti;
    do {
        rnti = generate_random_rnti();
    } while (is_duplicate_rnti(rnti));

    new_node->data.RX_UE_INFORMATION_TAG = rand(); // Random tag for example
    new_node->data.RNTI = rnti;
    new_node->data.CRC_INDICATION_REL8_TAG = rand() % 256; // Random tag for example
    atomic_store(&new_node->data.CRCFLAG, rand() % 2);

    new_node->next = pool.head;
    pool.head = new_node;
    atomic_fetch_add(&pool.size, 1);
    pthread_mutex_unlock(&pool.lock);

    return &new_node->data;
}

void free_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    if (!structure) return;

    pthread_mutex_lock(&pool.lock);
    Node** current = &pool.head;
    while (*current) {
        Node* entry = *current;
        if (&entry->data == structure) {
            *current = entry->next;
            free(entry);
            atomic_fetch_sub(&pool.size, 1);
            break;
        }
        current = &entry->next;
    }
    pthread_mutex_unlock(&pool.lock);
}

int main() {
    srand(time(NULL));

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_structure();
    if (pdu) {
        printf("Allocated PDU with RNTI: %lu\n", pdu->RNTI);
    } else {
        printf("Failed to allocate PDU.\n");
    }

    free_structure(pdu);

    return 0;
}
```

### Explanation

- **Custom Memory Management**: The code uses a linked list (`Node`) for dynamic memory management, allowing efficient handling of up to 10,000 structures.

- **Concurrency**: A mutex lock is used to ensure thread safety during structure allocation and deallocation. This approach minimizes contention while maintaining simplicity.

- **Random RNTI Generation**: Ensures unique RNTIs using a simple loop with random generation and duplicate checking.

- **Error Handling**: The function returns `NULL` if memory allocation fails or the pool is full, allowing for graceful error handling by the caller.

- **Atomic Operations**: Used for CRCFLAG to allow lock-free access, optimizing performance in concurrent environments.

This code provides a foundational approach to managing NFAPI_CRC_INDICATION_PDU_T structures with considerations for concurrency and resource management. Further optimizations can be applied based on specific system requirements and testing outcomes.']

