typedef struct DownlinkGrant {
    int grantId;
    // Additional fields as necessary
} DownlinkGrant;

typedef struct UeSessionData {
    int ueIdentifier;
    DownlinkGrant *downlinkGrants;
    size_t numDownlinkGrants;
    int statusFlag;
    struct UeSessionData *next;
} UeSessionData;

// Function prototypes
UeSessionData* create_ue_session(int ueId, const char *externalDataSource);
void insert_ue_session(UeSessionData **head, UeSessionData *newNode);
UeSessionData* find_ue_session_by_id(UeSessionData *head, int ueId);
void delete_ue_session(UeSessionData **head, int ueId);
void free_ue_sessions(UeSessionData *head);

// Helper functions for error handling and logging
static void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

UeSessionData* create_ue_session(int ueId, const char *externalDataSource) {
    UeSessionData *newNode = (UeSessionData*)malloc(sizeof(UeSessionData));
    if (!newNode) {
        log_error("Memory allocation failed for UeSessionData");
        return NULL;
    }

    newNode->ueIdentifier = ueId;

    // Simulate external data source interaction
    int numGrants = 5; // Assume a fixed number of grants for simplicity
    newNode->downlinkGrants = (DownlinkGrant*)malloc(numGrants * sizeof(DownlinkGrant));
    if (!newNode->downlinkGrants) {
        log_error("Memory allocation failed for DownlinkGrants");
        free(newNode);
        return NULL;
    }

    // Initialize downlink grants
    for (size_t i = 0; i < numGrants; ++i) {
        newNode->downlinkGrants[i].grantId = rand() % 1000; // Simulated grant ID
    }
    newNode->numDownlinkGrants = numGrants;

    newNode->statusFlag = 0; // Initial status flag
    newNode->next = NULL;

    return newNode;
}

void insert_ue_session(UeSessionData **head, UeSessionData *newNode) {
    if (!*head || (*head)->ueIdentifier > newNode->ueIdentifier) {
        newNode->next = *head;
        *head = newNode;
    } else {
        UeSessionData *current = *head;
        while (current->next && current->next->ueIdentifier < newNode->ueIdentifier) {
            current = current->next;
        }
        newNode->next = current->next;
        current->next = newNode;
    }
}

UeSessionData* find_ue_session_by_id(UeSessionData *head, int ueId) {
    UeSessionData *current = head;
    while (current && current->ueIdentifier != ueId) {
        current = current->next;
    }
    return current;
}

void delete_ue_session(UeSessionData **head, int ueId) {
    if (!*head) return;

    UeSessionData *temp = *head;
    if (temp->ueIdentifier == ueId) {
        *head = temp->next;
        free(temp->downlinkGrants);
        free(temp);
        return;
    }

    UeSessionData *current = *head;
    while (current->next && current->next->ueIdentifier != ueId) {
        current = current->next;
    }

    if (current->next) {
        UeSessionData *toDelete = current->next;
        current->next = toDelete->next;
        free(toDelete->downlinkGrants);
        free(toDelete);
    }
}

void free_ue_sessions(UeSessionData *head) {
    while (head) {
        UeSessionData *temp = head;
        head = head->next;
        free(temp->downlinkGrants);
        free(temp);
    }
}

int main() {
    // Example usage
    UeSessionData *head = NULL;

    UeSessionData *session1 = create_ue_session(101, "DataSource");
    if (session1) insert_ue_session(&head, session1);

    UeSessionData *session2 = create_ue_session(202, "DataSource");
    if (session2) insert_ue_session(&head, session2);

    UeSessionData *foundSession = find_ue_session_by_id(head, 101);
    if (foundSession) {
        printf("Found UE Session with ID: %d\n", foundSession->ueIdentifier);
    }

    delete_ue_session(&head, 101);
    free_ue_sessions(head);

    return 0;
}
