int initialize_data_structures(long num_records, int key_range_min, int key_range_max,
                               LoggingMode logging_mode) {
    long i;
    long offset_size = sizeof(long) * num_records;
    int key_size = sizeof(int) * num_records;
    record_t *records = (record_t *)malloc(offset_size);
    int *keys = (int *)malloc(key_size);
    char **metadata = (char **)malloc(sizeof(char *) * num_records);

    if (!records || !keys || !metadata) {
        fprintf(stderr, "Memory allocation failed\n");
        free(records); free(keys); free(metadata);
        return -1;
    }

    // Random number generation setup
    srand(time(NULL));

    // Set keys and validate uniqueness
    int used_keys[num_records] = {0};
    for (i = 0; i < num_records; ++i) {
        int key, generated_key;
        do {
            generated_key = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        } while (used_keys[generated_key] != 0);

        keys[i] = generated_key;
        used_keys[generated_key] = 1;
    }

    // Initialize records and validate timestamps
    time_t last_timestamp = 0;
    for (i = 0; i < num_records; ++i) {
        int record_value, status_flag;
        do {
            record_value = rand() % (key_range_max - key_range_min + 1) + key_range_min;
        } while (used_keys[record_value] != 0);

        used_keys[record_value] = 1;
        records[i].value = record_value;

        snprintf(records[i].string_repr, sizeof(records[i].string_repr), "%d", record_value);
        records[i].timestamp = time(NULL);

        if (records[i].timestamp <= last_timestamp) {
            fprintf(stderr, "Timestamps are not monotonically increasing\n");
            free(records); free(keys); free(metadata);
            return -1;
        }

        last_timestamp = records[i].timestamp;

        // Determine status flag
        status_flag = record_value > (key_range_max + key_range_min) / 2 ? 1 : 0;

        for (long j = 0; j < i; ++j) {
            if (records[j].status_flag == status_flag) {
                fprintf(stderr, "Duplicate status flags detected\n");
                free(records); free(keys); free(metadata);
                return -1;
            }
        }

        records[i].status_flag = status_flag;

        // Allocate and initialize metadata
        metadata[i] = (char *)malloc(50 * sizeof(char));  // Example size for metadata strings
        snprintf(metadata[i], 50, "Record %ld: value=%d", i + 1, record_value);

        log_operation(metadata[i], logging_mode); // Log the creation of each record
    }

    // Periodic integrity checks (simplified example)
    time_t current_time = time(NULL);
    if ((current_time - last_timestamp) > 5 * num_records) {  // Example condition for triggering check
        printf("Performing periodic integrity check...\n");
        // Integrity check logic here...
    }

    free(records); free(keys);
    for (i = 0; i < num_records; ++i) {
        free(metadata[i]);
    }
    free(metadata);

    return 0;
}
