#include "log_library.h"  // Assumed external logging library
#include "memory_pool.h"  // Assumed external memory pool library

#define MAX_ELEMENTS 10000
#define BATCH_SIZE 1000
#define POOL_BLOCK_SIZE sizeof(NFAPI_CRC_INDICATION_PDU_T)

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;  // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_pool(size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->elements = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_allocate(initial_capacity * POOL_BLOCK_SIZE);
    if (!pool->elements) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

bool resize_pool(MemoryPool* pool, size_t new_capacity) {
    if (new_capacity <= pool->capacity) return true;

    NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_reallocate(pool->elements, new_capacity * POOL_BLOCK_SIZE);
    if (!new_elements) return false;

    pool->elements = new_elements;
    pool->capacity = new_capacity;
    return true;
}

bool add_element(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        if (!resize_pool(pool, new_capacity)) {
            pthread_mutex_unlock(&pool->lock);
            log_error("Failed to resize memory pool.");
            return false;
        }
    }

    pool->elements[pool->count++] = element;

    pthread_mutex_unlock(&pool->lock);
    return true;
}

void process_batch(MemoryPool* pool, size_t start_index, size_t batch_size) {
    for (size_t i = 0; i < batch_size && start_index + i < pool->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* element = &pool->elements[start_index + i];
        // Process the element here
        log_info("Processing element with RNTI: %d", element->RNTI);
    }
}

void process_all_batches(MemoryPool* pool, size_t batch_size) {
    for (size_t start_index = 0; start_index < pool->count; start_index += batch_size) {
        size_t current_batch_size = (start_index + batch_size > pool->count) ? (pool->count - start_index) : batch_size;
        process_batch(pool, start_index, current_batch_size);
    }
}

void free_pool(MemoryPool* pool) {
    if (!pool) return;

    pthread_mutex_destroy(&pool->lock);
    memory_pool_free(pool->elements);
    free(pool);
}

int main() {
    MemoryPool* pool = create_pool(BATCH_SIZE);
    if (!pool) {
        log_error("Failed to initialize memory pool.");
        return EXIT_FAILURE;
    }

    // Simulate adding elements
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element = { rand(), rand(), rand(), rand() % 2 == 0 };
        if (!add_element(pool, element)) {
            log_error("Failed to add element to memory pool.");
            free_pool(pool);
            return EXIT_FAILURE;
        }
    }

    process_all_batches(pool, BATCH_SIZE);

    free_pool(pool);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Memory Pool**: Uses a custom memory pool for efficient allocation and reallocation.
- **Thread Safety**: Utilizes `pthread_mutex_t` to ensure thread-safe operations.
- **Batch Processing**: Processes elements in batches of 1,000 to optimize performance.
- **Error Handling**: Logs errors when memory allocation fails or resizing is unsuccessful.
- **Scalability**: Supports dynamic growth up to 10,000 elements.

This code assumes the presence of external libraries for logging (`log_library.h`) and memory pooling (`memory_pool.h`). Adjust these as necessary based on your actual dependencies.']

