    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} MetadataArray;

MetadataArray* create_metadata_array() {
    MetadataArray *array = malloc(sizeof(MetadataArray));
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    array->data = malloc(array->capacity * sizeof(UDT_FILE_METADATA));
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resize_metadata_array(MetadataArray *array) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(UDT_FILE_METADATA));
    }
    pthread_mutex_unlock(&array->lock);
}

void add_metadata(MetadataArray *array, UDT_FILE_METADATA metadata) {
    pthread_mutex_lock(&array->lock);
    resize_metadata_array(array);
    strcpy(array->data[array->count].FILE_NAME, metadata.FILE_NAME);
    array->data[array->count].FILE_SIZE = metadata.FILE_SIZE;
    array->data[array->count].MODIFICATION_TIMESTAMP = metadata.MODIFICATION_TIMESTAMP;
    array->count++;
    pthread_mutex_unlock(&array->lock);
}

UDT_FILE_METADATA* get_metadata(MetadataArray *array, const char *file_name) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; i++) {
        if (strcmp(array->data[i].FILE_NAME, file_name) == 0) {
            UDT_FILE_METADATA *metadata = malloc(sizeof(UDT_FILE_METADATA));
            *metadata = array->data[i];
            pthread_mutex_unlock(&array->lock);
            return metadata;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void update_metadata(MetadataArray *array, const char *file_name, UDT_FILE_METADATA new_metadata) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; i++) {
        if (strcmp(array->data[i].FILE_NAME, file_name) == 0) {
            strcpy(array->data[i].FILE_NAME, new_metadata.FILE_NAME);
            array->data[i].FILE_SIZE = new_metadata.FILE_SIZE;
            array->data[i].MODIFICATION_TIMESTAMP = new_metadata.MODIFICATION_TIMESTAMP;
            break;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

