        resize_frame_list(list, list->frame_count + 100); // Expand dynamically
    }

    info->index = (info->index + 1) % AVG_FRAME_COUNT;
    for (int i = 0; i < AVG_FRAME_COUNT - 1; ++i) {
        info->signal_strengths[i] = info->signal_strengths[(i + 1) % AVG_FRAME_COUNT];
    }

    info->signal_strengths[info->index] = info->ue_context.signal_strength;
    float sum = 0.0;
    for (int i = 0; i < AVG_FRAME_COUNT; ++i) {
        sum += info->signal_strengths[i];
    }
    info->rolling_avg_signal_strength = sum / AVG_FRAME_COUNT;

    list->frames[list->frame_count++] = info;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_RX_FRAME_INFO* retrieve_frame_info(DynamicFrameList *list, size_t index) {
    if (!list || index >= list->frame_count) return NULL;

    pthread_mutex_lock(&list->lock);

    NFAPI_RX_FRAME_INFO *info = list->frames[index];

    pthread_mutex_unlock(&list->lock);
    return info;
}

void free_frame_list(DynamicFrameList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->frame_count; ++i) {
        free_frame_info(list->frames[i]);
    }
    free(list->frames);

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

