typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node of the linked list
typedef struct ListNode {
    NetworkPerformanceMetrics metrics;
    size_t num_crcs; // Number of CRC indications
    NFAPI_CRC_INDICATION_PDU_T *crc_list;
    struct ListNode *next;
} ListNode;

// Function prototypes
ListNode* initialize_linked_list(size_t N, int seed);
void populate_metrics(NetworkPerformanceMetrics *metrics, int session_id);
void populate_crc_indications(NFAPI_CRC_INDICATION_PDU_T *crcs, size_t num_crcs, unsigned int true_count);
int validate_structure(ListNode *head);
void free_linked_list(ListNode *head);
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

ListNode* initialize_linked_list(size_t N, int seed) {
    pthread_mutex_lock(&list_lock);

    srand(seed); // Seed the random number generator
    ListNode *head = NULL, *current = NULL;
    unsigned int true_count = 0; // Count of CRCFLAG set to true

    for (size_t i = 0; i < N; ++i) {
        ListNode *new_node = (ListNode *)malloc(sizeof(ListNode));
        if (!new_node) {
            free_linked_list(head);
            pthread_mutex_unlock(&list_lock);
            return NULL;
        }

        populate_metrics(&new_node->metrics, i);

        size_t num_crcs = rand() % 10 + 1; // Random number of CRC indications
        new_node->num_crcs = num_crcs;
        new_node->crc_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_crcs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node->crc_list) {
            free(new_node);
            free_linked_list(head);
            pthread_mutex_unlock(&list_lock);
            return NULL;
        }

        populate_crc_indications(new_node->crc_list, num_crcs, true_count);

        new_node->next = NULL;

        if (head == NULL) {
            head = current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    pthread_mutex_unlock(&list_lock);

    if (!validate_structure(head)) {
        free_linked_list(head);
        return NULL;
    }

    return head;
}

void populate_metrics(NetworkPerformanceMetrics *metrics, int session_id) {
    metrics->timestamp = time(NULL);
    metrics->session_id = session_id;
    metrics->num_measurements = rand() % 5 + 1; // Random number of measurements
    metrics->measurements = (double *)malloc(metrics->num_measurements * sizeof(double));
    if (!metrics->measurements) {
        fprintf(stderr, "Memory allocation failed for measurements\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < metrics->num_measurements; ++i) {
        metrics->measurements[i] = rand() % 100.0;
    }
}

void populate_crc_indications(NFAPI_CRC_INDICATION_PDU_T *crcs, size_t num_crcs, unsigned int true_count) {
    for (size_t i = 0; i < num_crcs; ++i) {
        crcs[i].RX_UE_INFORMATION_TAG = rand();
        crcs[i].RNTI = rand() % 65536;
        crcs[i].CRCFLAG = rand() % 2;

        if (crcs[i].CRCFLAG == 1 && true_count < num_crcs / 2) {
            true_count++;
        } else if (crcs[i].CRCFLAG == 1) {
            crcs[i].CRCFLAG = 0;
        }
    }
}

int validate_structure(ListNode *head) {
    ListNode *current = head;

    while (current != NULL) {
        if (current->metrics.measurements == NULL || current->crc_list == NULL) {
            return 0; // Invalid structure
        }

        for (size_t i = 0; i < current->metrics.num_measurements; ++i) {
            if (current->metrics.measurements[i] < 0) { // Example validation
                return 0;
            }
        }

        for (size_t j = 0; j < current->num_crcs; ++j) {
            if (current->crc_list[j].CRCFLAG != 0 && current->crc_list[j].CRCFLAG != 1) {
                return 0;
            }
        }

        current = current->next;
    }

    return 1; // Valid structure
}

void free_linked_list(ListNode *head) {
    ListNode *current = head;

    while (current != NULL) {
        ListNode *temp = current;
        current = current->next;

        free(temp->metrics.measurements);
        free(temp->crc_list);
        free(temp);
    }
}

int main() {
    size_t N = 10; // Number of entries
    int seed = 42; // Seed for random number generation

    ListNode *list = initialize_linked_list(N, seed);
    if (list == NULL) {
        fprintf(stderr, "Failed to initialize linked list\n");
        return EXIT_FAILURE;
    }

    printf("Linked list initialized successfully with %zu entries.\n", N);

    free_linked_list(list);
    return EXIT_SUCCESS;
}
