int populate_nfa_list(struct NFAPI_CRC_INDICATION_PDU_T** list, size_t* current_size, size_t capacity, struct RX_UE_INFORMATION_TAG* rx_tags, uint16_t* rntis, size_t num_entries) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int result = 0;

    if (*current_size >= capacity) {
        // Double the capacity to handle overflow
        size_t new_capacity = capacity * 2 > MAX_STRUCTURES ? MAX_STRUCTURES : capacity * 2;
        struct NFAPI_CRC_INDICATION_PDU_T* temp_list = realloc(*list, new_capacity * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_list) {
            log_message("Memory allocation failed during resizing.");
            result = -1;
            return result;
        }
        *list = temp_list;
        capacity = new_capacity;
    }

    for (size_t i = 0; i < num_entries && (*current_size) < MAX_STRUCTURES; ++i) {
        pthread_mutex_lock(&mutex);

        struct NFAPI_CRC_INDICATION_PDU_T new_entry;
        new_entry.rx_ue_information_tag = rx_tags[i];
        new_entry.rnti = rntis[i];
        new_entry.crc_indication_rel8_tag.crcflag = rand() % 2; // Randomly set CRCFLAG

        if (validate_and_add(*list, *current_size, new_entry) == -1) {
            pthread_mutex_unlock(&mutex);
            continue;
        }

        (*list)[*current_size] = new_entry;
        log_message("Added NFAPI_CRC_INDICATION_PDU_T structure.");
        ++(*current_size);

        pthread_mutex_unlock(&mutex);
    }

    if (*current_size >= MAX_STRUCTURES) {
        log_message("Maximum storage limit reached. Further additions are not possible.");
    }

    return result;
}

int main() {
