typedef struct {
    int *value;
    int key;
    long offset;
} record;

record** allocate_and_initialize_records(int num_keys, int min_value, int max_value) {
    if (num_keys <= 0 || min_value >= max_value) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    long *offsets = malloc(num_keys * sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Fill offsets and keys with example data
    for (int i = 0; i < num_keys; ++i) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 1000;
    }

    record **records = malloc(num_keys * sizeof(record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    for (int i = 0; i < num_keys; ++i) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed.\n");

            // Free previously allocated memory
            for (int j = 0; j < i; ++j) free(records[j]);
            free(records);
            free(offsets);
            free(keys);

            return NULL;
        }

        pthread_mutex_lock(&lock);
        records[i]->value = malloc(sizeof(int));
        if (!records[i]->value) {
            fprintf(stderr, "Memory allocation failed.\n");

            // Free previously allocated memory
            for (int j = 0; j <= i; ++j) free(records[j]);
            free(records);
            free(offsets);
            free(keys);

            pthread_mutex_unlock(&lock);
            return NULL;
        }

        records[i]->value[0] = rand() % (max_value - min_value + 1) + min_value;
        records[i]->key = keys[i];
        records[i]->offset = offsets[i];

        pthread_mutex_unlock(&lock);
    }

    // Clean up
    free(offsets);
    free(keys);
    pthread_mutex_destroy(&lock);

    return records;
}

void free_records(record **records, int num_keys) {
    if (!records) return;

    for (int i = 0; i < num_keys; ++i) {
        if (records[i]) {
            free(records[i]->value);
            free(records[i]);
        }
    }

    free(records);
}

