typedef struct {
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T entries[MAX_ENTRIES];
    size_t forward_index;
    size_t backward_index;
} PduListManager;

// Function to initialize the list manager
void initPduListManager(PduListManager *manager) {
    manager->count = 0;
    manager->forward_index = 0;
    manager->backward_index = 0;
}

// Function to add an entry to the list manager
bool addPduEntry(PduListManager *manager, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (manager->count >= MAX_ENTRIES)
        return false;

    manager->entries[manager->count++] = entry;
    return true;
}

// Function to iterate forward over the list
NFAPI_CRC_INDICATION_PDU_T* nextPduEntryForward(PduListManager *manager) {
    if (manager->forward_index < manager->count) {
        return &manager->entries[manager->forward_index++];
    }
    return NULL; // End of list
}

// Function to iterate backward over the list
NFAPI_CRC_INDICATION_PDU_T* nextPduEntryBackward(PduListManager *manager) {
    if (manager->backward_index > 0) {
        manager->backward_index--;
        return &manager->entries[manager->backward_index];
    }
    return NULL; // Start of list
}

// Function to reset forward iteration
void resetForwardIteration(PduListManager *manager) {
    manager->forward_index = 0;
}

// Function to reset backward iteration
void resetBackwardIteration(PduListManager *manager) {
    manager->backward_index = manager->count;
}
