['Below is a C implementation for managing a dynamically scalable list of `NFAPI_CRC_INDICATION_PDU_T` and `UDT_FILE_METADATA` structures, considering cache alignment, concurrency, and efficient iteration.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    unsigned int valid_RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char FILE_NAME[256];
    size_t FILE_SIZE;
    time_t MODIFICATION_TIMESTAMP;
} UDT_FILE_METADATA;

typedef struct Node {
    void *data;
    struct Node *next;
    struct Node *prev;
} Node;

typedef struct {
    Node *head;
    Node *tail;
    pthread_mutex_t lock;
    int count;
} LinkedList;

void init_list(LinkedList *list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

void destroy_list(LinkedList *list) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

Node* create_node(void *data, size_t data_size) {
    Node *node = malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = malloc(data_size);
    if (!node->data) {
        free(node);
        return NULL;
    }

    memcpy(node->data, data, data_size);
    node->next = NULL;
    node->prev = NULL;
    return node;
}

void add_entry(LinkedList *list, void *data, size_t data_size) {
    if (list->count >= MAX_ENTRIES) return;

    pthread_mutex_lock(&list->lock);

    Node *new_node = create_node(data, data_size);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (!list->head) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void update_entry(LinkedList *list, int index, void *data, size_t data_size) {
    if (index < 0 || index >= list->count) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    for (int i = 0; i < index && current; i++) {
        current = current->next;
    }

    if (current) {
        memcpy(current->data, data, data_size);
    }

    pthread_mutex_unlock(&list->lock);
}

void* get_entry(LinkedList *list, int index) {
    if (index < 0 || index >= list->count) return NULL;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    for (int i = 0; i < index && current; i++) {
        current = current->next;
    }

    void *data = NULL;
    if (current) {
        data = malloc(list->count > MAX_ENTRIES ? sizeof(UDT_FILE_METADATA) : sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (data) memcpy(data, current->data, list->count > MAX_ENTRIES ? sizeof(UDT_FILE_METADATA) : sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&list->lock);
    return data;
}

void iterate_list_forward(LinkedList *list, void (*func)(void*)) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        func(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_list_reverse(LinkedList *list, void (*func)(void*)) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->tail;
    while (current) {
        func(current->data);
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

