    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 1234};
    add_entry(&crc_list, &pdu, sizeof(pdu));

    iterate_list_forward(&crc_list, print_crc);

    destroy_list(&crc_list);
    return 0;
}
