#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#define INITIAL_CAPACITY 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4]; // Assume a fixed size for simplicity
    uint8_t CRCFLAG; // Randomly generated
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
} ListManager;

#define ALIGNMENT 16

void* aligned_malloc(size_t size) {
    void* ptr = NULL;
#ifdef _WIN32
    ptr = _aligned_malloc(size, ALIGNMENT);
#else
    if (posix_memalign(&ptr, ALIGNMENT, size)) {
        ptr = NULL;
    }
#endif
    return ptr;
}

void aligned_free(void* ptr) {
#ifdef _WIN32
    _aligned_free(ptr);
#else
    free(ptr);
#endif
}

uint8_t generate_crcflag() {
    // Simple random generation for CRCFLAG
    return rand() & 0xFF;
}

void list_manager_init(ListManager* manager) {
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;

    size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * manager->capacity;
    manager->data = (NFAPI_CRC_INDICATION_PDU_T*)aligned_malloc(size);
}

void list_manager_free(ListManager* manager) {
    aligned_free(manager->data);
    manager->count = 0;
    manager->capacity = 0;
}

int list_manager_add(ListManager* manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity;

        NFAPI_CRC_INDICATION_PDU_T* new_data = 
            (NFAPI_CRC_INDICATION_PDU_T*)aligned_malloc(size);

        if (!new_data) return -1; // Allocation failed

        memcpy(new_data, manager->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * manager->count);

        aligned_free(manager->data);
        manager->data = new_data;
        manager->capacity = new_capacity;
    }

    pdu.CRCFLAG = generate_crcflag();
    manager->data[manager->count++] = pdu;

    return 0; // Success
}

const NFAPI_CRC_INDICATION_PDU_T* list_manager_get(ListManager* manager, size_t index) {
    if (index < manager->count) {
        return &manager->data[index];
    }
    return NULL;
}

// Forward iteration
void list_manager_iterate_forward(const ListManager* manager, void (*callback)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    for (size_t i = 0; i < manager->count; ++i) {
        callback(&manager->data[i]);
    }
}

// Backward iteration
void list_manager_iterate_backward(const ListManager* manager, void (*callback)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    for (int i = (int)manager->count - 1; i >= 0; --i) {
        callback(&manager->data[i]);
    }
}

// Example usage of the iteration
void print_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n",
           pdu->RX_UE_INFORMATION_TAG,
           pdu->RNTI,
           pdu->CRCFLAG);
}

int main() {
    ListManager manager;
    list_manager_init(&manager);

    // Add sample data
    for (uint32_t i = 0; i < 15; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {i, i, {0}, 0};
        if (list_manager_add(&manager, pdu) != 0) {
            fprintf(stderr, "Failed to add data.\n");
            return 1;
        }
    }

    // Forward iteration
    printf("Forward Iteration:\n");
    list_manager_iterate_forward(&manager, print_pdu);

    // Backward iteration
    printf("\nBackward Iteration:\n");
    list_manager_iterate_backward(&manager, print_pdu);

    list_manager_free(&manager);
    return 0;
}
```

This implementation includes:

- **Memory Alignment**: Ensures all memory allocations are aligned to a 16-byte boundary.
- **Dynamic Resizing**: Doubles the capacity when the current capacity is exceeded to minimize reallocations and fragmentation.
- **Forward and Backward Iteration**: Provides functions for both forward and backward iteration with callbacks for processing each entry, optimizing cache usage during traversal.
- **Simple CRCFLAG Generation**: Generates a random value for `CRCFLAG`.
- **Scalability**: Resizes the list dynamically while maintaining data integrity.

Adjustments can be made to the structure or memory management logic to accommodate future changes. The code is designed to efficiently handle up to 10,000 entries and scale beyond that as needed.']

