```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_RECORDS 10000
#define ARCHIVE_THRESHOLD_SECONDS 3600 // Example threshold

typedef struct {
    int value;
    char string_rep[256];
    time_t timestamp;
    void *metadata_ptr; 
} Record;

typedef struct MemoryPool {
    size_t element_size;
    unsigned long capacity;
    unsigned long count;
    void **elements;
    pthread_mutex_t lock;
} MemoryPool;

typedef struct {
    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    Record records[MAX_RECORDS];
    char *metadata_ptrs[MAX_RECORDS]; // Store metadata pointers
} DataSystem;

DataSystem system = {0};
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
MemoryPool pool;

void initialize_pool(size_t element_size, unsigned long capacity) {
    pool.element_size = element_size;
    pool.capacity = capacity;
    pool.count = 0;
    pool.elements = malloc(capacity * sizeof(void *));
    pthread_mutex_init(&pool.lock, NULL);
}

void* allocate_record() {
    pthread_mutex_lock(&pool.lock);
    if (pool.count >= pool.capacity) {
        // Resize the pool
        unsigned long new_capacity = pool.capacity * 2;
        void **new_elements = realloc(pool.elements, new_capacity * sizeof(void *));
        if (!new_elements) {
            pthread_mutex_unlock(&pool.lock);
            return NULL; // Handle error appropriately
        }
        pool.elements = new_elements;
        pool.capacity = new_capacity;
    }

    for (unsigned long i = 0; i < pool.capacity; ++i) {
        if (!pool.elements[i]) {
            void *new_element = malloc(pool.element_size);
            if (!new_element) {
                pthread_mutex_unlock(&pool.lock);
                return NULL; // Handle error appropriately
            }
            pool.elements[i] = new_element;
            pool.count++;
            pthread_mutex_unlock(&pool.lock);
            return new_element;
        }
    }

    pthread_mutex_unlock(&pool.lock); // This should not happen
    return NULL;
}

void free_record(void *element) {
    pthread_mutex_lock(&pool.lock);
    for (unsigned long i = 0; i < pool.capacity; ++i) {
        if (pool.elements[i] == element) {
            free(element);
            pool.elements[i] = NULL;
            pool.count--;
            break;
        }
    }
    pthread_mutex_unlock(&pool.lock);
}

void add_record(int key, long offset, const char *metadata) {
    pthread_rwlock_wrlock(&rwlock);

    if (system.count >= MAX_RECORDS) {
        // Handle error: system full
        pthread_rwlock_unlock(&rwlock);
        return;
    }

    // Validate key array size and monotonically increasing timestamps
    for (int i = 0; i < system.count; ++i) {
        if (system.keys[i] == key) {
            // Handle error: duplicate key
            pthread_rwlock_unlock(&rwlock);
            return;
        }
    }

    void *record_memory = allocate_record();
    if (!record_memory) {
        // Handle allocation failure
        pthread_rwlock_unlock(&rwlock);
        return;
    }

    Record *new_record = (Record *)record_memory;

    new_record->value = key;  // or some value derived from the operation
    strncpy(new_record->string_rep, "UniqueString", sizeof(new_record->string_rep)); // Example string generation
    time(&new_record->timestamp);

    system.metadata_ptrs[system.count] = strdup(metadata);
    if (!system.metadata_ptrs[system.count]) {
        free(record_memory);  // Clean up on error
        pthread_rwlock_unlock(&rwlock);
        return;
    }

    system.offsets[system.count] = offset;
    system.keys[system.count] = key;
    memcpy(&(system.records[system.count]), new_record, sizeof(Record));

    if (system.count > 0) {
        // Ensure timestamps are monotonically increasing
        time_t last_timestamp = system.records[system.count - 1].timestamp;
        if (new_record->timestamp <= last_timestamp) {
            free(record_memory);
            pthread_rwlock_unlock(&rwlock);
            return; // Handle error: timestamp not monotonically increasing
        }
    }

    system.count++;
    pthread_rwlock_unlock(&rwlock);
}

void archive_old_records() {
    time_t now = time(NULL);

    pthread_rwlock_wrlock(&rwlock);
    for (int i = 0; i < system.count;) {
        if (difftime(now, system.records[i].timestamp) > ARCHIVE_THRESHOLD_SECONDS) {
            // Archive record
            free(system.metadata_ptrs[i]);
            system.metadata_ptrs[i] = NULL;

            pthread_mutex_lock(&pool.lock);
            pool.elements[i] = NULL;
            pool.count--;
            pthread_mutex_unlock(&pool.lock);

            // Shift records to maintain contiguous array
            memmove(&(system.offsets[i]), &(system.offsets[i + 1]),
                    (system.count - i - 1) * sizeof(long));
            memmove(&(system.keys[i]), &(system.keys[i + 1]),
                    (system.count - i - 1) * sizeof(int));
            memmove(&(system.records[i]), &(system.records[i + 1]),
                    (system.count - i - 1) * sizeof(Record));

            system.count--;
        } else {
            ++i;
        }
    }
    pthread_rwlock_unlock(&rwlock);
}

void shutdown_system() {
    for (int i = 0; i < system.count; ++i) {
        free(system.metadata_ptrs[i]);
        void *record_memory = &system.records[i];
        free_record(record_memory);
    }

    pthread_mutex_destroy(&pool.lock);
    free(pool.elements);

    pthread_rwlock_destroy(&rwlock);
}

void* handle_connection(void* args) {
    // Handle network operations, calls to add_record, etc.
}

int main() {
    initialize_pool(sizeof(Record), MAX_RECORDS);

    // Start thread pool or connection handlers
    const int num_threads = 1000;
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, handle_connection, NULL) != 0) {
            // Handle thread creation error
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    shutdown_system();

    return 0;
}
```

### Key Points:
- **Custom Memory Pool**: A simple memory pool is implemented to manage `Record` structures, with dynamic resizing when the pool reaches capacity.
- **Concurrency Control**: Uses a read-write lock (`pthread_rwlock_t`) for managing access to shared data and fine-grained locking via a mutex within the pool. This balances between high concurrency and efficient synchronization.
- **Archiving Mechanism**: Periodically archives records older than a specified threshold by freeing metadata strings and memory, shifting remaining records to maintain contiguous arrays.
- **Thread Safety**: Ensures all operations on shared resources are thread-safe using appropriate locking mechanisms.
