    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* head;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int is_rnti_used(CRCList* list, unsigned short rnti) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        if (current->ueInfoTag.RNTI == rnti) return 1;
        current = current->next;
    }
    return 0;
}

int add_crc_pdu(CRCList* list, unsigned short RNTI_RANGE, int M) {
    pthread_mutex_lock(&list->lock);

    if (!list || !RNTI_RANGE || M <= 0) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Invalid parameters
    }

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    int count = 0;

    while (current && count < M) {
        current = current->next;
        count++;
    }

    if (count >= M) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List is full
    }

    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation failed
    }

    srand(time(NULL) + count); // Seed with time and count for randomness

    unsigned short rnti;
    do {
        rnti = (unsigned short)(rand() % RNTI_RANGE + 1);
    } while (is_rnti_used(list, rnti));

    new_node->ueInfoTag.RNTI = rnti;
    new_node->ueInfoTag.crcTag.CRCFLAG = rand() & 1; // Randomly set CRCFLAG
    new_node->next = NULL;

    if (!list->head) {
        list->head = new_node;
    } else {
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void print_crc_list(CRCList* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        printf("RNTI: %u, CRCFLAG: %d\n", current->ueInfoTag.RNTI, current->ueInfoTag.crcTag.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_crc_list(CRCList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
