    pthread_mutex_unlock(&lock);
}

int find_largest(int *array, size_t size) {
    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void process_stream() {
    log_message("Starting stream processing.");
    FILE *socket_file = fopen("network_socket", "rb");
    if (!socket_file) {
        log_message("Failed to open network socket.");
        return;
    }

    int *numbers = NULL;
    size_t capacity = 0, size = 0;
    int number;

    while (fread(&number, sizeof(int), 1, socket_file)) {
        if (number == -1) { // Termination signal
            break;
        }

        if (size >= capacity) {
            capacity = capacity ? capacity * 2 : 4;
            numbers = realloc(numbers, capacity * sizeof(int));
            if (!numbers) {
                log_message("Memory allocation failed.");
                fclose(socket_file);
                return;
            }
        }

        numbers[size++] = number;
    }

    fclose(socket_file);

    if (size > 0) {
        int largest_number = find_largest(numbers, size);
        printf("Largest number: %d\n", largest_number);
        log_message("Processed largest number.");
    } else {
        log_message("No valid numbers received.");
    }

    free(numbers);

    srand(time(NULL));
    size_t pdu_count = 10; // Example count
    UE_INFO_PDU *pdu_list = malloc(pdu_count * sizeof(UE_INFO_PDU));
    if (!pdu_list) {
        log_message("Memory allocation for PDUs failed.");
        return;
    }

    for (size_t i = 0; i < pdu_count; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu_list[i].RNTI = rand() % 1000;
        pdu_list[i].pdu.CRCFLAG = rand() & 1; // Randomly set CRCFLAG
    }

    log_message("Populated PDU list.");

    free(pdu_list);
}

int main() {
    process_stream();
    return 0;
}
```

