    int valid;  // Indicates if the context is initialized and active
    LMAC_CONFIG lmac_config;
    MAC_ADDRESS_LIST *mac_addresses;
    size_t mac_count;
    NFAPI_CRC_INDICATION_PDU_T crc_pdu;
    struct MAC_CONTEXT_T_ *next_in_cache;
} MAC_CONTEXT_T;

typedef struct {
    MAC_CONTEXT_T **contexts;
    int context_count;
    MAC_CONTEXT_T *cache[CACHE_SIZE];
    unsigned int cache_index;
    // Additional fields for network management integration and logging
} MAC_MANAGER;

MAC_MANAGER manager = {NULL, 0, {NULL}, 0};

void initialize_manager() {
    manager.contexts = (MAC_CONTEXT_T **)calloc(MAX_CONTEXTS, sizeof(MAC_CONTEXT_T *));
}

MAC_CONTEXT_T* create_context(int index) {
    if (index < 0 || index >= MAX_CONTEXTS) return NULL;

    MAC_CONTEXT_T *context = (MAC_CONTEXT_T *)malloc(sizeof(MAC_CONTEXT_T));
    if (!context) return NULL;

    context->valid = 1;
    // Initialize LMAC_CONFIG and NFAPI_CRC_INDICATION_PDU_T
    srand(time(NULL));  // Seed random number generator for CRCFLAG
    context->crc_pdu.crc_tag.CRCFLAG = rand() % 2;  // Randomly set CRCFLAG

    context->mac_addresses = NULL;
    context->mac_count = 0;

    // Add to cache
    manager.cache[manager.cache_index++] = context;
    if (manager.cache_index >= CACHE_SIZE) {
        manager.cache_index = 0;
    }

    manager.contexts[index] = context;
    manager.context_count++;
    return context;
}

void destroy_context(int index) {
    if (index < 0 || index >= MAX_CONTEXTS || !manager.contexts[index]) return;

    MAC_CONTEXT_T *context = manager.contexts[index];
    if (!context->valid) return;

    free(context->mac_addresses);
    free(context);

    context->valid = 0;
    manager.contexts[index] = NULL;
    manager.context_count--;

    // Remove from cache
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (manager.cache[i] == context) {
            manager.cache[i] = NULL;
            break;
        }
    }
}

void update_mac_address(int index, const char *mac_address) {
    MAC_CONTEXT_T *context = create_context(index);
    if (!context || !context->valid) return;

    context->mac_addresses = (MAC_ADDRESS_LIST *)realloc(context->mac_addresses,
                                                         (context->mac_count + 1) * sizeof(MAC_ADDRESS_LIST));
    strcpy(context->mac_addresses[context->mac_count].mac_address, mac_address);
    context->mac_count++;
}

void handle_external_service_failure() {
    // Logic to degrade gracefully and notify application layer
    printf("External service failure detected. Switching to cached responses.\n");
}

void log_system_health() {
    // Logging system health metrics for monitoring
    printf("Current active contexts: %d\n", manager.context_count);
}

void free_resources() {
    for (int i = 0; i < MAX_CONTEXTS; ++i) {
        destroy_context(i);
    }
    free(manager.contexts);
}

int main() {
    initialize_manager();

    // Example usage
    create_context(0);
    update_mac_address(0, "00:11:22:33:44:55");

    handle_external_service_failure();
    log_system_health();

    free_resources();
    return 0;
}
