#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int RNTI;
    // Add additional fields as needed for RX_UE_INFORMATION_TAG
} RX_UE_INFORMATION_TAG;

typedef struct {
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ueInfo;
    unsigned long long rnti;  // Using unsigned long long to store RNTI uniquely
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    int size;
    int maxSize;
    int dropOldest; // 1 if oldest should be dropped on full, 0 to reject
} CRCList;

void logMessage(const char* message) {
    FILE* logFile = fopen("nfaapi_log.txt", "a");
    if (logFile != NULL) {
        fprintf(logFile, "%s\n", message);
        fclose(logFile);
    }
}

CRCList* createCRCList(int maxSize, int dropOldest) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    list->head = NULL;
    list->size = 0;
    list->maxSize = maxSize;
    list->dropOldest = dropOldest;
    return list;
}

int isRNTIUnique(CRCList* list, unsigned long long rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            return 0;
        }
        current = current->next;
    }
    return 1;
}

void addCRCIndication(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (list->size >= list->maxSize) {
        char logBuffer[256];
        sprintf(logBuffer, "Maximum size reached. Current size: %d", list->size);
        logMessage(logBuffer);

        if (!list->dropOldest) {
            sprintf(logBuffer, "Rejecting new entry with RNTI: %llu due to max size.", pdu.rnti);
            logMessage(logBuffer);
            return;
        }

        // Drop the oldest entry
        Node* temp = list->head;
        list->head = list->head->next;
        free(temp);

        sprintf(logBuffer, "Dropped oldest entry. Adding new RNTI: %llu", pdu.rnti);
        logMessage(logBuffer);
    }

    if (!isRNTIUnique(list, pdu.rnti)) {
        sprintf((char*)logBuffer, "Duplicate RNTI detected: %llu. Entry not added.", pdu.rnti);
        logMessage(logBuffer);
        return;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = pdu;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;

    sprintf(logBuffer, "Added new entry with RNTI: %llu", pdu.rnti);
    logMessage(logBuffer);
}

void freeCRCList(CRCList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}

// Example function to generate a random CRCFLAG
unsigned char getRandomCRCFlag() {
    return rand() % 2; // Randomly set to 0 or 1 for CRCFLAG
}
```

