    MAC_ADDR_NODE *new_node = (MAC_ADDR_NODE *)malloc(sizeof(MAC_ADDR_NODE));
    if (!new_node) {
        perror("Failed to allocate memory for MAC address node");
        exit(EXIT_FAILURE);
    }

    strncpy(new_node->mac_address, mac, sizeof(new_node->mac_address));
    new_node->next = context->mac_addresses;
    context->mac_addresses = new_node;
