void free_mac_context(MAC_CONTEXT_T *context) {
    MAC_ADDR_NODE *current = context->mac_addresses;
    while (current) {
        MAC_ADDR_NODE *temp = current;
        current = current->next;
        free(temp);
    }
    free(context);
