angular.module('app').controller('GraphController', function($scope, $http) {
    const RETRY_LIMIT = 3;
    const RATE_LIMIT_DELAY_MS = 1000;

    const networkTopologyAPI = 'https://api.example.com/network-topology';

    function refreshDialogFields(resourceId, url) {
        const fieldNamesToCheck = ['field1', 'field2', 'field3']; // Example field names

        angular.forEach($scope.dialogFields, (field) => {
            if (fieldNamesToCheck.includes(field.name)) {
                $scope.sendMessageToParentWindow({
                    resourceId: resourceId,
                    url: url,
                    fieldName: field.name
                }, (response) => {
                    if (response.success) {
                        field.value = response.result;
                    }
                });
            }
        });

        updateNetworkGraph();
    }

    function sendMessageToParentWindow(data, callback) {
        // Simulated message sending and receiving
        window.parent.postMessage({ type: 'request', data }, '*');

        setTimeout(() => {  // Mock response handler
            const mockResponse = { success: true, result: `Updated value for ${data.fieldName}` };
            if (mockResponse.success) {
                callback(mockResponse);
            }
        }, Math.random() * 1000 + 500); // Random delay to simulate network behavior
    }

    function updateNetworkGraph() {
        fetchFromAPIWithRetries().then(handleData).catch((err) => console.error('Failed to fetch data:', err));
    }

    function fetchFromAPIWithRetries(retries = RETRY_LIMIT, delay = 0) {
        return $http.get(networkTopologyAPI)
            .then(response => validateAndReturnData(response.data))
            .catch(error => {
                if (retries > 0 && isRateLimitError(error)) {
                    console.warn('Rate limit hit. Retrying after delay...');
                    return new Promise(resolve =>
                        setTimeout(() => resolve(fetchFromAPIWithRetries(retries - 1, RATE_LIMIT_DELAY_MS)), RATE_LIMIT_DELAY_MS)
                    );
                } else if (retries > 0) {
                    console.warn('Temporary error. Retrying...');
                    return new Promise(resolve =>
                        setTimeout(() => resolve(fetchFromAPIWithRetries(retries - 1)), delay)
                    );
                }
                throw error;
            });
    }

    function validateAndReturnData(data) {
        const isValid = data.every(node => node.hasOwnProperty('vertexId') && Array.isArray(node.edges));
        if (!isValid || data.length > 10000) {
            console.error('Invalid or too large data received.');
            return fetchFromAPIWithRetries(0); // Retry on invalid data
        }

        cacheData(data);
        return data;
    }

    function handleData(graphData) {
        const adjacencyList = buildAdjacencyList(graphData);
        $scope.networkGraph = adjacencyList;  // Update the graph in scope
    }

    function buildAdjacencyList(nodes) {
        const graph = {};

        nodes.forEach(node => {
            if (!graph[node.vertexId]) {
                graph[node.vertexId] = { vertexName: node.vertexName, edges: [] };
            }

            node.edges.forEach(edge => {
                if (edge.status === 'active') {
                    graph[node.vertexId].edges.push({
                        edgeId: edge.edgeId,
                        timestamp: edge.timestamp
                    });
                }
            });
        });

        return graph;
    }

    function cacheData(data) {
        sessionStorage.setItem('networkGraphCache', JSON.stringify(data));
    }

    function isRateLimitError(error) {
        // Check if the error is due to rate limiting
        return (error.status === 429 || error.message.includes('rate limit'));
    }
});
