    CRC_INDICATION_REL8_TAG crc_ind_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for the linked list
struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

typedef struct {
    struct Node* head;
    pthread_mutex_t lock;  // Mutex for thread safety
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(CRCList* list) {
    if (!list) return;

    struct Node* current = list->head;
    while (current) {
        struct Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool add_pdu(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return false;

    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
    if (!new_node) return false;
    new_node->data = pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    return true;
}

void iterate_and_print(CRCList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    struct Node* current = list->head;
    while (current) {
        // Assuming functions to print these structures are defined
        printf("RX_UE_INFORMATION_TAG: ... \n");
        printf("RNTI: ... \n");
        printf("CRC_INDICATION_REL8_TAG CRCFLAG: %d\n", current->data.crc_ind_rel8.CRCFLAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Recovery mechanism to handle inconsistent states
void recover_inconsistencies(CRCList* list) {
