int rnti_exists(CRCIndicationList* list, int rnti);
void log_error(const char* message);

// Initialize the list
CRCIndicationList* init_list() {
    CRCIndicationList* list = (CRCIndicationList*)malloc(sizeof(CRCIndicationList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add a new indication to the list
int add_indication(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (rnti_exists(list, pdu.valid)) { // Assuming valid field is RNTI for simplicity
        log_error("RNTI already exists");
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    if (list->size >= MAX_LIST_SIZE) {
        log_error("Maximum list size exceeded");
        pthread_mutex_unlock(&list->lock);
        return -2;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3;
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Check if an RNTI exists in the list
int rnti_exists(CRCIndicationList* list, int rnti) {
    Node* current = list->head;
    while (current) {
        // Assuming valid field is RNTI for simplicity
        if (current->data.valid == rnti) return 1;
        current = current->next;
    }
    return 0;
}

// Log error to file
void log_error(const char* message) {
    FILE* log_file = fopen("error_log.txt", "a");
    if (!log_file) return;
    fprintf(log_file, "%s\n", message);
    fclose(log_file);
}

// Background command execution thread function
void* execute_command(void* arg) {
    // Command execution logic goes here
    pthread_exit(NULL);
}

// Execute commands concurrently without blocking the main process
int execute_commands(int num_commands, int user_id, int group_id) {
    pthread_t threads[num_commands];
    for (int i = 0; i < num_commands; ++i) {
        if (pthread_create(&threads[i], NULL, execute_command, NULL)) {
            log_error("Failed to create thread");
            return -1;
        }
    }

    for (int i = 0; i < num_commands; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

// Signal handler
void signal_handler(int signo) {
    // Cleanup logic goes here
}

// Main function to demonstrate usage
