#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

typedef struct {
    void* payload;
    size_t length;
    time_t timestamp;
} data_packet;

void initialize_network(int protocol, int use_reuseaddr) {
    int sockfd = socket(AF_INET, protocol, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    if (use_reuseaddr) {
        int optval = 1;
        setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &optval, sizeof(optval));
    }

    // Example buffer size configuration
    int rcvbuf_size = 1024 * 1024; // 1MB receive buffer
    setsockopt(sockfd, SOL_SOCKET, SO_RCVBUF, &rcvbuf_size, sizeof(rcvbuf_size));

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (bind(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("socket bind failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }
}

void* allocate_random_payload(size_t length) {
    void* payload = malloc(length);
    if (!payload) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    unsigned char* p = (unsigned char*)payload;
    for (size_t i = 0; i < length; ++i) {
        p[i] = rand() % 256;
    }
    return payload;
}

void initialize_packets(data_packet* packets, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        size_t length = rand() % 1024 + 1; // Random length between 1 and 1024 bytes
        packets[i].payload = allocate_random_payload(length);
        packets[i].length = length;
        packets[i].timestamp = time(NULL);
    }
}

void* packet_processing_thread(void* arg) {
    data_packet* packets = (data_packet*)arg;
    size_t count = *(size_t*)(arg + sizeof(data_packet*));

    for (size_t i = 0; i < count; ++i) {
        // Example encryption with AES-256-CBC
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        unsigned char key[EVP_MAX_KEY_LENGTH] = {0}; // Initialize with your key
        unsigned char iv[EVP_MAX_IV_LENGTH] = {0};   // Initialize with your IV

        if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
            fprintf(stderr, "Encryption initialization failed\n");
            continue;
        }

        size_t outlen;
        unsigned char* encrypted_payload = malloc(packets[i].length + EVP_CIPHER_block_size(EVP_aes_256_cbc()));
        if (!EVP_EncryptUpdate(ctx, encrypted_payload, &outlen, packets[i].payload, packets[i].length)) {
            fprintf(stderr, "Encryption update failed\n");
            free(encrypted_payload);
            continue;
        }

        size_t final_outlen;
        if (!EVP_EncryptFinal_ex(ctx, encrypted_payload + outlen, &final_outlen)) {
            fprintf(stderr, "Encryption finalization failed\n");
            free(encrypted_payload);
            continue;
        }

        outlen += final_outlen;

        // Handle the encrypted payload...

        free(encrypted_payload);
        EVP_CIPHER_CTX_free(ctx);
    }

    return NULL;
}

void initialize_and_process_packets(size_t count, int protocol, int use_reuseaddr, int async) {
    initialize_network(protocol, use_reuseaddr);

    data_packet* packets = malloc(count * sizeof(data_packet));
    if (!packets) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    initialize_packets(packets, count);

    if (async) {
        pthread_t threads[count];
        for (size_t i = 0; i < count; ++i) {
            pthread_create(&threads[i], NULL, packet_processing_thread, packets + i);
        }
        for (size_t i = 0; i < count; ++i) {
            pthread_join(threads[i], NULL);
        }
    } else {
        packet_processing_thread(packets);
    }

    for (size_t i = 0; i < count; ++i) {
        free(packets[i].payload);
    }
    free(packets);
}

int main() {
    srand(time(NULL));
    initialize_and_process_packets(10, SOCK_STREAM, 1, 1); // Example usage
    return 0;
}
