#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CONNECTIONS 1000

typedef struct {
    char source_ip[16];
    char destination_ip[16];
    unsigned short source_port;
    unsigned short destination_port;
    int connection_status; // 1 for active, 0 for inactive
    time_t timestamp;
} TCP_CONNECTION_RECORD_T;

typedef struct Node {
    TCP_CONNECTION_RECORD_T record;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    return list;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int log_connection(const char* message, const char* filename) {
    FILE* file = fopen(filename, "a");
    if (!file) return 0;

    time_t now = time(NULL);
    fprintf(file, "[%s] %s\n", ctime(&now), message);
    fclose(file);
    return 1;
}

int is_duplicate(LinkedList* list, const TCP_CONNECTION_RECORD_T* record) {
    Node* current = list->head;
    while (current != NULL) {
        if ((strcmp(current->record.source_ip, record->source_ip) == 0) &&
            (strcmp(current->record.destination_ip, record->destination_ip) == 0) &&
            (current->record.source_port == record->source_port) &&
            (current->record.destination_port == record->destination_port)) {
            return 1;
        }
        current = current->next;
    }
    return 0;
}

int add_connection(LinkedList* list, TCP_CONNECTION_RECORD_T* new_record,
                   int drop_oldest, const char* log_file) {
    if (list->count == MAX_CONNECTIONS) {
        if (drop_oldest) {
            Node* oldest = list->head;
            if (oldest) {
                char log_msg[256];
                snprintf(log_msg, sizeof(log_msg), "Dropping oldest connection: %s:%d -> %s:%d",
                         oldest->record.source_ip, oldest->record.source_port,
                         oldest->record.destination_ip, oldest->record.destination_port);
                log_connection(log_msg, log_file);

                list->head = oldest->next;
                if (list->head == NULL) {
                    list->tail = NULL;
                } else {
                    list->head->prev = NULL;
                }
                free(oldest);
                list->count--;
            }
        } else {
            char log_msg[256];
            snprintf(log_msg, sizeof(log_msg), "Rejected new connection: %s:%d -> %s:%d",
                     new_record->source_ip, new_record->source_port,
                     new_record->destination_ip, new_record->destination_port);
            log_connection(log_msg, log_file);
            return 0;
        }
    }

    if (is_duplicate(list, new_record)) {
        char log_msg[256];
        snprintf(log_msg, sizeof(log_msg), "Duplicate connection: %s:%d -> %s:%d",
                 new_record->source_ip, new_record->source_port,
                 new_record->destination_ip, new_record->destination_port);
        log_connection(log_msg, log_file);
        return 0;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        char log_msg[] = "Failed to allocate memory for a new connection record.";
        log_connection(log_msg, log_file);
        return 0;
    }
    *new_node->record = *new_record;

    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;

    char log_msg[256];
    snprintf(log_msg, sizeof(log_msg), "Added connection: %s:%d -> %s:%d",
             new_record->source_ip, new_record->source_port,
             new_record->destination_ip, new_record->destination_port);
    log_connection(log_msg, log_file);

    return 1;
}

void manage_connections(LinkedList* list, TCP_CONNECTION_RECORD_T* record,
                        int drop_oldest, const char* log_file) {
    add_connection(list, record, drop_oldest, log_file);
}
```

