record* process_and_store_records(int N, double (*data_source_func)(int)) {
    if (N <= 0 || data_source_func == NULL) {
        fprintf(stderr, "Invalid input\n");
        return NULL;
    }

    data_source = data_source_func;

    record *records = malloc(N * sizeof(record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    int num_threads = 4; // Adjust based on system capability
    pthread_t threads[num_threads];
    int records_per_thread = N / num_threads;

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, process_records, (void *)(records + i * records_per_thread))) {
            perror("Failed to create thread");
            free(records);
            return NULL;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return records;
}

void* process_records(void* arg) {
    record *records = (record *)arg;
    int length;

    if ((intptr_t)arg % sizeof(record) == 0) {
        // Adjust length based on the first thread's workload
        length = N - num_threads + 1;
    } else {
        length = records_per_thread;
    }

    for (int i = 0; i < length; ++i) {
        long current_time = get_current_time();
        int identifier = ((intptr_t)arg / sizeof(record)) * records_per_thread + i;

        double metric_value;
        if ((metric_value = data_source(identifier)) != -1.0) { // Assuming -1 indicates failure
            record rec = {current_time, identifier, metric_value};

            if (store_record(&rec) == 0) {
