    if (*root == NULL) {
        *root = new_node;
        add_to_cache(new_node);
        return;
    }
    // Simple insertion logic (e.g., based on id)
    if (strcmp((*root)->id, new_node->id) > 0) {
        insert_node(&(*root)->left, new_node);
    } else {
        insert_node(&(*root)->right, new_node);
    }
}

// Find a node by ID
Node* find_node_by_id(Node* root, const char* id) {
    if (root == NULL || strcmp(root->id, id) == 0) return root;
    Node* left_result = find_node_by_id(root->left, id);
    if (left_result != NULL) return left_result;
    return find_node_by_id(root->right, id);
