    if (!manager) return NULL;

    manager->connections = (Connection**)calloc(initial_capacity, sizeof(Connection*));
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->timeout_threshold = timeout_threshold;

    return manager;
}

// Destroy the ConnectionManager and free all associated resources
void destroy_connection_manager(ConnectionManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free_connection_resources(manager->connections[i]);
        free(manager->connections[i]);
    }
    free(manager->connections);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Add a connection to the ConnectionManager
int add_connection(ConnectionManager* manager, Connection* connection) {
    if (!manager || !connection) return -1;

    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        resize_connections_array(manager, new_capacity);
    }

    manager->connections[manager->count++] = connection;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Remove a connection from the ConnectionManager by index
int remove_connection(ConnectionManager* manager, size_t index) {
    if (!manager || index >= manager->count) return -1;

    pthread_mutex_lock(&manager->lock);

    free_connection_resources(manager->connections[index]);
    free(manager->connections[index]);

    // Shift remaining connections down
    for (size_t i = index; i < manager->count - 1; ++i) {
        manager->connections[i] = manager->connections[i + 1];
    }

    --manager->count;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Lookup a connection by index
Connection* lookup_connection(ConnectionManager* manager, size_t index) {
    if (!manager || index >= manager->count) return NULL;

    pthread_mutex_lock(&manager->lock);
    Connection* connection = manager->connections[index];
    pthread_mutex_unlock(&manager->lock);

    return connection;
}

