#include <stdbool.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_MEMORY_USAGE 1024 // Max memory usage in bytes
#define INITIAL_ARRAY_SIZE 10
#define RESIZE_THRESHOLD 0.8

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CRCArrayManager;

// Logging function
void log_message(const char *message) {
    printf("%s\n", message);
}

CRCArrayManager* create_crc_array_manager() {
    CRCArrayManager *manager = malloc(sizeof(CRCArrayManager));
    if (!manager) {
        log_message("Memory allocation failed for manager.");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = INITIAL_ARRAY_SIZE;
    manager->count = 0;
    manager->array = malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        log_message("Memory allocation failed for array.");
        free(manager);
        return NULL;
    }

    log_message("CRC Array Manager initialized successfully.");
    return manager;
}

bool resize_array_if_needed(CRCArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity * RESIZE_THRESHOLD) {
        size_t new_capacity = manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_array) {
            log_message("Memory reallocation failed.");
            pthread_mutex_unlock(&manager->lock);
            return false;
        }

        manager->capacity = new_capacity;
        manager->array = new_array;
        log_message("Array resized successfully.");
    }

    pthread_mutex_unlock(&manager->lock);
    return true;
}

bool add_crc_indication_pdu(CRCArrayManager *manager, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!resize_array_if_needed(manager)) {
        return false;
    }

    pthread_mutex_lock(&manager->lock);

    manager->array[manager->count] = pdu;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    log_message("CRC Indication PDU added successfully.");
    return true;
}

size_t get_current_memory_usage(CRCArrayManager *manager) {
    pthread_mutex_lock(&manager->lock);

    size_t usage = sizeof(*manager) + manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    pthread_mutex_unlock(&manager->lock);
    return usage;
}

bool validate_pdu_integrity(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu == NULL || pdu->RX_UE_INFORMATION_TAG == 0 || pdu->RNTI == 0 ||
        pdu->CRC_INDICATION_REL8_TAG > 15) { // Assume max valid value is 15
        return false;
    }
    return true;
}

void destroy_crc_array_manager(CRCArrayManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->array);
        free(manager);
        log_message("CRC Array Manager destroyed successfully.");
    }
}

// Usage example
int main() {
    CRCArrayManager *manager = create_crc_array_manager();
    if (!manager) return 1;

    for (size_t i = 0; i < 20; ++i) { // Simulate adding PDUs
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i + 1;
        pdu.RNTI = i + 2;
        pdu.CRC_INDICATION_REL8_TAG = i % 16;
        pdu.CRCFLAG = rand() % 2 == 0;

        if (!add_crc_indication_pdu(manager, pdu)) {
            log_message("Failed to add PDU.");
        }
    }

    size_t usage = get_current_memory_usage(manager);
    printf("Current memory usage: %zu bytes\n", usage);

    destroy_crc_array_manager(manager);

    return 0;
}
```

This implementation ensures thread-safe access using a mutex, manages dynamic resizing of the array while maintaining strict memory limits, and includes logging for performance monitoring. It also validates PDU integrity upon creation and provides an interface to query current memory usage. The system is designed with embedded constraints in mind, minimizing allocations and ensuring idempotency in operations.']

