typedef struct ListNode {
    char *timestamp;
    float temperature;
    int sensor_id;
    struct ListNode *next;
} ListNode;

float* read_and_average_numbers(size_t *count) {
    float *numbers = NULL;
    size_t capacity = 10;
    numbers = (float*)malloc(capacity * sizeof(float));
    if (!numbers) return NULL;

    size_t total_numbers = 0;
    char input[256];
    while (fgets(input, sizeof(input), stdin)) {
        if (total_numbers >= capacity) {
            capacity *= 2;
            numbers = (float*)realloc(numbers, capacity * sizeof(float));
            if (!numbers) break;
        }

        char *endptr;
        float number = strtof(input, &endptr);
        if (*endptr == '\0' || isspace(*endptr)) {
            numbers[total_numbers++] = number;
        }
    }

    *count = total_numbers;
    return numbers;
}

float calculate_average(float *numbers, size_t count) {
    float sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += numbers[i];
    }
    return (count > 0) ? (sum / count) : 0.0;
}

