    ListNode *node = (ListNode*)malloc(sizeof(ListNode));
    if (!node) return NULL;

    node->timestamp = strdup(timestamp);
    if (!node->timestamp) {
        free(node);
        return NULL;
    }

    node->temperature = temperature;
    node->sensor_id = sensor_id;
    node->next = NULL;
    return node;
}

