#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <zlib.h>
#include <time.h>

#define MAX_METRICS 1000
#define BATCH_SIZE 10
#define RETENTION_PERIOD (60 * 60) // 1 hour in seconds

typedef struct {
    uint64_t timestamp;
    char session_id[32];
    float latency;
    float throughput;
    float packet_loss;
} Metric;

typedef struct Node {
    Metric data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

typedef struct {
    LinkedList lists[MAX_METRICS];
    uint64_t hash_table[MAX_METRICS];
    pthread_rwlock_t rwlock;
    time_t last_cleanup;
} DistributedList;

uint32_t hash_function(const char* session_id) {
    unsigned long hash = 5381;
    int c;
    while ((c = *session_id++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % MAX_METRICS;
}

void initialize_list(DistributedList* dist_list) {
    for (int i = 0; i < MAX_METRICS; ++i) {
        dist_list->lists[i].head = NULL;
        pthread_mutex_init(&dist_list->lists[i].lock, NULL);
    }
    pthread_rwlock_init(&dist_list->rwlock, NULL);
    dist_list->last_cleanup = time(NULL);
}

Node* create_node(Metric metric) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = metric;
    new_node->next = NULL;
    return new_node;
}

void insert_metric(DistributedList* dist_list, Metric metric) {
    uint32_t index = hash_function(metric.session_id);
    pthread_mutex_lock(&dist_list->lists[index].lock);

    Node* new_node = create_node(metric);
    if (!new_node) {
        pthread_mutex_unlock(&dist_list->lists[index].lock);
        return;
    }

    new_node->next = dist_list->lists[index].head;
    dist_list->lists[index].head = new_node;

    pthread_mutex_unlock(&dist_list->lists[index].lock);
}

void batch_insert(DistributedList* dist_list, Metric metrics[], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        insert_metric(dist_list, metrics[i]);
    }
}

void cleanup_metrics(DistributedList* dist_list) {
    time_t now = time(NULL);
    if ((now - dist_list->last_cleanup) < RETENTION_PERIOD) return;

    for (int i = 0; i < MAX_METRICS; ++i) {
        pthread_mutex_lock(&dist_list->lists[i].lock);

        Node* current = dist_list->lists[i].head;
        Node* prev = NULL;
        while (current) {
            if ((now - current->data.timestamp) > RETENTION_PERIOD) {
                Node* to_delete = current;
                current = current->next;
                if (prev) {
                    prev->next = current;
                } else {
                    dist_list->lists[i].head = current;
                }
                free(to_delete);
            } else {
                prev = current;
                current = current->next;
            }
        }

        pthread_mutex_unlock(&dist_list->lists[i].lock);
    }

    dist_list->last_cleanup = now;
}

void compress_and_export(DistributedList* dist_list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;
    deflateInit(&stream, Z_BEST_COMPRESSION);

    for (int i = 0; i < MAX_METRICS; ++i) {
        pthread_mutex_lock(&dist_list->lists[i].lock);

        Node* current = dist_list->lists[i].head;
        while (current) {
            fwrite(current->data.session_id, sizeof(char), strlen(current->data.session_id), file);
            fwrite(&current->data.timestamp, sizeof(uint64_t), 1, file);
            fwrite(&current->data.latency, sizeof(float), 1, file);
            fwrite(&current->data.throughput, sizeof(float), 1, file);
            fwrite(&current->data.packet_loss, sizeof(float), 1, file);

            char buffer[1024];
            int compressed_size = compress2(buffer, sizeof(buffer), (unsigned char*)&current->data, sizeof(Metric), Z_BEST_COMPRESSION);
            if (compressed_size > 0) {
                fwrite(buffer, 1, compressed_size, file);
            }

            current = current->next;
        }

        pthread_mutex_unlock(&dist_list->lists[i].lock);
    }

    deflateEnd(&stream);
    fclose(file);
}

void* metric_cleanup_thread(void* arg) {
    DistributedList* dist_list = (DistributedList*)arg;
    while (1) {
        sleep(60); // Run cleanup every minute
        cleanup_metrics(dist_list);
    }
    return NULL;
}

void start_cleanup_daemon(DistributedList* dist_list) {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, metric_cleanup_thread, dist_list);
    pthread_detach(thread_id);
}

int main() {
    DistributedList dist_list;
    initialize_list(&dist_list);

    // Example usage
    Metric metrics[BATCH_SIZE];
    for (size_t i = 0; i < BATCH_SIZE; ++i) {
        sprintf(metrics[i].session_id, "session_%zu", i);
        metrics[i].timestamp = time(NULL);
        metrics[i].latency = rand() % 100;
        metrics[i].throughput = rand() % 1000;
        metrics[i].packet_loss = (rand() % 10) / 100.0;
    }

    batch_insert(&dist_list, metrics, BATCH_SIZE);

    start_cleanup_daemon(&dist_list);

    compress_and_export(&dist_list, "metrics.gz");

    return 0;
}
```

### Key Points:

- **Thread Safety**: Uses mutexes for individual list segments and a read-write lock for the entire structure.
- **Distributed Hash Table**: Simplified with modulo-based hashing.
- **Batch Insertion**: Supports concurrent inserts without excessive locking.
- **Compression**: Utilizes zlib to compress metrics before exporting.
- **Cleanup**: Periodic cleanup based on retention policy.
- **Memory Management**: Uses dynamic allocation and ensures cleanup of unused nodes.

This code provides a foundation for a distributed system handling network performance metrics, with considerations for scalability and fault tolerance. Adjustments may be needed based on specific infrastructure requirements and constraints.']

