#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} CRC_INDICATION_REL8_TAG_T;

typedef struct {
    int CRCFLAG;
    CRC_INDICATION_REL8_TAG_T crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

void handleError(const char* message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) handleError("Memory allocation failed for new node");
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void freeList(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

void printList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("RNTI: %d, CRCFLAG: %d\n", current->data.crcTag.RNTI, current->data.CRCFLAG);
        current = current->next;
    }
}

int isUnique(int RNTI, Node* head) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.crcTag.RNTI == RNTI) return 0;
        current = current->next;
    }
    return 1;
}

Node* configureAndOperateNFALinkedList(int N, int M) {
    if (M > MAX_ELEMENTS) handleError("Maximum elements exceed allowed limit");

    Node* head = NULL;
    srand(time(NULL));

    for (int i = 0; i < N && M > 0; ++i) {
        int RNTI = rand() % N + 1;

        while (!isUnique(RNTI, head)) {
            RNTI = rand() % N + 1;
        }

        NFAPI_CRC_INDICATION_PDU_T data = { .CRCFLAG = rand() % 2, .crcTag = { .RX_UE_INFORMATION_TAG = i + 1, .RNTI = RNTI } };
        Node* newNode = createNode(data);

        if (!head) {
            head = newNode;
        } else {
            Node* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = newNode;
        }

        --M;
    }

    printList(head);
    return head;
}

int main() {
    int N = 10; // Number of elements to create
    int M = 5;  // Maximum number of elements in the list

    Node* linkedList = configureAndOperateNFALinkedList(N, M);

    freeList(&linkedList);
    return 0;
}
