} NFAPI_MESSAGE_T;

// Node of the linked list
typedef struct ListNode {
    NFAPI_MESSAGE_T data;
    struct ListNode* next;
} ListNode;

// Linked List structure with mutex for thread safety
typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
    size_t count;  // Track number of elements in the list
} LinkedList;

// Function to initialize linked list
void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

// Function to add a new message to the list
void addMessage(LinkedList* list, NFAPI_MESSAGE_T message) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) return;

    newNode->data = message;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

// Function to find a message by BWP identity and C-RNTI
NFAPI_MESSAGE_T* findMessage(LinkedList* list, int bwp_identity, int c_rnti) {
    ListNode* current = list->head;
    while (current != NULL) {
        if (current->data.ind_pdu.bwp_identity == bwp_identity &&
            current->data.ind_pdu.c_rnti == c_rnti) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL;  // Not found
}

// Function to remove a message from the list by BWP identity and C-RNTI
void removeMessage(LinkedList* list, int bwp_identity, int c_rnti) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head, *prev = NULL;
    while (current != NULL) {
        if (current->data.ind_pdu.bwp_identity == bwp_identity &&
            current->data.ind_pdu.c_rnti == c_rnti) {
            if (prev) prev->next = current->next;
            else list->head = current->next;

            free(current);
            list->count--;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to clear the linked list
void clearLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head, *temp = NULL;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
}

// Function to serialize the linked list
void serializeLinkedList(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    ListNode* current = list->head;
    while (current != NULL) {
        fwrite(&(current->data), sizeof(NFAPI_MESSAGE_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

// Function to deserialize the linked list
void deserializeLinkedList(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    clearLinkedList(list);

    NFAPI_MESSAGE_T message;
    while (fread(&message, sizeof(NFAPI_MESSAGE_T), 1, file)) {
        addMessage(list, message);
    }

    fclose(file);
}

