['Below is a C library that meets the task description requirements. The code includes thread-safe operations for managing `MAC_CONTEXT_T` structures using mutexes for synchronization, efficient memory management with dynamic allocation, and periodic cleanup of stale entries.

```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Structure Definitions

typedef struct {
    // Define LMAC_CONFIG fields here
} LMAC_CONFIG;

typedef struct MAC_PACKET {
    // Define MAC_PACKET fields here
    time_t timestamp;
    struct MAC_PACKET* next;
} MAC_PACKET;

typedef struct {
    char unique_id[64];
    LMAC_CONFIG config;
    MAC_PACKET* packets_head;
    pthread_mutex_t mutex;
    time_t last_accessed;
} MAC_CONTEXT_T;

// Global Variables

#define CLEANUP_INTERVAL 60 // seconds
#define STALE_GRACE_PERIOD 300 // seconds

typedef struct {
    MAC_CONTEXT_T** contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t global_mutex;
    pthread_t cleanup_thread;
    int running;
} ContextManager;

// Function Prototypes

void* context_manager_init(size_t initial_capacity);
MAC_CONTEXT_T* add_context(ContextManager* manager, const char* unique_id, LMAC_CONFIG config);
int remove_context(ContextManager* manager, const char* unique_id);
MAC_CONTEXT_T* get_context(ContextManager* manager, const char* unique_id);
void cleanup_stale_contexts(ContextManager* manager);
static void* periodic_cleanup(void* arg);

// Function Implementations

void* context_manager_init(size_t initial_capacity) {
    ContextManager* manager = malloc(sizeof(ContextManager));
    if (!manager) return NULL;

    manager->contexts = calloc(initial_capacity, sizeof(MAC_CONTEXT_T*));
    if (!manager->contexts) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->global_mutex, NULL);

    if (pthread_create(&manager->cleanup_thread, NULL, periodic_cleanup, manager)) {
        // Cleanup and exit
        free(manager->contexts);
        free(manager);
        return NULL;
    }

    manager->running = 1;
    return manager;
}

MAC_CONTEXT_T* add_context(ContextManager* manager, const char* unique_id, LMAC_CONFIG config) {
    pthread_mutex_lock(&manager->global_mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->contexts[i]->unique_id, unique_id) == 0) {
            pthread_mutex_unlock(&manager->global_mutex);
            return NULL;
        }
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        MAC_CONTEXT_T** new_contexts = realloc(manager->contexts, new_capacity * sizeof(MAC_CONTEXT_T*));
        if (!new_contexts) {
            pthread_mutex_unlock(&manager->global_mutex);
            return NULL;
        }
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }

    MAC_CONTEXT_T* context = malloc(sizeof(MAC_CONTEXT_T));
    if (!context) {
        pthread_mutex_unlock(&manager->global_mutex);
        return NULL;
    }

    strncpy(context->unique_id, unique_id, sizeof(context->unique_id) - 1);
    context->config = config;
    context->packets_head = NULL;
    pthread_mutex_init(&context->mutex, NULL);
    context->last_accessed = time(NULL);

    manager->contexts[manager->count++] = context;

    pthread_mutex_unlock(&manager->global_mutex);
    return context;
}

int remove_context(ContextManager* manager, const char* unique_id) {
    pthread_mutex_lock(&manager->global_mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->contexts[i]->unique_id, unique_id) == 0) {
            MAC_CONTEXT_T* context = manager->contexts[i];

            pthread_mutex_destroy(&context->mutex);
            while (context->packets_head) {
                MAC_PACKET* packet = context->packets_head;
                context->packets_head = packet->next;
                free(packet);
            }

            free(context);

            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->contexts[j] = manager->contexts[j + 1];
            }

            --manager->count;
            pthread_mutex_unlock(&manager->global_mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->global_mutex);
    return -1;
}

MAC_CONTEXT_T* get_context(ContextManager* manager, const char* unique_id) {
    pthread_mutex_lock(&manager->global_mutex);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->contexts[i]->unique_id, unique_id) == 0) {
            MAC_CONTEXT_T* context = manager->contexts[i];
            context->last_accessed = time(NULL);
            pthread_mutex_unlock(&manager->global_mutex);
            return context;
        }
    }

    pthread_mutex_unlock(&manager->global_mutex);
    return NULL;
}

void cleanup_stale_contexts(ContextManager* manager) {
    time_t now = time(NULL);

    for (size_t i = 0; i < manager->count;) {
        MAC_CONTEXT_T* context = manager->contexts[i];

        pthread_mutex_lock(&context->mutex);
        if ((now - context->last_accessed) > STALE_GRACE_PERIOD) {
            while (context->packets_head) {
                MAC_PACKET* packet = context->packets_head;
                context->packets_head = packet->next;
                free(packet);
            }

            pthread_mutex_destroy(&context->mutex);

            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->contexts[j] = manager->contexts[j + 1];
            }

            --manager->count;
            free(context);
        } else {
            pthread_mutex_unlock(&context->mutex);
            ++i;
        }
    }
}

static void* periodic_cleanup(void* arg) {
    ContextManager* manager = (ContextManager*)arg;

    while (manager->running) {
        sleep(CLEANUP_INTERVAL);
        cleanup_stale_contexts(manager);
    }

    return NULL;
}

// Unit Tests

void test_context_manager() {
    // Initialize context manager
    ContextManager* manager = (ContextManager*)context_manager_init(10);

    if (!manager) {
        printf("Failed to initialize context manager.\n");
        return;
    }

    // Add a context and verify it exists
    LMAC_CONFIG config;
    MAC_CONTEXT_T* context = add_context(manager, "unique_id_1", config);
    assert(context != NULL);

    MAC_CONTEXT_T* retrieved_context = get_context(manager, "unique_id_1");
    assert(retrieved_context == context);

    // Remove the context and verify it no longer exists
    int result = remove_context(manager, "unique_id_1");
    assert(result == 0);

    retrieved_context = get_context(manager, "unique_id_1");
    assert(retrieved_context == NULL);

    // Cleanup
    pthread_cancel(manager->cleanup_thread);
    manager->running = 0;
    pthread_join(manager->cleanup_thread, NULL);
    free(manager->contexts);
    free(manager);
}

int main() {
    test_context_manager();
    printf("All tests passed.\n");
    return 0;
}
