#include <time.h>

typedef struct {
    int frameNumber;
    time_t timestamp;
    int packetCount;
} FrameStatistics;

#define MAX_TIMESTAMP_DIFF_SECONDS (24 * 60 * 60) // 24 hours in seconds

int isTimestampValid(time_t timestamp) {
    time_t currentTime = time(NULL);
    return difftime(currentTime, timestamp) <= MAX_TIMESTAMP_DIFF_SECONDS;
}

FrameStatistics* initializeFrameStatistics(int numFrames, int frameData[][3], size_t dataLength) {
    FrameStatistics *frames = (FrameStatistics*)malloc(numFrames * sizeof(FrameStatistics));
    if (!frames) {
        perror("Memory allocation failed");
        return NULL;
    }

    size_t validCount = 0;
    for (size_t i = 0; i < dataLength && validCount < numFrames; ++i) {
        int frameNumber = frameData[i][0];
        time_t timestamp = frameData[i][1];
        int packetCount = frameData[i][2];

        if (isTimestampValid(timestamp)) {
            frames[validCount].frameNumber = frameNumber;
            frames[validCount].timestamp = timestamp;
            frames[validCount].packetCount = packetCount;
            ++validCount;
        }
    }

    return validCount > 0 ? frames : NULL;
}

void freeFrameStatistics(FrameStatistics *frames) {
    if (frames) {
        free(frames);
    }
}

// Example usage:
int main() {
    int frameData[][3] = {
        {1, time(NULL) - 3600, 100},
        {2, time(NULL) - 90000, 150}, // This one is older than 24 hours
        {3, time(NULL), 200}
    };
    size_t dataLength = sizeof(frameData) / sizeof(frameData[0]);

    FrameStatistics *frames = initializeFrameStatistics(10, frameData, dataLength);
    if (frames) {
        for (int i = 0; frames[i].frameNumber != 0; ++i) { // Assuming default-constructed zeros
            printf("Frame %d: Timestamp = %ld, Packet Count = %d\n", 
                   frames[i].frameNumber, (long)frames[i].timestamp, frames[i].packetCount);
        }
        freeFrameStatistics(frames);
    } else {
        fprintf(stderr, "Failed to initialize frame statistics.\n");
    }

    return 0;
}
```

