['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

typedef struct Entry {
    long timestamp;
    int status_code;
    char *message;
    struct Entry *next;
} Entry;

typedef struct List {
    Entry *head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List *list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_entry(Entry *entry) {
    if (entry) {
        free(entry->message);
        free(entry);
    }
}

int add_entry(List *list, long timestamp, int status_code, const char *message) {
    Entry *new_entry = (Entry*)malloc(sizeof(Entry));
    new_entry->timestamp = timestamp;
    new_entry->status_code = status_code;
    new_entry->message = strdup(message);
    new_entry->next = NULL;

    pthread_mutex_lock(&list->lock);

    Entry **tracer = &(list->head);
    while (*tracer && (*tracer)->timestamp < timestamp) {
        tracer = &((*tracer)->next);
    }

    if (*tracer && (*tracer)->timestamp == timestamp) {
        free(new_entry->message);
        free(new_entry);
        pthread_mutex_unlock(&list->lock);
        return -1; // Duplicate timestamp
    }

    new_entry->next = *tracer;
    *tracer = new_entry;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

Entry* remove_entry_by_timestamp(List *list, long timestamp) {
    Entry *entry = NULL;

    pthread_mutex_lock(&list->lock);

    Entry **tracer = &(list->head);
    while (*tracer && (*tracer)->timestamp != timestamp) {
        tracer = &((*tracer)->next);
    }

    if (*tracer) {
        entry = *tracer;
        *tracer = entry->next;
        free_entry(entry);
    }

    pthread_mutex_unlock(&list->lock);
    return entry; // Return NULL if not found
}

Entry* get_most_recent(List *list) {
    Entry *entry = NULL;

    pthread_mutex_lock(&list->lock);

    entry = list->head;

    pthread_mutex_unlock(&list->lock);
    return entry;
}

void serialize_list(const char *filename, List *list) {
    FILE *file = fopen(filename, "wb");

    if (!file) return;

    Entry *entry = list->head;

    pthread_mutex_lock(&list->lock);

    while (entry) {
        fwrite(&entry->timestamp, sizeof(long), 1, file);
        fwrite(&entry->status_code, sizeof(int), 1, file);
        size_t len = strlen(entry->message) + 1;
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(entry->message, sizeof(char), len, file);
        entry = entry->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

void deserialize_list(const char *filename, List *list) {
    FILE *file = fopen(filename, "rb");

    if (!file) return;

    Entry *entry = NULL, **tracer = &(list->head);

    while (1) {
        long timestamp;
        int status_code;
        size_t len;

        fread(&timestamp, sizeof(long), 1, file);
        if (ferror(file)) break; // EOF or error

        fread(&status_code, sizeof(int), 1, file);

        fread(&len, sizeof(size_t), 1, file);

        char *message = (char*)malloc(len);
        fread(message, sizeof(char), len, file);

        entry = (Entry*)malloc(sizeof(Entry));
        entry->timestamp = timestamp;
        entry->status_code = status_code;
        entry->message = message;
        entry->next = NULL;

        pthread_mutex_lock(&list->lock);

        *tracer = entry;
        tracer = &entry->next;

        pthread_mutex_unlock(&list->lock);
    }

    fclose(file);
}

void free_list(List *list) {
    Entry *entry = list->head, *tmp;

    pthread_mutex_lock(&list->lock);

    while (entry) {
        tmp = entry;
        entry = entry->next;
        free_entry(tmp);
    }

    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

