#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure as per requirements.
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// List structure with head pointer and size counter
typedef struct {
    Node* head;
    int size;
} PduList;

// Function prototypes
PduList* create_list();
void destroy_list(PduList* list);
int add_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu);
int remove_pdu(PduList* list, int rnti);
int update_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T updatedPdu);
Node* find_node_by_rnti(Node* head, int rnti);

// Helper functions
void randomize_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu != NULL) {
        srand(time(NULL));
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }
}

int is_valid_rx_ue_info(int rx_ue_tag) {
    // Assuming a valid range for RX_UE_INFORMATION_TAG
    return (rx_ue_tag >= 0 && rx_ue_tag <= 100); // Example range, adjust as needed
}

// Create an empty list
PduList* create_list() {
    PduList* list = (PduList*)malloc(sizeof(PduList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    return list;
}

// Destroy the list and free memory
void destroy_list(PduList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    free(list);
}

// Add a new PDU to the list, ensuring unique RNTI
int add_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_valid_rx_ue_info(pdu.RX_UE_INFORMATION_TAG)) return -1;

    if (find_node_by_rnti(list->head, pdu.RNTI) != NULL) return -2; // RNTI already exists

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -3; // Memory allocation failure

    newNode->data = pdu;
    randomize_crcflag(&pdu);

    newNode->next = list->head;
    list->head = newNode;
    list->size++;

    return 0; // Success
}

// Remove a PDU from the list by RNTI
int remove_pdu(PduList* list, int rnti) {
    Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) return -1; // Not found

    if (prev == NULL) { // Removing head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->size--;

    return 0; // Success
}

// Update an existing PDU by RNTI
int update_pdu(PduList* list, NFAPI_CRC_INDICATION_PDU_T updatedPdu) {
    if (!is_valid_rx_ue_info(updatedPdu.RX_UE_INFORMATION_TAG)) return -1;

    Node* node = find_node_by_rnti(list->head, updatedPdu.RNTI);
    if (node == NULL) return -2; // Not found

    node->data = updatedPdu;
    randomize_crcflag(&updatedPdu);

    return 0; // Success
}

// Helper function to find a node by RNTI
Node* find_node_by_rnti(Node* head, int rnti) {
    while (head != NULL) {
        if (head->data.RNTI == rnti)
            return head;
        head = head->next;
    }
    return NULL; // Not found
}
