#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_FRAMES 1000
#define TIMESTAMP_RANGE_HOURS 24
#define FLUSH_THRESHOLD_DAYS 7

typedef struct {
    int frameNumber;
    time_t timestamp;
    int packetCount;
} FrameStatistics;

typedef struct {
    FrameStatistics* frames;
    size_t count;
    pthread_mutex_t lock;
} FrameArray;

// Logging mechanism using simple counters and print statements.
int processedFrames = 0, addedFrames = 0, ignoredFrames = 0;

void log_event(const char* message) {
    printf("%s\n", message);
}

FrameArray* init_frame_array(size_t max_frames) {
    FrameArray* array = (FrameArray*)malloc(sizeof(FrameArray));
    if (!array) return NULL;
    array->frames = (FrameStatistics*)malloc(max_frames * sizeof(FrameStatistics));
    if (!array->frames) {
        free(array);
        return NULL;
    }
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void flush_old_frames(FrameArray* array) {
    time_t now = time(NULL);
    time_t threshold = now - (FLUSH_THRESHOLD_DAYS * 24 * 60 * 60);

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count;) {
        if (array->frames[i].timestamp < threshold) {
            memmove(&array->frames[i], &array->frames[i + 1],
                    (array->count - i - 1) * sizeof(FrameStatistics));
            array->count--;
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

void insert_frame(FrameArray* array, int frameNumber, time_t timestamp, int packetCount) {
    processedFrames++;

    if (timestamp < (time(NULL) - TIMESTAMP_RANGE_HOURS * 60 * 60)) {
        log_event("Timestamp out of range.");
        return;
    }

    pthread_mutex_lock(&array->lock);

    if (array->count >= MAX_FRAMES) {
        ignoredFrames++;
        log_event("Frame insertion rejected: Exceeded max frame limit.");
        pthread_mutex_unlock(&array->lock);
        return;
    }

    array->frames[array->count].frameNumber = frameNumber;
    array->frames[array->count].timestamp = timestamp;
    array->frames[array->count].packetCount = packetCount;
    array->count++;
    addedFrames++;

    pthread_mutex_unlock(&array->lock);
}

float calculate_average_packet_count(FrameArray* array) {
    if (array->count == 0) return 0.0f;

    pthread_mutex_lock(&array->lock);

    int totalPackets = 0;
    for (size_t i = 0; i < array->count; i++) {
        totalPackets += array->frames[i].packetCount;
    }

    float average = (float)totalPackets / array->count;

    pthread_mutex_unlock(&array->lock);

    return average;
}

void serialize_frame_array(const FrameArray* array, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    fwrite(&array->count, sizeof(size_t), 1, file);
    fwrite(array->frames, sizeof(FrameStatistics), array->count, file);

    fclose(file);
}

void deserialize_frame_array(FrameArray* array, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&array->lock);

    free(array->frames);
    array->frames = (FrameStatistics*)malloc(count * sizeof(FrameStatistics));
    if (!array->frames) {
        pthread_mutex_unlock(&array->lock);
        fclose(file);
        return;
    }
    fread(array->frames, sizeof(FrameStatistics), count, file);
    array->count = count;

    pthread_mutex_unlock(&array->lock);

    fclose(file);
}

void free_frame_array(FrameArray* array) {
    if (!array) return;
    pthread_mutex_lock(&array->lock);

    free(array->frames);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}
