#define MAX_PRODUCT_NAME_LENGTH 256

typedef struct {
    int productId;
    char productName[MAX_PRODUCT_NAME_LENGTH];
    int stockQuantity;
    time_t lastUpdatedTimestamp;
} Product;

typedef struct Node {
    Product product;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} InventoryList;

InventoryList* create_inventory_list() {
    InventoryList* list = malloc(sizeof(InventoryList));
    if (!list) return NULL;
    list->head = NULL;
    if (pthread_mutex_init(&list->mutex, NULL) != 0) {
        free(list);
        return NULL;
    }
    return list;
}

void destroy_inventory_list(InventoryList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int days_between(time_t start, time_t end) {
    const int SECONDS_PER_DAY = 24 * 60 * 60;
    return (end - start) / SECONDS_PER_DAY;
}

int update_inventory(InventoryList* list, Product newProduct, time_t currentTime) {
    if (!list || days_between(currentTime, newProduct.lastUpdatedTimestamp) > 7)
        return 0;

    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current) {
        if (current->product.productId == newProduct.productId) {
            if (days_between(currentTime, newProduct.lastUpdatedTimestamp) <= 7) {
                current->product.stockQuantity = newProduct.stockQuantity;
                current->product.lastUpdatedTimestamp = newProduct.lastUpdatedTimestamp;
            }
            pthread_mutex_unlock(&list->mutex);
            return 1;
        }
        current = current->next;
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->mutex);
        return 0;
    }

    newNode->product = newProduct;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->mutex);
    return 1;
}

int main() {
    InventoryList* inventory = create_inventory_list();
    if (!inventory) {
        fprintf(stderr, "Failed to initialize inventory list.\n");
        return EXIT_FAILURE;
    }

    time_t currentTime = time(NULL);

    Product product1 = {101, "Product A", 50, currentTime};
    update_inventory(inventory, product1, currentTime);

    // Simulate an update within the last 7 days
    Product product2 = {101, "Product A", 45, currentTime - (3 * 24 * 60 * 60)};
    update_inventory(inventory, product2, currentTime);

    // Destroy inventory list when done
    destroy_inventory_list(inventory);

    return EXIT_SUCCESS;
}
