#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int key;
} record;

#define INITIAL_CAPACITY 16

typedef struct {
    record *records;
    int keys[INITIAL_CAPACITY];
    size_t capacity;
    size_t size;
    size_t total_allocations;
    size_t successful_allocations;
    size_t failed_allocations;
    size_t peak_memory_usage;
} HashTable;

unsigned long hash(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

HashTable* create_hash_table() {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) {
        log_allocation("Failed to allocate memory for hash table", 0);
        return NULL;
    }
    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    table->total_allocations = 0;
    table->successful_allocations = 0;
    table->failed_allocations = 0;
    table->peak_memory_usage = 0;

    table->records = malloc(sizeof(record) * table->capacity);
    if (!table->records) {
        free(table);
        log_allocation("Failed to allocate memory for records", 0);
        return NULL;
    }
    memset(table->keys, -1, sizeof(int) * table->capacity);

    log_allocation("Successfully allocated hash table and records", sizeof(HashTable) + sizeof(record) * INITIAL_CAPACITY);
    update_peak_memory_usage(table);

    return table;
}

void log_allocation(const char *message, size_t bytes) {
    printf("%s: %zu bytes\n", message, bytes);
}

void update_peak_memory_usage(HashTable *table) {
    if (table->total_allocations * sizeof(record) > table->peak_memory_usage) {
        table->peak_memory_usage = table->total_allocations * sizeof(record);
    }
}

int insert_record(HashTable *table, int key) {
    if (table->size >= table->capacity) {
        size_t new_capacity = table->capacity * 2;
        record *new_records = realloc(table->records, sizeof(record) * new_capacity);
        if (!new_records) {
            log_allocation("Failed to reallocate memory for records", 0);
            return -1;
        }

        int *new_keys = malloc(sizeof(int) * new_capacity);
        if (!new_keys) {
            free(new_records);
            log_allocation("Failed to allocate memory for new keys array", 0);
            return -1;
        }
        memset(new_keys, -1, sizeof(int) * new_capacity);

        memcpy(new_records + table->capacity, table->records, sizeof(record) * table->size);
        memcpy(new_keys, table->keys, sizeof(int) * table->capacity);
        free(table->records);
        free(table->keys);

        table->records = new_records;
        table->keys = new_keys;
        table->capacity = new_capacity;

        log_allocation("Successfully reallocated memory for records and keys", sizeof(record) * new_capacity + sizeof(int) * new_capacity);
    }

    unsigned long index = hash(key, table->capacity);
    while (table->keys[index] != -1) {
        if (++index == table->capacity) index = 0;
    }

    record new_record = { .key = key };
    table->records[table->size++] = new_record;
    table->keys[index] = key;

    table->total_allocations++;
    update_peak_memory_usage(table);
    log_allocation("Successfully inserted a record", sizeof(record));
    return 0;
}

int delete_record(HashTable *table, int key) {
    unsigned long index = hash(key, table->capacity);
    while (table->keys[index] != -1) {
        if (table->keys[index] == key) break;
        if (++index == table->capacity) index = 0;
    }

    if (table->keys[index] == -1) return -1;

    for (size_t i = index; i < table->capacity; ++i) {
        if (table->keys[i] != -1) continue;

        size_t shift_index = (i + 1) % table->capacity;
        while (table->keys[shift_index] != -1) {
            unsigned long new_index = hash(table->keys[shift_index], table->capacity);
            if ((new_index >= i && new_index < shift_index) || 
                (new_index < i && new_index > shift_index)) {
                table->records[i] = table->records[shift_index];
                table->keys[i] = table->keys[shift_index];
            }
            shift_index = (shift_index + 1) % table->capacity;
        }

        table->size--;
        break;
    }

    log_allocation("Successfully deleted a record", 0);
    return 0;
}

record* lookup_record(HashTable *table, int key) {
    unsigned long index = hash(key, table->capacity);
    while (table->keys[index] != -1) {
        if (table->keys[index] == key) return &table->records[index];
        if (++index == table->capacity) index = 0;
    }
    return NULL;
}

void print_summary(HashTable *table) {
    printf("Total allocations: %zu\n", table->total_allocations);
    printf("Successful allocations: %zu\n", table->successful_allocations);
    printf("Failed allocations: %zu\n", table->failed_allocations);
    printf("Peak memory usage: %zu bytes\n", table->peak_memory_usage);
}

void free_hash_table(HashTable *table) {
    if (table) {
        free(table->records);
        free(table->keys);
        log_allocation("Successfully deallocated records and keys", sizeof(record) * table->capacity + sizeof(int) * table->capacity);
        free(table);
        log_allocation("Successfully deallocated hash table", sizeof(HashTable));
    }
}

int main() {
    srand(time(NULL));

    HashTable *table = create_hash_table();
    if (!table) return 1;

    int num_keys = rand() % 1000 + 500;
    for (int i = 0; i < num_keys; ++i) {
        int key = rand() % 10000;
        insert_record(table, key);
    }

    print_summary(table);

    free_hash_table(table);
    return 0;
}
