```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

#define MAX_FILENAME_LENGTH 1024

typedef struct {
    int crc_value;
    // Add other necessary fields for the NFAPI_CRC_INDICATION_PDU_T structure
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int rnti;
    int rx_ue_info_tag;
    unsigned long crc_checksum;
} Record;

typedef struct {
    pthread_mutex_t lock;
    bool async_mode_enabled;
} LoggingContext;

void log_message(const char *message, LoggingContext *log_context) {
    if (log_context->async_mode_enabled) {
        // Implement asynchronous logging mechanism
    } else {
        pthread_mutex_lock(&log_context->lock);
        printf("%s\n", message);
        pthread_mutex_unlock(&log_context->lock);
    }
}

bool validate_filename(const char *filename) {
    return strlen(filename) <= MAX_FILENAME_LENGTH &&
           strncmp(filename, "./", 2) != 0 && 
           strncmp(filename, "../", 3) != 0;
}

void initialize_random(unsigned int seed) {
    srand(seed ? seed : time(NULL));
}

unsigned long generate_crc_checksum(const char *data) {
    unsigned long checksum = 0;
    while (*data) {
        checksum += (unsigned long)(*data++);
    }
    return checksum;
}

Record* allocate_records(size_t num_records, unsigned int range_min, unsigned int range_max,
                         const char *filename, LoggingContext *log_context) {

    if (!validate_filename(filename)) {
        log_message("Invalid filename provided", log_context);
        return NULL;
    }

    Record *records = (Record *)malloc(num_records * sizeof(Record));
    if (!records) {
        log_message("Failed to allocate memory for records", log_context);
        return NULL;
    }

    srand(time(NULL)); // Initialize random number generator
    for (size_t i = 0; i < num_records; ++i) {
        records[i].rnti = rand() % 1000000;
        records[i].rx_ue_info_tag = rand() % 10000;
        char data[64]; // Example data buffer, adjust size as needed
        snprintf(data, sizeof(data), "Record_%zu", i);
        records[i].crc_checksum = generate_crc_checksum(data);

        log_message("Initialized a record", log_context);
    }

    return records;
}

void free_records(Record *records) {
    if (records) {
        free(records);
    }
}

int main() {
    LoggingContext log_context;
    pthread_mutex_init(&log_context.lock, NULL);
    log_context.async_mode_enabled = false; // Set based on user preference

    Record *records = allocate_records(10, 0, 100, "valid_filename.txt", &log_context);

    if (records) {
        // Use the records for further processing
        free_records(records);
    }

    pthread_mutex_destroy(&log_context.lock);
    return 0;
}
