#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONFIGS 1000

typedef struct {
    char *region;
    char *interfaceName;
    int port;
    double latency;
} NetworkConfig;

typedef struct {
    NetworkConfig configs[MAX_CONFIGS];
    size_t count;
    pthread_rwlock_t lock; // Read-write lock for concurrent access
} ConfigManager;

int validate_config(const char* region, const char* interfaceName, int port, double latency) {
    if (region == NULL || strlen(region) == 0)
        return -1;
    if (interfaceName == NULL || strlen(interfaceName) == 0)
        return -2;
    if (port <= 0 || port > 65535)
        return -3;
    if (latency < 0.0)
        return -4;
    return 0; // Valid
}

void apply_configuration(ConfigManager *manager, NetworkConfig config) {
    pthread_rwlock_wrlock(&manager->lock);
    if (manager->count < MAX_CONFIGS) {
        manager->configs[manager->count++] = config;
    }
    pthread_rwlock_unlock(&manager->lock);
}

NetworkConfig* fetch_and_parse_config(const char* filename, ConfigManager *manager) {
    FILE *file = fopen(filename, "r");
    if (file == NULL)
        return NULL;

    char line[256];
    NetworkConfig newConfig;
    while (fgets(line, sizeof(line), file)) {
        char region[50], interfaceName[50];
        int port;
        double latency;

        if (sscanf(line, "%49[^,],%49[^,],%d,%lf", region, interfaceName, &port, &latency) == 4) {
            newConfig.region = strdup(region);
            newConfig.interfaceName = strdup(interfaceName);
            newConfig.port = port;
            newConfig.latency = latency;

            int validationError = validate_config(newConfig.region, newConfig.interfaceName, newConfig.port, newConfig.latency);
            if (validationError == 0) {
                apply_configuration(manager, newConfig);
            } else {
                free(newConfig.region);
                free(newConfig.interfaceName);
            }
        } else {
            fprintf(stderr, "Malformed line: %s", line);
        }
    }

    fclose(file);
    return manager->configs;
}

void init_config_manager(ConfigManager *manager) {
    pthread_rwlock_init(&manager->lock, NULL);
    manager->count = 0;
}

void cleanup_config_manager(ConfigManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->configs[i].region);
        free(manager->configs[i].interfaceName);
    }
    pthread_rwlock_destroy(&manager->lock);
}

int main() {
    ConfigManager configManager;
    init_config_manager(&configManager);

    // Example: Fetch and parse configurations from a file
    fetch_and_parse_config("network_config.txt", &configManager);

    cleanup_config_manager(&configManager);

    return 0;
}
