typedef struct {
    int *value;
    int initialized; // 0 for not initialized, 1 for initialized
} record;

void initialize_random(int min, int max) {
    srand((unsigned int) time(NULL));
}

int generate_unique_int(int min, int max, int used[], size_t size) {
    int num = rand() % (max - min + 1) + min;
    for (size_t i = 0; i < size; i++) {
        if (used[i] == num)
            return -1; // Indicates duplicate found
    }
    return num;
}

int populate_records(record *records, int *offsets, int *keys, size_t size, int min, int max) {
    int used[size];
    for (size_t i = 0; i < size; ++i)
        used[i] = -1;

    for (size_t i = 0; i < size; i++) {
        records[i].value = (int *) malloc(sizeof(int));
        if (!records[i].value) return -1; // Memory allocation failure

        int unique_value;
        do {
            unique_value = generate_unique_int(min, max, used, size);
        } while (unique_value == -1);

        *records[i].value = unique_value;
        records[i].initialized = 1;
        used[i] = unique_value;

        offsets[i] = (long) unique_value; // Example offset value
        keys[i] = unique_value % 10;      // Example key derived from the unique value
    }
    return 0;
}

void deallocate_memory(record *records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (records[i].value)
            free(records[i].value);
    }
    free(records);
}

int all_initialized(record *records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (!records[i].initialized)
            return 0;
    }
    return 1;
}

// Unit Test Function
void test_function() {
    size_t size = 10;
    int min = 1, max = 100;

    long *offsets = (long *) malloc(size * sizeof(long));
    int *keys = (int *) malloc(size * sizeof(int));

    if (!offsets || !keys) {
        printf("Memory allocation failed.\n");
        return;
    }

    record *records = (record *) malloc(size * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        printf("Memory allocation failed.\n");
        return;
    }

    initialize_random(min, max);

    if (populate_records(records, offsets, keys, size, min, max) != 0) {
        printf("Failed to populate records with unique values.\n");
        deallocate_memory(records, size);
        free(offsets);
        free(keys);
        return;
    }

    if (!all_initialized(records, size)) {
        printf("Not all records are initialized properly.\n");
    } else {
        printf("All records successfully initialized and populated with unique values.\n");
    }

    deallocate_memory(records, size);
    free(offsets);
    free(keys);
}

int main() {
    test_function();
    return 0;
}
