    for (int i = 0; i < MAX_POLICIES; ++i) {
        if (qos_pool[i].id == -1) {
            qos_pool[i].id = i; // Initialize with id as a simple example.
            pthread_mutex_unlock(&resource_lock);
            return &qos_pool[i];
        }
    }
    pthread_mutex_unlock(&resource_lock);
    return NULL; // Pool exhausted.
}

void deallocate_qos_config(LTE_QoS_Class_ID_T* config) {
    if (config) {
        pthread_mutex_lock(&resource_lock);
        config->id = -1;
        pthread_mutex_unlock(&resource_lock);
    }
}

