        log_message(2, "Entering reduced-memory mode.");
        reduced_memory_mode = 1;
    } else if (usage <= REDUCED_MEMORY_MODE_THRESHOLD && reduced_memory_mode) {
        log_message(2, "Exiting reduced-memory mode.");
        reduced_memory_mode = 0;
    }
}

void prioritize_policies(LTE_QoS_Class_ID_T* configs, int num_configs) {
