['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NODES 50000
#define TRANSACTION_LIMIT 10000

typedef struct {
    int sensor_id;
    time_t timestamp;
    int valid_flag;
} SensorNetworkPDU;

typedef struct Transaction {
    int transaction_id;
    double weighted_sum;
    time_t age;
} Transaction;

typedef struct Node {
    double temperature;
    float humidity;
    SensorNetworkPDU sensor_data;
    struct Node* next;
} Node;

typedef struct Graph {
    Node** nodes;
    size_t node_count;
    size_t capacity;
} Graph;

typedef struct TransactionSet {
    Transaction* transactions;
    size_t count;
    size_t capacity;
    double max_weighted_sum;
    int max_transaction_id;
} TransactionSet;

// Function prototypes
Graph* init_graph(size_t initial_capacity);
void free_graph(Graph* graph);
Node* add_node(Graph* graph, SensorNetworkPDU sensor_data, double temperature, float humidity);
void remove_node(Graph* graph, int sensor_id);

TransactionSet* init_transaction_set(size_t initial_capacity);
void free_transaction_set(TransactionSet* ts);
void update_transactions(TransactionSet* ts, const Transaction* new_transactions, size_t count);
int filter_and_calculate_weighted_sum(TransactionSet* ts, double threshold_age, int max_frequency, double min_weighted_sum);

Graph* init_graph(size_t initial_capacity) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    if (!graph) return NULL;

    graph->nodes = (Node**)calloc(initial_capacity, sizeof(Node*));
    graph->node_count = 0;
    graph->capacity = initial_capacity;

    return graph;
}

void free_graph(Graph* graph) {
    if (!graph) return;

    for (size_t i = 0; i < graph->node_count; ++i) {
        free(graph->nodes[i]);
    }
    free(graph->nodes);
    free(graph);
}

Node* add_node(Graph* graph, SensorNetworkPDU sensor_data, double temperature, float humidity) {
    if (graph->node_count == graph->capacity) {
        size_t new_capacity = graph->capacity * 2;
        Node** new_nodes = (Node**)realloc(graph->nodes, new_capacity * sizeof(Node*));
        if (!new_nodes) return NULL;

        memset(new_nodes + graph->capacity, 0, graph->capacity * sizeof(Node*));
        graph->nodes = new_nodes;
        graph->capacity = new_capacity;
    }

    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->temperature = temperature;
    node->humidity = humidity;
    node->sensor_data = sensor_data;
    node->next = NULL;

    graph->nodes[graph->node_count++] = node;
    return node;
}

void remove_node(Graph* graph, int sensor_id) {
    for (size_t i = 0; i < graph->node_count; ++i) {
        if (graph->nodes[i] && graph->nodes[i]->sensor_data.sensor_id == sensor_id) {
            free(graph->nodes[i]);
            graph->nodes[i] = graph->nodes[--graph->node_count];
            return;
        }
    }
}

TransactionSet* init_transaction_set(size_t initial_capacity) {
    TransactionSet* ts = (TransactionSet*)malloc(sizeof(TransactionSet));
    if (!ts) return NULL;

    ts->transactions = (Transaction*)calloc(initial_capacity, sizeof(Transaction));
    ts->count = 0;
    ts->capacity = initial_capacity;
    ts->max_weighted_sum = -1.0;
    ts->max_transaction_id = -1;

    return ts;
}

void free_transaction_set(TransactionSet* ts) {
    if (!ts) return;

    free(ts->transactions);
    free(ts);
}

void update_transactions(TransactionSet* ts, const Transaction* new_transactions, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (ts->count == ts->capacity) {
            size_t new_capacity = ts->capacity * 2;
            Transaction* new_array = (Transaction*)realloc(ts->transactions, new_capacity * sizeof(Transaction));
            if (!new_array) continue;

            memset(new_array + ts->capacity, 0, ts->capacity * sizeof(Transaction));
            ts->transactions = new_array;
            ts->capacity = new_capacity;
        }

        Transaction* trans = &ts->transactions[ts->count++];
        memcpy(trans, &new_transactions[i], sizeof(Transaction));

        if (trans->weighted_sum > ts->max_weighted_sum) {
            ts->max_weighted_sum = trans->weighted_sum;
            ts->max_transaction_id = trans->transaction_id;
        }
    }
}

int filter_and_calculate_weighted_sum(TransactionSet* ts, double threshold_age, int max_frequency, double min_weighted_sum) {
    time_t current_time = time(NULL);
    size_t valid_count = 0;

    for (size_t i = 0; i < ts->count; ++i) {
        Transaction* trans = &ts->transactions[i];
        if ((current_time - trans->age) > threshold_age &&
            trans->weighted_sum >= min_weighted_sum) {

            // Simulate frequency check
            valid_count++;
            if (valid_count > max_frequency) break;
        }
    }

    return ts->max_transaction_id;
}

int main() {
    srand(time(NULL));

    Graph* graph = init_graph(100);
    TransactionSet* transaction_set = init_transaction_set(100);

    // Example usage:
    SensorNetworkPDU sensor_data = { .sensor_id = 1, .timestamp = time(NULL), .valid_flag = 1 };
    add_node(graph, sensor_data, 25.5, 60.0f);
    remove_node(graph, 1);

    Transaction new_transactions[100];
    for (int i = 0; i < 100; ++i) {
        new_transactions[i].transaction_id = rand() % TRANSACTION_LIMIT;
        new_transactions[i].weighted_sum = (double)(rand() % 1000) / 10.0;
        new_transactions[i].age = time(NULL) - (rand() % 3600);
    }
    update_transactions(transaction_set, new_transactions, 100);

    int max_id = filter_and_calculate_weighted_sum(transaction_set, 1800, 500, 50.0);
    printf("Max Transaction ID: %d\n", max_id);

    free_graph(graph);
    free_transaction_set(transaction_set);

    return 0;
}
