ErrorCode create_nfa_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t max_limit, const unsigned char *data_buffer, size_t data_length) {
    pthread_mutex_lock(&lock);

    if (num_structures >= max_limit || !data_buffer || data_length == 0) {
        pthread_mutex_unlock(&lock);
        return ERROR_INSUFFICIENT_MEMORY;
    }

    for (size_t i = 0; i < num_structures; ++i) {
        // Check for duplicate tags
        if (unique_tags[i] != -1 && /* condition to check if the tag exists */) {
            pthread_mutex_unlock(&lock);
            return ERROR_DUPLICATE_ENTRY;
        }
    }

    *list = (NFAPI_CRC_INDICATION_PDU_T *)allocate_memory(max_limit * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        pthread_mutex_unlock(&lock);
        return ERROR_INSUFFICIENT_MEMORY;
    }

    for (size_t i = 0; i < max_limit && i + num_structures < MAX_STRUCTURES; ++i) {
        (*list)[i].RX_UE_INFORMATION_TAG = /* generate unique tag */;
        if (/* check if the tag is already used */) {
            deallocate_memory(*list);
            pthread_mutex_unlock(&lock);
