        (*list)[i].RNTI = /* generate RNTI */;
        (*list)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag(data_buffer, data_length);

        unique_tags[num_structures + i] = (*list)[i].RX_UE_INFORMATION_TAG;
    }

    num_structures += max_limit;
    pthread_mutex_unlock(&lock);
    return SUCCESS;
}

void free_nfa_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list) {
        deallocate_memory(list);
    }
