// Define the structure as per task description
typedef struct {
    unsigned int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a mutex for thread safety
pthread_mutex_t collection_mutex = PTHREAD_MUTEX_INITIALIZER;

// Dynamic array to store structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
} Collection;

// Function prototypes
Collection* initialize_collection(size_t initial_capacity);
void configure_network_interface(Collection *collection, size_t n);
void cleanup_collection(Collection *collection);

Collection* initialize_collection(size_t initial_capacity) {
    Collection *col = (Collection *)malloc(sizeof(Collection));
    if (!col) {
        perror("Failed to allocate memory for collection");
        return NULL;
    }

    col->array = (NFAPI_CRC_INDICATION_PDU_T *)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!col->array) {
        free(col);
        perror("Failed to allocate memory for array");
        return NULL;
    }

    col->capacity = initial_capacity;
    col->count = 0;

    return col;
}

void configure_network_interface(Collection *collection, size_t n) {
    pthread_mutex_lock(&collection_mutex);

    if (n > collection->capacity - collection->count) {
        // Expand capacity
        size_t new_capacity = collection->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(collection->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Failed to reallocate memory for expanded array");
            pthread_mutex_unlock(&collection_mutex);
            return;
        }
        collection->array = new_array;
        collection->capacity = new_capacity;
    }

    srand(time(NULL));  // Seed random number generator

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pthread_mutex_lock(&collection_mutex);  // Lock per structure to minimize contention

        pdu.RX_UE_INFORMATION_TAG = rand() % 10000;  // Random unique tag
        pdu.RNTI = rand() % 1000;                    // Random RNTI
        pdu.crc_tag.CRCFLAG = rand() & 1;            // Random CRC flag (0 or 1)

        collection->array[collection->count++] = pdu;

        pthread_mutex_unlock(&collection_mutex);  // Unlock per structure
    }

    pthread_mutex_unlock(&collection_mutex);
}

void cleanup_collection(Collection *collection) {
    if (collection) {
        free(collection->array);
        free(collection);
    }
}
```

### Key Considerations:
