        structures->long_timestamps = new_long_timestamps;
        structures->sensor_readings = new_sensor_readings;
        structures->measurement_records = new_measurement_records;
    } else {
        // Handle reallocation failure
        fprintf(stderr, "Memory reallocation failed!\n");
        free_dynamic_structures(structures);
        exit(EXIT_FAILURE);
    }
}

void manage_memory_for_nfa_pi(DynamicDataStructures* structures, int max_capacity) {
    if (structures->count >= max_capacity - 10) { // Threshold to trigger resizing
        resize_dynamic_structures(structures, max_capacity * 2);
    }

    unsigned long current_time = time(NULL);

    for (int i = 0; i < MAX_STRUCTS; ++i) {
