            structures->measurement_records[structures->count].value = structures->sensor_readings[structures->count].value;

            structures->count++;
        }
    }

    // Example of memory fragmentation check and compaction
    if (rand() % 100 < MEMORY_COMPACT_THRESHOLD_PERCENTAGE) {
        resize_dynamic_structures(structures, max_capacity / 2); // Simulate compaction by resizing
    }

    // Periodically clear data structures to free up memory
    if (structures->count == max_capacity) {
        memset(structures->long_timestamps, 0, max_capacity * sizeof(LongTimestamp));
        memset(structures->sensor_readings, 0, max_capacity * sizeof(FloatSensorReading));
