#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_MESSAGES 1024
#define RETRY_LIMIT 3
#define RETRY_DELAY_MS 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set to 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int TLVEncoder_sequence_number;
    char NAS_Message_type[16];
    char NAS_Message_content[256];
} LTE_DL_CCCH_Message_Type1_T;

int populate_NFAPI_CRC_INDICATION_PDU_and_DL_CCCH_Messages(int maxN, NFAPI_CRC_INDICATION_PDU_T **pdu_list, int *num_pdus,
                                                            LTE_DL_CCCH_Message_Type1_T **dl_ccch_list, int *num_dlccchs) {
    if (maxN > MAX_MESSAGES || !pdu_list || !num_pdus || !dl_ccch_list || !num_dlccchs) {
        fprintf(stderr, "Invalid input parameters.\n");
        return -1;
    }

    // Initialize random seed
    srand((unsigned int)time(NULL));

    *pdu_list = malloc(maxN * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdu_list) {
        perror("Failed to allocate memory for PDU list");
        return -1;
    }

    *dl_ccch_list = malloc(maxN * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!*dl_ccch_list) {
        perror("Failed to allocate memory for DL CCCH list");
        free(*pdu_list);
        return -1;
    }

    int success_pdus = 0, success_dlccchs = 0;

    // Populate PDU list
    for (int i = 0; i < maxN; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &((*pdu_list)[i]);
        pdu->RX_UE_INFORMATION_TAG = rand() % 100;
        pdu->RNTI = rand() % 1000;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 50;
        pdu->CRCFLAG = rand() % 2;

        success_pdus++;
    }

    *num_pdus = success_pdus;

    // Populate DL CCCH list
    for (int i = 0; i < maxN; ++i) {
        LTE_DL_CCCH_Message_Type1_T *dl_ccch = &((*dl_ccch_list)[i]);
        dl_ccch->TLVEncoder_sequence_number = i + 1;

        int retry_count = 0;
