#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MEMORY_POOL_SIZE 1024

// Memory pool structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool[MEMORY_POOL_SIZE];
    pthread_mutex_t lock;
    size_t count;
} MemoryPool;

// Initialize the memory pool
MemoryPool* init_memory_pool() {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    for (size_t i = 0; i < MEMORY_POOL_SIZE; ++i) {
        mp->pool[i] = NULL;
    }
    pthread_mutex_init(&mp->lock, NULL);
    mp->count = 0;
    return mp;
}

// Allocate a PDU from the memory pool
NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(MemoryPool *mp) {
    pthread_mutex_lock(&mp->lock);

    if (mp->count > 0) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = mp->pool[--mp->count];
        pthread_mutex_unlock(&mp->lock);
        return pdu;
    }

    pthread_mutex_unlock(&mp->lock);
    return (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Free a PDU back to the memory pool
void free_pdu(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&mp->lock);

    if (mp->count < MEMORY_POOL_SIZE) {
        mp->pool[mp->count++] = pdu;
    } else {
        free(pdu);
    }

    pthread_mutex_unlock(&mp->lock);
}

// Linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Thread-safe linked list structure
typedef struct {
    Node *head;
    pthread_mutex_t lock;
} SafeLinkedList;

// Initialize the thread-safe linked list
SafeLinkedList* init_safe_list() {
    SafeLinkedList *list = (SafeLinkedList*)malloc(sizeof(SafeLinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Insert a PDU into the list
void insert_pdu(SafeLinkedList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->data = *pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Validate and process PDUs
void validate_and_process(SafeLinkedList *list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (current->data.RX_UE_INFORMATION_TAG <= 0 || current->data.RNTI <= 0) {
            fprintf(stderr, "Invalid PDU encountered: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n",
                    current->data.RX_UE_INFORMATION_TAG, current->data.RNTI);
        } else {
            // Process valid PDU
            printf("Processing PDU: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
                   current->data.RX_UE_INFORMATION_TAG, current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG);
        }
        Node *temp = current;
        current = current->next;
        free_pdu(NULL, &temp->data); // Assuming memory pool is globally accessible
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
}

// Cleanup function for the list
void cleanup_list(SafeLinkedList *list) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free_pdu(NULL, &temp->data); // Assuming memory pool is globally accessible
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    MemoryPool *mp = init_memory_pool();
    SafeLinkedList *nfa_list = init_safe_list();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 2, 3};
    NFAPI_CRC_INDICATION_PDU_T *pdu_ptr1 = allocate_pdu(mp);
    *pdu_ptr1 = pdu1;
    insert_pdu(nfa_list, pdu_ptr1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = {-1, 0, 4}; // Invalid PDU
    NFAPI_CRC_INDICATION_PDU_T *pdu_ptr2 = allocate_pdu(mp);
    *pdu_ptr2 = pdu2;
    insert_pdu(nfa_list, pdu_ptr2);

    validate_and_process(nfa_list);

    cleanup_list(nfa_list);
    pthread_mutex_destroy(&mp->lock);
    free(mp);

    return 0;
}
