['Below is a C implementation that addresses your request by creating a thread-safe doubly linked list of `NFAPI_TX_COMMAND_PDU_T` structures, handling dynamic allocation with error logging, managing memory efficiently, supporting concurrent initialization requests, and integrating features for populating an array of `LTE_DL_CCCH_Message_Type1_T` structures.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

#define MAX_ELEMENTS M
#define TX_MODE_MIN 0
#define TX_MODE_MAX 10
#define CHANNEL_BANDWIDTH_MIN 5
#define CHANNEL_BANDWIDTH_MAX 20

typedef struct LTE_DL_CCCH_Message_Type1_T {
    // Simulated TLVEncoder and NAS_Message structures.
    void* TLVEncoder;
    char NAS_Message[256];
} LTE_DL_CCCH_Message_Type1;

typedef struct NFAPI_TX_COMMAND_PDU_T {
    int TX_UE_INFORMATION_TAG;
    int RRC_INSTANCE_ID;
    int TRANSMISSION_CONFIG_REL15_TAG;
    int TX_MODE;
    int CHANNEL_BANDWIDTH;
    struct NFAPI_TX_COMMAND_PDU_T* prev;
    struct NFAPI_TX_COMMAND_PDU_T* next;
} NFAPI_TX_COMMAND_PDU;

typedef struct {
    NFAPI_TX_COMMAND_PDU* head;
    NFAPI_TX_COMMAND_PDU* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) {
        perror("Failed to allocate memory for DoublyLinkedList");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(DoublyLinkedList* list) {
    if (!list) return;

    NFAPI_TX_COMMAND_PDU* current = list->head;
    while (current) {
        NFAPI_TX_COMMAND_PDU* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

void log_message(const char* message) {
    printf("[%lu] %s\n", time(NULL), message);
}

NFAPI_TX_COMMAND_PDU* create_pdu(int instance_id, int tag) {
    NFAPI_TX_COMMAND_PDU* pdu = (NFAPI_TX_COMMAND_PDU*)malloc(sizeof(NFAPI_TX_COMMAND_PDU));
    if (!pdu) {
        perror("Failed to allocate memory for NFAPI_TX_COMMAND_PDU");
        return NULL;
    }
    pdu->TX_UE_INFORMATION_TAG = rand() % 1000; // Example tag
    pdu->RRC_INSTANCE_ID = instance_id;
    pdu->TRANSMISSION_CONFIG_REL15_TAG = tag;
    pdu->TX_MODE = TX_MODE_MIN + rand() % (TX_MODE_MAX - TX_MODE_MIN + 1);
    pdu->CHANNEL_BANDWIDTH = CHANNEL_BANDWIDTH_MIN + rand() % (CHANNEL_BANDWIDTH_MAX - CHANNEL_BANDWIDTH_MIN + 1);
    pdu->prev = NULL;
    pdu->next = NULL;

    return pdu;
}

void add_pdu_to_list(DoublyLinkedList* list, NFAPI_TX_COMMAND_PDU* pdu) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = list->tail = pdu;
    } else {
        list->tail->next = pdu;
        pdu->prev = list->tail;
        list->tail = pdu;
    }

    pthread_mutex_unlock(&list->lock);
}

void init_list(DoublyLinkedList* list, int n) {
    if (!list) return;

    int instance_id_set[MAX_ELEMENTS] = {0};
    for (int i = 1; i <= n && MAX_ELEMENTS > 0; ++i) {
        pthread_mutex_lock(&list->lock);

        NFAPI_TX_COMMAND_PDU* pdu = create_pdu(i, rand() % 100); // Random tag
        if (!pdu || instance_id_set[i - 1]) {
            log_message("Initialization failed for a PDU.");
            pthread_mutex_unlock(&list->lock);
            continue;
        }

        int valid_instance = 0;
        for (int j = 0; j < MAX_ELEMENTS && !valid_instance; ++j) {
            if (!instance_id_set[j]) {
                instance_id_set[j] = i;
                add_pdu_to_list(list, pdu);
                valid_instance = 1;
            }
        }

        pthread_mutex_unlock(&list->lock);

        if (valid_instance) --MAX_ELEMENTS;
    }
}

void populate_nas_messages(LTE_DL_CCCH_Message_Type1 messages[], int size) {
    for (int i = 0; i < size; ++i) {
        messages[i].TLVEncoder = malloc(128); // Example allocation
        if (!messages[i].TLVEncoder) {
            perror("Failed to allocate TLVEncoder");
            continue;
        }

        snprintf(messages[i].NAS_Message, sizeof(messages[i].NAS_Message), "Message_Type_%d_Content", rand() % 10);
    }
}

void free_nas_messages(LTE_DL_CCCH_Message_Type1 messages[], int size) {
    for (int i = 0; i < size; ++i) {
        if (messages[i].TLVEncoder) {
            free(messages[i].TLVEncoder);
        }
    }
}

int main() {
    srand(time(NULL));

    DoublyLinkedList* list = create_list();
    if (!list) return EXIT_FAILURE;

    int num_elements = 10; // Example number of elements
    init_list(list, num_elements);

    LTE_DL_CCCH_Message_Type1 nas_messages[5];
    populate_nas_messages(nas_messages, sizeof(nas_messages) / sizeof(nas_messages[0]));

    free_list(list);
    free_nas_messages(nas_messages, 5);

    return EXIT_SUCCESS;
}
