```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int id;
    char type[10];
} PacketHeader;

typedef struct {
    PacketHeader header;
    size_t payloadSize;
    time_t timestamp;
} DataPacket;

typedef struct {
    DataPacket **packets;
    size_t count;
    size_t capacity;
    double rollingAveragePayloadSize;
    size_t totalPacketsProcessed;
} DynamicArray;

DynamicArray* initialize_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->packets = (DataPacket **)calloc(initial_capacity, sizeof(DataPacket *));
    if (!array->packets) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;
    array->rollingAveragePayloadSize = 0.0;
    array->totalPacketsProcessed = 0;

    return array;
}

int add_packet(DynamicArray *array, PacketHeader header, size_t payloadSize) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        DataPacket **new_packets = (DataPacket **)realloc(array->packets, new_capacity * sizeof(DataPacket *));
        if (!new_packets) return -1;

        array->packets = new_packets;
        array->capacity = new_capacity;
    }

    DataPacket *packet = (DataPacket *)malloc(sizeof(DataPacket));
    if (!packet) return -1;

    packet->header = header;
    packet->payloadSize = payloadSize;
    packet->timestamp = time(NULL);

    array->packets[array->count++] = packet;

    double oldAverage = array->rollingAveragePayloadSize;
    array->rollingAveragePayloadSize = ((oldAverage * (array->totalPacketsProcessed)) + payloadSize) / (array->totalPacketsProcessed + 1);
    array->totalPacketsProcessed++;

    return 0;
}

int filter_packets_by_min_size(DynamicArray *array, size_t min_payload_size) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->packets[i]->payloadSize >= min_payload_size) {
            printf("Packet ID: %d, Size: %zu\n", array->packets[i]->header.id, array->packets[i]->payloadSize);
        }
    }

    return 0;
}

void deallocate_dynamic_array(DynamicArray *array) {
    if (!array) return;

    for (size_t i = 0; i < array->count; ++i) {
        free(array->packets[i]);
    }

    free(array->packets);
    free(array);
}

int main() {
    DynamicArray *dataArray = initialize_dynamic_array(10);

    if (!dataArray) {
        fprintf(stderr, "Failed to allocate memory for dynamic array.\n");
        return 1;
    }

    PacketHeader header = { .id = 1, .type = "TCP" };
    add_packet(dataArray, header, 1024);
    add_packet(dataArray, (PacketHeader){.id = 2, .type = "UDP"}, 512);

    filter_packets_by_min_size(dataArray, 500);

    deallocate_dynamic_array(dataArray);

    return 0;
}
```

