// Define structures
typedef struct {
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef uint16_t RX_UE_INFORMATION_TAG;

typedef uint32_t RNTI;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NetworkPerformanceMetricNode {
    time_t timestamp;
    uint64_t session_id;
    int measurement_count;
    double *measurements; // Variable length array
    struct NetworkPerformanceMetricNode* next;
    NFAPI_CRC_INDICATION_PDU_T* crc_pdu_array;
} NetworkPerformanceMetricNode;

// Global variables for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a unique RNTI and populate CRC_FLAG randomly
int allocate_and_populate_crc_pdu_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t* size, uint32_t seed) {
    if (!array || !size) return -1;

    srand(seed);
    *size = 0;
    *array = NULL;

    bool success = false;
    for (int attempts = 0; attempts < 3 && !success; ++attempts) {
        size_t new_size = rand() % 100 + 10; // Randomize between 10 and 110
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (new_size + (*size)));

        if (!new_array) {
            fprintf(stderr, "Memory allocation failed\n");
            free(*array);
            return -1;
        }

        for (size_t i = 0; i < new_size; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.ue_info_tag = rand() % 10000; // Random RX_UE_INFORMATION_TAG
            bool unique_rnti = false;

            while (!unique_rnti) {
                pdu.rnti = rand();
                unique_rnti = true;

                for (size_t j = 0; j < *size; ++j) {
                    if ((*array)[j].rnti == pdu.rnti) {
                        unique_rnti = false;
                        break;
                    }
                }
            }

            pdu.crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

            new_array[*size + i] = pdu;
        }

        *array = new_array;
        *size += new_size;

        int true_count = 0, total_count = *size;
        for (size_t i = 0; i < *size; ++i) {
            if ((*array)[i].crc_indication_rel8_tag.CRCFLAG) true_count++;
        }

        if ((true_count * 2) <= total_count) success = true;
    }

    return success ? 0 : -1;
}

// Function to initialize and populate the linked list of Network Performance Metrics
int init_and_populate_performance_metrics(NetworkPerformanceMetricNode** head, size_t max_size) {
    if (!head || !max_size) return -1;

    *head = NULL;
    size_t current_size = 0;

    while (current_size < max_size) {
        pthread_mutex_lock(&lock);

        NetworkPerformanceMetricNode* new_node = malloc(sizeof(NetworkPerformanceMetricNode));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed for new node\n");
            pthread_mutex_unlock(&lock);
            return -1;
        }

        new_node->timestamp = time(NULL);
        new_node->session_id = rand(); // Unique session identifier
        new_node->measurement_count = rand() % 10 + 5; // Random number of measurements (between 5 and 15)
        new_node->measurements = malloc(sizeof(double) * new_node->measurement_count);

        if (!new_node->measurements) {
            fprintf(stderr, "Memory allocation failed for measurements\n");
            free(new_node);
            pthread_mutex_unlock(&lock);
            return -1;
        }

        // Populate measurements
        for (int i = 0; i < new_node->measurement_count; ++i) {
            new_node->measurements[i] = rand() % 100 / 10.0; // Random double value between 0 and 10
        }

        if (!(*head)) {
            *head = new_node;
        } else {
            NetworkPerformanceMetricNode* current = *head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_node;
        }

        pthread_mutex_unlock(&lock);

        // Allocate CRC indication array for the node
        if (allocate_and_populate_crc_pdu_array(&(new_node->crc_pdu_array), &current_size, rand()) != 0) {
            fprintf(stderr, "Failed to allocate and populate CRC PDU array\n");
            return -1;
        }

        current_size++;
    }

    // Validate integrity of the list
    NetworkPerformanceMetricNode* current = *head;
    while (current) {
        if (!current->timestamp || !current->session_id || !current->measurements ||
            !current->crc_pdu_array) {
            fprintf(stderr, "Data inconsistency found in performance metrics\n");
            return -1;
        }

        // Free the node
        free(current->measurements);
        free(current->crc_pdu_array);

        current = current->next;
    }

    return 0;
}

// Example usage of the functions
int main() {
    NFAPI_CRC_INDICATION_PDU_T* crc_pdu_array = NULL;
    size_t crc_pdu_size = 0;

    if (allocate_and_populate_crc_pdu_array(&crc_pdu_array, &crc_pdu_size, 12345) == 0) {
        printf("Successfully populated CRC PDU array with %zu elements\n", crc_pdu_size);

        NetworkPerformanceMetricNode* perf_metrics_head = NULL;
        if (init_and_populate_performance_metrics(&perf_metrics_head, 10) == 0) {
            printf("Successfully initialized and populated performance metrics\n");
        }
    } else {
        fprintf(stderr, "Failed to allocate and populate CRC PDU array\n");
    }

    // Cleanup
    free(crc_pdu_array);

    return 0;
}
