} TransportBlockManager;

// Function to initialize a new transport block
LTE_UL_TRANSPORTBLOCK_TYPE create_transport_block(int seq_num) {
    LTE_UL_TRANSPORTBLOCK_TYPE block;
    block.encoder.sequence_number = seq_num;

    // Randomly generate block size and modulation scheme
    block.phy_block.block_size = rand() % 1024 + 1; // Example random size
    snprintf(block.phy_block.modulation_scheme, sizeof(block.phy_block.modulation_scheme), "QAM-%d", (rand() % 4) + 2); // Example modulation

    return block;
}

// Function to initialize or expand the transport block manager
int initialize_Uplink_Transport_Block(TransportBlockManager *manager, size_t max_blocks) {
    if (!manager) return -1;

    if (manager->capacity < max_blocks) {
        LTE_UL_TRANSPORTBLOCK_TYPE *new_blocks = realloc(manager->blocks, sizeof(LTE_UL_TRANSPORTBLOCK_TYPE) * max_blocks);
        if (!new_blocks) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            return -2;
        }
        manager->blocks = new_blocks;
        manager->capacity = max_blocks;
    }

    for (size_t i = 0; i < max_blocks; ++i) {
        manager->blocks[i] = create_transport_block(i);
    }
    manager->count = max_blocks;

    return 0;
}

// Function to serialize the transport blocks
int serialize_transport_blocks(const TransportBlockManager *manager, unsigned char **out_data, size_t *out_size) {
    if (!manager || !out_data || !out_size) return -1;

    size_t total_size = sizeof(size_t) + manager->count * (sizeof(TLVEncoder) + sizeof(PHY_Transport_Block));
    *out_data = malloc(total_size);
    if (!*out_data) {
        fprintf(stderr, "Error: Serialization memory allocation failed\n");
        return -2;
    }

    unsigned char *ptr = *out_data;
    memcpy(ptr, &manager->count, sizeof(size_t));
    ptr += sizeof(size_t);

    for (size_t i = 0; i < manager->count; ++i) {
        const LTE_UL_TRANSPORTBLOCK_TYPE *block = &manager->blocks[i];
        memcpy(ptr, &block->encoder, sizeof(TLVEncoder));
        ptr += sizeof(TLVEncoder);
        memcpy(ptr, &block->phy_block, sizeof(PHY_Transport_Block));
        ptr += sizeof(PHY_Transport_Block);
    }

    *out_size = total_size;
    return 0;
}

// Function to deserialize the transport blocks
int deserialize_transport_blocks(const unsigned char *in_data, size_t in_size, TransportBlockManager *manager) {
    if (!in_data || !manager) return -1;

    const unsigned char *ptr = in_data;
    size_t count;
    memcpy(&count, ptr, sizeof(size_t));
    ptr += sizeof(size_t);

    if (count == 0 || in_size != sizeof(size_t) + count * (sizeof(TLVEncoder) + sizeof(PHY_Transport_Block))) {
        fprintf(stderr, "Error: Deserialization data integrity check failed\n");
        return -2;
    }

    manager->blocks = malloc(sizeof(LTE_UL_TRANSPORTBLOCK_TYPE) * count);
    if (!manager->blocks) {
        fprintf(stderr, "Error: Deserialization memory allocation failed\n");
        return -3;
    }

    manager->count = count;
    manager->capacity = count;

    for (size_t i = 0; i < count; ++i) {
        memcpy(&manager->blocks[i].encoder, ptr, sizeof(TLVEncoder));
        ptr += sizeof(TLVEncoder);
        memcpy(&manager->blocks[i].phy_block, ptr, sizeof(PHY_Transport_Block));
        ptr += sizeof(PHY_Transport_Block);
    }

    return 0;
}

// Function to free the transport block manager
void free_transport_block_manager(TransportBlockManager *manager) {
    if (manager && manager->blocks) {
        free(manager->blocks);
        manager->blocks = NULL;
        manager->count = 0;
        manager->capacity = 0;
    }
}
```

### Explanation:

- **Data Structures**: Defined `TLVEncoder`, `PHY_Transport_Block`, and `LTE_UL_TRANSPORTBLOCK_TYPE` to represent the transport block components.
- **Dynamic Array Management**: Used a `TransportBlockManager` struct to manage dynamic arrays, including functions for initialization, expansion, serialization, deserialization, and cleanup.
- **Random Data Generation**: Used `rand()` for generating random sizes and modulation schemes. In practice, ensure proper seeding of `rand()`.
- **Serialization/Deserialization**: Implemented binary format serialization and deserialization with integrity checks.
- **Error Handling**: Added error logging using `stderr` to handle memory allocation failures and data integrity issues.

This code provides a robust starting point for managing LTE uplink transport blocks while considering scalability, performance, and maintainability.']

