#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NUMBERS 10000

typedef struct {
    double timestamp;
    float temperature;
    float error_margin;
} TemperatureMeasurement;

// Mutex for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Log function
void log_message(const char *message) {
    pthread_mutex_lock(&lock);
    fprintf(stderr, "%s\n", message);
    pthread_mutex_unlock(&lock);
}

// Validate temperature measurement
int validate_measurement(float temperature, float error_margin) {
    if (temperature < -273.15 || error_margin <= 0) { // Absolute zero in Celsius and positive error margin
        log_message("Invalid temperature or error margin.");
        return 0;
    }
    return 1;
}

// Function to read numbers from input
int read_numbers(float *buffer, int source_fd, size_t buffer_size) {
    float num;
    int count = 0;

    if (source_fd == -1) { // Standard input
        while (count < buffer_size && scanf("%f", &num) == 1) {
            buffer[count++] = num;
        }
    } else { // File descriptor or network stream
        char line[256];
        ssize_t bytes_read;

        while ((bytes_read = read(source_fd, line, sizeof(line))) > 0) {
            if (count >= buffer_size) break;

            int i = 0;
            while (i < bytes_read && count < buffer_size) {
                sscanf(line + i, "%f", &num);
                buffer[count++] = num;

                // Find the next number
                for (; i < bytes_read; ++i) {
                    if (line[i] == ' ' || line[i] == '\n' || line[i] == EOF) break;
                }
            }
        }

        if (bytes_read < 0) {
            log_message("Failed to read from the file descriptor.");
        }
    }

    return count;
}

// Main function to process temperature measurements
int process_temperatures(TemperatureMeasurement *measurements, int source_fd, double time_start) {
    float buffer[MAX_NUMBERS];
    int num_read = read_numbers(buffer, source_fd, MAX_NUMBERS);

    if (num_read <= 0) {
        log_message("No valid numbers read.");
        return 0;
    }

    int valid_count = 0;
    float total_temperature = 0.0;

    for (int i = 0; i < num_read; ++i) {
        double timestamp = time_start + i * 1.0; // Example: Each measurement is 1 second apart
        if (validate_measurement(buffer[i], buffer[i] * 0.05)) { // Assuming error_margin as 5% of temperature
            pthread_mutex_lock(&lock);
            measurements[valid_count].timestamp = timestamp;
            measurements[valid_count].temperature = buffer[i];
            measurements[valid_count].error_margin = buffer[i] * 0.05; // Example error margin calculation
            pthread_mutex_unlock(&lock);

            total_temperature += buffer[i];
            valid_count++;
        }
    }

    if (valid_count == 0) {
        log_message("No valid temperature measurements found.");
        return 0;
    }

    float average_temperature = total_temperature / valid_count;

    // Log summary
    log_message("Processing complete.");
    printf("Average Temperature: %.2f\n", average_temperature);
    printf("Total Valid Measurements: %d\n", valid_count);

    return valid_count;
}

int main() {
    int source_fd = -1;  // Use -1 for standard input or a valid file descriptor for other sources
    double start_time = 0.0;

    TemperatureMeasurement measurements[MAX_NUMBERS];
    if (process_temperatures(measurements, source_fd, start_time) == 0) {
        log_message("Processing failed.");
    }

    return 0;
}
