#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Session {
    unsigned long user_id;
    char session_token[32];
    time_t creation_timestamp;
    time_t expiration_time;
    struct Session *next;
} Session;

typedef struct {
    Session *head;
    pthread_mutex_t lock;
} SessionList;

SessionList* create_session_list() {
    SessionList *list = malloc(sizeof(SessionList));
    if (list) {
        list->head = NULL;
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

void destroy_session_list(SessionList *list) {
    Session *current = list->head;
    while (current) {
        Session *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_session(SessionList *list, unsigned long user_id, const char *session_token, time_t expiration_duration) {
    pthread_mutex_lock(&list->lock);

    Session *new_session = malloc(sizeof(Session));
    if (!new_session) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    new_session->user_id = user_id;
    strncpy(new_session->session_token, session_token, sizeof(new_session->session_token) - 1);
    new_session->creation_timestamp = time(NULL);
    new_session->expiration_time = new_session->creation_timestamp + expiration_duration;
    new_session->next = list->head;
    list->head = new_session;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_session(SessionList *list, unsigned long user_id) {
    pthread_mutex_lock(&list->lock);

    Session **curr = &list->head;
    while (*curr) {
        Session *entry = *curr;
        if (entry->user_id == user_id) {
            *curr = entry->next;
            free(entry);
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        curr = &entry->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

int remove_session_by_token(SessionList *list, const char *session_token) {
    pthread_mutex_lock(&list->lock);

    Session **curr = &list->head;
    while (*curr) {
        Session *entry = *curr;
        if (strncmp(entry->session_token, session_token, sizeof(entry->session_token)) == 0) {
            *curr = entry->next;
            free(entry);
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
        curr = &entry->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

int extend_session(SessionList *list, const char *session_token, time_t additional_duration) {
    pthread_mutex_lock(&list->lock);

    for (Session *current = list->head; current != NULL; current = current->next) {
        if (strncmp(current->session_token, session_token, sizeof(current->session_token)) == 0) {
            current->expiration_time += additional_duration;
            pthread_mutex_unlock(&list->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

void invalidate_expired_sessions(SessionList *list) {
    time_t now = time(NULL);

    pthread_mutex_lock(&list->lock);

    Session **curr = &list->head;
    while (*curr) {
        Session *entry = *curr;
        if (entry->expiration_time <= now) {
            *curr = entry->next;
            free(entry);
        } else {
            curr = &entry->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void print_sessions(SessionList *list) { // For testing purposes
    pthread_mutex_lock(&list->lock);

    for (Session *current = list->head; current != NULL; current = current->next) {
        printf("User ID: %lu, Token: %s, Expired at: %ld\n",
               current->user_id,
               current->session_token,
               current->expiration_time);
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    SessionList *session_list = create_session_list();

    add_session(session_list, 12345, "token123", 3600); // 1 hour
    print_sessions(session_list);

    extend_session(session_list, "token123", 1800); // Extend by 30 minutes
    invalidate_expired_sessions(session_list);

    remove_session_by_token(session_list, "token123");
    destroy_session_list(session_list);

    return 0;
}
```

### Key Considerations:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure that the session list is accessed in a thread-safe manner.
- **Memory Management**: Frees allocated memory when sessions are removed or during cleanup.
- **Time Handling**: Utilizes standard C time functions for managing timestamps and expiration times.
- **Scalability & Performance**: The linked list structure allows for simple operations, though a more complex data structure (like a hash table) may be needed for high-performance scenarios with very large numbers of sessions.']

