// Structure Definitions
typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Linked List and Synchronization
typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

// Function Prototypes
void initLinkedList(LinkedList* list);
Node* createNode(NFAPI_CRC_INDICATION_PDU_T* pduData);
int validateLinkedList(LinkedList* list);
void freeLinkedList(LinkedList* list);
void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* pduData);
void updateFromExternalSource(LinkedList* list); // Placeholder for external data updates
void serializeLinkedList(const LinkedList* list, const char* filename);
void deserializeLinkedList(LinkedList* list, const char* filename);

// Function Implementations

void initLinkedList(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T* pduData) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->data = *pduData;
    newNode->next = NULL;
    return newNode;
}

int validateLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        if (!current || !current->data.RX_UE_INFORMATION_TAG || !current->data.RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return 0; // Invalid node found
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return 1; // List is valid
}

void freeLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;

    pthread_mutex_unlock(&list->mutex);
}

void insertNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T* pduData) {
    Node* newNode = createNode(pduData);

    if (!newNode) return;

    pthread_mutex_lock(&list->mutex);

    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->mutex);
}

void updateFromExternalSource(LinkedList* list) {
    // Placeholder for implementation
    // This function would fetch updates from an external source and integrate them into the list.
    // Ensure thread safety with mutex locks around critical sections of data manipulation.
}

void serializeLinkedList(const LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    pthread_mutex_lock((pthread_mutex_t*)&list->mutex);

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->mutex);

    fclose(file);
}

void deserializeLinkedList(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    pthread_mutex_lock(&list->mutex);

    // Clear existing data
    freeLinkedList(list);

    NFAPI_CRC_INDICATION_PDU_T pduData;
    while (fread(&pduData, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        insertNode(list, &pduData);
    }

    pthread_mutex_unlock(&list->mutex);

    fclose(file);
}

// Main for Testing
