    LinkedList list;
    initLinkedList(&list);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pduExample = {1, 1000, {.CRCFLAG = rand() % 2}};
    insertNode(&list, &pduExample);

    if (validateLinkedList(&list)) {
        printf("List is valid\n");
    }

    serializeLinkedList(&list, "linked_list.dat");
    freeLinkedList(&list);

    initLinkedList(&list); // Reinitialize before deserialization
    deserializeLinkedList(&list, "linked_list.dat");

    freeLinkedList(&list);

    return 0;
}
