// Cache to minimize memory allocations and deallocations
LTE_DL_CCCH_Message_Type1_T cache[CACHE_SIZE];
int cache_start = 0;
int cache_end = -1;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_info(const char* message) {
    printf("Info: %s\n", message);
}

LTE_DL_CCCH_Message_Type1_T* get_from_cache() {
    if (cache_start <= cache_end) {
        return &cache[cache_start++];
    }
    return NULL;
}

void release_to_cache(LTE_DL_CCCH_Message_Type1_T* item) {
    cache[++cache_end] = *item;
}

LTE_DL_CCCH_Message_Type1_T** initialize_messages(int num_elements, int* actual_count) {
    if (num_elements <= 0 || num_elements > MAX_ELEMENTS) {
        log_error("Invalid number of elements requested.");
        return NULL;
