    LTE_DL_CCCH_Message_Type1_T** messages = malloc(num_elements * sizeof(LTE_DL_CCCH_Message_Type1_T*));
    if (!messages) {
        log_error("Memory allocation failed for message pointers.");
        return NULL;
    }

    int initialized_count = 0;
    while (initialized_count < num_elements) {
        LTE_DL_CCCH_Message_Type1_T* item = get_from_cache();
        if (!item) {
            item = malloc(sizeof(LTE_DL_CCCH_Message_Type1_T));
