        snprintf(item->nas_message.content, sizeof(item->nas_message.content), "Message Content %d", item->nas_message.message_type);

        messages[initialized_count++] = item;
    }

    *actual_count = initialized_count;

    log_info("Messages initialized successfully.");
    return messages;
}

void deallocate_messages(LTE_DL_CCCH_Message_Type1_T** messages, int count) {
    for (int i = 0; i < count; ++i) {
        if (messages[i]) {
            release_to_cache(messages[i]);
            free(messages[i]); // Ensure the structure is freed
        }
    }
}

