#include <stdbool.h>
#include <string.h>

#define MAX_ALLOC_LIMIT 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    union {
        struct { 
            unsigned char CRCFLAG:1; // Additional fields can be added here
        } REL8;
        struct { 
            unsigned char CRCFLAG:1; // Additional fields can be added here
        } REL15;
    };
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

bool isValidRXUEInformationTag(int tag) {
    // Define valid range for RX_UE_INFORMATION_TAG
    return tag >= 0 && tag <= 100; // Example range
}

bool isValidRNTI(int rnti) {
    // Define valid range for RNTI
    return rnti >= 1 && rnti <= 65535; // Example range
}

void log_message(const char *message) {
    printf("%s\n", message);
}

DynamicArray* createDynamicArray(size_t initial_capacity) {
    if (initial_capacity > MAX_ALLOC_LIMIT) {
        log_message("Initial capacity exceeds maximum allocation limit.");
        return NULL;
    }

    DynamicArray *dynArray = malloc(sizeof(DynamicArray));
    if (!dynArray) {
        log_message("Failed to allocate memory for DynamicArray structure.");
        return NULL;
    }

    dynArray->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynArray->array) {
        free(dynArray);
        log_message("Failed to allocate initial array of structures.");
        return NULL;
    }

    pthread_mutex_init(&dynArray->lock, NULL);
    dynArray->capacity = initial_capacity;
    dynArray->count = 0;

    log_message("Dynamic array created successfully.");

    return dynArray;
}

bool addStructure(DynamicArray *dynArray, int type) {
    pthread_mutex_lock(&dynArray->lock);

    if (dynArray->count >= dynArray->capacity) {
        size_t new_capacity = dynArray->capacity < MAX_ALLOC_LIMIT ? 
                              2 * dynArray->capacity : MAX_ALLOC_LIMIT;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(dynArray->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&dynArray->lock);
            log_message("Failed to reallocate memory for additional structures.");
            return false;
        }

        dynArray->array = new_array;
        dynArray->capacity = new_capacity;

        log_message("Memory reallocated successfully.");
    }

    NFAPI_CRC_INDICATION_PDU_T *new_entry = &dynArray->array[dynArray->count];
    int tag = rand() % 101; // Random tag for demonstration
    int rnti = (rand() % 65535) + 1; // Random RNTI

    if (!isValidRXUEInformationTag(tag) || !isValidRNTI(rnti)) {
        pthread_mutex_unlock(&dynArray->lock);
        log_message("Invalid RX_UE_INFORMATION_TAG or RNTI generated.");
        return false;
    }

    new_entry->RX_UE_INFORMATION_TAG = tag;
    new_entry->RNTI = rnti;

    if (type == 8) {
        new_entry->REL8.CRCFLAG = rand() % 2;
    } else if (type == 15) {
        new_entry->REL15.CRCFLAG = rand() % 2;
    }

    dynArray->count++;
    pthread_mutex_unlock(&dynArray->lock);

    return true;
}

void freeDynamicArray(DynamicArray *dynArray) {
    pthread_mutex_lock(&dynArray->lock);

    if (dynArray && dynArray->array) {
        free(dynArray->array);
        dynArray->array = NULL;
    }

    pthread_mutex_unlock(&dynArray->lock);
    pthread_mutex_destroy(&dynArray->lock);

    free(dynArray);
}

void printStats(DynamicArray *dynArray) {
    pthread_mutex_lock(&dynArray->lock);

    printf("Current number of structures: %zu\n", dynArray->count);
    printf("Available slots for future allocations: %zu\n", dynArray->capacity - dynArray->count);

    pthread_mutex_unlock(&dynArray->lock);
}

// Example usage
int main() {
    DynamicArray *dynArray = createDynamicArray(10);

    if (dynArray) {
        addStructure(dynArray, 8); // Add REL8 type structure
        addStructure(dynArray, 15); // Add REL15 type structure

        printStats(dynArray);

        freeDynamicArray(dynArray);
    }

    return 0;
}
