```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define INITIAL_CAPACITY 10

typedef struct MAC_FRAME {
    // Define the structure fields as needed.
} MAC_FRAME;

typedef struct LMAC_CONFIG {
    // Define the configuration fields as needed.
} LMAC_CONFIG;

typedef struct MAC_CONTEXT_T {
    LMAC_CONFIG config;
    MAC_FRAME* frames;
    size_t frame_count;
    size_t frame_capacity;
} MAC_CONTEXT_T;

typedef struct MAC_CONTEXT_POOL {
    MAC_CONTEXT_T* contexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Fine-grained locking for thread safety
} MAC_CONTEXT_POOL;

MAC_CONTEXT_POOL* create_context_pool() {
    MAC_CONTEXT_POOL* pool = (MAC_CONTEXT_POOL*)malloc(sizeof(MAC_CONTEXT_POOL));
    if (!pool) return NULL;

    pool->contexts = (MAC_CONTEXT_T*)calloc(INITIAL_CAPACITY, sizeof(MAC_CONTEXT_T));
    if (!pool->contexts) {
        free(pool);
        return NULL;
    }

    pool->capacity = INITIAL_CAPACITY;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

int add_mac_context(MAC_CONTEXT_POOL* pool, LMAC_CONFIG config) {
    if (!pool) return -1;

    pthread_mutex_lock(&pool->lock);

    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        MAC_CONTEXT_T* new_contexts = (MAC_CONTEXT_T*)realloc(pool->contexts, new_capacity * sizeof(MAC_CONTEXT_T));
        if (!new_contexts) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Memory allocation failure
        }
        pool->contexts = new_contexts;
        pool->capacity = new_capacity;
    }

    MAC_CONTEXT_T* context = &pool->contexts[pool->count++];
    context->config = config;
    context->frames = NULL;
    context->frame_count = 0;
    context->frame_capacity = 0;

    pthread_mutex_unlock(&pool->lock);

    return 0; // Success
}

void free_mac_context_pool(MAC_CONTEXT_POOL* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->contexts[i].frames) {
            free(pool->contexts[i].frames);
        }
    }

    free(pool->contexts);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

// Example function to demonstrate logging integration
void log_context_operation(const char* operation, size_t index) {
    // Integrate with an external logging system here.
    printf("Operation: %s on context at index %zu\n", operation, index);
}

int main() {
    MAC_CONTEXT_POOL* pool = create_context_pool();
    if (!pool) return 1;

    LMAC_CONFIG config;
    // Initialize the config as needed.

    if (add_mac_context(pool, config) != 0) {
        fprintf(stderr, "Failed to add MAC context.\n");
        free_mac_context_pool(pool);
        return 1;
    }

    log_context_operation("Add", 0);

    free_mac_context_pool(pool);

    return 0;
}
```

