['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

#define MAX_PACKETS 15000
#define MAX_STORED_PACKETS 3000
#define MAX_SERVICES 150

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
    int unique_header_flag; // for critical packets
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PacketNode {
    NFAPI_CRC_INDICATION_PDU_T packet;
    struct PacketNode* next;
} PacketNode;

typedef struct ServiceRecord {
    long offset[MAX_PACKETS];
    int key[MAX_PACKETS];
    int value;
} ServiceRecord;

typedef struct ServiceInstance {
    int service_id;
    pthread_t thread;
    struct {
        ServiceRecord records[MAX_PACKETS];
    } service_data;
    int active;
} ServiceInstance;

PacketNode* head = NULL;
pthread_mutex_t packetMutex = PTHREAD_MUTEX_INITIALIZER;
int max_payload_size = 0, critical_packets_handled = 0;
long total_processing_time = 0;

void free_packet_list() {
    PacketNode *current = head, *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

int add_packet(NFAPI_CRC_INDICATION_PDU_T packet) {
    pthread_mutex_lock(&packetMutex);

    if (!head || !packet.RX_UE_INFORMATION_TAG || packet.RNTI <= 0 || packet.RNTI > MAX_PACKETS) {
        pthread_mutex_unlock(&packetMutex);
        return -1; // invalid packet
    }

    PacketNode* new_node = (PacketNode*)malloc(sizeof(PacketNode));
    if (!new_node) {
        pthread_mutex_unlock(&packetMutex);
        return -2; // memory allocation failed
    }

    memcpy(&(new_node->packet), &packet, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = head;
    head = new_node;

    int current_count = 0;
    PacketNode* temp = head;
    while (temp && current_count < MAX_STORED_PACKETS) {
        if (temp->packet.CRCFLAG) { // assuming CRCFLAG indicates payload size
            if (temp->packet.CRC_INDICATION_REL8_TAG > max_payload_size) {
                max_payload_size = temp->packet.CRC_INDICATION_REL8_TAG;
            }
        }
        current_count++;
        temp = temp->next;
    }

    critical_packets_handled += packet.unique_header_flag;

    pthread_mutex_unlock(&packetMutex);
    return 0; // success
}

void* service_simulation(void* arg) {
    ServiceInstance *service = (ServiceInstance*)arg;

    srand(time(NULL) + service->service_id); // unique seed per thread

    for (int i = 0; i < MAX_PACKETS; ++i) {
        service->service_data.records[i].value = rand() % 100; // random value between 0 and 99
        service->service_data.offset[i] = rand() % 1000;
        service->service_data.key[i] = rand() % 10;

        usleep((rand() % 150 + 50) * 1000); // delay from 50ms to 200ms

        if (!service->active) {
            printf("Service %d stopped at time %ld\n", service->service_id, time(NULL));
            break;
        }
    }

    return NULL;
}

int start_services(int num_services) {
    ServiceInstance *services = (ServiceInstance*)malloc(num_services * sizeof(ServiceInstance));

    if (!services) return -1;

    for (int i = 0; i < num_services && i < MAX_SERVICES; ++i) {
        services[i].service_id = i + 1;
        services[i].active = 1;

        if (pthread_create(&services[i].thread, NULL, service_simulation, &services[i])) {
            printf("Failed to create thread for Service %d\n", i + 1);
            free(services);
            return -2;
        }
    }

    sleep(5); // simulate runtime

    for (int i = 0; i < num_services && i < MAX_SERVICES; ++i) {
        services[i].active = 0;
        pthread_join(services[i].thread, NULL);
    }

    free(services);
    return 0;
}

void process_packets(int num_packets) {
    for (int i = 0; i < num_packets && i < MAX_PACKETS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T packet;
        // populate packet data, e.g., rand() functions
        packet.RX_UE_INFORMATION_TAG = rand() % 100;
        packet.RNTI = rand() % MAX_PACKETS + 1;
        packet.CRC_INDICATION_REL8_TAG = rand() % 256;
        packet.CRCFLAG = (rand() % 2 == 0);
        packet.unique_header_flag = (rand() % 10 == 0);

        clock_t start_time = clock();
        add_packet(packet);
        total_processing_time += clock() - start_time;
    }
}

int main() {
    process_packets(15000); // simulate receiving packets

    int services = 150; // number of concurrent service instances
    if (start_services(services) != 0) {
        printf("Error starting services\n");
        return -1;
    }

    free_packet_list();

    printf("Critical Packets Handled: %d\n", critical_packets_handled);
    printf("Max Payload Size: %d\n", max_payload_size);
    printf("Average Processing Time per Packet: %.2f ms\n",
           (float)total_processing_time / CLOCKS_PER_SEC * 1000.0 / MAX_PACKETS);

    return 0;
}
```

