pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Record *cache[MAX_ELEMENTS];
int cache_size = 0;
int active_elements = 0;

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

NFAPI_CRC_INDICATION_PDU_T create_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand() % 1000 + 1; // Example range
    pdu.RNTI = rand() % 1000 + 1;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    return pdu;
}

Record *get_cache_record(int key) {
    for (int i = 0; i < cache_size; ++i) {
        if (cache[i]->key == key) {
            log_message("Cache hit");
            return cache[i];
        }
    }
    return NULL;
}

void add_to_cache(Record *record) {
    pthread_mutex_lock(&lock);
    if (cache_size < MAX_ELEMENTS) {
        cache[cache_size++] = record;
        log_message("Added to cache");
    } else {
        // Implement a cache eviction policy here
        free(cache[0]);
        memmove(&cache[0], &cache[1], sizeof(Record*) * (--cache_size));
        cache[cache_size] = record;
        log_message("Evicted and added to cache");
    }
    pthread_mutex_unlock(&lock);
}

void init_cache() {
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        cache[i] = NULL;
    }
}

Record *allocate_and_initialize_record(long offset, int key) {
    Record *record = malloc(sizeof(Record));
    if (!record) {
        log_message("Memory allocation failed");
        return NULL;
    }

    record->offset = offset;
    record->key = key;
    record->record = create_random_pdu();

    pthread_mutex_lock(&lock);
    active_elements++;
    pthread_mutex_unlock(&lock);

    add_to_cache(record);
    return record;
}

void free_record(Record *record) {
    if (record) {
        pthread_mutex_lock(&lock);
        active_elements--;
        pthread_mutex_unlock(&lock);
        free(record);
    }
}

void cleanup() {
    for (int i = 0; i < cache_size; ++i) {
        free(cache[i]);
    }
    pthread_mutex_destroy(&lock);
    closelog();
}

void *worker_thread(void *arg) {
    long offset = (long)arg;
    int key = rand() % MAX_ELEMENTS + 1;

    Record *record = get_cache_record(key);
    if (!record) {
        record = allocate_and_initialize_record(offset, key);
    }

    // Simulate work
    usleep(1000);

    free_record(record);
    return NULL;
}

void start_concurrent_processing(int num_threads) {
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, worker_thread, (void *)(long)i)) {
            log_message("Thread creation failed");
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}

int main() {
    openlog("NFAPI_CRC_INDICATION", LOG_PID | LOG_CONS, LOG_USER);
    init_cache();

    start_concurrent_processing(10);

    cleanup();
    return 0;
}
