    ContextArray *array = malloc(sizeof(ContextArray));
    array->contexts = malloc(INITIAL_SIZE * sizeof(GPRS_PDP_Context));
    array->capacity = INITIAL_SIZE;
    atomic_store(&array->count, 0);
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resize_context_array(ContextArray *array) {
    size_t new_capacity = array->capacity * 2;
    if (new_capacity > MAX_PACKETS) new_capacity = MAX_PACKETS;

    GPRS_PDP_Context *new_contexts = realloc(array->contexts, new_capacity * sizeof(GPRS_PDP_Context));
    if (!new_contexts) return; // Handle error appropriately

    array->contexts = new_contexts;
    array->capacity = new_capacity;
}

void add_context(ContextArray *array, size_t payload_size) {
    pthread_mutex_lock(&array->lock);

    while (atomic_load(&array->count) >= array->capacity) {
        resize_context_array(array);
    }

    GPRS_PDP_Context context;
    // Initialize TLVEncoder here
    unsigned int packet_id = rand();
    char *payload = malloc(payload_size);
    if (!payload) return; // Handle error appropriately

    context.packet.id = packet_id;
    context.packet.payload = payload;

    size_t index = atomic_fetch_add(&array->count, 1);
    array->contexts[index] = context;

    pthread_mutex_unlock(&array->lock);
}

void remove_context(ContextArray *array, unsigned int packet_id) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < atomic_load(&array->count); ++i) {
        if (array->contexts[i].packet.id == packet_id) {
            free(array->contexts[i].packet.payload);
            array->contexts[i] = array->contexts[--atomic_fetch_sub(&array->count, 1)];
            break;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

