// Initialize memory pool
MemoryPool* init_memory_pool(size_t size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        log_error("Failed to allocate memory for the pool");
        return NULL;
    }

    pool->pool = malloc(size);
    if (!pool->pool) {
        free(pool);
        log_error("Failed to allocate memory for the pool's data");
        return NULL;
    }

    pool->current_offset = 0;
    pool->total_size = size;
    pthread_mutex_init(&pool->lock, NULL);

    log_info("Memory pool initialized successfully");
    return pool;
}

// Allocate from memory pool
void* pool_alloc(MemoryPool *pool, size_t size) {
    pthread_mutex_lock(&pool->lock);

    if (pool->current_offset + size > pool->total_size) {
        // Pool is full, need to resize or fail
        pthread_mutex_unlock(&pool->lock);
        log_error("Memory pool exhausted");
        return NULL;
    }

    void *ptr = (char*)pool->pool + pool->current_offset;
    pool->current_offset += size;

    pthread_mutex_unlock(&pool->lock);
    return ptr;
}

// Free memory pool
void free_memory_pool(MemoryPool *pool) {
    if (!pool) return;

    if (pool->pool) free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);

    log_info("Memory pool freed successfully");
}

