    int *keys = (int*)pool_alloc(pool, key_count * sizeof(int));
    Record *records = (Record*)pool_alloc(pool, record_count * sizeof(Record));

    if (!offsets || !keys || !records) {
        free_memory_pool(pool);
        log_error("Failed to allocate memory for structures");
        return -1;
    }

    // Initialize offset array
