    int key;
    long offset;
    struct Record *next; // For chaining in hash table
} Record;

typedef struct Database {
    Record **table;
    size_t table_size;
    size_t count;
    pthread_mutex_t lock;
} Database;

// Hash function
unsigned long hash(int key, size_t table_size) {
    return (unsigned long)key % table_size;
}

// Initialize the database
Database* init_db() {
    Database *db = malloc(sizeof(Database));
    if (!db) return NULL;

    db->table_size = INITIAL_TABLE_SIZE;
    db->count = 0;
    db->table = calloc(db->table_size, sizeof(Record*));
    if (!db->table) {
        free(db);
        return NULL;
    }

    pthread_mutex_init(&db->lock, NULL);

    return db;
}

// Resize the hash table
void resize_table(Database *db) {
    size_t old_size = db->table_size;
    Record **old_table = db->table;

    db->table_size *= 2;
    db->table = calloc(db->table_size, sizeof(Record*));
    if (!db->table) return; // Handle allocation failure gracefully

    for (size_t i = 0; i < old_size; i++) {
        Record *record = old_table[i];
        while (record) {
            Record *next = record->next;
            unsigned long new_index = hash(record->key, db->table_size);
            record->next = db->table[new_index];
            db->table[new_index] = record;
            record = next;
        }
    }

    free(old_table);
}

// Insert a record
void insert_record(Database *db, int key, long offset) {
    pthread_mutex_lock(&db->lock);

    if ((float)db->count / db->table_size > 0.75) {
        resize_table(db);
    }

    unsigned long index = hash(key, db->table_size);
    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    record->next = db->table[index];
    db->table[index] = record;

    db->count++;
    pthread_mutex_unlock(&db->lock);
}

// Delete a record
void delete_record(Database *db, int key) {
    pthread_mutex_lock(&db->lock);

    unsigned long index = hash(key, db->table_size);
    Record *record = db->table[index];
    Record *prev = NULL;

    while (record) {
        if (record->key == key) {
            if (prev) {
                prev->next = record->next;
            } else {
                db->table[index] = record->next;
            }
            free(record);
            db->count--;
            break;
        }
        prev = record;
        record = record->next;
    }

    pthread_mutex_unlock(&db->lock);
}

// Retrieve a record
Record* get_record(Database *db, int key) {
    unsigned long index = hash(key, db->table_size);
    Record *record = db->table[index];

    while (record) {
        if (record->key == key) {
            return record;
        }
        record = record->next;
    }

    return NULL;
}

// Clean up the database
void free_db(Database *db) {
    pthread_mutex_lock(&db->lock);

    for (size_t i = 0; i < db->table_size; i++) {
        Record *record = db->table[i];
        while (record) {
            Record *next = record->next;
            free(record);
            record = next;
        }
    }

    free(db->table);
    pthread_mutex_unlock(&db->lock);
    pthread_mutex_destroy(&db->lock);

    free(db);
}

// Example usage
int main() {
    Database *db = init_db();
    if (!db) return 1;

    insert_record(db, 1, 1000);
    insert_record(db, 2, 2000);

    Record *record = get_record(db, 1);
    if (record) printf("Key: %d, Offset: %ld\n", record->key, record->offset);

    delete_record(db, 1);
    free_db(db);

    return 0;
}
```']

