    size_t count;
    size_t capacity;
    threading.Lock lock;
} CRC_Indication_Pool;

void log_message(int level, const char *message) {
    if (level <= current_log_level) {
        printf("%s\n", message);
    }
}

CRC_Indication_Pool* create_pool(size_t N, int log_level) {
    static CRC_Indication_Pool global_pool = {NULL, 0, 0, threading.Lock()};
    CRC_Indication_Pool* pool = &global_pool;
    current_log_level = log_level;

    if (N > MAX_POOL_SIZE || N == 0) {
        char error_msg[100];
        snprintf(error_msg, sizeof(error_msg), "Invalid request: %zu structures requested. Max size is %d.", N, MAX_POOL_SIZE);
        log_message(LOG_LEVEL_ERROR, error_msg);
        return NULL;
    }

    pool->lock.acquire();

    if (pool->count >= pool->capacity) {
        size_t new_capacity = (N > MAX_POOL_SIZE ? MAX_POOL_SIZE : N);
        NFAPI_CRC_INDICATION_PDU_T* new_pool = realloc(pool->pool, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);

        if (!new_pool) {
            log_message(LOG_LEVEL_ERROR, "Memory allocation failed.");
            pool->lock.release();
            return NULL;
        }

        for (size_t i = pool->count; i < new_capacity; ++i) {
            new_pool[i].RX_UE_INFORMATION_TAG = rand() % 10000; // Example initialization
            new_pool[i].RNTI = rand() % 10000;
            new_pool[i].CRC_INDICATION_REL8_TAG = rand() % 10000;
            new_pool[i].CRCFLAG = rand() % 2 == 0;

            if (rand() % 10 < 1) { // Simulate an initialization error
                log_message(LOG_LEVEL_ERROR, "Initialization error at index: %zu", i);
                pool->lock.release();
                free(new_pool);
                return NULL;
            }
        }

        pool->pool = new_pool;
        pool->capacity = new_capacity;
    }

    char info_msg[100];
    snprintf(info_msg, sizeof(info_msg), "%zu structures allocated. Current usage: %zu/%zu", N, pool->count + N, pool->capacity);
    log_message(LOG_LEVEL_INFO, info_msg);

    pool->lock.release();
    return pool;
}

void destroy_pool(CRC_Indication_Pool* pool) {
    if (pool && pool->pool) {
        free(pool->pool);
        pool->pool = NULL;
        pool->count = 0;
        pool->capacity = 0;
    }
}
