// Function to initialize the array of TCP_SOCKET_STATE structures
TCP_SOCKET_STATE* initialize_socket_states(int N) {
    if (N <= 0) {
        fprintf(stderr, "Error: Number of socket states must be positive.\n");
        return NULL;
    }

    // Allocate memory for the array.
    TCP_SOCKET_STATE *socket_states = (TCP_SOCKET_STATE*) malloc(N * sizeof(TCP_SOCKET_STATE));
    if (!socket_states) {
        perror("Memory allocation failed for socket states");
        return NULL;
