sensor_record* initialize_sensor_records(size_t num_sensors, float min_temp, float max_temp,
                                         char ***sensor_ids) {
    if (num_sensors == 0 || sensor_ids == NULL) return NULL;

    // Dynamically allocate memory for sensor records and IDs
    sensor_record *records = malloc(num_sensors * sizeof(sensor_record));
    if (!records) return NULL;

    *sensor_ids = malloc(num_sensors * sizeof(char *));
    if (!(*sensor_ids)) {
        free(records);
        return NULL;
    }

    // Initialize sensor records and allocate memory for sensor IDs
    for (size_t i = 0; i < num_sensors; ++i) {
        pthread_mutex_lock(&lock);  // Lock for thread-safe initialization

        (*sensor_ids)[i] = malloc(16 * sizeof(char));  // Allocate enough space for ID format "SensorXXXX"
        if (!(*sensor_ids)[i]) {
            while (i > 0) {  // Free already allocated IDs and records
                free((*sensor_ids)[--i]);
            }
            free(records);
            free(*sensor_ids);
            return NULL;
        }

        snprintf((*sensor_ids)[i], 16, "Sensor%04zu", i + 1);  // Generate unique ID

        records[i].timestamp = 0;  // Initialize timestamp
        records[i].temperature_reading = (min_temp + max_temp) / 2.0f;  // Initialize with average of range

        pthread_mutex_unlock(&lock);
    }

    return records;
}

