#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 2 * 1024 * 1024 * 1024 // 2 GB
#define MAX_ELEMENTS 1000000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock; // Mutex for thread safety
    size_t memory_used;
} CRCList;

CRCList crc_list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

void initialize_structure(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand(); // Example tag initialization
    pdu->RNTI = (uint16_t)rand();
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu->CRCFLAG = rand() & 1; // Randomly set CRCFLAG
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void log_system_resources() {
    // Implement resource logging logic here
    // Example: printf("Memory used: %zu bytes\n", crc_list.memory_used);
}

int add_crc_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&crc_list.lock);

    if (crc_list.memory_used + sizeof(Node) > MAX_MEMORY_USAGE) {
        pthread_mutex_unlock(&crc_list.lock);
        return -1; // Out of memory
    }

    Node* new_node = create_node(pdu);
    if (!new_node) {
        pthread_mutex_unlock(&crc_list.lock);
        return -1;
    }

    new_node->next = crc_list.head;
    crc_list.head = new_node;
    crc_list.memory_used += sizeof(Node);

    pthread_mutex_unlock(&crc_list.lock);
    return 0;
}

void reclaim_memory() {
    pthread_mutex_lock(&crc_list.lock);

    Node* current = crc_list.head;
    Node* prev = NULL;

    while (current) {
        if (/* condition to determine stale entry */) {
            if (prev) {
                prev->next = current->next;
            } else {
                crc_list.head = current->next;
            }
            crc_list.memory_used -= sizeof(Node);
            free(current);
            current = (prev ? prev->next : crc_list.head);
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&crc_list.lock);
}

void* monitor_resources(void* arg) {
    while (1) {
        log_system_resources();
        reclaim_memory();
        sleep(5); // Adjust the frequency as needed
    }
    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t resource_thread;
    pthread_create(&resource_thread, NULL, monitor_resources, NULL);

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        initialize_structure(&pdu);
        if (add_crc_pdu(pdu) != 0) {
            printf("Failed to add CRC PDU\n");
            break;
        }
    }

    pthread_join(resource_thread, NULL);
    return 0;
}
```

### Key Points:
- **Concurrency**: A mutex is used for thread safety.
- **Memory Management**: Memory usage is tracked and limited to 2 GB. Nodes are freed when deemed stale.
- **Resource Monitoring**: A separate thread logs resource usage and reclaims memory periodically.
- **Graceful Handling**: The function returns an error code if memory allocation fails, allowing the application to handle it gracefully.']

