#define MAX_CACHE_SIZE 100
#define RATE_LIMIT 1000

// Global variables for caching and rate limiting
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t can_proceed = PTHREAD_COND_INITIALIZER;
int message_cache[MAX_CACHE_SIZE];
int cache_usage = 0;
int processed_messages = 0;
time_t last_processed_time;

typedef struct {
    int thread_id;
    time_t timestamp;
    char error_detail[256];
} LogEntry;

