void evict_from_cache();
int generate_random_message_type();
void fetch_nas_message_content(NAS_Message *nas_message);

void process_CCCH_and_CRC_PDU(LTE_DL_CCCH_Message_Type1_T *messages, int num_messages, NFAPI_CRC_INDICATION_PDU_T **output_pdu_list) {
    if (!messages || !num_messages || !output_pdu_list) {
        log_error("Invalid input parameters");
        return;
    }

    // Allocate memory for output PDUs
    *output_pdu_list = malloc(num_messages * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*output_pdu_list) {
        log_error("Memory allocation failed for output PDU list");
        return;
    }

    pthread_t thread_id = pthread_self();
    time(&last_processed_time);

    for (int i = 0; i < num_messages; ++i) {
        // Rate limiting
        while ((time(NULL) - last_processed_time) * 1000 < 1000 / RATE_LIMIT) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            ts.tv_sec += 1;
            pthread_cond_timedwait(&can_proceed, &cache_lock, &ts);
