        (*output_pdu_list)[i].tag.rnti = rand(); // Replace with actual logic
        (*output_pdu_list)[i].tag.crcflag = rand() % 2; // Randomly set CRCFLAG

        // Logging
        LogEntry log_entry;
        log_entry.thread_id = thread_id;
        time(&log_entry.timestamp);
        snprintf(log_entry.error_detail, sizeof(log_entry.error_detail), "Processed message type: %d", messages[i].nas_message.message_type);
        log_error(log_entry.error_detail);

        // Cache management
        pthread_mutex_lock(&cache_lock);
        if (cache_usage >= MAX_CACHE_SIZE) {
            evict_from_cache();
        }
        message_cache[cache_usage++] = i; // Store index or some identifier
        processed_messages++;
        last_processed_time = time(NULL);
        pthread_cond_signal(&can_proceed);
        pthread_mutex_unlock(&cache_lock);
    }

    log_error("Completed processing of all messages");
}

void evict_from_cache() {
