#define INITIAL_ARRAY_SIZE 10
#define MAX_CACHE_SIZE 100

typedef struct {
    int sequence_number;
    char nas_message_type[20];
    char nas_message_content[256];
} NAS_Message;

typedef struct {
    NAS_Message *nas_message;
