    unsigned int rnti;
    unsigned char crcflag;
    LTE_DL_CCCH_Message_Type1_T message;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheEntry {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    time_t last_accessed;
    int access_count;
    struct CacheEntry *next;
} CacheEntry;

typedef struct {
    CacheEntry *head;
    pthread_mutex_t lock;
    int size;
} MessageCache;

MessageCache cache = {NULL, PTHREAD_MUTEX_INITIALIZER, 0};

void log_error(const char *message) {
    time_t now = time(NULL);
    fprintf(stderr, "[%ld] ERROR: %s\n", (long)now, message);
}

int generate_random_crcflag() {
    return rand() & 1;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int sequence_number, const char *nas_message_type, const char *nas_message_content) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        log_error("Failed to allocate memory for PDU");
        return NULL;
    }

    pdu->rx_ue_information_tag = rand(); // Example generation
    pdu->rnti = rand() % 1000; // Example RNTI generation
    pdu->crcflag = generate_random_crcflag();

    pdu->message.nas_message = malloc(sizeof(NAS_Message));
    if (!pdu->message.nas_message) {
        log_error("Failed to allocate memory for NAS Message");
        free(pdu);
        return NULL;
    }

    pdu->message.nas_message->sequence_number = sequence_number;
    strncpy(pdu->message.nas_message->nas_message_type, nas_message_type, sizeof(pdu->message.nas_message->nas_message_type) - 1);
    strncpy(pdu->message.nas_message->nas_message_content, nas_message_content, sizeof(pdu->message.nas_message->nas_message_content) - 1);

    return pdu;
}

void add_to_cache(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&cache.lock);

    if (cache.size >= MAX_CACHE_SIZE) {
        // Evict the least frequently accessed entry
        CacheEntry *current = cache.head, *prev = NULL, *least_frequent = NULL;

        while (current) {
            if (!least_frequent || current->access_count < least_frequent->access_count) {
                least_frequent = current;
            }
            prev = current;
            current = current->next;
        }

        if (least_frequent) {
            if (prev) {
                prev->next = least_frequent->next;
            } else {
                cache.head = least_frequent->next;
            }
            free(least_frequent->pdu);
            free(least_frequent);
            cache.size--;
        }
    }

    CacheEntry *entry = malloc(sizeof(CacheEntry));
    if (!entry) {
        log_error("Failed to allocate memory for cache entry");
        pthread_mutex_unlock(&cache.lock);
        return;
    }

    entry->pdu = pdu;
    entry->last_accessed = time(NULL);
    entry->access_count = 1;
    entry->next = cache.head;
    cache.head = entry;
    cache.size++;

    pthread_mutex_unlock(&cache.lock);
}

void* populate_CRC_INDICATION_and_DL_CCCH_Messages(void *arg) {
    int *array_size_ptr = (int *)arg;
    NFAPI_CRC_INDICATION_PDU_T **pdu_array = malloc(*array_size_ptr * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (!pdu_array) {
        log_error("Failed to allocate memory for PDU array");
        return NULL;
    }

    pthread_t current_thread_id = pthread_self();

    for (int i = 0; i < *array_size_ptr; ++i) {
        char nas_message_type[20];
        snprintf(nas_message_type, sizeof(nas_message_type), "Type%d", rand() % 10);

        NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(i, nas_message_type, "Sample NAS Message Content");
        if (!pdu) {
            log_error("Failed to create PDU");
            continue;
        }

        pdu_array[i] = pdu;
        add_to_cache(pdu);

        printf("[%ld][Thread %lu] Created PDU with sequence number: %d\n", (long)time(NULL), (unsigned long)current_thread_id, i);
    }

    return pdu_array;
}

void free_pdu_array(NFAPI_CRC_INDICATION_PDU_T **pdu_array, int array_size) {
    for (int i = 0; i < array_size; ++i) {
        if (pdu_array[i]) {
            free(pdu_array[i]->message.nas_message);
            free(pdu_array[i]);
        }
    }
    free(pdu_array);
}

void cleanup_cache() {
    pthread_mutex_lock(&cache.lock);

    CacheEntry *current = cache.head, *next;
    while (current) {
        next = current->next;
        free(current->pdu);
        free(current);
        current = next;
    }

    cache.head = NULL;
    cache.size = 0;

    pthread_mutex_unlock(&cache.lock);
}

int main() {
    srand(time(NULL));

    int array_size = INITIAL_ARRAY_SIZE;
    NFAPI_CRC_INDICATION_PDU_T **pdu_array = populate_CRC_INDICATION_and_DL_CCCH_Messages(&array_size);

    if (pdu_array) {
        // Use pdu_array as needed
        free_pdu_array(pdu_array, array_size);
    }

    cleanup_cache();

    return 0;
}
```

