#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Entry {
    long timestamp;
    int status_code;
    char* message;
} Entry;

typedef struct Node {
    Entry entry;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
    size_t max_entries;
    time_t expiry_duration;
} List;

List* create_list(size_t max_entries, time_t expiry_duration) {
    List* list = malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->max_entries = max_entries;
    list->expiry_duration = expiry_duration;

    return list;
}

void destroy_list(List* list);

Entry create_entry(long timestamp, int status_code, const char* message) {
    Entry entry;
    entry.timestamp = timestamp;
    entry.status_code = status_code;
    entry.message = strdup(message);
    return entry;
}

void add_entry(List* list, Entry new_entry) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->max_entries) {
        // Remove expired entries or evict the oldest to make room
        Node** current = &list->head;
        while (*current && ((*current)->entry.timestamp + list->expiry_duration < time(NULL))) {
            Node* to_delete = *current;
            *current = (*current)->next;
            free(to_delete->entry.message);
            free(to_delete);
            list->count--;
        }
    }

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->entry = new_entry;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    // Log addition
    printf("Added entry: timestamp=%ld, status_code=%d\n", new_entry.timestamp, new_entry.status_code);

    pthread_mutex_unlock(&list->lock);
}

void remove_entry(List* list, int status_code) {
    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if ((*current)->entry.status_code == status_code) {
            Node* to_delete = *current;
            *current = (*current)->next;
            free(to_delete->entry.message);
            free(to_delete);
            list->count--;
            // Log removal
            printf("Removed entry with status code: %d\n", status_code);
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&list->lock);
}

Entry* get_entry(List* list, int index) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    size_t i = 0;

    while (current && i < index) {
        current = current->next;
        i++;
    }

    pthread_mutex_unlock(&list->lock);

    if (!current) return NULL;
    return &current->entry;
}

void destroy_list(List* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* to_delete = current;
        current = current->next;
        free(to_delete->entry.message);
        free(to_delete);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
