        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

Record* allocate_record(int key, long offset, double value, bool valid) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return NULL;

    new_record->key = key;
    new_record->offset = offset;
    new_record->value = value;
    new_record->valid = valid;
    new_record->next = NULL;
    return new_record;
}

void populate_random_data(Collection* collection, int num_records) {
    if (!collection || num_records <= 0) return;

    pthread_mutex_lock(&collection->lock);

    int keys[256] = {0}; // Array to track used keys within a block
    for (int i = 0; i < num_records; ++i) {
        long offset;
        double value;

        do {
            offset = rand() % 100000; // Randomize offset
            value = ((double)rand() / RAND_MAX) * 100.0; // Randomize value
        } while (keys[(offset % 256)] == 1);

        int key = rand() % 256;
        bool valid = rand() % 2;

        Record* new_record = allocate_record(key, offset, value, valid);
        if (!new_record) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&collection->lock);
            return; // Exit on failure
        }

        keys[key] = 1;
        new_record->next = collection->head;
        collection->head = new_record;
    }

    pthread_mutex_unlock(&collection->lock);
}

void free_records(Record* head) {
    Record* current = head;
    while (current != NULL) {
        Record* next = current->next;
        free(current);
        current = next;
    }
}
