#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

// Define constants for maximum usage and logging thresholds.
#define MAX_MEMORY_USAGE 1024 * 1024 // Example: 1MB
#define MEMORY_THRESHOLD_WARNING (MAX_MEMORY_USAGE * 0.75)
#define MEMORY_THRESHOLD_CRITICAL (MAX_MEMORY_USAGE * 0.9)

typedef struct {
    int value;
} Record;

// Define a simple hash table node structure.
typedef struct HashNode {
    int key;
    Record record;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** buckets;
    size_t bucket_count;
    pthread_mutex_t lock; // For atomic updates
} HashTable;

unsigned long hash_function(int key, size_t bucket_count) {
    return (unsigned long)(key % bucket_count);
}

HashTable* create_hash_table(size_t bucket_count) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = calloc(bucket_count, sizeof(HashNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->bucket_count = bucket_count;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void log_memory_usage(size_t current_usage) {
    if (current_usage > MEMORY_THRESHOLD_CRITICAL) {
        printf("CRITICAL: Memory usage exceeded critical threshold!\n");
    } else if (current_usage > MEMORY_THRESHOLD_WARNING) {
        printf("WARNING: Memory usage is high.\n");
    }
}

int add_or_update_record(HashTable* table, int key, Record record) {
    unsigned long index = hash_function(key, table->bucket_count);

    pthread_mutex_lock(&table->lock);

    HashNode* node = table->buckets[index];
    while (node) {
        if (node->key == key) {
            memcpy(&node->record, &record, sizeof(Record));
            pthread_mutex_unlock(&table->lock);
            return 0; // Record updated
        }
        node = node->next;
    }

    HashNode* new_node = malloc(sizeof(HashNode));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Allocation failed
    }

    new_node->key = key;
    memcpy(&new_node->record, &record, sizeof(Record));
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->lock);
    return 0; // Record added
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->bucket_count; ++i) {
        HashNode* node = table->buckets[i];
        while (node) {
            HashNode* tmp = node;
            node = node->next;
            free(tmp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int main() {
    size_t initial_bucket_count = 100; // Initial bucket count
    HashTable* table = create_hash_table(initial_bucket_count);

    if (!table) {
        fprintf(stderr, "Failed to initialize hash table.\n");
        return EXIT_FAILURE;
    }

    Record record;
    for (int i = 0; i < 1000; ++i) {
        record.value = rand() % 100; // Random value between 0 and 99
        if (add_or_update_record(table, i, record) != 0) {
            fprintf(stderr, "Failed to add or update record for key: %d\n", i);
        }
    }

    free_hash_table(table);

    return EXIT_SUCCESS;
}
