#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "logging_library.h" // Replace with actual logging library header

typedef enum {
    TYPE_STRING,
    TYPE_INTEGER,
    TYPE_BINARY_DATA
} ValueType;

typedef struct {
    char *Key;
    time_t Timestamp;
    ValueType Value_Type;
    void *Value;  // Pointer to store various data types
} CacheEntry;

typedef struct {
    CacheEntry **entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond_var;
} MetadataCache;

#define INITIAL_CAPACITY 16

MetadataCache* create_cache() {
    MetadataCache *cache = malloc(sizeof(MetadataCache));
    if (!cache) return NULL;

    cache->entries = calloc(INITIAL_CAPACITY, sizeof(CacheEntry *));
    if (!cache->entries) {
        free(cache);
        return NULL;
    }

    cache->capacity = INITIAL_CAPACITY;
    cache->count = 0;

    pthread_mutex_init(&cache->lock, NULL);
    pthread_cond_init(&cache->cond_var, NULL);

    log_info("Cache created with initial capacity of %zu.", INITIAL_CAPACITY); // Use actual logging API

    return cache;
}

void free_cache(MetadataCache *cache) {
    if (!cache) return;

    for (size_t i = 0; i < cache->count; ++i) {
        CacheEntry *entry = cache->entries[i];
        if (entry) {
            free(entry->Key);
            switch (entry->Value_Type) {
                case TYPE_STRING:
                    free(entry->Value);
                    break;
                case TYPE_INTEGER:
                    // No dynamic memory allocation for integer
                    break;
                case TYPE_BINARY_DATA:
                    free(entry->Value);
                    break;
            }
        }
    }

    free(cache->entries);

    pthread_mutex_destroy(&cache->lock);
    pthread_cond_destroy(&cache->cond_var);
    free(cache);

    log_info("Cache resources freed successfully.");
}

int cache_insert(MetadataCache *cache, const char *key, time_t timestamp, ValueType value_type, void *value) {
    if (!cache || !key) return -1;

    pthread_mutex_lock(&cache->lock);

    // Check for existing key
    for (size_t i = 0; i < cache->count; ++i) {
        if (strcmp(cache->entries[i]->Key, key) == 0) {
            log_warning("Duplicate key detected: %s", key);
            pthread_mutex_unlock(&cache->lock);
            return -1;
        }
    }

    // Resize cache if necessary
    if (cache->count >= cache->capacity) {
        size_t new_capacity = cache->capacity * 2;
        CacheEntry **new_entries = realloc(cache->entries, new_capacity * sizeof(CacheEntry *));
        if (!new_entries) {
            pthread_mutex_unlock(&cache->lock);
            log_error("Failed to resize cache.");
            return -1;
        }
        memset(new_entries + cache->capacity, 0, cache->capacity * sizeof(CacheEntry *));
        cache->entries = new_entries;
        cache->capacity = new_capacity;

        log_info("Cache resized to capacity %zu.", new_capacity);
    }

    // Allocate and initialize entry
    CacheEntry *entry = malloc(sizeof(CacheEntry));
    if (!entry) {
        pthread_mutex_unlock(&cache->lock);
        log_error("Failed to allocate memory for cache entry.");
        return -1;
    }

    entry->Key = strdup(key);
    entry->Timestamp = timestamp;
    entry->Value_Type = value_type;

    switch (value_type) {
        case TYPE_STRING:
            entry->Value = malloc(strlen((char *)value) + 1);
            if (!entry->Value) {
                free(entry->Key);
                free(entry);
                pthread_mutex_unlock(&cache->lock);
                log_error("Failed to allocate memory for string value.");
                return -1;
            }
            strcpy(entry->Value, (char *)value);
            break;
        case TYPE_INTEGER:
            entry->Value = malloc(sizeof(int));
            if (!entry->Value) {
                free(entry->Key);
                free(entry);
                pthread_mutex_unlock(&cache->lock);
                log_error("Failed to allocate memory for integer value.");
                return -1;
            }
            *(int *)entry->Value = *(int *)value;
            break;
        case TYPE_BINARY_DATA:
            entry->Value = malloc(strlen((char *)value));
            if (!entry->Value) {
                free(entry->Key);
                free(entry);
                pthread_mutex_unlock(&cache->lock);
                log_error("Failed to allocate memory for binary data value.");
                return -1;
            }
            memcpy(entry->Value, value, strlen((char *)value));
            break;
    }

    cache->entries[cache->count++] = entry;

    log_info("Inserted key: %s", key);

    pthread_mutex_unlock(&cache->lock);
    return 0;
}

void* retrieve_cache_entry(MetadataCache *cache, const char *key) {
    if (!cache || !key) return NULL;

    pthread_mutex_lock(&cache->lock);

    for (size_t i = 0; i < cache->count; ++i) {
        CacheEntry *entry = cache->entries[i];
        if (strcmp(entry->Key, key) == 0) {
            void *value_copy;
            switch (entry->Value_Type) {
                case TYPE_STRING:
                    value_copy = strdup((char *)entry->Value);
                    break;
                case TYPE_INTEGER:
                    value_copy = malloc(sizeof(int));
                    *(int *)value_copy = *(int *)entry->Value;
                    break;
                case TYPE_BINARY_DATA:
                    value_copy = malloc(strlen((char *)entry->Value));
                    memcpy(value_copy, entry->Value, strlen((char *)entry->Value));
                    break;
            }

            pthread_mutex_unlock(&cache->lock);
            log_info("Retrieved key: %s", key);

            return value_copy;
        }
    }

    pthread_mutex_unlock(&cache->lock);
    log_warning("Key not found: %s", key);

    return NULL;  // Key not found
}

void cache_evict(MetadataCache *cache) {
    if (!cache || cache->count == 0) return;

    pthread_mutex_lock(&cache->lock);

    // Implement a simple eviction policy, e.g., LRU or random eviction
    size_t evict_index = rand() % cache->count;  // Replace with actual LRU logic

    CacheEntry *entry = cache->entries[evict_index];
    if (entry) {
        free(entry->Key);
        switch (entry->Value_Type) {
            case TYPE_STRING:
                free(entry->Value);
                break;
            case TYPE_INTEGER:
                // No dynamic memory allocation for integer
                break;
            case TYPE_BINARY_DATA:
                free(entry->Value);
                break;
        }
        free(entry);

        memmove(&cache->entries[evict_index], &cache->entries[evict_index + 1],
                (cache->count - evict_index - 1) * sizeof(CacheEntry *));
        cache->count--;

        log_info("Evicted key at index %zu", evict_index);
    }

    pthread_mutex_unlock(&cache->lock);
}

void update_cache_config(MetadataCache *cache, size_t new_capacity) {
    if (!cache || new_capacity < cache->count) return;

    pthread_mutex_lock(&cache->lock);

    CacheEntry **new_entries = realloc(cache->entries, new_capacity * sizeof(CacheEntry *));
    if (new_entries) {
        memset(new_entries + cache->capacity, 0, (new_capacity - cache->capacity) * sizeof(CacheEntry *));
        cache->entries = new_entries;
        cache->capacity = new_capacity;

        log_info("Cache configuration updated. New capacity: %zu", new_capacity);
    } else {
        log_error("Failed to update cache configuration.");
    }

    pthread_mutex_unlock(&cache->lock);
}

void monitor_system_health(MetadataCache *cache) {
    if (!cache) return;

    pthread_mutex_lock(&cache->lock);

    // Log system health information
    log_info("System health check: Active threads %ld, Cached items %zu",
             (long)pthread_active_count(), cache->count);

    pthread_mutex_unlock(&cache->lock);
}

int main() {
    MetadataCache *cache = create_cache();

    if (!cache) {
        fprintf(stderr, "Failed to initialize cache.\n");
        return EXIT_FAILURE;
    }

    // Example usage
    int value = 42;
    cache_insert(cache, "key1", time(NULL), TYPE_INTEGER, &value);

    update_cache_config(cache, 32); // Example of runtime configuration adjustment

    monitor_system_health(cache);

    void *retrieved_value = retrieve_cache_entry(cache, "key1");
    if (retrieved_value) {
        int *int_value = (int *)retrieved_value;
        printf("Retrieved integer value: %d\n", *int_value);
        free(retrieved_value);
    }

    cache_evict(cache);

    free_cache(cache);

    return EXIT_SUCCESS;
}
