data_point* initialize_data_points(int num_points, double min_val, double max_val, char **categories, int category_count) {
    srand((unsigned int)time(NULL));

    // Allocate memory for data points and categories
    data_point *points = (data_point *)malloc(num_points * sizeof(data_point));
    if (!points) {
        perror("Failed to allocate memory for data points");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_points; ++i) {
        // Generate random double value
        double rand_val = min_val + ((double)rand() / RAND_MAX) * (max_val - min_val);
        points[i].value = rand_val;

        // Assign a random category label
        int cat_index = rand() % category_count;
        points[i].label = strdup(categories[cat_index]);
    }

    return points;
}

// Function to manage lifecycle of numerical resources
void process_data_points(data_point *points, int num_points, library *num_lib) {
    for (int i = 0; i < num_lib->count; ++i) {
        // Call each algorithm on the data points
        for (int j = 0; j < num_points; ++j) {
            num_lib->algorithms[i].func(&points[j]);
        }
    }

    // Example: Compute statistics
    double values[num_points];
    for (int i = 0; i < num_points; ++i) {
        values[i] = points[i].value;
    }

    printf("Mean: %f\n", calculate_mean(values, num_points));
    printf("Median: %f\n", calculate_median(values, num_points));
    printf("Variance: %f\n", calculate_variance(values, num_points));
}

// Function to free resources
void cleanup_data_points(data_point *points, int num_points) {
    for (int i = 0; i < num_points; ++i) {
        free(points[i].label);
    }
    free(points);
}

int main() {
    // Define categories and numerical algorithms
    char *categories[] = {"Category1", "Category2", "Category3"};
    int category_count = sizeof(categories) / sizeof(char *);

    library num_lib = {0};

    add_algorithm(&num_lib, "FFT", fft);
    add_algorithm(&num_lib, "Matrix Multiply", (numerical_func)matrix_multiply);

    // Initialize data points
    int num_points = 1000;
    double min_val = 0.0, max_val = 100.0;
    data_point *points = initialize_data_points(num_points, min_val, max_val, categories, category_count);

    // Process data points with numerical algorithms
    process_data_points(points, num_points, &num_lib);

    // Clean up resources
    cleanup_data_points(points, num_points);

    return 0;
}
```

