#include <stdio.h>
#include <stdlib.h>
import threading

#define MAX_REQUESTS 10000
#define MEMORY_THRESHOLD 1024 * 1024 * 512 // Example: 512MB

typedef struct {
    int id;
    char *headers;
    size_t headers_size;
    char *body;
    size_t body_size;
} RequestPayload;

typedef struct {
    RequestPayload payload;
    JSONEncoder encoder;
} HTTP_Request;

typedef struct {
    HTTP_Request* requests[MAX_REQUESTS];
    size_t count;
    pthread_mutex_t lock;
    // Example of custom allocator (can be replaced with others for testing)
    void* (*allocator)(size_t);
    void (*deallocator)(void*);
} RequestPool;

// Function prototypes
RequestPool* initialize_request_pool(void* (*alloc_func)(size_t), void (*dealloc_func)(void*));
int add_http_request(RequestPool* pool, HTTP_Request request);
void serialize_requests(const char* filepath, RequestPool* pool);
void deserialize_requests(const char* filepath, RequestPool* pool);
void cleanup_request_pool(RequestPool* pool);

// Initialize the request pool
RequestPool* initialize_request_pool(void* (*alloc_func)(size_t), void (*dealloc_func)(void*)) {
    RequestPool* pool = (RequestPool*)alloc_func(sizeof(RequestPool));
    if (!pool) return NULL;

    for (int i = 0; i < MAX_REQUESTS; ++i) {
        pool->requests[i] = NULL;
    }

    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pool->allocator = alloc_func;
    pool->deallocator = dealloc_func;

    // Log initialization
    printf("Request Pool initialized with custom allocator.\n");

    return pool;
}

// Add a new HTTP request to the pool
int add_http_request(RequestPool* pool, HTTP_Request request) {
    pthread_mutex_lock(&pool->lock);

    if (pool->count >= MAX_REQUESTS) {
        pthread_mutex_unlock(&pool->lock);
        fprintf(stderr, "Maximum number of requests reached.\n");
        return -1;
    }

    for (size_t i = 0; i < MAX_REQUESTS; ++i) {
        if (!pool->requests[i]) {
            pool->requests[i] = (HTTP_Request*)pool->allocator(sizeof(HTTP_Request));
            if (!pool->requests[i]) {
                pthread_mutex_unlock(&pool->lock);
                fprintf(stderr, "Memory allocation failed.\n");
                return -1;
            }
            *pool->requests[i] = request;
            ++pool->count;
            break;
        }
    }

    pthread_mutex_unlock(&pool->lock);

    // Log addition
    printf("Added HTTP_Request ID %d to the pool.\n", request.payload.id);
    return 0;
}

// Serialize requests to a binary file
void serialize_requests(const char* filepath, RequestPool* pool) {
    FILE* file = fopen(filepath, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing: %s\n", filepath);
        return;
    }

    pthread_mutex_lock(&pool->lock);

    fwrite(&pool->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < pool->count; ++i) {
        HTTP_Request* req = pool->requests[i];
        fwrite(&req->payload.id, sizeof(int), 1, file);
        fwrite(&req->payload.headers_size, sizeof(size_t), 1, file);
        fwrite(req->payload.headers, sizeof(char), req->payload.headers_size, file);
        fwrite(&req->payload.body_size, sizeof(size_t), 1, file);
        fwrite(req->payload.body, sizeof(char), req->payload.body_size, file);
    }

    pthread_mutex_unlock(&pool->lock);

    fclose(file);
}

// Deserialize requests from a binary file
void deserialize_requests(const char* filepath, RequestPool* pool) {
    FILE* file = fopen(filepath, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading: %s\n", filepath);
        return;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    pthread_mutex_lock(&pool->lock);
    pool->count = count;

    for (size_t i = 0; i < count; ++i) {
        HTTP_Request* req = (HTTP_Request*)pool->allocator(sizeof(HTTP_Request));
        if (!req) {
            fprintf(stderr, "Memory allocation failed during deserialization.\n");
            fclose(file);
            pthread_mutex_unlock(&pool->lock);
            return;
        }

        int id;
        size_t headers_size, body_size;

        fread(&id, sizeof(int), 1, file);
        fread(&headers_size, sizeof(size_t), 1, file);

        req->payload.headers = (char*)pool->allocator(headers_size);
        if (!req->payload.headers) {
            fprintf(stderr, "Memory allocation failed for headers.\n");
            fclose(file);
            pthread_mutex_unlock(&pool->lock);
            return;
        }

        fread(req->payload.headers, sizeof(char), headers_size, file);

        fread(&body_size, sizeof(size_t), 1, file);
        req->payload.body = (char*)pool->allocator(body_size);
        if (!req->payload.body) {
            fprintf(stderr, "Memory allocation failed for body.\n");
            fclose(file);
            pthread_mutex_unlock(&pool->lock);
            return;
        }

        fread(req->payload.body, sizeof(char), body_size, file);
        req->payload.id = id;

        pool->requests[i] = req;
    }

    pthread_mutex_unlock(&pool->lock);

    fclose(file);
}

// Cleanup the request pool
void cleanup_request_pool(RequestPool* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);

    for (size_t i = 0; i < pool->count; ++i) {
        HTTP_Request* req = pool->requests[i];
        if (req) {
            pool->deallocator(req->payload.headers);
            pool->deallocator(req->payload.body);
            pool->deallocator(req);
        }
    }

    pthread_mutex_unlock(&pool->lock);

    // Free the pool structure
    pthread_mutex_destroy(&pool->lock);
    pool->deallocator(pool);

    printf("Request Pool cleaned up.\n");
}
