            manager->messages[i].nasMessage.messageType = rand() % 256;
            snprintf(manager->messages[i].nasMessage.content, sizeof(manager->messages[i].nasMessage.content), 
                     "Content for message type %d", manager->messages[i].nasMessage.messageType);
        }
    }

    manager->count = new_size;

    pthread_mutex_unlock(&manager->lock);
}

void cleanup_message_manager(MessageManager* manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->messages[i].TLVEncoder);
    }
    free(manager->messages);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond_var);
}

int main() {
    MessageManager manager;
    initialize_message_manager(&manager, 1000); // Initialize with some size

    pthread_t threads[MAX_MESSAGES];
    for (size_t i = 0; i < MAX_MESSAGES && i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &manager)) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < MAX_MESSAGES && i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_join(threads[i], NULL);
    }

    resize_message_manager(&manager, 500); // Example of resizing

    cleanup_message_manager(&manager);

    return 0;
}
```

### Key Points:

- **Thread Safety:** Uses `pthread_mutex` and `pthread_cond_t` to ensure safe access to shared data structures.
- **Dynamic Resizing:** Implements dynamic resizing with `realloc` while maintaining thread safety.
- **Memory Management:** Efficiently manages memory allocation and deallocation for the encoder objects.
- **Error Handling:** Includes basic error handling for memory allocation failures.
- **Logging:** Logs system health periodically (simplified here for demonstration).
- **Asynchronous Processing:** Each thread processes its own set of messages independently, ensuring non-blocking operation.']

