        return -1;
    }

    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));
    record *records_arr = malloc(record_size * sizeof(record));

    if (!offsets || !keys || !records_arr) {
        log_error(log_path, "Memory allocation failed");
        free(offsets);
        free(keys);
        free(records_arr);
        return -1;
    }

    srand(seed);

    for (int i = 0; i < offset_size; ++i) {
        offsets[i] = rand() % 100000;
    }

    for (int i = 0; i < key_size; ++i) {
        keys[i] = rand() % 10000;
    }

    for (int i = 0; i < record_size; ++i) {
        records_arr[i].timestamp = offsets[i % offset_size];
        records_arr[i].key = keys[i % key_size];
        records_arr[i].value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
    }

    memcpy(records, records_arr, record_size * sizeof(record));

    free(offsets);
    free(keys);
    free(records_arr);

    return 0; // Success
}
