// Implement memory pooling for NFAPI_CRC_INDICATION_PDU_T
template<typename T>
class MemoryPool {
public:
    MemoryPool(size_t size) : poolSize(size), currentIndex(0) {
        pool.reserve(poolSize);
        for (size_t i = 0; i < poolSize; ++i) {
            pool.push_back(std::make_unique<T>());
        }
    }

    T* acquire() {
        std::lock_guard<std::mutex> lock(mtx);
        if (currentIndex >= pool.size()) {
            return new T();
        }
        return pool[currentIndex++].get();
    }

    void release(T* obj) {
        std::lock_guard<std::mutex> lock(mtx);
        if (currentIndex > 0) {
            --currentIndex;
            *pool[currentIndex] = *obj; // Reset object state
        } else {
            delete obj;
        }
    }

private:
    size_t poolSize;
    size_t currentIndex;
    std::vector<std::unique_ptr<T>> pool;
    mutable std::mutex mtx; // Mutex for thread-safe access
};

