#define INITIAL_SIZE 10

typedef enum { ACTIVE, INACTIVE, EXPIRED } SessionStatus;

typedef struct {
    char sessionID[64];
    time_t established;
    time_t lastAccessed;
    SessionStatus status;
    char userPreferences[256]; // Simplified for brevity
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SessionList;

int authenticateUser(const char *credentials) {
    // Simulated authentication function; replace with real service call.
    return 1; // Assume success for illustration
}

void initializeSessions(SessionList *sessionList) {
    sessionList->sessions = malloc(INITIAL_SIZE * sizeof(UserSession));
    if (!sessionList->sessions) exit(EXIT_FAILURE);

    sessionList->count = 0;
    sessionList->capacity = INITIAL_SIZE;
    pthread_mutex_init(&sessionList->lock, NULL);
}

void resizeSessions(SessionList *sessionList) {
    size_t newCapacity = sessionList->capacity * 2;
    UserSession *newSessions = realloc(sessionList->sessions, newCapacity * sizeof(UserSession));

    if (!newSessions) exit(EXIT_FAILURE);

    sessionList->sessions = newSessions;
    sessionList->capacity = newCapacity;
}

void addSession(SessionList *sessionList, const char *sessionID, const char *credentials) {
    pthread_mutex_lock(&sessionList->lock);

    if (sessionList->count == sessionList->capacity)
        resizeSessions(sessionList);

    if (authenticateUser(credentials)) {
        UserSession newSession;
        strncpy(newSession.sessionID, sessionID, sizeof(newSession.sessionID));
        newSession.established = time(NULL);
        newSession.lastAccessed = newSession.established;
        newSession.status = ACTIVE;
        strcpy(newSession.userPreferences, "default"); // Simplified for brevity

        sessionList->sessions[sessionList->count++] = newSession;
    }

    pthread_mutex_unlock(&sessionList->lock);
}

void removeExpiredSessions(SessionList *sessionList) {
    time_t currentTime = time(NULL);
    size_t i, j;

    pthread_mutex_lock(&sessionList->lock);

    for (i = 0, j = 0; i < sessionList->count; ++i) {
        if (difftime(currentTime, sessionList->sessions[i].lastAccessed) > 3600 && 
            sessionList->sessions[i].status != INACTIVE) {

            // Session expired
            sessionList->sessions[i].status = EXPIRED;
        } else if (sessionList->sessions[i].status != EXPIRED) {
            sessionList->sessions[j++] = sessionList->sessions[i];
        }
    }

    sessionList->count = j;

    pthread_mutex_unlock(&sessionList->lock);
}

void updateSessionAccess(SessionList *sessionList, const char *sessionID) {
    pthread_mutex_lock(&sessionList->lock);

    for (size_t i = 0; i < sessionList->count; ++i) {
        if (strcmp(sessionList->sessions[i].sessionID, sessionID) == 0 &&
            sessionList->sessions[i].status != EXPIRED) {

            sessionList->sessions[i].lastAccessed = time(NULL);
            break;
        }
    }

    pthread_mutex_unlock(&sessionList->lock);
}

void cleanupSessions(SessionList *sessionList) {
    free(sessionList->sessions);
    pthread_mutex_destroy(&sessionList->lock);
}

// Example usage
int main() {
    SessionList sessionList;
    initializeSessions(&sessionList);

    addSession(&sessionList, "session1", "user_credentials");
