#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_METADATA_SIZE 256
#define STATUS_INCOMPLETE 0
#define STATUS_COMPLETE 1

typedef struct {
    int value;
    char str_value[12];
    time_t timestamp;
    char metadata[MAX_METADATA_SIZE];
    int status_flag;
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} BatchRecord;

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    pthread_mutex_lock(&log_mutex);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_mutex);
}

int compare_metadata(const void *a, const void *b) {
    return strcmp(((BatchRecord *)a)->record.metadata, ((BatchRecord *)b)->record.metadata);
}

void initialize_batch(int num_records, int key[], long seed, double probability, BatchRecord **batch) {
    if (num_records <= 0 || !key || !batch) return;

    srand(seed);

    *batch = malloc(num_records * sizeof(BatchRecord));
    if (!*batch) {
        fprintf(stderr, "Memory allocation failed for batch.\n");
        exit(EXIT_FAILURE);
    }

    int valid_metadata_count = 0;
    char metadata_set[100][MAX_METADATA_SIZE] = {{"meta1"}, {"meta2"}, {"meta3"}}; // Example set
    int metadata_indices[100] = {-1}; // Track used indices

    for (int i = 0; i < num_records; ++i) {
        (*batch)[i].offset = i;
        (*batch)[i].key = key[i];

        if ((rand() / (double)RAND_MAX) < probability) {
            int value = rand() % 1000;
            snprintf((*batch)[i].record.str_value, sizeof((*batch)[i].record.str_value), "%d", value);
            (*batch)[i].record.value = value;
        } else {
            (*batch)[i].record.value = -1;
            strcpy((*batch)[i].record.str_value, "N/A");
        }

        (*batch)[i].record.timestamp = time(NULL) + i; // Monotonically increasing

        int metadata_index;
        do {
            metadata_index = rand() % 3;
        } while (metadata_indices[metadata_index] != -1);

        strcpy((*batch)[i].record.metadata, metadata_set[metadata_index]);
        metadata_indices[metadata_index] = i;

        (*batch)[i].record.status_flag = STATUS_INCOMPLETE;

        char log_buf[256];
        snprintf(log_buf, sizeof(log_buf), "Record %d initialized with key %d and metadata %s", 
                 i, key[i], (*batch)[i].record.metadata);
        log_message(log_buf);

        valid_metadata_count++;
    }

    if (valid_metadata_count != num_records) {
        fprintf(stderr, "Metadata uniqueness constraint violated.\n");
        free(*batch);
        *batch = NULL;
        exit(EXIT_FAILURE);
    }
}

void finalize_batch(BatchRecord **batch, int num_records) {
    if (!batch || !*batch) return;

    for (int i = 0; i < num_records; ++i) {
        (*batch)[i].record.status_flag = STATUS_COMPLETE;
    }

    free(*batch);
    *batch = NULL;
}

int main() {
    int keys[] = {1, 2, 3, 4, 5};
    BatchRecord *batch = NULL;

    initialize_batch(5, keys, 12345, 0.8, &batch);

    if (batch) {
        // Process records...
        finalize_batch(&batch, 5);
    }

    return 0;
}
```

### Key Points:
- **Dynamic Allocation**: Allocates memory for a batch of `BatchRecord` structures.
- **Random Initialization**: Uses a seed for reproducibility and respects a probability distribution for random value generation.
- **Metadata Uniqueness**: Ensures metadata strings are unique within the batch.
- **Logging**: Implements thread-safe logging to record each record's creation.
- **Error Handling**: Checks for memory allocation failures and ensures metadata uniqueness.
- **Finalization**: Cleans up allocated memory after processing.']

