#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_STRUCTURES 1024 // Configurable maximum number of structures to initialize
#define CACHE_LIMIT 1000    // Cache size limit

// Structure definitions (assuming these are provided or can be created as per requirements)
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[10];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    time_t last_access_time; // For cache eviction based on access frequency
    pthread_mutex_t lock;    // Mutex for thread safety
    struct CacheNode* next;
    struct CacheNode* prev;
} CacheNode;

// Global variables and mutexes
CacheNode* cache_head = NULL;
CacheNode* cache_tail = NULL;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
int total_cached_items = 0;
int total_structures_processed = 0;

void log_error(const char* error_message) {
    time_t now = time(NULL);
    fprintf(stderr, "[%s] Error: %s\n", ctime(&now), error_message);
}

NFAPI_CRC_INDICATION_PDU_T* populate_NFAPI_CRC_INDICATION_PDU_T(int max_structures, int* actual_count) {
    if (max_structures <= 0 || max_structures > MAX_STRUCTURES) {
        log_error("Invalid maximum structures limit.");
        *actual_count = 0;
        return NULL;
    }

    pthread_mutex_lock(&cache_lock);

    // Calculate the number of new items to add
    int num_items_to_add = (total_cached_items + max_structures < CACHE_LIMIT) ? max_structures : CACHE_LIMIT - total_cached_items;

    NFAPI_CRC_INDICATION_PDU_T* result_array = malloc(num_items_to_add * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result_array) {
        log_error("Memory allocation failure for result array.");
        pthread_mutex_unlock(&cache_lock);
        *actual_count = 0;
        return NULL;
    }

    // Populate the structures
    for (int i = 0; i < num_items_to_add; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_item = &result_array[i];
        pthread_mutex_t item_lock;
        pthread_mutex_init(&item_lock, NULL);

        new_item->RX_UE_INFORMATION_TAG = rand() % 10000; // Random value
        new_item->RNTI = rand() % 1000000;                // Random value

        for (int j = 0; j < sizeof(new_item->CRC_INDICATION_REL8_TAG); ++j) {
            new_item->CRC_INDICATION_REL8_TAG[j] = rand() % 256;
        }

        uint8_t CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        if (CRCFLAG) {
            log_error("CRCFLAG is set to true in structure.");
        }

        // Create cache node
        CacheNode* new_cache_node = malloc(sizeof(CacheNode));
        if (!new_cache_node) {
            free(result_array);
            log_error("Memory allocation failure for cache node.");
            pthread_mutex_unlock(&cache_lock);
            *actual_count = 0;
            return NULL;
        }

        memcpy(&new_cache_node->data, new_item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        time(&new_cache_node->last_access_time);

        pthread_mutex_init(&new_cache_node->lock, NULL);
        new_cache_node->next = cache_head;
        new_cache_node->prev = NULL;

        if (cache_head) {
            cache_head->prev = new_cache_node;
        }

        cache_head = new_cache_node;

        if (!cache_tail) {
            cache_tail = new_cache_node;
        }

        total_cached_items++;
        total_structures_processed++;

        pthread_mutex_lock(&item_lock);
        pthread_mutex_unlock(&item_lock);
    }

    // Eviction policy if the cache limit is reached
    while (total_cached_items > CACHE_LIMIT && cache_head) {
        CacheNode* node_to_remove = cache_tail;

        if (node_to_remove->prev) {
            node_to_remove->prev->next = NULL;
        } else {
            cache_head = node_to_remove->next;
        }

        if (cache_tail == node_to_remove) {
            cache_tail = node_to_remove->prev;
        }

        pthread_mutex_destroy(&node_to_remove->lock);
        free(node_to_remove);

        total_cached_items--;
    }

    pthread_mutex_unlock(&cache_lock);

    *actual_count = num_items_to_add;
    return result_array;
}

void cleanup_cache() {
    CacheNode* current = cache_head;
    while (current) {
        CacheNode* next_node = current->next;
        pthread_mutex_destroy(&current->lock);
        free(current);
        current = next_node;
    }
    cache_head = NULL;
    cache_tail = NULL;
    total_cached_items = 0;
}

int main() {
    int actual_count = 0;
    NFAPI_CRC_INDICATION_PDU_T* structures = populate_NFAPI_CRC_INDICATION_PDU_T(10, &actual_count);

    if (structures) {
        printf("Successfully populated %d structures.\n", actual_count);
        free(structures);
    }

    cleanup_cache();

    return 0;
}
```

### Key Design Choices:
- **Thread Safety**: Mutexes are used to ensure thread safety during cache operations and structure initialization.
- **Error Logging**: Errors are logged with timestamps for debugging and monitoring purposes.
- **Cache Management**: A simple linked list is used to manage the cache, with eviction based on the least recently accessed policy.
- **Memory Efficiency**: Dynamic memory allocation ensures efficient use of resources, adjusting size as necessary.
- **Scalability**: The function supports future scaling by making configuration parameters easily adjustable and modular design choices.']

