// Initialize the custom memory allocator
void init_custom_allocator(CustomAllocator *allocator, size_t capacity) {
    allocator->capacity = capacity;
    for (size_t i = 0; i < capacity; ++i) {
        atomic_store(&allocator->pool[i], (uintptr_t)NULL);
    }
    pthread_mutex_init(&allocator->lock, NULL);
}

// Free the custom memory allocator
void free_custom_allocator(CustomAllocator *allocator) {
    pthread_mutex_destroy(&allocator->lock);
}

// Allocate a new NFAPI_CRC_INDICATION_PDU_T structure
NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(CustomAllocator *allocator) {
    for (size_t i = 0; i < allocator->capacity; ++i) {
        uintptr_t ptr = atomic_load(&allocator->pool[i]);
        if (ptr == (uintptr_t)NULL) {
            void *mem = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!mem) return NULL;
            NFAPI_CRC_INDICATION_PDU_T* pdu = mem;
            // Initialize fields...
            atomic_store(&allocator->pool[i], (uintptr_t)pdu);
            return pdu;
        }
    }
    return NULL; // No available slots
}

// Release a previously allocated structure
void deallocate_pdu(CustomAllocator *allocator, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    for (size_t i = 0; i < allocator->capacity; ++i) {
