// Namespace for resource management
namespace ResourceManager {

class Timer {
public:
    using Clock = std::chrono::high_resolution_clock;

    void Start() { start_ = Clock::now(); }

    double ElapsedMilliseconds() const {
        auto end = Clock::now();
        return std::chrono::duration_cast<std::chrono::milliseconds>(end - start_).count();
    }

private:
    Clock::time_point start_;
};

class ArrayManager {
public:
    explicit ArrayManager(size_t initial_size) : keys_(initial_size), values_(initial_size) {}

    bool Resize(size_t new_size) {
        std::lock_guard<std::mutex> lock(mutex_);
        try {
            keys_.resize(new_size);
            values_.resize(new_size);
            Logger::Log("Array resized successfully.");
            return true;
        } catch (const std::bad_alloc&) {
            Logger::Error("Failed to resize array due to memory allocation error.");
            return false;
        }
    }

private:
    std::vector<int> keys_;
    std::vector<double> values_;
    mutable std::mutex mutex_;
};

class LinkedListManager {
public:
    struct Item {
        std::string name;
        double value;

        bool operator==(const Item& other) const {
            return name == other.name && value == other.value;
        }
    };

    using ItemPtr = std::shared_ptr<Item>;
    using Hash = std::hash<std::string>;

private:
    struct ItemHasher {
        size_t operator()(const Item& item) const {
            return Hash{}(item.name) ^ static_cast<size_t>(std::round(item.value));
        }
    };

public:
    bool AddItem(const ItemPtr& item) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (items_.find(*item) != items_.end()) {
            Logger::Log("Duplicate item not added.");
            return false;
        }

        items_.insert(*item);
        list_.push_back(item);
        Logger::Log("Item added successfully.");
        return true;
    }

    void Clear() {
        std::lock_guard<std::mutex> lock(mutex_);
        items_.clear();
        list_.clear();
        Logger::Log("Linked list cleared.");
    }

private:
    std::list<ItemPtr> list_;
    std::unordered_set<Item, ItemHasher> items_;
    mutable std::mutex mutex_;
};

class ResourceFinalizer {
public:
    static void Finalize(ArrayManager& array_manager, LinkedListManager& linked_list_manager) {
        Logger::Log("Finalizing resources.");
        // ArrayManager finalization is managed by RAII
        linked_list_manager.Clear();
    }
};
}

// Main program demonstrating the usage of resource management classes
int main() {
    using namespace ResourceManager;

    Timer timer;
    timer.Start();

    try {
        ArrayManager array_manager(10);
        LinkedListManager linked_list_manager;

        if (!array_manager.Resize(20)) {
            throw std::runtime_error("Array resizing failed.");
        }

        auto item1 = std::make_shared<LinkedListManager::Item>();
        item1->name = "item1";
        item1->value = 12.34;
        linked_list_manager.AddItem(item1);

        auto item2 = std::make_shared<LinkedListManager::Item>();
        item2->name = "item2";
        item2->value = 56.78;
        linked_list_manager.AddItem(item2);

    } catch (const std::exception& e) {
        Logger::Error(e.what());
    }

    double elapsed_time = timer.ElapsedMilliseconds();
    Logger::Log("Elapsed time: " + std::to_string(elapsed_time) + " ms");

    ResourceFinalizer::Finalize(array_manager, linked_list_manager);

    return 0;
}
