#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CACHE_SIZE 10
#define INITIAL_ARRAY_SIZE 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data[MAX_CACHE_SIZE];
    int timestamps[MAX_CACHE_SIZE];
    pthread_mutex_t cache_lock;
} LRUCache;

void init_cache(LRUCache* cache) {
    memset(cache->data, 0, sizeof(cache->data));
    for (int i = 0; i < MAX_CACHE_SIZE; ++i) {
        cache->timestamps[i] = -1;
    }
    pthread_mutex_init(&cache->cache_lock, NULL);
}

void log_message(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

int find_least_recently_used(LRUCache* cache) {
    int min_timestamp = INT_MAX;
    int lru_index = -1;

    for (int i = 0; i < MAX_CACHE_SIZE; ++i) {
        if (cache->timestamps[i] != -1 && cache->timestamps[i] < min_timestamp) {
            min_timestamp = cache->timestamps[i];
            lru_index = i;
        }
    }

    return lru_index;
}

void evict_cache_entry(LRUCache* cache, int index) {
    memset(&cache->data[index], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    cache->timestamps[index] = -1;
}

int handle_NFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_T* pduArray, size_t count, int max_init) {
    LRUCache cache;
    init_cache(&cache);

    pthread_mutex_lock(&cache.cache_lock);

    log_message("Starting to process NFAPI CRC Indication PDUs");

    for (size_t i = 0; i < count && i < max_init; ++i) {
        // Simulate processing and updating the timestamp
        int lru_index = find_least_recently_used(&cache);

        if (lru_index == -1) {  // Cache is not full, add new entry
            for (int j = 0; j < MAX_CACHE_SIZE; ++j) {
                if (cache.timestamps[j] == -1) {
                    lru_index = j;
                    break;
                }
            }
        }

        if (lru_index != -1) { // Cache has space or an entry was evicted
            cache.data[lru_index] = pduArray[i];
            cache.timestamps[lru_index] = time(NULL);
        } else {
            log_message("Cache is full, eviction needed");
            lru_index = find_least_recently_used(&cache);
            evict_cache_entry(&cache, lru_index);
            cache.data[lru_index] = pduArray[i];
            cache.timestamps[lru_index] = time(NULL);
        }

        // Simulate network protocol operations
        log_message("Processed and cached PDU");
    }

    pthread_mutex_unlock(&cache.cache_lock);

    log_message("Finished processing NFAPI CRC Indication PDUs");

    return (count < max_init) ? count : max_init;
}

int main() {
    int array_size = 10; // Example size
    NFAPI_CRC_INDICATION_PDU_T pduArray[array_size];

    for (int i = 0; i < array_size; ++i) {
        pduArray[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pduArray[i].RNTI = rand() % 100;
        pduArray[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        pduArray[i].CRCFLAG = (rand() % 2);
    }

    int processed_count = handle_NFAPI_CRC_INDICATION_PDU(pduArray, array_size, INITIAL_ARRAY_SIZE);
    printf("Number of PDUs processed: %d\n", processed_count);

    return 0;
}
