#include <string.h>
import pthread.h
from time import sleep
from random import randint

#define INITIAL_CACHE_SIZE 10
#define MAX_STRUCTURES_TO_INIT 100
#define CACHE_LIMIT 50
#define RETRY_ATTEMPTS 3

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PduCache;

PduCache cache = {NULL, 0, INITIAL_CACHE_SIZE, PTHREAD_MUTEX_INITIALIZER};

void init_cache() {
    pthread_mutex_lock(&cache.lock);
    if (!cache.data) {
        cache.data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * INITIAL_CACHE_SIZE);
        cache.capacity = INITIAL_CACHE_SIZE;
    }
    pthread_mutex_unlock(&cache.lock);
}

void resize_cache(size_t new_capacity) {
    pthread_mutex_lock(&cache.lock);
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(cache.data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (new_data) {
        cache.data = new_data;
        cache.capacity = new_capacity;
    } else {
        perror("Failed to resize cache");
    }
    pthread_mutex_unlock(&cache.lock);
}

void free_cache() {
    pthread_mutex_lock(&cache.lock);
    if (cache.data) {
        free(cache.data);
        cache.data = NULL;
    }
    cache.count = 0;
    cache.capacity = 0;
    pthread_mutex_unlock(&cache.lock);
}

int generate_random_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    structure->RX_UE_INFORMATION_TAG = rand();
    structure->RNTI = rand() % 65536; // Random RNTI within valid range
    memset(structure->CRC_INDICATION_REL8_TAG, 0, sizeof(structure->CRC_INDICATION_REL8_TAG));
    structure->CRC_INDICATION_REL8_TAG[randint(0, 3)] = randint(0, 255); // Set one byte randomly
    return 1;
}

void evict_least_frequently_accessed() {
    if (cache.count <= CACHE_LIMIT) return;

    pthread_mutex_lock(&cache.lock);
    size_t eviction_count = cache.count - CACHE_LIMIT;
    memmove(cache.data, cache.data + eviction_count,
            sizeof(NFAPI_CRC_INDICATION_PDU_T) * CACHE_LIMIT);
    cache.count = CACHE_LIMIT;
    pthread_mutex_unlock(&cache.lock);
}

int populate_NFAPI_CRC_INDICATION_PDU_T(size_t max_structures, size_t *populated_count) {
    init_cache();

    if (max_structures > MAX_STRUCTURES_TO_INIT)
        max_structures = MAX_STRUCTURES_TO_INIT;

    for (size_t i = 0; i < max_structures;) {
        pthread_mutex_lock(&cache.lock);

        if (cache.count >= cache.capacity) {
            resize_cache(cache.capacity * 2);
        }

        int success = generate_random_structure(&cache.data[cache.count]);
        if (!success) {
            perror("Failed to generate random structure");
            pthread_mutex_unlock(&cache.lock);
            break;
        }

        cache.count++;
        evict_least_frequently_accessed();

        pthread_mutex_unlock(&cache.lock);

        i++;

        // Simulate potential external failures
        int retry_attempts = 0;
        while (retry_attempts < RETRY_ATTEMPTS) {
            if (rand() % 10 == 0) {  // Simulated random failure condition
                printf("Simulated failure encountered, attempting retry...\n");
                sleep(1);  // Retry delay
                retry_attempts++;
            } else {
                break;
            }
        }

        if (retry_attempts == RETRY_ATTEMPTS) {
            fprintf(stderr, "Max retries reached, stopping operation\n");
            *populated_count = i;
            return -1;  // Indicate failure due to external dependency issues
        }
    }

    *populated_count = cache.count;
    pthread_mutex_unlock(&cache.lock);
    return 0;
}

int main() {
    size_t populated_count = 0;
    if (populate_NFAPI_CRC_INDICATION_PDU_T(20, &populated_count) == 0) {
        printf("Successfully populated %zu structures.\n", populated_count);
    } else {
        fprintf(stderr, "Failed to populate structures.\n");
    }
    free_cache();
    return 0;
}
