void update_cache(const char *hostname, const struct in_addr *ip_address) {
    int index = get_cache_index(hostname);
    if (index != -1) {
        dns_cache[index].last_accessed = time(NULL);
        memcpy(&dns_cache[index].ip_address, ip_address, sizeof(struct in_addr));
    } else {
        // Implement LRU eviction policy
        int oldest_index = 0;
        for (int i = 1; i < cache_size; ++i) {
            if (dns_cache[i].last_accessed < dns_cache[oldest_index].last_accessed) {
                oldest_index = i;
            }
        }
        strcpy(dns_cache[oldest_index].hostname, hostname);
        memcpy(&dns_cache[oldest_index].ip_address, ip_address, sizeof(struct in_addr));
        dns_cache[oldest_index].last_accessed = time(NULL);
    }
}

struct in_addr resolve_hostname(const char *hostname) {
    struct hostent *host;
    int retry_count = 0;
    while (retry_count < RETRY_LIMIT) {
        pthread_mutex_lock(&cache_lock);
        int cache_index = get_cache_index(hostname);
        if (cache_index != -1) {
            pthread_mutex_unlock(&cache_lock);
            return dns_cache[cache_index].ip_address;
