    // Read hostnames from standard input
    size_t buffer_size = 1024;
    char *input_buffer = malloc(buffer_size);
    size_t num_hostnames = 0;
    while (fgets(input_buffer, buffer_size, stdin)) {
        if (num_hostnames == 0) {
            char **hostnames = malloc(sizeof(char *));
            hostnames[0] = strdup(input_buffer);
            ++num_hostnames;
        } else {
            char **new_hostnames = realloc(hostnames, sizeof(char *) * (num_hostnames + 1));
            new_hostnames[num_hostnames] = strdup(input_buffer);
            free(hostnames);
            hostnames = new_hostnames;
            ++num_hostnames;
        }
    }

    pthread_t threads[10]; // Example thread pool size
    int active_threads = 0;

    for (size_t i = 0; i < num_hostnames; ++i) {
        while (active_threads >= 10) {
            // Wait for a thread to finish
            pthread_join(threads[i % 10], NULL);
            --active_threads;
        }

        char **hostname_args = malloc(sizeof(char *));
        hostname_args[0] = hostnames[i];
        pthread_create(&threads[i % 10], NULL, process_hostnames, hostname_args);
        ++active_threads;
    }

    for (int i = 0; i < active_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(input_buffer);
    for (size_t i = 0; i < num_hostnames; ++i) {
        free(hostnames[i]);
    }
    free(hostnames);
    free(ints);

    fclose(log_file);
    return 0;
}
