void initialize_memory(size_t offset_size, size_t key_size, size_t record_count, int min_value, int max_value) {
    long *offset_array = NULL;
    int *key_array = NULL;
    Record *record_array = NULL;

    if (enable_logging == ENABLED) log_info("Starting memory initialization.");

    pthread_mutex_lock(&lock);

    // Allocate and initialize offset array
    offset_array = malloc(offset_size * sizeof(long));
    if (!offset_array) {
        log_error("Failed to allocate memory for offset array.");
        goto cleanup;
    }

    for (size_t i = 0; i < offset_size; ++i) {
        offset_array[i] = (long)i; // Example initialization
    }

    // Allocate and initialize key array
    key_array = malloc(key_size * sizeof(int));
    if (!key_array) {
        log_error("Failed to allocate memory for key array.");
        free(offset_array);
        goto cleanup;
    }

    for (size_t i = 0; i < key_size; ++i) {
        key_array[i] = (int)i % (max_value - min_value + 1) + min_value; // Example initialization within range
    }

    // Allocate and initialize record array with unique values
    record_array = malloc(record_count * sizeof(Record));
    if (!record_array) {
        log_error("Failed to allocate memory for record array.");
        free(offset_array);
        free(key_array);
        goto cleanup;
    }

    int *used_values = calloc(max_value - min_value + 1, sizeof(int));
    if (!used_values) {
        log_error("Failed to allocate temporary storage for unique value tracking.");
        free(record_array);
        free(key_array);
        free(offset_array);
        pthread_mutex_unlock(&lock);
        return;
    }

    int count = 0;
    for (int i = min_value; i <= max_value && count < record_count; ++i) {
        if (!used_values[i - min_value]) {
            record_array[count].value = i;
            used_values[i - min_value] = 1;
            count++;
        }
    }

    free(used_values);

    if (count != record_count) {
        log_error("Not enough unique values available for the given range.");
        free(record_array);
        free(key_array);
        free(offset_array);
        pthread_mutex_unlock(&lock);
        return;
    }

    // Log success
    if (enable_logging == ENABLED) {
        printf("Memory initialization successful.\n");
    }

cleanup:
    pthread_mutex_unlock(&lock);

    // Free allocated resources in case of failure
    if (!offset_array || !key_array || !record_array) {
        if (offset_array) free(offset_array);
        if (key_array) free(key_array);
        if (record_array) free(record_array);
        log_error("Memory initialization failed. Resources freed.");
    }
}

