int findLargestInteger(const int *keys, size_t size);

int main() {
    srand(time(NULL));

    // Allocate and initialize arrays
    long* offsets = allocateOffsetArray(MAX_OFFSET_SIZE);
    if (!offsets) return 1;

    int* keys = allocateKeyArray(MAX_OFFSET_SIZE);
    if (!keys) {
        free(offsets);
        return 1;
    }

    record* records = allocateRecordArray(NUM_RECORDS, RANGE_MIN, RANGE_MAX);
    if (!records) {
        free(keys);
        free(offsets);
        return 1;
    }

    // Initialize thread-safe storage
    ThreadSafeStorage *storage = initializeThreadSafeStorage();
    if (!storage) {
        free(records);
        free(keys);
        free(offsets);
        return 1;
    }

    int value, numUniqueValues;
    printf("Enter number of integers to input: ");
    scanf("%d", &numUniqueValues);

    printf("Enter %d unique integers in the range [%d, %d]:\n", numUniqueValues, RANGE_MIN, RANGE_MAX);
    for (int i = 0; i < numUniqueValues; ++i) {
        scanf("%d", &value);
        if (!addUniqueValue(storage, value, RANGE_MIN, RANGE_MAX)) {
            printf("Invalid or duplicate input. Please re-enter.\n");
            --i;
        }
    }

    int largest = findLargestInteger(keys, MAX_OFFSET_SIZE);
    printf("The largest integer in the array is: %d\n", largest);

    // Generate NFAPI_CRC_INDICATION_PDU_T list
    size_t nfaPiCount = 5; // Example count
    unsigned long rxUeInfoTag = 12345;
    unsigned long rnti = 67890;

    NFAPI_CRC_INDICATION_PDU_T* indications = generateNFAPICRCIndications(nfaPiCount, rxUeInfoTag, rnti);
    free(indications);

    // Cleanup
    freeThreadSafeStorage(storage);
    free(records);
    free(keys);
    free(offsets);

    return 0;
}

long* allocateOffsetArray(size_t size) {
    return (long*)malloc(size * sizeof(long));
}

int* allocateKeyArray(size_t size) {
    return (int*)malloc(size * sizeof(int));
}

record* allocateRecordArray(size_t size, int rangeMin, int rangeMax) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) return NULL;

    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % (rangeMax - rangeMin + 1) + rangeMin;
    }
    return records;
}

ThreadSafeStorage* initializeThreadSafeStorage() {
    ThreadSafeStorage *storage = (ThreadSafeStorage*)malloc(sizeof(ThreadSafeStorage));
    if (!storage) return NULL;

    pthread_mutex_init(&storage->lock, NULL);
    storage->uniqueList = NULL;
    return storage;
}

void freeThreadSafeStorage(ThreadSafeStorage *storage) {
    UniqueIntNode *current, *tmp;

    pthread_mutex_lock(&storage->lock);
    HASH_ITER(hh, storage->uniqueList, current, tmp) {
        HASH_DEL(storage->uniqueList, current);
        free(current);
    }
    pthread_mutex_unlock(&storage->lock);

    pthread_mutex_destroy(&storage->lock);
    free(storage);
}

int addUniqueValue(ThreadSafeStorage *storage, int value, int minRange, int maxRange) {
    if (value < minRange || value > maxRange) return 0;

    UniqueIntNode *node;
    HASH_FIND_INT(storage->uniqueList, &value, node);

    if (!node) {
        node = (UniqueIntNode*)malloc(sizeof(UniqueIntNode));
        node->uniqueKey = value;

        pthread_mutex_lock(&storage->lock);
        HASH_ADD_INT(storage->uniqueList, uniqueKey, node);
        pthread_mutex_unlock(&storage->lock);
    }

    return 1; // Successfully added
}

NFAPI_CRC_INDICATION_PDU_T* generateNFAPICRCIndications(size_t count, unsigned long rxUeInfoTag, unsigned long rnti) {
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) return NULL;

    for (size_t i = 0; i < count; ++i) {
        array[i].rnti = rnti;
        array[i].crcFlag = rand() % 2;
        HASH_ADD_INT(array, rnti, &array[i]);
    }

    return array;
}

void freeNFAPICRCIndications(NFAPI_CRC_INDICATION_PDU_T *array) {
    if (!array) return;

    NFAPI_CRC_INDICATION_PDU_T *current, *tmp;
    HASH_ITER(hh, array, current, tmp) {
        HASH_DEL(array, current);
        free(current);
    }
}

int findLargestInteger(const int *keys, size_t size) {
    if (!keys || size == 0) return -1;

    int largest = keys[0];
    for (size_t i = 1; i < size; ++i) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }

    return largest;
}
