#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <unistd.h>
#include <errno.h>

#define MAX_INTEGERS 10000000
#define MAX_HOSTNAMES 500

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_tag;
    // Additional fields can be added as needed
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheNode {
    char hostname[256];
    u_char ip_address[4];
    int active;
    struct CacheNode* prev;
    struct CacheNode* next;
} CacheNode;

typedef struct {
    CacheNode* head;
    CacheNode* tail;
    size_t capacity;
    pthread_mutex_t lock;
} LRUCache;

// Global variables
int largest_integer = INT_MIN;
u_char ip_addresses[MAX_HOSTNAMES][4];
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
LRUCache cache;

void initialize_cache(size_t capacity) {
    cache.head = NULL;
    cache.tail = NULL;
    cache.capacity = capacity;
    pthread_mutex_init(&cache.lock, NULL);
}

int get_from_cache(const char* hostname) {
    pthread_mutex_lock(&cache.lock);
    CacheNode* current = cache.head;
    while (current) {
        if (strcmp(current->hostname, hostname) == 0 && current->active) {
            // Move to front
            if (current != cache.head) {
                if (current == cache.tail) {
                    cache.tail = current->prev;
                    cache.tail->next = NULL;
                } else {
                    current->prev->next = current->next;
                    current->next->prev = current->prev;
                }
                current->next = cache.head;
                current->prev = NULL;
                cache.head->prev = current;
                cache.head = current;
            }
            pthread_mutex_unlock(&cache.lock);
            return 1; // Found in cache
        }
        current = current->next;
    }
    pthread_mutex_unlock(&cache.lock);
    return 0; // Not found
}

void add_to_cache(const char* hostname, const u_char ip_address[4]) {
    pthread_mutex_lock(&cache.lock);

    CacheNode* node = malloc(sizeof(CacheNode));
    if (!node) {
        pthread_mutex_unlock(&cache.lock);
        return;
    }

    strncpy(node->hostname, hostname, sizeof(node->hostname));
    memcpy(node->ip_address, ip_address, 4);
    node->active = 1;

    if (cache.head == NULL) {
        cache.head = node;
        cache.tail = node;
        node->prev = NULL;
        node->next = NULL;
    } else {
        node->next = cache.head;
        cache.head->prev = node;
        cache.head = node;
        node->prev = NULL;

        if (cache.capacity < ++node_count) {
            CacheNode* to_remove = cache.tail;
            cache.tail = to_remove->prev;
            cache.tail->next = NULL;
            free(to_remove);
            --node_count;
        }
    }

    pthread_mutex_unlock(&cache.lock);
}

int dns_lookup(const char* hostname, u_char ip_address[4]) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip_address, &(ipv4->sin_addr), sizeof(struct in_addr));
        break;
    }

    freeaddrinfo(res);
    return 0;
}

void* resolve_hostname(void* arg) {
    char* hostname = (char*)arg;
    u_char ip[4];

    if (!get_from_cache(hostname)) {
        int retries = 3;
        while (retries--) {
            if (dns_lookup(hostname, ip) == 0) {
                add_to_cache(hostname, ip);
                pthread_mutex_lock(&log_lock);
                printf("Resolved %s to %u.%u.%u.%u\n", hostname,
                       ip[0], ip[1], ip[2], ip[3]);
                pthread_mutex_unlock(&log_lock);
                break;
            }
            sleep(1 << (3 - retries)); // Exponential backoff
        }
    }

    return NULL;
}

void processNFAPIAndDNS() {
    int num_integers, value;
    char hostname[MAX_HOSTNAMES][256];
    pthread_t threads[MAX_HOSTNAMES];
    size_t cache_capacity = 100; // Example capacity

    initialize_cache(cache_capacity);

    // Read integers from standard input
    printf("Enter number of integers: ");
    scanf("%d", &num_integers);
    for (int i = 0; i < num_integers && i < MAX_INTEGERS; ++i) {
        scanf("%d", &value);
        if (value > largest_integer) {
            largest_integer = value;
        }
    }

    // Read hostnames
    printf("Enter number of hostnames: ");
    int num_hostnames;
    scanf("%d", &num_hostnames);
    for (int i = 0; i < num_hostnames && i < MAX_HOSTNAMES; ++i) {
        scanf("%s", hostname[i]);
    }

    // Concurrent DNS resolution
    for (int i = 0; i < num_hostnames; ++i) {
        pthread_create(&threads[i], NULL, resolve_hostname, (void*)hostname[i]);
    }
    for (int i = 0; i < num_hostnames; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup and reset mock library
    printf("Processing complete. Largest integer: %d\n", largest_integer);
}

int main() {
    processNFAPIAndDNS();
    return 0;
}
