#define RETENTION_TIME_SECONDS 3600 // Example retention time

typedef struct Measurement {
    double latency;
    double throughput;
    double packet_loss;
} Measurement;

typedef struct NetworkPerformanceMetrics {
    long timestamp;
    uint32_t session_id;
    int measurement_count;
    Measurement *measurements;
    struct NetworkPerformanceMetrics *next;
} NetworkPerformanceMetrics;

typedef struct EventRecord {
    char message[256];
    size_t message_length;
} EventRecord;

pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

NetworkPerformanceMetrics* initialize_metrics(long timestamp, uint32_t session_id, int measurement_count) {
    NetworkPerformanceMetrics *new_node = (NetworkPerformanceMetrics *)malloc(sizeof(NetworkPerformanceMetrics));
    if (!new_node) return NULL;

    new_node->timestamp = timestamp;
    new_node->session_id = session_id;
    new_node->measurement_count = measurement_count;
    new_node->measurements = (Measurement *)malloc(measurement_count * sizeof(Measurement));
    if (!new_node->measurements) {
        free(new_node);
        return NULL;
    }

    new_node->next = NULL;
    return new_node;
}

void insert_metrics(NetworkPerformanceMetrics **head, NetworkPerformanceMetrics *new_node) {
    pthread_mutex_lock(&list_lock);
    if (*head == NULL) {
        *head = new_node;
    } else {
        NetworkPerformanceMetrics *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&list_lock);
}

void cleanup_metrics(NetworkPerformanceMetrics **head, long retention_time) {
    pthread_mutex_lock(&list_lock);
    NetworkPerformanceMetrics *current = *head, *prev = NULL;
    time_t now = time(NULL);

    while (current != NULL) {
        if ((now - current->timestamp) > retention_time) {
            if (prev == NULL) { // Head node
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->measurements);
            NetworkPerformanceMetrics *temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list_lock);
}

void initialize_event_records(EventRecord **records, int count) {
    *records = (EventRecord *)malloc(count * sizeof(EventRecord));
    if (!*records) return;

    for (int i = 0; i < count; ++i) {
        (*records)[i].message_length = strlen("Predefined ASCII String");
        strncpy((*records)[i].message, "Predefined ASCII String", sizeof((*records)[i].message));
    }
}

void process_event_records(EventRecord *records, int count) {
    // Placeholder for processing logic
    for (int i = 0; i < count; ++i) {
        printf("Processing record %d: %s\n", i + 1, records[i].message);
    }
}

// Example of how you might periodically clean up metrics in a separate thread
void* periodic_cleanup(void *arg) {
    NetworkPerformanceMetrics **metrics_list = (NetworkPerformanceMetrics **)arg;
    while (1) {
        sleep(60); // Run cleanup every minute
        cleanup_metrics(metrics_list, RETENTION_TIME_SECONDS);
    }
    return NULL;
}

// Main function to demonstrate usage
int main() {
    NetworkPerformanceMetrics *metrics_head = NULL;

    // Initialize and insert metrics
    long timestamps[] = {1609459200, 1609462800, 1609466400};
    uint32_t session_ids[] = {1, 2, 3};
    for (int i = 0; i < 3; ++i) {
        NetworkPerformanceMetrics *metrics = initialize_metrics(timestamps[i], session_ids[i], 5);
        insert_metrics(&metrics_head, metrics);
    }

    // Initialize event records
    EventRecord *event_records;
    initialize_event_records(&event_records, 3);

    // Process event records
    process_event_records(event_records, 3);

    // Start periodic cleanup thread
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, periodic_cleanup, &metrics_head);

    // Join cleanup thread for demonstration purposes (in real application, you might not join)
    pthread_join(cleanup_thread, NULL);

    // Cleanup resources
    while (metrics_head != NULL) {
        NetworkPerformanceMetrics *temp = metrics_head;
        metrics_head = metrics_head->next;
        free(temp->measurements);
        free(temp);
    }
    free(event_records);

    return 0;
}
