        frames[i]->payload = (char*)calloc(pdu_header.length, sizeof(char));
        if (!frames[i]->payload) {
            frames[i]->errorStatus = ERROR_PAYLOAD_ALLOC;
            log_message("Failed to allocate payload memory");
            free(frames[i]);
            continue;
        }

        // Fetch external metadata and handle errors
        RadioFrame *external_data = fetch_external_metadata();
        if (external_data && external_data->pduHeader.length == pdu_header.length) {
            memcpy(frames[i]->payload, external_data->payload, pdu_header.length);
            free(external_data); // Ensure we don't leak the fetched metadata
        } else {
            log_message("Failed to fetch or validate external metadata");
            frames[i]->errorStatus = ERROR_METADATA_FETCH;
            continue;  // Skip adding this frame if metadata is invalid/missing
        }

        // Set error status based on successful operations
        frames[i]->errorStatus = NO_ERROR;

        (*count)++;
    }

    return frames;
}

// Logging function for monitoring and debugging purposes
void log_message(const char* message) {
    printf("Log: %s\n", message);
}

// Simulated external metadata fetch function
RadioFrame* fetch_external_metadata() {
    // This is a placeholder to simulate fetching metadata; 
    // replace with actual implementation as needed.
    static int call_count = 0;
    if (call_count < 5) {  // Simulate successful metadata on first few calls
        RadioFrame *metadata_frame = (RadioFrame*)malloc(sizeof(RadioFrame));
        if (!metadata_frame) return NULL;

        PDUHeader pdu_header;
        pdu_header.length = rand() % 256 + 1; 

        metadata_frame->pduHeader = pdu_header;
        metadata_frame->payload = (char*)calloc(pdu_header.length, sizeof(char));
        if (!metadata_frame->payload) {
            free(metadata_frame);
            return NULL;
        }
        memset(metadata_frame->payload, '*', pdu_header.length); // Dummy payload
        call_count++;
        return metadata_frame;
    } else {
        return NULL;  // Simulate failure after some calls
    }
}

int main() {
    size_t frame_count = 0;
    int num_frames = 10;

    RadioFrame** radio_frames = init_radio_frames(num_frames, &frame_count);
    printf("Successfully initialized %zu frames.\n", frame_count);

    // Cleanup allocated memory
    for (size_t i = 0; i < frame_count; ++i) {
        free(radio_frames[i]->payload);
        free(radio_frames[i]);
    }
