#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define CRCFLAG_SIZE sizeof(unsigned char)

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char *variable_string;
    int value;
    double timestamp;
} record;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array[MAX_RECORDS];
    long *offsets_array[MAX_RECORDS];
    int *keys_array[MAX_RECORDS];
    record *records_array[MAX_RECORDS];

    size_t pdu_count;
    size_t offsets_count;
    size_t keys_count;
    size_t records_count;

    pthread_mutex_t lock;
} DataManagementSystem;

void initialize_system(DataManagementSystem *dms) {
    dms->pdu_count = 0;
    dms->offsets_count = 0;
    dms->keys_count = 0;
    dms->records_count = 0;
    pthread_mutex_init(&dms->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(unsigned int rx_tag, unsigned int rnti, unsigned int crc_tag) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->RX_UE_INFORMATION_TAG = rx_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = crc_tag;
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    return pdu;
}

long* create_offset(long offset) {
    long *offset_ptr = (long *)malloc(sizeof(long));
    if (!offset_ptr) return NULL;

    *offset_ptr = offset;
    return offset_ptr;
}

int* create_key(int key) {
    int *key_ptr = (int *)malloc(sizeof(int));
    if (!key_ptr) return NULL;

    *key_ptr = key;
    return key_ptr;
}

record* create_record(const char *str, int value, double timestamp) {
    record *rec = (record *)malloc(sizeof(record));
    if (!rec) return NULL;

    rec->variable_string = strdup(str);
    rec->value = value;
    rec->timestamp = timestamp;

    return rec;
}

void add_pdu(DataManagementSystem *dms, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&dms->lock);

    if (dms->pdu_count < MAX_RECORDS) {
        dms->pdu_array[dms->pdu_count++] = pdu;
    }

    pthread_mutex_unlock(&dms->lock);
}

void add_offset(DataManagementSystem *dms, long *offset) {
    pthread_mutex_lock(&dms->lock);

    if (dms->offsets_count < MAX_RECORDS) {
        dms->offsets_array[dms->offsets_count++] = offset;
    }

    pthread_mutex_unlock(&dms->lock);
}

void add_key(DataManagementSystem *dms, int *key) {
    pthread_mutex_lock(&dms->lock);

    if (dms->keys_count < MAX_RECORDS) {
        dms->keys_array[dms->keys_count++] = key;
    }

    pthread_mutex_unlock(&dms->lock);
}

void add_record(DataManagementSystem *dms, record *rec) {
    pthread_mutex_lock(&dms->lock);

    if (dms->records_count < MAX_RECORDS) {
        dms->records_array[dms->records_count++] = rec;
    }

    pthread_mutex_unlock(&dms->lock);
}

void deallocate_system(DataManagementSystem *dms) {
    pthread_mutex_lock(&dms->lock);

    for (size_t i = 0; i < dms->pdu_count; ++i) {
        free(dms->pdu_array[i]);
    }
    for (size_t i = 0; i < dms->offsets_count; ++i) {
        free(dms->offsets_array[i]);
    }
    for (size_t i = 0; i < dms->keys_count; ++i) {
        free(dms->keys_array[i]);
    }
    for (size_t i = 0; i < dms->records_count; ++i) {
        free(dms->records_array[i]->variable_string);
        free(dms->records_array[i]);
    }

    pthread_mutex_unlock(&dms->lock);
    pthread_mutex_destroy(&dms->lock);
}

int main() {
    DataManagementSystem dms;
    initialize_system(&dms);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu(123, 456, 789);
    add_pdu(&dms, pdu);

    long *offset = create_offset(1000);
    add_offset(&dms, offset);

    int *key = create_key(42);
    add_key(&dms, key);

    record *rec = create_record("example", 7, time(NULL));
    add_record(&dms, rec);

    // Clean up
    deallocate_system(&dms);

    return 0;
}
```

