RadioFrame* createRadioFrame(const PDUHeader *header) {
    if (!validatePDUHeader(header)) {
        fprintf(stderr, "Invalid PDU Header\n");
        return NULL;
    }

    RadioFrame *frame = (RadioFrame *)malloc(sizeof(RadioFrame));
    if (!frame) {
        perror("Failed to allocate memory for RadioFrame");
        return NULL;
    }

    frame->header = *header;
    frame->payload = (char *)malloc(header->length);
    if (!frame->payload) {
        perror("Failed to allocate memory for Payload");
        free(frame);
        return NULL;
    }

    // Default initialization
    frame->errorStatus = 0;

    return frame;
}

int addRadioFrame(RadioFrameList *list, const PDUHeader *header) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= MAX_FRAMES) {
        fprintf(stderr, "Maximum number of frames reached\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    RadioFrame *frame = createRadioFrame(header);
    if (!frame) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    list->frames[list->count++] = frame;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void freeRadioFrameList(RadioFrameList *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->frames[i]) {
            free(list->frames[i]->payload);
            free(list->frames[i]);
        }
    }

