// Logging function for monitoring and debugging
void log_message(const char *message) {
    // Simple logging implementation (can be enhanced)
    printf("%s\n", message);
}

// Function to process metadata string
char* process_metadata_string(const char *input, size_t size_limit) {
    if (strlen(input) >= size_limit) {
        return NULL;
    }

    char *result = malloc(strlen(input) + 2); // +1 for '\0' and +1 for '/'
    if (!result) {
        log_message("Memory allocation failed");
        return NULL;
    }

    strcpy(result, input);
    strcat(result, "/");
    return result;
}

// Function to initialize and populate RadioFrame
RadioFrame* create_radio_frame(const PDUHeader *header, const char *metadata, size_t metadata_size_limit) {
    if (!header || header->length <= 0) {
        log_message("Invalid PDU Header");
        return NULL;
    }

    pthread_mutex_lock(&frameMutex);

    // Allocate memory for RadioFrame
    RadioFrame *frame = malloc(sizeof(RadioFrame));
    if (!frame) {
        log_message("Memory allocation failed for RadioFrame");
        pthread_mutex_unlock(&frameMutex);
        return NULL;
    }

    frame->header = *header;

    // Process metadata
    char *processed_metadata = process_metadata_string(metadata, metadata_size_limit);
    if (!processed_metadata) {
        frame->error = MISSING_METADATA;
        log_message("Metadata processing failed");
        free(frame);  // Free allocated RadioFrame memory
        pthread_mutex_unlock(&frameMutex);
        return NULL;
    }

    // Allocate payload based on header length
    frame->payload.data = malloc(header->length);
    if (!frame->payload.data) {
        frame->error = DATA_CORRUPTED;
        log_message("Memory allocation failed for Payload");
        free(processed_metadata);
        free(frame);  // Free allocated RadioFrame memory
        pthread_mutex_unlock(&frameMutex);
        return NULL;
    }

    // Here you would copy the metadata to the payload, e.g., memcpy()
    strncpy((char *)frame->payload.data, processed_metadata, header->length);

    frame->error = NO_ERROR;

    free(processed_metadata);  // Free allocated metadata
    pthread_mutex_unlock(&frameMutex);

    log_message("RadioFrame created successfully");
    return frame;
}

