#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char DataTransmissionStatus; // e.g., 'S' for Success, 'F' for Failed
    int ErrorCodes[5];           // Array to hold up to 5 error codes
} EventDetails;

typedef struct {
    int DeviceIdentifier;
    time_t EventTime;
    EventDetails EventDetails;
} NetworkEvent;

// Global mutex for thread safety
pthread_mutex_t eventMutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototype for logging service integration (simulated)
void log_event(const NetworkEvent* event);

void initialize_network_events(NetworkEvent** events, size_t num_events) {
    if (!events || num_events == 0) return;

    *events = malloc(num_events * sizeof(NetworkEvent));
    if (*events == NULL) {
        perror("Failed to allocate memory for network events");
        exit(EXIT_FAILURE);
    }

    // Simulating real-world conditions using random numbers
    srand(time(NULL));

    pthread_t threads[num_events];
    for (size_t i = 0; i < num_events; ++i) {
        pthread_create(&threads[i], NULL, [] (void* arg) -> void* {
            size_t idx = *(size_t*)arg;

            pthread_mutex_lock(&eventMutex);
            NetworkEvent* event = &(*((NetworkEvent**)arg)[idx]);

            // Populate DeviceIdentifier
            event->DeviceIdentifier = rand() % 1000;  // Random identifier

            // Populate EventTime with current time
            event->EventTime = time(NULL);

            // Simulate network condition-based probability for EventDetails
            int peak_traffic_probability = (rand() % 100) < 20; // 20% chance during peak traffic
            int intermittent_connectivity = (rand() % 100) < 10; // 10% chance of connectivity issue

            if (!peak_traffic_probability && !intermittent_connectivity) {
                event->EventDetails.DataTransmissionStatus = 'S'; // Success
                for (int j = 0; j < 5; ++j)
                    event->EventDetails.ErrorCodes[j] = 0; // No errors
            } else {
                event->EventDetails.DataTransmissionStatus = 'F'; // Failure

                // Assign error codes based on conditions
                if (peak_traffic_probability) {
                    event->EventDetails.ErrorCodes[0] = 1001; // Error code for peak traffic
                }

                if (intermittent_connectivity) {
                    event->EventDetails.ErrorCodes[1] = 1002; // Error code for connectivity issue
                }

                // Assign additional random errors
                int error_count = rand() % 3 + 1;
                for (int j = 0; j < error_count && j < 5; ++j) {
                    event->EventDetails.ErrorCodes[j + 2] = rand() % 2000;
                }
            }

            // Log the event
            log_event(event);

            pthread_mutex_unlock(&eventMutex);

            return NULL;
        }, (void*)&i);
    }

    for (size_t i = 0; i < num_events; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Placeholder function for logging service integration
void log_event(const NetworkEvent* event) {
    // Simulate logging to an external service, handle potential I/O latency here.
    printf("Logged Event: Device %d at time %ld with status %c\n",
           event->DeviceIdentifier, event->EventTime, event->EventDetails.DataTransmissionStatus);
}

void free_network_events(NetworkEvent** events) {
    if (events && *events) {
        free(*events);
        *events = NULL;
    }
}
