#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 1000
#define MIN_RANGE -1000
#define MAX_RANGE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_message(const char *message) {
    printf("LOG: %s\n", message);
}

int is_valid_integer(int num) {
    return num >= MIN_RANGE && num <= MAX_RANGE;
}

int read_integers(int **numbers, int *count) {
    int temp, i = 0;
    *numbers = (int *)malloc(sizeof(int) * MAX_ELEMENTS);

    if (*numbers == NULL) {
        log_message("Memory allocation failed.");
        return -1;
    }

    while (scanf("%d", &temp) == 1) {
        if (!is_valid_integer(temp)) {
            free(*numbers);
            fprintf(stderr, "Error: Integer %d out of range.\n", temp);
            return -2;
        }

        (*numbers)[i++] = temp;

        if (i >= MAX_ELEMENTS) break;
    }

    *count = i;
    log_message("Input reading complete.");
    return 0;
}

int set_crc_flag() {
    srand(time(NULL));
    return rand() % 2; // Returns 0 or 1 with equal probability
}

void create_crc_indication_pdu(int *numbers, int count, NFAPI_CRC_INDICATION_PDU_T **pdu_list) {
    *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);

    if (*pdu_list == NULL) {
        log_message("Memory allocation for PDU list failed.");
        return;
    }

    for (int i = 0; i < count; ++i) {
        (*pdu_list)[i].RX_UE_INFORMATION_TAG = numbers[i];
        (*pdu_list)[i].RNTI = i + 1; // Example value, modify as needed
        (*pdu_list)[i].CRC_INDICATION_REL8_TAG = (numbers[i] % 10) + 1; // Example calculation
        (*pdu_list)[i].CRCFLAG = set_crc_flag();
    }

