#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    char CRC_INDICATION_REL8_TAG[64];
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned int crc_error_count;
    time_t last_log_time;
    pthread_mutex_t metric_lock;
} CRCList;

CRCList* create_crc_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->crc_error_count = 0;
    list->last_log_time = time(NULL);
    pthread_mutex_init(&list->metric_lock, NULL);
    return list;
}

int is_rnti_unique(CRCList* list, unsigned int rnti) {
    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) return 0;
        current = current->next;
    }
    return 1;
}

void log_crc_errors(CRCList* list) {
    pthread_mutex_lock(&list->metric_lock);
    time_t now = time(NULL);
    if (difftime(now, list->last_log_time) >= 60) { // Log every minute
        printf("Total CRC-indicated errors: %u\n", list->crc_error_count);
        list->crc_error_count = 0;
        list->last_log_time = now;
    }
    pthread_mutex_unlock(&list->metric_lock);
}

void add_crc_indication(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!is_rnti_unique(list, pdu.RNTI)) return;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;
    memcpy(&new_node->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;

    // Simulate random CRCFLAG setting
    new_node->data.CRCFLAG = rand() % 2;
    if (new_node->data.CRCFLAG) {
        pthread_mutex_lock(&list->metric_lock);
        list->crc_error_count++;
        pthread_mutex_unlock(&list->metric_lock);
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_crc_indication(CRCList* list, unsigned int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current) {
        if (current->data.RNTI == rnti) {
            if (prev) prev->next = current->next;
            else list->head = current->next;

            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void cleanup_crc_list(CRCList* list) {
    Node *current = list->head, *next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    pthread_mutex_destroy(&list->metric_lock);
    free(list);
}

int main() {
    CRCList* crc_list = create_crc_list();
    if (!crc_list) return 1;

    // Simulate adding and removing elements
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();

    add_crc_indication(crc_list, pdu);
    remove_crc_indication(crc_list, pdu.RNTI);

    // Periodically log CRC errors
    while (1) {
        log_crc_errors(crc_list);
        sleep(5); // Check every 5 seconds
    }

    cleanup_crc_list(crc_list);
    return 0;
}
