// Add a new UE context or update an existing one
int add_or_update_ue_context(UE_Context_Manager *manager, LTE_RRC_UE_CONTEXT *context) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->id == context->id) {
            // Update existing context
            memcpy(manager->contexts[i], context, sizeof(LTE_RRC_UE_CONTEXT));
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    if (manager->count < MAX_UE_CONTEXTS) {
        manager->contexts[manager->count++] = context;
        pthread_mutex_unlock(&manager->lock);
        return 0;
    }

    pthread_mutex_unlock(&manager->lock);
    fprintf(stderr, "Error: Maximum UE contexts reached.\n");
    return -1;
}

// Retrieve a specific UE context by its ID
LTE_RRC_UE_CONTEXT *get_ue_context_by_id(UE_Context_Manager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->id == id) {
            LTE_RRC_UE_CONTEXT *context = malloc(sizeof(LTE_RRC_UE_CONTEXT));
            memcpy(context, manager->contexts[i], sizeof(LTE_RRC_UE_CONTEXT));
            pthread_mutex_unlock(&manager->lock);
            return context;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    fprintf(stderr, "Error: UE context with ID %d not found.\n");
    return NULL;
}

// Deallocate a specific UE context by its ID
int remove_ue_context_by_id(UE_Context_Manager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->id == id) {
            free(manager->contexts[i]);
            memmove(&manager->contexts[i], &manager->contexts[i + 1],
                    sizeof(LTE_RRC_UE_CONTEXT *) * (manager->count - i - 1));
            --manager->count;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    fprintf(stderr, "Error: UE context with ID %d not found for removal.\n");
    return -1;
}

// Initialize the manager
void init_ue_context_manager(UE_Context_Manager *manager) {
    memset(manager, 0, sizeof(UE_Context_Manager));
    pthread_mutex_init(&manager->lock, NULL);
}

// Clean up the manager
