    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    manager->total_attempts = 0;
    manager->successful_creations = 0;
}

// Add a node to the list in a thread-safe manner
int add_to_list(ListManager* manager, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&manager->lock);

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    new_node->next = manager->head;
    manager->head = new_node;
    manager->count++;
    manager->successful_creations++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

