            int result = add_to_list(manager, data);
            if (result == 0) break;

            log_error("Failed to allocate node");
            attempts++;
            usleep(RETRY_BACKOFF_MS * 1000); // Backoff before retrying
        }
    }

    return manager->successful_creations;
}

// Clean up and free resources
void destroy_list(ListManager* manager) {
    pthread_mutex_lock(&manager->lock);
    Node* current = manager->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    manager->count = 0;

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

