    pthread_mutex_lock(&list.lock);

    if (list.memory_usage + calculate_memory_size(data) > MEMORY_LIMIT || 
        list.head == NULL && list.memory_usage + calculate_memory_size(data) > MEMORY_LIMIT) {
        pthread_mutex_unlock(&list.lock);
        return -1; // Memory limit exceeded
    }

    Node* current = list.head;
    while (current) {
        if (current->data.RNTI == data.RNTI) {
            pthread_mutex_unlock(&list.lock);
            return 0; // Duplicate RNTI
        }
        current = current->next;
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list.lock);
        return -1; // Memory allocation failed
    }

    list.memory_usage += calculate_memory_size(data);

    if (list.head == NULL || list.memory_usage > MEMORY_LIMIT / 2) {
        Node* temp = list.head;
        list.head = new_node;
        new_node->next = temp;
    } else {
        current = list.head;
        while (current->next) current = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&list.lock);
    return 1; // Success
}

int delete_entry(unsigned short rnti) {
    pthread_mutex_lock(&list.lock);

    Node *current = list.head, *prev = NULL;

    while (current && current->data.RNTI != rnti) {
        prev = current;
        current = current->list.head;
    }

    if (!current) {
        pthread_mutex_unlock(&list.lock);
        return 0; // Not found
    }

    list.memory_usage -= calculate_memory_size(current->data);

    if (prev == NULL) {
        list.head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list.lock);
    return 1; // Success
}

void* iterator(void* arg) {
    pthread_mutex_lock(&list.lock);

    Node* current = list.head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &current->data;
        printf("RNTI: %u, CRCFLAG: %d\n", pdu->RNTI, pdu->CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list.lock);
    return NULL;
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu1 = {1, 100, 2, rand() % 2};
    add_entry(pdu1);

    NFAPI_CRC_INDICATION_PDU_T* iterator_thread = malloc(sizeof(pthread_t));
    if (iterator_thread) {
        pthread_create(iterator_thread, NULL, iterator, NULL);
        pthread_join(*iterator_thread, NULL);
    }

    delete_entry(100);

    free_list();
    return 0;
}
