CRC_INDICATION_LIST* create_crc_indication_list(size_t initial_size) {
    CRC_INDICATION_LIST *list = malloc(sizeof(CRC_INDICATION_LIST));
    if (!list) return NULL;

    list->data = calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->offset_values = calloc(initial_size, sizeof(long));
    list->keys = calloc(initial_size, sizeof(int));
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void free_crc_indication_list(CRC_INDICATION_LIST *list) {
    if (list) {
        free(list->data);
        free(list->offset_values);
        free(list->keys);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_record(CRC_INDICATION_LIST *list, NFAPI_CRC_INDICATION_PDU_T record, long offset_value, int key) {
    pthread_mutex_lock(&list->lock);

    size_t new_size = list->count + 1;
    if (new_size > list->data && list->offset_values && list->keys) { // Reallocate memory
        NFAPI_CRC_INDICATION_PDU_T *temp_data = realloc(list->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        long *temp_offset_values = realloc(list->offset_values, new_size * sizeof(long));
        int *temp_keys = realloc(list->keys, new_size * sizeof(int));

        if (!temp_data || !temp_offset_values || !temp_keys) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }

        list->data = temp_data;
        list->offset_values = temp_offset_values;
        list->keys = temp_keys;
    }

    record.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    list->data[list->count] = record;
    list->offset_values[list->count] = offset_value;
    list->keys[list->count] = key;
    list->count++;

    pthread_mutex_unlock(&list->lock);

    log_event("Record added successfully");
    return 0; // Success
}

