    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        operation(arg);

        if (/* success condition */) {
            return 0;
        }

        usleep(RETRY_BACKOFF_MS * 1000); // Backoff before retrying
    }

    log_event("Operation failed after retries");
    return -1; // Failed after all attempts
}

