void cleanup_outdated_metrics(MetricsLinkedList* list, time_t retention_time) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (difftime(time(NULL), current->data.timestamp) > retention_time) {
            if (prev == NULL) {  // Removing head
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->data.measurement_results);
            Node *to_delete = current;
            current = current->next;
            free(to_delete);
            list->size--;
        } else {
            prev = current;
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

