// Delete a metric by session ID
void delete_metric_by_session_id(MetricsLinkedList* list, const char* session_id) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (strcmp(current->data.session_id, session_id) == 0) {
            if (prev == NULL) {  // Removing head
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->data.measurement_results);
            free(current);
            list->size--;
            break;
        }
        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Retrieve a metric by session ID
NetworkPerformanceMetric* retrieve_metric_by_session_id(MetricsLinkedList* list, const char* session_id) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current != NULL) {
        if (strcmp(current->data.session_id, session_id) == 0) {
            NetworkPerformanceMetric* metric = &current->data;
            // Cache retrieval logic
            pthread_mutex_unlock(&list->lock);
            return metric; // Return a pointer to the data
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

