    }
    list->capacity = initial_capacity;
    list->count = 0;
    return list;
}

// Resize the CRC list.
void resize_crc_list(CRCList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        log_error("Failed to resize data array.");
        return;
    }
    list->data = new_data;
    list->capacity = new_capacity;
}

// Append a new element to the CRC list.
bool append_crc_indication(CRCList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 4;
        resize_crc_list(list, new_capacity);
        if (!list->data) return false; // Check if resize failed.
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == pdu.RNTI) {
            log_info("Duplicate RNTI detected, replacing existing entry.");
            list->data[i] = pdu;
            return true;
        }
    }

    list->data[list->count++] = pdu;
    return true;
}

// Retrieve an element by RNTI.
NFAPI_CRC_INDICATION_PDU_T* get_crc_indication_by_rnti(CRCList *list, uint16_t rnti) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].RNTI == rnti) {
            return &list->data[i];
        }
    }
    log_info("RNTI not found.");
    return NULL;
}

// Export the CRC list to a binary format.
bool export_crc_list(CRCList *list, const char *filename) {
