    if (!file) {
        log_error("Failed to open file for writing.");
        return false;
    }

    // Write version number and count for backward compatibility.
    uint8_t version = 1;
    fwrite(&version, sizeof(version), 1, file);
    fwrite(&list->count, sizeof(list->count), 1, file);

    if (fwrite(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file) != list->count) {
        log_error("Failed to write data to file.");
        fclose(file);
        return false;
    }

    fclose(file);
    log_info("CRC list exported successfully.");
    return true;
}

// Import the CRC list from a binary format.
bool import_crc_list(CRCList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_error("Failed to open file for reading.");
        return false;
    }

    uint8_t version;
    fread(&version, sizeof(version), 1, file);
    if (version != 1) {
        log_error("Unsupported file version.");
        fclose(file);
        return false;
    }

    size_t count;
    fread(&count, sizeof(count), 1, file);

    // Resize and load data.
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        log_error("Failed to allocate memory for import.");
        fclose(file);
        return false;
    }

    fread(new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);

    // Replace current list data with imported data.
    free(list->data);
    list->data = new_data;
    list->capacity = count;
    list->count = count;

    fclose(file);
    log_info("CRC list imported successfully.");
    return true;
}

// Clear the CRC list.
void clear_crc_list(CRCList *list) {
    free(list->data);
    list->data = NULL;
    list->capacity = 0;
    list->count = 0;
}

// Free resources associated with the CRC list.
void destroy_crc_list(CRCList *list) {
    clear_crc_list(list);
    free(list);
}
