['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <zlib.h>  // For compression/decompression
#include <stdint.h>

#define MAX_MESSAGES 10000

typedef struct {
    // Define TLVEncoder, NAS_Message, and LTE_DL_CCCH_Message_Type1_T as per your requirements.
} TLVEncoder;

typedef struct {
    int message_type;
    char content[256];
} NAS_Message;

typedef struct {
    TLVEncoder encoder;
    NAS_Message nas_message;
} LTE_DL_CCCH_Message_Type1_T;

typedef struct {
    LTE_DL_CCCH_Message_Type1_T *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;  // For thread-safe operations
} MessagePool;

// Logging function for errors and system health
void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_info(const char* message) {
    printf("Info: %s\n", message);
}

MessagePool* init_message_pool(size_t initial_capacity) {
    MessagePool *pool = malloc(sizeof(MessagePool));
    if (!pool) {
        log_error("Failed to allocate memory for message pool");
        return NULL;
    }

    pool->messages = calloc(initial_capacity, sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!pool->messages) {
        free(pool);
        log_error("Failed to allocate memory for messages");
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    log_info("Message pool initialized");
    return pool;
}

void resize_message_pool(MessagePool *pool) {
    size_t new_capacity = pool->capacity * 2;
    LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(pool->messages, new_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!new_messages) {
        log_error("Failed to resize message pool");
        return;
    }

    pool->messages = new_messages;
    pool->capacity = new_capacity;
}

void free_message_pool(MessagePool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->messages);
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
    log_info("Message pool freed");
}

int add_random_message(MessagePool *pool) {
    if (pthread_mutex_trylock(&pool->lock) != 0) return -1;

    if (pool->count >= pool->capacity) {
        resize_message_pool(pool);
        pthread_mutex_unlock(&pool->lock);
        return add_random_message(pool); // Retry after resizing
    }

    LTE_DL_CCCH_Message_Type1_T *msg = &pool->messages[pool->count++];
    srand(time(NULL) + rand());
    msg->nas_message.message_type = rand() % 10;  // Random message type
    snprintf(msg->nas_message.content, sizeof(msg->nas_message.content), "Message content %d", pool->count);

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Compression function using zlib
int compress_data(const void *data, size_t data_size, unsigned char **compressed_data) {
    uLongf compressed_size = compressBound(data_size);
    *compressed_data = malloc(compressed_size);

    if (!*compressed_data) {
        log_error("Failed to allocate memory for compression");
        return -1;
    }

    int result = compress(*compressed_data, &compressed_size, (const unsigned char *)data, data_size);
    if (result != Z_OK) {
        free(*compressed_data);
        *compressed_data = NULL;
        log_error("Compression failed");
        return -1;
    }

    return 0; // Success
}

// Decompression function using zlib
int decompress_data(const unsigned char *compressed_data, size_t compressed_size, void **decompressed_data) {
    uLongf decompressed_size = compressBound(compressed_size);  // Approximation
    *decompressed_data = malloc(decompressed_size);

    if (!*decompressed_data) {
        log_error("Failed to allocate memory for decompression");
        return -1;
    }

    int result = uncompress((unsigned char *)*decompressed_data, &decompressed_size, compressed_data, compressed_size);
    if (result != Z_OK) {
        free(*decompressed_data);
        *decompressed_data = NULL;
        log_error("Decompression failed");
        return -1;
    }

    return 0; // Success
}

void* thread_function(void *arg) {
    MessagePool *pool = (MessagePool *)arg;

    for (size_t i = 0; i < MAX_MESSAGES; ++i) {
        if (add_random_message(pool) != 0) {
            log_error("Failed to add message");
        }

        // Example of compression
        unsigned char *compressed_data;
        if (compress_data(&pool->messages[pool->count - 1], sizeof(LTE_DL_CCCH_Message_Type1_T), &compressed_data) == 0) {
            free(compressed_data);  // Free compressed data after use
        }
    }

    return NULL;
}

void init_system(size_t num_threads, size_t initial_capacity) {
    pthread_t threads[num_threads];
    MessagePool *pools = malloc(num_threads * sizeof(MessagePool));

    for (size_t i = 0; i < num_threads; ++i) {
        pools[i] = *init_message_pool(initial_capacity);
        if (!pools[i].messages) break;

        pthread_create(&threads[i], NULL, thread_function, &pools[i]);
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
        free_message_pool(&pools[i]);
    }

    free(pools);
}

int main() {
    init_system(4, 100); // Example usage with 4 threads and initial capacity of 100
    return 0;
}
```

