#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define structures
typedef struct {
    int data; // Placeholder for actual LMAC_CONFIG data
} LMAC_CONFIG;

typedef struct {
    int frame_data; // Placeholder for actual MAC_FRAME data
} MAC_FRAME;

typedef struct {
    LMAC_CONFIG config;
    MAC_FRAME *frames;
    size_t frame_count;
} MAC_CONTEXT_T;

// Dynamic array and its management
typedef struct {
    MAC_CONTEXT_T **array;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex; // For thread safety
} MAC_CONTEXT_ARRAY;

// Function prototypes
MAC_CONTEXT_ARRAY* create_context_array(size_t initial_capacity);
void destroy_context_array(MAC_CONTEXT_ARRAY *context_array);
int add_context(MAC_CONTEXT_ARRAY *context_array, LMAC_CONFIG config, const MAC_FRAME *frames, size_t frame_count);
int remove_context(MAC_CONTEXT_ARRAY *context_array, size_t index);

// Error logging function
void log_error(const char *error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}

// Create a new dynamic array for MAC_CONTEXT_T structures
MAC_CONTEXT_ARRAY* create_context_array(size_t initial_capacity) {
    MAC_CONTEXT_ARRAY *context_array = (MAC_CONTEXT_ARRAY *)malloc(sizeof(MAC_CONTEXT_ARRAY));
    if (!context_array) {
        log_error("Failed to allocate memory for context array");
        return NULL;
    }

    context_array->array = (MAC_CONTEXT_T **)calloc(initial_capacity, sizeof(MAC_CONTEXT_T *));
    if (!context_array->array) {
        free(context_array);
        log_error("Failed to allocate memory for context array elements");
        return NULL;
    }

    context_array->capacity = initial_capacity;
    context_array->count = 0;

    pthread_mutex_init(&context_array->mutex, NULL);

    // Log creation
    printf("Created context array with capacity %zu\n", initial_capacity);

    return context_array;
}

// Destroy the dynamic array and free resources
void destroy_context_array(MAC_CONTEXT_ARRAY *context_array) {
    if (!context_array) return;

    pthread_mutex_lock(&context_array->mutex);

    for (size_t i = 0; i < context_array->count; ++i) {
        if (context_array->array[i]) {
            free(context_array->array[i]->frames);
            free(context_array->array[i]);
        }
    }

    free(context_array->array);
    pthread_mutex_unlock(&context_array->mutex);

    pthread_mutex_destroy(&context_array->mutex);
    free(context_array);

    // Log destruction
    printf("Destroyed context array\n");
}

// Add a new MAC_CONTEXT_T to the dynamic array
int add_context(MAC_CONTEXT_ARRAY *context_array, LMAC_CONFIG config, const MAC_FRAME *frames, size_t frame_count) {
    if (!context_array) return -1;

    pthread_mutex_lock(&context_array->mutex);

    if (context_array->count == context_array->capacity) {
        size_t new_capacity = context_array->capacity * 2;
        MAC_CONTEXT_T **new_array = (MAC_CONTEXT_T **)realloc(context_array->array, new_capacity * sizeof(MAC_CONTEXT_T *));

        if (!new_array) {
            pthread_mutex_unlock(&context_array->mutex);
            log_error("Failed to reallocate memory for context array");
            return -1;
        }

        context_array->array = new_array;
        context_array->capacity = new_capacity;
    }

    MAC_CONTEXT_T *new_context = (MAC_CONTEXT_T *)malloc(sizeof(MAC_CONTEXT_T));
    if (!new_context) {
        pthread_mutex_unlock(&context_array->mutex);
        log_error("Failed to allocate memory for a new context");
        return -1;
    }

    new_context->config = config;
    new_context->frames = (MAC_FRAME *)malloc(frame_count * sizeof(MAC_FRAME));
    if (!new_context->frames) {
        free(new_context);
        pthread_mutex_unlock(&context_array->mutex);
        log_error("Failed to allocate memory for frames in a new context");
        return -1;
    }

    for (size_t i = 0; i < frame_count; ++i) {
        new_context->frames[i] = frames[i];
    }
    new_context->frame_count = frame_count;

    context_array->array[context_array->count++] = new_context;

    pthread_mutex_unlock(&context_array->mutex);

    // Log addition
    printf("Added new context. Total contexts: %zu\n", context_array->count);

    return 0;
}

// Remove a MAC_CONTEXT_T from the dynamic array by index
int remove_context(MAC_CONTEXT_ARRAY *context_array, size_t index) {
    if (!context_array || index >= context_array->count) return -1;

    pthread_mutex_lock(&context_array->mutex);

    free(context_array->array[index]->frames);
    free(context_array->array[index]);

    for (size_t i = index; i < context_array->count - 1; ++i) {
        context_array->array[i] = context_array->array[i + 1];
    }

    context_array->array[--context_array->count] = NULL;

    pthread_mutex_unlock(&context_array->mutex);

    // Log removal
    printf("Removed context at index %zu. Total contexts: %zu\n", index, context_array->count);

    return 0;
}

// Example usage
int main() {
    MAC_CONTEXT_ARRAY *context_array = create_context_array(10);
    if (!context_array) return EXIT_FAILURE;

    LMAC_CONFIG config = { .data = 123 };
    MAC_FRAME frames[3] = { .frame_data = 1, .frame_data = 2, .frame_data = 3 };

    add_context(context_array, config, frames, 3);
    remove_context(context_array, 0);

    destroy_context_array(context_array);

    return EXIT_SUCCESS;
}
