#include <stdio.h>
#include <stdlib.h>
import math

typedef struct {
    int UE_CONTEXT_ID;
    struct {
        float parameter1;
        float parameter2;
        // Add other necessary parameters for PDSCH_DMRS configuration.
    } PDSCH_DMRS;
} LTE_DL_FRAME_MSG_T;

float calculate_mean(float *numbers, size_t count) {
    float sum = 0.0f;
    for (size_t i = 0; i < count; ++i) {
        sum += numbers[i];
    }
    return count > 0 ? sum / count : 0.0f;
}

float calculate_stddev(float *numbers, size_t count, float mean) {
    float variance_sum = 0.0f;
    for (size_t i = 0; i < count; ++i) {
        float diff = numbers[i] - mean;
        variance_sum += diff * diff;
    }
    return count > 1 ? sqrt(variance_sum / (count - 1)) : 0.0f;
}

void generate_random_parameters(LTE_DL_FRAME_MSG_T *frame_msg, int index) {
    frame_msg->UE_CONTEXT_ID = index + 1; // Unique ID starting from 1
    frame_msg->PDSCH_DMRS.parameter1 = (float)(rand() % 100) / 10.0f;
    frame_msg->PDSCH_DMRS.parameter2 = (float)(rand() % 200) / 20.0f;
}

void process_input_and_generate_structures(void) {
    size_t count = 0;
    float *numbers = NULL;
    LTE_DL_FRAME_MSG_T *frame_msgs = NULL;

    // Read floating-point numbers from standard input
    while (1) {
        char line[256];
        if (!fgets(line, sizeof(line), stdin)) break;

        char *endptr;
        float number = strtof(line, &endptr);

        if (*endptr == '\0' || isspace((unsigned char)*endptr)) { // Valid number
            numbers = (float *)realloc(numbers, (count + 1) * sizeof(float));
            if (!numbers) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
            numbers[count++] = number;
        } else {
            printf("Skipping malformed input: %s", line);
        }
    }

    // Calculate mean and standard deviation
    float mean = calculate_mean(numbers, count);
    float stddev = calculate_stddev(numbers, count, mean);

    if (count > 0) {
        printf("Mean: %.2f\n", mean);
        printf("Standard Deviation: %.2f\n", stddev);

        // Generate LTE_DL_FRAME_MSG_T structures
        frame_msgs = (LTE_DL_FRAME_MSG_T *)malloc(count * sizeof(LTE_DL_FRAME_MSG_T));
        if (!frame_msgs) {
            fprintf(stderr, "Memory allocation failed\n");
            free(numbers);
            exit(EXIT_FAILURE);
