} CRC_INDICATION_PDU_T;

typedef struct {
    size_t count;
    size_t capacity;
    CRC_INDICATION_PDU_T* pdus;
    pthread_mutex_t mutex;
    bool logging_enabled;
} NFAPI_CRC_INDICATION_CONTEXT_T;

// Initialize the context
void init_nfa_crc_indication_context(NFAPI_CRC_INDICATION_CONTEXT_T *context, bool enable_logging) {
    pthread_mutex_init(&context->mutex, NULL);
    context->count = 0;
    context->capacity = 16; // Initial capacity
    context->pdus = malloc(context->capacity * sizeof(CRC_INDICATION_PDU_T));
    if (!context->pdus) {
        third_party_log_error("Failed to allocate initial memory");
        exit(EXIT_FAILURE);
    }
    context->logging_enabled = enable_logging;
}

// Resize the dynamic array
void resize_nfa_crc_indication_array(NFAPI_CRC_INDICATION_CONTEXT_T *context, size_t new_capacity) {
    CRC_INDICATION_PDU_T* new_pdus = realloc(context->pdus, new_capacity * sizeof(CRC_INDICATION_PDU_T));
    if (!new_pdus) {
        third_party_log_error("Failed to reallocate memory");
        free(context->pdus);
        pthread_mutex_unlock(&context->mutex);
        exit(EXIT_FAILURE);
    }
    context->pdus = new_pdus;
    context->capacity = new_capacity;
}

// Add a PDU
void add_nfa_crc_indication_pdu(NFAPI_CRC_INDICATION_CONTEXT_T *context, uint32_t rx_ue_information_tag, uint32_t rnti) {
    pthread_mutex_lock(&context->mutex);

    if (context->count >= context->capacity) {
        size_t new_capacity = context->capacity * 2;
        if (new_capacity > MAX_NFAPI_CRL_INDICATE_PDU_COUNT) {
            third_party_log_error("Maximum capacity reached");
            resize_nfa_crc_indication_array(context, MAX_NFAPI_CRL_INDICATE_PDU_COUNT);
        } else {
            resize_nfa_crc_indication_array(context, new_capacity);
        }
    }

    CRC_INDICATION_PDU_T *pdu = &context->pdus[context->count++];
    pdu->crc_rel8_tag.RX_UE_INFORMATION_TAG = rx_ue_information_tag;
    pdu->crc_rel8_tag.RNTI = rnti;
    pdu->CRCFLAG = rand() % 2; // Randomly set

    if (context->logging_enabled) {
        third_party_log_info("Added PDU: RXUE=%u, RNTI=%u, CRCFLAG=%d", rx_ue_information_tag, rnti, pdu->CRCFLAG);
    }

    pthread_mutex_unlock(&context->mutex);
}

// Iterate over PDUs
void iterate_nfa_crc_indication_pdus(NFAPI_CRC_INDICATION_CONTEXT_T *context) {
    pthread_mutex_lock(&context->mutex);

    for (size_t i = 0; i < context->count; ++i) {
        CRC_INDICATION_PDU_T *pdu = &context->pdus[i];
        if (context->logging_enabled) {
            third_party_log_debug("Iterating PDU: RXUE=%u, RNTI=%u, CRCFLAG=%d", pdu->crc_rel8_tag.RX_UE_INFORMATION_TAG,
                                  pdu->crc_rel8_tag.RNTI, pdu->CRCFLAG);
        }
    }

    pthread_mutex_unlock(&context->mutex);
}

// Clean up the context
void cleanup_nfa_crc_indication_context(NFAPI_CRC_INDICATION_CONTEXT_T *context) {
    pthread_mutex_lock(&context->mutex);

    if (context->pdus) {
        free(context->pdus);
        context->pdus = NULL;
        context->count = 0;
        context->capacity = 0;
    }

    pthread_mutex_unlock(&context->mutex);
    pthread_mutex_destroy(&context->mutex);
}

// Main function to demonstrate usage (not part of the interface)
int main() {
    NFAPI_CRC_INDICATION_CONTEXT_T context;
    init_nfa_crc_indication_context(&context, true);

    add_nfa_crc_indication_pdu(&context, 1, 12345);
    iterate_nfa_crc_indication_pdus(&context);

    cleanup_nfa_crc_indication_context(&context);
    return 0;
}
