    return result;

fail:
    for (int i = 0; i < ARRAY_SIZE && result == 0; ++i) {
        if (manager->messages[i]) free(manager->messages[i]);
        if (manager->crc_indications[i]) free(manager->crc_indications[i]);
    }
    return 0;
}

void monitorMemoryUsage(MessageManager *manager) {
    while (1) { // Hypothetical monitoring loop
        pthread_mutex_lock(&manager->mutex);
        log_info("Current memory usage: %zu bytes", manager->current_memory_usage);
        pthread_mutex_unlock(&manager->mutex);

        sleep(10); // Adjust the interval as needed
    }
}

int main() {
    MessageManager manager;
    initializeMessageManager(&manager);

    if (!allocateMessagesAndCRCIndications(&manager)) {
        log_error("Failed to allocate messages and CRC indications");
        cleanupMessageManager(&manager);
        return EXIT_FAILURE;
    }

    // Start memory monitoring in a separate thread
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, (void *)monitorMemoryUsage, &manager);

    // Further processing...

    pthread_join(monitor_thread, NULL);
    cleanupMessageManager(&manager);
    return EXIT_SUCCESS;
}
