void initialize_messages(LTEMessageManager *manager, int reduced_memory_mode);
void free_lte_message_manager(LTEMessageManager *manager);

// Helper functions for synchronization
void lock_entry_list(EntryList *list) { pthread_mutex_lock(&list->lock); }
void unlock_entry_list(EntryList *list) { pthread_mutex_unlock(&list->lock); }

void lock_lte_manager(LTEMessageManager *manager) { pthread_mutex_lock(&manager->lock); }
void unlock_lte_manager(LTEMessageManager *manager) { pthread_mutex_unlock(&manager->lock); }

// EntryList functions
EntryList* create_entry_list() {
    EntryList *list = malloc(sizeof(EntryList));
    list->entries = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_entry(EntryList *list, long timestamp, int status_code, const char *message) {
    lock_entry_list(list);

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].timestamp == timestamp) {
            unlock_entry_list(list);
            return;
        }
    }

    EntryList new_list = {NULL, list->count + 1, pthread_mutex_lock(&list->lock)};
    new_list.entries = realloc(list->entries, new_list.count * sizeof(Entry));
    if (!new_list.entries) {
        unlock_entry_list(list);
        free(list);
        return;
    }

    new_list.entries[list->count].timestamp = timestamp;
    new_list.entries[list->count].status_code = status_code;
    new_list.entries[list->count].message = strdup(message);

    *list = new_list;

    unlock_entry_list(list);
}

int remove_entry_by_timestamp(EntryList *list, long timestamp) {
    lock_entry_list(list);
    int found = 0;

    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].timestamp == timestamp) {
            free(list->entries[i].message);
            memmove(&list->entries[i], &list->entries[i + 1],
                    (list->count - i - 1) * sizeof(Entry));
            list->count--;
            found = 1;
            break;
        }
    }

    if (!found && list->count > 0) {
        EntryList new_list = {NULL, list->count, pthread_mutex_lock(&list->lock)};
        new_list.entries = realloc(list->entries, new_list.count * sizeof(Entry));
        if (new_list.entries) {
            *list = new_list;
        }
    }

    unlock_entry_list(list);
    return found;
}

Entry* get_most_recent_entry(const EntryList *list) {
    lock_entry_list((EntryList*)list);

    Entry *most_recent = NULL;
    for (size_t i = 0; i < list->count; ++i) {
        if (!most_recent || list->entries[i].timestamp > most_recent->timestamp) {
            most_recent = &list->entries[i];
        }
    }

    unlock_entry_list((EntryList*)list);
    return most_recent;
}

void serialize_to_file(const EntryList *list, const char *filename) {
    lock_entry_list((EntryList*)list);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        unlock_entry_list((EntryList*)list);
        return;
    }

    fwrite(&list->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->count; ++i) {
        fwrite(&list->entries[i].timestamp, sizeof(long), 1, file);
        fwrite(&list->entries[i].status_code, sizeof(int), 1, file);
        size_t message_len = strlen(list->entries[i].message) + 1;
        fwrite(&message_len, sizeof(size_t), 1, file);
        fwrite(list->entries[i].message, sizeof(char), message_len, file);
    }

    fclose(file);
    unlock_entry_list((EntryList*)list);
}

int deserialize_from_file(EntryList *list, const char *filename) {
    lock_entry_list(list);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        unlock_entry_list(list);
        return 0;
    }

    size_t new_count;
    fread(&new_count, sizeof(size_t), 1, file);

    EntryList new_list = {NULL, new_count, pthread_mutex_lock(&list->lock)};
    new_list.entries = malloc(new_count * sizeof(Entry));
    if (!new_list.entries) {
        fclose(file);
        unlock_entry_list(list);
        return 0;
    }

    for (size_t i = 0; i < new_count; ++i) {
        fread(&new_list.entries[i].timestamp, sizeof(long), 1, file);
        fread(&new_list.entries[i].status_code, sizeof(int), 1, file);
        size_t message_len;
        fread(&message_len, sizeof(size_t), 1, file);
        new_list.entries[i].message = malloc(message_len * sizeof(char));
        fread(new_list.entries[i].message, sizeof(char), message_len, file);
    }

    fclose(file);

    free_entry_list(list);
    *list = new_list;

    unlock_entry_list(list);
    return 1;
}

void free_entry_list(EntryList *list) {
    lock_entry_list(list);

    for (size_t i = 0; i < list->count; ++i) {
        free(list->entries[i].message);
    }
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

