// Global memory pool (for simplicity)
#define POOL_SIZE (MAX_STRUCTS * sizeof(LTE_PDCP_PDU_T))
char memory_pool[POOL_SIZE];
LTE_PDCP_PDU_T* allocations[MAX_STRUCTS] = {0};

void* custom_alloc(size_t size) {
    for (int i = 0; i < MAX_STRUCTS; ++i) {
        if (!allocations[i]) {
            allocations[i] = (LTE_PDCP_PDU_T*)(memory_pool + (i * sizeof(LTE_PDCP_PDU_T)));
            return allocations[i];
        }
    }
    fprintf(stderr, "Memory allocation failed\n");
    return NULL;
}

void* custom_free(void* ptr) {
    for (int i = 0; i < MAX_STRUCTS; ++i) {
        if (allocations[i] == ptr) {
            allocations[i] = NULL;
            return ptr;
        }
    }
    fprintf(stderr, "Attempted to free unallocated memory\n");
    return NULL;
}

LTE_PDCP_PDU_T* generate_pdcp_pdu_list(int count) {
    LTE_PDCP_PDU_T *list = (LTE_PDCP_PDU_T*)custom_alloc(count * sizeof(LTE_PDCP_PDU_T));
    if (!list) return NULL;

    int previous_pdch_id = -1;

    for (int i = 0; i < count; ++i) {
        list[i].PDCH_PDU = rand() % PDCH_ID_RANGE;

        // Ensure no two consecutive elements share the same PDCH identity
        while (list[i].PDCH_PDU == previous_pdch_id) {
            list[i].PDCH_PDU = rand() % PDCH_ID_RANGE;
        }
        previous_pdch_id = list[i].PDCH_PDU;

        list[i].PDCP_SN = i + 1; // Simple sequence number assignment

        // Simulate key generation and random encryption status
        for (int j = 0; j < sizeof(list[i].ciphering_key); ++j) {
            ((char*)list[i].ciphering_key)[j] = rand() % 256;
        }

        list[i].encryption_status = rand() % 2;

        // Integrate with external encryption framework
        if (list[i].encryption_status) {
            encrypt_pdu(list + i, sizeof(LTE_PDCP_PDU_T));  // Assume encrypt_pdu is provided by the external library
        }
    }

    return list;
}

// Example usage of freeing resources
void free_pdcp_pdu_list(LTE_PDCP_PDU_T* list, int count) {
