#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 100

typedef struct {
    uint16_t crcflag;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

uint16_t custom_random(uint32_t seed) {
    // Simple Linear Congruential Generator (LCG)
    const uint32_t a = 1664525, c = 1013904223;
    return ((a * seed + c) & 0xFFFFFFFF) >> 16;
}

void log_operation(const char* operation, Node* node) {
    FILE* log_file = fopen("operations.log", "a");
    if (log_file) {
        time_t now = time(NULL);
        fprintf(log_file, "[%s] Operation: %s, RNTI: %d\n",
                ctime(&now), operation, node->data.RNTI);
        fclose(log_file);
    }
}

void print_list(Node* head, int verbose) {
    if (!verbose) return;
    Node* current = head;
    while (current) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.tag.crcflag);
        current = current->next;
    }
}

void free_list(Node** head) {
    Node* current = *head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int verify_memory_freed(Node* head) {
    return head == NULL;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    log_operation("Insert", new_node);
    print_list(new_node, 1); // Debug: Set verbose to 0 in production
    return new_node;
}

Node* populate_linked_list(uint32_t seed, int M, int verbose) {
    if (M > MAX_ELEMENTS) M = MAX_ELEMENTS;

    Node* head = NULL;
    Node** last_ptr = &head;
    uint16_t rnti_set[MAX_ELEMENTS] = {0};
    int count = 0;

    for (int i = 1; i <= M; ++i) {
        pthread_mutex_lock(&lock);

        if (count >= MAX_ELEMENTS) break;

        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = i;
        pdu.RNTI = i;

        // Ensure unique RNTI
        while (rnti_set[pdu.RNTI - 1]) {
            ++pdu.RNTI;
            if (pdu.RNTI > M) {
                pthread_mutex_unlock(&lock);
                return head; // Exit early on duplicate limit exceeded
            }
        }
        rnti_set[pdu.RNTI - 1] = 1;

        uint16_t random_value = custom_random(seed + pdu.RNTI);
        pdu.tag.crcflag = random_value & 0x01;

        Node* new_node = create_node(pdu);
        if (!new_node) {
            pthread_mutex_unlock(&lock);
            free_list(&head);
            return NULL; // Allocation failure
        }

        *last_ptr = new_node;
        last_ptr = &new_node->next;

        ++count;
        pthread_mutex_unlock(&lock);
    }

    print_list(head, verbose);
    return head;
}

int main(int argc, char* argv[]) {
    uint32_t seed = 12345; // Example seed
    int M = 10;            // Example max elements
    int verbose = 1;       // Enable debug output

    Node* list = populate_linked_list(seed, M, verbose);

    if (list) {
        free_list(&list);
        printf("Memory freed: %s\n", verify_memory_freed(list) ? "Yes" : "No");
    }

    return 0;
}
