#include <pthread.h>
#include <time.h>
#include <jansson.h> // JSON parsing library

// Structure for network performance metrics
typedef struct Measurement {
    char *metric_name;
    double value;
    struct Measurement *next;
} Measurement;

typedef struct NetworkPerformanceMetrics {
    time_t timestamp;
    char session_id[256];
    Measurement *measurements;
    struct NetworkPerformanceMetrics *prev, *next;
} NetworkPerformanceMetrics;

// Doubly linked list node and management
typedef struct {
    NetworkPerformanceMetrics *head, *tail;
    size_t max_entries;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} LinkedList;

// Initialize the linked list
void init_linked_list(LinkedList *list, size_t max_entries) {
    list->head = list->tail = NULL;
    list->max_entries = max_entries;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
}

// Cleanup function for outdated metrics
void cleanup_metrics(LinkedList *list, time_t retention_time) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics *current = list->head, *prev = NULL;
    while (current != NULL) {
        if (difftime(time(NULL), current->timestamp) > retention_time || 
            (list->max_entries && list->head != NULL && 
             (size_t)0 == (unsigned long)((list->tail - list->head + 1))) ) {
            NetworkPerformanceMetrics *to_delete = current;
            if (prev == NULL) {
                list->head = current->next;
                if (list->head != NULL) list->head->prev = NULL;
            } else {
                prev->next = current->next;
                if (current->next != NULL) current->next->prev = prev;
            }
            if (current == list->tail) list->tail = prev;

            // Free measurements
            Measurement *m = current->measurements;
            while (m) {
                Measurement *temp = m;
                m = m->next;
                free(temp->metric_name);
                free(temp);
            }

            free(current->session_id);
            free(current);
            if (prev == NULL && list->head != NULL) prev = list->head;
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to find a session by ID
NetworkPerformanceMetrics* find_session(LinkedList *list, const char *session_id) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics *current = list->head;
    while (current != NULL) {
        if (strcmp(current->session_id, session_id) == 0) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Add or update a metric
void add_or_update_metric(LinkedList *list, json_t *json_payload) {
    const char *session_id = json_string_value(json_object_get(json_payload, "session_id"));
    if (!session_id) return;

    NetworkPerformanceMetrics *metric = find_session(list, session_id);

    pthread_mutex_lock(&list->lock);

    if (metric == NULL) { // Add new metric
        metric = malloc(sizeof(NetworkPerformanceMetrics));
        strcpy(metric->session_id, session_id);
        time(&metric->timestamp);

        metric->measurements = NULL;
        json_t *json_measurements = json_object_get(json_payload, "measurements");
        if (json_is_array(json_measurements)) {
            size_t index, n = json_array_size(json_measurements);
            for (index = 0; index < n; index++) {
                json_t *entry = json_array_get(json_measurements, index);
                Measurement *m = malloc(sizeof(Measurement));
                m->metric_name = strdup(json_string_value(json_object_get(entry, "name")));
                m->value = json_number_value(json_object_get(entry, "value"));
                m->next = metric->measurements;
                metric->measurements = m;
            }
        }

        if (list->tail) {
            list->tail->next = metric;
            metric->prev = list->tail;
            list->tail = metric;
        } else {
            list->head = list->tail = metric;
        }

    } else { // Update existing metric
        time(&metric->timestamp);

        json_t *json_measurements = json_object_get(json_payload, "measurements");
        if (json_is_array(json_measurements)) {
            size_t index, n = json_array_size(json_measurements);
            Measurement **mptr = &metric->measurements;
            while (*mptr) {
                Measurement *m = *mptr;
                for (index = 0; index < n; index++) {
                    json_t *entry = json_array_get(json_measurements, index);
                    const char *name = json_string_value(json_object_get(entry, "name"));
                    if (strcmp(m->metric_name, name) == 0) {
                        m->value = json_number_value(json_object_get(entry, "value"));
                        break;
                    }
                }
                mptr = &m->next;
            }

            // Add new measurements
            for (index = 0; index < n; index++) {
                json_t *entry = json_array_get(json_measurements, index);
                const char *name = json_string_value(json_object_get(entry, "name"));
                Measurement **mptr = &metric->measurements;
                while (*mptr) {
                    if (strcmp((*mptr)->metric_name, name) == 0) break;
                    mptr = &(*mptr)->next;
                }

                if (!*mptr) { // Add new measurement
                    Measurement *m = malloc(sizeof(Measurement));
                    m->metric_name = strdup(name);
                    m->value = json_number_value(json_object_get(entry, "value"));
                    m->next = NULL;
                    *mptr = m;
                }
            }
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Remove a metric by session ID
void remove_metric(LinkedList *list, const char *session_id) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics *metric = find_session(list, session_id);
    if (metric == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (metric->prev) metric->prev->next = metric->next;
    else list->head = metric->next;

    if (metric->next) metric->next->prev = metric->prev;
    else list->tail = metric->prev;

    Measurement *m = metric->measurements;
    while (m) {
        Measurement *temp = m;
        m = m->next;
        free(temp->metric_name);
        free(temp);
    }

    free(metric->session_id);
    free(metric);

    pthread_mutex_unlock(&list->lock);
}

// Export metrics to CSV
void export_metrics_to_csv(LinkedList *list, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "Timestamp,Session ID,Metric Name,Value\n");

    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics *current = list->head;
    while (current != NULL) {
        char ts[100];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&current->timestamp));

        Measurement *m = current->measurements;
        while (m) {
            fprintf(file, "\"%s\",\"%s\",\"%s\",%.2f\n",
                    ts, current->session_id, m->metric_name, m->value);
            m = m->next;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

// HTTP request handlers (simplified pseudo-implementation)
void handle_put_request(LinkedList *list, const char *json_str) {
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);
    if (!root) return;

    add_or_update_metric(list, root);

    json_decref(root);
}

void handle_delete_request(LinkedList *list, const char *session_id) {
    remove_metric(list, session_id);
}

// Main function to simulate API service
int main() {
    LinkedList metrics_list;
    init_linked_list(&metrics_list, 100); // Max 100 entries

    // Simulate HTTP PUT request
    const char *json_payload = "{\"session_id\":\"1234\",\"measurements\":[{\"name\":\"latency\",\"value\":10.5}]}";
    handle_put_request(&metrics_list, json_payload);

    // Simulate periodic cleanup task (run in background thread)
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, (void *)cleanup_metrics, &metrics_list);

    // Simulate HTTP GET request
    export_metrics_to_csv(&metrics_list, "metrics.csv");

    // Join threads and cleanup
    pthread_join(cleanup_thread, NULL);

    return 0;
}
