#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef enum {
    LOG_NONE,
    LOG_CONSOLE,
    LOG_FILE
} LogLevel;

typedef struct {
    LogLevel level;
    FILE *file;
} LoggerConfig;

void logMessage(const char *message, const LoggerConfig *logger) {
    if (logger->level == LOG_NONE) return;

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    if (logger->level == LOG_CONSOLE || logger->file) {
        printf("[%s] %s\n", timestamp, message);
    }
    if (logger->file && logger->level != LOG_NONE) {
        fprintf(logger->file, "[%s] %s\n", timestamp, message);
    }
}

void freeLogger(LoggerConfig *logger) {
    if (logger->file) {
        fclose(logger->file);
    }
}

int initializeRecordArrays(size_t recordCount, int minValue, int maxValue,
                           int **longOffsets, int **keys, LoggerConfig *logger) {
    if (!longOffsets || !keys || logger == NULL) return -1;

    size_t initialSize = recordCount;
    *longOffsets = malloc(sizeof(int) * initialSize);
    *keys = malloc(sizeof(int) * initialSize);

    if (*longOffsets == NULL || *keys == NULL) {
        logMessage("Memory allocation failed", logger);
        free(*longOffsets); 
        free(*keys);
        return -1;
    }

    srand(time(NULL));

    for (size_t i = 0; i < recordCount; ++i) {
        int newValue = minValue + rand() % (maxValue - minValue + 1);

        if (i >= initialSize) {
            size_t newSize = initialSize * 2;
            int *tempOffsets = realloc(*longOffsets, sizeof(int) * newSize);
            int *tempKeys = realloc(*keys, sizeof(int) * newSize);

            if (tempOffsets == NULL || tempKeys == NULL) {
                logMessage("Memory reallocation failed", logger);
                free(tempOffsets); 
                free(tempKeys);
                return -1;
            }

            *longOffsets = tempOffsets;
            *keys = tempKeys;

            for (size_t j = initialSize; j < newSize; ++j) {
                (*longOffsets)[j] = 0;
                (*keys)[j] = 0;
            }

            initialSize = newSize;
        }

        (*longOffsets)[i] = rand() % 1000000; // Example offset value
        (*keys)[i] = newValue;
    }

    return 0;
}

// Usage example
int main() {
    LoggerConfig logger = { LOG_CONSOLE, NULL };
    int *offsets = NULL;
    int *keyArray = NULL;

    if (initializeRecordArrays(10, 1, 100, &offsets, &keyArray, &logger) == 0) {
        printf("Initialization successful.\n");
    } else {
        printf("Initialization failed.\n");
    }

    free(offsets);
    free(keyArray);

    return 0;
}
