#define MAX_INITIAL_SIZE 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG; // Randomly set
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

void initDynamicArray(DynamicArray* array, size_t initial_capacity) {
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void resizeDynamicArray(DynamicArray* array, size_t new_capacity) {
    pthread_mutex_lock(&array->lock);
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to reallocate memory");
        pthread_mutex_unlock(&array->lock);
        exit(EXIT_FAILURE);
    }
    array->data = new_data;
    array->capacity = new_capacity;
    pthread_mutex_unlock(&array->lock);
}

void addCRCIndication(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        resizeDynamicArray(array, array->capacity * 2);
    }
    array->data[array->count++] = pdu;
    pthread_mutex_unlock(&array->lock);
}

void serializeData(const char* filename, DynamicArray* array) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_mutex_lock(&array->lock);
    fwrite(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), array->count, file);
    pthread_mutex_unlock(&array->lock);

    fclose(file);
}

void deserializeData(const char* filename, DynamicArray* array) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    size_t count;
    fseek(file, 0, SEEK_END);
    count = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    rewind(file);

    resizeDynamicArray(array, count);
    pthread_mutex_lock(&array->lock);
    fread(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    array->count = count;
    pthread_mutex_unlock(&array->lock);

    fclose(file);
}

void generateRandomCRCIndication(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand((unsigned int)time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = (uint16_t)rand() % 65536;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Randomly set to 0 or 1
}

void cleanupDynamicArray(DynamicArray* array) {
    pthread_mutex_destroy(&array->lock);
    free(array->data);
}

