    long   nanoseconds;
} timestamp;

typedef struct node {
    float value;
    char* string_value;
    timestamp insertion_time;
    struct node* next;
} node;

// External logging interface (stub)
void log_insertion(const char* message) {
    // This is a stub for an actual logging operation
    printf("%s\n", message);
}

// Mutex for thread safety
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

node* create_node(float value, const char* str_value, timestamp time) {
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) return NULL;

    new_node->value = value;
    new_node->string_value = strdup(str_value);
    if (!new_node->string_value) {
        free(new_node);
        return NULL;
    }

    new_node->insertion_time = time;
    new_node->next = NULL;
    return new_node;
}

void free_linked_list(node* head) {
    node *current, *next;
    for (current = head; current != NULL;) {
        next = current->next;
        free(current->string_value);
        free(current);
        current = next;
    }
}

int validate_monotonicity(timestamp prev_time, timestamp curr_time) {
    if ((curr_time.seconds < prev_time.seconds) ||
        (curr_time.seconds == prev_time.seconds && curr_time.nanoseconds <= prev_time.nanoseconds)) {
        return 0; // Not monotonically increasing
    }
    return 1;
}

int insert_node(node** head, float value, const char* str_value, timestamp time) {
    pthread_mutex_lock(&list_mutex);

    if (!validate_monotonicity(((node*)*head)->insertion_time, time)) {
        pthread_mutex_unlock(&list_mutex);
        return -1; // Timestamp validation failed
    }

    node* new_node = create_node(value, str_value, time);
    if (!new_node) {
        pthread_mutex_unlock(&list_mutex);
        return -2; // Memory allocation failure
    }

    log_insertion(str_value);

    new_node->next = *head;
    *head = new_node;

    pthread_mutex_unlock(&list_mutex);
    return 0;
}

node* initialize_linked_list(size_t num_nodes, float min_val, float max_val) {
    if (num_nodes <= 0) return NULL;

    node* head = NULL;
    char str_value[32];
