    for (size_t i = 0; i < num_nodes; ++i) {
        float value = min_val + ((float)rand() / RAND_MAX) * (max_val - min_val);

        snprintf(str_value, sizeof(str_value), "%f", value);

        clock_gettime(CLOCK_REALTIME, &curr_time);

        if (insert_node(&head, value, str_value, curr_time)) {
            free_linked_list(head);
            return NULL; // Handle insertion error
        }
    }

    return head;
}

int main() {
    srand(time(NULL));

    size_t num_nodes = 4;
    float min_val = -100.0f, max_val = 100.0f;

    node* list_head = initialize_linked_list(num_nodes, min_val, max_val);

