        node *current = list_head;
        while (current != NULL) {
            printf("Value: %f, String: %s\n", current->value, current->string_value);
            current = current->next;
        }

        free_linked_list(list_head);
    } else {
        fprintf(stderr, "Failed to initialize linked list.\n");
    }

    return 0;
}
