// Mock function to encode NAS messages
void initializeTLVEncoder(void *encoder) {
    // Initialize encoder logic here
}

// Mock messaging system interface
int sendMessageToQueue(const NAS_Message *message) {
    // Simulate sending message, return 0 on success, -1 on failure.
    return rand() % 2;
