typedef struct {
    LTE_DL_CCCH_Message_Type1_T *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MessageArray;

// Function to dynamically allocate and initialize the message array
int initializeMessageArray(MessageArray *array, size_t initial_capacity) {
    pthread_mutex_lock(&array->lock);

    array->messages = (LTE_DL_CCCH_Message_Type1_T *)malloc(initial_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!array->messages) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->capacity = initial_capacity;
    array->count = 0;

    for (size_t i = 0; i < initial_capacity; ++i) {
        initializeTLVEncoder(&(array->messages[i].encoder));
        NAS_Message *nas_message = &(array->messages[i]); // Assuming a way to access NAS_Message
        nas_message->message_type = rand() % 100; // Random message type
        snprintf(nas_message->content, MAX_MESSAGE_SIZE, "Content for type %d", nas_message->message_type);
    }

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Function to free the allocated memory
void cleanupMessageArray(MessageArray *array) {
    pthread_mutex_lock(&array->lock);

    if (array->messages) {
        free(array->messages);
        array->messages = NULL;
    }
    array->capacity = 0;
    array->count = 0;

    pthread_mutex_unlock(&array->lock);
}

// Function to send messages
void *messageSender(void *arg) {
    MessageArray *array = (MessageArray *)arg;
    int retry_interval = 1; // Initial retry interval in seconds

    while (1) {
        pthread_mutex_lock(&array->lock);

        for (size_t i = 0; i < array->count; ++i) {
            NAS_Message *nas_message = &(array->messages[i]); // Accessing the NAS_Message
            int success = sendMessageToQueue(nas_message);
            if (!success) {
                int retries = 0;
                while (retries < MAX_RETRIES) {
                    sleep(retry_interval);
                    success = sendMessageToQueue(nas_message);
                    if (success) break;
                    retries++;
                    retry_interval *= 2; // Exponential backoff
                }
                if (!success) {
                    fprintf(stderr, "Failed to send message after %d retries\n", MAX_RETRIES);
                }
            }
        }

        pthread_mutex_unlock(&array->lock);
        sleep(1); // Throttle sending rate
    }

    return NULL;
}

int main() {
    MessageArray array = {0};
    pthread_t sender_thread;

    pthread_mutex_init(&array.lock, NULL);

    if (initializeMessageArray(&array, INITIAL_ARRAY_SIZE) != 0) {
        cleanupMessageArray(&array);
        pthread_mutex_destroy(&array.lock);
        return EXIT_FAILURE;
    }

    if (pthread_create(&sender_thread, NULL, messageSender, &array) != 0) {
        fprintf(stderr, "Failed to create sender thread\n");
        cleanupMessageArray(&array);
        pthread_mutex_destroy(&array.lock);
        return EXIT_FAILURE;
    }

    // Join the sender thread for demonstration purposes
    pthread_join(sender_thread, NULL);

    cleanupMessageArray(&array);
    pthread_mutex_destroy(&array.lock);

    return EXIT_SUCCESS;
}
