unsigned int rolling_hash(unsigned int prev_hash, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    unsigned int hash = prev_hash;
    hash ^= (pdu->RX_UE_INFORMATION_TAG << 1) | (pdu->RNTI >> 15);
    return hash & 0xFF; // Ensure CRCFLAG is an 8-bit value
}

int is_valid_rnti(unsigned short rnti, unsigned short *existing_rntis, int count) {
    for (int i = 0; i < count; ++i) {
        if (existing_rntis[i] == rnti) return 0;
    }
    return rnti >= RNTI_MIN && rnti <= RNTI_MAX;
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int n, int *result_count) {
    if (n > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Requested size exceeds maximum capacity.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    unsigned short existing_rntis[MAX_ELEMENTS] = {0};
    int count = 0;

    srand(time(NULL)); // Seed for randomness

    while (count < n) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 10000; // Example tag generation
        unsigned short rnti;

        do {
            rnti = rand() % (RNTI_MAX - RNTI_MIN + 1) + RNTI_MIN;
        } while (!is_valid_rnti(rnti, existing_rntis, count));

        pdu.RNTI = rnti;
        pdu.CRC_INDICATION_REL8_TAG = rand() & 0xFF; // Example tag generation

        if (count > 0) {
            pdu.CRCFLAG = rolling_hash(list[count - 1].CRCFLAG, &pdu);
        } else {
            pdu.CRCFLAG = rand() & 0xFF; // Initial random CRCFLAG
        }

        existing_rntis[count] = rnti;
        list[count++] = pdu;

        if (log_creation("Successfully created and validated a PDU structure") != 0) {
            fprintf(stderr, "Error: Failed to log the creation of a PDU structure.\n");
        }
    }

    // Sort based on RX_UE_INFORMATION_TAG
    qsort(list, count, sizeof(NFAPI_CRC_INDICATION_PDU_T), 
          (int (*)(const void *, const void *)) strcmp);

    *result_count = count;
    return list;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    if (list != NULL) {
        free(list);
    }
}
