    MemoryPool* pool = create_memory_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_STRUCTURES);
    if (!pool) {
        log_message(LOG_LEVEL_ERROR, "Failed to create memory pool");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed for list");
        destroy_memory_pool(pool);
        return NULL;
    }

    pthread_mutex_t sort_lock = PTHREAD_MUTEX_INITIALIZER;
    uint16_t unique_rntis[MAX_STRUCTURES] = {0};
    size_t rnti_count = 0;

    srand(seed);

    for (size_t i = 0; i < MAX_STRUCTURES; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = allocate_from_pool(pool);
        if (!pdu) {
            log_message(LOG_LEVEL_ERROR, "Memory allocation failed from pool");
            break;
