        if (rnti_count < MAX_STRUCTURES) {
            unique_rntis[rnti_count++] = rnti;
        }

        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        if (!is_valid_crc_flag(pdu->CRC_INDICATION_REL8_TAG.CRCFLAG)) {
            log_message(LOG_LEVEL_ERROR, "Invalid CRCFLAG detected");
            free(pdu);
            continue;
        }

        pthread_mutex_lock(&sort_lock);
        list[i] = pdu;
        // Insert in sorted order
        for (size_t j = i; j > 0 && list[j-1]->RNTI > list[j]->RNTI; --j) {
            NFAPI_CRC_INDICATION_PDU_T* temp = list[j];
            list[j] = list[j - 1];
            list[j - 1] = temp;
        }
        pthread_mutex_unlock(&sort_lock);
    }

    *count = rnti_count;

    if (verify_checksums) {
        for (size_t i = 0; i < rnti_count; ++i) {
            if (!is_valid_crc_flag(list[i]->CRC_INDICATION_REL8_TAG.CRCFLAG)) {
                log_message(LOG_LEVEL_ERROR, "Checksum verification failed");
                return NULL;
            }
        }
    }

    pthread_mutex_destroy(&sort_lock);
    destroy_memory_pool(pool);
    return list;
}

MemoryPool* create_memory_pool(size_t block_size, size_t total_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->total_blocks = total_blocks;
    pool->blocks = malloc(block_size * total_blocks);
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    if (pool) {
        free(pool->blocks);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool* pool) {
    if (!pool) return NULL;

    pthread_mutex_lock(&pool->lock);
    static size_t current_index = 0;

    if (current_index >= pool->total_blocks) {
        pthread_mutex_unlock(&pool->lock);
        log_message(LOG_LEVEL_ERROR, "Memory pool exhausted");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* block = 
        (NFAPI_CRC_INDICATION_PDU_T*)(pool->blocks + current_index * pool->block_size);

    ++current_index;
    pthread_mutex_unlock(&pool->lock);
    return block;
}

// Example usage
