#include <time.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum { Array_of_Longs, Map_of_Strings, Graph_Node } Data_Structure_Type;

typedef struct {
    int Task_ID;
    int Priority_Level;
    Data_Structure_Type Data_Structure;
    void *Data;
} Async_Task_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    unsigned long seed;
} CRCList;

void init_crc_list(CRCList* list, unsigned long seed) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->seed = seed;
}

unsigned long get_random_rnti(CRCList* list) {
    srand(list->seed);
    return (rand() % 0xFFFFFFFFL); // Random RNTI
}

int is_duplicate(NFAPI_CRC_INDICATION_PDU_T new_pdu, Node* node) {
    while (node != NULL) {
        if (new_pdu.RNTI == node->data.RNTI) {
            return 1;
        }
        node = node->next;
    }
    return 0;
}

int insert_into_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T new_pdu) {
    pthread_mutex_lock(&list->lock);

    if (new_pdu.RNTI == 0 || is_duplicate(new_pdu, list->head)) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Duplicate RNTI or invalid RNTI
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failure
    }

    new_node->data = new_pdu;
    new_node->next = NULL;

    if (list->head == NULL || list->head->data.RNTI > new_pdu.RNTI) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL && current->next->data.RNTI < new_pdu.RNTI) {
            current = current->next;
        }
        if (current->next == NULL || current->next->data.RNTI > new_pdu.RNTI) {
            new_node->next = current->next;
            current->next = new_node;
        } else {
            free(new_node); // Duplicate RNTI detected at the end
            pthread_mutex_unlock(&list->lock);
            return -1; 
        }
    }

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void cleanup_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    pthread_mutex_destroy(&list->lock);
}

// Asynchronous task management
typedef struct TaskQueue {
    Async_Task_T* tasks[MAX_LIST_SIZE];
    int count;
    pthread_mutex_t lock;
} TaskQueue;

void init_task_queue(TaskQueue* queue) {
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

int add_task(TaskQueue* queue, Async_Task_T task) {
    pthread_mutex_lock(&queue->lock);

    if (queue->count >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue full
    }

    for (int i = 0; i < queue->count; ++i) {
        if (queue->tasks[i]->Task_ID == task.Task_ID) {
            pthread_mutex_unlock(&queue->lock);
            return -2; // Duplicate Task ID
        }
    }

    queue->tasks[queue->count++] = &task;

    pthread_mutex_unlock(&queue->lock);

    return 0;
}

void cleanup_task_queue(TaskQueue* queue) {
    pthread_mutex_destroy(&queue->lock);
}

