                return NULL;
            }
            memcpy(pdu_copy, &da->array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&da->lock);
            return pdu_copy;
        }
    }

    pthread_mutex_unlock(&da->lock);
    return NULL; // Not found
}

void free_dynamic_array(DynamicArray *da) {
    if (!da) return;

    pthread_mutex_lock(&da->lock);
    free(da->array);
    pthread_mutex_unlock(&da->lock);

    pthread_mutex_destroy(&da->lock);
    free(da);
}
