    return 0;
}

int main() {
    MemoryPool mp;
    if (init_memory_pool(&mp, 1024 * 1024) != 0) { // 1 MB pool
        fprintf(stderr, "Failed to initialize memory pool.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    int result = populate_linked_list(&head, &mp, 100);
    if (result != 0) {
        fprintf(stderr, "Failed to populate linked list.\n");
    }

    // Free the linked list
    while (head) {
        NFAPI_CRC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp->CRC_INDICATION_REL8);
        free(temp);
    }

    free_memory_pool(&mp);
    return 0;
}
```

This code snippet provides a thread-safe function to dynamically allocate and populate a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures. It manages memory allocation from a pre-allocated pool, ensuring that allocations are minimized to reduce fragmentation and optimize performance. The solution also ensures uniqueness for the `CRCFLAG` value within each list instance while supporting multi-threaded access with mutex locks. If any allocation fails, it returns an error code to handle such scenarios gracefully.']

