#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned short CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Record {
    int key;
    long offset;
    double value;
    bool isValid;
    struct Record* next;
} Record;

typedef struct {
    Record* head;
    pthread_mutex_t lock;
} RecordCollection;

// Global variable for cumulative count
int globalValidCount = 0;
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;

void log_performance(const char* message) {
    printf("LOG: %s\n", message);
}

bool allocate_and_initialize(int numPDUs, NFAPI_CRC_INDICATION_PDU_T** pdus,
                             RecordCollection** collection) {
    pthread_mutex_lock(&globalLock);

    // Allocate PDUs
    *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numPDUs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        log_performance("Failed to allocate memory for PDUs.");
        pthread_mutex_unlock(&globalLock);
        return false;
    }

    // Initialize PDUs with random values
    srand((unsigned int)time(NULL));
    for (int i = 0; i < numPDUs; ++i) {
        (*pdus)[i].RX_UE_INFORMATION_TAG = rand();
        (*pdus)[i].RNTI = rand();
        (*pdus)[i].CRC_INDICATION_REL8_TAG = rand() % 65536;
        (*pdus)[i].CRCFLAG = (rand() % 2 == 0);
    }

    // Initialize record collection
    *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (*collection == NULL) {
        log_performance("Failed to allocate memory for RecordCollection.");
        free(*pdus);
        pthread_mutex_unlock(&globalLock);
        return false;
    }

    (*collection)->head = NULL;
    pthread_mutex_init(&((*collection)->lock), NULL);

    // Allocate records with unique keys
    int keys[numPDUs];
    for (int i = 0; i < numPDUs; ++i) {
        bool isUniqueKey = false;
        while (!isUniqueKey) {
            int key = rand() % 1000000;
            isUniqueKey = true;

            pthread_mutex_lock(&((*collection)->lock));
            Record* current = (*collection)->head;
            while (current != NULL) {
                if (current->key == key) {
                    isUniqueKey = false;
                    break;
                }
                current = current->next;
            }
            pthread_mutex_unlock(&((*collection)->lock));

            if (!isUniqueKey) continue;

            keys[i] = key;
        }

        // Allocate and initialize record
        Record* newRecord = (Record*)malloc(sizeof(Record));
        if (newRecord == NULL) {
            log_performance("Failed to allocate memory for a new record.");
            free(*pdus);
            pthread_mutex_destroy(&((*collection)->lock));
            free(*collection);
            pthread_mutex_unlock(&globalLock);
            return false;
        }

        newRecord->key = keys[i];
        newRecord->offset = rand() % 1000000L;
        newRecord->value = (double)rand() / RAND_MAX;
        newRecord->isValid = true;

        // Insert record into collection
        pthread_mutex_lock(&((*collection)->lock));
        newRecord->next = (*collection)->head;
        (*collection)->head = newRecord;
        globalValidCount++;
        pthread_mutex_unlock(&((*collection)->lock));
    }

    log_performance("Successfully allocated and initialized structures.");
    pthread_mutex_unlock(&globalLock);
    return true;
}

void free_resources(NFAPI_CRC_INDICATION_PDU_T* pdus, RecordCollection* collection) {
    if (pdus != NULL) {
        free(pdus);
    }

    Record* current = collection->head;
    while (current != NULL) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&collection->lock);
    free(collection);

    pthread_mutex_lock(&globalLock);
    globalValidCount = 0;
    pthread_mutex_unlock(&globalLock);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;
    RecordCollection* collection = NULL;

    if (allocate_and_initialize(100, &pdus, &collection)) {
        // Use allocated resources...

        free_resources(pdus, collection);
    } else {
        printf("Failed to initialize structures.\n");
    }

    return 0;
}
