#define MAX_ENTRIES 1024

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RNTI; // Radio Network Temporary Identifier
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Error codes
#define SUCCESS 0
#define ERROR_MEMORY_ALLOCATION_FAILED -1
#define ERROR_INVALID_RNTI -2

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array[MAX_ENTRIES];
    int size;
} CRC_Indication_Manager;

CRC_Indication_Manager* initialize_crc_manager() {
    CRC_Indication_Manager *manager = (CRC_Indication_Manager *)malloc(sizeof(CRC_Indication_Manager));
    if (!manager) return NULL;

    manager->size = 0;
    memset(manager->array, 0, sizeof(manager->array));

    return manager;
}

int add_or_update_crc_entry(CRC_Indication_Manager *manager, uint32_t rnti, int crcflag) {
    if (manager == NULL) return ERROR_INVALID_RNTI;

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (manager->array[i] && manager->array[i]->RNTI == rnti) {
            manager->array[i]->crc_indication_rel8_tag.CRCFLAG = crcflag;
            return SUCCESS;
        }
    }

    if (manager->size >= MAX_ENTRIES) return ERROR_INVALID_RNTI;

    NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entry) return ERROR_MEMORY_ALLOCATION_FAILED;

    entry->RNTI = rnti;
    entry->crc_indication_rel8_tag.CRCFLAG = crcflag;

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (!manager->array[i]) {
            manager->array[i] = entry;
            manager->size++;
            return SUCCESS;
        }
    }

    free(entry);
    return ERROR_INVALID_RNTI;
}

NFAPI_CRC_INDICATION_PDU_T* get_crc_entry(CRC_Indication_Manager *manager, uint32_t rnti) {
    if (manager == NULL) return NULL;

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (manager->array[i] && manager->array[i]->RNTI == rnti) {
            return manager->array[i];
        }
    }

    return NULL;
}

void free_crc_manager(CRC_Indication_Manager *manager) {
    if (!manager) return;

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (manager->array[i]) {
            free(manager->array[i]);
        }
    }

    free(manager);
}
