    unsigned long timestamp;
    char packet_type;
} L2FWD_FRAME_STATS;

volatile sig_atomic_t interrupted = 0;

void handle_signal(int signal) {
    interrupted = 1;
}

double calculate_mean(const float* numbers, size_t count);
double calculate_standard_deviation(const float* numbers, size_t count, double mean);

int process_numbers(float* buffer, L2FWD_FRAME_STATS* stats_array, size_t num_stats, int num_floats) {
    if (num_floats == 0 || num_floats > MAX_NUMBERS) {
        fprintf(stderr, "Error: Invalid number of floating-point inputs.\n");
        return -1;
    }

    signal(SIGINT, handle_signal);

    float* numbers = buffer;
    double mean = calculate_mean(numbers, num_floats);
    if (mean == 0.0 && !interrupted) {
        fprintf(stderr, "Error: Failed to calculate mean due to invalid input.\n");
        return -1;
    }

    double stddev = calculate_standard_deviation(numbers, num_floats, mean);
    if (!stddev && !interrupted) {
        fprintf(stderr, "Error: Failed to calculate standard deviation.\n");
        return -1;
    }

    printf("Mean: %.2f\n", mean);
    printf("Standard Deviation: %.2f\n", stddev);

    for (size_t i = 0; i < num_stats && !interrupted; ++i) {
        stats_array[i].valid_frame_length = rand() % 1500 + 64; // Example length
        stats_array[i].timestamp = time(NULL);
        stats_array[i].packet_type = 'A' + (rand() % 26); // Random packet type A-Z
    }

    return num_stats;
}

double calculate_mean(const float* numbers, size_t count) {
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        if (!isfinite(numbers[i])) {
            return 0.0;
        }
        sum += numbers[i];
    }
    return sum / count;
}

double calculate_standard_deviation(const float* numbers, size_t count, double mean) {
    double variance = 0.0;
    for (size_t i = 0; i < count; ++i) {
        double diff = numbers[i] - mean;
        variance += diff * diff;
    }
    return sqrt(variance / count);
}

int main() {
    float buffer[MAX_NUMBERS];
    L2FWD_FRAME_STATS stats_array[100]; // Example size

    // Simulate receiving data
    for (int i = 0; i < 5000 && !interrupted; ++i) { // Simulating 5000 numbers
        buffer[i] = (float)(rand() % 100);
    }

    int result = process_numbers(buffer, stats_array, sizeof(stats_array) / sizeof(stats_array[0]), 5000);
    if (result >= 0) {
        printf("Successfully processed %d structures.\n", result);
    } else {
        fprintf(stderr, "Processing failed.\n");
    }

    return 0;
}
