void initialize_message_array(MessageArray *messageArray, size_t initialCapacity) {
    pthread_mutex_lock(&messageArray->mutex);

    messageArray->array = malloc(initialCapacity * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!messageArray->array) {
        log_event("Memory allocation failed during initialization");
        pthread_mutex_unlock(&messageArray->mutex);
        return;
    }

    messageArray->size = 0;
    messageArray->capacity = initialCapacity;

    pthread_mutex_unlock(&messageArray->mutex);
}

void resize_message_array(MessageArray *messageArray) {
    pthread_mutex_lock(&messageArray->mutex);

    if (messageArray->size >= messageArray->capacity) {
        size_t new_capacity = messageArray->capacity + MEMORY_INCREMENT;
        LTE_DL_CCCH_Message_Type1_T *new_array = realloc(messageArray->array, new_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));

        if (!new_array) {
            log_event("Memory reallocation failed during resizing");
            pthread_mutex_unlock(&messageArray->mutex);
            return;
        }

        messageArray->array = new_array;
        messageArray->capacity = new_capacity;
    }

    pthread_mutex_unlock(&messageArray->mutex);
}

