    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_event("Failed to open file for serialization");
        return -1;
    }

    size_t written = fwrite(messageArray->array, sizeof(LTE_DL_CCCH_Message_Type1_T), messageArray->size, file);

    fclose(file);

    if (written != messageArray->size) {
        log_event("Serialization failed: incomplete write operation");
        return -1;
    }

    log_event("Serialization completed successfully");
    return 0;
}

