typedef struct {
    long timestamp;
    int sensor_id;
    float value;
} Measurement;

typedef struct MeasurementNode {
    Measurement data;
    struct MeasurementNode* next;
} MeasurementNode;

typedef struct {
    MeasurementNode* head;
    pthread_mutex_t lock;
} MeasurementList;

typedef struct {
    unsigned long RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    unsigned int CRC_INDICATION_REL8_TAG_CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global data structures
MeasurementList timestamp_list = {NULL, PTHREAD_MUTEX_INITIALIZER};
float* sensor_readings = NULL;
unsigned long* long_timestamps = NULL;
int sensor_count = 0;

void initialize_structures(int initial_size) {
    pthread_mutex_lock(&timestamp_list.lock);

    if (sensor_readings) free(sensor_readings);
    if (long_timestamps) free(long_timestamps);

    sensor_readings = malloc(initial_size * sizeof(float));
    long_timestamps = malloc(initial_size * sizeof(unsigned long));

    for (int i = 0; i < initial_size; ++i) {
        MeasurementNode* new_node = malloc(sizeof(MeasurementNode));
        new_node->data.timestamp = time(NULL);
        new_node->data.sensor_id = rand() % 100;
        new_node->data.value = (float)(rand() % 1000) / 10.0f;
        new_node->next = timestamp_list.head;
        timestamp_list.head = new_node;
    }

    pthread_mutex_unlock(&timestamp_list.lock);
}

void reset_structures() {
    pthread_mutex_lock(&timestamp_list.lock);

    MeasurementNode* current = timestamp_list.head;
    while (current) {
        MeasurementNode* temp = current;
        current = current->next;
        free(temp);
    }
    timestamp_list.head = NULL;

    if (sensor_readings) free(sensor_readings);
    if (long_timestamps) free(long_timestamps);

    sensor_readings = NULL;
    long_timestamps = NULL;

    pthread_mutex_unlock(&timestamp_list.lock);
}

void manage_memory_and_data(int new_sensor_count) {
    // Resize if necessary
    if (sensor_count < new_sensor_count) {
        initialize_structures(new_sensor_count);
        sensor_count = new_sensor_count;
    }

    // Simulate data processing and reset periodically
    static int cycle = 0;
    if (++cycle % 10 == 0) { 
        reset_structures();
        initialize_structures(sensor_count); // Reinitialize with the current size
    }
}

NFAPI_CRC_INDICATION_PDU_T create_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = rand();
    pdu.CRC_INDICATION_REL8_TAG_CRCFLAG = rand() % 2; // Random CRC flag
    return pdu;
}

void handle_data_flow(int data_rate) {
    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        int* rate = malloc(sizeof(int));
        *rate = data_rate;
        pthread_create(&threads[i], NULL, (void*)manage_memory_and_data, rate);
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
        free(rate);
    }
}

int main() {
    srand(time(NULL));
    handle_data_flow(100); // Simulate data flow with a specific rate
    return 0;
}
