// Memory pool structure for efficient allocation management
typedef struct {
    void *pool;
    size_t pool_size;
    size_t current_position;
    int block_size;
} MemoryPool;

// Function to initialize a memory pool
MemoryPool* create_memory_pool(size_t initial_size, size_t block_size) {
    MemoryPool *mp = (MemoryPool *)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool = malloc(initial_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    mp->pool_size = initial_size;
    mp->current_position = 0;
    mp->block_size = block_size;

    return mp;
}

// Function to allocate memory from the pool
void* allocate_from_pool(MemoryPool *mp, size_t size) {
    if (size > mp->block_size || mp->current_position + size > mp->pool_size)
        return NULL; // Allocation failed

    void *ptr = (char *)mp->pool + mp->current_position;
    mp->current_position += size;
    return ptr;
}

// Function to free the memory pool
void free_memory_pool(MemoryPool *mp) {
    if (!mp) return;

    if (mp->pool)
        free(mp->pool);

    free(mp);
}

