// Function to update parents for a range of items
void set_parents(Item *items, int start_index, int end_index, Item *parent) {
    if (start_index < 0 || end_index >= count || start_index > end_index) return;

    for (int i = start_index; i <= end_index; ++i) {
        items[i].parent = parent;
    }
}

// Function to free allocated memory
void free_items(Item *items, int count) {
    if (!items) return;

    for (int i = 0; i < count; ++i) {
        free(items[i].name); // Free the name string
    }

    free(items); // Free the array of items
}

