#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node in the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Linked list structure
typedef struct {
    Node* head;
    pthread_mutex_t lock; // Mutex for thread safety
} CRCList;

CRCList* createList() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void freeNode(Node* node) {
    free(node);
}

void clearAndResetList(CRCList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        freeNode(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

int appendToCRCList(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) return -1;

    Node** node = &list->head;
    pthread_mutex_lock(&list->lock);

    // Check for duplicate RNTI
    while (*node) {
        if ((*node)->data.RNTI == pdu.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return 0; // Duplicate found, do not append
        }
        node = &(*node)->next;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }

    memcpy(&newNode->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->next = NULL;
    *node = newNode;

    pthread_mutex_unlock(&list->lock);
    return 1;
}

NFAPI_CRC_INDICATION_PDU_T* retrieveFromCRCList(CRCList* list, unsigned int rnti) {
    if (!list) return NULL;

    Node* current = list->head;
    pthread_mutex_lock(&list->lock);

    while (current) {
        if (current->data.RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* pduCopy = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pduCopy) {
                pthread_mutex_unlock(&list->lock);
                return NULL;
            }
            memcpy(pduCopy, &current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list->lock);
            return pduCopy;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

void destroyList(CRCList* list) {
    if (!list) return;

    clearAndResetList(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Simulate network transmission with retry mechanism
int transmitNetwork(NFAPI_CRC_INDICATION_PDU_T* pdu, int maxRetries) {
    int attempt = 0;
    int success = 0;

    while (attempt < maxRetries && !success) {
        // Simulated network transmission logic
        // Use exponential backoff
        int delay = (1 << attempt);
        printf("Transmitting PDU with RNTI %u, Attempt: %d\n", pdu->RNTI, attempt + 1);

        success = rand() % 2; // Randomly simulate success/failure

        if (!success) {
            sleep(delay); // Wait before retrying
        }
        attempt++;
    }

    return success;
}

// Batch transmission for efficiency
void batchTransmit(CRCList* list, int maxRetries) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (!transmitNetwork(&current->data, maxRetries)) {
            printf("Failed to transmit PDU with RNTI %u after retries\n", current->data.RNTI);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Main function for demonstration
int main() {
    CRCList* list = createList();
    if (!list) return -1;

    srand(time(NULL)); // Seed random number generator

    // Create and append some PDUs to the list
    for (int i = 0; i < 5; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 100;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 ? '1' : '0';

        if (appendToCRCList(list, pdu) != 1) {
            printf("Failed to append PDU with RNTI %u\n", pdu.RNTI);
        }
    }

    // Transmit all PDUs in the list
    batchTransmit(list, 3);

    clearAndResetList(list);
    destroyList(list);

    return 0;
}
```

