['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int latency;
    int throughput;
    float packet_loss;
} MeasurementResults;

typedef struct Node {
    time_t timestamp;
    unsigned long session_id;
    MeasurementResults results;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int max_entries;
} DoublyLinkedList;

// Function to generate a unique session ID
unsigned long generate_unique_session_id(DoublyLinkedList* list) {
    static unsigned long next_id = 1;
    while (1) {
        unsigned long id = next_id++;
        // Check uniqueness within the list
        Node* current = list->head;
        while (current != NULL) {
            if (current->session_id == id) return generate_unique_session_id(list);
            current = current->next;
        }
        return id;
    }
}

// Function to initialize and populate the doubly linked list
void init_and_populate_list(DoublyLinkedList* list, int num_entries, time_t retention_policy) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->max_entries = 0;

    for (int i = 0; i < num_entries; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed\n");
            continue;
        }

        pthread_mutex_lock(&list->lock);

        time_t now = time(NULL);
        new_node->timestamp = now;

        new_node->session_id = generate_unique_session_id(list);

        // Populate random measurement results
        srand(time(NULL) ^ (intptr_t)new_node); // Seed with timestamp and node pointer
        new_node->results.latency = rand() % 1000;       // Random latency in ms
        new_node->results.throughput = rand() % 10000;   // Random throughput in Mbps
        new_node->results.packet_loss = (float)(rand() % 100) / 10.0f; // Random packet loss in %

        // Insert the node into the list
        if (list->tail == NULL) {
            list->head = new_node;
            list->tail = new_node;
        } else {
            list->tail->next = new_node;
            new_node->prev = list->tail;
            list->tail = new_node;
        }

        pthread_mutex_unlock(&list->lock);
    }

    // Periodically clean up outdated metrics
    if (pthread_create(NULL, NULL, cleanup_outdated_metrics, (void*)list) != 0) {
        fprintf(stderr, "Failed to create cleanup thread\n");
    }
}

// Cleanup function for outdated metrics
void* cleanup_outdated_metrics(void* arg) {
    DoublyLinkedList* list = (DoublyLinkedList*)arg;
    while (1) {
        pthread_mutex_lock(&list->lock);

        time_t current_time = time(NULL);
        Node *current = list->head, *to_delete = NULL;

        while (current != NULL) {
            if ((current_time - current->timestamp) > retention_policy) {
                to_delete = current;
                current = current->next;

                if (to_delete->prev)
                    to_delete->prev->next = to_delete->next;
                if (to_delete->next)
                    to_delete->next->prev = to_delete->prev;

                if (list->head == to_delete) list->head = to_delete->next;
                if (list->tail == to_delete) list->tail = to_delete->prev;

                free(to_delete);
            } else {
                current = current->next;
            }
        }

        pthread_mutex_unlock(&list->lock);

        sleep(retention_policy); // Sleep according to the retention policy
    }
}

// Example usage
int main() {
    DoublyLinkedList list;
    init_and_populate_list(&list, 10, 60); // Initialize with 10 entries and a 60-second retention policy

    return 0;
}
```

This code initializes and populates a doubly linked list with unique session identifiers and random measurement results. It supports concurrent operations with thread-safe access using `pthread_mutex_t`. The cleanup function runs in a separate thread to remove outdated metrics based on a specified retention policy, optimizing memory usage while considering CPU overhead.']

