#define MAX_MEMORY_USAGE 1024 * 1024 // Example threshold in bytes
#define INITIAL_CAPACITY 10

typedef struct {
    int config_id;
    char* mac_address;
} LMAC_CONFIG;

typedef struct {
    LMAC_CONFIG lmac_config;
    char** mac_addresses; // List of MAC addresses
    size_t num_mac_addresses;
} MAC_CONTEXT_T;

// Global variables for resource management and concurrency control
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t current_memory_usage = 0;
size_t capacity = INITIAL_CAPACITY;
MAC_CONTEXT_T* contexts = NULL;

// Function to add a new context
int add_context(MAC_CONTEXT_T new_context) {
    pthread_mutex_lock(&mutex);

    // Check memory usage
    size_t estimated_new_usage = sizeof(MAC_CONTEXT_T) + 
                                sizeof(char*) * (new_context.num_mac_addresses + 1);
    if (current_memory_usage + estimated_new_usage > MAX_MEMORY_USAGE) {
        pthread_mutex_unlock(&mutex);
        fprintf(stderr, "Error: Memory limit exceeded.\n");
        return -1;
    }

    // Resize contexts array if necessary
    if (capacity == current_memory_usage / sizeof(MAC_CONTEXT_T)) {
        size_t new_capacity = capacity * 2;
        MAC_CONTEXT_T* new_contexts = realloc(contexts, sizeof(MAC_CONTEXT_T) * new_capacity);
        if (!new_contexts) {
            pthread_mutex_unlock(&mutex);
            fprintf(stderr, "Error: Out of memory.\n");
            return -1;
        }
        contexts = new_contexts;
        capacity = new_capacity;
    }

    // Add the new context
    contexts[current_memory_usage / sizeof(MAC_CONTEXT_T)] = new_context;
    current_memory_usage += estimated_new_usage;

    pthread_mutex_unlock(&mutex);
    return 0;
}

// Function to update LMAC_CONFIG from external service
int update_lmac_config(int config_id, int new_config_value) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < current_memory_usage / sizeof(MAC_CONTEXT_T); ++i) {
        if (contexts[i].lmac_config.config_id == config_id) {
            contexts[i].lmac_config.config_id = new_config_value;
            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&mutex);
    fprintf(stderr, "Error: Config ID not found.\n");
    return -1;
}

// Function to free resources
void cleanup() {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < current_memory_usage / sizeof(MAC_CONTEXT_T); ++i) {
        free(contexts[i].mac_addresses);
        free(contexts[i].lmac_config.mac_address);
    }
    free(contexts);

    pthread_mutex_unlock(&mutex);
}

// Example unit test function
void test_add_context() {
    MAC_CONTEXT_T new_context = { .lmac_config = {1, NULL}, .num_mac_addresses = 0 };
    int result = add_context(new_context);
    if (result == 0) {
        printf("Test passed: Context added successfully.\n");
    } else {
        printf("Test failed: Failed to add context.\n");
    }
}

int main() {
    test_add_context();
    cleanup();
    return 0;
}
