['Below is a C implementation of the described task. This code includes memory management, validation against duplicate RNTI values, handling for maximum list size constraints, error codes, and basic mechanisms to deal with real-time data streaming and external inconsistencies.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

// Error codes
#define SUCCESS 0
#define OUT_OF_MEMORY -1
#define MAX_SIZE_REACHED -2
#define INVALID_INPUT -3

typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI; // Radio Network Temporary Identifier
    CRC_INDICATION_REL8_TAG crcTag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t max_size;
} DynamicList;

DynamicList* create_list(size_t max_size) {
    if (max_size == 0)
        return NULL;

    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list)
        return NULL;

    list->head = NULL;
    list->count = 0;
    list->max_size = max_size;
    return list;
}

bool has_duplicate_rnti(DynamicList* list, uint16_t rnti) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti)
            return true;
        current = current->next;
    }
    return false;
}

int insert_into_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || list->count >= list->max_size)
        return MAX_SIZE_REACHED;

    if (has_duplicate_rnti(list, pdu.RNTI))
        return INVALID_INPUT;

    Node* new_node = malloc(sizeof(Node));
    if (!new_node)
        return OUT_OF_MEMORY;

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    // Simulating the CRCFLAG set with a random number for demonstration
    new_node->data.crcTag.CRCFLAG = rand() % 256; 

    return SUCCESS;
}

void free_list(DynamicList* list) {
    if (!list)
        return;

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    free(list);
}

