// Helper function to find the largest integer
int findLargestInteger(int *array, size_t size) {
    int largest = array[0];
    for (size_t i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

// Main processing function
void processInputAndGenerateCRCIndications() {
    clock_t start_time, end_time;
    double cpu_time_used;

    int *numbers = NULL;
    size_t count = 0;
    size_t capacity = 10;
    numbers = malloc(capacity * sizeof(int));
    if (numbers == NULL) {
        logMessage("Memory allocation failed");
        return;
    }

