    // Read integers from standard input
    while (1) {
        int num;
        char line[256];
        if (!fgets(line, sizeof(line), stdin)) break;

        if (sscanf(line, "%d", &num) == 1) {
            if (count >= capacity) {
                capacity *= 2;
                numbers = realloc(numbers, capacity * sizeof(int));
                if (numbers == NULL) {
                    logMessage("Memory reallocation failed");
                    free(numbers);
                    return;
                }
            }
            numbers[count++] = num;
        } else {
            logMessage("Invalid input encountered");
        }
    }

    // Find and print the largest integer
    if (count > 0) {
        int largest = findLargestInteger(numbers, count);
        printf("Largest Integer: %d\n", largest);
    } else {
        printf("No valid integers were processed.\n");
    }

    end_time = clock();
    cpu_time_used = ((double)(end_time - start_time)) / CLOCKS_PER_SEC;
    logMessage((const char *)asprintf(NULL, "Processing completed in %.2f seconds", cpu_time_used));

    // Generate CRC indication structures
    RNG rng = {0, 1}; // CRCFLAG range between 0 and 1
    size_t numIndications = count; // Assuming one per input integer for simplicity

    NFAPI_CRC_INDICATION_PDU_T *indications = malloc(numIndications * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (indications == NULL) {
        logMessage("Memory allocation failed for CRC indications");
        free(numbers);
        return;
    }

    for (size_t i = 0; i < numIndications; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = numbers[i];
        indications[i].RNTI = rngRandomInt(&rng); // Example RNTI generation
        indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rngRandomInt(&rng);
    }

    // Print the CRC indication structures (for demonstration)
    for (size_t i = 0; i < numIndications; ++i) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               indications[i].RX_UE_INFORMATION_TAG,
               indications[i].RNTI,
               indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG);
    }

    free(numbers);
    free(indications);
}

int main() {
    // Seed the random number generator
    srand((unsigned int)time(NULL));

    printf("Enter integers (press Ctrl+D to end):\n");
    processInputAndGenerateCRCIndications();

    return 0;
}
