typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} CRCIndicationPduManager;

// Initialize the dynamic array manager
int init_crc_pdu_manager(CRCIndicationPduManager *manager) {
    if (pthread_mutex_init(&manager->mutex, NULL) != 0) return -1;

    manager->capacity = 10000; // Initial capacity
    manager->size = 0;

    manager->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        pthread_mutex_destroy(&manager->mutex);
        return -1;
    }

    return 0;
}

// Resize the dynamic array
int resize_crc_pdu_manager(CRCIndicationPduManager *manager, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;

    manager->array = new_array;
    manager->capacity = new_capacity;
    return 0;
}

// Add a new NFAPI_CRC_INDICATION_PDU_T to the array
int add_crc_pdu(CRCIndicationPduManager *manager, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        int status = resize_crc_pdu_manager(manager, new_capacity);
        if (status != 0) {
            pthread_mutex_unlock(&manager->mutex);
            return -1;
        }
    }

    // Copy the data
    manager->array[manager->size++] = *pdu;

    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

// Free the dynamic array and associated resources
void free_crc_pdu_manager(CRCIndicationPduManager *manager) {
    pthread_mutex_lock(&manager->mutex);

    free(manager->array);
    manager->array = NULL;
    manager->capacity = 0;
    manager->size = 0;

    pthread_mutex_unlock(&manager->mutex);
    pthread_mutex_destroy(&manager->mutex);
}

