#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        unsigned char CRC_INDICATION_REL8_TAG;
        unsigned short CRCFLAG; // Randomly set value
    } crc_info;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    int successful_allocations;
    int allocation_failures;
    int verbosity_level; // 0: None, 1: Basic, 2: Detailed
} NFAPI_List;

void log_event(const char* message, int level) {
    if (level <= verbosity_level) {
        printf("%s\n", message);
    }
}

NFAPI_List* create_list(int verbosity) {
    NFAPI_List* list = (NFAPI_List*)malloc(sizeof(NFAPI_List));
    if (!list) {
        log_event("Failed to allocate memory for list.", 1);
        return NULL;
    }

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->successful_allocations = 0;
    list->allocation_failures = 0;
    list->verbosity_level = verbosity;

    log_event("List created successfully.", 2);
    return list;
}

int push_back(NFAPI_List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_event("Failed to allocate memory for node.", 1);
        pthread_mutex_unlock(&list->lock);
        list->allocation_failures++;
        return -1;
    }

    new_node->data = data;
    new_node->next = NULL;

    // Randomly set CRCFLAG
    srand(time(NULL) ^ (unsigned int)pthread_self());
    new_node->data.crc_info.CRCFLAG = rand() & 0xFFFF;

    if (!list->head) {
        list->head = new_node;
    } else {
        Node* temp = list->head;
        while (temp->next) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    list->successful_allocations++;
    log_event("Node pushed successfully.", 2);

    return 0;
}

void free_list(NFAPI_List* list) {
    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);

    log_event("List deallocated successfully.", 2);
}

void print_statistics(NFAPI_List* list) {
    printf("Successful Allocations: %d\n", list->successful_allocations);
    printf("Allocation Failures: %d\n", list->allocation_failures);
}

