// Main function to create and initialize the list
NFAPI_CRC_INDICATION_PDU_T* allocate_nfa_pdu_list(size_t count, const char *keywords[]) {
    if (count == 0 || keywords == NULL) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        async_log("Memory allocation failed for list");
        return NULL;
    }

    char keyword_keys[KEYWORDS_COUNT][METADATA_SIZE];
    strncpy(keyword_keys, keywords, KEYWORDS_COUNT * METADATA_SIZE);

    int last_timestamp = 0;
    int unique_metadata_count = 0;

    for (size_t i = 0; i < count; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand();
        list[i].RNTI = rand() & 0xFFFF;
        list[i].crc_tag.CRCFLAG = rand() % (CRCFLAG_MAX + 1);

        int random_value = generate_random_value(0, 100);
        snprintf(list[i].crc_tag.string_repr, sizeof(list[i].crc_tag.string_repr), "%d", random_value);

        time_t now;
        time(&now);
        if ((long)now <= last_timestamp) {
            async_log("Timestamp not monotonically increasing");
            free(list);
            return NULL;
        }
        list[i].creation_time = now;
        last_timestamp = (int)now;

        do {
            int keyword_index = rand() % KEYWORDS_COUNT;
            snprintf(list[i].metadata, METADATA_SIZE, "%s_%d", keyword_keys[keyword_index], unique_metadata_count++);
        } while (!is_metadata_unique(list, i + 1, list[i].metadata));

        async_log("Record initialized successfully");
    }

    return list;
}

// Utility function to check metadata uniqueness
int is_metadata_unique(NFAPI_CRC_INDICATION_PDU_T *list, size_t count, const char *metadata) {
    for (size_t i = 0; i < count; ++i) {
        if (strcmp(list[i].metadata, metadata) == 0) {
            return 0;
        }
    }
    return 1;
}

