#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_LIMIT 1048576 // 1 MB in bytes
#define CHUNK_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

