    int message_type;
} NAS_Message;

typedef struct {
    LTE_DL_CCCH_Message_Type1_T *messages;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} MessageArray;

// Custom memory allocator (simplified example)
void* custom_alloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void custom_free(void *ptr) {
    free(ptr);
}

// Logging system
int successful_initializations = 0;
int allocation_failures = 0;

void log_status(const char* message) {
    printf("%s\n", message);
}

// Validation mechanism (placeholder)
int validate_message(LTE_DL_CCCH_Message_Type1_T *message) {
    return message != NULL && message->crc_pdu.RX_UE_INFORMATION_TAG >= 0 &&
           message->crc_pdu.RNTI >= 0 && message->crc_rel8_tag.CRCFLAG >= 0;
}

// Function to initialize and populate the array
int init_message_array(MessageArray *array) {
    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
    array->capacity = CHUNK_SIZE;

    array->messages = (LTE_DL_CCCH_Message_Type1_T *)custom_alloc(array->capacity * sizeof(LTE_DL_CCCH_Message_TYPE1_T));
    if (!array->messages) {
        allocation_failures++;
        log_status("Failed to allocate initial memory for messages.");
        return -1;
    }

    while (array->count < 1000) {
        size_t required_size = (array->count + CHUNK_SIZE) * sizeof(LTE_DL_CCCH_Message_TYPE1_T);
        if (required_size > MAX_MEMORY_LIMIT) break;

        LTE_DL_CCCH_Message_Type1_T* temp_messages = (LTE_DL_CCCH_Message_Type1_T *)
            custom_alloc(required_size);
        if (!temp_messages) {
            allocation_failures++;
            log_status("Failed to reallocate memory for messages.");
            continue;
        }

        memcpy(temp_messages, array->messages, array->count * sizeof(LTE_DL_CCCH_MESSAGE_TYPE1_T));
        custom_free(array->messages);

        array->messages = temp_messages;
        array->capacity += CHUNK_SIZE;

        for (size_t i = array->count; i < array->count + CHUNK_SIZE && i < 1000; ++i) {
            LTE_DL_CCCH_Message_Type1_T *message = &array->messages[i];
            message->crc_pdu.RX_UE_INFORMATION_TAG = rand() % 256;
            message->crc_pdu.RNTI = rand() % 1024;

            message->crc_rel8_tag.CRCFLAG = rand() % 2;

            NAS_Message nas_message;
            snprintf(nas_message.content, sizeof(nas_message.content), "Message %zu", i);
            nas_message.message_type = rand() % 10 + 1; // Random type between 1 and 10

            if (!validate_message(message)) {
                log_status("Validation failed for message.");
                continue;
            }

            successful_initializations++;
        }

        array->count += CHUNK_SIZE;

        if (array->count >= 1000) break;
    }

    return 0;
}

// Function to free the allocated memory
void free_message_array(MessageArray *array) {
    pthread_mutex_lock(&array->lock);
    custom_free(array->messages);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}
