    size_t failed_allocations;
} AllocationStats;

// Dynamic list structure
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// List structure with thread-safe management
typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    AllocationStats stats;
    int log_allocations; // Flag for logging events
} DynamicList;

DynamicList* create_dynamic_list(int enable_logging) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->stats.successful_allocations = 0;
    list->stats.failed_allocations = 0;
    list->log_allocations = enable_logging;

    return list;
}

void free_node(Node* node) {
    if (node) {
        free(node);
    }
}

int random_crcflag() { 
    return rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

NFAPI_CRC_INDICATION_PDU_T generate_pdu(int index) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = index;
    pdu.RNTI = index * 100; // Example mapping for RNTI
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = random_crcflag();
    return pdu;
}

int add_to_list(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list) return -1;

    pthread_mutex_lock(&list->mutex);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        list->stats.failed_allocations++;
        if (list->log_allocations)
            printf("Failed to allocate memory for a new node.\n");
        return -1;
    }

    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->stats.successful_allocations++;

    if (list->log_allocations)
        printf("Allocated and added new node with RNTI: %d\n", data.RNTI);

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void free_list(DynamicList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);

    if (list->log_allocations)
        printf("All nodes deallocated and list destroyed.\n");
}

void print_allocation_stats(const DynamicList* list) {
    printf("Successful Allocations: %zu\n", list->stats.successful_allocations);
    printf("Failed Allocations: %zu\n", list->stats.failed_allocations);
}

int main() {
    srand((unsigned int)time(NULL)); // Seed for random number generation

    DynamicList* nfa_list = create_dynamic_list(1); // Enable logging
    if (!nfa_list) {
        printf("Failed to create dynamic list.\n");
        return 1;
