#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define data structures
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRC_INDICATION_REL8_TAG;
        unsigned char CRCFLAG; // Randomly set to 0 or 1
    } crc_info;
} NFAPI_CRC_INDICATION_PDU_T;

// Define constants for logging verbosity levels
typedef enum {
    LOG_NONE,
    LOG_LOW,
    LOG_HIGH
} LogLevel;

// Configuration for the logging system
LogLevel log_level = LOG_LOW;

// Mutex and condition variable for thread safety
pthread_mutex_t lock;
pthread_cond_t cond_var;

// Hash table to manage unique offsets and keys
#define HASH_TABLE_SIZE 10000

typedef struct HashNode {
    int offset;
    int key;
    struct HashNode* next;
} HashNode;

HashNode* hash_table[HASH_TABLE_SIZE];

unsigned long hash_function(int key) {
    return key % HASH_TABLE_SIZE;
}

// Function prototypes
void log_event(const char* event, LogLevel level);
int add_to_hash_table(int offset, int key);
int validate_and_deduplicate(int* offsets, int* keys, size_t num_entries);

// Logging function
void log_event(const char* event, LogLevel level) {
    if (level >= log_level) {
        printf("%s\n", event);
    }
}

// Hash table functions
int add_to_hash_table(int offset, int key) {
    unsigned long index = hash_function(key);
    pthread_mutex_lock(&lock);

    HashNode* head = hash_table[index];
    while (head) {
        if (head->offset == offset && head->key == key) {
            pthread_mutex_unlock(&lock);
            return 0; // Duplicate found
        }
        head = head->next;
    }

    HashNode* new_node = (HashNode*)malloc(sizeof(HashNode));
    if (!new_node) {
        log_event("Memory allocation failed for hash table.", LOG_HIGH);
        pthread_mutex_unlock(&lock);
        return -1; // Allocation failure
    }

    new_node->offset = offset;
    new_node->key = key;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;

    log_event("Added to hash table.", LOG_LOW);

    pthread_mutex_unlock(&lock);
    return 1; // Successfully added
}

int validate_and_deduplicate(int* offsets, int* keys, size_t num_entries) {
    for (size_t i = 0; i < num_entries; ++i) {
        if (!add_to_hash_table(offsets[i], keys[i])) {
            log_event("Duplicate entry found and removed.", LOG_LOW);
        }
    }
    return 1;
}

// Dynamic list management functions
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
size_t count = 0;

void add_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_event("Memory allocation failed for PDU list.", LOG_HIGH);
        pthread_mutex_unlock(&lock);
        return;
    }

    new_node->data = pdu;
    srand(time(NULL)); // Seed random number generator
    new_node->data.crc_info.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    new_node->next = head;
    head = new_node;
    ++count;

    log_event("PDU added to list.", LOG_LOW);

    pthread_mutex_unlock(&lock);
}

void remove_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;

    pthread_mutex_lock(&lock);

    Node** current = &head;
    while (*current) {
        if ((*current)->data.RX_UE_INFORMATION_TAG == pdu->RX_UE_INFORMATION_TAG &&
            (*current)->data.RNTI == pdu->RNTI) {
            Node* temp = *current;
            *current = (*current)->next;
            free(temp);
            --count;

            log_event("PDU removed from list.", LOG_LOW);
            pthread_mutex_unlock(&lock);
            return;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&lock);
}

void free_list() {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    head = NULL;
    count = 0;

    log_event("All PDUs deallocated.", LOG_LOW);

    pthread_mutex_unlock(&lock);
}

// Initialization and cleanup functions
void init_system() {
    memset(hash_table, 0, sizeof(hash_table));
    pthread_mutex_init(&lock, NULL);
    pthread_cond_init(&cond_var, NULL);
}

void cleanup_system() {
    free_list();
    for (int i = 0; i < HASH_TABLE_SIZE; ++i) {
        HashNode* current = hash_table[i];
        while (current) {
            HashNode* temp = current;
            current = current->next;
            free(temp);
        }
    }
    pthread_mutex_destroy(&lock);
    pthread_cond_destroy(&cond_var);
}

// Main function for testing
int main() {
    init_system();

    int offsets[] = {1, 2, 3, 4, 5};
    int keys[] = {10, 20, 30, 40, 50};

    validate_and_deduplicate(offsets, keys, sizeof(offsets) / sizeof(int));

    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = 12345;
    pdu.RNTI = 54321;

    add_pdu(pdu);
    remove_pdu(&pdu);

    cleanup_system();
    return 0;
}
```']

