#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int UE_ID;
    // Assume RLC_PDU_LIST and MAC_TX_BUFFER are defined elsewhere.
    void *rlc_pdu_list;
    void *mac_tx_buffer;
} NR_UE_CONTEXT;

typedef struct {
    NR_UE_CONTEXT **contexts;  // Dynamic array of pointers to NR_UE_CONTEXT
    size_t capacity;           // Current allocated capacity
    size_t size;               // Number of active UE contexts
    pthread_mutex_t lock;      // Mutex for thread-safe operations
} NR_UE_MANAGER;

// Function prototypes
NR_UE_MANAGER* create_ue_manager(size_t initial_capacity);
int add_ue_context(NR_UE_MANAGER *manager, int ue_id, void *rlc_pdu_list, void *mac_tx_buffer);
int update_ue_context(NR_UE_MANAGER *manager, int ue_id, void *new_rlc_pdu_list, void *new_mac_tx_buffer);
NR_UE_CONTEXT* get_ue_context(const NR_UE_MANAGER *manager, int ue_id);
void free_ue_manager(NR_UE_MANAGER *manager);

// Function definitions
NR_UE_MANAGER* create_ue_manager(size_t initial_capacity) {
    NR_UE_MANAGER *manager = (NR_UE_MANAGER*) malloc(sizeof(NR_UE_MANAGER));
    manager->contexts = (NR_UE_CONTEXT**) calloc(initial_capacity, sizeof(NR_UE_CONTEXT*));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

int add_ue_context(NR_UE_MANAGER *manager, int ue_id, void *rlc_pdu_list, void *mac_tx_buffer) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i]->UE_ID == ue_id) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // UE_ID already exists
        }
    }

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        NR_UE_CONTEXT **new_contexts = (NR_UE_CONTEXT**) realloc(manager->contexts, new_capacity * sizeof(NR_UE_CONTEXT*));
        if (!new_contexts) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failure
        }
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }

    NR_UE_CONTEXT *context = (NR_UE_CONTEXT*) malloc(sizeof(NR_UE_CONTEXT));
    if (!context) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failure
    }
    context->UE_ID = ue_id;
    context->rlc_pdu_list = rlc_pdu_list;
    context->mac_tx_buffer = mac_tx_buffer;

    manager->contexts[manager->size++] = context;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int update_ue_context(NR_UE_MANAGER *manager, int ue_id, void *new_rlc_pdu_list, void *new_mac_tx_buffer) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i]->UE_ID == ue_id) {
            manager->contexts[i]->rlc_pdu_list = new_rlc_pdu_list;
            manager->contexts[i]->mac_tx_buffer = new_mac_tx_buffer;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // UE_ID not found
}

NR_UE_CONTEXT* get_ue_context(const NR_UE_MANAGER *manager, int ue_id) {
    pthread_mutex_lock((pthread_mutex_t*)&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i]->UE_ID == ue_id) {
            NR_UE_CONTEXT* context = manager->contexts[i];
            pthread_mutex_unlock((pthread_mutex_t*)&manager->lock);
            return context;
        }
    }

    pthread_mutex_unlock((pthread_mutex_t*)&manager->lock);
    return NULL; // UE_ID not found
}

void free_ue_manager(NR_UE_MANAGER *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->contexts[i]);
    }
    free(manager->contexts);

    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

// Example function to periodically update UE status
void *periodic_ue_status_update(void *arg) {
    NR_UE_MANAGER *manager = (NR_UE_MANAGER*) arg;

    while (1) {
        // Simulate periodic updates, replace with actual logic
        pthread_mutex_lock(&manager->lock);
        for (size_t i = 0; i < manager->size; ++i) {
            // Update RLC PDU list or MAC TX buffer as needed
            // Example: ((NR_UE_CONTEXT*)manager->contexts[i])->rlc_pdu_list = updated_rlc_pdu_list;
        }
        pthread_mutex_unlock(&manager->lock);

        sleep(1); // Simulate periodic update interval
    }

    return NULL;
}
```

