            free(records);
            free(used_metadata);
            return EXIT_FAILURE;
        }
        records[i].timestamp = current_time;
        last_timestamp = current_time;

        int metadata_index;
        do {
            metadata_index = rand() % config.metadata_set_size;
        } while (used_metadata[metadata_index]);

        used_metadata[metadata_index] = 1; // Mark as used
        strncpy(records[i].metadata, metadata_keywords[metadata_index], sizeof(records[i].metadata));

        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Record %zu created with RNTI: %d", i + 1, records[i].rnti);
        log_message_async(&logger, log_message);
    }

    // Free allocated resources
    free(records);
    free(used_metadata);
    pthread_mutex_destroy(&logger.lock);

    return EXIT_SUCCESS;
}
