NFAPI_CRC_INDICATION_PDU_T* create_crc_list(int num_entries, int (*hash_function)(NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&crc_mutex);

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        log_message(ERROR, "Memory allocation failed for CRC list.");
        pthread_mutex_unlock(&crc_mutex);
        return NULL;
