            free(list);
            return NULL;
        }
    }

    log_message(INFO, "All CRC entries validated successfully.");

    return list;
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    if (list) {
        pthread_mutex_lock(&crc_mutex);

        free(list);
        log_message(DEBUG, "Freed the memory allocated for CRC list.");

        pthread_mutex_unlock(&crc_mutex);
    }
}
