int add_header(HeaderList *list, HttpResponseHeader header) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        HttpResponseHeader *new_headers = realloc(list->headers, sizeof(HttpResponseHeader) * new_capacity);
        if (!new_headers) {
