                int geo_success = fetch_geolocation_info(record->SOURCE_IP, country);
                if (!geo_success) {
                    log_error("Failed to retrieve geolocation information.");
                }
            }
        }

        if (!success) {
            log_error("Max retries reached for connection.");
            connections[i] = NULL;
        }
    }

    return connections;
}

