// Node for linked list
typedef struct PacketNode {
    DataPacket packet;
    struct PacketNode *next;
} PacketNode;

// Dynamic array management structure
typedef struct {
    PacketNode *head;
    pthread_mutex_t lock;
    time_t retention_period; // configurable retention period in seconds
    void (*custom_free)(void *ptr); // function pointer for custom memory deallocation
} DataPacketArray;

// Function to initialize the dynamic array
DataPacketArray* create_data_packet_array(time_t retention) {
    DataPacketArray *array = (DataPacketArray*)malloc(sizeof(DataPacketArray));
    if (!array) return NULL;

    array->head = NULL;
    pthread_mutex_init(&array->lock, NULL);
    array->retention_period = retention;
    array->custom_free = free; // default allocator
    return array;
}

// Thread-safe function to insert a new DataPacket
void insert_data_packet(DataPacketArray *array, const DataPacket *packet) {
    PacketNode *new_node = (PacketNode*)malloc(sizeof(PacketNode));
    if (!new_node) return;

    memcpy(&new_node->packet, packet, sizeof(DataPacket));
    new_node->packet.payload = malloc(packet->payload_size);
    if (new_node->packet.payload) {
        memcpy(new_node->packet.payload, packet->payload, packet->payload_size);
    }

    pthread_mutex_lock(&array->lock);

    // Insert at the head for simplicity
    new_node->next = array->head;
    array->head = new_node;

    pthread_mutex_unlock(&array->lock);
}

// Thread-safe function to delete a DataPacket by timestamp
void delete_data_packet(DataPacketArray *array, time_t timestamp) {
    pthread_mutex_lock(&array->lock);

    PacketNode **current = &array->head;
    while (*current) {
        if ((*current)->packet.timestamp == timestamp) {
            PacketNode *to_delete = *current;
            *current = to_delete->next;

            free(to_delete->packet.payload);
            free(to_delete);
            break;
        }
        current = &(*current)->next;
    }

    pthread_mutex_unlock(&array->lock);
}

// Thread-safe function to prune outdated packets
void prune_outdated_packets(DataPacketArray *array) {
    time_t now = time(NULL);

    pthread_mutex_lock(&array->lock);

    PacketNode **current = &array->head;
    while (*current) {
        if (now - (*current)->packet.timestamp > array->retention_period) {
            PacketNode *to_delete = *current;
            *current = to_delete->next;

            free(to_delete->packet.payload);
            free(to_delete);
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&array->lock);
}

// Function to set a custom memory allocator
void set_custom_allocator(DataPacketArray *array, void (*custom_free)(void *)) {
    array->custom_free = custom_free;
}

// Cleanup function for the dynamic array
void free_data_packet_array(DataPacketArray *array) {
    pthread_mutex_lock(&array->lock);

    PacketNode *current = array->head;
    while (current) {
        PacketNode *to_delete = current;
        current = current->next;

        array->custom_free(to_delete->packet.payload);
        array->custom_free(to_delete);
    }

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

// Example usage of custom allocator
void custom_allocator_free(void *ptr) {
    // Implement a custom deallocation logic if necessary
    free(ptr);
}
```

This implementation provides a dynamic array for managing `DataPacket` structures with thread-safe operations. The custom allocator functionality is provided, and the code handles insertion, deletion, and periodic pruning based on retention periods.']

