unsigned int generate_random_number() {
    return rand();
}

// Function to calculate checksum
unsigned long calculate_checksum(NFAPI_CRC_INDICATION_PDU_T *array, size_t count) {
    unsigned long checksum = 0;
    for (size_t i = 0; i < count; ++i) {
        checksum += array[i].crc_tag.CRCFLAG;
    }
    return checksum;
}

// Main function to allocate and populate the array
NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(size_t N, int *success) {
    if (N > MAX_UE_COUNT) {
        *success = 0;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *success = 0;
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < N; ++i) {
        array[i].crc_tag.CRCFLAG = generate_random_number();
    }

    int retry_count = 0;
    unsigned long checksum;

    do {
        checksum = calculate_checksum(array, N);
        if (checksum == CHECKSUM_PREDEFINED_VALUE) {
            *success = 1;
            return array;
        }
        retry_count++;
    } while (retry_count < 3);

    // Fallback strategy: process a subset of the data
    size_t fallback_size = N / 2; // Process half the data as a fallback
    for (size_t i = 0; i < fallback_size; ++i) {
        array[i].crc_tag.CRCFLAG = generate_random_number();
    }

    checksum = calculate_checksum(array, fallback_size);
    if (checksum == CHECKSUM_PREDEFINED_VALUE) {
        *success = 1;
    } else {
        *success = 0;
    }

    return array; // Return even on failure to allow graceful degradation
}

// Example usage
int main() {
    int success;
    size_t N = 5000; // Number of UEs

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = allocate_and_populate_array(N, &success);

    if (success) {
        printf("Array allocated and populated successfully.\n");
    } else {
        printf("Failed to allocate/populate array with valid checksum. Using fallback strategy.\n");
    }

    free(pdu_array);
    return 0;
}
