['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Measurement {
    double value;
    struct Measurement* next;
} Measurement;

typedef struct NetworkPerformanceMetrics {
    time_t timestamp;
    char session_id[64];
    Measurement* measurements_head;
    struct NetworkPerformanceMetrics* prev;
    struct NetworkPerformanceMetrics* next;
} NetworkPerformanceMetrics;

typedef struct List {
    NetworkPerformanceMetrics* head;
    NetworkPerformanceMetrics* tail;
    pthread_mutex_t lock;
    size_t entry_count;
} List;

List* list_init() {
    List* list = malloc(sizeof(List));
    if (!list) return NULL;

    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->entry_count = 0;
    return list;
}

void list_destroy(List* list);

NetworkPerformanceMetrics* create_metrics_node(time_t timestamp, const char* session_id) {
    NetworkPerformanceMetrics* node = malloc(sizeof(NetworkPerformanceMetrics));
    if (!node) return NULL;

    node->timestamp = timestamp;
    strncpy(node->session_id, session_id, sizeof(node->session_id) - 1);
    node->measurements_head = NULL;
    node->prev = node->next = NULL;

    return node;
}

void add_measurement(NetworkPerformanceMetrics* metrics, double value) {
    Measurement* measurement = malloc(sizeof(Measurement));
    if (!measurement) return;

    measurement->value = value;
    measurement->next = metrics->measurements_head;
    metrics->measurements_head = measurement;
}

void list_push_back(List* list, NetworkPerformanceMetrics* node) {
    pthread_mutex_lock(&list->lock);
    if (list->tail) {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    } else {
        list->head = list->tail = node;
    }
    list->entry_count++;
    pthread_mutex_unlock(&list->lock);
}

void cleanup_metrics(List* list, time_t retention_time) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics *current = list->head, *temp;

    while (current != NULL) {
        if (difftime(time(NULL), current->timestamp) > retention_time) {
            temp = current;
            current = current->next;

            // Remove metrics
            Measurement* m_current = temp->measurements_head;
            while (m_current != NULL) {
                Measurement* to_delete = m_current;
                m_current = m_current->next;
                free(to_delete);
            }

            if (temp->prev)
                temp->prev->next = temp->next;
            else
                list->head = temp->next;

            if (temp->next)
                temp->next->prev = temp->prev;
            else
                list->tail = temp->prev;

            free(temp);
            list->entry_count--;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void get_list_stats(const List* list, size_t* total_entries, double* average_age) {
    time_t now = time(NULL);

    *total_entries = 0;
    long total_age = 0;

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);
    NetworkPerformanceMetrics* current = list->head;

    while (current != NULL) {
        (*total_entries)++;
        total_age += difftime(now, current->timestamp);

        current = current->next;
    }
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);

    *average_age = (*total_entries > 0) ? (double)total_age / (double)*total_entries : 0.0;
}

void list_destroy(List* list) {
    NetworkPerformanceMetrics* current = list->head;

    while (current != NULL) {
        Measurement* m_current = current->measurements_head;
        while (m_current != NULL) {
            Measurement* to_delete = m_current;
            m_current = m_current->next;
            free(to_delete);
        }

        NetworkPerformanceMetrics* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    List* list = list_init();

    // Example usage
    time_t now = time(NULL);
    add_measurement(create_metrics_node(now, "session1"), 100.0);
    list_push_back(list, create_metrics_node(now, "session2"));

    size_t total_entries;
    double average_age;

    get_list_stats(list, &total_entries, &average_age);

    printf("Total Entries: %zu\n", total_entries);
    printf("Average Age: %.2f seconds\n", average_age);

    cleanup_metrics(list, 3600); // Retain metrics for the last hour

    list_destroy(list);
    return 0;
}
```

This code snippet sets up a doubly-linked list of `NetworkPerformanceMetrics` structures with thread safety using a mutex. It includes functions to initialize and destroy the list, add new performance metric nodes, manage measurements within each node, calculate statistics, and perform cleanup based on retention time. The cleanup mechanism iterates through the list once per function call, removing outdated entries while maintaining concurrency safety.']

