#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_INPUT 1000
#define RANGE_MIN 1
#define RANGE_MAX 100

typedef struct CRC_INDICATION_REL8_TAG {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRCFLAG;
} CRC_INDICATION_REL8_TAG_T;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    CRC_INDICATION_REL8_TAG_T crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    int value;
    struct Node *prev, *next;
} Node;

typedef struct DoublyLinkedList {
    Node *head, *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList *list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DoublyLinkedList *list) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_unique(DoublyLinkedList *list, int value) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = list->tail = (Node*)malloc(sizeof(Node));
        list->head->value = value;
        list->head->prev = list->head->next = NULL;
    } else {
        Node *current = list->head;
        while (current) {
            if (current->value == value) {
                pthread_mutex_unlock(&list->lock);
                return 0; // Duplicate found
            }
            current = current->next;
        }

        Node *new_node = (Node*)malloc(sizeof(Node));
        new_node->value = value;
        new_node->prev = list->tail;
        new_node->next = NULL;

        if (list->tail) {
            list->tail->next = new_node;
        }
        list->tail = new_node;

        if (!list->head) {
            list->head = new_node;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return 1; // Successfully inserted
}

int find_largest(DoublyLinkedList *list, int *largest) {
    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is empty
    }

    Node *current = list->head;
    *largest = current->value;

    while (current) {
        if (current->value > *largest) {
            *largest = current->value;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void read_and_process_input(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T *array, size_t array_size) {
    int values[MAX_INPUT], count = 0;
    printf("Enter integers (end with -1):\n");

    while (count < MAX_INPUT && scanf("%d", &values[count]) == 1 && values[count] != -1) {
        if (values[count] >= RANGE_MIN && values[count] <= RANGE_MAX) {
            count++;
        } else {
            printf("Invalid range, try again.\n");
            count--;
        }
    }

    for (int i = 0; i < count; i++) {
        insert_unique(list, values[i]);
    }

    int largest;
    if (find_largest(list, &largest) == 0) {
        printf("Largest integer: %d\n", largest);
    } else {
        printf("List is empty.\n");
    }

    srand(time(NULL));
    for (size_t i = 0; i < array_size && i < count; i++) {
        array[i].crc_indication_rel8_tag.RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].crc_indication_rel8_tag.RNTI = rand() % 1000;
        array[i].crc_indication_rel8_tag.CRCFLAG = rand() & 1;
    }
}

int main() {
    DoublyLinkedList *list = create_list();
    if (!list) {
        fprintf(stderr, "Memory allocation failed for list.\n");
        return EXIT_FAILURE;
    }

    size_t array_size = 10; // Example size
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed for array.\n");
        destroy_list(list);
        return EXIT_FAILURE;
    }

    read_and_process_input(list, array, array_size);

    free(array);
    destroy_list(list);
    return EXIT_SUCCESS;
}
```

### Key Points:
- **Thread Safety**: Uses `pthread_mutex_t` to ensure thread-safe operations on the linked list.
- **Unique Insertion**: Ensures no duplicates are inserted into the list.
- **Largest Value**: Finds and prints the largest integer in the list.
- **Memory Management**: Handles dynamic memory allocation and deallocation efficiently.
- **Error Handling**: Logs errors for memory allocation failures.

This code is designed to be modular, allowing developers to expand or modify components as needed.']

