void add_context(DynamicArrayManager* manager, MAC_CONTEXT_T* context) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count < MAX_CONTEXTS) {
        manager->contexts[manager->count++] = context;
    } else {
        // Handle overflow or log error
        fprintf(stderr, "Maximum contexts reached\n");
    }
    pthread_mutex_unlock(&manager->lock);
}

void remove_context(DynamicArrayManager* manager, size_t index) {
    pthread_mutex_lock(&manager->lock);
    if (index < manager->count) {
        free(manager->contexts[index]->mac_addresses);
        free(manager->contexts[index]);
        for (size_t i = index; i < manager->count - 1; ++i) {
            manager->contexts[i] = manager->contexts[i + 1];
        }
        manager->contexts[--manager->count] = NULL;
    } else {
        // Handle invalid index or log error
        fprintf(stderr, "Invalid context index\n");
    }
    pthread_mutex_unlock(&manager->lock);
}

void initialize_manager(DynamicArrayManager* manager) {
    memset(manager->contexts, 0, sizeof(manager->contexts));
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void cleanup_manager(DynamicArrayManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->contexts[i]->mac_addresses);
        free(manager->contexts[i]);
    }
