    // Additional FSA structure members...
} FSA_STATE;

pthread_mutex_t rand_mutex = PTHREAD_MUTEX_INITIALIZER;

int thread_safe_rand(int max) {
    pthread_mutex_lock(&rand_mutex);
    int result = rand() % (max + 1);
    pthread_mutex_unlock(&rand_mutex);
    return result;
}

NFAPI_CRC_INDICATION_PDU_T* construct_nfa_crc_list(
    const int* states, 
    int num_states, 
    const FSA_STATE* fsa, 
    int instances_per_state,
    int debug_mode) {

    if (debug_mode) {
        printf("Starting construction of NFA CRC list\n");
    }

    size_t total_instances = num_states * instances_per_state;
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(total_instances * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_list) {
        perror("Failed to allocate memory for CRC indication list");
        return NULL;
    }

    for (int i = 0; i < num_states; ++i) {
        int state_index = states[i];

        if (debug_mode && state_index >= num_states) {
            fprintf(stderr, "Invalid state index: %d\n", state_index);
            free(pdu_list);
            return NULL;
        }

        for (int j = 0; j < instances_per_state; ++j) {
            size_t pdu_index = i * instances_per_state + j;

            if (debug_mode) {
                printf("Processing state ID: %d, instance: %d\n", fsa[state_index].state_id, j);
            }

            int crc_flag = thread_safe_rand(1); // Randomly set CRCFLAG to 0 or 1
            pdu_list[pdu_index].crc_indication_rel8_tag.CRCFLAG = crc_flag;
        }
    }

    if (debug_mode) {
        printf("Successfully constructed NFA CRC list\n");
    }

    return pdu_list;
}

void free_nfa_crc_list(NFAPI_CRC_INDICATION_PDU_T* pdu_list, int num_states, int instances_per_state) {
    size_t total_instances = num_states * instances_per_state;
    free(pdu_list);
}
```

