['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
import time.h
#include <pthread.h>

typedef struct {
    unsigned char mac_header[8];
    unsigned char *mac_payload;
    size_t payload_len;
    time_t timestamp;
} MAC_PDU_T;

typedef struct {
    MAC_PDU_T *pdus;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PDU_Array;

PDU_Array* pdu_array_create(size_t initial_capacity) {
    PDU_Array *array = (PDU_Array *)malloc(sizeof(PDU_Array));
    array->pdus = (MAC_PDU_T *)malloc(initial_capacity * sizeof(MAC_PDU_T));
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void pdu_array_destroy(PDU_Array *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->pdus[i].mac_payload);
    }
    free(array->pdus);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int pdu_array_add(PDU_Array *array, const unsigned char *header, const unsigned char *payload, size_t payload_len) {
    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        array->capacity *= 2;
        MAC_PDU_T *new_pdus = (MAC_PDU_T *)realloc(array->pdus, array->capacity * sizeof(MAC_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Failed to allocate memory
        }
        array->pdus = new_pdus;
    }

    MAC_PDU_T *pdu = &array->pdus[array->count++];
    memcpy(pdu->mac_header, header, sizeof(pdu->mac_header));
    pdu->mac_payload = (unsigned char *)malloc(payload_len);
    if (!pdu->mac_payload) {
        array->count--;
        pthread_mutex_unlock(&array->lock);
        return -1; // Failed to allocate memory
    }
    memcpy(pdu->mac_payload, payload, payload_len);
    pdu->payload_len = payload_len;
    pdu->timestamp = time(NULL);

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}

MAC_PDU_T* pdu_array_get(PDU_Array *array, size_t index) {
    if (index >= array->count) return NULL;

    pthread_mutex_lock(&array->lock);
    MAC_PDU_T *pdu = &array->pdus[index];
    pthread_mutex_unlock(&array->lock);

    // Create a copy to ensure thread safety
    MAC_PDU_T *copy = (MAC_PDU_T *)malloc(sizeof(MAC_PDU_T));
    memcpy(copy->mac_header, pdu->mac_header, sizeof(pdu->mac_header));
    copy->mac_payload = (unsigned char *)malloc(pdu->payload_len);
    if (!copy->mac_payload) {
        free(copy);
        return NULL;
    }
    memcpy(copy->mac_payload, pdu->mac_payload, pdu->payload_len);
    copy->payload_len = pdu->payload_len;
    copy->timestamp = pdu->timestamp;

    return copy;
}

int pdu_array_remove(PDU_Array *array, size_t index) {
    if (index >= array->count) return -1;

    pthread_mutex_lock(&array->lock);

    free(array->pdus[index].mac_payload);

    for (size_t i = index; i < array->count - 1; ++i) {
        array->pdus[i] = array->pdus[i + 1];
    }
    array->count--;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int pdu_array_serialize(PDU_Array *array, const char *filename) {
    pthread_mutex_lock(&array->lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    fwrite(&array->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < array->count; ++i) {
        fwrite(array->pdus[i].mac_header, sizeof(unsigned char), 8, file);
        fwrite(&array->pdus[i].payload_len, sizeof(size_t), 1, file);
        fwrite(array->pdus[i].mac_payload, sizeof(unsigned char), array->pdus[i].payload_len, file);
        fwrite(&array->pdus[i].timestamp, sizeof(time_t), 1, file);
    }

    fclose(file);

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int pdu_array_deserialize(PDU_Array *array, const char *filename) {
    pthread_mutex_lock(&array->lock);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    size_t new_count;
    fread(&new_count, sizeof(size_t), 1, file);

    MAC_PDU_T *new_pdus = (MAC_PDU_T *)realloc(array->pdus, new_count * sizeof(MAC_PDU_T));
    if (!new_pdus) {
        fclose(file);
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    array->pdus = new_pdus;
    array->capacity = new_count;
    array->count = new_count;

    for (size_t i = 0; i < array->count; ++i) {
        fread(array->pdus[i].mac_header, sizeof(unsigned char), 8, file);
        fread(&array->pdus[i].payload_len, sizeof(size_t), 1, file);
        array->pdus[i].mac_payload = (unsigned char *)malloc(array->pdus[i].payload_len);
        if (!array->pdus[i].mac_payload) {
            fclose(file);
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        fread(array->pdus[i].mac_payload, sizeof(unsigned char), array->pdus[i].payload_len, file);
        fread(&array->pdus[i].timestamp, sizeof(time_t), 1, file);
    }

    fclose(file);

    pthread_mutex_unlock(&array->lock);
    return 0;
}
