#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int TX_RNTI;
    int MEASUREMENT_TYPE;
    float PHY_CHANNEL_QUALITY_INDICATOR;
} NR_PHY_MEASUREMENT_T;

typedef struct Node {
    NR_PHY_MEASUREMENT_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
} DoublyLinkedList;

DoublyLinkedList* createList() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    return list;
}

int compareTX_RNTI(const void* a, const void* b) {
    NR_PHY_MEASUREMENT_T* m1 = (NR_PHY_MEASUREMENT_T*)a;
    NR_PHY_MEASUREMENT_T* m2 = (NR_PHY_MEASUREMENT_T*)b;
    return m1->TX_RNTI - m2->TX_RNTI;
}

int isValidChannelQuality(float quality) {
    const float MIN_QUALITY = 0.5;
    const float MAX_QUALITY = 5.0;
    return quality >= MIN_QUALITY && quality <= MAX_QUALITY;
}

Node* createNode(int txRNTI, int measurementType, float channelQualityIndicator) {
    if (!isValidChannelQuality(channelQualityIndicator)) {
        return NULL;
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->data.TX_RNTI = txRNTI;
    newNode->data.MEASUREMENT_TYPE = measurementType;
    newNode->data.PHY_CHANNEL_QUALITY_INDICATOR = channelQualityIndicator;
    newNode->prev = newNode->next = NULL;
    return newNode;
}

int insertOrdered(DoublyLinkedList* list, Node* newNode) {
    if (!list || !newNode) return -1;

    Node** current = &(list->head);

    while (*current && ((*current)->data.TX_RNTI < newNode->data.TX_RNTI)) {
        current = &((*current)->next);
    }

    newNode->next = *current;
    if (*current) {
        (*current)->prev = newNode;
    } else {
        list->tail = newNode; // If new node is the last one
    }

    newNode->prev = (*current == list->head) ? NULL : (*current)->prev;

    if (newNode->prev) {
        newNode->prev->next = newNode;
    } else {
        list->head = newNode; // If new node is the first one
    }

    return 0;
}

void freeList(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

void iterateForward(DoublyLinkedList* list, void (*callback)(NR_PHY_MEASUREMENT_T*)) {
    if (!list || !list->head || !callback) return;

    for (Node* node = list->head; node != NULL; node = node->next) {
        callback(&(node->data));
    }
}

void iterateReverse(DoublyLinkedList* list, void (*callback)(NR_PHY_MEASUREMENT_T*)) {
    if (!list || !list->tail || !callback) return;

    for (Node* node = list->tail; node != NULL; node = node->prev) {
        callback(&(node->data));
    }
}

void filterByMeasurementType(DoublyLinkedList* list, int measurementType, void (*callback)(NR_PHY_MEASUREMENT_T*)) {
    if (!list || !callback) return;

    for (Node* node = list->head; node != NULL; node = node->next) {
        if (node->data.MEASUREMENT_TYPE == measurementType) {
            callback(&(node->data));
        }
    }
}

// Example usage of the iteration callbacks
void printMeasurement(NR_PHY_MEASUREMENT_T* data) {
    printf("TX_RNTI: %d, Measurement Type: %d, Quality Indicator: %.2f\n",
           data->TX_RNTI,
           data->MEASUREMENT_TYPE,
           data->PHY_CHANNEL_QUALITY_INDICATOR);
}

int main() {
    DoublyLinkedList* list = createList();
    if (!list) return -1;

    Node* node1 = createNode(10, 1, 2.5);
    Node* node2 = createNode(20, 2, 3.0);
    Node* node3 = createNode(15, 1, 4.0);

    if (node1) insertOrdered(list, node1);
    if (node2) insertOrdered(list, node2);
    if (node3) insertOrdered(list, node3);

    printf("Forward iteration:\n");
    iterateForward(list, printMeasurement);

    printf("\nReverse iteration:\n");
    iterateReverse(list, printMeasurement);

    printf("\nFilter by Measurement Type 1:\n");
    filterByMeasurementType(list, 1, printMeasurement);

    freeList(list);
    return 0;
}
