    unsigned short rnti = (rand() % (RNTI_MAX - RNTI_MIN + 1)) + RNTI_MIN;

    if (!is_valid_rx_ue_tag(rx_ue_tag) || !is_valid_rnti(rnti)) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
