    new_node->RX_UE_INFORMATION_TAG = rx_ue_tag;
    new_node->RNTI = rnti;
    new_node->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = list->head;
    list->head = new_node;

    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

// Example usage
int main() {
    LinkedList list;
    init_list(&list);

    // Simulate concurrent access with threads
    const int num_threads = 10;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, (void*)add_to_list, &list);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_list(&list);

    return 0;
}
