    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

void init_list(LinkedList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int validate_crc_flag(uint8_t crcFlag) {
    // Placeholder for CRC flag validation logic
    return (crcFlag & 0x01); // Example: Must be odd
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    if (!validate_crc_flag(data.CRCFLAG)) {
        fprintf(stderr, "Invalid CRC FLAG\n");
        return NULL;
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = NULL;
    return newNode;
}

void insert_sorted(LinkedList* list, Node* newNode) {
    pthread_mutex_lock(&list->lock);

    if (!list->head || list->head->data.RNTI > newNode->data.RNTI) {
        newNode->next = list->head;
        if (list->head) list->head->prev = newNode;
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next && current->next->data.RNTI < newNode->data.RNTI) {
            current = current->next;
        }
        if (current->next && current->next->data.RNTI == newNode->data.RNTI) {
            pthread_mutex_unlock(&list->lock);
            free(newNode);
            return; // RNTI must be unique
        }
        newNode->next = current->next;
        if (current->next) current->next->prev = newNode;
        current->next = newNode;
        newNode->prev = current;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

LinkedList* merge_lists(LinkedList* list1, LinkedList* list2) {
    LinkedList* mergedList = (LinkedList*)malloc(sizeof(LinkedList));
    if (!mergedList) {
        perror("Failed to allocate memory for merged list");
        exit(EXIT_FAILURE);
    }
    init_list(mergedList);

    Node dummy;
    dummy.next = NULL;
    dummy.prev = &dummy;
    Node* tail = &dummy;

    Node* current1 = list1->head;
    Node* current2 = list2->head;

    while (current1 || current2) {
        if (!current1) {
            Node* nodeCopy = create_node(current2->data);
            insert_sorted(mergedList, nodeCopy);
            current2 = current2->next;
        } else if (!current2) {
            Node* nodeCopy = create_node(current1->data);
            insert_sorted(mergedList, nodeCopy);
            current1 = current1->next;
        } else if (current1->data.RNTI < current2->data.RNTI) {
            Node* nodeCopy = create_node(current1->data);
            insert_sorted(mergedList, nodeCopy);
            current1 = current1->next;
        } else if (current1->data.RNTI > current2->data.RNTI) {
            Node* nodeCopy = create_node(current2->data);
            insert_sorted(mergedList, nodeCopy);
            current2 = current2->next;
        } else {
            // Both have the same RNTI; choose one
            Node* nodeCopy = create_node(current1->data);
            insert_sorted(mergedList, nodeCopy);
            current1 = current1->next;
            current2 = current2->next;
        }
    }

    pthread_mutex_unlock(&list1->lock);
    pthread_mutex_unlock(&list2->lock);

    return mergedList;
}

LinkedList* filter_list(const LinkedList* list, uint8_t bitmask) {
    LinkedList* filteredList = (LinkedList*)malloc(sizeof(LinkedList));
    if (!filteredList) {
        perror("Failed to allocate memory for filtered list");
        exit(EXIT_FAILURE);
    }
    init_list(filteredList);

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if ((current->data.CRCFLAG & bitmask) == bitmask) {
            Node* nodeCopy = create_node(current->data);
            insert_sorted(filteredList, nodeCopy);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    return filteredList;
}

void iterate_forward(const LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        printf("RNTI: %d, CRCFLAG: %u\n", current->data.RNTI, current->data.CRCFLAG);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_reverse(const LinkedList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    if (!current) return;

    while (current->next) {
        current = current->next;
    }

    while (current) {
        printf("RNTI: %d, CRCFLAG: %u\n", current->data.RNTI, current->data.CRCFLAG);
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    LinkedList list1, list2;

    init_list(&list1);
    init_list(&list2);

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T data1 = {1, 100, 0x01, 0b00000001};
    NFAPI_CRC_INDICATION_PDU_T data2 = {2, 200, 0x02, 0b00000010};

    Node* node1 = create_node(data1);
    Node* node2 = create_node(data2);

    insert_sorted(&list1, node1);
    insert_sorted(&list2, node2);

    iterate_forward(&list1);
    iterate_reverse(&list1);

    LinkedList* mergedList = merge_lists(&list1, &list2);
    iterate_forward(mergedList);

    LinkedList* filteredList = filter_list(mergedList, 0b00000001);
    iterate_forward(filteredList);

    free_list(&list1);
    free_list(&list2);
    free_list((LinkedList*)mergedList);
    free_list(filteredList);

    return 0;
}
