#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TASKS 10000

typedef struct {
    int job_id;
    int priority_level;
    int estimated_completion_time;
    int status; // 0 = not started, 1 = started
} Task;

typedef struct {
    Task *tasks[MAX_TASKS];
    size_t count;
} TaskList;

Task* create_task(int job_id, int priority_level, int estimated_completion_time) {
    Task *task = (Task*)malloc(sizeof(Task));
    if (!task) return NULL;

    task->job_id = job_id;
    task->priority_level = priority_level;
    task->estimated_completion_time = estimated_completion_time;
    task->status = 0; // Not started by default

    return task;
}

void free_task(Task *task) {
    if (task) free(task);
}

int find_task_index(TaskList *list, int job_id) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->tasks[i]->job_id == job_id) return i;
    }
    return -1;
}

void add_task(TaskList *list, Task *task) {
    if (list->count >= MAX_TASKS) {
        fprintf(stderr, "Task limit reached.\n");
        free_task(task);
        return;
    }

    list->tasks[list->count++] = task;

    // Sort tasks after addition
    qsort(list->tasks, list->count, sizeof(Task*), compare_tasks);
}

void update_task(TaskList *list, int job_id, int priority_level, int estimated_completion_time) {
    int index = find_task_index(list, job_id);
    if (index == -1) return;

    Task *task = list->tasks[index];
    task->priority_level = priority_level;
    task->estimated_completion_time = estimated_completion_time;

    // Resort after update
    qsort(list->tasks, list->count, sizeof(Task*), compare_tasks);
}

void mark_task_as_started(TaskList *list, int job_id) {
    int index = find_task_index(list, job_id);
    if (index == -1) return;

    list->tasks[index]->status = 1;
}

int compare_tasks(const void *a, const void *b) {
    Task *taskA = *(Task**)a;
    Task *taskB = *(Task**)b;

    return taskA->priority_level - taskB->priority_level;
}

void free_task_list(TaskList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free_task(list->tasks[i]);
    }
    memset(list, 0, sizeof(TaskList));
}

// Example usage
int main() {
    TaskList taskList = { .count = 0 };

    Task *task1 = create_task(101, 5, 120);
    add_task(&taskList, task1);

    Task *task2 = create_task(102, 3, 90);
    add_task(&taskList, task2);

    update_task(&taskList, 101, 2, 100); // Update task 101
    mark_task_as_started(&taskList, 102); // Mark task 102 as started

    // Free resources
    free_task_list(&taskList);

    return 0;
