    }
    array->messages = newMessages;
    array->messageCount = newSize;
    pthread_mutex_unlock(&array->mutex);
}

// Function to initialize the doubly-linked list of metrics
void initMetricList(MetricList *list) {
    pthread_rwlock_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
}

// Function to add a metric to the list
void addMetric(MetricList *list, NetworkPerformanceMetric *metric) {
    pthread_rwlock_wrlock(&list->lock);

    if (!list->head) {
        list->head = metric;
        list->tail = metric;
        metric->prev = NULL;
        metric->next = NULL;
    } else {
        metric->prev = list->tail;
        metric->next = NULL;
        list->tail->next = metric;
        list->tail = metric;
    }

    pthread_rwlock_unlock(&list->lock);
}

// Function to find a metric by session ID
NetworkPerformanceMetric* findMetric(MetricList *list, const char *sessionId) {
    pthread_rwlock_rdlock(&list->lock);

    NetworkPerformanceMetric *current = list->head;
    while (current) {
        if (strcmp(current->sessionId, sessionId) == 0) {
            pthread_rwlock_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }

    pthread_rwlock_unlock(&list->lock);
    return NULL;
}

// Function to remove a metric by session ID
void removeMetric(MetricList *list, const char *sessionId) {
    pthread_rwlock_wrlock(&list->lock);

    NetworkPerformanceMetric **current = &list->head;
    while (*current) {
        if (strcmp((*current)->sessionId, sessionId) == 0) {
            NetworkPerformanceMetric *toRemove = *current;
            *current = toRemove->next;

            if (toRemove == list->tail) {
                list->tail = toRemove->prev;
            }
            if (toRemove->prev) {
                toRemove->prev->next = toRemove->next;
            }

            free(toRemove->results);
            free(toRemove);

            pthread_rwlock_unlock(&list->lock);
            return;
        }
        current = &(*current)->next;
    }

    pthread_rwlock_unlock(&list->lock);
}

// Function to periodically clean up outdated metrics
void cleanupMetrics(MetricList *list, time_t currentTime) {
    pthread_rwlock_wrlock(&list->lock);

    NetworkPerformanceMetric **current = &list->head;
    while (*current) {
        if (currentTime - (*current)->timestamp > 3600) { // Example: 1-hour retention policy
