#include <string.h>

typedef struct record {
    int value;
    long *offset_ptr;
    struct record *next;
} record;

// Hash function for integers
unsigned int hash_int(int key, unsigned int table_size) {
    return (key & 0x7FFFFFFF) % table_size; 
}

// Hash function for longs
unsigned int hash_long(long key, unsigned int table_size) {
    return ((unsigned long)key & 0x7FFFFFFFFFFFFFFFULL) % table_size;
}

// Function to check if a value is unique in a hash table
int is_unique_int(int *keys, int size, int value) {
    for (int i = 0; i < size; ++i) {
        if (keys[i] == value) return 0;
    }
    return 1;
}

// Function to check if a long offset is unique in a hash table
int is_unique_long(long *offsets, int size, long value) {
    for (int i = 0; i < size; ++i) {
        if (offsets[i] == value) return 0;
    }
    return 1;
}

// Function to parse configuration file and get num_offsets and num_keys
int parse_config(const char *filename, int *num_offsets, int *num_keys) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Unable to open the file");
        return -1;
    }

    if (fscanf(file, "%d %d", num_offsets, num_keys) != 2) {
        fprintf(stderr, "Invalid format in configuration file\n");
        fclose(file);
        return -1;
    }

    fclose(file);

    // Validate numbers
    if (*num_offsets <= 0 || *num_keys <= 0) {
        fprintf(stderr, "Number of offsets and keys must be positive\n");
        return -1;
    }

    return 0;
}

// Function to initialize an array with unique values
void init_unique_array(long *array, int size, long min_val, long max_val) {
    unsigned int table_size = (max_val - min_val + 1);
    int *hash_table = calloc(table_size, sizeof(int));

    for (int i = 0; i < size; ++i) {
        do {
            array[i] = rand() % (max_val - min_val + 1) + min_val;
        } while (!is_unique_long(array, i, array[i]));

        hash_table[array[i] - min_val] = 1;
    }

    free(hash_table);
}

// Function to initialize an array with unique keys
void init_unique_keys(int *keys, int size) {
    unsigned int table_size = size * 2; // A simple heuristic for load factor
    int *hash_table = calloc(table_size, sizeof(int));

    for (int i = 0; i < size; ++i) {
        do {
            keys[i] = rand() % table_size;
        } while (!is_unique_int(keys, i, keys[i]));

        hash_table[keys[i]] = 1;
    }

    free(hash_table);
}

// Function to initialize record linked list
record* init_records(int *keys, long *offsets, int size) {
    record *head = NULL, **current_ptr = &head;

    for (int i = 0; i < size; ++i) {
        record *new_record = malloc(sizeof(record));
        if (!new_record) {
            perror("Failed to allocate memory for new record");
            exit(EXIT_FAILURE);
        }

        new_record->value = keys[i];
        new_record->offset_ptr = &offsets[i];
        new_record->next = NULL;

        *current_ptr = new_record;
        current_ptr = &new_record->next;
    }

    return head;
}

// Function to traverse and print the linked list
void traverse_print_list(record *head) {
    record *current = head;
    while (current != NULL) {
        printf("Record Value: %d, Offset: %ld\n", current->value, *(current->offset_ptr));
        current = current->next;
    }
}

// Function to deallocate memory
void cleanup(long *offsets, int num_offsets, record *head) {
    free(offsets);

    while (head != NULL) {
        record *temp = head;
        head = head->next;
        free(temp);
    }
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int num_offsets, num_keys;
    if (parse_config(argv[1], &num_offsets, &num_keys)) {
        return EXIT_FAILURE;
    }

    long min_offset = 0, max_offset = 1000000; // Example range
    long *offsets = malloc(num_offsets * sizeof(long));
    int *keys = malloc(num_keys * sizeof(int));

    if (!offsets || !keys) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    init_unique_array(offsets, num_offsets, min_offset, max_offset);
    init_unique_keys(keys, num_keys);

    record *head = init_records(keys, offsets, num_keys);

    traverse_print_list(head);

    cleanup(offsets, num_offsets, head);

    return EXIT_SUCCESS;
}
