    Node* head;
    size_t size;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int add_element(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (pthread_mutex_lock(&list->lock)) return -1;

    if (list->size >= MAX_LIST_SIZE) {
        fprintf(stderr, "Error: List size exceeded.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->data = element;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    if (pthread_mutex_unlock(&list->lock)) return -1;
    return 0;
}

int validate_list(LinkedList* list) {
    int valid = 1;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        // Define your validation logic here
        if (current->data.RX_UE_INFORMATION_TAG < 0 || 
            current->data.RNTI <= 0 ||
            current->data.CRC_INDICATION_REL8_TAG < 0) {
            valid = 0;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);

    return valid;
}

void free_list(LinkedList* list) {
    if (pthread_mutex_lock(&list->lock)) return;

    Node* current = list->head;
    while (current) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }

    list->head = NULL;
    list->size = 0;

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

