    task1.Data_Structure.Array_of_Longs = (long*)malloc(sizeof(long) * 10); // Example allocation

    Task task2 = {2, 3};
    char **map_array = (char**)malloc(2 * sizeof(char*));
    map_array[0] = strdup("key");
    map_array[1] = strdup("value");
    map_array[2] = NULL;
    task2.Data_Structure.Map_of_Strings = map_array;

    enqueue_task(queue, task1);
    enqueue_task(queue, task2);

    // Create and populate NFAPI_CRC_INDICATION_PDU_T structures
    size_t num_crcs = 5;
    NFAPI_CRC_INDICATION_PDU_T *crcs = create_crc_indications(num_crcs);
    if (crcs) {
