    if (!manager) return NULL;
    manager->count = 0;
    for (int i = 0; i < MAX_PACKETS; ++i) {
        manager->packets[i].head = NULL;
        manager->packets[i].size = 0;
    }
    return manager;
}

void add_packet(NetworkPacketManager *manager, NetworkPacket packet) {
    if (manager->count >= MAX_PACKETS) return;

    int index = hash_ip(packet.sourceIP) % MAX_PACKETS;
    PacketNode *new_node = (PacketNode *)malloc(sizeof(PacketNode));
    new_node->packet = packet;
    new_node->next = manager->packets[index].head;
    manager->packets[index].head = new_node;
    manager->packets[index].size++;
    manager->count++;
}

NetworkPacket* retrieve_by_ip(NetworkPacketManager *manager, const char *ip) {
    int index = hash_ip(ip) % MAX_PACKETS;
    PacketNode *current = manager->packets[index].head;

    while (current) {
        if (strcmp(current->packet.sourceIP, ip) == 0 || 
            strcmp(current->packet.destinationIP, ip) == 0) {
            return &current->packet;
        }
        current = current->next;
    }
    return NULL;
}

void remove_by_timestamp(NetworkPacketManager *manager, time_t timestamp) {
    for (int i = 0; i < MAX_PACKETS; ++i) {
        PacketNode *current = manager->packets[i].head;
