        fprintf(stderr, "Failed to create packet manager\n");
        return 1;
    }

    // Example usage
    NetworkPacket packet = {time(NULL), "192.168.0.1", "192.168.0.2"};
    add_packet(manager, packet);

    NetworkPacket *found = retrieve_by_ip(manager, "192.168.0.1");
    if (found) {
        printf("Packet found: %s -> %s\n", found->sourceIP, found->destinationIP);
    }

    remove_by_timestamp(manager, packet.timestamp);

    // Cleanup
    for (int i = 0; i < MAX_PACKETS; ++i) {
        PacketNode *current = manager->packets[i].head;
        while (current) {
            PacketNode *temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(manager);

    return 0;
}
```

