['Here is a C implementation that addresses your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Entry {
    long timestamp;
    int status_code;
    char *message;
    double performance_metric;
} Entry;

typedef struct Node {
    Entry entry;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} EntryList;

EntryList* create_entry_list() {
    EntryList *list = (EntryList *)malloc(sizeof(EntryList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node(Node *node) {
    if (node) {
        free(node->entry.message);
        free(node);
    }
}

void remove_entry_list(EntryList *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free_node(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_entry(EntryList *list, Entry new_entry) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->entry.timestamp < new_entry.timestamp) {
        if (current->entry.timestamp == new_entry.timestamp) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate timestamp
        }
        current = current->next;
    }

    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failure
    }

    new_node->entry = new_entry;
    new_node->next = current ? current : NULL;

    if (current == list->head || !current) {
        list->head = new_node;
    } else {
        Node *prev = list->head;
        while (prev->next != current) {
            prev = prev->next;
        }
        prev->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int remove_entry_by_timestamp(EntryList *list, long timestamp) {
    pthread_mutex_lock(&list->lock);

    Node **indirect = &list->head;
    while (*indirect != NULL && (*indirect)->entry.timestamp != timestamp) {
        indirect = &(*indirect)->next;
    }

    if (*indirect == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Entry not found
    }

    Node *to_remove = *indirect;
    *indirect = to_remove->next;
    free_node(to_remove);

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int update_entry_by_timestamp(EntryList *list, long timestamp, Entry updated_entry) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->entry.timestamp != timestamp) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Entry not found
    }

    current->entry = updated_entry;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

Entry get_most_recent_entry(EntryList *list) {
    pthread_mutex_lock(&list->lock);

    Entry most_recent = {0, 0, NULL, 0.0};
    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return most_recent; // Empty list
    }

    Node *current = list->head;
    while (current != NULL) {
        most_recent = current->entry;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return most_recent;
}

void list_entries_older_than(EntryList *list, long time_threshold, void (*callback)(Entry)) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        if (current->entry.timestamp < time_threshold) {
            callback(current->entry);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

int serialize_to_file(EntryList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL) {
        fwrite(&(current->entry.timestamp), sizeof(long), 1, file);
        int message_length = strlen(current->entry.message) + 1;
        fwrite(&message_length, sizeof(int), 1, file);
        fwrite(current->entry.message, sizeof(char), message_length, file);
        fwrite(&(current->entry.status_code), sizeof(int), 1, file);
        fwrite(&(current->entry.performance_metric), sizeof(double), 1, file);

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    fclose(file);
    return 0; // Success
}

void log_change(const char *action, long timestamp) {
    printf("Log: %s at %ld\n", action, timestamp); // Simple logging
}
```

This code implements a thread-safe dynamic list of `Entry` structures with functions to add, remove, update, and retrieve entries. It uses mutexes for synchronization, ensuring safe concurrent access. The serialization function writes entries to a file in a simple binary format, supporting versioning by including all necessary data fields. Logging is done via a lightweight function that prints changes to the console.']

