    strncpy(new_data.rx_ue_information_tag, rx_ue_information_tag, sizeof(new_data.rx_ue_information_tag));

    pthread_mutex_lock(&list_lock);
    add_or_update_entry(session_id, new_data);
    pthread_mutex_unlock(&list_lock);

    json_object_put(parsed_json);
    return MHD_YES;
}

static int handle_delete_request(void *cls, struct MHD_Connection *connection,
                                 const char *url, const char *method,
                                 const char *version, const void *upload_data,
                                 size_t *upload_data_size, void **con_cls) {
    if (strcmp(method, "DELETE") != 0) return MHD_NO;

    int session_id = atoi(url + strlen("/delete/"));
    int replace_with_default = 1; // or parse from request

    pthread_mutex_lock(&list_lock);
    delete_entry_by_session_id(session_id, replace_with_default);
    pthread_mutex_unlock(&list_lock);

    return MHD_YES;
}

static int handle_get_request(void *cls, struct MHD_Connection *connection,
                              const char *url, const char *method,
                              const char *version, const void *upload_data,
                              size_t *upload_data_size, void **con_cls) {
    if (strcmp(method, "GET") != 0) return MHD_NO;

    const char* csv_filename = "metrics.csv";
    const char* delimiter = ",";

    pthread_mutex_lock(&list_lock);
    export_to_csv(csv_filename, delimiter);
    pthread_mutex_unlock(&list_lock);

    FILE *file = fopen(csv_filename, "r");
    struct MHD_Response *response;
    struct stat st;

    if (file == NULL) {
        response = MHD_create_response_from_buffer(0, NULL, MHD_RESPMEM_PERSISTENT);
    } else {
        fstat(fileno(file), &st);
        void *data = malloc(st.st_size + 1);
        fread(data, st.st_size, 1, file);
        fclose(file);
        data[st.st_size] = '\0';
        response = MHD_create_response_from_buffer(st.st_size, (void *)data, MHD_RESPMEM_MUST_FREE);
    }

    int ret = MHD_queue_response(connection, MHD_HTTP_OK, response);
    MHD_destroy_response(response);

    return ret;
}

int main(int argc, char **argv) {
    struct MHD_Daemon *daemon;

    daemon = MHD_start_daemon(MHD_USE_INTERNAL_POLLING_THREAD,
                              8080, NULL, NULL,
                              &handle_put_request, NULL, MHD_OPTION_END);
    if (NULL == daemon) return 1;

    // Run the server indefinitely
    getchar();

    MHD_stop_daemon(daemon);
    return 0;
}

void add_or_update_entry(int session_id, NFAPI_CRC_INDICATION_PDU_T new_data) {
    Node *current = head;
    while (current != NULL) {
        if (current->data.session_id == session_id) {
            current->data = new_data;
            return;
        }
        current = current->next;
    }

    Node *new_node = malloc(sizeof(Node));
    new_node->data = new_data;
    new_node->prev = tail;
    new_node->next = NULL;

    if (tail != NULL) {
        tail->next = new_node;
    } else {
        head = new_node;
    }
    tail = new_node;

    while (count_entries() > max_entries) {
        Node *temp = head;
        head = head->next;
        free(temp);
        if (head != NULL) {
            head->prev = NULL;
        }
    }
}

void delete_entry_by_session_id(int session_id, int replace_with_default) {
    Node *current = head;
    while (current != NULL) {
        if (current->data.session_id == session_id) {
            if (current->prev) current->prev->next = current->next;
            if (current->next) current->next->prev = current->prev;

            if (current == head) head = current->next;
            if (current == tail) tail = current->prev;

            free(current);
            break;
        }
        current = current->next;
    }

    // Optionally replace with a default entry
    if (replace_with_default) {
        NFAPI_CRC_INDICATION_PDU_T default_data = {0, "", "", 0};
        add_or_update_entry(session_id, default_data);
    }
}

int count_entries() {
    int count = 0;
    Node *current = head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    return count;
}

void export_to_csv(const char* filename, const char* delimiter) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    fprintf(file, "SessionID%sRNTI%sRX_UE_INFORMATION_TAG%sCRCFLAG\n", delimiter, delimiter, delimiter);
    Node *current = head;
    while (current != NULL) {
        fprintf(file, "%d%s%s%s%d\n",
                current->data.session_id,
                delimiter,
                current->data.rnti,
                delimiter,
                current->data.rx_ue_information_tag,
                delimiter,
                current->data.crcflag);
        current = current->next;
    }

    fclose(file);
}
