### Rust Implementation: Directory Creation and Environment Variable Setting

```rust
use std::env;
use std::fs;
use std::path::Path;

fn create_dir_and_set_env_var(dir_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    if let Ok(existing_path) = env::var("MY_CUSTOM_DIR") {
        println!("Using existing directory path from environment variable.");
        return Ok(());
    }

    let dir_path = Path::new(dir_name);
    match fs::create_dir_all(dir_path) {
        Ok(_) => {
            println!("Directory created successfully at {:?}", dir_path.display());
        }
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
            println!("Directory already exists.");
        }
