    }

    for (size_t i = 0; i < max_count && i < message_array.capacity; ++i) {
        if (!message_array.messages[i]) {
            LTE_DL_CCCH_Message_Type1_T *msg = malloc(sizeof(LTE_DL_CCCH_Message_Type1_T));
            if (!msg) {
                log_error("Memory allocation failed for message.");
