            if (!msg->nas_message.content) {
                free(msg);
                log_error("Memory allocation failed for NAS message content.");
                pthread_mutex_unlock(&message_array.lock);
                return i;
            }
            snprintf(msg->nas_message.content, content_size, "Content for type %d", type);

            message_array.messages[i] = msg;
            ++message_array.count;
        }
    }

    pthread_mutex_unlock(&message_array.lock);
    return message_array.count;
}

void serialize_messages(const char *filename) {
    pthread_mutex_lock(&message_array.lock);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for serialization.");
        pthread_mutex_unlock(&message_array.lock);
        return;
    }

    fwrite(&message_array.count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < message_array.count; ++i) {
        fwrite(&message_array.messages[i]->encoder.sequence_number, sizeof(int), 1, file);
        fwrite(&message_array.messages[i]->nas_message.message_type, sizeof(int), 1, file);
        size_t content_length = strlen(message_array.messages[i]->nas_message.content) + 1;
        fwrite(&content_length, sizeof(size_t), 1, file);
        fwrite(message_array.messages[i]->nas_message.content, sizeof(char), content_length, file);
    }

    fclose(file);
    pthread_mutex_unlock(&message_array.lock);
}

int deserialize_messages(const char *filename) {
    pthread_mutex_lock(&message_array.lock);

    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_error("Failed to open file for deserialization.");
        pthread_mutex_unlock(&message_array.lock);
        return 0;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    if (count > message_array.capacity) {
        LTE_DL_CCCH_Message_Type1_T **new_messages = realloc(message_array.messages, count * sizeof(LTE_DL_CCCH_Message_Type1_T *));
        if (!new_messages) {
            fclose(file);
            pthread_mutex_unlock(&message_array.lock);
            log_error("Memory allocation failed during deserialization.");
            return 0;
        }
        memset(new_messages + message_array.capacity, 0, (count - message_array.capacity) * sizeof(LTE_DL_CCCH_Message_Type1_T *));
        message_array.messages = new_messages;
        message_array.capacity = count;
    }

    for (size_t i = 0; i < count; ++i) {
        LTE_DL_CCCH_Message_Type1_T *msg = malloc(sizeof(LTE_DL_CCCH_Message_Type1_T));
        if (!msg) {
            fclose(file);
            pthread_mutex_unlock(&message_array.lock);
            log_error("Memory allocation failed during deserialization.");
            return 0;
        }

        fread(&msg->encoder.sequence_number, sizeof(int), 1, file);
        fread(&msg->nas_message.message_type, sizeof(int), 1, file);

        size_t content_length;
        fread(&content_length, sizeof(size_t), 1, file);
        msg->nas_message.content = malloc(content_length);
        if (!msg->nas_message.content) {
            free(msg);
            fclose(file);
            pthread_mutex_unlock(&message_array.lock);
            log_error("Memory allocation failed for NAS message content during deserialization.");
            return 0;
        }
        fread(msg->nas_message.content, sizeof(char), content_length, file);

        message_array.messages[i] = msg;
    }

    fclose(file);
    message_array.count = count;
    pthread_mutex_unlock(&message_array.lock);
    return 1;
}

void free_messages() {
    pthread_mutex_lock(&message_array.lock);

    for (size_t i = 0; i < message_array.count; ++i) {
        if (message_array.messages[i]) {
            free(message_array.messages[i]->nas_message.content);
            free(message_array.messages[i]);
        }
    }

    free(message_array.messages);
    message_array.messages = NULL;
    message_array.capacity = 0;
    message_array.count = 0;

    pthread_mutex_unlock(&message_array.lock);
}

int main() {
    srand(time(NULL));
    initialize_messages(MAX_MESSAGES);
    serialize_messages("messages.bin");
    deserialize_messages("messages.bin");
    free_messages();
    return 0;
}
