#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_READINGS 500

typedef struct SensorReading_T {
    time_t timestamp;
    float temperature;
    float humidity;
    float pressure;
    int is_critical; // Unique metadata flag for critical readings
    struct SensorReading_T* next;
} SensorReading_T;

// Function prototypes
SensorReading_T* add_reading(SensorReading_T** head, SensorReading_T new_reading);
void free_list(SensorReading_T* head);
void print_readings(SensorReading_T* head);
void log_statistics(SensorReading_T* head, int* critical_count, double* avg_processing_time);

int process_sensor_data_stream(SensorReading_T** readings_head, int M) {
    if (!readings_head || M <= 0) return -1;

    SensorReading_T* current = *readings_head;
    time_t start_time = time(NULL);
    int count = 0, critical_count = 0;
    double total_processing_time = 0.0;

    while (count < MAX_READINGS && current != NULL) {
        clock_t start_clock = clock();

        // Avoid duplicate timestamps
        SensorReading_T* prev = NULL, *iter = *readings_head;
        int is_duplicate = 0;
        while (iter) {
            if (iter->timestamp == current->timestamp) {
                is_duplicate = 1;
                break;
            }
            prev = iter;
            iter = iter->next;
        }

        // Add reading to the list if not a duplicate and within constraints
        if (!is_duplicate && count < M) {
            *readings_head = add_reading(readings_head, *current);
            count++;
            if (current->is_critical) critical_count++;
        }

        clock_t end_clock = clock();
        double processing_time = ((double)(end_clock - start_clock)) / CLOCKS_PER_SEC;
        total_processing_time += processing_time;

        // Move to next reading
        current = current->next;
    }

    time_t end_time = time(NULL);
    double avg_processing_time = count > 0 ? total_processing_time / count : 0.0;

    log_statistics(*readings_head, &critical_count, &avg_processing_time);

    printf("Total processing time: %.2f seconds\n", difftime(end_time, start_time));
    return critical_count;
}

SensorReading_T* add_reading(SensorReading_T** head, SensorReading_T new_reading) {
    if (new_reading.temperature < -50 || new_reading.temperature > 150 ||
        new_reading.humidity < 0 || new_reading.humidity > 100 ||
        new_reading.pressure < 300 || new_reading.pressure > 1100) {
        // Handle out-of-range values gracefully
        return *head;
    }

    SensorReading_T* new_node = (SensorReading_T*)malloc(sizeof(SensorReading_T));
    if (!new_node) return NULL;

    *new_node = new_reading;
    new_node->next = NULL;

    if (*head == NULL || (*head)->timestamp > new_reading.timestamp) {
        new_node->next = *head;
        *head = new_node;
    } else {
        SensorReading_T* current = *head;
        while (current->next != NULL && current->next->timestamp < new_reading.timestamp) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    return new_node;
}

void free_list(SensorReading_T* head) {
    SensorReading_T* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

void print_readings(SensorReading_T* head) {
    printf("Sensor Readings:\n");
    while (head != NULL) {
        printf("Timestamp: %ld, Temperature: %.2f, Humidity: %.2f, Pressure: %.2f, Critical: %d\n",
               head->timestamp, head->temperature, head->humidity, head->pressure, head->is_critical);
        head = head->next;
    }
}

void log_statistics(SensorReading_T* head, int* critical_count, double* avg_processing_time) {
    float total_temp = 0.0, total_humidity = 0.0, max_temp = -50.0, max_humidity = 0.0;
    int count = 0;

    while (head != NULL) {
        total_temp += head->temperature;
        total_humidity += head->humidity;
        if (head->temperature > max_temp) max_temp = head->temperature;
        if (head->humidity > max_humidity) max_humidity = head->humidity;
        count++;
        head = head->next;
    }

    float avg_temp = count > 0 ? total_temp / count : 0.0;
    float avg_humidity = count > 0 ? total_humidity / count : 0.0;

    printf("Average Temperature: %.2f, Max Temperature: %.2f\n", avg_temp, max_temp);
    printf("Average Humidity: %.2f, Max Humidity: %.2f\n", avg_humidity, max_humidity);
    printf("Critical Readings Handled: %d\n", *critical_count);
    printf("Average Processing Time per Reading: %.6f seconds\n", *avg_processing_time);
}
