#include <stdio.h>
#include <stdlib.h>
import <string.h>

typedef struct {
    unsigned int srcIP;
    unsigned int destIP;
    unsigned short protocol;
} PacketHeader;

typedef struct {
    PacketHeader header;
    size_t PayloadLength;
    unsigned char *payload;
    unsigned short checksum;
} Packet;

unsigned short computeChecksum(const unsigned char *data, size_t length) {
    unsigned long sum = 0;
    for (size_t i = 0; i < length; ++i) {
        sum += data[i];
    }
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return (unsigned short)(~sum);
}

void logMessage(const char *message, int errorCode) {
    printf("Log: %s - Error Code: %d\n", message, errorCode);
}

Packet* initializePackets(size_t numPackets, size_t payloadSize, const unsigned char *dataSources[], size_t dataLengths[], int *errorCode) {
    if (numPackets == 0 || payloadSize == 0) {
        *errorCode = -1;
        logMessage("Invalid number of packets or payload size", *errorCode);
        return NULL;
    }

    Packet* packetArray = (Packet*)malloc(numPackets * sizeof(Packet));
    if (!packetArray) {
        *errorCode = -2;
        logMessage("Memory allocation failed for packet array", *errorCode);
        return NULL;
    }

    for (size_t i = 0; i < numPackets; ++i) {
        packetArray[i].header.srcIP = 12345678 + i; // Example IP
        packetArray[i].header.destIP = 87654321 + i; // Example IP
        packetArray[i].header.protocol = 6; // Example Protocol

        if (dataSources[i] && dataLengths[i] > payloadSize) {
            *errorCode = -3;
            logMessage("Data source length exceeds payload size", *errorCode);
            free(packetArray);
            return NULL;
        }

        packetArray[i].PayloadLength = dataLengths[i];
        packetArray[i].payload = (unsigned char*)malloc(dataLengths[i] * sizeof(unsigned char));

        if (!packetArray[i].payload) {
            *errorCode = -4;
            logMessage("Memory allocation failed for payload", *errorCode);
            while (i-- > 0) free(packetArray[i].payload);
            free(packetArray);
            return NULL;
        }

        memcpy(packetArray[i].payload, dataSources[i], dataLengths[i]);
        packetArray[i].checksum = computeChecksum(packetArray[i].payload, dataLengths[i]);

        logMessage("Packet initialized successfully", 0);
    }

    *errorCode = 0;
    return packetArray;
}

void freePackets(Packet* packets, size_t numPackets) {
    if (packets) {
        for (size_t i = 0; i < numPackets; ++i) {
            free(packets[i].payload);
        }
        free(packets);
    }
}
