} CRC_Indication_Manager;

CRC_Indication_Manager* create_crc_indication_manager(size_t n) {
    if (n == 0) return NULL;

    CRC_Indication_Manager *manager = malloc(sizeof(CRC_Indication_Manager));
    manager->array = calloc(n, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size = n;

    pthread_mutex_init(&manager->mutex, NULL);

    srand((unsigned int)time(NULL)); // Seed for random number generation

    if (!manager->array) {
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        manager->array[i].RX_UE_INFORMATION_TAG = rand() % 100; // Example index
        manager->array[i].RNTI = rand() % 65535;
        manager->array[i].CRC_INDICATION_REL8_TAG[0] = (uint8_t)(rand() % 256);
        manager->array[i].CRC_INDICATION_REL8_TAG[1] = (uint8_t)(rand() % 256);
        manager->array[i].CRC_INDICATION_REL8_TAG[2] = (uint8_t)(rand() % 256);
        manager->array[i].CRC_INDICATION_REL8_TAG[3] = (uint8_t)(rand() % 256); // Random CRCFLAG
    }

    return manager;
}

void destroy_crc_indication_manager(CRC_Indication_Manager *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->mutex);
    free(manager->array);
    free(manager);
}

void update_crcflag_for_rnti(CRC_Indication_Manager *manager, unsigned short rnti, uint8_t crc_flag) {
    if (!manager || !crc_flag) return;

    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].RNTI == rnti) {
            manager->array[i].CRC_INDICATION_REL8_TAG[3] = crc_flag;
            break;
        }
    }

    update_crcflag_in_shared_memory(rnti, crc_flag);

    pthread_mutex_unlock(&manager->mutex);
}

// Example function to be called by threads
void* thread_function(void *arg) {
    CRC_Indication_Manager *manager = (CRC_Indication_Manager*) arg;

    // Example operation
    update_crcflag_for_rnti(manager, rand() % 65535, (uint8_t)(rand() % 256));

    return NULL;
}

int main() {
    size_t n_elements = 1000; // Example size

    CRC_Indication_Manager *manager = create_crc_indication_manager(n_elements);
    if (!manager) {
        fprintf(stderr, "Failed to create CRC indication manager.\n");
        return EXIT_FAILURE;
    }

    const int num_threads = 10;
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, thread_function, manager);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_crc_indication_manager(manager);

    return EXIT_SUCCESS;
}
