    float latency; // Example measurement
    float throughput; // Example measurement
    float packet_loss; // Example measurement
    struct PerformanceMetric *next;
} PerformanceMetric;

// Define a structure to hold LTE_DL_CCCH_Message_Type1_T details
typedef struct {
