    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} LTE_DL_CCCH_Message_Type1_T;

// Define a node structure that combines network node and its metrics
typedef struct Node {
    NetworkNode node_info;
    PerformanceMetric *metrics_head;
    LTE_DL_CCCC_message_Type1_T lte_message;
    struct Node* next;
} ListNode;

// Head pointer for the list of nodes
ListNode* head = NULL;

// Mutex for thread safety (consider using a more advanced lock-free structure if feasible)
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new node to the list
void addNode(unsigned char ip[4], uint16_t port, bool status,
             time_t timestamp, uint32_t session_id, float latency, 
             float throughput, float packet_loss,
             int TLVEncoder, const char* NAS_Message,
             uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&mutex);

    ListNode *new_node = (ListNode*) malloc(sizeof(ListNode));
    if (!new_node) return; // Handle memory allocation failure

    memcpy(new_node->node_info.ip, ip, 4);
    new_node->node_info.port = port;
    new_node->node_info.status = status;

    new_node->metrics_head = (PerformanceMetric *)malloc(sizeof(PerformanceMetric));
    if (!new_node->metrics_head) {
        free(new_node);
        pthread_mutex_unlock(&mutex);
        return; // Handle memory allocation failure
    }

    new_node->metrics_head->timestamp = timestamp;
    new_node->metrics_head->session_id = session_id;
    new_node->metrics_head->latency = latency;
    new_node->metrics_head->throughput = throughput;
    new_node->metrics_head->packet_loss = packet_loss;
    new_node->metrics_head->next = NULL;

    new_node->lte_message.TLVEncoder = TLVEncoder;
    strncpy(new_node->lte_message.NAS_Message, NAS_Message, sizeof(new_node->lte_message.NAS_Message) - 1);
    new_node->lte_message.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->lte_message.RNTI = RNTI;

    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&mutex);
}

// Function to fetch employee data from the database
void fetchEmployeeData(const char *db_host, const char *db_user,
                       const char *db_pass, const char *db_name,
                       uint32_t supervisor_id) {
    MYSQL *conn;
    MYSQL_RES *res;
    MYSQL_ROW row;

    conn = mysql_init(NULL);

    if (!mysql_real_connect(conn, db_host, db_user, db_pass, 
                            db_name, 0, NULL, 0)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        exit(1);
    }

    char query[256];
    snprintf(query, sizeof(query), "SELECT name, city, address FROM employees WHERE supervisor_id = %u",
             supervisor_id);

    if (mysql_query(conn, query)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        mysql_close(conn);
        exit(1);
    }

    res = mysql_use_result(conn);

    printf("Executed SQL: %s\n", query);

    while ((row = mysql_fetch_row(res))) {
        printf("Name: %s, City: %s, Address: %s\n", row[0], row[1], row[2]);
    }

    mysql_free_result(res);
    mysql_close(conn);
}

// Simple logging function
