```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h> // For network byte order functions
#include <pthread.h>   // For thread safety

// Structure for IP addresses (supporting both IPv4 and IPv6)
typedef union {
    struct in_addr ipv4;
    struct in6_addr ipv6;
} IPAddress;

// TCP Packet Header structure
typedef struct {
    IPAddress src_ip;
    IPAddress dst_ip;
    uint32_t sequence_number;
    uint16_t checksum; // Example, not calculating real checksum here
} TCPPacketHeader;

// Dynamic array of packet headers
typedef struct {
    TCPTCPPacketHeader *headers;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;  // For thread safety
} PacketHeaderArray;

// Function declarations
PacketHeaderArray* create_packet_header_array(size_t initial_capacity);
void destroy_packet_header_array(PacketHeaderArray *array);
int insert_packet_header(PacketHeaderArray *array, const TCPTCPPacketHeader *header);
TCPPacketHeader* retrieve_packet_header(PacketHeaderArray *array, size_t index);
int remove_packet_header(PacketHeaderArray *array, size_t index);
int validate_packet_header(const TCPPacketHeader *header);

// Function implementations
PacketHeaderArray* create_packet_header_array(size_t initial_capacity) {
    PacketHeaderArray *array = malloc(sizeof(PacketHeaderArray));
    if (!array) return NULL;

    array->headers = malloc(initial_capacity * sizeof(TCPPTCPacketHeader));
    if (!array->headers) {
        free(array);
        return NULL;
    }

    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_packet_header_array(PacketHeaderArray *array) {
    if (array) {
        free(array->headers);
        pthread_mutex_destroy(&array->lock);
        free(array);
    }
}

int insert_packet_header(PacketHeaderArray *array, const TCPPacketHeader *header) {
    if (!validate_packet_header(header)) return -1;

    pthread_mutex_lock(&array->lock);

    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        TCPTCPHeader *new_headers = realloc(array->headers, new_capacity * sizeof(TCPTCPHeader));
        if (!new_headers) {
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->headers = new_headers;
        array->capacity = new_capacity;
    }

    memcpy(&array->headers[array->count], header, sizeof(TCPTCPHeader));
    array->count++;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

TCPPacketHeader* retrieve_packet_header(PacketHeaderArray *array, size_t index) {
    if (index >= array->count) return NULL;

    pthread_mutex_lock(&array->lock);

    TCPPacketHeader *header = &array->headers[index];

    pthread_mutex_unlock(&array->lock);
    return header;
}

int remove_packet_header(PacketHeaderArray *array, size_t index) {
    if (index >= array->count) return -1;

    pthread_mutex_lock(&array->lock);

    memmove(&array->headers[index], &array->headers[index + 1],
            (array->count - index - 1) * sizeof(TCPPacketHeader));
    array->count--;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

int validate_packet_header(const TCPPacketHeader *header) {
    // Simple placeholder validation; should be expanded for real use
    if (ntohl(header->sequence_number) == 0) return 0;
    return 1;
}
```

### Key Points:
- **Thread Safety**: The library uses a mutex to ensure thread-safe operations on the dynamic array.
- **Dynamic Array Management**: Handles resizing of the internal array as needed.
- **Error Handling**: Basic error handling is in place for memory allocation failures and invalid indices.
- **Validation Function**: A placeholder function `validate_packet_header` checks simple conditions; this should be extended to include real checksum validation.

This example provides a basic framework. You may need additional features like IPv6-specific handling, advanced checksum calculations, or more comprehensive error reporting depending on your application's requirements."]

