int readAndValidateNumbers(const char* filename, float minVal, float maxVal, float** outNumbers, size_t* count) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    float number;
    *count = 0;
    while (fscanf(file, "%f", &number) == 1) {
        if (number >= minVal && number <= maxVal) {
            (*count)++;
            *outNumbers = realloc(*outNumbers, (*count) * sizeof(float));
            (*outNumbers)[*count - 1] = number;
        }
    }

    fclose(file);
    return 0;
}

