pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a list of NFAPICRCINDICATIONPDUT structures
PDUListEntry* generateNfadPduList(int count) {
    pthread_mutex_lock(&lock);

    // Allocate memory for the list
    PDUListEntry *pdu_list = (PDUListEntry*) malloc(sizeof(PDUListEntry) * count);
    if (!pdu_list) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Seed random number generator
    srand((unsigned int)time(NULL));

    for (int i = 0; i < count; ++i) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i + 1;
        pdu_list[i].RNTI = rand() % 65536;
        pdu_list[i].pdu.CRC_INDICATION_REL8.CRCFLAG = rand() % 2;
    }

    pthread_mutex_unlock(&lock);
    return pdu_list;
}

