import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.locks.ReentrantLock;

public class MD5Hasher {
    private final ReentrantLock lock = new ReentrantLock();

    public String computeMD5Hash(String input) {
        lock.lock();
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : messageDigest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            System.err.println("Error computing MD5 hash: " + e.getMessage());
            return null;
        } finally {
            lock.unlock();
        }
    }

    public String computeMD5HashWithProgress(String input) throws InterruptedException {
        lock.lock();
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageBytes = input.getBytes();
            int chunkSize = messageBytes.length / 10;

            for (int i = 0; i < messageBytes.length; i += chunkSize) {
                if (i > 0) {
                    Thread.sleep(50); // Simulate work
                }
                md.update(messageBytes, i, Math.min(chunkSize, messageBytes.length - i));
                System.out.printf("Progress: %.0f%%%n", ((double) i / messageBytes.length) * 100);
            }

            byte[] messageDigest = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : messageDigest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            System.err.println("Error computing MD5 hash: " + e.getMessage());
            return null;
        } finally {
            lock.unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        MD5Hasher hasher = new MD5Hasher();

        // Example usage
        String largeString = "a".repeat(1024 * 1024); // 1MB string
        System.out.println(hasher.computeMD5HashWithProgress(largeString));
    }
}
```

