    // Add more event types as needed.
} EventType;

typedef struct {
    time_t timestamp;
    EventType type;
    int id;
} TrafficEvent;

typedef struct {
    TrafficEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TrafficEventManager;

TrafficEventManager* initialize_traffic_events(size_t initial_capacity, time_t start_time, time_t end_time) {
    TrafficEventManager *manager = malloc(sizeof(TrafficEventManager));
    if (!manager) return NULL;

    manager->events = calloc(initial_capacity, sizeof(TrafficEvent));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    srand(time(NULL)); // Seed the random number generator.

    for (size_t i = 0; i < initial_capacity; ++i) {
        TrafficEvent *event = &manager->events[i];

        event->timestamp = start_time + rand() % (end_time - start_time);
        event->type = rand() % 3; // Randomly select an event type.
        event->id = i;
    }

    return manager;
}

void grow_traffic_events(TrafficEventManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        TrafficEvent *new_events = realloc(manager->events, new_capacity * sizeof(TrafficEvent));
        if (!new_events) {
            pthread_mutex_unlock(&manager->lock);
            return; // Handle allocation failure as needed.
        }

        manager->events = new_events;
        manager->capacity = new_capacity;

        time_t start_time = manager->events[0].timestamp - 1; // Example: adjust based on your logic
        time_t end_time = manager->events[manager->count - 1].timestamp + 1; 

        for (size_t i = manager->count; i < new_capacity; ++i) {
            TrafficEvent *event = &manager->events[i];

            event->timestamp = start_time + rand() % (end_time - start_time);
            event->type = rand() % 3;
            event->id = i;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void free_traffic_events(TrafficEventManager *manager) {
    if (manager) {
        free(manager->events);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

// Example of extending the function to add new events.
int add_traffic_event(TrafficEventManager *manager, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        grow_traffic_events(manager);
    }

    TrafficEvent *event = &manager->events[manager->count];
    event->timestamp = start_time + rand() % (end_time - start_time);
    event->type = rand() % 3;
    event->id = manager->count;

    ++(manager->count);

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Main function for demonstration purposes.
int main() {
    size_t initial_capacity = 10;
    time_t start_time = time(NULL) - 3600; // One hour ago.
    time_t end_time = time(NULL); // Current time.

    TrafficEventManager *manager = initialize_traffic_events(initial_capacity, start_time, end_time);
    if (!manager) {
        fprintf(stderr, "Failed to initialize traffic events manager.\n");
        return EXIT_FAILURE;
    }

    add_traffic_event(manager, start_time, end_time);

    free_traffic_events(manager);

    return 0;
}
