// Function to read RNTI values from a file
int readRNTIsFromFile(const char *filename, int **rntiArray, size_t *count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open RNTI configuration file.");
        return -1;
    }

    // Assuming the number of RTNI values is known or determined dynamically
    size_t capacity = 100; 
    int *tempArray = malloc(capacity * sizeof(int));
    if (tempArray == NULL) {
        perror("Failed to allocate memory for RNTI array.");
        fclose(file);
        return -1;
    }

    *count = 0;

    while (fscanf(file, "%d", &tempArray[(*count)++]) == 1) {
        // Reallocate if needed
        if (*count >= capacity) {
            capacity *= 2;
            int *newArray = realloc(tempArray, capacity * sizeof(int));
            if (!newArray) {
                perror("Failed to reallocate memory for RNTI array.");
                free(tempArray);
                fclose(file);
                return -1;
            }
            tempArray = newArray;
        }
    }

    fclose(file);

    // Resize the final array to match the number of elements read
    int *finalArray = realloc(tempArray, (*count) * sizeof(int));
    if (finalArray == NULL) {
        perror("Failed to resize RNTI array.");
        free(tempArray);
        return -1;
    }

    *rntiArray = finalArray;
    return 0;
}

