#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

// Enum for event types
typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    EVENT_TYPE_C
} EventType;

// Structure to hold additional attributes
typedef struct {
    double latitude;
    double longitude;
    int speed;
    int direction;
} TrafficAttributes;

// Structure for a traffic event
typedef struct {
    time_t timestamp;
    EventType eventType;
    int uniqueID;
    TrafficAttributes attrs;
} TrafficEvent;

// Thread-safe dynamic array structure
typedef struct {
    TrafficEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TrafficEventsArray;

// Function to initialize the thread-safe dynamic array
void initTrafficEventsArray(TrafficEventsArray *array, size_t initialCapacity) {
    array->events = malloc(sizeof(TrafficEvent) * initialCapacity);
    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

// Function to resize the dynamic array
void resizeTrafficEventsArray(TrafficEventsArray *array) {
    pthread_mutex_lock(&array->lock);
    size_t newCapacity = array->capacity * 2;
    TrafficEvent *newEvents = realloc(array->events, sizeof(TrafficEvent) * newCapacity);
    if (newEvents) {
        array->events = newEvents;
        array->capacity = newCapacity;
    }
    pthread_mutex_unlock(&array->lock);
}

// Function to add an event to the dynamic array
void addTrafficEvent(TrafficEventsArray *array, TrafficEvent event) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        resizeTrafficEventsArray(array);
    }
    array->events[array->count++] = event;
    pthread_mutex_unlock(&array->lock);
}

// Function to fetch real-time traffic data
TrafficAttributes fetchRealTimeTrafficData() {
    TrafficAttributes attrs;
    // Simulate fetching data from an external service
    attrs.latitude = (double)rand() / RAND_MAX * 180 - 90; // Random latitude
    attrs.longitude = (double)rand() / RAND_MAX * 360 - 180; // Random longitude
    attrs.speed = rand() % 120 + 10; // Random speed between 10 and 130
    attrs.direction = rand() % 360; // Random direction in degrees

    return attrs;
}

// Function to initialize events with real-time data
void initializeTrafficEvents(TrafficEventsArray *array, size_t N, time_t startTime, time_t endTime) {
    srand(time(NULL));
    for (size_t i = 0; i < N; ++i) {
        TrafficEvent event;
        event.timestamp = startTime + rand() % (endTime - startTime);
        event.eventType = rand() % 3;
        event.uniqueID = rand();
        event.attrs = fetchRealTimeTrafficData();

        addTrafficEvent(array, event);
    }
}

// Function to compute statistics
void calculateStatistics(const TrafficEventsArray *array) {
    double totalSpeed = 0.0;
    int eventTypeCount[3] = {0};

    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        totalSpeed += array->events[i].attrs.speed;
        eventTypeCount[array->events[i].eventType]++;
    }
    pthread_mutex_unlock(&array->lock);

    double averageSpeed = array->count ? totalSpeed / array->count : 0;
    printf("Average Speed: %.2f\n", averageSpeed);

    for (int i = 0; i < 3; ++i) {
        printf("Event Type %d Count: %d\n", i, eventTypeCount[i]);
    }
}

// Function to clean up resources
void cleanupTrafficEventsArray(TrafficEventsArray *array) {
    pthread_mutex_destroy(&array->lock);
    free(array->events);
}

int main() {
    TrafficEventsArray events;
    time_t startTime = time(NULL) - 3600; // 1 hour ago
    time_t endTime = time(NULL);

    initTrafficEventsArray(&events, 10); // Initial capacity of 10
    initializeTrafficEvents(&events, 100, startTime, endTime);

    calculateStatistics(&events);
    cleanupTrafficEventsArray(&events);

    return 0;
}
