} LTE_TRANSPORT_CONTEXT_T;

// Node for the linked list
struct ContextNode {
    LTE_TRANSPORT_CONTEXT_T context;
    struct ContextNode* next;
};

// Structure to manage contexts
typedef struct {
    struct ContextNode* head;
    pthread_mutex_t lock; // Mutex for thread safety
} ContextManager;

// Logger function (placeholder)
