LTE_TRANSPORT_CONTEXT_T* get_context(ContextManager* manager, TRANSPORT_CONTEXT_ID id);
int update_context(ContextManager* manager, TRANSPORT_CONTEXT_ID id, LTE_TRANSPORT_CHANNEL_CONFIG new_config);
void remove_stale_contexts(ContextManager* manager);
void monitor_and_alert(ContextManager* manager);
void cleanup_manager(ContextManager* manager);

// Create a context manager
ContextManager* create_context_manager() {
    ContextManager* manager = (ContextManager*)malloc(sizeof(ContextManager));
    if (!manager) return NULL;
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    log_message("Created context manager.");
    return manager;
}

// Add a new context
int add_context(ContextManager* manager, LTE_TRANSPORT_CONTEXT_T new_context) {
    pthread_mutex_lock(&manager->lock);

    // Check for unique TRANSPORT_CONTEXT_ID
    struct ContextNode* current = manager->head;
    while (current != NULL) {
        if (current->context.contextId == new_context.contextId) {
            log_message("Context ID already exists.");
            pthread_mutex_unlock(&manager->lock);
            return -1; // Error: duplicate context ID
        }
        current = current->next;
    }

    struct ContextNode* newNode = (struct ContextNode*)malloc(sizeof(struct ContextNode));
    if (!newNode) {
        log_message("Failed to allocate memory for new context.");
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: failed allocation
    }
    newNode->context = new_context;
    newNode->next = manager->head;
    manager->head = newNode;

    log_message("Added new context.");
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Retrieve a context by ID
LTE_TRANSPORT_CONTEXT_T* get_context(ContextManager* manager, TRANSPORT_CONTEXT_ID id) {
    pthread_mutex_lock(&manager->lock);

    struct ContextNode* current = manager->head;
    while (current != NULL) {
        if (current->context.contextId == id) {
            log_message("Retrieved context.");
            pthread_mutex_unlock(&manager->lock);
            return &(current->context); // Found
        }
        current = current->next;
    }

    log_message("Context not found.");
    pthread_mutex_unlock(&manager->lock);
    return NULL; // Not found
}

// Update an existing context's configuration
int update_context(ContextManager* manager, TRANSPORT_CONTEXT_ID id, LTE_TRANSPORT_CHANNEL_CONFIG new_config) {
    pthread_mutex_lock(&manager->lock);

    struct ContextNode* current = manager->head;
    while (current != NULL) {
