#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct WorkerResource {
    int id;
    pthread_mutex_t lock;
} WorkerResource;

typedef struct Job {
    char *description;
    time_t deadline;
    int priority; // Higher number means higher priority
    struct Job **dependencies;
    size_t dep_count;
} Job;

typedef struct DataProcessingTask {
    Job job;
    WorkerResource *resources;
    size_t resource_count;
    pthread_mutex_t task_lock;
    pthread_cond_t cond_var;
    int completed;
} DataProcessingTask;

// Function prototypes
DataProcessingTask* create_task(Job job, WorkerResource **resources, size_t count);
void destroy_task(DataProcessingTask *task);
int add_task(DataProcessingTask ***tasks, size_t *size, DataProcessingTask *new_task);
int remove_task(DataProcessingTask ***tasks, size_t *size, int index);
void schedule_tasks(DataProcessingTask **tasks, size_t size);
void* execute_task(void *arg);
void handle_resource_failure(WorkerResource *resource);

// Global mutex for managing tasks array
pthread_mutex_t task_array_lock = PTHREAD_MUTEX_INITIALIZER;

DataProcessingTask* create_task(Job job, WorkerResource **resources, size_t count) {
    DataProcessingTask *task = (DataProcessingTask*)malloc(sizeof(DataProcessingTask));
    if (!task) return NULL;

    task->job = job;
    task->resources = resources;
    task->resource_count = count;
    pthread_mutex_init(&task->task_lock, NULL);
    pthread_cond_init(&task->cond_var, NULL);
    task->completed = 0;

    for (size_t i = 0; i < count; ++i) {
        pthread_mutex_init(&resources[i]->lock, NULL);
    }

    return task;
}

void destroy_task(DataProcessingTask *task) {
    if (!task) return;

    for (size_t i = 0; i < task->resource_count; ++i) {
        pthread_mutex_destroy(&task->resources[i]->lock);
    }
    pthread_mutex_destroy(&task->task_lock);
    pthread_cond_destroy(&task->cond_var);
    free(task);
}

int add_task(DataProcessingTask ***tasks, size_t *size, DataProcessingTask *new_task) {
    pthread_mutex_lock(&task_array_lock);

    // Resize array if necessary
    *tasks = realloc(*tasks, (*size + 1) * sizeof(DataProcessingTask*));
    if (!*tasks) {
        pthread_mutex_unlock(&task_array_lock);
        return -1;
    }

    (*tasks)[*size] = new_task;
    ++(*size);

    pthread_mutex_unlock(&task_array_lock);
    return 0;
}

int remove_task(DataProcessingTask ***tasks, size_t *size, int index) {
    if (index < 0 || index >= *size) return -1;

    pthread_mutex_lock(&task_array_lock);

    DataProcessingTask* task = (*tasks)[index];
    destroy_task(task);

    // Shift remaining tasks
    for (size_t i = index; i < *size - 1; ++i) {
        (*tasks)[i] = (*tasks)[i + 1];
    }
    *tasks = realloc(*tasks, (*size - 1) * sizeof(DataProcessingTask*));

    --(*size);

    pthread_mutex_unlock(&task_array_lock);
    return 0;
}

void schedule_tasks(DataProcessingTask **tasks, size_t size) {
    pthread_t threads[size];

    for (size_t i = 0; i < size; ++i) {
        if (pthread_create(&threads[i], NULL, execute_task, &tasks[i]) != 0) {
            perror("Failed to create thread");
        }
    }

    for (size_t i = 0; i < size; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void* execute_task(void *arg) {
    DataProcessingTask *task = (DataProcessingTask*)arg;

    // Check dependencies
    for (size_t i = 0; i < task->job.dep_count; ++i) {
        while (!(*(task->job.dependencies[i]))->completed) {
            pthread_cond_wait(&task->cond_var, &task->task_lock);
        }
    }

    // Acquire resources
    for (size_t i = 0; i < task->resource_count; ++i) {
        if (pthread_mutex_trylock(&task->resources[i]->lock) != 0) {
            handle_resource_failure(task->resources[i]);
            continue;
        }
    }

    // Simulate job execution
    printf("Executing job: %s\n", task->job.description);
    sleep(1);

    // Mark as completed
    pthread_mutex_lock(&task->task_lock);
    task->completed = 1;
    for (size_t i = 0; i < task->job.dep_count; ++i) {
        pthread_cond_signal(task->cond_var); // Notify dependent tasks
    }
    pthread_mutex_unlock(&task->task_lock);

    return NULL;
}

void handle_resource_failure(WorkerResource *resource) {
    printf("Handling failure for resource %d\n", resource->id);
    // Implement retry or fallback logic here
}
