        fprintf(stderr, "Invalid number of structures requested.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
