        pdus[i].rnti = fetch_rnti();
        pdus[i].crc_indication_rel8.crc_indication_rel8_tag = rand() % 256;

        // Ensure no two consecutive structures have the same CRCFLAG
        int crcflag;
        do {
            crcflag = rand() % 2; // Randomly set to 0 or 1
        } while (i > 0 && pdus[i - 1].CRCFLAG == crcflag);

        pdus[i].CRCFLAG = crcflag;

        printf("Allocated structure %d: RXUE=%d, RNTI=%d, CRCIND=%d, CRCFLAG=%d\n", 
               i + 1, pdus[i].rx_ue_information.rx_ue_info, pdus[i].rnti.rnti,
