#define MAX_FILENAME_LENGTH 255
#define MAX_FILE_NAME 100

typedef struct {
    float value;
    time_t timestamp;
} SensorData;

typedef struct {
    SensorData *data;
    size_t count;
    pthread_rwlock_t lock;
} ThreadSafeDataStorage;

float calculate_average(ThreadSafeDataStorage *storage) {
    float sum = 0.0f;
    for (size_t i = 0; i < storage->count; ++i) {
        sum += storage->data[i].value;
    }
    return storage->count > 0 ? sum / storage->count : 0.0f;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

char* get_file_extension(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (!dot || dot == filename) return ".txt";
    return dot;
}

int count_vowels(const char *str) {
    int count = 0;
    while (*str) {
        if (strchr("aeiouAEIOU", *str)) ++count;
        str++;
    }
    return count;
}

void refresh_sensor_data(ThreadSafeDataStorage *storage, float temp_range_min, float temp_range_max);

char* process_filename(const char *filename, const char *metadata_service_status) {
    if (!filename || strlen(filename) == 0) {
        log_error("Invalid filename.");
        return NULL;
    }

    if (strncasecmp(filename, "./", 2) == 0 || strncasecmp(filename, "../", 3) == 0) {
        log_error("Path traversal detected.");
        return NULL;
    }

    char new_filename[MAX_FILENAME_LENGTH + 1];
    strncpy(new_filename, filename, MAX_FILE_NAME);
    if (strlen(new_filename) > MAX_FILE_NAME - 10) { // Reserve space for extension and timestamp
        strncat(new_filename, "...", 3); // Truncate with ellipsis
        log_error("Filename truncated.");
    }

    const char *extension = get_file_extension(filename);
    int vowel_count = count_vowels(filename);

    time_t current_time;
    time(&current_time);
    struct tm *tm_info = localtime(&current_time);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "_%Y%m%d_%H%M%S", tm_info);

    snprintf(new_filename + strlen(new_filename) - strlen(extension), 
             MAX_FILENAME_LENGTH - strlen(new_filename) + 1, 
             "%d%s%s",
             vowel_count,
             extension,
             timestamp);

    if (strlen(new_filename) > MAX_FILENAME_LENGTH) {
        new_filename[MAX_FILENAME_LENGTH] = '\0';
        log_error("Filename exceeds maximum length.");
    }

    // Append metadata service status if available
    if (metadata_service_status && strcmp(metadata_service_status, "available") == 0) {
        strncat(new_filename, "_metadata", MAX_FILENAME_LENGTH - strlen(new_filename));
    } else {
        strncat(new_filename, "_noservice", MAX_FILENAME_LENGTH - strlen(new_filename));
    }

    return strdup(new_filename);
}

void process_file(const char *filename, float range_min, float range_max) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_error("Failed to open file.");
        return;
    }

    ThreadSafeDataStorage storage = { .data = NULL, .count = 0 };
    pthread_rwlock_init(&storage.lock, NULL);

    float number;
    while (fscanf(file, "%f", &number) == 1) {
        if (number >= range_min && number <= range_max) {
            pthread_rwlock_wrlock(&storage.lock);
            storage.data = realloc(storage.data, sizeof(SensorData) * (storage.count + 1));
            storage.data[storage.count].value = number;
            time(&(storage.data[storage.count].timestamp));
            ++storage.count;
            pthread_rwlock_unlock(&storage.lock);
        }
    }

    fclose(file);

    float average = calculate_average(&storage);
    printf("Average: %f\n", average);

    // Refresh sensor data in a separate thread
    pthread_t refresh_thread;
    pthread_create(&refresh_thread, NULL, (void *)refresh_sensor_data, &storage);
    pthread_join(refresh_thread, NULL);

    free(storage.data);
    pthread_rwlock_destroy(&storage.lock);
}

void* refresh_sensor_data(void *arg) {
    ThreadSafeDataStorage *storage = (ThreadSafeDataStorage *)arg;

    // Dummy implementation for refreshing sensor data
    while (1) {
        sleep(5);  // Refresh every 5 seconds
        pthread_rwlock_wrlock(&storage->lock);

        // Simulate new data being added (this part would be replaced with actual data refresh logic)
        if (storage->count < 1000) { // Example limit for demonstration purposes
            storage->data = realloc(storage->data, sizeof(SensorData) * (storage->count + 1));
            storage->data[storage->count].value = rand() % 100;  // Simulated sensor value
            time(&(storage->data[storage->count].timestamp));
            ++storage->count;
        }

        pthread_rwlock_unlock(&storage->lock);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <filename> <range_min> <range_max>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *metadata_service_status = "available"; // Simulated metadata service status
    char *new_filename = process_filename(argv[1], metadata_service_status);

    if (new_filename) {
        printf("Processed filename: %s\n", new_filename);

        float range_min = atof(argv[2]);
        float range_max = atof(argv[3]);
        process_file(new_filename, range_min, range_max);

        free(new_filename);
    }

    return EXIT_SUCCESS;
}
