#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum { DEBUG, INFO, WARN, ERROR } LogLevel;

typedef struct {
    char *timestamp;
    int event_id;
    char *message;
} LogEntry;

typedef struct {
    LogLevel level;
    FILE *file;
    FILE *console;
    char *log_file_path;
    int log_to_file;
    int log_to_console;
} LoggingConfig;

LoggingConfig logging_config = { DEBUG, NULL, stdout, "./app.log", 1, 1 };

void free_log_entry(LogEntry *entry) {
    if (entry->timestamp) free(entry->timestamp);
    if (entry->message) free(entry->message);
}

void log_message(LogLevel level, int event_id, const char *message) {
    if (level < logging_config.level) return;

    LogEntry entry;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    // Allocate and set timestamp
    entry.timestamp = malloc(20 * sizeof(char));
    strftime(entry.timestamp, 19, "%Y-%m-%d %H:%M:%S", tm_info);

    entry.event_id = event_id;

    // Allocate and copy message
    entry.message = strdup(message);

    if (logging_config.log_to_file && logging_config.file) {
        fprintf(logging_config.file, "[%s] [%d] %s\n", entry.timestamp, entry.event_id, entry.message);
    }
    if (logging_config.log_to_console && logging_config.console) {
        fprintf(logging_config.console, "[%s] [%d] %s\n", entry.timestamp, event_id, message);
    }

    free_log_entry(&entry);
}

int initialize_logging_system(const char *log_file_path, LogLevel level, int log_to_file, int log_to_console) {
    logging_config.level = level;
    logging_config.log_to_file = log_to_file;
    logging_config.log_to_console = log_to_console;

    if (log_file_path != NULL) {
        strcpy(logging_config.log_file_path, log_file_path);
    }

    if (logging_config.log_to_file) {
        logging_config.file = fopen(logging_config.log_file_path, "a");
        if (!logging_config.file) {
            perror("Failed to open log file");
            return -1;
        }
    } else {
        logging_config.file = NULL;
    }

    logging_config.console = (log_to_console) ? stdout : NULL;

    return 0;
}

void cleanup_logging_system() {
    if (logging_config.file) {
        fclose(logging_config.file);
        logging_config.file = NULL;
    }
}
