#include "pdf_converter.h"   // Assume a PDF converter library

#define INITIAL_CAPACITY 10
#define MAX_THREADS 4

typedef struct {
    char **filePaths;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MediaFileList;

MediaFileList* createMediaFileList() {
    MediaFileList *list = malloc(sizeof(MediaFileList));
    if (!list) return NULL;

    list->filePaths = malloc(INITIAL_CAPACITY * sizeof(char *));
    if (!list->filePaths) {
        free(list);
        return NULL;
    }

    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int addFilePath(MediaFileList *list, const char *filePath) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        char **newPaths = realloc(list->filePaths, newCapacity * sizeof(char *));
        if (!newPaths) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failure
        }

        list->filePaths = newPaths;
        list->capacity = newCapacity;
    }

    char *pathCopy = strdup(filePath);
    if (!pathCopy) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    list->filePaths[list->count++] = pathCopy;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void freeMediaFileList(MediaFileList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->filePaths[i]);
    }
    free(list->filePaths);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void processFilesInParallel(MediaFileList *list, pdf_converter_context *context) {
    size_t threads = (list->count < MAX_THREADS) ? list->count : MAX_THREADS;
    pthread_t threadArray[threads];

    for (size_t i = 0; i < threads; ++i) {
        if (pthread_create(&threadArray[i], NULL, convertFileToPDF, (void *)context)) {
            logError("Failed to create a processing thread");
        }
    }

    for (size_t i = 0; i < threads; ++i) {
        pthread_join(threadArray[i], NULL);
    }
}

void* convertFileToPDF(void *arg) {
    pdf_converter_context *context = (pdf_converter_context *)arg;
    MediaFileList *list = context->fileList;

    while (1) {
        pthread_mutex_lock(&list->lock);

        if (context->currentIndex >= list->count) {
            pthread_mutex_unlock(&list->lock);
            break; // All files processed
        }

        char *filePath = list->filePaths[context->currentIndex];
        context->currentIndex++;

        pthread_mutex_unlock(&list->lock);

        unsigned int uniqueID = rand();  // Generate a random identifier

        if (!pdf_convert_to_pdf(filePath, uniqueID)) {
            logError("PDF conversion failed for file: %s", filePath);
        } else {
            logInfo("Successfully processed file: %s with ID: %u", filePath, uniqueID);
        }

        free(filePath); // Free the string after processing
    }

    return NULL;
}

void processMediaFilesAndGeneratePDFs(char **filePaths, size_t numFiles) {
    MediaFileList *list = createMediaFileList();
    if (!list) {
        logError("Failed to initialize media file list");
        return;
    }

    pdf_converter_context context;
    context.fileList = list;
    context.currentIndex = 0;

    for (size_t i = 0; i < numFiles; ++i) {
        if (addFilePath(list, filePaths[i]) != 0) {
            logError("Failed to add file path: %s", filePaths[i]);
            freeMediaFileList(list);
            return;
        }
    }

    processFilesInParallel(list, &context);

    freeMediaFileList(list);
}
