#include <time.h>
#include <pthread.h>

typedef long offset_t;
typedef int key_t;

#define MAX_RECORDS 1000
#define RAND_MIN 1
#define RAND_MAX 100

typedef struct {
    int value;
} record_t;

// Logging function to write errors to a log file
void logError(const char *errorType, const char *details) {
    FILE *logFile = fopen("db_errors.log", "a");
    if (logFile != NULL) {
        time_t now = time(NULL);
        fprintf(logFile, "[%s] %s: %s\n", ctime(&now), errorType, details);
        fclose(logFile);
    }
}

// Mutex for thread safety
pthread_mutex_t dbMutex = PTHREAD_MUTEX_INITIALIZER;

void initializeDatabase(offset_t *offsetArray, key_t *keyArray, record_t **recordArrayPtr, size_t numElements) {
    pthread_mutex_lock(&dbMutex);

    // Allocate memory for arrays and check for errors
    offsetArray = (offset_t *)malloc(numElements * sizeof(offset_t));
    if (!offsetArray) {
        logError("Memory Error", "Failed to allocate memory for offset array");
        goto cleanup;
    }

    keyArray = (key_t *)malloc(numElements * sizeof(key_t));
    if (!keyArray) {
        logError("Memory Error", "Failed to allocate memory for key array");
        free(offsetArray);
        goto cleanup;
    }

    *recordArrayPtr = (record_t *)malloc(numElements * sizeof(record_t));
    if (!*recordArrayPtr) {
        logError("Memory Error", "Failed to allocate memory for record array");
        free(offsetArray);
        free(keyArray);
        goto cleanup;
    }

    // Initialize arrays
    for (size_t i = 0; i < numElements; ++i) {
        offsetArray[i] = (offset_t)i;
        keyArray[i] = (key_t)(i + 1); // Unique keys starting from 1

        if (!srand(time(NULL) ^ ((unsigned int)pthread_self() << 16))) {
            logError("Initialization Error", "Failed to seed random number generator");
            break; // Seed failure can't be fixed at runtime
        }
        (*recordArrayPtr)[i].value = (int)(RAND_MIN + rand() % (RAND_MAX - RAND_MIN + 1));
    }

cleanup:
    pthread_mutex_unlock(&dbMutex);
}

// Function to free allocated resources
void freeDatabaseResources(offset_t *offsetArray, key_t *keyArray, record_t *recordArray) {
    if (offsetArray) {
        free(offsetArray);
    }
    if (keyArray) {
        free(keyArray);
    }
    if (recordArray) {
        free(recordArray);
    }
}
