    unsigned char* pool;
    size_t total_blocks;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;
    mp->block_size = block_size;
    mp->total_blocks = num_blocks;
    mp->pool = malloc(block_size * num_blocks);
    pthread_mutex_init(&mp->mutex, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool* mp) {
    if (mp) {
        free(mp->pool);
        pthread_mutex_destroy(&mp->mutex);
        free(mp);
    }
}

void* allocate_from_pool(MemoryPool* mp) {
    pthread_mutex_lock(&mp->mutex);
    void* block = malloc(mp->block_size); // Simulate allocation
    if (block == NULL && mp->total_blocks > 0) {
        block = mp->pool;
        mp->pool += mp->block_size;
        --mp->total_blocks;
    }
    pthread_mutex_unlock(&mp->mutex);
    return block;
}

void deallocate_to_pool(MemoryPool* mp, void* ptr) {
    // Not implemented: typically this would involve adding back to a free list
}

CRCList* create_crc_list(size_t max_entries, double crc_probability) {
    CRCList* cl = malloc(sizeof(CRCList));
    if (!cl) return NULL;
    cl->head = cl->tail = NULL;
    cl->count = 0;
    cl->max_entries = max_entries;
    cl->crc_probability = crc_probability;
    pthread_mutex_init(&cl->lock, NULL);
    return cl;
}

void destroy_crc_list(CRCList* cl) {
    if (cl) {
        Node* current = cl->head;
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
        pthread_mutex_destroy(&cl->lock);
        free(cl);
    }
}

void log_entry(NFAPI_CRC_INDICATION_PDU_T entry, time_t timestamp) {
    printf("Entry ID: %d, CRC Flag: %s, Timestamp: %ld\n",
           entry.id,
           entry.crcFlag ? "True" : "False",
           (long)timestamp);
}

int should_set_crc_flag(double probability) {
    return ((double)rand() / RAND_MAX) < probability;
}

void add_entry(CRCList* cl, NFAPI_CRC_INDICATION_PDU_T new_entry, MemoryPool* mp) {
    pthread_mutex_lock(&cl->lock);

    Node* node = (Node*)allocate_from_pool(mp);
    if (!node) return;

    node->data = new_entry;
    new_entry.crcFlag = should_set_crc_flag(cl->crc_probability);

    log_entry(new_entry, time(NULL));

    if (cl->head == NULL) {
        cl->head = cl->tail = node;
    } else {
        cl->tail->next = node;
        cl->tail = node;
    }

    if (++(cl->count) > cl->max_entries) {
        Node* oldest = cl->head;
        cl->head = cl->head->next;
        free(oldest);
        --(cl->count);
    }

    pthread_mutex_unlock(&cl->lock);
}

size_t get_entry_count(CRCList* cl) {
    size_t count;
    pthread_mutex_lock(&cl->lock);
    count = cl->count;
    pthread_mutex_unlock(&cl->lock);
    return count;
}
