#define MAX_IMAGES 1024
#define BUFFER_SIZE 256

typedef struct {
    char *filePath;
    char *reportData;
    char *uniqueIdentifier;
} ImageRecord;

typedef struct {
    ImageRecord *images;
    size_t count;
    pthread_mutex_t lock; // For thread safety
} BatchProcessor;

// Function prototypes
BatchProcessor* createBatchProcessor(size_t initialSize);
void destroyBatchProcessor(BatchProcessor *processor);
int processImage(const char *filePath, ImageRecord *record);
void logMessage(const char *message);
char* generateUniqueIdentifier();
struct stat getFileInfo(const char *path);

// Main function to handle batch processing
void batchProcessImagesAndGenerateReport(char **filePaths, size_t numFiles) {
    pthread_mutex_init(&processor.lock, NULL);

    BatchProcessor *processor = createBatchProcessor(numFiles);
    if (!processor) {
        logMessage("Failed to allocate memory for processor.");
        return;
    }

    int processedCount = 0;

    for (size_t i = 0; i < numFiles; ++i) {
        struct stat fileInfo = getFileInfo(filePaths[i]);
        if (fileInfo.st_size == 0 || !S_ISREG(fileInfo.st_mode)) {
            logMessage("Invalid file.");
            continue;
        }

        pthread_mutex_lock(&processor.lock);
        if (processedCount >= processor->count) {
            // Resize logic here
            size_t newSize = processor->count + numFiles; // Simplistic resizing
            ImageRecord *newImages = realloc(processor->images, newSize * sizeof(ImageRecord));
            if (!newImages) {
                logMessage("Failed to reallocate memory for images.");
                pthread_mutex_unlock(&processor.lock);
                destroyBatchProcessor(processor);
                return;
            }
            processor->images = newImages;
            processor->count = newSize;
        }

        ImageRecord *record = &processor->images[processedCount];
        record->filePath = strdup(filePaths[i]);
        if (!record->filePath) {
            logMessage("Failed to allocate memory for file path.");
            pthread_mutex_unlock(&processor.lock);
            destroyBatchProcessor(processor);
            return;
        }

        if (processImage(record->filePath, record)) {
            processedCount++;
            logMessage("Image processed successfully.");
        } else {
            logMessage("Error processing image.");
        }

        pthread_mutex_unlock(&processor.lock);
    }

    // Ensure all images are processed correctly
    if (processedCount != numFiles) {
        logMessage("Mismatch between input and processed images.");
    }

    destroyBatchProcessor(processor);
    pthread_mutex_destroy(&processor.lock);
}

