#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int x;
    int y;
} point;

typedef struct {
    size_t vertex_count;
    point *vertices;
} polygon;

void log_message(const char *message) {
    // Simple logging function for debugging purposes.
    printf("%s\n", message);
}

polygon* read_polygons_from_csv(const char *filename, size_t max_vertices_per_polygon, size_t *num_polygons) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_message("Error: Could not open file.");
        return NULL;
    }

    polygon *polygons = NULL;
    size_t allocated_size = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Skip empty lines and comments
        if (line[0] == '\n' || line[0] == '#') continue;

        // Ensure enough space for a new polygon
        size_t current_size = allocated_size;
        if (current_size == 0) {
            polygons = malloc(sizeof(polygon));
            if (!polygons) {
                log_message("Error: Memory allocation failed.");
                fclose(file);
                return NULL;
            }
            allocated_size++;
        } else {
            polygons = realloc(polygons, sizeof(polygon) * (allocated_size + 1));
            if (!polygons) {
                log_message("Error: Memory allocation failed during resizing.");
                fclose(file);
                return NULL;
            }
            allocated_size++;
        }

        polygon *current_polygon = &polygons[allocated_size - 1];
        current_polygon->vertex_count = 0;

        char *token = strtok(line, ",");
        while (token && current_polygon->vertex_count < max_vertices_per_polygon) {
            int x = atoi(token);
            token = strtok(NULL, ",");
            if (!token) break;
            int y = atoi(token);
            token = strtok(NULL, ",");

            // Ensure enough space for new vertices
            size_t vertex_size = current_polygon->vertex_count + 1;
            point *vertices = realloc(current_polygon->vertices, sizeof(point) * vertex_size);
            if (!vertices && current_polygon->vertices) {
                log_message("Error: Memory allocation failed during resizing vertices.");
                free(polygons[allocated_size - 1].vertices);
                fclose(file);
                return NULL;
            }
            current_polygon->vertices = vertices;

            point new_point = {x, y};
            current_polygon->vertices[current_polygon->vertex_count] = new_point;
            current_polygon->vertex_count++;
        }

        if (current_polygon->vertex_count == 0) {
            // If no valid data was found for the polygon, remove it.
            free(current_polygon->vertices);
            allocated_size--;
            polygons = realloc(polygons, sizeof(polygon) * allocated_size);
        }
    }

    fclose(file);

    *num_polygons = allocated_size;
    log_message("Successfully read polygons from CSV.");
    return polygons;
}

void free_polygons(polygon *polygons, size_t num_polygons) {
    for (size_t i = 0; i < num_polygons; i++) {
        free(polygons[i].vertices);
    }
    free(polygons);
}
