    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->probability = probability;
}

// Destroy the node list and free memory
void destroy_node_list(NodeList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

// Add a new PDU to the list
void add_pdu(NodeList* list, NFAPI_CRC_INDICATION_PDU_T pdu, SensorData sensor_data) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data.valid_RX_UE_INFORMATION_TAG = 1; // Assuming valid
    new_node->data.RNTI = rand() % 1000;
    new_node->data.CRC_INDICATION_REL8_TAG = (rand() % 100) < list->probability;

    new_node->sensor_data = sensor_data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Refresh sensor data at regular intervals
void refresh_sensor_data(NodeList* list) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        // Simulate fetching fresh sensor data
        current->sensor_data.temperature += 0.5; // Example update
        current->sensor_data.humidity += 1.0;     // Example update
        time(&current->sensor_data.timestamp);

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

// Compute and print the average of floating-point numbers in sensor data
void compute_and_print_average(NodeList* list) {
    float sum_temperature = 0.0, sum_humidity = 0.0;
    int count = 0;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->sensor_data.temperature >= -50 && current->sensor_data.temperature <= 50) { // Example range
            sum_temperature += current->sensor_data.temperature;
        }

        if (current->sensor_data.humidity >= 0 && current->sensor_data.humidity <= 100) { // Example range
            sum_humidity += current->sensor_data.humidity;
        }

        count++;
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    if (count > 0) {
        printf("Average Temperature: %.2f\n", sum_temperature / count);
        printf("Average Humidity: %.2f\n", sum_humidity / count);
    } else {
        printf("No valid data to compute average.\n");
    }
}

// Handle network latency issues
void* handle_latency(void* arg) {
    NodeList* list = (NodeList*)arg;

    while (1) {
        // Simulate checking for high-latency conditions and handling them
        sleep(5); // Check every 5 seconds

        pthread_mutex_lock(&list->lock);
        Node* current = list->head;

        while (current != NULL) {
            // Example mitigation strategy: Log or adjust data
            if ((time(NULL) - current->sensor_data.timestamp) > 10) { // 10 seconds threshold
                printf("High latency detected for node with RNTI %d\n", current->data.RNTI);
                // Implement your mitigation logic here
            }
            current = current->next;
        }

        pthread_mutex_unlock(&list->lock);
    }
    return NULL;
}

int main() {
