    int size;
    int max_entries;
    pthread_rwlock_t lock;
    // Additional fields for health check, resource monitoring...
} LRUCache;

LRUCache* create_cache(int max_entries) {
    LRUCache* cache = (LRUCACHE*)malloc(sizeof(LRUCACHE));
    cache->head = cache->tail = NULL;
    cache->size = 0;
    cache->max_entries = max_entries;
    pthread_rwlock_init(&cache->lock, NULL);
    // Initialize health check and resource monitor...
    return cache;
}

void set_crc_flag_policy(LRUCache* cache) {
    // Implement dynamic CRCFLAG setting based on network traffic and load.
}

void log_anomaly(const char* message) {
    printf("Anomaly: %s\n", message);
    // Extend to log into a file or monitoring system...
}

void evict_if_needed(LRUCache* cache) {
    pthread_rwlock_wrlock(&cache->lock);
    if (cache->size >= cache->max_entries) {
        Node* old = cache->head;
        if (old != NULL) {
            cache->head = old->next;
            if (cache->head == NULL)
                cache->tail = NULL;
            else
                cache->head->prev = NULL;
            // Evict to secondary storage or free memory...
            free(old);
            cache->size--;
        }
    }
    pthread_rwlock_unlock(&cache->lock);
}

void insert_entry(LRUCache* cache, NFAPI_CRC_INDICATION_PDU_T entry) {
    set_crc_flag_policy(cache);

    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = entry;
    new_node->lastUsed = time(NULL);
    new_node->next = NULL;

    pthread_rwlock_wrlock(&cache->lock);
    if (cache->tail == NULL) {
        cache->head = cache->tail = new_node;
    } else {
        cache->tail->next = new_node;
        new_node->prev = cache->tail;
        cache->tail = new_node;
    }
    evict_if_needed(cache);
    pthread_rwlock_unlock(&cache->lock);

    // Health check...
}

NFAPI_CRC_INDICATION_PDU_T* get_entry(LRUCache* cache, int index) {
    pthread_rwlock_rdlock(&cache->lock);
    Node* current = cache->head;
    for (int i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }
    if (current == NULL) {
        pthread_rwlock_unlock(&cache->lock);
        return NULL;
    }
    current->lastUsed = time(NULL); // Update last used
    NFAPI_CRC_INDICATION_PDU_T* entry = &current->data;

    pthread_rwlock_unlock(&cache->lock);
    return entry;
}

int get_entry_count(LRUCache* cache) {
    pthread_rwlock_rdlock(&cache->lock);
    int count = cache->size;
    pthread_rwlock_unlock(&cache->lock);
    return count;
}

void update_max_entries(LRUCache* cache, int new_max) {
    pthread_rwlock_wrlock(&cache->lock);
    if (new_max < cache->size) {
        evict_if_needed(cache);
    }
    cache->max_entries = new_max;
    pthread_rwlock_unlock(&cache->lock);
}

void serialize_cache_state(LRUCache* cache, const char* filename) {
    pthread_rwlock_rdlock(&cache->lock);
    FILE* file = fopen(filename, "w");
    if (file != NULL) {
        Node* current = cache->head;
        while (current != NULL) {
            // Serialize node data...
            fprintf(file, "%d\n", current->data.crcFlag); // Example serialization
            current = current->next;
        }
        fclose(file);
    }
    pthread_rwlock_unlock(&cache->lock);
}

void deserialize_cache_state(LRUCache* cache, const char* filename) {
    pthread_rwlock_wrlock(&cache->lock);
    FILE* file = fopen(filename, "r");
    if (file != NULL) {
        while (!feof(file)) {
            NFAPI_CRC_INDICATION_PDU_T entry;
            // Deserialize node data...
            fscanf(file, "%d", &entry.crcFlag); // Example deserialization
            insert_entry(cache, entry);
        }
        fclose(file);
    }
    pthread_rwlock_unlock(&cache->lock);
}

void cleanup_cache(LRUCache* cache) {
    pthread_rwlock_wrlock(&cache->lock);
    Node* current = cache->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_rwlock_unlock(&cache->lock);
    pthread_rwlock_destroy(&cache->lock);
    free(cache);
}

int main() {
