#define MAX_OFFSETS 10000
#define MAX_KEYS 5000
#define STRING_SIZE 128

typedef struct {
    char string[STRING_SIZE];
    long offset;
    int key;
} record;

int generate_random_key(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record* initialize_records(bool use_calloc) {
    srand(time(NULL));

    // Calculate potential memory usage
    size_t total_size = sizeof(record) * MAX_OFFSETS;
    if (!use_calloc) {
        total_size += STRING_SIZE * MAX_OFFSETS;
    }

    // Get system memory info (This is a placeholder, actual implementation may vary)
    // For simplicity, we assume 8GB of available RAM
    size_t max_memory_usage = 0.8 * 8 * 1024 * 1024 * 1024;

    if (total_size > max_memory_usage) {
        return NULL;
    }

    record* records = use_calloc ? calloc(MAX_OFFSETS, sizeof(record)) : malloc(sizeof(record) * MAX_OFFSETS);
    if (!records) {
        return NULL;
    }

    int unique_keys[MAX_KEYS] = {0};
    int keys_count = 0;

    for (int i = 0; i < MAX_OFFSETS; ++i) {
        records[i].offset = rand();

        int key, collisions = 0;
        do {
            if (collisions++ > MAX_KEYS * 2) {
                free(records);
                return NULL; // Avoid infinite loop on excessive collision
            }
            key = generate_random_key(1, 1000000); // Example range
        } while (!unique_keys[key % MAX_KEYS]);

        records[i].key = key;
        unique_keys[key % MAX_KEYS] = 1;

        if (keys_count < MAX_KEYS) {
            keys_count++;
        }

        if (!use_calloc) {
            char* string_ptr = ((char*)records) + i * STRING_SIZE;
            memset(string_ptr, 'A' + (i % 26), STRING_SIZE - 1);
            string_ptr[STRING_SIZE - 1] = '\0';
            memcpy(records[i].string, string_ptr, STRING_SIZE);
        }
    }

    return records;
}

void free_records(record* records) {
    if (!records) return;
    free(records);
}
