int InitializeAndPopulateCCCHMessages(size_t count, size_t max_type) {
    if (count > MAX_MESSAGES) return -1;

    pthread_mutex_lock(&pool.lock);

    if (pool.count + count > pool.messages ? sizeof(pool.messages) / sizeof(LTE_DL_CCCH_Message_Type1_T) : 0) {
        LogError("Resource pool overflow");
        pthread_mutex_unlock(&pool.lock);
        return -1;
    }

