    printf("%s\n", message);
}

// Function to generate a random CRCFLAG
int generate_random_crcflag() {
    return rand() % 2; // Generates either 0 or 1
}

// Thread-safe initialization and population of the list
NFAPI_CRC_INDICATION_PDU_T* init_nfa_pdu_list(int n, int* success_count) {
    pthread_mutex_lock(&lock); // Ensure thread safety

    if (n > MAX_ENTRIES) {
        log_message("Requested number exceeds maximum allowable entries");
        *success_count = 0;
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!list) {
        log_message("Memory allocation failed");
        *success_count = 0;
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int valid_entries = 0;
    for (int i = 0; i < n; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag
        list[i].RNTI = rand() % 1000;                   // Example RNTI
        list[i].CRC_INDICATION_REL8_TAG = rand() % 100; // Example CRC tag
        list[i].CRCFLAG = generate_random_crcflag();

        if (list[i].RX_UE_INFORMATION_TAG > 0 && 
            list[i].RNTI > 0 && 
            list[i].CRC_INDICATION_REL8_TAG > 0) {
            valid_entries++;
        } else {
            log_message("Invalid entry generated, retrying");
            i--; // Retry this iteration
        }
    }

    *success_count = valid_entries;
    log_message("Successfully initialized NFAPI_CRC_INDICATION_PDU_T list");

    pthread_mutex_unlock(&lock); // Release lock after operation
    return list;
}

// Example usage function to demonstrate the call and cleanup
void example_usage() {
    int success_count = 0;
    int n = 100; // Number of entries you want to initialize

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = init_nfa_pdu_list(n, &success_count);

    if (pdu_list) {
        log_message("PDU list successfully created");
        printf("Successful Entries: %d\n", success_count);

        free(pdu_list); // Free the allocated memory
    } else {
        log_message("Failed to create PDU list");
    }
}

int main() {
    srand(time(NULL));  // Seed random number generator

    example_usage();    // Demonstrate usage of the function

    return 0;
}
