#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_HISTORY 1000
#define MIN_VALUE 1
#define MAX_VALUE 10000

typedef enum {
    INSERT,
    UPDATE,
    DELETE
} EventType;

typedef struct {
    int value;
    char str_value[12]; // Enough to hold INT_MAX in decimal + '\0'
    time_t timestamp;
    EventType event_type;
} Record;

typedef struct {
    Record *records;
    int *keys;
    time_t *timestamps;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    FILE *log_file;
} DataProcessingModule;

int compare_timestamps(const void *a, const void *b) {
    return (*(time_t *)a - *(time_t *)b);
}

void log_event(FILE *log_file, Record *record) {
    fprintf(log_file, "Timestamp: %ld, Value: %d, Event: %d\n",
            record->timestamp, record->value, record->event_type);
}

DataProcessingModule* initialize_module(size_t initial_capacity) {
    DataProcessingModule *module = malloc(sizeof(DataProcessingModule));
    if (!module) return NULL;

    module->records = calloc(initial_capacity, sizeof(Record));
    module->keys = calloc(initial_capacity, sizeof(int));
    module->timestamps = calloc(initial_capacity, sizeof(time_t));

    if (!module->records || !module->keys || !module->timestamps) {
        free(module->records);
        free(module->keys);
        free(module->timestamps);
        free(module);
        return NULL;
    }

    module->count = 0;
    module->capacity = initial_capacity;
    pthread_mutex_init(&module->lock, NULL);

    if (!(module->log_file = fopen("log.txt", "a"))) {
        pthread_mutex_destroy(&module->lock);
        free(module->records);
        free(module->keys);
        free(module->timestamps);
        free(module);
        return NULL;
    }

    return module;
}

int add_record(DataProcessingModule *module, EventType event_type) {
    pthread_mutex_lock(&module->lock);

    if (module->count == module->capacity) {
        // Double the capacity
        size_t new_capacity = module->capacity * 2;
        Record *new_records = realloc(module->records, new_capacity * sizeof(Record));
        int *new_keys = realloc(module->keys, new_capacity * sizeof(int));
        time_t *new_timestamps = realloc(module->timestamps, new_capacity * sizeof(time_t));

        if (!new_records || !new_keys || !new_timestamps) {
            pthread_mutex_unlock(&module->lock);
            return -1;
        }

        module->records = new_records;
        module->keys = new_keys;
        module->timestamps = new_timestamps;
        module->capacity = new_capacity;
    }

    Record *record = &module->records[module->count];
    record->value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    snprintf(record->str_value, sizeof(record->str_value), "%d", record->value);
    record->timestamp = time(NULL);
    record->event_type = event_type;

    module->keys[module->count] = module->count; // Example key
    module->timestamps[module->count] = record->timestamp;
    log_event(module->log_file, record);

    if (module->count > 0) {
        qsort(module->timestamps, module->count + 1, sizeof(time_t), compare_timestamps);
    }

    if (++module->count > MAX_HISTORY) {
        // Shift all elements by one to discard the oldest
        memmove(module->records, module->records + 1, (--module->count) * sizeof(Record));
        memmove(module->keys, module->keys + 1, (module->count) * sizeof(int));
        memmove(module->timestamps, module->timestamps + 1, (module->count) * sizeof(time_t));
    }

    pthread_mutex_unlock(&module->lock);
    return 0;
}

void free_module(DataProcessingModule *module) {
    if (!module) return;

    pthread_mutex_lock(&module->lock);
    fclose(module->log_file);

    free(module->records);
    free(module->keys);
    free(module->timestamps);

    pthread_mutex_unlock(&module->lock);
    pthread_mutex_destroy(&module->lock);
    free(module);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    DataProcessingModule *module = initialize_module(10);
    if (!module) {
        fprintf(stderr, "Failed to initialize module\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 20; ++i) {
        add_record(module, INSERT + (rand() % 3));
    }

    free_module(module);

    return EXIT_SUCCESS;
}
