    NFAPI_CRC_INDICATION_PDU_T **last_ptr = &head;

    pthread_mutex_lock(&list_lock);

    for (int i = 0; i < n; ++i) {
        // Throttling mechanism
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_nsec += THROTTLE_RATE * 1000;
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR);

        NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node) {
            log_allocation_failure(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&list_lock);
            return NULL;
        }

        // Populate the node
        node->rx_ue_information_tag = rand() % 1000; // Example value
        node->rnti = rand() % 500; // Example value

        int context_id = get_UE_context(node->rnti);
        if (context_id == -1 || !verify_UE_context(context_id)) {
            if (invalid_cb) invalid_cb(node->rnti);
            free(node);
            pthread_mutex_unlock(&list_lock);
            return NULL;
        }

        node->crc_indication_rel8_tag = context_id; // Mock association
        node->crcflag = rand() % 2;

        *last_ptr = node;
        last_ptr = &node->next;

        log_allocation_success(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1) > max_memory_usage) {
            // Cleanup in case of memory threshold breach
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T *temp = head;
                head = head->next;
                free(temp);
            }
            pthread_mutex_unlock(&list_lock);
            return NULL;
        }
    }

    pthread_mutex_unlock(&list_lock);

    // Optional compression step
    if (compression_enabled) {
        // Implement compression logic here
    }

    return head;
}

void log_allocation_success(size_t size) {
    printf("Allocation success: %zu bytes\n", size);
}

void log_allocation_failure(size_t size) {
    fprintf(stderr, "Allocation failure: %zu bytes\n", size);
}

// Example usage
int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T* list = create_nfa_crc_indication_list(10, MAX_MEMORY_USAGE, 
                                                                       NULL, 0);

    // Free the list
    while (list != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = list;
        list = list->next;
        free(temp);
    }

    return 0;
}
