} DynamicList;

void initialize_dynamic_list(DynamicList *list) {
    list->size = 0;
    list->capacity = 1024; // Start with a small capacity to minimize initial memory usage
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    if (!list->elements) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
}

void expand_dynamic_list(DynamicList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (!new_elements) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    list->elements = new_elements;
    list->capacity = new_capacity;
}

void add_crc_indication_pdu(DynamicList *list, int rx_ue_tag, int rnti, int crc_rel8_tag) {
    time_t start_time = time(NULL);

    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        expand_dynamic_list(list);
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &list->elements[list->size];
    element->RX_UE_INFORMATION_TAG = rx_ue_tag;
    element->RNTI = rnti;
    element->CRC_INDICATION_REL8_TAG = crc_rel8_tag;
    element->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    list->size++;

    pthread_mutex_unlock(&list->lock);

    if (time(NULL) - start_time > 0.01) { // Check if time limit exceeded
        FILE *log_file = fopen("time_limit_exceeded.log", "a");
        if (log_file) {
            fprintf(log_file, "Time limit exceeded for adding CRC indication PDU\n");
            fclose(log_file);
        }
    }
}

void free_dynamic_list(DynamicList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->elements);
    list->elements = NULL;
    list->size = 0;
    list->capacity = 0;
}

