typedef struct {
    unsigned int SN;
} RLC_PDU;

typedef struct {
    unsigned long RNTI;
    unsigned int TX_UE_INFORMATION_TAG;
} NFAPI_RLC_PDU_T;

struct Node {
    NFAPI_RLC_PDU_T data;
    struct Node* prev;
    struct Node* next;
};

typedef struct {
    struct Node* head;
    struct Node* tail;
    size_t node_size;
} DoublyLinkedList;

DoublyLinkedList* create_list(size_t node_size) {
    DoublyLinkedList* list = malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->node_size = node_size;
    return list;
}

int add_node(DoublyLinkedList* list, NFAPI_RLC_PDU_T data) {
    struct Node* new_node = malloc(list->node_size);
    if (!new_node) return -1;

    * (NFAPI_RLC_PDU_T*) new_node = data;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail)
        list->tail->next = new_node;
    else
        list->head = new_node;

    list->tail = new_node;
    return 0;
}

void free_list(DoublyLinkedList* list) {
    struct Node* current = list->head;
    while (current) {
        struct Node* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int manage_nfa_pi_rlc_pdu(int N, int M, size_t B) {
