    unsigned long rnti_counter = 0;
    size_t total_memory_used = sizeof(DoublyLinkedList);

    for (int i = 0; i < N; ++i) {
        if ((total_memory_used + list->node_size) > B) break;

        struct Node* new_node = malloc(list->node_size);
        if (!new_node) {
            free_list(list);
            return -1;
