        pdu->SN = i % M + 1; // Ensure SN is within [1, M]

        int result = add_node(list, data);
        if (result == -1) {
            free(new_node);
            free_list(list);
            return -1;
        }
    }

    struct Node* current = list->head;
    while (current) {
        NFAPI_RLC_PDU_T* data = &current->data;
        printf("RNTI: %lu, SN: %u, TX_UE_INFORMATION_TAG: %u\n",
               data->RNTI, ((RLC_PDU*) &(data->RLC_PDU))->SN, data->TX_UE_INFORMATION_TAG);
        current = current->next;
    }

    free_list(list);
    return 0;
}

int main() {
