```javascript
/**
 * Efficiently copies a specified number of bytes from buffered data chunks into a new buffer.
 * @param {Buffer[]} dataChunks - Array of Buffer objects representing the data chunks.
 * @param {number} numBytes - The number of bytes to copy.
 * @returns {Buffer} A new Buffer containing the copied bytes.
 */
function copyBufferData(dataChunks, numBytes) {
    const result = Buffer.allocUnsafe(numBytes);
    let totalCopied = 0;

    for (const chunk of dataChunks) {
        if (totalCopied >= numBytes) break;

        const remaining = numBytes - totalCopied;
        const bytesToCopy = Math.min(chunk.length, remaining);

        chunk.copy(result, totalCopied, 0, bytesToCopy);
        totalCopied += bytesToCopy;

        if (totalCopied === numBytes) break;
    }

    return result.slice(0, numBytes); // Trim any excess in case of over-estimation
}
