#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_OFFSETS 10000
#define MAX_KEYS 5000
#define STRING_MAX_LENGTH 256

typedef struct Record {
    int key;
    char *value;
    struct Record *next;
} Record;

typedef struct {
    Record **records;
    size_t count;
    size_t capacity;
} RecordList;

RecordList* init_record_list(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    RecordList *list = malloc(sizeof(RecordList));
    list->records = calloc(initial_capacity, sizeof(Record *));
    list->count = 0;
    list->capacity = initial_capacity;

    return list;
}

void free_record_list(RecordList *list) {
    if (list == NULL) return;

    for (size_t i = 0; i < list->count; ++i) {
        Record *record = list->records[i];
        free(record->value);
        free(record);
    }
    free(list->records);
    free(list);
}

void resize_record_list(RecordList *list, size_t new_capacity) {
    if (new_capacity <= list->capacity) return;

    Record **new_records = realloc(list->records, new_capacity * sizeof(Record *));
    if (!new_records) {
        perror("Failed to resize record list");
        exit(EXIT_FAILURE);
    }

    memset(new_records + list->count, 0, (new_capacity - list->count) * sizeof(Record *));
    list->records = new_records;
    list->capacity = new_capacity;
}

int insert_record(RecordList *list, int key, const char *value) {
    if (key < 0 || key >= MAX_KEYS) return -1;

    if (list->count == list->capacity) {
        resize_record_list(list, list->capacity * 2);
    }

    Record *record = malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate record");
        exit(EXIT_FAILURE);
    }

    record->key = key;
    record->value = strdup(value);
    if (!record->value) {
        free(record);
        perror("Failed to duplicate string value");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < list->capacity; ++i) {
        if (list->records[i] == NULL) {
            list->records[i] = record;
            break;
        }
    }

    ++list->count;
    return 0;
}

int delete_record(RecordList *list, int key) {
    if (key < 0 || key >= MAX_KEYS) return -1;

    for (size_t i = 0; i < list->capacity; ++i) {
        Record *record = list->records[i];
        if (record && record->key == key) {
            free(record->value);
            free(record);
            list->records[i] = NULL;
            --list->count;

            // Compact the records to avoid fragmentation
            for (size_t j = i; j < list->capacity - 1; ++j) {
                if (list->records[j + 1] != NULL) {
                    list->records[j] = list->records[j + 1];
                    list->records[j + 1] = NULL;
                } else {
                    break;
                }
            }

            return 0;
        }
    }

    return -1;
}

void iterate_records(RecordList *list, void (*callback)(int key, const char* value)) {
    for (size_t i = 0; i < list->capacity; ++i) {
        Record *record = list->records[i];
        if (record && callback) {
            callback(record->key, record->value);
        }
    }
}

void example_callback(int key, const char* value) {
    printf("Key: %d, Value: %s\n", key, value);
}

int main() {
    RecordList *list = init_record_list(10);

    insert_record(list, 1, "Hello");
    insert_record(list, 2, "World");

    iterate_records(list, example_callback);

    delete_record(list, 1);

    iterate_records(list, example_callback);

    free_record_list(list);
    return 0;
}
