#define MAX_TIMESTAMP 10000

typedef struct {
    time_t timestamp;
    double value;
    int is_valid;
} DataPoint;

double calculate_mean(double* values, size_t count) {
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += values[i];
    }
    return sum / count;
}

double calculate_std_deviation(double* values, size_t count, double mean) {
    double variance = 0.0;
    for (size_t i = 0; i < count; ++i) {
        variance += pow(values[i] - mean, 2);
    }
    return sqrt(variance / count);
}

DataPoint* generate_data_points(double* values, size_t count, time_t start_time) {
    DataPoint* data_points = (DataPoint*)malloc(count * sizeof(DataPoint));
    if (!data_points) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        time_t current_time = start_time + ((long)(ts.tv_nsec / 1e6));
        data_points[i].timestamp = current_time % MAX_TIMESTAMP;
        data_points[i].value = values[i];
        data_points[i].is_valid = (values[i] >= -1000.0 && values[i] <= 1000.0);
    }

    return data_points;
}

int main() {
    double value;
    size_t count = 0;
    double* valid_values = NULL;

    // Initial memory allocation for up to 1024 values
    size_t capacity = 1024;
    valid_values = (double*)malloc(capacity * sizeof(double));
    if (!valid_values) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    while (scanf("%lf", &value) == 1) {
        if (value >= -1000.0 && value <= 1000.0) {
            if (count == capacity) {
                capacity *= 2;
                valid_values = (double*)realloc(valid_values, capacity * sizeof(double));
                if (!valid_values) {
                    fprintf(stderr, "Memory reallocation failed\n");
                    return EXIT_FAILURE;
                }
            }
            valid_values[count++] = value;
        } else {
            printf("Value out of range: %f\n", value);
