            current_size *= 2;
            NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(array, current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_array) {
                free(array);
                *error_code = 1; // Memory allocation error
                return NULL;
            }
            array = new_array;
        }

