            rtis[allocated_count] = true;

            valid_entry = true;  // In real use case, additional validation logic might be required here.
        }

        array[allocated_count++] = entry;
    }

    if (current_size > MAX_SIZE) {
        free(array);
        *error_code = 2; // Maximum size exceeded
        return NULL;
    }

    return array;
}

