#define MAX_RANGE 1000

typedef struct {
    int rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Record {
    int value;
    pthread_mutex_t lock;
} Record;

typedef struct DataStore {
    long *offsets;
    int *keys;
    Record **records;
    int num_elements;
    pthread_mutex_t mutex;
} DataStore;

int generate_unique_int(int min, int max, int *used) {
    int val = rand() % (max - min + 1) + min;
    while (used[val] != 0) {
        val = rand() % (max - min + 1) + min;
    }
    used[val] = 1;
    return val;
}

void free_data_store(DataStore *store) {
    pthread_mutex_lock(&store->mutex);
    if (store->offsets) free(store->offsets);
    if (store->keys) free(store->keys);
    for (int i = 0; i < store->num_elements; ++i) {
        if (store->records[i]) {
            pthread_mutex_destroy(&store->records[i]->lock);
            free(store->records[i]);
        }
    }
    if (store->records) free(store->records);
    pthread_mutex_unlock(&store->mutex);
}

int process_input(DataStore *store, int argc, char *argv[]) {
    pthread_mutex_lock(&store->mutex);
    store->num_elements = argc - 1;
    store->offsets = malloc(sizeof(long) * store->num_elements);
    store->keys = malloc(sizeof(int) * store->num_elements);
    store->records = malloc(sizeof(Record *) * store->num_elements);

    int used[MAX_RANGE + 1] = {0};
    for (int i = 0; i < store->num_elements; ++i) {
        int value;
        if (sscanf(argv[i + 1], "%d", &value) != 1 || value < 0 || value > MAX_RANGE) {
            free_data_store(store);
            pthread_mutex_unlock(&store->mutex);
            return -1;
        }
        if (used[value] != 0) {
            free_data_store(store);
            pthread_mutex_unlock(&store->mutex);
            return -1;
        }
        used[value] = 1;

        store->offsets[i] = i; // Example offset assignment
        store->keys[i] = generate_unique_int(0, MAX_RANGE, used);

        Record *record = malloc(sizeof(Record));
        pthread_mutex_init(&record->lock, NULL);
        record->value = value;
        store->records[i] = record;
    }
    pthread_mutex_unlock(&store->mutex);
    return 0;
}

int find_largest_value(DataStore *store) {
    int max_val = -1;
    pthread_mutex_lock(&store->mutex);
    for (int i = 0; i < store->num_elements; ++i) {
        Record *record = store->records[i];
        pthread_mutex_lock(&record->lock);
        if (record->value > max_val) {
            max_val = record->value;
        }
        pthread_mutex_unlock(&record->lock);
    }
    pthread_mutex_unlock(&store->mutex);
    printf("Largest value: %d\n", max_val);
    return max_val;
}

void populate_nfaapi_crc_indications(NFAPI_CRC_INDICATION_PDU_T *array, int n) {
    for (int i = 0; i < n; ++i) {
        array[i].rnti = rand() % MAX_RANGE + 1;
        array[i].crcflag = rand() % 2;
    }
}

int main(int argc, char *argv[]) {
    srand(time(NULL));

    DataStore store;
    pthread_mutex_init(&store.mutex, NULL);

    if (process_input(&store, argc, argv) != 0) {
        fprintf(stderr, "Error processing input.\n");
        pthread_mutex_destroy(&store.mutex);
        return -1;
    }

    find_largest_value(&store);

    int n = 10; // Example size
    NFAPI_CRC_INDICATION_PDU_T *indication_array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    populate_nfaapi_crc_indications(indication_array, n);

    free(indication_array);
    free_data_store(&store);
    pthread_mutex_destroy(&store.mutex);

    return 0;
}
