int resolve_dns(const char *hostname, u_char ip_buffer[DNS_BUFFER_SIZE]) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_message("DNS resolution failed");
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        inet_ntop(AF_INET, &(ipv4->sin_addr), (char *)ip_buffer, DNS_BUFFER_SIZE);
        freeaddrinfo(res);
        return 0;
    }

    freeaddrinfo(res);
    log_message("No valid IP found for hostname");
    return -1;
}

int fetch_employee_details(sqlite3 *db, int supervisor_id, char **employee_details) {
    sqlite3_stmt *stmt;
    const char *sql = "SELECT details FROM employees WHERE supervisor_id = ?";
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        log_message("Failed to prepare SQL statement");
        return -1;
    }

    sqlite3_bind_int(stmt, 1, supervisor_id);
    if (sqlite3_step(stmt) == SQLITE_ROW) {
        int col_size = sqlite3_column_bytes(stmt, 0);
        *employee_details = malloc(col_size + 1);
        memcpy(*employee_details, sqlite3_column_text(stmt, 0), col_size);
        (*employee_details)[col_size] = '\0';
    } else {
        log_message("Query execution failed or no data found");
        return -1;
    }

    sqlite3_finalize(stmt);
    return 0;
}

