    *nfaapi_list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*nfaapi_list == NULL) {
        log_message("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return -2; // Error code for memory allocation failure
    }

    srand(time(NULL));  // Seed random number generator

    char *network_interface = NULL;
    int performance_threshold;
    if (fetch_api_config(&network_interface, &performance_threshold) != 0) {
        free(*nfaapi_list);
        pthread_mutex_unlock(&lock);
        return -3; // Error code for API call failure
    }
    free(network_interface);

    u_char ip_buffer[DNS_BUFFER_SIZE];
    if (resolve_dns("example.com", ip_buffer) != 0) {
        free(*nfaapi_list);
        pthread_mutex_unlock(&lock);
        return -4; // Error code for DNS resolution failure
    }

    sqlite3 *db;
    char *errmsg = NULL;
    if (sqlite3_open(DB_CONNECTION_STRING, &db) != SQLITE_OK) {
        log_message("Failed to open database");
        free(*nfaapi_list);
        pthread_mutex_unlock(&lock);
