    char *employee_details = NULL;
    if (fetch_employee_details(db, 12345, &employee_details) != 0) {
        sqlite3_close(db);
        free(*nfaapi_list);
        pthread_mutex_unlock(&lock);
        return -6; // Error code for DB query failure
    }
    free(employee_details);

    sqlite3_close(db);

    for (int i = 0; i < N; ++i) {
