// Function implementations
int populate_dynamic_list(NFAPI_CRC_INDICATION_PDU_T **list, int max_elements) {
    if (!list || max_elements <= 0) return -1;

    srand(time(NULL));
    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*list == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    int count = 0, idx;

    while (count < max_elements) {
        for (idx = 0; idx < count; ++idx) {
            if (!unique_validation(&(*list)[count], &(*list)[0], count)) break;
        }

        if (idx != count) { // Duplicate found
            fprintf(stderr, "Duplicate entry detected.\n");
            continue;
        }

        (*list)[count].rx_ue_information_tag.ue_information_tag = rand() % 100000; 
        (*list)[count].rx_ue_information_tag.rnti = rand() % 65535;
        (*list)[count].crc_indication_rel8_tag.CRCFLAG = rand() & 1;

        count++;
    }

    return count; // Return the number of elements populated
}

int unique_validation(NFAPI_CRC_INDICATION_PDU_T *entry, NFAPI_CRC_INDICATION_PDU_T *existing_list, int existing_count) {
    for (int i = 0; i < existing_count; ++i) {
        if ((existing_list[i].rx_ue_information_tag.ue_information_tag == entry->rx_ue_information_tag.ue_information_tag) &&
            (existing_list[i].rnti == entry->rnti)) {
            return 0;
        }
    }
    return 1;
}

int serialize_to_file(const char *file_path, const NFAPI_CRC_INDICATION_PDU_T *list, int list_size) {
    if (!list || !file_path) return -1;

    FILE *file = fopen(file_path, "wb");
    if (!file) {
        perror("File open failed");
        return -1;
    }

    if (fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), list_size, file) != list_size) {
        fprintf(stderr, "Serialization error.\n");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int deserialize_from_file(const char *file_path, NFAPI_CRC_INDICATION_PDU_T **list, int *list_size) {
    if (!file_path || !list || !list_size) return -1;

    FILE *file = fopen(file_path, "rb");
    if (!file) {
        perror("File open failed");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    int size = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    rewind(file);

    *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*list == NULL) {
        perror("Memory allocation failed");
        fclose(file);
        return -1;
    }

    if (fread(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file) != size) {
        fprintf(stderr, "Deserialization error.\n");
        free(*list);
        fclose(file);
        return -1;
    }

    *list_size = size;
    fclose(file);
    return 0;
}
