}

int validate_parameters(int N, const char* filename) {
    if (N < MIN_N || N > MAX_N) return 0;
    if (filename == NULL || strlen(filename) == 0 || strlen(filename) >= MAX_FILENAME_LENGTH) return 0;
    return 1;
}

void persist_to_file(NFAPI_CRC_INDICATION_PDU_T* structures, int N, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("File opening failed");
        return;
    }
    fwrite(structures, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    fclose(file);
}

void generateAndPersistRxIndications(int N, uint32_t seed, const char* filename) {
    if (!validate_parameters(N, filename)) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structures == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < N; ++i) {
        structures[i].crc_tag.RX_UE_INFORMATION_TAG = thread_safe_random(seed + i);
        structures[i].crc_tag.RNTI = (uint16_t)(thread_safe_random(seed + i * 2) % 65536);
        structures[i].CRCFLAG = (uint8_t)(thread_safe_random(seed + i * 3) % 2);

        log_creation(&structures[i]);
    }

    persist_to_file(structures, N, filename);

    free(structures);
}
