import { Injectable } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { catchError, retry } from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class DialogService {

  constructor(private http: HttpClient) {}

  refreshDialogFields(resourceId: string, url: string): Observable<any> {
    return this.http.get(url).pipe(
      retry(3), // Retry up to 3 times before failing
      catchError(this.handleError('refreshDialogFields', {})) // Provide a fallback value in case of error
    ).subscribe(data => {
      this.updateFields(resourceId, data);
    });
  }

  private updateFields(resourceId: string, data: any) {
    const dialog = document.getElementById(`dialog-${resourceId}`);
    if (dialog) {
      for (const key in data) {
        const field = dialog.querySelector(`[name="${key}"]`);
        if (field) {
          field.value = data[key];
        }
      }
    }
  }

  private handleError<T>(operation = 'operation', result?: T) {
    return (error: any): Observable<T> => {
      console.error(`${operation} failed: ${error.message}`);
      return of(result as T);
    };
  }
}
