#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define BLOCK_STATUS_UNINITIALIZED 0
#define BLOCK_STATUS_INITIALIZED   1
#define BLOCK_STATUS_USED          2
#define BLOCK_STATUS_RELEASED      3
#define BLOCK_STATUS_INVALIDATED   4

typedef struct storage_block {
    size_t block_id;
    unsigned int block_status;
    void *data_ptr;
} storage_block;

typedef struct {
    storage_block *blocks;
    pthread_mutex_t lock;
} StorageManager;

StorageManager* initialize_and_manage_storage_blocks(size_t N) {
    if (N == 0) return NULL;

    StorageManager *manager = malloc(sizeof(StorageManager));
    if (!manager) {
        fprintf(stderr, "Failed to allocate memory for manager\n");
        return NULL;
    }

    manager->blocks = calloc(N, sizeof(storage_block));
    if (!manager->blocks) {
        free(manager);
        fprintf(stderr, "Failed to allocate memory for blocks\n");
        return NULL;
    }

    pthread_mutex_init(&manager->lock, NULL);

    // Initialize blocks
    for (size_t i = 0; i < N; ++i) {
        manager->blocks[i].block_id = i;
        manager->blocks[i].block_status = BLOCK_STATUS_UNINITIALIZED;
        manager->blocks[i].data_ptr = NULL;

        // Simulate data allocation - replace with actual logic as needed
        size_t block_size = 1024; // Example fixed size, adjust as necessary
        void *data_memory = malloc(block_size);
        if (data_memory) {
            manager->blocks[i].data_ptr = data_memory;
            manager->blocks[i].block_status = BLOCK_STATUS_INITIALIZED;
        } else {
            fprintf(stderr, "Failed to allocate memory for block %zu\n", i);
            // Handle allocation failure: rollback or cleanup
            for (size_t j = 0; j < i; ++j) {
                free(manager->blocks[j].data_ptr);
                manager->blocks[j].block_status = BLOCK_STATUS_INVALIDATED;
            }
            free(manager->blocks);
            pthread_mutex_destroy(&manager->lock);
            free(manager);
            return NULL;
        }
    }

    return manager;
}

void mark_block_as_used(StorageManager *manager, size_t block_id) {
    if (!manager || block_id >= N) return;

    pthread_mutex_lock(&manager->lock);
    if (manager->blocks[block_id].block_status == BLOCK_STATUS_INITIALIZED) {
        manager->blocks[block_id].block_status = BLOCK_STATUS_USED;
    }
    pthread_mutex_unlock(&manager->lock);
}

void mark_block_as_released(StorageManager *manager, size_t block_id) {
    if (!manager || block_id >= N) return;

    pthread_mutex_lock(&manager->lock);
    manager->blocks[block_id].block_status = BLOCK_STATUS_RELEASED;
    pthread_mutex_unlock(&manager->lock);
}

void invalidate_block(StorageManager *manager, size_t block_id) {
    if (!manager || block_id >= N) return;

    pthread_mutex_lock(&manager->lock);
    if (manager->blocks[block_id].data_ptr) {
        free(manager->blocks[block_id].data_ptr);
        manager->blocks[block_id].block_status = BLOCK_STATUS_INVALIDATED;
    }
    pthread_mutex_unlock(&manager->lock);
}

void cleanup_storage_manager(StorageManager *manager, size_t N) {
    if (!manager) return;

    for (size_t i = 0; i < N; ++i) {
        invalidate_block(manager, i);
    }

    free(manager->blocks);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    size_t num_blocks = 10;
    StorageManager *manager = initialize_and_manage_storage_blocks(num_blocks);

    if (manager) {
        mark_block_as_used(manager, 5);
        mark_block_as_released(manager, 5);
        invalidate_block(manager, 5);
        cleanup_storage_manager(manager, num_blocks);
    }

    return 0;
}
