int get_tmsi_from_db(unsigned long *tmsi, int attempt) {
    static const unsigned long tmsis[] = {12345, 67890, 24680, 13579}; // Example TMSI values
    if (attempt < sizeof(tmsis) / sizeof(tmsis[0])) {
        *tmsi = tmsis[attempt];
        return 1; // Success
    }
    return 0; // Failure
}

// Generate a unique message payload
void generate_message_payload(char **payload, size_t *size) {
