    *size = strlen(message) + 1;
    *payload = (char *)malloc(*size);
    strcpy(*payload, message);
}

// Function to manage and process NFAPI_UL_CCCH_PDU_T structures
void manage_and_process_pdus(NFAPI_UL_CCCH_PDU_T **pdus, int num_connections) {
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    unsigned long tmsi_set[5000] = {0};
    pthread_t worker_threads[num_connections];
    int thread_count = 4; // Example based on system resources

    for (int i = 0; i < num_connections; ++i) {
        NFAPI_UL_CCCH_PDU_T *pdu = (NFAPI_UL_CCCH_PDU_T *)malloc(sizeof(NFAPI_UL_CCCH_PDU_T));
        if (!pdu) {
            fprintf(stderr, "Memory allocation failed for PDU\n");
            continue;
        }

        int attempt = 0;
        while (attempt < MAX_RETRIES) {
            if (get_tmsi_from_db(&pdu->TMSI, attempt)) {
                break;
            }
            attempt++;
            usleep(RETRY_DELAY_BASE_MS * (1 << attempt) * 1000); // Exponential backoff
        }

        if (attempt == MAX_RETRIES || tmsi_set[pdu->TMSI % 5000]) {
            free(pdu);
            continue;
        }

        pthread_mutex_lock(&mutex);
        tmsi_set[pdu->TMSI % 5000] = pdu->TMSI;
        pthread_mutex_unlock(&mutex);

        generate_message_payload(&pdu->message_payload, NULL);
        snprintf(pdu->CCCH_MESSAGE_TAG, sizeof(pdu->CCCH_MESSAGE_TAG), "Message for TMSI: %lu", pdu->TMSI);
        pdus[i] = pdu;

        int thread_index = i % thread_count;
        pthread_create(&worker_threads[thread_index], NULL, (void *(*)(void *))process_ccch_message_worker, pdu);
    }

    for (int i = 0; i < thread_count; ++i) {
        pthread_join(worker_threads[i], NULL);
    }
}

// Worker function to process CCCH messages
void *process_ccch_message_worker(void *arg) {
    NFAPI_UL_CCCH_PDU_T *pdu = (NFAPI_UL_CCCH_PDU_T *)arg;
    process_ccch_message(pdu);

    // Free dynamically allocated memory
    free(pdu->message_payload);
    free(pdu);

    return NULL;
}

