    size_t new_capacity = manager->capacity ? (manager->capacity * 2) : 16;
    NFAPI_CRC_INDICATION_PDU_T* resized_array =
        realloc(manager->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);

