#define MAX_MAC_COMMANDS 1000
#define MAX_CONTEXTS 10000

typedef struct {
    // Define LMAC_CONFIG structure
} LMAC_CONFIG;

typedef struct {
    // Define MAC_COMMAND structure
} MAC_COMMAND;

typedef struct {
    LMAC_CONFIG lmac_config;
    MAC_COMMAND mac_commands[MAX_MAC_COMMANDS];
    size_t num_commands;
    pthread_mutex_t lock;
} MAC_CONTEXT_T;

typedef struct {
    MAC_CONTEXT_T* contexts[MAX_CONTEXTS];
    size_t count;
    pthread_mutex_t array_lock;
} MAC_CONTEXT_ARRAY;

MAC_CONTEXT_ARRAY* create_context_array() {
    MAC_CONTEXT_ARRAY* array = malloc(sizeof(MAC_CONTEXT_ARRAY));
    if (array) {
        memset(array->contexts, 0, sizeof(array->contexts));
        array->count = 0;
        pthread_mutex_init(&array->array_lock, NULL);
    }
    return array;
}

MAC_CONTEXT_T* create_context() {
    MAC_CONTEXT_T* context = malloc(sizeof(MAC_CONTEXT_T));
    if (context) {
        memset(context->mac_commands, 0, sizeof(context->mac_commands));
        context->num_commands = 0;
        pthread_mutex_init(&context->lock, NULL);
    }
    return context;
}

void free_context(MAC_CONTEXT_T* context) {
    if (context) {
        pthread_mutex_destroy(&context->lock);
        free(context);
    }
}

int add_context(MAC_CONTEXT_ARRAY* array, MAC_CONTEXT_T* context) {
    if (!array || !context || array->count >= MAX_CONTEXTS)
        return -1;

    pthread_mutex_lock(&array->array_lock);
    if (array->count < MAX_CONTEXTS) {
        array->contexts[array->count++] = context;
    }
    pthread_mutex_unlock(&array->array_lock);

    return 0;
}

MAC_CONTEXT_T* get_context(MAC_CONTEXT_ARRAY* array, size_t index) {
    if (!array || index >= array->count)
        return NULL;

    MAC_CONTEXT_T* context = array->contexts[index];
    if (context) {
        pthread_mutex_lock(&context->lock);
    }
    return context;
}

void release_context(MAC_CONTEXT_ARRAY* array, size_t index) {
    if (!array || index >= array->count)
        return;

    pthread_mutex_lock(&array->array_lock);
    MAC_CONTEXT_T* context = array->contexts[index];
    if (context) {
        pthread_mutex_lock(&context->lock);
        free_context(context);
        array->contexts[index] = NULL;
    }
    pthread_mutex_unlock(&array->array_lock);
}

int add_mac_command(MAC_CONTEXT_T* context, const MAC_COMMAND* command) {
    if (!context || context->num_commands >= MAX_MAC_COMMANDS)
        return -1;

    pthread_mutex_lock(&context->lock);
    memcpy(&context->mac_commands[context->num_commands++], command, sizeof(MAC_COMMAND));
    pthread_mutex_unlock(&context->lock);

    return 0;
}

int remove_mac_command(MAC_CONTEXT_T* context, size_t index) {
    if (!context || index >= context->num_commands)
        return -1;

    pthread_mutex_lock(&context->lock);
    memmove(&context->mac_commands[index], &context->mac_commands[index + 1],
            (context->num_commands - index - 1) * sizeof(MAC_COMMAND));
    --context->num_commands;
    pthread_mutex_unlock(&context->lock);

    return 0;
}

void free_context_array(MAC_CONTEXT_ARRAY* array) {
    if (!array)
        return;

    pthread_mutex_lock(&array->array_lock);
    for (size_t i = 0; i < array->count; ++i) {
        free_context(array->contexts[i]);
    }
    pthread_mutex_unlock(&array->array_lock);

    pthread_mutex_destroy(&array->array_lock);
    free(array);
}
```

