#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

#define MAX_RNTI 65535

typedef struct {
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    bool rnti_usage[MAX_RNTI + 1];
    size_t capacity;
} MemoryPool;

uint8_t crcflag_hash(uint16_t rnti, uint32_t seed) {
    return (rnti ^ seed) & 0xFF; // Simple hash function
}

MemoryPool* create_memory_pool(size_t m) {
    MemoryPool *mp = malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool = calloc(m, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    for (int i = 0; i <= MAX_RNTI; ++i)
        mp->rnti_usage[i] = false;

    mp->capacity = m;
    return mp;
}

bool allocate_nfa_pi(MemoryPool *mp, uint16_t rnti, uint32_t seed) {
    if (mp->rnti_usage[rnti]) return false; // RNTI already used

    for (size_t i = 0; i < mp->capacity; ++i) {
        if (!mp->pool[i].RNTI) { // Find an empty slot
            mp->pool[i].RNTI = rnti;
            mp->pool[i].CRC_INDICATION_REL8_TAG = crcflag_hash(rnti, seed);
            mp->rnti_usage[rnti] = true;
            return true;
        }
    }

    return false; // No space left
}

void free_memory_pool(MemoryPool *mp) {
    if (mp) {
        free(mp->pool);
        free(mp);
    }
}

// Example usage with an external data source simulation
int main() {
    size_t m = 10;
    uint32_t seed = 42; // Constant seed for hash function

    MemoryPool *mp = create_memory_pool(m);
    if (!mp) {
        fprintf(stderr, "Failed to create memory pool\n");
        return EXIT_FAILURE;
    }

    // Simulate fetching UE information
    for (uint16_t rnti = 1; rnti <= MAX_RNTI; ++rnti) {
        if (allocate_nfa_pi(mp, rnti, seed)) {
            printf("Allocated RNTI: %u, CRC_INDICATION_REL8_TAG: %u\n", 
                   mp->pool[rnti].RNTI, mp->pool[rnti].CRC_INDICATION_REL8_TAG);
        } else {
            break; // Break if no space or if all RNTIs have been used
        }
    }

    free_memory_pool(mp);
    return EXIT_SUCCESS;
}
