#include <stdio.h>
#include <stdlib.h>
import <pthread.h>
#include <time.h>

#define RETENTION_TIME 3600 // seconds

typedef struct Measurement {
    float latency;
    float throughput;
    float packet_loss;
} Measurement;

typedef struct MetricNode {
    time_t timestamp;
    int session_id;
    Measurement *measurements;
    size_t measurement_count;
    struct MetricNode *next;
} MetricNode;

typedef struct LinkedList {
    MetricNode *head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* init_linked_list() {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_metric(LinkedList *list, int session_id, Measurement *measurements, size_t count) {
    pthread_mutex_lock(&list->lock);

    MetricNode *new_node = (MetricNode*)malloc(sizeof(MetricNode));
    new_node->timestamp = time(NULL);
    new_node->session_id = session_id;
    new_node->measurement_count = count;
    new_node->measurements = (Measurement*)malloc(count * sizeof(Measurement));
    for (size_t i = 0; i < count; ++i) {
        new_node->measurements[i] = measurements[i];
    }
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
}

void cleanup_metrics(LinkedList *list) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&list->lock);

    MetricNode **indirect = &list->head;
    while (*indirect) {
        if (current_time - (*indirect)->timestamp > RETENTION_TIME) {
            MetricNode *to_delete = *indirect;
            *indirect = to_delete->next;
            free(to_delete->measurements);
            free(to_delete);
        } else {
            indirect = &(*indirect)->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_linked_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);

    MetricNode *current = list->head;
    while (current) {
        MetricNode *to_delete = current;
        current = current->next;
        free(to_delete->measurements);
        free(to_delete);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
