    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

// Dynamic List structure with thread safety in mind
typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(DynamicList* list) {
    ListNode* current = list->head;
    while (current) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list) return -1;

    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (!new_node) return -2;

    new_node->data = element;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

int get_element_by_index(DynamicList* list, size_t index, NFAPI_CRC_INDICATION_PDU_T* element) {
    if (!list || !element) return -1;

    ListNode* current = list->head;
    size_t count = 0;

    pthread_mutex_lock(&list->lock);

    while (current && count < index) {
        current = current->next;
        count++;
    }

    pthread_mutex_unlock(&list->lock);

    if (!current) return -2; // Index out of bounds

    *element = current->data;
    return 0; // Success
}

int update_crc_flag(DynamicList* list, size_t index, int new_cflag) {
    if (!list) return -1;

    ListNode* current = list->head;
    size_t count = 0;

    pthread_mutex_lock(&list->lock);

    while (current && count < index) {
        current = current->next;
        count++;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Index out of bounds
    }

    current->data.crc_indication_rel8_tag.CRCFLAG = new_cflag;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

// Function to generate a random CRC flag for demonstration purposes.
int get_random_crc_flag() {
    return rand() % 2; // Randomly returns 0 or 1
}

