    int RNTI;  // Added directly to simplify logic in this example
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t count;
    pthread_mutex_t mutex;
} DynamicList;

// Function prototypes
int add_pdu(DynamicList *list, RX_UE_INFORMATION_TAG rx_info_tag, int rnti);
void free_dynamic_list(DynamicList *list);
unsigned char determine_crc_flag(int rnti);

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) {
        fprintf(stderr, "Memory allocation failed for DynamicList structure.\n");
        return NULL;
    }

    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T array.\n");
        return NULL;
    }

    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

int add_pdu(DynamicList *list, RX_UE_INFORMATION_TAG rx_info_tag, int rnti) {
    if (list->count >= MAX_ELEMENTS) {
        fprintf(stderr, "Maximum capacity reached. Cannot add more elements.\n");
        return -1;  // No room for additional PDUs
    }

    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->elements[list->count];
    pdu->rx_info_tag = rx_info_tag;
    pdu->RNTI = rnti;
    pdu->crc_indication_rel8.CRCFLAG = determine_crc_flag(rnti);

    // Increment the element count
    list->count++;

    pthread_mutex_unlock(&list->mutex);

    return 0;  // Success
}

unsigned char determine_crc_flag(int rnti) {
    // Example condition: CRCFLAG is set if RNTI value is even
    return (rnti % 2 == 0) ? 1 : 0;
}

void free_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);

    free(list->elements);
    list->count = 0;

    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);

    free(list);
}

int main() {
    // Example usage
    DynamicList* pdu_list = create_dynamic_list();
    if (pdu_list == NULL) {
        return EXIT_FAILURE;
    }

    RX_UE_INFORMATION_TAG example_tag;
    int result = add_pdu(pdu_list, example_tag, 1234);
    if (result != 0) {
        fprintf(stderr, "Failed to add PDU.\n");
    }

    // Add additional PDUs as necessary

    free_dynamic_list(pdu_list);

    return EXIT_SUCCESS;
}
