void insert_node(NFAPI_CRC_INDICATION_PDU_T** head, unsigned short rnti, int crcflag);
void free_list(NFAPI_CRC_INDICATION_PDU_T* head);
NFAPI_CRC_INDICATION_PDU_T* find_node_by_rnti(NFAPI_CRC_INDICATION_PDU_T* head, unsigned short rnti);

// Create a new node
NFAPI_CRC_INDICATION_PDU_T* create_node(unsigned short rnti, int crcflag) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_node->RNTI = rnti;
    new_node->CRCFLAG = crcflag;
    new_node->next = NULL;
    return new_node;
}

// Insert a node into the linked list
void insert_node(NFAPI_CRC_INDICATION_PDU_T** head, unsigned short rnti, int crcflag) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(rnti, crcflag);
    new_node->next = *head;
    *head = new_node;
}

// Free the linked list
void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Find a node by RNTI
NFAPI_CRC_INDICATION_PDU_T* find_node_by_rnti(NFAPI_CRC_INDICATION_PDU_T* head, unsigned short rnti) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    while (current != NULL) {
        if (current->RNTI == rnti) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Periodically update the list from an external data source
void periodic_update(NFAPI_CRC_INDICATION_PDU_T** head) {
    // Simulate network latency and data consistency handling
    time_t start_time = time(NULL);

    for (unsigned short rnti = 1; rnti <= 65535; ++rnti) {
        int crcflag = rand() % 2;

        if (*head == NULL || (*head)->RNTI != rnti) {
            insert_node(head, rnti, crcflag);
        } else {
            (*head)->CRCFLAG = crcflag;
        }

        // Simulate a delay for network latency
        while (difftime(time(NULL), start_time) < 0.01) {
            // Busy wait
        }
    }
}

// Initialize random number generator
void init_random() {
    srand((unsigned int)time(NULL));
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    init_random();

    // Example usage: Periodically update the list
    for (int i = 0; i < 5; ++i) {
        periodic_update(&head);
    }

    free_list(head);
    return 0;
}
