int retry_with_backoff(int (*operation)(void), int max_retries) {
    int attempt = 0;
    while (attempt < max_retries) {
        if (operation() == 0) {
            return 0; // Success
        }
        printf("Retry %d failed, backing off...\n", attempt + 1);
        sleep((1 << attempt)); // Exponential backoff
        ++attempt;
    }
    return -1; // Failure after max retries
}

int fetch_rnti_from_rrc_config_service() {
    // Mock function to simulate interaction with an external service.
    static int rnti = 1000;
    if (rnti % 5 == 0) { // Simulate failure on some attempts.
