}

int* process_rrc_ue_identity(RRC_UE_IDENTITY_T *ue_list, size_t ue_count, NFAPI_CRC_INDICATION_PDU_T **pdu_array) {
    if (!ue_list || !pdu_array) return NULL;

    *pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(ue_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pdu_array) {
        perror("Memory allocation failed");
        return NULL;
    }

    pthread_t threads[ue_count];
    size_t thread_count = ue_count;

    for (size_t i = 0; i < thread_count && i < sizeof(threads)/sizeof(pthread_t); ++i) {
        if (!threads[i]) {
            pthread_create(&threads[i], NULL, [](void* arg) -> void* {
                RRC_UE_IDENTITY_T *ue_identity = (RRC_UE_IDENTITY_T *)arg;
                NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

                if (!pdu) {
                    perror("Memory allocation failed");
                    return NULL;
                }

                int success = retry_with_backoff(fetch_rnti_from_rrc_config_service, MAX_RETRIES);
                if (success == 0) {
                    pdu->rnti = fetch_rnti_from_rrc_config_service(); // Assume successful fetch here.
                    pdu->rx_ue_information_tag = ue_identity->rnti;   // Example association.
                    pdu->crc_indication_rel8_tag = rand() % 1000;      // Simulated tag.
