                pthread_mutex_init(&lock, NULL);

                pthread_mutex_lock(&lock);
                *((NFAPI_CRC_INDICATION_PDU_T*)arg) = *pdu; // Store pdu in correct position.
                pthread_mutex_unlock(&lock);

                free(pdu); // Free the temporary storage
                return NULL;
            }, &ue_list[i]);
        }
    }

    for (size_t i = 0; i < thread_count && i < sizeof(threads)/sizeof(pthread_t); ++i) {
        if (threads[i]) {
            pthread_join(threads[i], NULL);
        }
    }

    return *pdu_array;
}

