void freeRecords(record* records, size_t numRecords);

int main() {
    // Configuration parameters (in a real system, these would be fetched from an external source)
    const size_t numRecords = 10;
    const int minKey = 1;
    const int maxKeyRange = 100; // e.g., keys can range from 1 to 100
    const int arraySize = 5;

    record* records = NULL;
    if (initializeRecords(&records, numRecords, minKey, maxKeyRange, arraySize) != 0) {
        fprintf(stderr, "Failed to initialize records.\n");
        return EXIT_FAILURE;
    }

    // Use the initialized records...

    freeRecords(records, numRecords);

    return EXIT_SUCCESS;
}

int initializeRecords(record** records, size_t numRecords, int minKey, int maxKeyRange, int arraySize) {
    if (records == NULL || numRecords == 0 || arraySize <= 0) {
        fprintf(stderr, "Invalid parameters for initializing records.\n");
        return -1;
    }

    *records = (record*)malloc(numRecords * sizeof(record));
    if (*records == NULL) {
        perror("Failed to allocate memory for records");
        return -2;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < numRecords; ++i) {
        int key;
        do {
            key = minKey + rand() % maxKeyRange;
        } while (!isUniqueKey(*records, i, key));

        (*records)[i].key = key;

        // Allocate memory for the integer array
        (*records)[i].intArray = (long*)malloc(arraySize * sizeof(long));
        if ((*records)[i].intArray == NULL) {
            perror("Failed to allocate memory for intArray");
            freeRecords(*records, i); // Free previously allocated records
            return -3;
        }

        // Populate the integer array with random values
        for (int j = 0; j < arraySize; ++j) {
            (*records)[i].intArray[j] = rand() % 100; // Example range [0, 99]
        }
    }

    return 0;
}

void freeRecords(record* records, size_t numRecords) {
    if (records == NULL) {
        return;
    }

    for (size_t i = 0; i < numRecords; ++i) {
        free(records[i].intArray);
    }

    free(records);
}

int isUniqueKey(const record* records, size_t currentIdx, int key) {
    for (size_t i = 0; i < currentIdx; ++i) {
        if (records[i].key == key) {
            return 0;
        }
    }
    return 1;
}
