#define MAX_MESSAGES 10000

typedef struct {
    int UE_ID;
    char *payload;
    size_t payload_size;
    // TLVEncoder is assumed to be a function pointer or similar type for encoding.
    void (*TLVEncode)(const char *, size_t, char *, size_t);
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T *messages;
    int capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} MessageManager;

MessageManager *initialize_manager(int initial_capacity) {
    MessageManager *manager = malloc(sizeof(MessageManager));
    manager->capacity = initial_capacity;
    manager->messages = calloc(initial_capacity, sizeof(NFAPI_MESSAGE_T));
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    return manager;
}

void resize_manager(MessageManager *manager, int new_capacity) {
    pthread_mutex_lock(&manager->lock);
    NFAPI_MESSAGE_T *new_messages = realloc(manager->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
    if (new_messages) {
        manager->messages = new_messages;
        manager->capacity = new_capacity;
    }
    pthread_mutex_unlock(&manager->lock);
}

void add_message(MessageManager *manager, int ue_id, const char *message, size_t message_size) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->capacity; ++i) {
        if (manager->messages[i].UE_ID == 0 || manager->messages[i].UE_ID == ue_id) { // Assume UE_ID 0 means unused
            manager->messages[i].UE_ID = ue_id;
            manager->messages[i].payload_size = message_size;
            manager->messages[i].payload = realloc(manager->messages[i].payload, message_size);
            if (manager->messages[i].payload) {
                memcpy(manager->messages[i].payload, message, message_size);
            }
            pthread_cond_signal(&manager->cond);
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void cleanup_manager(MessageManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->capacity; ++i) {
        free(manager->messages[i].payload);
        manager->messages[i].UE_ID = 0;
    }
    free(manager->messages);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
    free(manager);
}

// Example function for encoding, this should be replaced with the actual implementation
