// Initialize the memory pool
void initialize_memory_pool() {
    for (size_t i = 0; i < MEMORY_POOL_SIZE; ++i) {
        memory_pool.pool[i] = (NFAPI_MESSAGE_T *)malloc(sizeof(NFAPI_MESSAGE_T));
        memset(memory_pool.pool[i], 0, sizeof(NFAPI_MESSAGE_T));
    }
    pthread_mutex_init(&memory_pool.lock, NULL);
}

// Allocate a message from the pool
NFAPI_MESSAGE_T* allocate_message(unsigned int ue_id) {
    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.used < MEMORY_POOL_SIZE) {
        NFAPI_MESSAGE_T *msg = memory_pool.pool[memory_pool.used++];
        msg->ue_id = ue_id;
        memset(msg->payload, 0, MAX_PAYLOAD_SIZE);
        pthread_mutex_unlock(&memory_pool.lock);
        return msg;
    } else {
        pthread_mutex_unlock(&memory_pool.lock);
        return NULL; // No available memory
    }
}

// Free a message back to the pool
void free_message(NFAPI_MESSAGE_T *msg) {
    pthread_mutex_lock(&memory_pool.lock);
    memmove(memory_pool.pool[memory_pool.used++], msg, sizeof(NFAPI_MESSAGE_T));
    pthread_mutex_unlock(&memory_pool.lock);
}

// Initialize the message queue
void initialize_message_queue() {
    for (size_t i = 0; i < MEMORY_POOL_SIZE; ++i) {
        message_queue.messages[i] = NULL;
    }
    pthread_rwlock_init(&message_queue.rwlock, NULL);
}

// Add a message to the queue
int add_message(unsigned int ue_id, const char *payload, size_t length) {
    if (length > MAX_PAYLOAD_SIZE) return -1; // Payload too large

    NFAPI_MESSAGE_T *msg = allocate_message(ue_id);
    if (!msg) return -2; // Memory allocation failed

    strncpy(msg->payload, payload, length);

    pthread_rwlock_wrlock(&message_queue.rwlock);
    if (message_queue.count < MEMORY_POOL_SIZE) {
        message_queue.messages[message_queue.count++] = msg;
    } else {
        free_message(msg); // Queue is full
        pthread_rwlock_unlock(&message_queue.rwlock);
        return -3; // Queue overflow
    }
    pthread_rwlock_unlock(&message_queue.rwlock);

    // Persist the state after adding a message
    persist_messages();

    return 0;
}

// Retrieve and remove a message from the queue
NFAPI_MESSAGE_T* get_message() {
    pthread_rwlock_rdlock(&message_queue.rwlock);
    if (message_queue.count == 0) {
        pthread_rwlock_unlock(&message_queue.rwlock);
        return NULL; // No messages available
    }

    NFAPI_MESSAGE_T *msg = message_queue.messages[0];
    memmove(message_queue.messages, &message_queue.messages[1], 
            (--message_queue.count) * sizeof(NFAPI_MESSAGE_T *));

    pthread_rwlock_unlock(&message_queue.rwlock);

    persist_messages();
    return msg;
}

// Persist messages to non-volatile storage
void persist_messages() {
    FILE *file = fopen("messages.dat", "wb");
    if (!file) return;

    fwrite(&message_queue.count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < message_queue.count; ++i) {
        fwrite(message_queue.messages[i], sizeof(NFAPI_MESSAGE_T), 1, file);
    }

    fclose(file);
}

// Restore messages from non-volatile storage
void restore_messages() {
    FILE *file = fopen("messages.dat", "rb");
    if (!file) return;

    fread(&message_queue.count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < message_queue.count; ++i) {
        NFAPI_MESSAGE_T *msg = allocate_message(0); // ue_id is not used on restore
        if (!msg) break;

        fread(msg, sizeof(NFAPI_MESSAGE_T), 1, file);
        pthread_rwlock_wrlock(&message_queue.rwlock);
        message_queue.messages[i] = msg;
        pthread_rwlock_unlock(&message_queue.rwlock);
    }

    fclose(file);
}

int main() {
    initialize_memory_pool();
    initialize_message_queue();
    restore_messages();

    // Example usage
    add_message(1, "Hello", 5);
    NFAPI_MESSAGE_T *msg = get_message();
    if (msg) {
        printf("Retrieved Message: %s\n", msg->payload);
        free_message(msg); 
    }

    return 0;
}
```

**Note:** This implementation provides a basic framework with thread safety, memory management via a pool allocator, and persistence mechanisms. The code includes rudimentary error handling and uses a simple file-based approach for message persistence. Further optimization and refinement are necessary for deployment in a real embedded system environment. Adjustments may include more sophisticated locking strategies or advanced I/O techniques based on specific hardware capabilities.']

