#include <time.h>

typedef struct {
    int value;
    char status;
    int key;
} record;

record* manage_memory(size_t num_records, int max_key_value, int enable_debug) {
    if (enable_debug) {
        // Example placeholder for enabling memory debugging tools
        printf("Memory debugging enabled.\n");
    }

    record *records = NULL;

    // Allocate memory for the records array.
    records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        return NULL;  // Memory allocation failed
    }

    srand((unsigned int)time(NULL));  // Seed random number generator

    // Temporary arrays to track unique values and keys
    int values[num_records];
    int used_values[num_records] = {0};

    for (size_t i = 0; i < num_records; ++i) {
        if (i >= max_key_value) break;

        records[i].key = i + 1;

        // Randomly assign status A or B
        records[i].status = (rand() % 2 == 0) ? 'A' : 'B';

        // Assign unique random values between 1 and 1000
        int value;
        do {
            value = rand() % 1000 + 1;  // Random number between 1 and 1000
        } while (used_values[value - 1]);

        used_values[value - 1] = 1;  // Mark this value as used
        records[i].value = value;
    }

    return records;
}

void free_memory(record *records) {
    if (records) {
        free(records);
    }
}
