    // Allocate memory for the configuration structure.
    NetworkInterfaceConfig* config = (NetworkInterfaceConfig*)malloc(sizeof(NetworkInterfaceConfig));
    if (!config) {
        logError("Memory allocation failed for network interface configuration.");
        return NULL;
