    if (result != 0) {
        logError("Failed to fetch configuration from external service.");

        // Fallback mechanism: use default values or optional parameters.
        config->speed = "100Mbps";
        config->duplex = "half";

        // Check for optional parameters
        while (*optionalParams && **optionalParams) {
            if (strncmp(*optionalParams, "speed=", 6) == 0) {
                config->speed = strdup((*optionalParams) + 6);
            } else if (strncmp(*optionalParams, "duplex=", 7) == 0) {
                config->duplex = strdup((*optionalParams) + 7);
            }
            optionalParams++;
        }
    } else {
        // Parse the fetched configuration data.
        char* token = strtok(fetchedConfigData, ";");
        while (token != NULL) {
            if (strncmp(token, "speed=", 6) == 0) {
                config->speed = strdup((token + 6));
            } else if (strncmp(token, "duplex=", 7) == 0) {
                config->duplex = strdup((token + 7));
            }
            token = strtok(NULL, ";");
        }

        // Free the fetched configuration data.
        free(fetchedConfigData);
    }

    // Validate the final configuration.
    if (!validateConfiguration(config)) {
        logError("Invalid network interface configuration.");
        freeNetworkInterfaceConfig(config); // Implement this function to free memory
        return NULL;
    }

    return config;
}

