typedef struct {
    node* head;
    size_t count;
} AuditLogList;

AuditLogList* createAuditLogList() {
    AuditLogList* list = (AuditLogList*)malloc(sizeof(AuditLogList));
    list->head = NULL;
    list->count = 0;
    return list;
}

void freePayload(void* payload, eventType type) {
    // Free payload based on event type
    // Example:
    if (type == EVENT_TYPE_1 && payload != NULL) {
        free(payload);
    }
    // Add more cases as needed
}

void deleteAuditLogList(AuditLogList* list) {
    node* current = list->head;
    while (current != NULL) {
        node* next = current->next;
        freePayload(current->event.payload, current->event.type);
        free(current);
        current = next;
    }
    free(list);
}

void addAuditEvent(AuditLogList* list, time_t timestamp, eventType type, const char* description, void* payload) {
    node* new_node = (node*)malloc(sizeof(node));
    new_node->event.timestamp = timestamp;
    new_node->event.type = type;
    new_node->event.description = strdup(description);
    new_node->event.payload = payload;

    // Insert in sorted order by timestamp to handle duplicates and maintain order
    node** current = &list->head;
    while (*current != NULL && ((*current)->event.timestamp < timestamp || 
        ((*current)->event.timestamp == timestamp && (*current)->event.type <= type))) {
        current = &(*current)->next;
    }
    new_node->next = *current;
    *current = new_node;
    list->count++;
}

auditEvent* filterEventsByType(AuditLogList* list, eventType type) {
    node* current = list->head;
    size_t index = 0;

    while (current != NULL) {
        if (current->event.type == type) {
            static auditEvent events[1000000]; // Example buffer size
            memcpy(&events[index++], &current->event, sizeof(auditEvent));
        }
        current = current->next;
    }

    return index > 0 ? events : NULL;
}

auditEvent* getEventsInTimeRange(AuditLogList* list, time_t start_time, time_t end_time) {
    node* current = list->head;
    size_t index = 0;

    while (current != NULL) {
        if (current->event.timestamp >= start_time && current->event.timestamp <= end_time) {
            static auditEvent events[1000000]; // Example buffer size
            memcpy(&events[index++], &current->event, sizeof(auditEvent));
        }
        current = current->next;
    }

    return index > 0 ? events : NULL;
}

int serializeAuditLogList(AuditLogList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1;

    fwrite(&list->count, sizeof(size_t), 1, file);

    node* current = list->head;
    while (current != NULL) {
        fwrite(&current->event.timestamp, sizeof(time_t), 1, file);
        fwrite(&current->event.type, sizeof(eventType), 1, file);

        size_t description_len = strlen(current->event.description) + 1;
        fwrite(&description_len, sizeof(size_t), 1, file);
        fwrite(current->event.description, sizeof(char), description_len, file);

        // For payload, we need to manage serialization based on type
        if (current->event.type == EVENT_TYPE_1 && current->event.payload != NULL) {
            size_t payload_size = *((size_t*)current->event.payload);
            fwrite(&payload_size, sizeof(size_t), 1, file);
            fwrite((char*)(current->event.payload) + sizeof(size_t), sizeof(char), payload_size, file);
        }
        // Add more cases as needed

        current = current->next;
    }

    fclose(file);
    return 0;
}

int deserializeAuditLogList(AuditLogList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1;

    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        auditEvent event;
        fread(&event.timestamp, sizeof(time_t), 1, file);
        fread(&event.type, sizeof(eventType), 1, file);

        size_t description_len;
        fread(&description_len, sizeof(size_t), 1, file);
        char* description = (char*)malloc(description_len);
        fread(description, sizeof(char), description_len, file);
        event.description = description;

        if (event.type == EVENT_TYPE_1) {
            size_t payload_size;
            fread(&payload_size, sizeof(size_t), 1, file);
            void* payload = malloc(payload_size + sizeof(size_t));
            ((size_t*)payload)[0] = payload_size;
            fread((char*)payload + sizeof(size_t), sizeof(char), payload_size, file);
            event.payload = payload;
        }
        // Add more cases as needed

        addAuditEvent(list, event.timestamp, event.type, event.description, event.payload);
    }

    fclose(file);
    return 0;
}
