['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define REALLOCATION_THRESHOLD_FACTOR 2

typedef struct {
    time_t timestamp;
    int id;
    char status[20];
} DataRecord;

typedef struct {
    DataRecord *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} RecordArray;

// Function to create a new record array with initial capacity
RecordArray* create_record_array() {
    RecordArray *arr = (RecordArray*)malloc(sizeof(RecordArray));
    if (!arr) return NULL;

    arr->records = (DataRecord*)calloc(INITIAL_CAPACITY, sizeof(DataRecord));
    if (!arr->records) {
        free(arr);
        return NULL;
    }

    arr->capacity = INITIAL_CAPACITY;
    arr->count = 0;
    pthread_mutex_init(&arr->lock, NULL);

    return arr;
}

// Function to dynamically reallocate memory when needed
int expand_record_array(RecordArray *arr) {
    size_t new_capacity = arr->capacity * REALLOCATION_THRESHOLD_FACTOR;

    DataRecord *new_records = (DataRecord*)realloc(arr->records, new_capacity * sizeof(DataRecord));
    if (!new_records) return -1;

    arr->records = new_records;
    arr->capacity = new_capacity;

    // Initialize newly allocated records
    for (size_t i = arr->count; i < new_capacity; ++i) {
        time(&arr->records[i].timestamp);
        arr->records[i].id = -1;  // Indicate unused record
        snprintf(arr->records[i].status, sizeof(arr->records[i].status), "default");
    }

    return 0;
}

// Function to add a new record safely
int add_record(RecordArray *arr) {
    pthread_mutex_lock(&arr->lock);

    if (arr->count >= arr->capacity) {
        if (expand_record_array(arr) == -1) {
            pthread_mutex_unlock(&arr->lock);
            return -1;
        }
    }

    DataRecord *record = &arr->records[arr->count];
    time(&record->timestamp);
    record->id = arr->count;  // Simple unique ID based on index
    snprintf(record->status, sizeof(record->status), "default");

    ++arr->count;

    pthread_mutex_unlock(&arr->lock);

    return record->id;
}

// Function to update the status of a specific record by its id
int update_record_status(RecordArray *arr, int id, const char *new_status) {
    if (id < 0 || id >= arr->count) return -1;

    pthread_mutex_lock(&arr->lock);

    DataRecord *record = &arr->records[id];
    snprintf(record->status, sizeof(record->status), "%s", new_status);

    // Optional: Log update
    printf("Updated record ID %d to status '%s'\n", id, new_status);

    pthread_mutex_unlock(&arr->lock);

    return 0;
}

// Function to free allocated memory
void destroy_record_array(RecordArray *arr) {
    if (arr) {
        free(arr->records);
        pthread_mutex_destroy(&arr->lock);
        free(arr);
    }
}

int main() {
    RecordArray *arr = create_record_array();
    if (!arr) {
        fprintf(stderr, "Failed to allocate record array\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 15; ++i) { // Add more records than initial capacity
        int id = add_record(arr);
        if (id == -1) {
            fprintf(stderr, "Failed to add record at index %d\n", i);
            destroy_record_array(arr);
            return EXIT_FAILURE;
        }
    }

    update_record_status(arr, 5, "updated");

    destroy_record_array(arr);

    return EXIT_SUCCESS;
}
```

