#include <stdio.h>
#include <stdlib.h>
import <pthread.h>

#define MAX_ELEMENTS 5000

typedef struct {
    int PHY_FRAME_TAG;
    int CELL_ID;
    int TX_POWER_LEVEL_TAG;
    int RF_BANDWIDTH;
} LTE_PHY_RX_FRAME_PDU_T;

typedef struct Node {
    LTE_PHY_RX_FRAME_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CellIDHashTable;

CellIDHashTable* create_hash_table(size_t size) {
    CellIDHashTable* table = malloc(sizeof(CellIDHashTable));
    table->head = NULL;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

int hash_function(int cell_id, size_t size) {
    return cell_id % size;
}

Node* create_node(LTE_PHY_RX_FRAME_PDU_T data) {
    Node* node = malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

void insert_cell_id_hash_table(CellIDHashTable* table, LTE_PHY_RX_FRAME_PDU_T pdu) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(pdu.CELL_ID, MAX_ELEMENTS);
    Node* current = table->head;

    while (current != NULL && current->data.CELL_ID != pdu.CELL_ID) {
        if (current->next == NULL) break;
        current = current->next;
    }

    if (current != NULL && current->data.CELL_ID == pdu.CELL_ID) {
        // Update existing entry
        current->data.PHY_FRAME_TAG = pdu.PHY_FRAME_TAG;
        current->data.TX_POWER_LEVEL_TAG = pdu.TX_POWER_LEVEL_TAG;
        current->data.RF_BANDWIDTH = pdu.RF_BANDWIDTH;
    } else {
        // Insert new node
        Node* new_node = create_node(pdu);
        if (table->head == NULL) {
            table->head = new_node;
        } else {
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    pthread_mutex_unlock(&table->lock);
}

int validate_pdu(LTE_PHY_RX_FRAME_PDU_T* pdu) {
    if (pdu->PHY_FRAME_TAG < 0 || pdu->CELL_ID <= 0 || pdu->TX_POWER_LEVEL_TAG < -128 || pdu->TX_POWER_LEVEL_TAG > 127) {
        fprintf(stderr, "Validation failed: Invalid data ranges.\n");
        return 0;
    }
    return 1;
}

void* initialize_and_populate_pdu_array(void* args) {
    LTE_PHY_RX_FRAME_PDU_T* array = (LTE_PHY_RX_FRAME_PDU_T*)args;
    CellIDHashTable* hash_table = create_hash_table(MAX_ELEMENTS);

    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        LTE_PHY_RX_FRAME_PDU_T pdu = { .PHY_FRAME_TAG = rand() % 100,
                                       .CELL_ID = rand() % 1000 + 1,
                                       .TX_POWER_LEVEL_TAG = rand() % 256 - 128,
                                       .RF_BANDWIDTH = (rand() % 3) * 10 + 5 }; // Random between 5, 15, 25

        if (!validate_pdu(&pdu)) {
            free(hash_table);
            return NULL;
        }

        insert_cell_id_hash_table(hash_table, pdu);
        array[i] = pdu;
    }

    free(hash_table); // Proper cleanup after use
    return array;
}

int main() {
    pthread_t thread;
    LTE_PHY_RX_FRAME_PDU_T* pdu_array = malloc(MAX_ELEMENTS * sizeof(LTE_PHY_RX_FRAME_PDU_T));

    if (pthread_create(&thread, NULL, initialize_and_populate_pdu_array, pdu_array) != 0) {
        fprintf(stderr, "Failed to create thread.\n");
        free(pdu_array);
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    // Use the populated array here...

    free(pdu_array); // Ensure cleanup of allocated memory
    return EXIT_SUCCESS;
}
