#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;

    return list;
}

void free_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insert_element(List* list, NFAPI_CRC_INDICATION_PDU_T element) {
    if (!list || !element) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -2;

    new_node->data = element;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);

    new_node->next = list->head;
    list->head = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

int validate_data(NFAPI_CRC_INDICATION_PDU_T element) {
    if (element.RX_UE_INFORMATION_TAG == 0 || 
        element.RNTI == 0 || 
        element.CRC_INDICATION_REL8_TAG.CRCFLAG > 1) { // assuming valid CRCFLAG is 0 or 1
        printf("Validation failed for RX_UE_INFORMATION_TAG: %u, RNTI: %u, CRCFLAG: %d\n", 
               element.RX_UE_INFORMATION_TAG, 
               element.RNTI, 
               element.CRC_INDICATION_REL8_TAG.CRCFLAG);
        return -1;
    }
    return 0;
}

void log_error(const char* message) {
    printf("ERROR: %s\n", message);
}

int generate_random_crcflag() {
    srand(time(NULL));
    return rand() % 2; // Randomly 0 or 1
}

NFAPI_CRC_INDICATION_PDU_T create_pdu(unsigned int rx_tag, unsigned int rnti) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RX_UE_INFORMATION_TAG = rx_tag;
    pdu.RNTI = rnti;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();

    if (validate_data(pdu) != 0) {
        log_error("Invalid PDU data");
        exit(EXIT_FAILURE);
    }

    return pdu;
}

int retry_with_backoff(int (*operation)(void*), void* arg, int max_retries, int base_delay_ms) {
    for (int i = 0; i < max_retries; ++i) {
        if (operation(arg) == 0) return 0;

        sleep(base_delay_ms * (1 << i)); // Exponential backoff
    }

    log_error("Operation failed after retries");
    return -1;
}

int sample_operation(void* arg) {
    List* list = (List*)arg;
    unsigned int rx_tag = rand() % 10000; 
    unsigned int rnti = rand() % 1000;

    NFAPI_CRC_INDICATION_PDU_T pdu = create_pdu(rx_tag, rnti);

    return insert_element(list, pdu);
}

void data_sync(List* list) {
    if (!list) return;

    retry_with_backoff(sample_operation, (void*)list, 5, 100); // 5 retries with exponential backoff starting at 100ms
}

int main() {
    List* nfa_list = create_list();
    if (!nfa_list) {
        log_error("Failed to create list");
        return -1;
    }

    data_sync(nfa_list);

    free_list(nfa_list);

    return 0;
}
