    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->strategy = strategy;
    return list;
}

// Function to insert a node into the list
void insert_crc_indication(CRC_Indications_List *list, RX_UE_INFORMATION_TAG rx_ue_info,
                           CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!validate_crc(crc_indication_rel8_tag.crcflag)) {
        free(new_node);
