        return; // Skip invalid CRC indications
    }

    new_node->rx_ue_info = rx_ue_info;
    new_node->crc_indication_rel8_tag = crc_indication_rel8_tag;
    new_node->prev = NULL;
    new_node->next = NULL;

    if (!list->head) {
        list->head = list->tail = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        bool found_duplicate = false;

        while (current) {
            if (current->rx_ue_info.rnti == rx_ue_info.rnti) {
                found_duplicate = true;
                switch (list->strategy) {
                    case MERGE_DATA:
                        // Merge data logic here (assuming merging means just updating CRCFLAG)
                        current->crc_indication_rel8_tag.crcflag = crc_indication_rel8_tag.crcflag;
                        break;

                    case DISCARD_DUPLICATE:
                        free(new_node);
                        pthread_mutex_unlock(&list->lock);
                        return;
                }
                break;
            }
            current = current->next;
        }

        if (!found_duplicate) {
            list->tail->next = new_node;
            new_node->prev = list->tail;
            list->tail = new_node;
        }
    }

    pthread_mutex_unlock(&list->lock);
