#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    char str_value[32];
    time_t timestamp;
} record;

typedef struct {
    void (*log)(const char*);
    int (*retry_log)(const char*, int);
} LoggingInterface;

// Global mutex for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Retry logging with exponential backoff
int retry_logging(const char *message, int max_retries) {
    int attempts = 0;
    while (attempts < max_retries) {
        if (logging_interface.retry_log(message, attempts)) {
            return 1; // Success
        }
        sleep((1 << attempts)); // Exponential backoff
        attempts++;
    }
    return 0; // Failed after retries
}

// Initialize arrays and structures with error handling
int initialize_arrays(long num_elements, LoggingInterface *logging_interface) {
    logging_interface = logging_interface;

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;
    int *status_flags = NULL;

    if (!num_elements) return 0; // No initialization needed for zero elements

    offsets = (long *)malloc(num_elements * sizeof(long));
    keys = (int *)malloc(num_elements * sizeof(int));
    records = (record *)calloc(num_elements, sizeof(record));
    status_flags = (int *)calloc(num_elements, sizeof(int));

    if (!offsets || !keys || !records || !status_flags) {
        free(offsets);
        free(keys);
        free(records);
        free(status_flags);
        return -1; // Memory allocation failed
    }

    pthread_mutex_lock(&lock);

    time_t last_timestamp = 0;
    for (long i = 0; i < num_elements; ++i) {
        keys[i] = rand(); // Example key generation
        offsets[i] = i * sizeof(record); // Example offset calculation

        records[i].value = keys[i];
        snprintf(records[i].str_value, sizeof(records[i].str_value), "%d", keys[i]);
        records[i].timestamp = time(NULL);

        if (records[i].timestamp <= last_timestamp) {
            logging_interface.log("Timestamps are not monotonically increasing.");
            free(offsets);
            free(keys);
            free(records);
            free(status_flags);
            pthread_mutex_unlock(&lock);
            return -2; // Invalid timestamp sequence
        }

        last_timestamp = records[i].timestamp;
        status_flags[i] = 0; // Unprocessed

        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Record %ld created with key %d.", i, keys[i]);
        if (!retry_logging(log_msg, 3)) {
            logging_interface.log("Failed to log creation after retries.");
        }
    }

    pthread_mutex_unlock(&lock);

    // Simulate processing and updating status flags
    for (long i = 0; i < num_elements; ++i) {
        // Processing logic here...
        status_flags[i] = 1; // Mark as processed

        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Record %ld processed.", i);
        if (!retry_logging(log_msg, 3)) {
            logging_interface.log("Failed to log processing after retries.");
        }
    }

    return 0; // Success
}

void free_resources(long *offsets, int *keys, record *records, int *status_flags) {
    free(offsets);
    free(keys);
    free(records);
    free(status_flags);
}
