    srand(seed + pdu->ue_info.RX_UE_INFORMATION_TAG + pdu->ue_info.RNTI);
    pdu->crc_info.CRCFLAG = rand() % 2;
}

int validate_uniqueness(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU* current = head;
    while (current != NULL) {
        if ((current->ue_info.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) ||
            (current->ue_info.RNTI == RNTI)) {
            return 0; // Duplicate found
        }
        current = current->next;
    }
    return 1; // Unique
}

void insert_pdu(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&lock);

    if (!validate_uniqueness(RX_UE_INFORMATION_TAG, RNTI)) {
        pthread_mutex_unlock(&lock);
        printf("Duplicate entry found.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU* new_node = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!new_node) {
