    }

    new_node->ue_info.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->ue_info.RNTI = RNTI;
    set_crcflag(new_node);
    new_node->next = head;
    head = new_node;

    pthread_mutex_unlock(&lock);
}

void export_to_file(const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing.");
        return;
    }

    NFAPI_CRC_INDICATION_PDU* current = head;
    while (current != NULL) {
        fwrite(&(current->ue_info), sizeof(UE_INFO), 1, file);
        fwrite(&(current->crc_info), sizeof(CRC_INDICATION_REL8), 1, file);
        current = current->next;
    }

    fclose(file);
}

void import_from_file(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading.");
        return;
    }

    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU* current = head;

    while (current != NULL && !feof(file)) {
        UE_INFO ue_info;
        CRC_INDICATION_REL8 crc_info;

        if (fread(&ue_info, sizeof(UE_INFO), 1, file) == 1 &&
            fread(&crc_info, sizeof(CRC_INDICATION_REL8), 1, file) == 1) {

            current->ue_info = ue_info;
            current->crc_info.CRCFLAG = crc_info.CRCFLAG;

            current = current->next;
        } else {
            break; // End of file or error
        }
    }

    pthread_mutex_unlock(&lock);
    fclose(file);
}

void stress_test(int iterations) {
    for (int i = 0; i < iterations; ++i) {
        int RX_UE_INFORMATION_TAG = rand() % MAX_ELEMENTS;
        int RNTI = rand() % MAX_ELEMENTS;
