    }
}

void cleanup() {
    pthread_mutex_lock(&lock);
    NFAPI_CRC_INDICATION_PDU* current = head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_unlock(&lock);
}

