CRCLinkedList* create_list() {
    CRCLinkedList* list = (CRCLinkedList*)malloc(sizeof(CRCLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_node(NFAPI_CRC_INDICATION_PDU* node) {
    if (node) free(node);
}

NFAPI_CRC_INDICATION_PDU* create_node(UE_INFO info) {
    NFAPI_CRC_INDICATION_PDU* node = (NFAPI_CRC_INDICATION_PDU*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!node) return NULL;
    node->info = info;
    node->crc_tag.CRCFLAG = rand() % 2; // Random CRCFLAG
    node->prev = node->next = NULL;
    return node;
}

void add_crc_indication(CRCLinkedList* list, UE_INFO info, int merge_duplicates) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU *current = list->head, *prev = NULL;
    while (current) {
        if (current->info.RNTI == info.RNTI) {
            if (merge_duplicates) {
                // Merge logic here
                printf("Merging RNTI: %u\n", info.RNTI);
            } else {
                pthread_mutex_unlock(&list->lock);
                return; // Discard duplicate
            }
        }
        prev = current;
        current = current->next;
    }

    NFAPI_CRC_INDICATION_PDU* new_node = create_node(info);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (list->tail) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

void remove_crc_indication(CRCLinkedList* list, uint16_t rnti) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU *current = list->head, *prev = NULL;
    while (current && current->info.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev) prev->next = current->next;
    else list->head = current->next;

    if (current == list->tail) list->tail = prev;
    if (current->next) current->next->prev = prev;

    free_node(current);
    list->count--;

    pthread_mutex_unlock(&list->lock);
}

void iterate_forward(CRCLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU*)) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current) {
        callback(current);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_reverse(CRCLinkedList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU*)) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU* current = list->tail;
    while (current) {
        callback(current);
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

void free_list(CRCLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU* current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU* next = current->next;
        free_node(current);
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

