    Node *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* create_list() {
    DoublyLinkedList *list = (DoublyLinkedList *)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_node(Node *node) {
    free(node);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(DoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->data.rnti != data.rnti) {
        current = current->next;
    }

    if (current == NULL) { // Not found, add new node
        Node *new_node = create_node(data);

        if (list->tail == NULL) {
            list->head = list->tail = new_node;
        } else {
            list->tail->next = new_node;
            new_node->prev = list->tail;
            list->tail = new_node;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_from_list(DoublyLinkedList *list, int rnti) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current != NULL && current->data.rnti != rnti) {
        current = current->next;
    }

    if (current == NULL) return;

    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current->next != NULL) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev;
    }

    destroy_node(current);

    pthread_mutex_unlock(&list->lock);
}

void free_list(DoublyLinkedList *list) {
    Node *current = list->head;

    while (current != NULL) {
        Node *next = current->next;
        destroy_node(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Unit test functions
void test_add_and_remove() {
    DoublyLinkedList *list = create_list();

    NFAPI_CRC_INDICATION_PDU_T data1 = { .rnti = 1 };
    add_to_list(list, data1);

    Node *current = list->head;
    printf("List size after adding: %d\n", (current == NULL) ? 0 : 1);

    remove_from_list(list, 1);
    current = list->head;
    printf("List size after removing: %d\n", (current == NULL) ? 0 : 1);

    free_list(list);
}

int main() {
    test_add_and_remove();
    return 0;
}
```

### Documentation

- **Performance and Memory Usage:** The linked list is designed to handle concurrent updates efficiently, using a mutex for thread safety. The use of doubly linked nodes ensures efficient insertions and deletions.

- **Memory Management:** The `destroy_node` function provides explicit memory management for individual nodes, while `free_list` handles complete garbage collection.

- **Dynamic Resizing:** The structure can handle dynamic data sizes by simply adding new entries or removing existing ones without predefining limits.

- **Configuration and Optimization:**
  - For high concurrency, ensure the system has a sufficient number of CPU cores.
  - Monitor memory usage and adjust based on available resources to prevent fragmentation.

- **Testing:** The unit test `test_add_and_remove` demonstrates basic functionality. Further stress tests should be implemented with threading to simulate concurrent access under heavy load conditions.

This code provides a foundational implementation for managing dynamically resizable doubly linked lists of CRC indication PDUs in an NFAPI context, with considerations for performance, memory efficiency, and concurrency.']

