    long array_size, record_size, num_threads;
    printf("Enter size for offset and key arrays (1-%d): ", MAX_SIZE);
    scanf("%ld", &array_size);

    if(array_size <= 0 || array_size > MAX_SIZE) {
        log_error("Invalid array size");
        return EXIT_FAILURE;
    }

    int* keys = malloc(array_size * sizeof(int));
    long* offsets = malloc(array_size * sizeof(long));

    if (!keys || !offsets) {
        log_error("Memory allocation failed for arrays");
        free(keys);
        free(offsets);
        return EXIT_FAILURE;
    }

    printf("Enter size for record array (1-%d): ", MAX_SIZE);
    scanf("%ld", &record_size);

    if(record_size <= 0 || record_size > MAX_SIZE) {
        log_error("Invalid record size");
        free(keys);
        free(offsets);
        return EXIT_FAILURE;
    }

    record* records = malloc(record_size * sizeof(record));
    if (!records) {
        log_error("Memory allocation failed for records");
        free(keys);
        free(offsets);
        return EXIT_FAILURE;
    }

    printf("Enter number of threads (1-%d): ", MAX_SIZE / 10); // Example limit
    scanf("%ld", &num_threads);

    if(num_threads <= 0 || num_threads > array_size) {
        log_error("Invalid number of threads");
        free(keys);
        free(offsets);
        free(records);
        return EXIT_FAILURE;
    }

    pthread_t* threads = malloc(num_threads * sizeof(pthread_t));
    if (!threads) {
        log_error("Memory allocation failed for threads");
        free(keys);
        free(offsets);
        free(records);
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    long chunk_size = record_size / num_threads;
    pthread_attr_t attr;
    pthread_attr_init(&attr);

    for (long i = 0; i < num_threads; ++i) {
        long start_index = i * chunk_size;
        long end_index = (i == num_threads - 1) ? record_size : start_index + chunk_size;

        // Allocate memory to pass index and records pointer
        void* arg = malloc(sizeof(long) + sizeof(record*) + sizeof(char));
        if (!arg) {
            log_error("Memory allocation failed for thread arguments");
            free(keys);
            free(offsets);
            free(records);
            free(threads);
            return EXIT_FAILURE;
        }

        // Set argument values
        *((long*)arg) = start_index;
        *(record**)(arg + sizeof(long)) = records;

        int res = pthread_create(&threads[i], &attr, initialize_record, arg);

        if (res != 0) {
            log_error("Failed to create thread");
            free(arg);
            free(keys);
            free(offsets);
            free(records);
            free(threads);
            return EXIT_FAILURE;
        }
    }

    for(long i = 0; i < num_threads; ++i) {
        void* arg = malloc(sizeof(long) + sizeof(record*) + sizeof(char));
        if (!arg) {
            log_error("Memory allocation failed for thread arguments");
            free(keys);
            free(offsets);
            free(records);
            free(threads);
            return EXIT_FAILURE;
        }

        *((long*)arg) = i * (record_size / num_threads);
        *(record**)(arg + sizeof(long)) = records;

        pthread_join(threads[i], NULL);

        free(arg);
    }

    // Cleanup
    free(keys);
    free(offsets);
    free(records);
    free(threads);

    return EXIT_SUCCESS;
}
