#define CACHE_SIZE 100

typedef struct {
    uint32_t rnti;
    int crc_flag; // Randomly set CRC flag
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t rx_ue_info_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Logging function prototype (assuming a logging framework exists)
void log_crc_failure(uint32_t rnti);

typedef struct {
    pthread_mutex_t lock; // Mutex for thread safety
    size_t count;         // Number of elements
    size_t capacity;      // Capacity of the array
    NFAPI_CRC_INDICATION_PDU_T *elements; // Dynamic array of structures
} CRC_Indication_List;

// Cache structure to optimize data retrieval
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T cache[CACHE_SIZE];
    size_t index;
    pthread_mutex_t lock; // Mutex for thread safety in the cache
} CRC_Cache;

CRC_Cache crc_cache = {.index = 0, .lock = PTHREAD_MUTEX_INITIALIZER};

// Function to initialize the list
void init_crc_indication_list(CRC_Indication_List *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->capacity = 10; // Initial capacity
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
}

// Function to resize the list dynamically
void resize_crc_indication_list(CRC_Indication_List *list, size_t new_capacity) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    if (new_elements != NULL) {
        list->elements = new_elements;
        list->capacity = new_capacity;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to add an element to the list
void add_crc_indication(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        resize_crc_indication_list(list, list->capacity * 2);
    }
    list->elements[list->count++] = pdu;
    pthread_mutex_unlock(&list->lock);
}

// Function to generate random CRC flag
int generate_random_crc_flag() {
    return rand() % 2; // Randomly returns 0 or 1
}

// Thread-safe function to populate the list
void populate_crc_indication_list(CRC_Indication_List *list, size_t n) {
    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        pthread_mutex_lock(&crc_cache.lock);
        if (crc_cache.index < CACHE_SIZE) {
            pdu = crc_cache.cache[crc_cache.index++];
        }
        pthread_mutex_unlock(&crc_cache.lock);

        // Populate structure with random data
        pdu.rx_ue_info_tag = rand() % 10000;
        pdu.rnti = rand() % 1000;
        pdu.crc_indication_rel8_tag.crc_flag = generate_random_crc_flag();

        if (pdu.crc_indication_rel8_tag.crc_flag == 1) {
            log_crc_failure(pdu.rnti);
        }

        // Add to list and cache
        add_crc_indication(list, pdu);

        pthread_mutex_lock(&crc_cache.lock);
        if (crc_cache.index < CACHE_SIZE) {
            crc_cache.cache[crc_cache.index++] = pdu;
        }
        pthread_mutex_unlock(&crc_cache.lock);
    }
}

// Error handling example function
