['Here's a C implementation for the described task using POSIX threads for concurrency, along with a simple LRU mechanism and periodic flushing:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define CACHE_SIZE 1000

typedef struct CacheEntry {
    char *key;
    char *value;
    time_t last_accessed;
    struct CacheEntry *prev, *next;
} CacheEntry;

typedef struct {
    CacheEntry *head, *tail;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} LRUCache;

LRUCache* create_cache(size_t capacity) {
    LRUCache *cache = (LRUCache*)malloc(sizeof(LRUCache));
    cache->head = cache->tail = NULL;
    cache->capacity = capacity;
    pthread_mutex_init(&cache->lock, NULL);
    pthread_cond_init(&cache->not_full, NULL);
    pthread_cond_init(&cache->not_empty, NULL);
    return cache;
}

void lock_cache(LRUCache *cache) {
    pthread_mutex_lock(&cache->lock);
}

void unlock_cache(LRUCache *cache) {
    pthread_mutex_unlock(&cache->lock);
}

CacheEntry* create_entry(const char *key, const char *value) {
    CacheEntry *entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    entry->key = strdup(key);
    entry->value = strdup(value);
    entry->last_accessed = time(NULL);
    entry->prev = entry->next = NULL;
    return entry;
}

void move_to_front(LRUCache *cache, CacheEntry *entry) {
    if (entry == cache->head) return;

    if (entry->prev) entry->prev->next = entry->next;
    if (entry->next) entry->next->prev = entry->prev;

    if (entry == cache->tail) cache->tail = entry->prev;

    entry->next = cache->head;
    entry->prev = NULL;

    if (cache->head) cache->head->prev = entry;
    cache->head = entry;

    if (!cache->tail) cache->tail = entry;
}

void evict_if_needed(LRUCache *cache) {
    while (count_entries(cache) > cache->capacity) {
        CacheEntry *to_remove = cache->tail;
        printf("Evicting: %s\n", to_remove->key);

        if (to_remove->prev) to_remove->prev->next = NULL;
        if (to_remove == cache->head) cache->head = to_remove->next;

        free(to_remove->key);
        free(to_remove->value);
        free(to_remove);

        cache->tail = to_remove->prev;
    }
}

size_t count_entries(LRUCache *cache) {
    size_t count = 0;
    CacheEntry *current = cache->head;
    while (current) {
        count++;
        current = current->next;
    }
    return count;
}

void flush_expired(LRUCache *cache, time_t expiration_time) {
    lock_cache(cache);
    CacheEntry *current = cache->head;
    while (current) {
        if (difftime(time(NULL), current->last_accessed) > expiration_time) {
            CacheEntry *to_remove = current;
            current = current->next;

            if (to_remove->prev) to_remove->prev->next = to_remove->next;
            if (to_remove->next) to_remove->next->prev = to_remove->prev;

            if (to_remove == cache->head) cache->head = to_remove->next;
            if (to_remove == cache->tail) cache->tail = to_remove->prev;

            free(to_remove->key);
            free(to_remove->value);
            free(to_remove);

        } else {
            current = current->next;
        }
    }
    unlock_cache(cache);
}

void set_value(LRUCache *cache, const char *key, const char *value) {
    lock_cache(cache);

    CacheEntry *current = cache->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            free(current->value);
            current->value = strdup(value);
            current->last_accessed = time(NULL);
            move_to_front(cache, current);
            unlock_cache(cache);
            return;
        }
        current = current->next;
    }

    CacheEntry *new_entry = create_entry(key, value);
    new_entry->next = cache->head;
    if (cache->head) cache->head->prev = new_entry;
    cache->head = new_entry;

    if (!cache->tail) cache->tail = new_entry;

    evict_if_needed(cache);

    unlock_cache(cache);
}

char* get_value(LRUCache *cache, const char *key) {
    lock_cache(cache);

    CacheEntry *current = cache->head;
    while (current) {
        if (strcmp(current->key, key) == 0) {
            current->last_accessed = time(NULL);
            move_to_front(cache, current);
            unlock_cache(cache);
            return strdup(current->value);
        }
        current = current->next;
    }

    unlock_cache(cache);
    return NULL;
}

void destroy_cache(LRUCache *cache) {
    lock_cache(cache);

    CacheEntry *current = cache->head;
    while (current) {
        CacheEntry *to_free = current;
        current = current->next;

        free(to_free->key);
        free(to_free->value);
        free(to_free);
    }

    pthread_mutex_destroy(&cache->lock);
    pthread_cond_destroy(&cache->not_full);
    pthread_cond_destroy(&cache->not_empty);

    free(cache);
}

// Unit tests
void test_cache() {
    LRUCache *cache = create_cache(2);

    set_value(cache, "key1", "value1");
    printf("Get key1: %s\n", get_value(cache, "key1"));
    set_value(cache, "key2", "value2");
    printf("Get key2: %s\n", get_value(cache, "key2"));

    set_value(cache, "key3", "value3"); // Evicts key1
    printf("Get key1 after eviction: %s\n", get_value(cache, "key1")); // Should be NULL

    set_value(cache, "key4", "value4"); // Evicts key2
    printf("Get key2 after eviction: %s\n", get_value(cache, "key2")); // Should be NULL

    printf("Get key3: %s\n", get_value(cache, "key3"));
    printf("Get key4: %s\n", get_value(cache, "key4"));

    flush_expired(cache, 5); // Flush if older than 5 seconds

    destroy_cache(cache);
}

int main() {
    test_cache();
    return 0;
}
```

### Explanation:

- **LRU Cache Structure**: The cache uses a doubly linked list to maintain the order of usage and a hash table for quick access. Here, we've simplified it with just a linked list.

- **Concurrency**: Mutex locks are used to ensure thread safety during read/write operations.

- **Eviction Policy**: When adding a new entry, if the cache exceeds its capacity, the least recently used item (tail of the list) is evicted.

- **Expiration**: Periodically, entries older than a specified time are removed.

- **Unit Tests**: Basic tests cover setting and getting values, eviction logic, and expiration handling.']

