['```java
package CacheService;

import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class CacheManager {
    private final ConcurrentHashMap<String, CacheEntry> cache;
    private final ScheduledExecutorService scheduler;
    private final int maxCacheSize;
    private final Logger logger;

    public CacheManager(int maxCacheSize) {
        this.maxCacheSize = maxCacheSize;
        this.cache = new ConcurrentHashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(1);
        this.logger = Logger.getLogger(CacheManager.class.getName());

        // Start eviction task
        scheduler.scheduleAtFixedRate(this::evictEntries, 0, 1, TimeUnit.MINUTES);
    }

    public void put(String key, String value, long expirationTimeMillis, Map<String, String> metadata) {
        CacheEntry entry = new CacheEntry(key, value, System.currentTimeMillis() + expirationTimeMillis, metadata);
        cache.put(key, entry);

        if (cache.size() > maxCacheSize) {
            evictOldest();
        }

        logger.log(Level.INFO, "Put entry: {0}", key);
    }

    public String get(String key) {
        CacheEntry entry = cache.get(key);
        if (entry == null || System.currentTimeMillis() > entry.expirationTime) {
            logger.log(Level.FINE, "Cache miss for key: {0}", key);
            return null;
        }

        logger.log(Level.INFO, "Cache hit for key: {0}", key);
        return entry.value;
    }

    private void evictEntries() {
        long currentTime = System.currentTimeMillis();
        Iterator<Map.Entry<String, CacheEntry>> iterator = cache.entrySet().iterator();

        while (iterator.hasNext()) {
            Map.Entry<String, CacheEntry> entry = iterator.next();
            if (entry.getValue().expirationTime < currentTime) {
                iterator.remove();
                logger.log(Level.INFO, "Evicted expired entry: {0}", entry.getKey());
            }
        }

        // Optionally evict more entries to maintain a certain cache size
    }

    private void evictOldest() {
        Map.Entry<String, CacheEntry> oldestEntry = null;
        for (Map.Entry<String, CacheEntry> entry : cache.entrySet()) {
            if (oldestEntry == null || entry.getValue().expirationTime < oldestEntry.getValue().expirationTime) {
                oldestEntry = entry;
            }
        }

        if (oldestEntry != null) {
            cache.remove(oldestEntry.getKey());
            logger.log(Level.INFO, "Evicted oldest entry: {0}", oldestEntry.getKey());
        }
    }

    public void shutdown() {
        scheduler.shutdown();
        try {
            if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    private static class CacheEntry implements Serializable {
        final String key;
        final String value;
        final long expirationTime;
        final Map<String, String> metadata;

        public CacheEntry(String key, String value, long expirationTime, Map<String, String> metadata) {
            this.key = key;
            this.value = value;
            this.expirationTime = expirationTime;
            this.metadata = new HashMap<>(metadata);
        }

        private void writeObject(ObjectOutputStream oos) throws IOException {
            oos.defaultWriteObject();
        }

        private void readObject(ObjectInputStream ois) throws ClassNotFoundException, IOException {
            ois.defaultReadObject();
        }
    }

    public static void main(String[] args) {
        CacheManager cacheManager = new CacheManager(100);

        // Example usage
        Map<String, String> metadata = new HashMap<>();
        metadata.put("source", "external-system");

        cacheManager.put("key1", "value1", 5000, metadata);
        System.out.println(cacheManager.get("key1"));

        cacheManager.shutdown();
    }
}
```

This Java program implements a thread-safe distributed caching system using a `CacheManager` class. The cache uses a `ConcurrentHashMap` for thread-safe storage and employs a scheduled task to evict expired entries. The `CacheEntry` class supports serialization for persistence, and the logger is used for monitoring cache operations while managing logging verbosity to prevent performance bottlenecks.']

