import threading

// Mock definitions for external dependencies
typedef unsigned int RX_UE_INFORMATION_TAG;
typedef unsigned int RNTI;
#define NFAPI_OK 0
#define NFAPI_ERROR -1
#define MAX_PDUS 10000
#define EXPECTED_CRC_FLAG 0xA5A5 // Example expected CRC flag

typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Logging function
void log_message(const char* message) {
    printf("%s\n", message);
}

// Thread-safe RNG initialization
pthread_mutex_t rng_lock = PTHREAD_MUTEX_INITIALIZER;

int generate_random_crc_flag(uint16_t *crc_flag) {
    pthread_mutex_lock(&rng_lock);
    // Example of generating a random CRC flag
    *crc_flag = rand() % 0xFFFF;
    pthread_mutex_unlock(&rng_lock);

    return NFAPI_OK;
}

// Mock function to fetch RNTI from external source
int fetch_rnti_from_external_source(RNTI *rnti) {
    // Simulate fetching with possible failure or delay
    if (rand() % 2 == 0) { // Simulate a 50% chance of failure
        return NFAPI_ERROR;
    }
    *rnti = rand() % 10000; // Example RNTI generation
    return NFAPI_OK;
}

// Main function to generate PDUs
int generate_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus, size_t num_pdus) {
    if (num_pdus > MAX_PDUS) {
        log_message("Error: Requested number of PDUs exceeds maximum limit.");
        return NFAPI_ERROR;
    }

    *pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*pdus == NULL) {
        log_message("Error: Memory allocation failed.");
        return NFAPI_ERROR;
    }

    RNTI used_rntis[MAX_PDUS] = {0};
    int rnti_count = 0;

    for (size_t i = 0; i < num_pdus; ++i) {
        (*pdus)[i].ue_info_tag = rand(); // Example value

        int success;
        do {
            RNTI rnti;
            success = fetch_rnti_from_external_source(&rnti);
            if (success != NFAPI_OK) {
                log_message("Warning: Failed to fetch RNTI, retrying...");
                continue;
            }

            // Check for duplicate RNTI
            int is_duplicate = 0;
            for (int j = 0; j < rnti_count; ++j) {
                if (used_rntis[j] == rnti) {
                    is_duplicate = 1;
                    break;
                }
            }

            if (!is_duplicate) {
                used_rntis[rnti_count++] = rnti;
                (*pdus)[i].rnti = rnti;
            } else {
                log_message("Warning: Duplicate RNTI found, retrying...");
            }
        } while (success != NFAPI_OK || is_duplicate);

        if (generate_random_crc_flag(&(*pdus)[i].crc_indication_rel8_tag.CRCFLAG) != NFAPI_OK) {
            free(*pdus);
            log_message("Error: Failed to generate random CRC flag.");
            return NFAPI_ERROR;
        }

        // Validate the generated CRC flag
        if ((*pdus)[i].crc_indication_rel8_tag.CRCFLAG != EXPECTED_CRC_FLAG) {
            free(*pdus);
            log_message("Error: Generated PDU has invalid CRC flag.");
            return NFAPI_ERROR;
        }
    }

    log_message("Success: PDUs generated successfully.");
    return NFAPI_OK;
}

// Function to free allocated memory
void free_pdus(NFAPI_CRC_INDICATION_PDU_T *pdus) {
    if (pdus != NULL) {
        free(pdus);
    }
}
```

