#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Measurement {
    float latency;
    float throughput;
    float packet_loss;
} Measurement;

typedef struct Node {
    time_t timestamp;
    int session_id;
    Measurement measurements[10]; // Adjust size as needed
    int measurement_count;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_at_head(LinkedList* list, time_t timestamp, int session_id, Measurement measurements[], int count) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->timestamp = timestamp;
    new_node->session_id = session_id;
    memcpy(new_node->measurements, measurements, count * sizeof(Measurement));
    new_node->measurement_count = count;
    new_node->next = list->head;
    list->head = new_node;

    log_operation("Inserted at head");

    pthread_mutex_unlock(&list->lock);
}

void insert_at_end(LinkedList* list, time_t timestamp, int session_id, Measurement measurements[], int count) {
    pthread_mutex_lock(&list->lock);

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->timestamp = timestamp;
    new_node->session_id = session_id;
    memcpy(new_node->measurements, measurements, count * sizeof(Measurement));
    new_node->measurement_count = count;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    log_operation("Inserted at end");

    pthread_mutex_unlock(&list->lock);
}

void cleanup_metrics(LinkedList* list, time_t retention_time) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;

    while (current != NULL) {
        if (difftime(time(NULL), current->timestamp) > retention_time) {
            Node* temp = current;
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(temp);
            log_operation("Cleaned up metric");
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void log_operation(const char* operation) {
    // Implement a more efficient logging mechanism as needed.
    printf("%s\n", operation);
}

void prune_list(LinkedList* list, int max_entries) {
    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    int count = 0;

    while (current != NULL && count < max_entries) {
        prev = current;
        current = current->next;
        count++;
    }

    if (count > max_entries && prev != NULL) {
        Node* temp = prev;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = NULL; // Truncate the list
        log_operation("Pruned old entries");
    }

    pthread_mutex_unlock(&list->lock);
}

void integrate_with_monitoring_system(LinkedList* list) {
    // Simulated integration logic. Implement actual data flow to an external system here.
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;

    while (current != NULL) {
        // Send metrics to the monitoring system
        log_operation("Integrated with monitoring system");
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_linked_list(LinkedList* list) {
    if (!list) return;

    Node *current = list->head, *temp = NULL;

    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    LinkedList* metrics_list = create_linked_list();

    Measurement measurements[] = {{10.5, 1000.0, 0.1}, {9.8, 950.0, 0.2}};
    insert_at_head(metrics_list, time(NULL), 12345, measurements, 2);

    sleep(1); // Simulate delay

    integrate_with_monitoring_system(metrics_list);

    cleanup_metrics(metrics_list, 60); // Retain metrics for 60 seconds
    prune_list(metrics_list, 10); // Limit to 10 entries at most

    destroy_linked_list(metrics_list);
    return 0;
}
```

