#define MAX_FRAMES 1024
#define MAC_ADDRESS_LENGTH 6
#define ETHERTYPE_SIZE 2

typedef struct {
    unsigned char SourceMACAddress[MAC_ADDRESS_LENGTH];
    unsigned char DestinationMACAddress[MAC_ADDRESS_LENGTH];
    unsigned int Timestamp;
    unsigned short Ethertype;
} FrameHeader;

typedef struct {
    FrameHeader *frames;
    size_t count;
} FrameSet;

pthread_mutex_t frame_set_lock = PTHREAD_MUTEX_INITIALIZER;

unsigned int generate_unique_timestamp() {
    return (unsigned int)time(NULL);
}

void generate_random_mac_address(unsigned char mac[MAC_ADDRESS_LENGTH]) {
    for (int i = 0; i < MAC_ADDRESS_LENGTH; i++) {
        mac[i] = rand() % 256;
    }
    mac[0] &= 0xFE; // Ensure the first byte's second bit is zero
}

int mac_address_is_unique(unsigned char *mac, FrameSet *frame_set) {
    for (size_t i = 0; i < frame_set->count; i++) {
        if (memcmp(frame_set->frames[i].SourceMACAddress, mac, MAC_ADDRESS_LENGTH) == 0) {
            return 0;
        }
    }
    return 1;
}

int ethertype_is_unique(unsigned short ethertype, FrameHeader *frame_headers, size_t count) {
    for (size_t i = 0; i < count; i++) {
        if (frame_headers[i].Ethertype == ethertype) {
            return 0;
        }
    }
    return 1;
}

FrameSet* initialize_frame_set(size_t num_frames) {
    FrameSet *frame_set = malloc(sizeof(FrameSet));
    frame_set->frames = malloc(num_frames * sizeof(FrameHeader));
    frame_set->count = 0;

    if (!frame_set || !frame_set->frames) {
        free(frame_set);
        return NULL;
    }

    srand((unsigned int)time(NULL));

    unsigned short ethertypes[MAX_FRAMES];
    memset(ethertypes, 0, sizeof(ethertypes));

    for (size_t i = 0; i < num_frames; ++i) {
        pthread_mutex_lock(&frame_set_lock);

        FrameHeader *header = &frame_set->frames[frame_set->count];

        do {
            generate_random_mac_address(header->SourceMACAddress);
        } while (!mac_address_is_unique(header->SourceMACAddress, frame_set));

        // Generate a random destination MAC address
        generate_random_mac_address(header->DestinationMACAddress);

        header->Timestamp = generate_unique_timestamp();

        unsigned short ethertype;
        do {
            ethertype = (unsigned short)(rand() % 0xFFFF);
        } while (!ethertype_is_unique(ethertype, frame_set->frames, frame_set->count));

        memcpy(&header->Ethertype, &ethertype, ETHERTYPE_SIZE);

        ethertypes[frame_set->count] = ethertype;
        ++frame_set->count;

        pthread_mutex_unlock(&frame_set_lock);
    }

    return frame_set;
}

void free_frame_set(FrameSet *frame_set) {
    if (frame_set) {
        free(frame_set->frames);
        free(frame_set);
    }
}

int main() {
    size_t num_frames = 100; // Example number of frames
    FrameSet *frame_set = initialize_frame_set(num_frames);

    if (!frame_set) {
        fprintf(stderr, "Failed to initialize frame set.\n");
        return EXIT_FAILURE;
    }

    printf("Frame set initialized with %zu unique frames.\n", frame_set->count);

    free_frame_set(frame_set);
    return 0;
}
