#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct MAC_EVENT {
    int event_id;
    struct MAC_EVENT* next_event;
} MAC_EVENT;

typedef struct LMAC_CONFIG {
    // Define your LMAC_CONFIG fields here
} LMAC_CONFIG;

typedef struct MAC_CONTEXT_T {
    int context_id;
    LMAC_CONFIG config;
    MAC_EVENT* events_head;
    pthread_mutex_t lock;  // For thread safety on this structure
    struct MAC_CONTEXT_T* next;
    struct MAC_CONTEXT_T* prev;  // For easy removal and insertion in linked list
} MAC_CONTEXT_T;

typedef struct {
    MAC_CONTEXT_T* head;
    MAC_CONTEXT_T* tail;
    pthread_rwlock_t rwlock;  // Reader-writer lock for thread-safe operations on contexts
} DynamicArray;

// Function to log messages with timestamps
void log_message(const char* message, int context_id) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    printf("[%04d-%02d-%02d %02d:%02d:%02d] Context ID: %d - %s\n", 
           t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, context_id, message);
}

// Initialize the dynamic array
DynamicArray* init_dynamic_array() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    da->head = NULL;
    da->tail = NULL;
    pthread_rwlock_init(&da->rwlock, NULL);
    return da;
}

// Create a new MAC_CONTEXT_T
MAC_CONTEXT_T* create_context(int context_id) {
    MAC_CONTEXT_T* ctx = (MAC_CONTEXT_T*)malloc(sizeof(MAC_CONTEXT_T));
    if (!ctx) {
        perror("Failed to allocate memory for context");
        exit(EXIT_FAILURE);
    }
    ctx->context_id = context_id;
    pthread_mutex_init(&ctx->lock, NULL);
    ctx->events_head = NULL;
    ctx->next = NULL;
    ctx->prev = NULL;

    // Initialize LMAC_CONFIG here
    return ctx;
}

// Add a new context to the dynamic array
void add_context(DynamicArray* da, int context_id) {
    pthread_rwlock_wrlock(&da->rwlock);
    MAC_CONTEXT_T* ctx = create_context(context_id);

    if (da->tail) {
        da->tail->next = ctx;
        ctx->prev = da->tail;
        da->tail = ctx;
    } else {
        da->head = da->tail = ctx;
    }

    pthread_rwlock_unlock(&da->rwlock);
    log_message("Added new context", context_id);
}

// Update an existing context
void update_context(DynamicArray* da, int context_id) {
    pthread_rwlock_rdlock(&da->rwlock);
    MAC_CONTEXT_T* ctx = da->head;
    while (ctx) {
        if (pthread_mutex_trylock(&ctx->lock) == 0) {  // Try to lock the mutex
            log_message("Updating existing context", context_id);

            // Update LMAC_CONFIG or other data here

            pthread_mutex_unlock(&ctx->lock);
            break;
        }
        ctx = ctx->next;
    }
    pthread_rwlock_unlock(&da->rwlock);
}

// Retrieve events associated with a specific context
MAC_EVENT* get_events(DynamicArray* da, int context_id) {
    pthread_rwlock_rdlock(&da->rwlock);
    MAC_CONTEXT_T* ctx = da->head;
    while (ctx) {
        if (ctx->context_id == context_id) {
            if (pthread_mutex_trylock(&ctx->lock) == 0) {  // Try to lock the mutex
                log_message("Retrieving events", context_id);

                MAC_EVENT* events = ctx->events_head;
                pthread_mutex_unlock(&ctx->lock);
                pthread_rwlock_unlock(&da->rwlock);
                return events;
            }
        }
        ctx = ctx->next;
    }
    pthread_rwlock_unlock(&da->rwlock);
    log_message("Context not found for event retrieval", context_id);
    return NULL;
}

// Archive a context
void archive_context(DynamicArray* da, int context_id) {
    // Implementation to move the context from active list to an archived list or file system

    pthread_rwlock_wrlock(&da->rwlock);
    MAC_CONTEXT_T* ctx = da->head;
    while (ctx) {
        if (pthread_mutex_trylock(&ctx->lock) == 0) {  // Try to lock the mutex
            log_message("Archiving context", context_id);

            // Detach context from active list and move it to archive

            pthread_mutex_unlock(&ctx->lock);
            break;
        }
        ctx = ctx->next;
    }
    pthread_rwlock_unlock(&da->rwlock);
}

// Restore an archived context
void restore_context(DynamicArray* da, int context_id) {
    // Implementation to move the context from archive back to active list

    pthread_rwlock_wrlock(&da->rwlock);
    log_message("Restoring archived context", context_id);

    // Retrieve and reattach context to active list

    pthread_rwlock_unlock(&da->rwlock);
}

// Free memory for a MAC_CONTEXT_T
void free_context(MAC_CONTEXT_T* ctx) {
    pthread_mutex_lock(&ctx->lock);
    MAC_EVENT* event = ctx->events_head;
    while (event) {
        MAC_EVENT* temp_event = event;
        event = event->next_event;
        free(temp_event);
    }
    pthread_mutex_unlock(&ctx->lock);
    pthread_mutex_destroy(&ctx->lock);
    free(ctx);
}

// Clean up dynamic array
void cleanup_dynamic_array(DynamicArray* da) {
    pthread_rwlock_wrlock(&da->rwlock);
    MAC_CONTEXT_T* ctx = da->head;
    while (ctx) {
        MAC_CONTEXT_T* temp_ctx = ctx;
        ctx = ctx->next;
        free_context(temp_ctx);
    }
    pthread_rwlock_unlock(&da->rwlock);
    pthread_rwlock_destroy(&da->rwlock);
    free(da);
}

int main() {
    DynamicArray* da = init_dynamic_array();

    add_context(da, 1);
    update_context(da, 1);
    MAC_EVENT* events = get_events(da, 1);

    // Add more operations as needed

    cleanup_dynamic_array(da);
    return 0;
}
