int dequeueEvent(EventQueue* queue, NetworkEvent* event);
void cleanupExpiredEvents(EventQueue* queue);
void* periodicCleanup(void* arg);

void initializeQueue(EventQueue* queue, time_t ttl) {
    queue->head = NULL;
    queue->tail = NULL;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    queue->ttl = ttl;

    // Start cleanup thread
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, periodicCleanup, queue);
}

int enqueueEvent(EventQueue* queue, NetworkEvent event) {
    EventNode* newNode = (EventNode*)malloc(sizeof(EventNode));
    if (!newNode) return -1;

    newNode->event = event;
    newNode->next = NULL;

    pthread_mutex_lock(&queue->lock);

    if (queue->tail) {
        queue->tail->next = newNode;
    } else {
        queue->head = newNode;
    }
    queue->tail = newNode;
    queue->size++;

    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeueEvent(EventQueue* queue, NetworkEvent* event) {
    pthread_mutex_lock(&queue->lock);

    if (!queue->head) {
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }

    EventNode* temp = queue->head;
    *event = temp->event;

    queue->head = queue->head->next;
    if (!queue->head) {
        queue->tail = NULL;
    }
    free(temp);

    queue->size--;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void cleanupExpiredEvents(EventQueue* queue) {
    time_t current_time = time(NULL);
    pthread_mutex_lock(&queue->lock);

    EventNode *current = queue->head, *prev = NULL;

    while (current) {
        if ((current_time - current->event.timestamp) > queue->ttl) {
            EventNode* to_delete = current;
            if (prev) {
                prev->next = current->next;
            } else {
                queue->head = current->next;
            }
            if (!current->next) {
                queue->tail = prev;
            }
            free(to_delete);
            queue->size--;
        } else {
            prev = current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&queue->lock);
}

void* periodicCleanup(void* arg) {
    EventQueue* queue = (EventQueue*)arg;

    while (1) {
        sleep(60); // Cleanup every 60 seconds
        cleanupExpiredEvents(queue);
    }
    return NULL;
}
```

This code provides a basic implementation of the described functionality, including thread-safe enqueue and dequeue operations, periodic cleanup of expired events, and dynamic memory management. Further enhancements could include integration with external storage systems and more sophisticated logging and error handling mechanisms.']

