        unsigned int CRCFLAG:1;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;
    size_t capacity;
    size_t count;
    long *offset_values;
    int *keys;
    LTE_DL_CCCH_Message_Type1_T *message_structs;
} DynamicList;

void initialize_dynamic_list(DynamicList *list, size_t initial_capacity);
int add_pdu_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu);
void resize_if_needed(DynamicList *list);
