void initialize_dynamic_list(DynamicList *list, size_t initial_capacity) {
    if (!list || initial_capacity == 0) {
        LOG_ERROR("Invalid input parameters");
        return;
    }

    pthread_mutex_init(&list->mutex, NULL);
    list->capacity = initial_capacity;
    list->count = 0;

    list->pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu_array) {
        LOG_ERROR("Memory allocation failed for PDU array");
        return;
    }

    list->offset_values = (long *)calloc(initial_capacity, sizeof(long));
    if (!list->offset_values) {
        LOG_ERROR("Memory allocation failed for offset values");
        free(list->pdu_array);
        return;
    }

    list->keys = (int *)malloc(initial_capacity * sizeof(int));
    if (!list->keys) {
        LOG_ERROR("Memory allocation failed for keys");
        free(list->offset_values);
        free(list->pdu_array);
        return;
    }

    list->message_structs = (LTE_DL_CCCH_Message_Type1_T *)calloc(initial_capacity, sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!list->message_structs) {
        LOG_ERROR("Memory allocation failed for message structs");
        free(list->keys);
        free(list->offset_values);
        free(list->pdu_array);
        return;
    }

    log_memory_usage("Initialization complete");
}

int add_pdu_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list) {
        LOG_ERROR("Invalid list pointer");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    resize_if_needed(list);

    // Check for duplicates
    for (size_t i = 0; i < list->count; ++i) {
        if (list->pdu_array[i].RNTI == pdu.RNTI) {
            LOG_INFO("Duplicate RNTI found, not adding PDU");
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
    }

    list->pdu_array[list->count] = pdu;
    pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crc_flag();
    ++list->count;

    log_memory_usage("Added PDU to list");
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void resize_if_needed(DynamicList *list) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pdu_array = realloc(list->pdu_array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        long *new_offset_values = realloc(list->offset_values, new_capacity * sizeof(long));
        int *new_keys = realloc(list->keys, new_capacity * sizeof(int));
        LTE_DL_CCCH_Message_Type1_T *new_message_structs = realloc(list->message_structs, new_capacity * sizeof(LTE_DL_CCCH_Message_Type1_T));

        if (!new_pdu_array || !new_offset_values || !new_keys || !new_message_structs) {
            LOG_ERROR("Memory reallocation failed");
            return;
        }

        list->pdu_array = new_pdu_array;
        list->offset_values = new_offset_values;
        list->keys = new_keys;
        list->message_structs = new_message_structs;
        list->capacity = new_capacity;

        log_memory_usage("Resized dynamic list");
    }
}

unsigned int generate_random_crc_flag() {
    return rand() % 2;
}

void log_memory_usage(const char *context) {
    // Log the current memory usage
    size_t total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * list.capacity +
                        sizeof(long) * list.capacity +
                        sizeof(int) * list.capacity +
                        sizeof(LTE_DL_CCCH_Message_Type1_T) * list.capacity;

    LOG_INFO("Memory usage for %s: %zu bytes", context, total_size);
}

void log_system_health(int active_threads, int encoded_messages) {
    // Log system health metrics
    LOG_INFO("Active threads: %d, Successfully encoded messages: %d", active_threads, encoded_messages);
}

// Example function to periodically check and log system health
void *periodic_system_check(void *arg) {
    DynamicList *list = (DynamicList *)arg;

    while (1) {
        sleep(10); // Check every 10 seconds

        pthread_mutex_lock(&list->mutex);
        int active_threads = /* logic to count active threads */;
        int encoded_messages = list->count; // Assuming count is number of successfully encoded messages
        log_system_health(active_threads, encoded_messages);
        pthread_mutex_unlock(&list->mutex);
    }

    return NULL;
}

// Function to free all resources
void destroy_dynamic_list(DynamicList *list) {
    if (!list) return;

    pthread_mutex_destroy(&list->mutex);

    free(list->pdu_array);
    free(list->offset_values);
    free(list->keys);
    free(list->message_structs);

    LOG_INFO("Dynamic list destroyed");
}
