#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_FRAMES 1000
#define TIMESTAMP_RANGE_HOURS 24
#define FLUSH_THRESHOLD_DAYS 7

typedef struct {
    int frameNumber;
    time_t timestamp;
    int packetCount;
} FrameStatistics;

typedef struct {
    char RX_UE_INFORMATION_TAG[32];
    unsigned long RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    FrameStatistics data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
    int processedFrames;
    int addedFrames;
    int ignoredFrames;
} FrameList;

void log_event(const char* message) {
    printf("%s\n", message);
}

int is_valid_timestamp(time_t timestamp) {
    time_t now = time(NULL);
    double diff_hours = difftime(now, timestamp) / 3600.0;
    return diff_hours <= TIMESTAMP_RANGE_HOURS;
}

double calculate_average_packet_count(FrameList* frameList) {
    pthread_mutex_lock(&frameList->mutex);

    if (frameList->head == NULL) {
        pthread_mutex_unlock(&frameList->mutex);
        log_event("No frames to calculate average packet count.");
        return 0.0;
    }

    Node* current = frameList->head;
    double sum = 0.0;
    int count = 0;

    while (current != NULL) {
        sum += current->data.packetCount;
        count++;
        current = current->next;
    }

    pthread_mutex_unlock(&frameList->mutex);
    return count > 0 ? sum / count : 0.0;
}

void flush_old_frames(FrameList* frameList, int threshold_days) {
    time_t now = time(NULL);
    double threshold_seconds = threshold_days * 24 * 60 * 60;

    pthread_mutex_lock(&frameList->mutex);

    Node** current = &frameList->head;
    while (*current != NULL) {
        if (difftime(now, (*current)->data.timestamp) > threshold_seconds) {
            Node* temp = *current;
            *current = (*current)->next;
            free(temp);
            frameList->processedFrames++;
        } else {
            current = &(*current)->next;
        }
    }

    pthread_mutex_unlock(&frameList->mutex);
}

void initialize_and_populate_frames(FrameList* frameList, int maxFrames) {
    pthread_mutex_init(&frameList->mutex, NULL);

    for (int i = 0; i < maxFrames; ++i) {
        time_t timestamp = time(NULL) - rand() % (TIMESTAMP_RANGE_HOURS * 3600);
        if (!is_valid_timestamp(timestamp)) {
            log_event("Invalid timestamp. Frame ignored.");
            frameList->ignoredFrames++;
            continue;
        }

        pthread_mutex_lock(&frameList->mutex);

        if (frameList->processedFrames >= maxFrames) {
            log_event("Max frames limit reached, ignoring insertion.");
            frameList->ignoredFrames++;
            pthread_mutex_unlock(&frameList->mutex);
            continue;
        }

        Node* newFrame = malloc(sizeof(Node));
        if (!newFrame) {
            log_event("Memory allocation failed. Frame ignored.");
            frameList->ignoredFrames++;
            pthread_mutex_unlock(&frameList->mutex);
            continue;
        }

        newFrame->data.frameNumber = i + 1;
        newFrame->data.timestamp = timestamp;
        newFrame->data.packetCount = rand() % 100;

        newFrame->next = frameList->head;
        frameList->head = newFrame;

        frameList->processedFrames++;
        frameList->addedFrames++;

        pthread_mutex_unlock(&frameList->mutex);
    }
}

void create_crc_indications(NFAPI_CRC_INDICATION_PDU_T* indications, int count) {
    for (int i = 0; i < count; ++i) {
        snprintf(indications[i].RX_UE_INFORMATION_TAG, sizeof(indications[i].RX_UE_INFORMATION_TAG), "Tag%d", i);
        indications[i].RNTI = rand() % 10000;
        indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }
}

// Example usage
int main() {
    FrameList frameList = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0, 0};
    initialize_and_populate_frames(&frameList, MAX_FRAMES);

    double averagePacketCount = calculate_average_packet_count(&frameList);
    printf("Average Packet Count: %.2f\n", averagePacketCount);

    flush_old_frames(&frameList, FLUSH_THRESHOLD_DAYS);

    NFAPI_CRC_INDICATION_PDU_T indications[10];
    create_crc_indications(indications, 10);

    return 0;
}
