typedef struct {
    double average_path_length;
    unsigned long file_size; // This can be used to store additional metadata if needed.
    char *file_path;
} file_metadata;

file_metadata* initialize_file_metadata(const char *input_file, size_t num_files) {
    FILE *fp = fopen(input_file, "r");
    if (!fp) {
        fprintf(stderr, "Error opening input file.\n");
        return NULL;
    }

    file_metadata *metadata_array = (file_metadata *)malloc(num_files * sizeof(file_metadata));
    if (!metadata_array) {
        fprintf(stderr, "Memory allocation failed for metadata array.\n");
        fclose(fp);
        return NULL;
    }

    char buffer[1024];
    size_t total_path_length = 0;

    for (size_t i = 0; i < num_files && fgets(buffer, sizeof(buffer), fp) != NULL; ++i) {
        // Remove newline character
        buffer[strcspn(buffer, "\n")] = '\0';

        metadata_array[i].file_size = 0; // Initialize file size or other relevant data if needed

        // Calculate path length and allocate memory for the path
        size_t path_length = strlen(buffer) + 1;
        total_path_length += path_length;

        metadata_array[i].file_path = (char *)malloc(path_length);
        if (!metadata_array[i].file_path) {
            fprintf(stderr, "Memory allocation failed for file path.\n");

            // Free previously allocated memory
            while (--i >= 0) free(metadata_array[i].file_path);
            free(metadata_array);
            fclose(fp);
            return NULL;
        }

        strcpy(metadata_array[i].file_path, buffer);
    }

    size_t num_valid_paths = (ferror(fp) || feof(fp)) ? i : num_files;

    if (num_valid_paths > 0) {
        double average_length = (double)total_path_length / num_valid_paths;
        for (size_t j = 0; j < num_valid_paths; ++j) {
            metadata_array[j].average_path_length = average_length;
        }
    }

    fclose(fp);
    return metadata_array;
}

void free_file_metadata(file_metadata *metadata_array, size_t num_files) {
    if (!metadata_array) return;

    for (size_t i = 0; i < num_files; ++i) {
        free(metadata_array[i].file_path);
    }
    free(metadata_array);
}
