// Define structure types
typedef enum {
    PHY_FRAME_TYPE_A,
    PHY_FRAME_TYPE_B,
    // Add other frame types as necessary
} PHY_FRAME_TYPE;

typedef struct {
    PHY_FRAME_TYPE type;
    uint32_t frame_number;
    uint64_t time_stamp; // Use 64-bit for timestamp precision
    float rx_quality;
} LTE_PHY_RX_FRAME_INFO;

// Define dynamic list structure
typedef struct {
    LTE_PHY_RX_FRAME_INFO *data;
    size_t capacity;
    size_t count;
} DynamicList;

// Function prototypes
int init_list(DynamicList *list, size_t initial_capacity);
int append_frame(DynamicList *list, const LTE_PHY_RX_FRAME_INFO *frame_info);
LTE_PHY_RX_FRAME_INFO* find_frame_by_number(const DynamicList *list, uint32_t frame_number);
void clear_list(DynamicList *list);
int export_to_binary(const DynamicList *list, FILE *file);
int import_from_binary(DynamicList *list, const FILE *file);

// External logging and error handling dependencies
extern void log_error(const char *message);
extern void log_info(const char *message);

#define VERSION 1

// Implementation of dynamic list functions
int init_list(DynamicList *list, size_t initial_capacity) {
    if (initial_capacity == 0) return -1;

    list->data = aligned_alloc(alignof(LTE_PHY_RX_FRAME_INFO), 
                               initial_capacity * sizeof(LTE_PHY_RX_FRAME_INFO));
    if (!list->data) {
        log_error("Failed to allocate memory for dynamic list.");
        return -1;
    }
    list->capacity = initial_capacity;
    list->count = 0;

    log_info("Dynamic list initialized successfully.");
    return 0;
}

int append_frame(DynamicList *list, const LTE_PHY_RX_FRAME_INFO *frame_info) {
    if (!list || !frame_info) return -1;

    // Check for duplicate frame number
    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].frame_number == frame_info->frame_number) {
            log_error("Duplicate FRAME_NUMBER detected.");
            return -2;
        }
    }

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        LTE_PHY_RX_FRAME_INFO *new_data = aligned_realloc(list->data, 
                                                          alignof(LTE_PHY_RX_FRAME_INFO), 
                                                          new_capacity * sizeof(LTE_PHY_RX_FRAME_INFO));
        if (!new_data) {
            log_error("Failed to reallocate memory for dynamic list.");
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    memcpy(&list->data[list->count], frame_info, sizeof(LTE_PHY_RX_FRAME_INFO));
    ++list->count;

    log_info("Frame appended successfully.");
    return 0;
}

LTE_PHY_RX_FRAME_INFO* find_frame_by_number(const DynamicList *list, uint32_t frame_number) {
    if (!list) return NULL;

    for (size_t i = 0; i < list->count; ++i) {
        if (list->data[i].frame_number == frame_number) {
            log_info("Frame found.");
            return &list->data[i];
        }
    }

    log_error("Frame not found.");
    return NULL;
}

void clear_list(DynamicList *list) {
    if (!list) return;

    free(list->data);
    list->data = NULL;
    list->capacity = 0;
    list->count = 0;

    log_info("Dynamic list cleared.");
}

int export_to_binary(const DynamicList *list, FILE *file) {
    if (!list || !file) return -1;

    fwrite(&VERSION, sizeof(VERSION), 1, file);
    fwrite(&list->count, sizeof(list->count), 1, file);

    for (size_t i = 0; i < list->count; ++i) {
        const LTE_PHY_RX_FRAME_INFO *frame = &list->data[i];
        fwrite(&frame->type, sizeof(frame->type), 1, file);
        fwrite(&frame->frame_number, sizeof(frame->frame_number), 1, file);
        fwrite(&frame->time_stamp, sizeof(frame->time_stamp), 1, file);
        fwrite(&frame->rx_quality, sizeof(frame->rx_quality), 1, file);
    }

    log_info("Export to binary successful.");
    return 0;
}

int import_from_binary(DynamicList *list, const FILE *file) {
    if (!list || !file) return -1;

    uint8_t version;
    fread(&version, sizeof(version), 1, file);

    if (version != VERSION) {
        log_error("Incompatible binary format.");
        return -2;
    }

    size_t count;
    fread(&count, sizeof(count), 1, file);

    for (size_t i = 0; i < list->capacity && i < count; ++i) {
        LTE_PHY_RX_FRAME_INFO frame;
        fread(&frame.type, sizeof(frame.type), 1, file);
        fread(&frame.frame_number, sizeof(frame.frame_number), 1, file);
        fread(&frame.time_stamp, sizeof(frame.time_stamp), 1, file);
        fread(&frame.rx_quality, sizeof(frame.rx_quality), 1, file);

        append_frame(list, &frame); // Reuses duplicate check and reallocation
    }

    log_info("Import from binary successful.");
    return 0;
}
