typedef struct {
    // Add appropriate members here
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_RETRY 5

void process_integers(int N) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    int retries = 0;
    size_t initial_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    void *ptr = NULL;

    while (retries < MAX_RETRY) {
        if ((ptr = malloc(initial_size * N)) != NULL) {
            pthread_mutex_lock(&lock);
            // Initialize the array of structures
            for (int i = 0; i < N; ++i) {
                *(NFAPI_CRC_INDICATION_PDU_T *)(((char *)ptr) + i * initial_size) = (NFAPI_CRC_INDICATION_PDU_T){};
            }
            pthread_mutex_unlock(&lock);

            // Process the data...

            free(ptr);
            return;
        } else {
            retries++;
            fprintf(stderr, "Memory allocation failed. Retry %d/%d.\n", retries, MAX_RETRY);
            sleep(1 << retries); // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to allocate memory after %d attempts.\n", MAX_RETRY);

    pthread_mutex_destroy(&lock);
}
