// Define the LTEPHY_TDL_FRAME_CONFIG_T structure.
typedef struct {
    int frequency_band;
    int frame_type;
    uint8_t subframe_config[10]; // Example size, adjust as needed
} LTEPHY_TDL_FRAME_CONFIG_T;

#define MAX_ARRAY_SIZE 1024

typedef struct {
    LTEPHY_TDL_FRAME_CONFIG_T *array;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

// Function prototypes.
DynamicArray* init_dynamic_array();
void destroy_dynamic_array(DynamicArray *dyn_arr);
int add_config(DynamicArray *dyn_arr, LTEPHY_TDL_FRAME_CONFIG_T config);
LTEPHY_TDL_FRAME_CONFIG_T* get_config(DynamicArray *dyn_arr, size_t index);
size_t get_size(const DynamicArray *dyn_arr);
uint8_t* serialize_configs(const DynamicArray *dyn_arr, size_t *out_size);
int validate_config(const LTEPHY_TDL_FRAME_CONFIG_T *config);

// Initialize the dynamic array.
DynamicArray* init_dynamic_array() {
    DynamicArray *dyn_arr = malloc(sizeof(DynamicArray));
    if (!dyn_arr) return NULL;

    dyn_arr->array = NULL;
    dyn_arr->size = 0;
    pthread_mutex_init(&dyn_arr->lock, NULL);

    return dyn_arr;
}

// Destroy the dynamic array.
void destroy_dynamic_array(DynamicArray *dyn_arr) {
    if (dyn_arr) {
        free(dyn_arr->array);
        pthread_mutex_destroy(&dyn_arr->lock);
        free(dyn_arr);
    }
}

// Add a configuration to the dynamic array, ensuring validation and thread safety.
int add_config(DynamicArray *dyn_arr, LTEPHY_TDL_FRAME_CONFIG_T config) {
    if (!validate_config(&config)) return -1;

    pthread_mutex_lock(&dyn_arr->lock);

    if (dyn_arr->size >= MAX_ARRAY_SIZE) {
        pthread_mutex_unlock(&dyn_arr->lock);
        return -2; // Array is full
    }

    dyn_arr->array = realloc(dyn_arr->array, sizeof(LTEPHY_TDL_FRAME_CONFIG_T) * (dyn_arr->size + 1));
    if (!dyn_arr->array) {
        pthread_mutex_unlock(&dyn_arr->lock);
        return -3; // Memory allocation failed
    }

    dyn_arr->array[dyn_arr->size++] = config;
    pthread_mutex_unlock(&dyn_arr->lock);

    return 0;
}

// Retrieve a configuration by index.
LTEPHY_TDL_FRAME_CONFIG_T* get_config(DynamicArray *dyn_arr, size_t index) {
    if (index >= dyn_arr->size) return NULL;

    pthread_mutex_lock(&dyn_arr->lock);
    LTEPHY_TDL_FRAME_CONFIG_T *config = &dyn_arr->array[index];
    pthread_mutex_unlock(&dyn_arr->lock);

    return config;
}

// Get the current size of the dynamic array.
size_t get_size(const DynamicArray *dyn_arr) {
    pthread_mutex_lock((pthread_mutex_t*)&dyn_arr->lock);
    size_t size = dyn_arr->size;
    pthread_mutex_unlock((pthread_mutex_t*)&dyn_arr->lock);

    return size;
}

// Serialize the configurations into a binary format.
uint8_t* serialize_configs(const DynamicArray *dyn_arr, size_t *out_size) {
    pthread_mutex_lock(&dyn_arr->lock);

    size_t total_size = sizeof(size_t) + dyn_arr->size * (sizeof(int) + sizeof(int) + sizeof(uint8_t[10]));
    uint8_t *buffer = malloc(total_size);

    if (!buffer) {
        pthread_mutex_unlock(&dyn_arr->lock);
        return NULL;
    }

    size_t offset = 0;
    memcpy(buffer + offset, &dyn_arr->size, sizeof(size_t));
    offset += sizeof(size_t);

    for (size_t i = 0; i < dyn_arr->size; ++i) {
        memcpy(buffer + offset, &dyn_arr->array[i].frequency_band, sizeof(int));
        offset += sizeof(int);
        memcpy(buffer + offset, &dyn_arr->array[i].frame_type, sizeof(int));
        offset += sizeof(int);
        memcpy(buffer + offset, dyn_arr->array[i].subframe_config, sizeof(uint8_t[10]));
        offset += sizeof(uint8_t[10]);
    }

    pthread_mutex_unlock(&dyn_arr->lock);

    *out_size = total_size;
    return buffer;
}

// Validate the configuration.
int validate_config(const LTEPHY_TDL_FRAME_CONFIG_T *config) {
    if (config->frequency_band < 1 || config->frame_type < 0 || 
        config->frame_type > 2 || // Example frame type range
        strlen((char *)config->subframe_config) != 10) {
            return 0; // Invalid configuration
    }
    return 1;
