// Function to initialize and configure a list of LTE PHY layer frames
LTE_PHY_Frame* init_lte_phy_frames(int num_frames, int *pcis, size_t *transport_block_sizes) {
    if (num_frames > MAX_FRAMES || !pcis || !transport_block_sizes) {
        handle_error("Invalid input parameters");
    }

    LTE_PHY_Frame *frames = (LTE_PHY_Frame *)malloc(num_frames * sizeof(LTE_PHY_Frame));
    if (!frames) {
        handle_error("Memory allocation failed for frames array");
    }

    for (int i = 0; i < num_frames; ++i) {
        // Assign PCI
        frames[i].pci = pcis[i];

        // Determine transport block size within defined limits
        size_t tb_size = transport_block_sizes[i];
        if (tb_size < MIN_FRAME_SIZE || tb_size > MAX_FRAME_SIZE) {
            handle_error("Invalid transport block size");
        }

        // Allocate memory for transport block dynamically
        frames[i].transport_block = malloc(tb_size);
        if (!frames[i].transport_block) {
            // Handle failed allocation by freeing previously allocated blocks and frames array
            while (--i >= 0) free(frames[i].transport_block); 
            free(frames);
            handle_error("Memory allocation failed for transport block");
        }

        frames[i].transport_block_size = tb_size;
    }

    return frames;
}

// Function to free memory used by the LTE PHY layer frames
void cleanup_lte_phy_frames(LTE_PHY_Frame *frames, int num_frames) {
