```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Define the fields for PROCESS_CONFIG here
} PROCESS_CONFIG;

typedef struct DATA_FRAME {
    // Define the fields for DATA_FRAME here
    int id;
    // Add other necessary fields
} DATA_FRAME;

typedef struct DATA_PROCESSOR_T {
    PROCESS_CONFIG config;
    DATA_FRAME *dataFrames;
    size_t dataFrameCount;
} DATA_PROCESSOR_T;

typedef struct {
    DATA_PROCESSOR_T **processors;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

// Function to initialize the dynamic array
int initDynamicArray(DynamicArray *array) {
    if (!array) return -1;

    array->count = 0;
    array->capacity = 10; // Initial capacity
    array->processors = (DATA_PROCESSOR_T **)malloc(array->capacity * sizeof(DATA_PROCESSOR_T *));
    if (!array->processors) return -2;

    pthread_mutex_init(&array->lock, NULL);
    return 0;
}

// Function to resize the dynamic array when needed
int resizeArray(DynamicArray *array) {
    size_t newCapacity = array->capacity * 2;
    DATA_PROCESSOR_T **newProcessors = (DATA_PROCESSOR_T **)realloc(array->processors, newCapacity * sizeof(DATA_PROCESSOR_T *));
    if (!newProcessors) return -1;

    array->processors = newProcessors;
    array->capacity = newCapacity;
    return 0;
}

// Function to add a DATA_PROCESSOR_T instance to the dynamic array
int addDataProcessor(DynamicArray *array, DATA_PROCESSOR_T *processor) {
    if (!array || !processor) return -1;

    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity && resizeArray(array)) {
        pthread_mutex_unlock(&array->lock);
        return -2;
    }

    array->processors[array->count++] = processor;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Function to remove a DATA_PROCESSOR_T instance from the dynamic array
int removeDataProcessor(DynamicArray *array, size_t index) {
    if (!array || index >= array->count) return -1;

    pthread_mutex_lock(&array->lock);

    free(array->processors[index]->dataFrames);
    free(array->processors[index]);
    for (size_t i = index; i < array->count - 1; ++i) {
        array->processors[i] = array->processors[i + 1];
    }
    --array->count;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Function to free the dynamic array resources
void destroyDynamicArray(DynamicArray *array) {
    if (!array) return;

    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        free(array->processors[i]->dataFrames);
        free(array->processors[i]);
    }
    free(array->processors);

    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

// Function to create a new DATA_PROCESSOR_T instance
DATA_PROCESSOR_T *createDataProcessor(PROCESS_CONFIG config, size_t frameCount) {
    DATA_PROCESSOR_T *processor = (DATA_PROCESSOR_T *)malloc(sizeof(DATA_PROCESSOR_T));
    if (!processor) return NULL;

    processor->config = config;
    processor->dataFrameCount = frameCount;
    processor->dataFrames = (DATA_FRAME *)calloc(frameCount, sizeof(DATA_FRAME));

    if (!processor->dataFrames) {
        free(processor);
        return NULL;
    }

    return processor;
}

// Example usage
int main() {
    DynamicArray array;
    initDynamicArray(&array);

    PROCESS_CONFIG config; // Initialize as needed
    DATA_PROCESSOR_T *processor = createDataProcessor(config, 5);
    if (processor) addDataProcessor(&array, processor);

    // Perform operations on the dynamic array

    destroyDynamicArray(&array);
    return 0;
}
```

