#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define structure for CRC indication
typedef struct {
    int valid_RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node for linked list to store structures dynamically
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Queue structure with mutex for thread safety
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int count;
    int allocation_success;
    int allocation_failures;
} CRC_Queue;

CRC_Queue queue = {NULL, NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0, 0};

// Function to generate random CRCFLAG
int generate_random_crcflag() {
    return rand() % 2; // Simulate a binary flag (0 or 1)
}

// Function to create and add an element to the queue
void enqueue(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        pthread_mutex_lock(&queue.lock);
        queue.allocation_failures++;
        pthread_mutex_unlock(&queue.lock);
        return;
    }

    new_node->data.valid_RX_UE_INFORMATION_TAG = pdu->valid_RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = pdu->RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = pdu->CRC_INDICATION_REL8_TAG;
    new_node->data.CRCFLAG = generate_random_crcflag();
    new_node->next = NULL;

    pthread_mutex_lock(&queue.lock);
    if (queue.tail != NULL) {
        queue.tail->next = new_node;
    } else {
        queue.head = new_node;
    }
    queue.tail = new_node;
    queue.count++;
    queue.allocation_success++;
    pthread_mutex_unlock(&queue.lock);
}

// Function to dequeue and remove an element from the queue
int dequeue(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&queue.lock);
    if (queue.head == NULL) {
        pthread_mutex_unlock(&queue.lock);
        return 0;
    }

    Node* temp = queue.head;
    *pdu = temp->data;
    queue.head = queue.head->next;

    if (queue.head == NULL) {
        queue.tail = NULL;
    }

    free(temp);
    queue.count--;
    pthread_mutex_unlock(&queue.lock);
    return 1;
}

// Function to clean up and free all nodes
void cleanup_queue() {
    NFAPI_CRC_INDICATION_PDU_T pdu;

    while (dequeue(&pdu)); // Dequeue until empty
}

// Main function for simulation
int main() {
    srand(time(NULL));

    pthread_t threads[4];
    int i;

    void* thread_func(void* arg) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {1, rand(), rand(), 0};

        for (int j = 0; j < 1000; ++j) {
            enqueue(&pdu);
        }

        return NULL;
    }

    // Start threads
    for (i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    // Join threads
    for (i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    printf("Total CRC indications processed: %d\n", queue.count);
    printf("Allocation successes: %d\n", queue.allocation_success);
    printf("Allocation failures: %d\n", queue.allocation_failures);

    // Cleanup
    cleanup_queue();

    return 0;
}
```']

