#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define MAX_HEAP_USAGE 1024 * 1024 * 100 // 100 MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t allocated_count;
    size_t failed_allocations;
    unsigned long total_processed_crcs;
    double average_allocation_time;
} CRC_Queue;

CRC_Queue crc_queue = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0, 0, 0.0};
pthread_mutex_t metrics_lock = PTHREAD_MUTEX_INITIALIZER;
int max_heap_usage = MAX_HEAP_USAGE;

void* allocate_node(void);
void free_queue(CRC_Queue*);
void enqueue(NFAPI_CRC_INDICATION_PDU_T pdu);
NFAPI_CRC_INDICATION_PDU_T dequeue();
void log_performance_metrics();
void telemetry_monitor();

void init_crc_queue() {
    crc_queue.head = NULL;
}

void cleanup_crc_queue() {
    free_queue(&crc_queue);
}

Node* allocate_node(void) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        pthread_mutex_lock(&crc_queue.lock);
        crc_queue.failed_allocations++;
        pthread_mutex_unlock(&crc_queue.lock);
        return NULL;
    }

    clock_t start = clock();
    node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    node->next = NULL;
    clock_t end = clock();

    double allocation_time = (double)(end - start) / CLOCKS_PER_SEC;

    pthread_mutex_lock(&crc_queue.lock);
    crc_queue.allocated_count++;
    crc_queue.average_allocation_time += allocation_time;
    pthread_mutex_unlock(&crc_queue.lock);

    return node;
}

void free_queue(CRC_Queue* queue) {
    Node* current = queue->head;
    while (current != NULL) {
        Node* next_node = current->next;
        free(current);
        current = next_node;
    }
    queue->head = NULL;

    pthread_mutex_destroy(&queue->lock);
}

void enqueue(NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* node = allocate_node();
    if (node == NULL) return; // Allocation failed

    node->data.RX_UE_INFORMATION_TAG = pdu.RX_UE_INFORMATION_TAG;
    node->data.RNTI = pdu.RNTI;
    node->data.CRC_INDICATION_REL8_TAG = pdu.CRC_INDICATION_REL8_TAG;

    pthread_mutex_lock(&crc_queue.lock);
    node->next = crc_queue.head;
    crc_queue.head = node;
    crc_queue.total_processed_crcs++;
    pthread_mutex_unlock(&crc_queue.lock);
}

NFAPI_CRC_INDICATION_PDU_T dequeue() {
    if (!crc_queue.head) return (NFAPI_CRC_INDICATION_PDU_T){0};

    Node* temp_node = crc_queue.head;
    NFAPI_CRC_INDICATION_PDU_T pdu = temp_node->data;

    pthread_mutex_lock(&crc_queue.lock);
    crc_queue.head = temp_node->next;
    free(temp_node);
    pthread_mutex_unlock(&crc_queue.lock);

    return pdu;
}

void log_performance_metrics() {
    pthread_mutex_lock(&metrics_lock);
    double avg_alloc_time = (crc_queue.allocated_count > 0) ? 
                            (crc_queue.average_allocation_time / crc_queue.allocated_count) : 0;

    printf("Total CRCs processed: %lu\n", crc_queue.total_processed_crcs);
    printf("Failed allocations: %zu\n", crc_queue.failed_allocations);
    printf("Average allocation time: %.6f seconds\n", avg_alloc_time);

    pthread_mutex_unlock(&metrics_lock);
}

void telemetry_monitor() {
    // Placeholder for telemetry logic, e.g., gather CPU usage or memory pressure
    while (1) {
        sleep(5);  // Monitor every 5 seconds
        log_performance_metrics();
    }
}

int main() {
    srand(time(NULL));

    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, (void*)telemetry_monitor, NULL);

    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, 3, 0};

    for (int i = 0; i < 1000; ++i) {
        enqueue(pdu);
    }

    sleep(10); // Simulate workload

    while (crc_queue.head != NULL) {
        NFAPI_CRC_INDICATION_PDU_T processed_pdu = dequeue();
        printf("Processed PDU with CRCFLAG: %d\n", processed_pdu.CRCFLAG);
    }

    pthread_join(monitor_thread, NULL);

    cleanup_crc_queue();

    return 0;
}
