#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define TABLE_SIZE 1024
#define LOAD_FACTOR 0.75

typedef struct Record {
    int value;
} Record;

typedef struct HashNode {
    int key;
    Record *record;
    struct HashNode *next;
} HashNode;

typedef struct HashTable {
    HashNode **buckets;
    pthread_mutex_t lock;
    size_t size;
    size_t count;
} HashTable;

// Function prototypes
HashTable* create_hash_table(size_t size);
void destroy_hash_table(HashTable *table, int free_data);
int hash_function(int key, size_t table_size);
void insert_record(HashTable *table, int key, Record *record);
Record* find_record(HashTable *table, int key);

// Thread-safe random number generator
unsigned int thread_safe_random(unsigned int min, unsigned int max) {
    static pthread_mutex_t rand_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&rand_lock);

    // Seed the random number generator once
    static int seeded = 0;
    if (!seeded) {
        srand((unsigned int)time(NULL));
        seeded = 1;
    }

    unsigned int range = (max - min) + 1;
    unsigned int num = rand() % range + min;

    pthread_mutex_unlock(&rand_lock);
    return num;
}

// Create a new hash table
HashTable* create_hash_table(size_t size) {
    HashTable *table = malloc(sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        exit(EXIT_FAILURE);
    }

    table->buckets = calloc(size, sizeof(HashNode *));
    if (!table->buckets) {
        free(table);
        perror("Failed to allocate memory for buckets");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&table->lock, NULL);
    table->size = size;
    table->count = 0;

    return table;
}

// Destroy the hash table and optionally free data
void destroy_hash_table(HashTable *table, int free_data) {
    for (size_t i = 0; i < table->size; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *temp = node;
            node = node->next;

            if (free_data) {
                free(temp->record);
            }
            free(temp);
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

// Simple hash function
int hash_function(int key, size_t table_size) {
    return key % table_size;
}

// Insert a record into the hash table
void insert_record(HashTable *table, int key, Record *record) {
    int index = hash_function(key, table->size);

    pthread_mutex_lock(&table->lock);

    HashNode *node = malloc(sizeof(HashNode));
    if (!node) {
        perror("Failed to allocate memory for hash node");
        exit(EXIT_FAILURE);
    }
    node->key = key;
    node->record = record;
    node->next = table->buckets[index];
    table->buckets[index] = node;

    table->count++;

    pthread_mutex_unlock(&table->lock);

    // Resize if load factor is exceeded
    if ((float)table->count / table->size > LOAD_FACTOR) {
        printf("Resizing hash table...\n");
        // Implement resizing logic here if needed
    }
}

// Find a record by key in the hash table
Record* find_record(HashTable *table, int key) {
    int index = hash_function(key, table->size);

    pthread_mutex_lock(&table->lock);

    HashNode *node = table->buckets[index];
    while (node) {
        if (node->key == key) {
            pthread_mutex_unlock(&table->lock);
            return node->record;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return NULL;
}

// Initialize and manage dynamic memory for records
void initialize_records(long *offsets, int keys[], Record **records, size_t num_records) {
    HashTable *hash_table = create_hash_table(TABLE_SIZE);

    offsets = malloc(num_records * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    records = malloc(num_records * sizeof(Record *));
    if (!records) {
        free(offsets);
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = (long)i;
        keys[i] = thread_safe_random(1, 10000);

        Record *record = malloc(sizeof(Record));
        if (!record) {
            free(offsets);
            free(records);
            perror("Failed to allocate memory for record");
            exit(EXIT_FAILURE);
        }

        record->value = thread_safe_random(10, 100);
        records[i] = record;

        insert_record(hash_table, keys[i], record);
    }
}

// Example usage
int main() {
    size_t num_records = 1000;
    long *offsets = NULL;
    int *keys = malloc(num_records * sizeof(int));
    Record **records = NULL;

    if (!keys) {
        perror("Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }

    initialize_records(offsets, keys, records, num_records);

    // Example lookup
    Record *found_record = find_record(create_hash_table(TABLE_SIZE), keys[0]);
    if (found_record) {
        printf("Found record with value: %d\n", found_record->value);
    } else {
        printf("Record not found.\n");
    }

    destroy_hash_table(create_hash_table(TABLE_SIZE), 1);

    free(keys);
    // Free other allocated resources here

    return 0;
}
```

This code provides a basic implementation of dynamic memory allocation and initialization for records in a multi-threaded environment. It includes thread-safe random number generation, a hash table with chaining for collision handling, and functions to manage the lifecycle of the data structures.']

