int find_largest_integer() {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    int *numbers = NULL;
    size_t capacity = 0, count = 0;
    int num, max = INT_MIN;

    printf("Enter integers (EOF to finish):\n");

    while (true) {
        if (scanf("%d", &num) != 1) break;

        pthread_mutex_lock(&lock);

        // Resize array if necessary
        if (count >= capacity) {
            size_t new_capacity = capacity == 0 ? 4 : capacity * 2;
            int *new_numbers = realloc(numbers, new_capacity * sizeof(int));
            if (!new_numbers) {
                fprintf(stderr, "Memory allocation failed\n");
                free(numbers);
                pthread_mutex_unlock(&lock);
                return -1;
            }
            numbers = new_numbers;
            capacity = new_capacity;
        }

        numbers[count++] = num;

        // Update maximum value
        if (num > max) max = num;

        pthread_mutex_unlock(&lock);
    }

    if (count < MIN_INT_COUNT) {
        fprintf(stderr, "Error: At least %d integers are required.\n", MIN_INT_COUNT);
        free(numbers);
        return -1;
    }

    free(numbers);
    return max;
}

