#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI; // Using unsigned long for wider range
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int is_duplicate(unsigned long rnti, NFAPI_CRC_INDICATION_PDU_T* array, int size) {
    for (int i = 0; i < size; ++i) {
        if (array[i].RNTI == rnti) {
            return 1;
        }
    }
    return 0;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

unsigned int pseudo_random_crc() {
    // Seed the random number generator for reproducibility
    static unsigned int seed = time(NULL); 
    return rand_r(&seed) % 2; // Returns 0 or 1
}

NFAPI_CRC_INDICATION_PDU_T* manage_dynamic_array(NFAPI_CRC_INDICATION_PDU_T* array, int* size, unsigned long rnti, int rx_ue_tag) {
    if (*size >= MAX_ELEMENTS) {
        log_error("Maximum capacity reached.");
        return array;
    }

    if (is_duplicate(rnti, array, *size)) {
        char message[100];
        snprintf(message, sizeof(message), "Duplicate RNTI detected: %lu", rnti);
        log_error(message);
        return array; // Skip duplicate
    }

    array[*size].RX_UE_INFORMATION_TAG = rx_ue_tag;
    array[*size].RNTI = rnti;
    array[*size].CRC_INDICATION_REL8_TAG = pseudo_random_crc();
    (*size)++;

    return array;
}

// Example usage (assuming the caller manages memory allocation and deallocation)
int main() {
    srand(time(NULL)); // Initialize global random seed for pseudo_random_crc
    NFAPI_CRC_INDICATION_PDU_T* dynamic_array = malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int current_size = 0;

    if (dynamic_array == NULL) {
        log_error("Memory allocation failed.");
        return EXIT_FAILURE;
    }

    // Simulating data feed processing
    for (int i = 0; i < MAX_ELEMENTS * 2; ++i) { // To test duplicate handling
        unsigned long rnti = rand() % ((1UL << 20) - 1); + 1; // Random RNTI in range [1, 2^20)
        manage_dynamic_array(dynamic_array, &current_size, rnti, i);
    }

    free(dynamic_array);
    return EXIT_SUCCESS;
}
