        // Simulate fetching and validating data from an external service
        // On failure, decrement retry count and possibly backoff before retrying
        int success = rand() % 2; // Mock success or failure

        if (success) break;

        retry_count--;
        time_t wait_time = 1 << (3 - retry_count); // Exponential back-off
        sleep(wait_time);
    }

    if (!retry_count) {
        fprintf(stderr, "Failed to fetch and validate data for UID %d\n", record->uid);
    }
