    int logical_channel_id;
    char* transmission_data; // Assume a simple string for demonstration.
} MAC_Transmission_Pdu;

// A utility function to validate the transmission data.
int validate_transmission_data(const char* data) {
    // Implement validation logic, e.g., non-empty, certain length, specific format.
    return data != NULL && strlen(data) > 0;
}

typedef struct {
    MAC_Transmission_Pdu *array;
    size_t capacity;
    size_t count;
} MAC_Transmission_Array;

void init_MAC_Transmission_Array(MAC_Transmission_Array *arr, size_t initial_capacity) {
    arr->capacity = initial_capacity;
    arr->count = 0;
    arr->array = (MAC_Transmission_Pdu*) malloc(initial_capacity * sizeof(MAC_Transmission_Pdu));
}

void free_MAC_Transmission_Array(MAC_Transmission_Array *arr) {
    for (size_t i = 0; i < arr->count; ++i) {
        free(arr->array[i].transmission_data);
    }
    free(arr->array);
    arr->capacity = 0;
    arr->count = 0;
}

void resize_MAC_Transmission_Array(MAC_Transmission_Array *arr, size_t new_capacity) {
    MAC_Transmission_Pdu* new_array = (MAC_Transmission_Pdu*) realloc(arr->array, new_capacity * sizeof(MAC_Transmission_Pdu));
    if (new_array != NULL) {
        arr->array = new_array;
        arr->capacity = new_capacity;
    } else {
        // Handle allocation failure gracefully
        fprintf(stderr, "Memory reallocation failed\n");
    }
}

int add_MAC_Transmission_Pdu(MAC_Transmission_Array *arr, MAC_Transmission_Pdu pdu) {
    if (!validate_transmission_data(pdu.transmission_data)) {
        return -1; // Invalid data.
    }

    if (arr->count >= arr->capacity) {
        resize_MAC_Transmission_Array(arr, arr->capacity == 0 ? 4 : arr->capacity * 2);
        if (arr->array == NULL) {
            return -1; // Memory allocation failed.
        }
    }

    arr->array[arr->count++] = pdu;
    return 0; // Success
}

int remove_MAC_Transmission_Pdu(MAC_Transmission_Array *arr, size_t index) {
    if (index >= arr->count) {
        return -1; // Index out of bounds.
    }

    free(arr->array[index].transmission_data);
    for (size_t i = index; i < arr->count - 1; ++i) {
        arr->array[i] = arr->array[i + 1];
    }
    --arr->count;

    if ((arr->capacity > 4) && (arr->count <= arr->capacity / 2)) {
        resize_MAC_Transmission_Array(arr, arr->capacity / 2);
    }

    return 0; // Success
}

int update_MAC_Transmission_Pdu(MAC_Transmission_Array *arr, size_t index, MAC_Transmission_Pdu new_pdu) {
    if (index >= arr->count || !validate_transmission_data(new_pdu.transmission_data)) {
        return -1; // Index out of bounds or invalid data.
    }

    free(arr->array[index].transmission_data);
    arr->array[index] = new_pdu;
    return 0; // Success
}

// Usage example:
int main() {
    MAC_Transmission_Array pdu_array;
    init_MAC_Transmission_Array(&pdu_array, 4);

    MAC_Transmission_Pdu pdu1 = {TYPE_A, 1, strdup("Data for PDU 1")};
    add_MAC_Transmission_Pdu(&pdu_array, pdu1);

    // Further usage...

    free_MAC_Transmission_Array(&pdu_array);
    return 0;
}
