}

int deserialize_from_file(const char *filename, DynamicArray *arr) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1;

    int count;
    fread(&count, sizeof(int), 1, file);
    for (int i = 0; i < count; ++i) {
        NFDataRecord *record = malloc(sizeof(NFDataRecord));
        fread(record, sizeof(NFDataRecord), 1, file);
        pthread_mutex_lock(&arr->lock);
        arr->records[i] = record;
        fetch_metadata(record); // Update metadata after loading
        pthread_mutex_unlock(&arr->lock);
    }

    fclose(file);
    return 0;
}

void free_dynamic_array(DynamicArray *arr) {
    pthread_mutex_lock(&arr->lock);
    for (int i = 0; i < arr->count; ++i) {
        if (arr->records[i]) {
            free(arr->records[i]);
        }
    }
    free(arr->records);
    pthread_mutex_unlock(&arr->lock);
    pthread_mutex_destroy(&arr->lock);
