#include <stdio.h>
#include <stdlib.h>

// Define a record structure with an int value and a pointer to long for offsets
typedef struct {
    int value;
    long *offset_ptr;
} Record;

// Function prototype
void* allocate_and_initialize(int max_size);

void* allocate_and_initialize(int max_size) {
    // Check if the requested size is valid
    if (max_size <= 0) {
        fprintf(stderr, "Error: Invalid maximum size.\n");
        return NULL;
    }

    // Dynamically allocate memory for offsets array of longs
    long *offsets = malloc(max_size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Memory allocation failed for offsets.\n");
        return NULL;
    }

    // Allocate memory for keys array of ints
    int *keys = malloc(max_size * sizeof(int));
    if (!keys) {
        free(offsets);  // Prevent memory leak
        fprintf(stderr, "Error: Memory allocation failed for keys.\n");
        return NULL;
    }

    // Allocate memory for records array and individual record structures
    Record *records = malloc(max_size * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        fprintf(stderr, "Error: Memory allocation failed for records.\n");
        return NULL;
    }

    // Initialize the arrays and structure pointers
    for (int i = 0; i < max_size; ++i) {
        keys[i] = 0;  // Initialize key array with zeros

        records[i].value = 0;  // Set default value in record

        // Allocate memory for each record's offset pointer and handle allocation failure
        records[i].offset_ptr = malloc(sizeof(long));
        if (!records[i].offset_ptr) {
            fprintf(stderr, "Error: Memory allocation failed for offset pointer at index %d.\n", i);

            // Free previously allocated resources to prevent leaks
            for (int j = 0; j < i; ++j) {
                free(records[j].offset_ptr);
            }
            free(keys);
            free(offsets);
            free(records);
            return NULL;
        }

        offsets[i] = 0;  // Initialize offset array with zeros

        records[i].offset_ptr[0] = offsets[i];  // Set the long pointer to point to current offset
    }

    // Return a pointer to a structure holding all allocations for ease of access
    typedef struct {
        long *offsets;
        int *keys;
        Record *records;
    } AllocatedMemory;

    AllocatedMemory *allocated_memory = malloc(sizeof(AllocatedMemory));
    if (!allocated_memory) {
        free(keys);
        free(offsets);
        for (int i = 0; i < max_size; ++i) {
            free(records[i].offset_ptr);
        }
        free(records);
        fprintf(stderr, "Error: Memory allocation failed for AllocatedMemory.\n");
        return NULL;
    }

    allocated_memory->offsets = offsets;
    allocated_memory->keys = keys;
    allocated_memory->records = records;

    return allocated_memory;
}

// Function to clear and deallocate the memory
void free_allocated_memory(void *ptr) {
    if (!ptr) return;

    AllocatedMemory *allocated_memory = (AllocatedMemory*) ptr;

    for (int i = 0; i < max_size; ++i) {
        free(allocated_memory->records[i].offset_ptr);
    }

    free(allocated_memory->keys);
    free(allocated_memory->offsets);
    free(allocated_memory->records);
    free(allocated_memory);
}
```

This code defines a function that dynamically allocates and initializes memory for an array of `long` offsets, an array of `int` keys, and an array of `record` structures. It includes error checking to handle allocation failures gracefully, and provides functionality to free the allocated memory once it is no longer needed. The solution ensures robustness against memory leaks by freeing all resources in case of any failure during allocation.']

