#include <time.h>

#define MAX_ENTRIES 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    node->data = *pdu;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

bool is_rnti_unique(Node* head, int rnti) {
    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            return false;
        }
        current = current->next;
    }
    return true;
}

void insert_node(Node** head, Node* node) {
    if (*head == NULL) {
        *head = node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
        node->prev = current;
    }
}

void remove_node(Node** head, Node* node) {
    if (*head == NULL || node == NULL) return;

    if (node->prev) {
        node->prev->next = node->next;
    } else {
        *head = node->next;
    }

    if (node->next) {
        node->next->prev = node->prev;
    }

    free(node);
}

int populate_nfa_list(Node** head, size_t initial_size, bool compact_periodically) {
    srand(time(NULL));
    Node* current = NULL;
    int entry_count = 0;

    while (entry_count < initial_size && entry_count < MAX_ENTRIES) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        // Ensure unique RNTI
        int rnti;
        do {
            rnti = rand() % 10000;
        } while (!is_rnti_unique(*head, rnti));

        pdu.RNTI = rnti;

        Node* new_node = create_node(&pdu);
        if (!new_node) return -1; // Memory allocation failed

        insert_node(head, new_node);
        current = new_node;
        entry_count++;

        // Compact periodically if enabled
        if (compact_periodically && entry_count % 10 == 0) {
            Node* temp = *head;
            while (temp != NULL) {
                Node* next = temp->next;
                remove_node(head, temp);
                free(temp);
                temp = next;
            }
            // Reinsert nodes as needed
        }
    }

    return entry_count;
}

void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    Node* list_head = NULL;
    int result = populate_nfa_list(&list_head, 50, true);

    if (result < 0) {
        fprintf(stderr, "Failed to populate the list\n");
    } else {
        printf("List populated with %d entries\n", result);
    }

    free_list(&list_head);
    return 0;
}
