    if (manager->size >= manager->capacity) {
        manager->capacity = manager->capacity ? 2 * manager->capacity : 4; // Start with size 4 if zero.
        manager->array = realloc(manager->array, manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!manager->array) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
    }
}

