#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_LEVEL 3

typedef struct Measurement {
    double latency;
    double throughput;
    int packet_loss;
} Measurement;

typedef struct NetworkPerformanceMetrics {
    time_t timestamp;
    char session_id[64];
    Measurement *measurements; // Pointer to dynamically allocated array
    size_t measurement_count;
    struct NetworkPerformanceMetrics *prev;
    struct NetworkPerformance Metrics *next;
} NetworkPerformanceMetrics;

typedef struct Node {
    NetworkPerformanceMetrics *metrics;
    struct Node *prev;
    struct Node *next;
} Node;

typedef struct DoublyLinkedList {
    Node *head;
    Node *tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

DoublyLinkedList* init_list(void) {
    DoublyLinkedList *list = malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

int custom_hash(const char* session_id) {
    unsigned long hash = 5381;
    int c;
    while ((c = *session_id++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % 10007;
}

int add_metrics(DoublyLinkedList* list, NetworkPerformanceMetrics* metrics) {
    if (!list || !metrics) return -1;

    pthread_mutex_lock(&list->lock);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->metrics = metrics;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }

    list->tail = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void cleanup_metrics(DoublyLinkedList* list, time_t retention_time) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        NetworkPerformanceMetrics *metrics = current->metrics;

        if (difftime(time(NULL), metrics->timestamp) > retention_time) {
            Node *to_delete = current;
            current = current->next;

            free(metrics->measurements);
            free(to_delete->metrics);
            free(to_delete);

            if (!current) list->tail = NULL;
            else current->prev = NULL;
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void log_message(int level, const char *message) {
    if (level > MAX_LOG_LEVEL) return;

    // Simulating logging
    printf("[%d] %s\n", level, message);
}

// A simple function to simulate periodic snapshot integration
void snapshot_to_storage(DoublyLinkedList* list) {
    log_message(1, "Starting snapshot");
    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        NetworkPerformanceMetrics *metrics = current->metrics;

        // Simulate storing metrics to external storage
        printf("Snapshotting session ID: %s with timestamp: %ld\n", 
               metrics->session_id, metrics->timestamp);

        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    log_message(1, "Completed snapshot");
}

void free_list(DoublyLinkedList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current) {
        NetworkPerformanceMetrics *metrics = current->metrics;

        free(metrics->measurements);
        free(metrics);

        Node *to_delete = current;
        current = current->next;
        free(to_delete);
    }

    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

```

