import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Level;
import java.util.logging.Logger;

public class LTEMessageManager {

    private static final Logger logger = Logger.getLogger(LTEMessageManager.class.getName());
    private static final int MAX_ACTIVE_MESSAGES = 1000; // Threshold for active messages
    private final ConcurrentHashMap<Integer, LTE_DL_CCCH_Message_Type1_T> messageMap;
    private final AtomicInteger activeMessageCount;

    public LTEMessageManager() {
        this.messageMap = new ConcurrentHashMap<>();
        this.activeMessageCount = new AtomicInteger(0);
    }

    public void initializeAndManageMessages(int numberOfMessages) {
        try {
            for (int i = 0; i < numberOfMessages; i++) {
                if (activeMessageCount.get() >= MAX_ACTIVE_MESSAGES) {
                    cleanupOldMessages();
                }

                int messageType = generateRandomMessageType();
                NAS_Message nasMessage = createNASMessage(messageType);

                LTE_DL_CCCH_Message_Type1_T message = new LTE_DL_CCCH_Message_Type1_T(new TLVEncoder(nasMessage));
                int messageId = System.identityHashCode(message); // Unique ID for the message

                boolean added = messageMap.putIfAbsent(messageId, message) == null;
                if (added) {
                    activeMessageCount.incrementAndGet();
                } else {
                    logger.log(Level.WARNING, "Failed to add a new message due to duplicate key.");
                }
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error initializing messages", e);
        }
