        if (!messageMap.isEmpty()) {
            Integer oldestKey = null; // Determine which key is the oldest
            LTE_DL_CCCH_Message_Type1_T removedMessage = messageMap.remove(oldestKey);
            if (removedMessage != null) {
                activeMessageCount.decrementAndGet();
                logger.log(Level.INFO, "Cleaned up a message to free resources.");
            }
        }
    }

    private int generateRandomMessageType() {
