typedef struct {
    int value;
} record;

int allocate_and_populate(long *offsets, int *keys, record **records, size_t num_elements, int key_range_min, int key_range_max) {
    if (num_elements <= 0 || key_range_min >= key_range_max) return -1;

    size_t total_memory = sizeof(long) * num_elements + sizeof(int) * num_elements + sizeof(record) * num_elements;

    if (total_memory > MAX_MEMORY_LIMIT) return -2;

    offsets = (long *)malloc(sizeof(long) * num_elements);
    keys = (int *)malloc(sizeof(int) * num_elements);
    *records = (record *)malloc(sizeof(record) * num_elements);

    if (!offsets || !keys || !(*records)) {
        free(offsets); 
        free(keys); 
        free(*records); 
        return -3;
    }

    srand((unsigned int)time(NULL));

    int collision_count = 0;
    for (size_t i = 0; i < num_elements; ++i) {
        offsets[i] = rand() % 1000000; // Example offset value
        keys[i] = -1;

        do {
            keys[i] = key_range_min + rand() % (key_range_max - key_range_min + 1);
            collision_count += check_collision(keys, i); 
        } while (check_collision(keys, i));

        (*records)[i].value = rand() % 1000; // Example record value
    }

    printf("Number of key collisions: %d\n", collision_count);

    return 0;
}

int check_collision(int *keys, size_t new_index) {
    for (size_t i = 0; i < new_index; ++i) {
        if (keys[i] == keys[new_index]) {
            return 1;
        }
    }
    return 0;
}

void free_resources(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}
