#define MAX_NODES 1000000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct SensorNode {
    int id;
    time_t timestamp;
    unsigned char data_validity_flags;
    float temperature_threshold;
    float humidity_threshold;
    struct SensorNode* next;  // For linked list structure
} SensorNode;

typedef struct {
    SensorNode* head;
    pthread_mutex_t lock;
} SensorNetworkPDU;

SensorNetworkPDU* createGraph() {
    SensorNetworkPDU* graph = (SensorNetworkPDU*)malloc(sizeof(SensorNetworkPDU));
    if (!graph) return NULL;
    graph->head = NULL;
    pthread_mutex_init(&graph->lock, NULL);
    return graph;
}

void freeGraph(SensorNetworkPDU* graph) {
    SensorNode* current = graph->head;
    while (current) {
        SensorNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&graph->lock);
    free(graph);
}

void addSensorNode(SensorNetworkPDU* graph, int id, unsigned char data_validity_flags,
                   float temperature_threshold, float humidity_threshold) {
    SensorNode* new_node = (SensorNode*)malloc(sizeof(SensorNode));
    if (!new_node) return;

    pthread_mutex_lock(&graph->lock);
    new_node->id = id;
    new_node->timestamp = time(NULL);
    new_node->data_validity_flags = data_validity_flags;
    new_node->temperature_threshold = temperature_threshold;
    new_node->humidity_threshold = humidity_threshold;
    new_node->next = graph->head;
    graph->head = new_node;
    pthread_mutex_unlock(&graph->lock);
}

void removeSensorNode(SensorNetworkPDU* graph, int id) {
    pthread_mutex_lock(&graph->lock);

    SensorNode *current = graph->head, *prev = NULL;

    while (current && current->id != id) {
        prev = current;
        current = current->next;
    }

    if (current) {  // Node found
        if (prev)
            prev->next = current->next;
        else
            graph->head = current->next;

        free(current);
    }

    pthread_mutex_unlock(&graph->lock);
}

void updateSensorNode(SensorNetworkPDU* graph, int id,
                      unsigned char data_validity_flags,
                      float temperature_threshold, float humidity_threshold) {
    pthread_mutex_lock(&graph->lock);

    SensorNode *current = graph->head;

    while (current && current->id != id) {
        current = current->next;
    }

    if (current) {  // Node found
        current->data_validity_flags = data_validity_flags;
        current->temperature_threshold = temperature_threshold;
        current->humidity_threshold = humidity_threshold;
    }

    pthread_mutex_unlock(&graph->lock);
}

void logGraph(SensorNetworkPDU* graph) {
    SensorNode *current = graph->head;

    while (current) {
        printf("Sensor ID: %d, Timestamp: %ld, Data Validity Flags: %u, "
               "Temperature Threshold: %.2f, Humidity Threshold: %.2f\n",
               current->id, current->timestamp,
               current->data_validity_flags,
               current->temperature_threshold,
               current->humidity_threshold);
        current = current->next;
    }
}

float getRandomThreshold() {
    return (rand() % 100) / 10.0;  // Random value between 0.0 and 10.0
}

void initializeRandomness() {
    srand((unsigned int)time(NULL));
}

int main() {
    SensorNetworkPDU* graph = createGraph();
    if (!graph) {
        fprintf(stderr, "Failed to create graph\n");
        return EXIT_FAILURE;
    }

    initializeRandomness();

    for (int i = 0; i < MAX_NODES / 10; ++i) {  // Add some nodes
        addSensorNode(graph, i,
                      (rand() % 256),  // Random data validity flags
                      getRandomThreshold(),
                      getRandomThreshold());
    }

    logGraph(graph);

    for (int i = 0; i < MAX_NODES / 10; ++i) {  // Remove some nodes
        removeSensorNode(graph, i);
    }

    freeGraph(graph);

    return EXIT_SUCCESS;
}
