    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);
}

// Function to resize the dynamic array when needed
void resizeDynamicArray(DynamicArray *da) {
    size_t new_capacity = da->capacity * 2;
    LTE_UESearchResult_T *new_array = (LTE_UESearchResult_T *)realloc(da->array, new_capacity * sizeof(LTE_UESearchResult_T));
    if (!new_array) {
        perror("Failed to reallocate memory for DynamicArray");
        exit(EXIT_FAILURE);
    }
    da->array = new_array;
    da->capacity = new_capacity;
}

// Function to add a new entry to the dynamic array
void addUEResult(DynamicArray *da, int ue_id, const char *pucch_config) {
    pthread_mutex_lock(&da->lock);

    if (da->size == da->capacity) {
        resizeDynamicArray(da);
    }

    LTE_UESearchResult_T new_entry;
    new_entry.UE_ID = ue_id;
    strncpy(new_entry.PUCCH_Configuration, pucch_config, sizeof(new_entry.PUCCH_Configuration));
    new_entry.SR_FLAG = rand() % 2 == 0;

    da->array[da->size++] = new_entry;

    pthread_mutex_unlock(&da->lock);
}

// Function to cleanup the dynamic array
void freeDynamicArray(DynamicArray *da) {
    pthread_mutex_destroy(&da->lock);
    free(da->array);
    da->array = NULL;
    da->capacity = 0;
    da->size = 0;
}

// Example function to simulate logging and monitoring
void logOperation(bool success, const char *message) {
    if (success) {
        printf("Success: %s\n", message);
    } else {
        fprintf(stderr, "Error: %s\n", message);
    }
}

int main() {
