#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Structure to hold session metadata and statistics.
typedef struct {
    char sessionId[64];
    time_t startTime;
    time_t endTime;
    int activeUsers;
    unsigned long bandwidthUsage; // in bytes
    int errorCode;
} SessionStats;

// Dynamic array structure for managing sessions.
typedef struct {
    SessionStats *sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} SessionManager;

// Function prototypes
SessionManager* create_session_manager(size_t initial_capacity);
void destroy_session_manager(SessionManager *manager);
int add_session(SessionManager *manager, const SessionStats *session);
int remove_session(SessionManager *manager, const char *sessionId);
size_t get_sessions_exceeding_duration(SessionManager *manager, time_t duration_threshold);
void log_session_lifecycle(const SessionStats *session, const char *action);

// Function implementations
SessionManager* create_session_manager(size_t initial_capacity) {
    SessionManager *manager = (SessionManager *)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->sessions = (SessionStats *)calloc(initial_capacity, sizeof(SessionStats));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_session_manager(SessionManager *manager) {
    if (manager) {
        free(manager->sessions);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_session(SessionManager *manager, const SessionStats *session) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        SessionStats *new_sessions = (SessionStats *)realloc(manager->sessions, new_capacity * sizeof(SessionStats));
        if (!new_sessions) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Failed to allocate memory
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }

    memcpy(&(manager->sessions[manager->count]), session, sizeof(SessionStats));
    manager->count++;

    log_session_lifecycle(session, "CREATED");

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int remove_session(SessionManager *manager, const char *sessionId) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strncmp(manager->sessions[i].sessionId, sessionId, sizeof(manager->sessions[i].sessionId)) == 0) {
            memmove(&(manager->sessions[i]), &(manager->sessions[i + 1]),
                    (manager->count - i - 1) * sizeof(SessionStats));
            manager->count--;

            log_session_lifecycle(&(manager->sessions[i]), "DELETED");

            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

size_t get_sessions_exceeding_duration(SessionManager *manager, time_t duration_threshold) {
    size_t count = 0;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        time_t sessionDuration = manager->sessions[i].endTime - manager->sessions[i].startTime;
        if (sessionDuration > duration_threshold) {
            count++;
        }
    }

    pthread_mutex_unlock(&manager->lock);

    return count;
}

void log_session_lifecycle(const SessionStats *session, const char *action) {
    // Placeholder for logging mechanism
    printf("Session %s: %s\n", session->sessionId, action);
    // Additional logic to compress and store logs in an external system.
}
```

### Key Considerations:
- **Thread Safety**: Use `pthread_mutex_t` to ensure safe concurrent access to the dynamic array.
- **Dynamic Resizing**: Double the capacity when adding sessions to manage growth efficiently.
- **Session Removal**: Implement efficient removal using `memmove`.
- **Logging Mechanism**: Simplified logging placeholder; integrate with external systems as needed.
- **Performance**: Use a mutex lock for synchronization, which may introduce some contention but ensures consistency. Consider more advanced techniques like read-write locks or lock-free data structures for further optimization if necessary.
- **Resource Management**: Ensure proper allocation and deallocation of memory to prevent leaks.

This code provides a foundation that can be extended with additional functionality such as periodic cleanup based on retention policies, optimized logging mechanisms, and integration with external data processing systems.']

