// Function prototypes
CRCList* create_crc_list(size_t max_size);
bool add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T new_data, unsigned long* rnti_set);
void free_crc_list(CRCList* list);

// Random number generator for CRCFLAG
static bool generate_random_crcflag() {
    return rand() % 2 == 0;
}

// Initialize the CRC List
CRCList* create_crc_list(size_t max_size) {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) {
        perror("Failed to allocate memory for CRCList");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    list->length = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add data to the list ensuring unique RNTI
bool add_to_crc_list(CRCList* list, NFAPI_CRC_INDICATION_PDU_T new_data, unsigned long* rnti_set) {
    if (pthread_mutex_lock(&list->lock) != 0) {
        perror("Mutex lock failed");
        return false;
    }

    // Check for unique RNTI
    for (unsigned long i = 0; i < list->length && rnti_set[i] != new_data.RNTI; ++i);

    if (rnti_set[i] == new_data.RNTI) {
        pthread_mutex_unlock(&list->lock);
        return false; // RNTI collision detected
    }

    // Add to the set of RNTIs
    rnti_set[list->length] = new_data.RNTI;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Failed to allocate memory for node");
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    newNode->data = new_data;
    newNode->next = list->head;
    list->head = newNode;
    list->length++;

    pthread_mutex_unlock(&list->lock);
    return true;
}

// Free the CRC List
void free_crc_list(CRCList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to populate the CRC List
void populate_crc_list(CRCList* list, size_t count, unsigned long max_rnti) {
    unsigned long rnti_set[count];
    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag generation
        pdu.RNTI = rand() % max_rnti;

        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();

        if (!add_to_crc_list(list, pdu, rnti_set)) {
            fprintf(stderr, "RNTI collision or memory allocation error for index: %zu\n", i);
            // Handle the overflow strategy here
        }
    }
}

int main() {
    size_t max_elements = 100;
    unsigned long max_rnti_value = 10000;

    CRCList* crc_list = create_crc_list(max_elements);
    populate_crc_list(crc_list, max_elements, max_rnti_value);

    // Free the list at the end
    free_crc_list(crc_list);

    return 0;
}
