typedef struct {
    int context_id;  // Unique identifier for the context
    LMAC_CONFIG lmac_config;
    MAC_COMMANDS* mac_commands;
} MAC_CONTEXT_T;

typedef struct {
    MAC_CONTEXT_T** array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

// Function to initialize a dynamic array
void init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    da->array = malloc(initial_capacity * sizeof(MAC_CONTEXT_T*));
    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);
}

// Function to resize the dynamic array
void resize_dynamic_array(DynamicArray *da);

// Function to check if LMAC_CONFIG is valid
int is_lmac_config_valid(const LMAC_CONFIG* config) {
    // Assume this function checks against external configuration service
    return config && config->valid;
}

// Function to add a new MAC_CONTEXT_T structure to the array
int add_mac_context(DynamicArray *da, MAC_CONTEXT_T *context) {
    pthread_mutex_lock(&da->mutex);

    if (!is_lmac_config_valid(&context->lmac_config)) {
        pthread_mutex_unlock(&da->mutex);
        return -1; // Invalid LMAC_CONFIG
    }

    if (context->mac_commands == NULL || context->mac_commands->command == NULL) {
        pthread_mutex_unlock(&da->mutex);
        return -2; // Empty MAC_COMMANDS list
    }

    if (da->size >= da->capacity) {
        resize_dynamic_array(da);
    }

    da->array[da->size++] = context;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

// Function to remove a MAC_CONTEXT_T structure by index
int remove_mac_context(DynamicArray *da, size_t index) {
    pthread_mutex_lock(&da->mutex);

    if (index >= da->size) {
        pthread_mutex_unlock(&da->mutex);
        return -1; // Index out of bounds
    }

    free(da->array[index]); // Free the memory associated with MAC_CONTEXT_T
    memmove(&da->array[index], &da->array[index + 1],
            (da->size - index - 1) * sizeof(MAC_CONTEXT_T*));
    da->size--;

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

// Function to search for a MAC_CONTEXT_T by context_id
int find_mac_context(DynamicArray *da, int context_id, size_t *index) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i]->context_id == context_id) {
            *index = i;
            return 0;
        }
    }
    return -1; // Not found
}

// Function to update a MAC_CONTEXT_T structure
int update_mac_context(DynamicArray *da, int context_id, LMAC_CONFIG new_config, MAC_COMMANDS* new_commands) {
    pthread_mutex_lock(&da->mutex);

    size_t index;
    if (find_mac_context(da, context_id, &index) != 0) {
        pthread_mutex_unlock(&da->mutex);
        return -1; // Not found
    }

    if (!is_lmac_config_valid(&new_config)) {
        pthread_mutex_unlock(&da->mutex);
        return -2; // Invalid new LMAC_CONFIG
    }

    MAC_CONTEXT_T* context = da->array[index];
    free(context->mac_commands); // Free existing commands list
    context->lmac_config = new_config;
    context->mac_commands = new_commands;

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

// Function to resize the dynamic array
void resize_dynamic_array(DynamicArray *da) {
    size_t new_capacity = da->capacity * 2;
    MAC_CONTEXT_T** new_array = realloc(da->array, new_capacity * sizeof(MAC_CONTEXT_T*));
    if (!new_array) {
        // Handle memory allocation failure
        return;
    }
    da->array = new_array;
    da->capacity = new_capacity;
}

// Function to free the dynamic array resources
void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);

    for (size_t i = 0; i < da->size; ++i) {
        free(da->array[i]->mac_commands); // Free commands list
        free(da->array[i]); // Free MAC_CONTEXT_T structure
    }
    free(da->array);
    pthread_mutex_unlock(&da->mutex);

    pthread_mutex_destroy(&da->mutex);
}

// Main function for testing purposes (not part of the library)
int main() {
    DynamicArray da;
    init_dynamic_array(&da, INITIAL_SIZE);

    // Example usage: Add, remove, update, search

    free_dynamic_array(&da);
    return 0;
}
