// Define a structure for an Activity Type
typedef struct {
    char type[50];
} ActivityType;

// Define a structure for User Activity Log Entry
typedef struct LogEntry {
    time_t timestamp;
    char userId[50];
    int activityCount;
    ActivityType *activities;
    struct LogEntry *prev, *next;
} LogEntry;

// Doubly Linked List for managing logs
typedef struct {
    LogEntry *head, *tail;
    pthread_mutex_t lock;  // Mutex for thread-safe operations
} LogManager;

// Function to create a new log entry
LogEntry* create_log_entry(const char *userId, const ActivityType *activities, int activityCount) {
    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    if (!entry) return NULL;

    time(&entry->timestamp);
    strncpy(entry->userId, userId, sizeof(entry->userId));
    entry->activityCount = activityCount;
    entry->activities = (ActivityType*) malloc(activityCount * sizeof(ActivityType));
    memcpy(entry->activities, activities, activityCount * sizeof(ActivityType));

    entry->prev = entry->next = NULL;
    return entry;
}

// Function to initialize the log manager
LogManager* init_log_manager() {
    LogManager *manager = (LogManager *)malloc(sizeof(LogManager));
    if (!manager) return NULL;

    manager->head = manager->tail = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to add a new log entry
void add_log_entry(LogManager *manager, const char *userId, const ActivityType *activities, int activityCount) {
    pthread_mutex_lock(&manager->lock);

    LogEntry *newEntry = create_log_entry(userId, activities, activityCount);
    if (!newEntry) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }

    if (manager->tail) {
        manager->tail->next = newEntry;
        newEntry->prev = manager->tail;
        manager->tail = newEntry;
    } else {
        manager->head = manager->tail = newEntry;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to remove a log entry
void remove_log_entry(LogManager *manager, LogEntry *entry) {
    pthread_mutex_lock(&manager->lock);

    if (entry->prev)
        entry->prev->next = entry->next;
    else
        manager->head = entry->next;

    if (entry->next)
        entry->next->prev = entry->prev;
    else
        manager->tail = entry->prev;

    free(entry->activities);
    free(entry);

    pthread_mutex_unlock(&manager->lock);
}

// Prune function to periodically remove old entries based on a retention policy
void prune_logs(LogManager *manager, time_t currentTime) {
    pthread_mutex_lock(&manager->lock);

    LogEntry *current = manager->head;
    while (current) {
        // Define the retention time period in seconds
        if (difftime(currentTime, current->timestamp) > 86400 * 7) { // Example: retain logs for 7 days
            LogEntry *toDelete = current;
            current = current->next;
            remove_log_entry(manager, toDelete);
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Function to retrieve and summarize activities within a given time range for a user
void get_activity_summary(LogManager *manager, const char *userId, time_t startTime, time_t endTime, ActivityType **summaryActivities, int *activityCount) {
    pthread_mutex_lock(&manager->lock);

    LogEntry *current = manager->head;
    while (current) {
        if ((strcmp(current->userId, userId) == 0) &&
            (difftime(current->timestamp, startTime) >= 0) &&
            (difftime(endTime, current->timestamp) >= 0)) {

            // Aggregate activities - pseudocode for aggregation
            for (int i = 0; i < current->activityCount; ++i) {
                // Add logic to aggregate similar activity types into summaryActivities
            }
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Periodic prune function, called by a separate thread periodically
void *prune_thread_function(void *arg) {
    LogManager *manager = (LogManager *)arg;
    while (1) {
        time_t currentTime;
        time(&currentTime);
        prune_logs(manager, currentTime);

        // Sleep for defined period before next prune
        sleep(3600);  // Example: run every hour
    }
    return NULL;
}

// Initialize the pruning thread
void start_prune_thread(LogManager *manager) {
    pthread_t pruneThread;
    pthread_create(&pruneThread, NULL, prune_thread_function, (void*) manager);
}

// Function to cleanup and free resources
void destroy_log_manager(LogManager *manager) {
    while (manager->head) {
        remove_log_entry(manager, manager->head);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);

    // Note: Pruning thread should be properly terminated in a real-world scenario.
}

// Main function demonstrating the usage
int main() {
    LogManager *logManager = init_log_manager();
    start_prune_thread(logManager);

    ActivityType activities[] = { {"login"}, {"purchase"} };
    add_log_entry(logManager, "user123", activities, 2);

    // Add more log entries and operations here...

    destroy_log_manager(logManager);
    return 0;
}
