typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

#define INITIAL_CAPACITY 100
#define MAX_CAPACITY 10000

DynamicArray* create_dynamic_array() {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->count = 0;
    da->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&da->mutex, NULL);

    return da;
}

void resize_array(DynamicArray* da) {
    size_t new_capacity = (da->capacity * 2 > MAX_CAPACITY) ? MAX_CAPACITY : da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)aligned_realloc(da->array, 64, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        fprintf(stderr, "Memory allocation failed during resize.\n");
        exit(EXIT_FAILURE);
    }

    da->array = new_array;
    da->capacity = new_capacity;
}

int add_pdu(DynamicArray* da, uint16_t rx_ue_info_tag, uint32_t rnti) {
    pthread_mutex_lock(&da->mutex);

    if (da->count == da->capacity) {
        resize_array(da);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &da->array[da->count];
    pdu->RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    da->count++;
    pthread_mutex_unlock(&da->mutex);

    return 0; // Success
}

void free_dynamic_array(DynamicArray* da) {
    if (da) {
        pthread_mutex_destroy(&da->mutex);
        if (da->array) {
            free(da->array);
        }
        free(da);
    }
}
