int initialize_nas_messages(LTE_NAS_EMM_Message *messages, size_t count) {
    if (messages == NULL || count == 0) return -1;

    for (size_t i = 0; i < count; ++i) {
        messages[i].NAS_MESSAGE_ID = rand() % 100;
        messages[i].MME_UE_S1AP_ID = rand() % 1000;
        snprintf(messages[i].EMM_Procedure_Type, sizeof(messages[i].EMM_Procedure_Type), "Procedure_%zu", i);
    }
    return 0;
}

int checksum(LTE_NAS_EMM_Message *messages, size_t count) {
    int sum = 0;
    for (size_t i = 0; i < count; ++i) {
        sum += messages[i].NAS_MESSAGE_ID + messages[i].MME_UE_S1AP_ID +
               strlen(messages[i].EMM_Procedure_Type);
    }
    return sum % 256;
}

int initialize_crc_indications(NFAPI_CRC_INDICATION_PDU_T *indicators, size_t count) {
    if (indicators == NULL || count == 0) return -1;

    for (size_t i = 0; i < count; ++i) {
        indicators[i].UE_Index = i;
        indicators[i].CRC_INDICATION_REL8_TAG.RX_UE_INFORMATION_TAG = rand() % 10000;
        indicators[i].CRC_INDICATION_REL8_TAG.RNTI = rand() % 100000;
        indicators[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }
    return 0;
}

int verify_and_retry(int (*func)(void *), void *data, size_t count, int expected_checksum) {
    for (int retries = 0; retries < MAX_RETRIES; ++retries) {
        pthread_mutex_lock(&lock);
        int result = func(data);

        if (result == 0 && checksum((LTE_NAS_EMM_Message *)data, count) == expected_checksum) {
            pthread_mutex_unlock(&lock);
            return 0;
        }

        pthread_mutex_unlock(&lock);
    }
    return -1; // Failure after retries
}

int main() {
    srand(time(NULL));

    size_t nas_count = 100;
    LTE_NAS_EMM_Message *nas_messages = malloc(nas_count * sizeof(LTE_NAS_EMM_Message));
    if (nas_messages == NULL) return -1;

    int expected_checksum = checksum(nas_messages, nas_count);

    if (verify_and_retry(initialize_nas_messages, nas_messages, nas_count, expected_checksum) != 0) {
        printf("Failed to initialize NAS messages after retries.\n");
        free(nas_messages);
        return -1;
    }

    size_t crc_count = MAX_UE;
    NFAPI_CRC_INDICATION_PDU_T *crc_indications = malloc(crc_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indications == NULL) {
        free(nas_messages);
        return -1;
    }

    pthread_t threads[MAX_UE];
    for (size_t i = 0; i < crc_count; ++i) {
        int ret = pthread_create(&threads[i], NULL, (void *(*)(void *))initialize_crc_indications,
                                 &crc_indications[i]);
        if (ret != 0) break;
    }

    for (size_t i = 0; i < crc_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(nas_messages);
    free(crc_indications);

    return 0;
}
