        pdu->CRC_INDICATION_REL8_TAG[i] = rand() % 256;
    }
    pdu->CRCFLAG = rand() % 2;
}

// Function to encode and send a PDU
void *worker_thread(void *arg) {
    PduManager *manager = (PduManager *)arg;

    while (!manager->shutdown_flag) {
        pthread_mutex_lock(&manager->lock);

        while (manager->used == 0 && !manager->shutdown_flag) {
            pthread_cond_wait(&manager->cond, &manager->lock);
        }

        if (manager->shutdown_flag) {
            pthread_mutex_unlock(&manager->lock);
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[0];
        init_pdu(pdu);

        // Simulate encoding and sending
        printf("Encoded PDU with RX_UE_INFORMATION_TAG: %d\n", pdu->RX_UE_INFORMATION_TAG);

        memmove(manager->array, manager->array + 1, (manager->used - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        --manager->used;

        if (manager->used == manager->size / 4 && manager->size > 10) {
            resize_array(manager);
        }

        pthread_cond_signal(&manager->cond);
        pthread_mutex_unlock(&manager->lock);

        usleep(1000); // Simulate work
    }
    return NULL;
}

// Function to add a new PDU
void add_pdu(PduManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->used == manager->size) {
        resize_array(manager);
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    init_pdu(&pdu);

    manager->array[manager->used++] = pdu;

    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->lock);
}

// Function to start worker threads
void start_workers(PduManager *manager) {
    for (int i = 0; i < manager->worker_count; ++i) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, worker_thread, manager) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }
}

// Function to stop worker threads
void stop_workers(PduManager *manager) {
    pthread_mutex_lock(&manager->lock);
    manager->shutdown_flag = 1;
    pthread_cond_broadcast(&manager->cond);
    pthread_mutex_unlock(&manager->lock);

    for (int i = 0; i < manager->worker_count; ++i) {
        pthread_join(thread, NULL);
    }
}

// Main function to demonstrate usage
int main() {
    PduManager manager;
    init_manager(&manager);

    start_workers(&manager);

    // Simulate adding PDUs
    for (int i = 0; i < 100000; ++i) {
        add_pdu(&manager);
        usleep(10); // Adjust based on system capabilities
    }

    stop_workers(&manager);
    free_manager(&manager);

    return 0;
}
```

