#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_RECORDS 1000
#define RECORD_STRING_SIZE 50
#define METADATA_SIZE 20
#define CRC_FLAG_RANGE (1 << 16)
#define RANDOM_INT_MIN 0
#define RANDOM_INT_MAX 1000

typedef struct {
    int rnti;
    int rx_ue_information_tag;
    unsigned short crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int value;
    char string_repr[RECORD_STRING_SIZE];
    time_t timestamp;
    char *metadata;
} Record;

typedef struct {
    long offset;
} OffsetStruct;

typedef struct {
    int key;
} KeyStruct;

// Global variables and mutex for thread safety
Record *records = NULL;
OffsetStruct *offsets = NULL;
KeyStruct *keys = NULL;
char **metadatas = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void free_resources() {
    if (records) free(records);
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (metadatas) {
        for (int i = 0; i < MAX_RECORDS; ++i) free(metadatas[i]);
        free(metadatas);
    }
}

void log_error(const char *message) {
    // Fallback mechanism: print to stderr
    fprintf(stderr, "Error: %s\n", message);
}

int generate_unique_metadata(char *metadata_buffer, size_t buffer_size, int record_index) {
    snprintf(metadata_buffer, buffer_size, "meta_%d", record_index); // Simple unique metadata generation
    return 1; // Assume success for simplicity
}

void create_records(int n) {
    pthread_mutex_lock(&lock);

    records = malloc(n * sizeof(Record));
    offsets = malloc(n * sizeof(OffsetStruct));
    keys = malloc(n * sizeof(KeyStruct));
    metadatas = malloc(n * sizeof(char *));

    if (!records || !offsets || !keys || !metadatas) {
        log_error("Memory allocation failed");
        free_resources();
        pthread_mutex_unlock(&lock);
        return;
    }

    for (int i = 0; i < n; ++i) {
        offsets[i].offset = rand() % (1 << 20); // Example offset
        keys[i].key = rand() % RANDOM_INT_MAX + RANDOM_INT_MIN;

        records[i].value = rand() % RANDOM_INT_MAX + RANDOM_INT_MIN;
        snprintf(records[i].string_repr, RECORD_STRING_SIZE, "Value: %d", records[i].value);
        records[i].timestamp = time(NULL);

        metadatas[i] = malloc(METADATA_SIZE * sizeof(char));
        if (!metadatas[i]) {
            log_error("Metadata allocation failed");
            free_resources();
            pthread_mutex_unlock(&lock);
            return;
        }

        generate_unique_metadata(metadatas[i], METADATA_SIZE, i);

        // Ensure monotonically increasing timestamps
        if (i > 0 && records[i].timestamp <= records[i - 1].timestamp) {
            records[i].timestamp = records[i - 1].timestamp + 1;
        }
    }

    pthread_mutex_unlock(&lock);
}

void archive_old_records(int age_threshold_seconds) {
    time_t current_time = time(NULL);

    pthread_mutex_lock(&lock);

    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (current_time - records[i].timestamp > age_threshold_seconds) {
            // Archive logic: mark as archived and free memory
            printf("Archiving record %d\n", i);
            free(metadatas[i]);
            metadatas[i] = NULL;
        }
    }

    pthread_mutex_unlock(&lock);
}

void* periodic_archiver(void *arg) {
    int age_threshold_seconds = *(int *)arg;

    while (1) {
        archive_old_records(age_threshold_seconds);
        sleep(60); // Archive every minute
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t archiver_thread;
    int age_threshold_seconds = 3600; // Example threshold: one hour

    create_records(MAX_RECORDS);

    if (pthread_create(&archiver_thread, NULL, periodic_archiver, &age_threshold_seconds) != 0) {
        log_error("Failed to create archiver thread");
    }

    pthread_join(archiver_thread, NULL);

    free_resources();
    return 0;
}
