}

// Function to serialize the structures into a binary format
size_t serialize_pdu(const NFAPI_CRC_INDICATION_PDU_T *pdu, uint8_t **buffer) {
    size_t total_size = sizeof(uint32_t) + sizeof(uint16_t) + sizeof(uint8_t);

    if (!pdu || !buffer) return 0;
    *buffer = (uint8_t *)malloc(total_size);
    if (*buffer == NULL) {
        log_error("Failed to allocate memory for serialization");
        return 0;
    }

    // Copy data into buffer, considering endianness
    uint32_t ue_tag_be = __builtin_bswap32(pdu->RX_UE_INFORMATION_TAG);
    uint16_t rnti_be = __builtin_bswap16(pdu->RNTI);

    memcpy(*buffer, &ue_tag_be, sizeof(uint32_t));
    memcpy(*buffer + sizeof(uint32_t), &rnti_be, sizeof(uint16_t));
    memcpy(*buffer + sizeof(uint32_t) + sizeof(uint16_t), &pdu->CRC_INDICATION_REL8_TAG.CRCFLAG, sizeof(uint8_t));

    return total_size;
}

// Function to deserialize binary data back into structures
NFAPI_CRC_INDICATION_PDU_T *deserialize_pdu(const uint8_t *buffer, size_t buffer_size) {
    if (!buffer || buffer_size != (sizeof(uint32_t) + sizeof(uint16_t) + sizeof(uint8_t))) {
        log_error("Invalid buffer or size for deserialization");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        log_error("Failed to allocate memory for PDU structure");
        return NULL;
    }

    uint32_t ue_tag_be, rnti_be;

    memcpy(&ue_tag_be, buffer, sizeof(uint32_t));
    memcpy(&rnti_be, buffer + sizeof(uint32_t), sizeof(uint16_t));

    pdu->RX_UE_INFORMATION_TAG = __builtin_bswap32(ue_tag_be);
    pdu->RNTI = __builtin_bswap16(rnti_be);
    memcpy(&pdu->CRC_INDICATION_REL8_TAG.CRCFLAG, buffer + sizeof(uint32_t) + sizeof(uint16_t), sizeof(uint8_t));

    return pdu;
}

// Main function to allocate and populate the array
NFAPI_CRC_INDICATION_PDU_T *allocate_and_populate_pdu_array(size_t num_pdus) {
    if (num_pdus == 0 || num_pdus > 10000) {
