// Define a node for the dynamic list.
typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode *next;
} ListNode;

// Define the list structure with a mutex for thread safety.
typedef struct {
    ListNode *head;
    pthread_mutex_t lock;
} CRCList;

// Function to initialize the CRCList
int initCRCList(CRCList **list) {
    if (!list) return -1;

    *list = (CRCList *)malloc(sizeof(CRCList));
    if (!*list) return -1; // Memory allocation failure

    (*list)->head = NULL;
    if (pthread_mutex_init(&((*list)->lock), NULL) != 0) {
        free(*list);
        return -1; // Mutex initialization failed
    }

    return 0; // Success
}

// Function to add an item to the list.
int addItem(CRCList *list, int rxUEInfoTag, int rnti, unsigned char crcFlag) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    ListNode *newNode = (ListNode *)malloc(sizeof(ListNode));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    newNode->data.RX_UE_INFORMATION_TAG = rxUEInfoTag;
    newNode->data.RNTI = rnti;
    newNode->data.crcTag.CRCFLAG = crcFlag;
    newNode->next = list->head;
    list->head = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Function to free the list and its resources.
void freeCRCList(CRCList *list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    ListNode *current = list->head;
    while (current) {
        ListNode *nextNode = current->next;
        free(current);
        current = nextNode;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example function to initialize and manage the dynamic list.
void manageDynamicList(int *longOffsets, int longOffsetCount, int *keys, int keyCount) {
