#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
import "lock_manager.h"  // Assume this provides necessary locking mechanisms
import "metric_collector.h" // Assume this provides necessary metric collection functionalities

#define INITIAL_CAPACITY 1024
#define FAILURE_INTERVAL_MS 1000

typedef struct {
    int valid;             // RX_UE_INFORMATION_TAG validity flag
    unsigned int RNTI;
    int CRCFLAG;           // Randomly set CRC indication
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int failure_count;
    unsigned long last_report_time_ms;
} CRCListManager;

static void initialize_list_manager(CRCListManager* manager) {
    manager->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->capacity = INITIAL_CAPACITY;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->failure_count = 0;
    manager->last_report_time_ms = current_millis(); // Assume this function gives the current time in ms
}

static void resize_list(CRCListManager* manager) {
    size_t new_capacity = manager->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_data) {
        fprintf(stderr, "Out of memory\n");
        // Handle error: continue with reduced capacity or log and exit
        return;
    }

    manager->data = new_data;
    manager->capacity = new_capacity;
}

static void report_failure_metric(CRCListManager* manager) {
    unsigned long current_time_ms = current_millis();
    if (current_time_ms - manager->last_report_time_ms >= FAILURE_INTERVAL_MS) {
        metric_collector_report(manager->failure_count); // Assume this function reports the failure count
        manager->failure_count = 0;
        manager->last_report_time_ms = current_time_ms;
    }
}

void add_crc_indication(CRCListManager* manager, unsigned int rnti, int valid) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        resize_list(manager);
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &manager->data[manager->count++];
    pdu->RNTI = rnti;
    pdu->valid = valid;
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    if (!pdu->valid) {
        manager->failure_count++;
    }

    report_failure_metric(manager);

    pthread_mutex_unlock(&manager->lock);
}

void get_crc_indications(CRCListManager* manager, NFAPI_CRC_INDICATION_PDU_T** out_data, size_t* out_count) {
    pthread_mutex_lock(&manager->lock);
    *out_data = manager->data;
    *out_count = manager->count;
    pthread_cond_wait(&manager->cond, &manager->lock); // Wait for new data to process
    pthread_mutex_unlock(&manager->lock);
}

void cleanup_list_manager(CRCListManager* manager) {
    free(manager->data);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
}

int main() {
    CRCListManager manager;
    initialize_list_manager(&manager);

    // Simulate adding and retrieving data
    for (int i = 0; i < 10000; ++i) {
        add_crc_indication(&manager, i, rand() % 2); // Random validity
    }

    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
    get_crc_indications(&manager, &data, &count);

    // Further processing with 'data' and 'count'

    cleanup_list_manager(&manager);
    return 0;
}
