        }

        if (!ip_address) {
            fprintf(stderr, "Failed to resolve hostname: %s\n", pdu->hostname);
        }
    }

    return NULL;
}

u_char* get_ip_from_cache(char* hostname) {
    pthread_mutex_lock(&cache_mutex);

    CacheEntry* current = cache_head;
    while (current != NULL) {
        if (strcmp(current->hostname, hostname) == 0) {
            pthread_mutex_unlock(&cache_mutex);
            return current->ip_address;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&cache_mutex);
    return NULL;
}

void add_to_cache(char* hostname, u_char* ip_address) {
    pthread_mutex_lock(&cache_mutex);

    if (!cache_head || cache_size == 0) {
        CacheEntry* new_entry = (CacheEntry*)malloc(sizeof(CacheEntry));
        strcpy(new_entry->hostname, hostname);
        memcpy(new_entry->ip_address, ip_address, 4);
        time_t now = time(NULL);
        new_entry->timestamp = now;
        new_entry->next = cache_head;
        cache_head = new_entry;

        if (cache_size > 0) {
            cache_size--;
        }

        pthread_mutex_unlock(&cache_mutex);
        return;
    }

    // Implement LRU eviction
    CacheEntry* current = cache_head;
    CacheEntry* prev = NULL;

    while (current != NULL && current->timestamp < time(NULL) - (60 * 5)) { // Evict entries older than 5 minutes
        if (!prev) {
            cache_head = current->next;
        } else {
            prev->next = current->next;
        }
        CacheEntry* to_delete = current;
        current = current->next;

        free(to_delete);
    }

    CacheEntry* new_entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    strcpy(new_entry->hostname, hostname);
    memcpy(new_entry->ip_address, ip_address, 4);
    time_t now = time(NULL);
    new_entry->timestamp = now;
    new_entry->next = cache_head;
    cache_head = new_entry;

    pthread_mutex_unlock(&cache_mutex);
}

