// Java method to calculate MD5 hash
extern "C" JNIEXPORT jstring JNICALL
Java_MyClass_calculateMD5Hash(JNIEnv *env, jobject obj, jstring input) {
    const char *str = env->GetStringUTFChars(input, nullptr);

    unsigned char digest[MD5_DIGEST_LENGTH];
    std::vector<char> buffer(1024); // Buffer for large strings

    MD5_CTX ctx;
    MD5_Init(&ctx);

    size_t length = strlen(str);
    if (length < 1024) {
        MD5_Update(&ctx, str, static_cast<unsigned int>(length));
    } else {
        size_t processed = 0;
        while (processed < length) {
            size_t to_read = std::min(length - processed, buffer.size());
            env->GetStringRegion(input, processed / sizeof(jchar), to_read / sizeof(jchar), &buffer[0]);
            MD5_Update(&ctx, &buffer[0], static_cast<unsigned int>(to_read));
            processed += to_read;
        }
    }

    MD5_Final(digest, &ctx);
    env->ReleaseStringUTFChars(input, str);

    char md5_str[33];
    for (int i = 0; i < 16; ++i) {
        sprintf(&md5_str[i * 2], "%02x", static_cast<int>(digest[i]));
    }
    md5_str[32] = '\0';

    return env->NewStringUTF(md5_str);
}
