#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>

#define MAX_CONTEXTS 1024
#define POOL_SIZE 64

typedef struct {
    int RNTI;
    int RX_UE_INFORMATION_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t pdu_count;
} LMAC_CONFIG;

typedef struct {
    LMAC_CONFIG config;
} MAC_CONTEXT_T;

typedef struct MemoryPool {
    void* blocks[POOL_SIZE];
    pthread_mutex_t lock;
    int available;
} MemoryPool;

MemoryPool mac_context_pool = { .blocks = {0}, .available = POOL_SIZE, .lock = PTHREAD_MUTEX_INITIALIZER };

void* memory_pool_alloc(size_t size) {
    pthread_mutex_lock(&mac_context_pool.lock);
    if (mac_context_pool.available == 0) {
        pthread_mutex_unlock(&mac_context_pool.lock);
        return malloc(size); // Fallback to system allocation
    }
    void* block = mac_context_pool.blocks[--mac_context_pool.available];
    pthread_mutex_unlock(&mac_context_pool.lock);
    return block;
}

void memory_pool_free(void* ptr) {
    pthread_mutex_lock(&mac_context_pool.lock);
    if (mac_context_pool.available < POOL_SIZE) {
        mac_context_pool.blocks[mac_context_pool.available++] = ptr;
    }
    pthread_mutex_unlock(&mac_context_pool.lock);
}

MAC_CONTEXT_T* create_mac_context(size_t pdu_count) {
    MAC_CONTEXT_T* context = memory_pool_alloc(sizeof(MAC_CONTEXT_T));
    if (!context) return NULL;

    context->config.pdus = malloc(pdu_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!context->config.pdus) {
        memory_pool_free(context);
        return NULL;
    }

    for (size_t i = 0; i < pdu_count; ++i) {
        context->config.pdus[i].RNTI = rand(); // Random RNTI
        context->config.pdus[i].RX_UE_INFORMATION_TAG = rand(); // Random tag
        context->config.pdus[i].CRCFLAG = rand() & 1; // Random CRCFLAG
    }

    context->config.pdu_count = pdu_count;
    return context;
}

void destroy_mac_context(MAC_CONTEXT_T* context) {
    if (context) {
        free(context->config.pdus);
        memory_pool_free(context);
    }
}

// Example usage
int main() {
    // Initialize pool with dummy blocks for simplicity
    memset(mac_context_pool.blocks, 0, sizeof(void*) * POOL_SIZE);

    MAC_CONTEXT_T* context = create_mac_context(10);
    if (context) {
        printf("MAC Context created successfully.\n");
        destroy_mac_context(context);
    } else {
        fprintf(stderr, "Failed to create MAC Context.\n");
    }

    return 0;
}
```

