void free_resources(char **ids, size_t *sizes, TextBlock **blocks, int count) {
    for (int i = 0; i < count; ++i) {
        free(ids[i]);
        free(blocks[i]->data);
        free(blocks[i]);
    }
    free(ids);
    free(sizes);
    free(blocks);
