TextBlock* allocate_blocks(char **ids, size_t *sizes, int count, char fill_char, size_t max_block_size) {
    TextBlock *blocks = malloc(count * sizeof(TextBlock));
    if (!blocks) return NULL;

    for (int i = 0; i < count; ++i) {
        blocks[i].data = malloc(sizes[i] > max_block_size ? max_block_size : sizes[i]);
        if (!blocks[i].data) {
            free_resources(ids, sizes, blocks, i);
            return NULL;
        }
        for (size_t j = 0; j < sizes[i]; ++j) {
            blocks[i].data[j] = fill_char;
        }
    }

    return blocks;
}

