import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class HashProcessor {

    private static final Logger logger = Logger.getLogger(HashProcessor.class.getName());
    private final Map<String, String> cache;
    private boolean cacheEnabled;

    // Load cache size from configuration
    private int cacheSize = loadCacheSizeFromConfig();

    public HashProcessor(boolean cacheEnabled) {
        this.cacheEnabled = cacheEnabled;
        this.cache = new LinkedHashMap<String, String>(cacheSize, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, String> eldest) {
                return size() > cacheSize;
            }
        };
    }

    public String processInputForHashing(String input) {
        if (input == null || input.trim().isEmpty()) {
            logger.log(Level.WARNING, "Received empty or null input.");
            return null;
        }

        try {
            // Check cache first
            if (cacheEnabled && cache.containsKey(input)) {
                String cachedHash = cache.get(input);
                logger.info("Cache hit for input: " + input);
                logProcessedInput(input, cachedHash, "CACHE_HIT");
                return cachedHash;
            }

            // Compute MD5 hash
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes());

            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }

            String hashValue = sb.toString();

            // Store in cache
            if (cacheEnabled) {
                cache.put(input, hashValue);
            }

            logProcessedInput(input, hashValue, "SUCCESS");
            return hashValue;
        } catch (NoSuchAlgorithmException e) {
            logger.log(Level.SEVERE, "MD5 algorithm not found.", e);
            return null;
        }
    }

    private void logProcessedInput(String input, String hash, String status) {
        // Log the processed input with hash and status
        logger.info("Processed Input: " + input + ", Hash: " + hash + ", Status: " + status);

        // Assume this method integrates with an existing system to append logs
    }

    private int loadCacheSizeFromConfig() {
        // Simulate loading cache size from a configuration file
        return 100; // Default size
    }

    public static void main(String[] args) {
        HashProcessor processor = new HashProcessor(true);

        // Example usage
        String input = "exampleString";
        String hashValue = processor.processInputForHashing(input);
        System.out.println("MD5 Hash: " + hashValue);
    }
}
