#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

typedef struct {
    int TransportChannelID;
    uint16_t RNTI;
    uint8_t CRCFlag; // Initialized based on a hash of identifiers
} LTE_Uu_TransportChannelInfo;

typedef struct {
    LTE_Uu_TransportChannelInfo *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;  // Mutex for thread safety
} TransportChannelArray;

// Initialize the transport channel array structure.
void initTransportChannelArray(TransportChannelArray *tca, size_t initialCapacity) {
    tca->capacity = initialCapacity;
    tca->count = 0;
    tca->array = (LTE_Uu_TransportChannelInfo *)malloc(tca->capacity * sizeof(LTE_Uu_TransportChannelInfo));
    pthread_mutex_init(&tca->lock, NULL);
}

// Hash function to initialize CRCFlag
uint8_t hashTransportChannelIDAndRNTI(int id, uint16_t rnti) {
    return (id ^ rnti) & 0xFF; // Simple XOR-based hash for illustration
}

// Add a new transport channel info to the array.
void addTransportChannelInfo(TransportChannelArray *tca, int tcID, uint16_t rnti) {
    pthread_mutex_lock(&tca->lock);

    if (tca->count == tca->capacity) {
        // Double capacity when limit is reached
        size_t newCapacity = tca->capacity * 2;
        LTE_Uu_TransportChannelInfo *newArray = (LTE_Uu_TransportChannelInfo *)realloc(tca->array, newCapacity * sizeof(LTE_Uu_TransportChannelInfo));

        if (newArray) {
            tca->array = newArray;
            tca->capacity = newCapacity;
        } else {
            // Handle memory allocation failure
            pthread_mutex_unlock(&tca->lock);
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
    }

    LTE_Uu_TransportChannelInfo *info = &tca->array[tca->count];
    info->TransportChannelID = tcID;
    info->RNTI = rnti;
    info->CRCFlag = hashTransportChannelIDAndRNTI(tcID, rnti);

    tca->count++;
    pthread_mutex_unlock(&tca->lock);
}

// Free the allocated resources.
void freeTransportChannelArray(TransportChannelArray *tca) {
    if (tca->array) {
        free(tca->array);
    }
    pthread_mutex_destroy(&tca->lock);
}
```

### Key Points:
- **Thread Safety**: Mutex is used to ensure that only one thread can modify the array at a time, minimizing race conditions.
- **Dynamic Allocation**: The array's capacity doubles when it reaches its limit to balance memory allocation overhead and performance under load.
- **Cache Efficiency & False Sharing**: The structure layout minimizes false sharing by keeping the size of `LTE_Uu_TransportChannelInfo` minimal and padding can be added if necessary.
- **Ease of Extension**: Structures are designed so that adding new fields in future versions is straightforward without altering existing functionality.

This design ensures a balance between performance, memory efficiency, and maintainability.']

