#define INITIAL_MAX_MEMORY 1024 * 1024 * 10 // Example initial limit: 10 MB
#define RECORD_COUNT 10000

typedef struct {
    long value;
    int* keys;
} Offset;

typedef struct {
    int data;
} Record;

