size_t getCurrentMemoryUsage() {
    return rand() % (INITIAL_MAX_MEMORY + INITIAL_MAX_MEMORY / 10); // Simulated fluctuation
}

// Logging function to track memory usage
void logMemoryUsage(size_t used_memory) {
    printf("Current Memory Usage: %zu bytes\n", used_memory);
}

size_t maxMemoryLimit = INITIAL_MAX_MEMORY;

Offset* allocateOffsets(int numOffsets, int keySizes[], size_t *totalAllocatedMemory) {
    Offset* offsets = (Offset*)malloc(numOffsets * sizeof(Offset));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < numOffsets; ++i) {
        size_t requiredMemory = sizeof(int) * keySizes[i];

        if (*totalAllocatedMemory + requiredMemory > maxMemoryLimit) {
            perror("Exceeded memory limit during offset allocation");
            free(offsets);
            exit(EXIT_FAILURE);
        }

        offsets[i].keys = (int*)malloc(requiredMemory);
        if (!offsets[i].keys) {
            perror("Failed to allocate memory for keys");
            for (int j = 0; j < i; ++j) free(offsets[j].keys);
            free(offsets);
            exit(EXIT_FAILURE);
        }

        *totalAllocatedMemory += requiredMemory;
    }

    return offsets;
}

Record* allocateRecords(int count, int rangeMin, int rangeMax, size_t *totalAllocatedMemory) {
    size_t recordSize = sizeof(Record) * count;

    if (*totalAllocatedMemory + recordSize > maxMemoryLimit) {
        perror("Exceeded memory limit during record allocation");
        exit(EXIT_FAILURE);
    }

    Record* records = (Record*)malloc(recordSize);
    if (!records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        records[i].data = rangeMin + rand() % (rangeMax - rangeMin + 1);
    }

    *totalAllocatedMemory += recordSize;
    return records;
}

void freeResources(Offset* offsets, int numOffsets, Record* records) {
    for (int i = 0; i < numOffsets; ++i) {
        free(offsets[i].keys);
    }
    free(offsets);

    free(records);
}

void manageMemory(int numOffsets, int keySizes[], int rangeMin, int rangeMax) {
    size_t totalAllocatedMemory = 0;
    Offset* offsets = allocateOffsets(numOffsets, keySizes, &totalAllocatedMemory);

    Record* records = allocateRecords(RECORD_COUNT, rangeMin, rangeMax, &totalAllocatedMemory);

    // Simulate memory usage monitoring
    while (1) {
        size_t currentUsage = getCurrentMemoryUsage();
        if (currentUsage > maxMemoryLimit * 0.9) {  // Example threshold of 90%
            printf("Approaching maximum memory limit.\n");
            break;  // Break for demonstration, adjust as needed in real scenario
        }
        logMemoryUsage(currentUsage);
        sleep(1);  // Simulate delay between checks
    }

    freeResources(offsets, numOffsets, records);
}

int main() {
    int keySizes[] = {10, 20, 30}; // Example key sizes for offsets
    manageMemory(sizeof(keySizes) / sizeof(int), keySizes, 1, 100);

    return 0;
}
