#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

#define MAX_THREADS 10
#define THROUGHPUT_TARGET 10000

typedef struct {
    uint32_t RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} List;

void log_event(const char* message) {
    time_t now = time(NULL);
    printf("%s - %s\n", ctime(&now), message);  // Fallback local logging
}

int init_list(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return 0;
}

void push_back(List* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_event("Memory allocation failed");
        return;
    }

    pthread_mutex_lock(&list->lock);
    memcpy(&new_node->data, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* temp = list->head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

void handle_operations(List* list, int operations_count) {
    for (int i = 0; i < operations_count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RNTI = rand() % 1000000;  // Example value
        pdu.CRCFLAG = rand() & 1;

        push_back(list, &pdu);
    }
}

void* thread_function(void* arg) {
    List* list = (List*)arg;
    handle_operations(list, THROUGHPUT_TARGET / MAX_THREADS);

    return NULL;
}

int main() {
    srand(time(NULL));
    List shared_list;
    init_list(&shared_list);

    pthread_t threads[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &shared_list)) {
            log_event("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Cleanup and exit
    Node* current = shared_list.head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&shared_list.lock);

    log_event("Program finished successfully");

    return EXIT_SUCCESS;
}
