#define MAX_NODES 1000
#define INACTIVE_THRESHOLD 3600 // Example threshold in seconds

typedef struct {
    unsigned char ip[4];
    uint16_t port;
    bool status_flag;
    time_t timestamp;
} NetworkNode;

// Thread-safe list using atomic operations and volatile for shared state management.
typedef struct {
    NetworkNode *nodes[MAX_NODES];
    size_t count;
    _Atomic(size_t) write_index;
    volatile bool debug_mode;
} NodeList;

// Archive structure to hold inactive nodes
typedef struct {
    NetworkNode *nodes[MAX_NODES];
    size_t count;
} ArchivedNodes;

NodeList nodeList = {.count = 0, .write_index = 0, .debug_mode = false};
ArchivedNodes archivedNodes = {.count = 0};

void print_debug_info() {
    if (nodeList.debug_mode) {
        printf("Active nodes: %zu\n", nodeList.count);
        printf("Archived nodes: %zu\n", archivedNodes.count);
        // Additional memory usage info can be added here
    }
}

NetworkNode* create_node(unsigned char ip[4], uint16_t port, bool status_flag, time_t timestamp) {
    NetworkNode *node = (NetworkNode*)aligned_alloc(64, sizeof(NetworkNode));
    if (!node) return NULL;

    for (int i = 0; i < 4; ++i) node->ip[i] = ip[i];
    node->port = port;
    node->status_flag = status_flag;
    node->timestamp = timestamp;

    return node;
}

void add_node(NodeList *list, NetworkNode *node) {
    size_t index = atomic_fetch_add_explicit(&list->write_index, 1, memory_order_relaxed);
    if (index < MAX_NODES) {
        list->nodes[index] = node;
        list->count++;
        print_debug_info();
    }
}

void remove_node(NodeList *list, size_t index) {
    if (index < nodeList.count) {
        free(list->nodes[index]);
        for (size_t i = index; i < nodeList.count - 1; ++i) {
            list->nodes[i] = list->nodes[i + 1];
        }
        list->count--;
        print_debug_info();
    }
}

void update_node(NodeList *list, size_t index, NetworkNode *new_data) {
    if (index < nodeList.count && new_data) {
        free(list->nodes[index]);
        list->nodes[index] = new_data;
        print_debug_info();
    }
}

void set_global_status_flag(bool flag) {
    for (size_t i = 0; i < nodeList.count; ++i) {
        nodeList.nodes[i]->status_flag = flag;
    }
    print_debug_info();
}

// Background worker thread function
void* archive_inactive_nodes(void *arg) {
    while (1) {
        time_t now = time(NULL);
        for (size_t i = 0; i < nodeList.count; ++i) {
            if (difftime(now, nodeList.nodes[i]->timestamp) > INACTIVE_THRESHOLD) {
                remove_node(&nodeList, i);
                add_node(&archivedNodes, nodeList.nodes[i]);
                i--; // Adjust index after removal
            }
        }
        sleep(60); // Run every 60 seconds
    }
    return NULL;
}

void start_archive_worker() {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, archive_inactive_nodes, NULL) != 0) {
        perror("Failed to create background worker");
    }
}

// Memory compression strategy (simple example)
void compress_memory(NodeList *list) {
    // Placeholder for a real compression algorithm
    // Here we could implement something like run-length encoding or another lightweight method
}

int main() {
    start_archive_worker();

    unsigned char ip1[] = {192, 168, 1, 1};
    NetworkNode *node1 = create_node(ip1, 8080, true, time(NULL));
    add_node(&nodeList, node1);

    // Additional operations...

    return 0;
}
