    LTE_RRC_UE_CONTEXT context;
    struct UE_Context_Node* next;
} UE_Context_Node;

typedef struct {
    UE_Context_Node** table;
    size_t size;
    pthread_mutex_t lock;
} UE_Context_Manager;

static void log_performance(const char* operation, double time_taken) {
    printf("Operation: %s, Time Taken: %.6f seconds\n", operation, time_taken);
}

UE_Context_Manager* create_ue_context_manager(size_t hash_table_size) {
    UE_Context_Manager* manager = (UE_Context_Manager*)malloc(sizeof(UE_Context_Manager));
    if (!manager) return NULL;

    manager->table = (UE_Context_Node**)calloc(hash_table_size, sizeof(UE_Context_Node*));
    if (!manager->table) {
        free(manager);
        return NULL;
    }

    manager->size = hash_table_size;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

unsigned int hash_function(int id, size_t size) {
    return (unsigned int)(id % size);
}

int add_ue_context(UE_Context_Manager* manager, LTE_RRC_UE_CONTEXT context) {
    if (!manager) return -1;

    unsigned int index = hash_function(context.id, manager->size);

    pthread_mutex_lock(&manager->lock);

    UE_Context_Node* node = (UE_Context_Node*)malloc(sizeof(UE_Context_Node));
    if (!node) {
        pthread_mutex_unlock(&manager->lock);
        return -2;
    }

    memcpy(&node->context, &context, sizeof(LTE_RRC_UE_CONTEXT));

    node->next = manager->table[index];
    manager->table[index] = node;

    pthread_mutex_unlock(&manager->lock);

    return 0;
}

int update_ue_context(UE_Context_Manager* manager, int id, LTE_RRC_UE_CONTEXT new_context) {
    if (!manager) return -1;

    unsigned int index = hash_function(id, manager->size);

    pthread_mutex_lock(&manager->lock);

    UE_Context_Node* node = manager->table[index];
    while (node) {
        if (node->context.id == id) {
            memcpy(&node->context, &new_context, sizeof(LTE_RRC_UE_CONTEXT));
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&manager->lock);

    return -3; // Context not found
}

LTE_RRC_UE_CONTEXT* get_ue_context(UE_Context_Manager* manager, int id) {
    if (!manager) return NULL;

    unsigned int index = hash_function(id, manager->size);

    pthread_mutex_lock(&manager->lock);

    UE_Context_Node* node = manager->table[index];
    while (node) {
        if (node->context.id == id) {
            pthread_mutex_unlock(&manager->lock);
            return &node->context;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&manager->lock);

    return NULL; // Context not found
}

void cleanup_ue_context_manager(UE_Context_Manager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->size; ++i) {
        UE_Context_Node* node = manager->table[i];
        while (node) {
            UE_Context_Node* temp = node;
            node = node->next;
            free(temp);
        }
    }

    free(manager->table);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    UE_Context_Manager* manager = create_ue_context_manager(1024);

    LTE_RRC_UE_CONTEXT context = {1, "Initial Data"};
    add_ue_context(manager, context);

    clock_t start = clock();
    get_ue_context(manager, 1);
    clock_t end = clock();

    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
    log_performance("Get Context", time_taken);

    cleanup_ue_context_manager(manager);

    return 0;
}
