    RX_UE_INFORMATION_TAG ue_info_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
} NFAPI_CRC_INDICATION_PDU_T;

#define SUCCESS 0
#define ERROR -1

// Function to initialize random seed for repeatable randomness
void init_random_seed() {
    srand(time(NULL)); // Or use a fixed seed for repeatability across runs, e.g., `srand(42);`
}

int add_crc_indication(NFAPI_CRC_INDICATION_PDU_T **head, unsigned int rnti, size_t max_size_bytes) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) return ERROR;

    // Calculate the total memory footprint and check against maximum size
    size_t total_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_size > max_size_bytes) {
        free(new_node);
        return ERROR;
    }

    new_node->ue_info_tag.RNTI = rnti;
    new_node->ue_info_tag.crc_tag.CRCFLAG = rand() % 2; // Random CRC flag, repeatable
    new_node->ue_info_tag.timestamp = time(NULL);

    new_node->next = *head;
    if (*head) {
        (*head)->prev = new_node;
    }
    *head = new_node;

    return SUCCESS;
}

int create_crc_list(NFAPI_CRC_INDICATION_PDU_T **head, int N, size_t M, size_t max_size_bytes) {
    if (!head || N <= 0 || M <= 0 || max_size_bytes == 0) return ERROR;

    *head = NULL;
    unsigned int rnti_set[256] = {0}; // Assuming RNTI is within 8-bit range
    size_t current_memory_usage = 0;
    int allocated_count = 0;

    for (int i = 1; i <= N && allocated_count < M; ++i) {
        if (!rnti_set[i % sizeof(rnti_set)]) { // Ensure unique RNTI within range
            rnti_set[i % sizeof(rnti_set)] = 1;
            int status = add_crc_indication(head, i, max_size_bytes - current_memory_usage);
            if (status == SUCCESS) {
                allocated_count++;
                current_memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
            } else {
                // Handle allocation failure by breaking the loop
                break;
            }
        }
    }

    return allocated_count > 0 ? SUCCESS : ERROR;
}

void free_crc_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
}

void print_crc_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        printf("RNTI: %u, CRCFLAG: %d, Timestamp: %ld\n",
               current->ue_info_tag.RNTI,
               current->ue_info_tag.crc_tag.CRCFLAG,
               current->ue_info_tag.timestamp);
        current = current->next;
    }
}

int main() {
    init_random_seed(); // Initialize the random seed for repeatable randomness

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    int N = 10; // Number of structures to create
    size_t M = 15; // Maximum number of elements in the list
    size_t max_size_bytes = 1024; // Maximum memory allocation for the linked list

    if (create_crc_list(&head, N, M, max_size_bytes) == SUCCESS) {
        printf("Doubly-linked list created successfully.\n");
        print_crc_list(head);
    } else {
        fprintf(stderr, "Failed to create doubly-linked list.\n");
    }

    free_crc_list(head); // Free all allocated resources
    return 0;
}
