    pthread_mutex_lock(&shared_data.lock);

    float old_mean = shared_data.mean_rss;
    float old_variance = shared_data.variance_rss;
    int count = shared_data.phy_count;

    shared_data.mean_rss += (new_value - old_mean) / (count + 1);
    if (count > 0) {
        shared_data.variance_rss += ((new_value - old_mean) * (new_value - shared_data.mean_rss) - old_variance) / (count + 1);
    }
    shared_data.stddev_rss = sqrt(shared_data.variance_rss);

    pthread_mutex_unlock(&shared_data.lock);
}

void process_input(int range_min, int range_max) {
    int value;
    int unique_tags[MAX_SAMPLES] = {0};

    while (scanf("%d", &value) == 1) {
        if (value < range_min || value > range_max) continue;

        pthread_mutex_lock(&shared_data.lock);

        if (!is_unique_crc(value, unique_tags, shared_data.crc_count)) {
            pthread_mutex_unlock(&shared_data.lock);
            continue;
        }

        if (shared_data.crc_count >= MAX_SAMPLES) {
            printf("Maximum samples reached.\n");
            pthread_mutex_unlock(&shared_data.lock);
            break;
        }

        NFAPI_CRC_INDICATION_PDU_T *crc_pdu = &shared_data.crc_pdu_array[shared_data.crc_count++];
        crc_pdu->RX_UE_INFORMATION_TAG = value;
        crc_pdu->RNTI = rand() % 1000; // Example RNTI
        crc_pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) == 0;

        int new_rss = rand() % range_max + range_min;

        if (shared_data.phy_count < MAX_SAMPLES) {
            PHY_STATS_PDU_T *phy_stats = &shared_data.phy_stats_array[shared_data.phy_count++];
            phy_stats->TX_POWER_LEVELS = (float)(rand() % 31);
            phy_stats->RECEIVED_SIGNAL_STRENGTH = new_rss;
            phy_stats->LINK_LAYER_STATS.SNR = (float)rand() / RAND_MAX * 30.0; // Example SNR

            update_statistics(new_rss);
        } else {
            printf("PHY STATS Maximum samples reached.\n");
        }

        pthread_mutex_unlock(&shared_data.lock);
    }
}

void print_largest_integer() {
    int largest = -1;

    pthread_mutex_lock(&shared_data.lock);

    for (int i = 0; i < shared_data.crc_count; ++i) {
        if (shared_data.crc_pdu_array[i].RX_UE_INFORMATION_TAG > largest) {
            largest = shared_data.crc_pdu_array[i].RX_UE_INFORMATION_TAG;
        }
    }

    pthread_mutex_unlock(&shared_data.lock);

    printf("Largest Integer: %d\n", largest);
}

int main() {
    initialize_shared_data();

    process_input(10, 1000); // Example range

    print_largest_integer();

    free_shared_data();

    return 0;
}
