// Union-Find Data Structure with path compression and union by rank
typedef struct UFNode {
    int parent;
    int rank;
} UFNode;

UFNode* uf_create(int size) {
    UFNode *uf = malloc(size * sizeof(UFNode));
    for (int i = 0; i < size; i++) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
    return uf;
}

int uf_find(UFNode* uf, int x) {
    if (uf[x].parent != x)
        uf[x].parent = uf_find(uf, uf[x].parent);
    return uf[x].parent;
}

void uf_union(UFNode* uf, int x, int y) {
    int rootX = uf_find(uf, x);
    int rootY = uf_find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank)
            uf[rootY].parent = rootX;
        else if (uf[rootX].rank < uf[rootY].rank)
            uf[rootX].parent = rootY;
        else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

// Thread-safe logging function
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void thread_safe_log(const char *message) {
    pthread_mutex_lock(&log_mutex);
    printf("%s\n", message);
    pthread_mutex_unlock(&log_mutex);
}

// Error handling with callback mechanism
typedef void (*ErrorCallback)(int error_code);

// Function to process disjoint pairs
int processNfaPairs(int* array, size_t size, ErrorCallback errorCallback) {
    if (!array || size == 0) {
        errorCallback(1); // Example error code
        return 0;
    }

    UFNode *uf = uf_create(size);
    int disjoint_pairs = 0;

    for (size_t i = 0; i < size - 1; ++i) {
        for (size_t j = i + 1; j < size; ++j) {
            clock_t start_time = clock();

            // Check if i and j are in different sets
            if (uf_find(uf, array[i]) != uf_find(uf, array[j])) {
                disjoint_pairs++;
                uf_union(uf, array[i], array[j]);
            }

            clock_t end_time = clock();
            double time_taken = ((double)(end_time - start_time)) / CLOCKS_PER_SEC * 1000;
            thread_safe_log("Disjointness check took: %.2f ms", time_taken);
        }
    }

    free(uf);

    return disjoint_pairs;
}

