['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1000
#define CACHE_SIZE 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int unique_value;
    NFAPI_CRC_INDICATION_PDU_T pdu;
} record_t;

typedef struct {
    record_t* records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RecordArray;

static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static record_t* record_cache[CACHE_SIZE];
static int cache_index = 0;

void log_message(const char* message) {
    printf("%s\n", message);
}

record_t* get_cached_record() {
    pthread_mutex_lock(&cache_lock);
    if (cache_index > 0) {
        record_t* record = record_cache[--cache_index];
        pthread_mutex_unlock(&cache_lock);
        return record;
    }
    pthread_mutex_unlock(&cache_lock);
    return NULL;
}

void cache_record(record_t* record) {
    pthread_mutex_lock(&cache_lock);
    if (cache_index < CACHE_SIZE) {
        record_cache[cache_index++] = record;
    }
    pthread_mutex_unlock(&cache_lock);
}

record_t* create_record(int unique_value, int RX_UE_INFORMATION_TAG, int RNTI) {
    record_t* record = get_cached_record();
    if (!record) {
        record = (record_t*)malloc(sizeof(record_t));
        if (!record) {
            log_message("Memory allocation failed for record.");
            return NULL;
        }
    }

    record->unique_value = unique_value;
    record->pdu.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    record->pdu.RNTI = RNTI;
    record->pdu.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    return record;
}

void free_record(record_t* record) {
    cache_record(record);
}

int add_record(RecordArray* array, int unique_value, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&array->lock);

    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity > 0 ? array->capacity * 2 : 1;
        if (new_capacity > MAX_ELEMENTS) {
            log_message("Exceeded maximum element limit.");
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        record_t* new_records = (record_t*)realloc(array->records, new_capacity * sizeof(record_t));
        if (!new_records) {
            log_message("Memory reallocation failed for records array.");
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->records = new_records;
        array->capacity = new_capacity;
    }

    int i;
    for (i = 0; i < array->count; ++i) {
        if (array->records[i].unique_value == unique_value) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Duplicate found
        }
    }

    record_t* new_record = create_record(unique_value, RX_UE_INFORMATION_TAG, RNTI);
    if (!new_record) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    array->records[array->count++] = *new_record;
    free_record(new_record);

    pthread_mutex_unlock(&array->lock);
    return 0;
}

void initialize_record_array(RecordArray* array) {
    array->records = NULL;
    array->count = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void free_record_array(RecordArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free_record(&array->records[i]);
    }
    free(array->records);
    pthread_mutex_destroy(&array->lock);
}

int main() {
    srand(time(NULL));

    RecordArray array;
    initialize_record_array(&array);

    int result = add_record(&array, 1, 100, 200);
    if (result == 0) {
        log_message("Record added successfully.");
    } else {
        log_message("Failed to add record.");
    }

    free_record_array(&array);
    return 0;
}
