#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ENTRIES 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries[MAX_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
    int crc_count;
    int anomaly_count;
} CRCManager;

CRCManager* create_crc_manager() {
    CRCManager *manager = (CRCManager *)malloc(sizeof(CRCManager));
    if (!manager) return NULL;

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->crc_count = 0;
    manager->anomaly_count = 0;

    for (size_t i = 0; i < MAX_ENTRIES; ++i) {
        manager->entries[i] = NULL;
    }

    return manager;
}

void log_message(const char *message) {
    // Simple logging mechanism
    printf("%s\n", message);
}

int add_crc_indication(CRCManager *manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_ENTRIES) {
        log_message("Max entries reached. Cannot add more.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    // Simulate data validation
    if (pdu->RX_UE_INFORMATION_TAG == 0 || pdu->RNTI == 0) {
        manager->anomaly_count++;
        log_message("Anomalous data detected.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    manager->entries[manager->count++] = pdu;
    manager->crc_count++;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void clear_crc_manager(CRCManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i]);
        manager->entries[i] = NULL;
    }
    manager->count = 0;

    log_message("CRC Manager cleared.");

    pthread_mutex_unlock(&manager->lock);
}

void destroy_crc_manager(CRCManager *manager) {
    clear_crc_manager(manager);
    pthread_mutex_destroy(&manager->lock);
    free(manager);

    log_message("CRC Manager destroyed.");
}

int main() {
    // Example usage
    CRCManager *manager = create_crc_manager();

    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = 1;
    pdu->RNTI = 12345;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = 0x01;

    add_crc_indication(manager, pdu);

    destroy_crc_manager(manager);

    return 0;
}
