    LTE_DL_CCCH_Message_Type1_T *messages = NULL;
    size_t currentSize = 0;
    size_t newSize = 10; // Initial allocation size
    int sequenceNumber = 0;
    double startTime = (double)clock() / CLOCKS_PER_SEC;

