                log_error("Failed to initialize a message");
                --currentSize; // Do not count this as successfully initialized
            }
        }

        newSize *= 2;
    }

    *actualCount = currentSize;
    double endTime = (double)clock() / CLOCKS_PER_SEC;

    printf("Memory usage: %zu bytes\n", currentSize * sizeof(LTE_DL_CCCH_Message_Type1_T));
    printf("Processing time: %.2f seconds\n", endTime - startTime);

    return messages;
}

void log_error(const char *error) {
    fprintf(stderr, "Error: %s\n", error);
}

void serialize_messages(LTE_DL_CCCH_Message_Type1_T *messages, size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for serialization");
        return;
    }

    fwrite(&count, sizeof(count), 1, file);
    fwrite(messages, sizeof(LTE_DL_CCCH_Message_Type1_T), count, file);

    fclose(file);
}

size_t deserialize_messages(LTE_DL_CCCH_Message_Type1_T **messages, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        log_error("Failed to open file for deserialization");
        return 0;
    }

    size_t count;
    fread(&count, sizeof(count), 1, file);

    *messages = malloc(count * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!*messages) {
        log_error("Memory allocation failed during deserialization");
        fclose(file);
        return 0;
    }

    fread(*messages, sizeof(LTE_DL_CCCH_Message_Type1_T), count, file);

    fclose(file);
    return count;
}

int main() {
    size_t actualCount = 0;
    LTE_DL_CCCH_Message_Type1_T *messages = initialize_DL_CCCH_Messages(100, &actualCount);

    if (messages) {
        serialize_messages(messages, actualCount, "messages.bin");

        LTE_DL_CCCH_Message_Type1_T *deserializedMessages = NULL;
        size_t deserializedCount = deserialize_messages(&deserializedMessages, "messages.bin");

        printf("Deserialized %zu messages\n", deserializedCount);

        free(deserializedMessages);
        free(messages);
    }

    return 0;
}
