['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_LIST_SIZE 1024

// Cache structure for frequently accessed RNTI values
typedef struct {
    uint16_t rnti;
    size_t index;
} RNTICacheEntry;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_LIST_SIZE];
    size_t count;
    pthread_mutex_t lock;
    RNTICacheEntry cache[256]; // Simple fixed-size cache
    int cache_hits;
    time_t ttl; // Time-to-live for purging old entries
} CRCListManager;

// Logging function
void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

// Initialize the list manager
void init_crc_list_manager(CRCListManager *manager, time_t ttl_seconds) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    manager->ttl = ttl_seconds;
    memset(manager->list, 0, sizeof(manager->list));
    memset(manager->cache, 0, sizeof(manager->cache));
    manager->cache_hits = 0;
}

// Add an entry to the list
int add_crc_indication(CRCListManager *manager, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= MAX_LIST_SIZE) {
        log_error("List is full");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->list[i]->RNTI == entry->RNTI) {
            log_error("Duplicate RNTI entry");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
    }

    manager->list[manager->count++] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->list[manager->count - 1]) {
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    memcpy(manager->list[manager->count - 1], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Retrieve an entry by RNTI
NFAPI_CRC_INDICATION_PDU_T *get_crc_indication(CRCListManager *manager, uint16_t rnti) {
    pthread_mutex_lock(&manager->lock);

    // Check cache first
    for (int i = 0; i < sizeof(manager->cache) / sizeof(RNTICacheEntry); ++i) {
        if (manager->cache[i].rnti == rnti && manager->list[manager->cache[i].index]) {
            manager->cache_hits++;
            pthread_mutex_unlock(&manager->lock);
            return manager->list[manager->cache[i].index];
        }
    }

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->list[i]->RNTI == rnti) {
            // Update cache
            manager->cache[i % sizeof(manager->cache) / sizeof(RNTICacheEntry)] = (RNTICacheEntry){rnti, i};
            pthread_mutex_unlock(&manager->lock);
            return manager->list[i];
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Clear the list
void clear_crc_list(CRCListManager *manager) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->list[i]);
        manager->list[i] = NULL;
    }

    manager->count = 0;
    memset(manager->cache, 0, sizeof(manager->cache));
    pthread_mutex_unlock(&manager->lock);
}

// Purge old entries based on TTL
void purge_old_entries(CRCListManager *manager) {
    time_t now = time(NULL);

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (difftime(now, manager->list[i]->RX_UE_INFORMATION_TAG) > manager->ttl) {
            free(manager->list[i]);
            memmove(&manager->list[i], &manager->list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (manager->count - i - 1));
            --manager->count;
            --i; // Check the new element at this index
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

// Get statistics
void get_statistics(CRCListManager *manager, size_t *unique_rntis, int *crc0_count, int *crc1_count) {
    *unique_rntis = 0;
    *crc0_count = 0;
    *crc1_count = 0;

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        int found = 0;
        for (size_t j = 0; j < *unique_rntis; ++j) {
            if (manager->list[j]->RNTI == manager->list[i]->RNTI) {
                found = 1;
                break;
            }
        }
        if (!found) (*unique_rntis)++;

        if (manager->list[i]->CRCFLAG == 0) (*crc0_count)++;
        else if (manager->list[i]->CRCFLAG == 1) (*crc1_count)++;
    }

    pthread_mutex_unlock(&manager->lock);
}

// Periodic purging function
void *periodic_purge(void *arg) {
    CRCListManager *manager = (CRCListManager *)arg;
    while (1) {
        sleep(manager->ttl);
        purge_old_entries(manager);
    }
    return NULL;
}

// Initialize and start the periodic purger
void start_periodic_purger(CRCListManager *manager) {
    pthread_t tid;
    pthread_create(&tid, NULL, periodic_purge, manager);
    pthread_detach(tid);
}
