#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>
#include <limits.h>
#include <time.h>

#define MAX_INTS 10000
#define LOG_FILE "system_log.txt"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG; // Assuming CRCFLAG is a single bit
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char *message) {
    pthread_mutex_lock(&log_mutex);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
    pthread_mutex_unlock(&log_mutex);
}

int validate_integer(const char *str) {
    char *endptr;
    int num = strtol(str, &endptr, 10);

    if (endptr == str || *endptr != '\0' || errno == ERANGE || num <= 0) {
        return -1; // Invalid integer
    }
    return num;
}

void read_integers(int **int_array, int *count) {
    char buffer[12]; // Buffer to hold up to 10 digits + null terminator
    *int_array = malloc(MAX_INTS * sizeof(int));
    if (*int_array == NULL) {
        log_message("Memory allocation failed for integer array.");
        return;
    }

    *count = 0;
    while (fgets(buffer, sizeof(buffer), stdin)) {
        int value = validate_integer(buffer);
        if (value != -1 && *count < MAX_INTS) {
            (*int_array)[*count] = value;
            (*count)++;
        } else {
            log_message("Invalid input or limit exceeded.");
            break;
        }
    }

    if (*count == 0) {
        free(*int_array);
        *int_array = NULL;
        log_message("No valid integers were read.");
    }
}

void sort_integers(int *array, int count) {
    for (int i = 0; i < count - 1; ++i) {
        for (int j = i + 1; j < count; ++j) {
            if (array[i] < array[j]) {
                int temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
    }
}

void populate_structures(NFAPI_CRC_INDICATION_PDU_T *buffer, int *int_array, int count) {
    int structures_created = 0;
    for (int i = 0; i < count; ++i) {
        buffer[i].RX_UE_INFORMATION_TAG = int_array[i];
        buffer[i].RNTI = rand(); // Simulating RNTI generation
        buffer[i].CRC_INDICATION_REL8_TAG = rand() & 1; // Randomly setting CRCFLAG

        if (buffer[i].RX_UE_INFORMATION_TAG != 0) {
            structures_created++;
        } else {
            log_message("Zero integer found, skipping structure creation.");
        }
    }

    log_message("Total structures successfully created: ");
    printf("%d\n", structures_created);
}

int main() {
    int *integers = NULL;
    NFAPI_CRC_INDICATION_PDU_T buffer[MAX_INTS];

    read_integers(&integers, &count);

    if (integers == NULL) {
        return EXIT_FAILURE;
    }

    sort_integers(integers, count);

    populate_structures(buffer, integers, count);

    int largest_index = 0; // Index of the largest integer after sorting
    printf("Index of the largest integer: %d\n", largest_index);
    printf("Total structures created: %d\n", count);

    free(integers);
    return EXIT_SUCCESS;
}
```

### Key Features:
