#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Measurement {
    double latency;
    double throughput;
    double packet_loss;
} Measurement;

typedef struct NetworkMetric {
    time_t timestamp;
    char session_id[64];
    Measurement* measurements;
    size_t measurement_count;
    struct NetworkMetric* prev;
    struct NetworkMetric* next;
} NetworkMetric;

typedef struct LinkedList {
    NetworkMetric* head;
    NetworkMetric* tail;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_measurement(Measurement* measurement, size_t count) {
    free(measurement);
}

void destroy_network_metric(NetworkMetric* metric) {
    if (metric->measurements) {
        destroy_measurement(metric->measurements, metric->measurement_count);
    }
    free(metric);
}

void cleanup_metrics(LinkedList* list, time_t retention_time) {
    pthread_mutex_lock(&list->lock);

    NetworkMetric *current = list->head, *next;
    while (current) {
        next = current->next;

        if (difftime(time(NULL), current->timestamp) > retention_time) {
            if (current == list->head) list->head = next;
            if (current == list->tail) list->tail = current->prev;
            if (current->prev) current->prev->next = current->next;
            if (current->next) current->next->prev = current->prev;

            destroy_network_metric(current);
        }
        current = next;
    }

    pthread_mutex_unlock(&list->lock);
}

void add_network_metric(LinkedList* list, time_t timestamp, const char* session_id, Measurement* measurements, size_t count) {
    NetworkMetric* new_metric = malloc(sizeof(NetworkMetric));
    if (!new_metric) return;

    new_metric->timestamp = timestamp;
    strncpy(new_metric->session_id, session_id, sizeof(new_metric->session_id) - 1);
    new_metric->measurements = (Measurements*)malloc(count * sizeof(Measurement));
    memcpy(new_metric->measurements, measurements, count * sizeof(Measurement));
    new_metric->measurement_count = count;
    new_metric->prev = NULL;
    new_metric->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (!list->head) {
        list->head = new_metric;
        list->tail = new_metric;
    } else {
        list->tail->next = new_metric;
        new_metric->prev = list->tail;
        list->tail = new_metric;
    }

    pthread_mutex_unlock(&list->lock);
}

void retrieve_summary_statistics(LinkedList* list, time_t start_time, time_t end_time, double* avg_latency, double* total_throughput) {
    *avg_latency = 0.0;
    *total_throughput = 0.0;
    size_t latency_count = 0;

    pthread_mutex_lock(&list->lock);

    NetworkMetric* current = list->head;
    while (current) {
        if (current->timestamp >= start_time && current->timestamp <= end_time) {
            for (size_t i = 0; i < current->measurement_count; ++i) {
                *total_throughput += current->measurements[i].throughput;
                *avg_latency += current->measurements[i].latency;
                latency_count++;
            }
        }
        current = current->next;
    }

    if (latency_count > 0) {
        *avg_latency /= latency_count;
    }

    pthread_mutex_unlock(&list->lock);
}

void monitor_memory_usage(LinkedList* list, size_t* total_elements, size_t* total_memory_used) {
    *total_elements = 0;
    *total_memory_used = 0;

    pthread_mutex_lock(&list->lock);

    NetworkMetric* current = list->head;
    while (current) {
        (*total_elements)++;
        *total_memory_used += sizeof(NetworkMetric);
        if (current->measurements) {
            *total_memory_used += current->measurement_count * sizeof(Measurement);
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void handle_error(const char* error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
    // Additional error handling logic
}
