#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    time_t timestamp;
    size_t payload_length;
} Message;

typedef struct {
    Message *messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MessageArray;

MessageArray* create_message_array(size_t initial_capacity) {
    MessageArray *array = malloc(sizeof(MessageArray));
    array->messages = malloc(initial_capacity * sizeof(Message));
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void resize_message_array(MessageArray *array) {
    size_t new_capacity = array->capacity * 2;
    Message *new_messages = realloc(array->messages, new_capacity * sizeof(Message));
    if (new_messages) {
        array->messages = new_messages;
        array->capacity = new_capacity;
    }
}

void add_message(MessageArray *array, int id, time_t timestamp, size_t payload_length) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        resize_message_array(array);
    }
    Message message = {id, timestamp, payload_length};
    array->messages[array->count++] = message;
    pthread_mutex_unlock(&array->lock);
}

Message* get_message_by_id(MessageArray *array, int id) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].id == id) {
            pthread_mutex_unlock(&array->lock);
            return &array->messages[i];
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void update_payload_length(MessageArray *array, int id, size_t offset) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].id == id) {
            array->messages[i].payload_length += offset;
            break;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

void serialize_message_array(MessageArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file) {
        fwrite(&array->count, sizeof(size_t), 1, file);
        fwrite(array->messages, sizeof(Message), array->count, file);
        fclose(file);
    }
}

void deserialize_message_array(MessageArray *array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file) {
        size_t count;
        fread(&count, sizeof(size_t), 1, file);
        resize_message_array(array);
        array->count = count;
        fread(array->messages, sizeof(Message), count, file);
        fclose(file);
    }
}

void free_message_array(MessageArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->messages);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
    free(array);
}
```

### Design Decisions:

1. **Dynamic Resizing**: The array doubles its capacity when full, balancing memory usage and insertion speed.
2. **Thread Safety**: A mutex ensures safe concurrent access, crucial for multi-threaded environments.
3. **Serialization/Deserialization**: Binary file operations ensure efficient I/O performance.
4. **Memory Management**: `malloc`, `realloc`, and `free` manage dynamic memory, with careful locking to prevent race conditions.
5. **Scalability**: The design supports high load by minimizing lock contention and efficiently managing memory growth.

These choices aim to balance speed, memory usage, and thread safety for scalable message management.']

