    if (!list->data) {
        log_error("Failed to allocate memory for data");
        free(list);
        return NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int validate_crc_indication(const CRC_INDICATION_REL8_TAG* tag) {
    // Add validation logic here
    return 1; // Assume valid for now
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

void resize_pdu_list(PDUList* list) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            log_error("Failed to resize PDUList");
        } else {
            list->data = new_data;
            list->capacity = new_capacity;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void add_pdu_to_list(PDUList* list, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!validate_crc_indication(&pdu->crc_indication_rel8_tag)) {
        log_error("Invalid CRC indication format");
        return;
    }
    pthread_mutex_lock(&list->lock);
    resize_pdu_list(list);
    list->data[list->size++] = *pdu;
    pthread_mutex_unlock(&list->lock);
}

int compare_pdu(const void* a, const void* b) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_a = (NFAPI_CRC_INDICATION_PDU_T*)a;
    NFAPI_CRC_INDICATION_PDU_T* pdu_b = (NFAPI_CRC_INDICATION_PDU_T*)b;
    return pdu_a->RNTI - pdu_b->RNTI;
}

void sort_pdu_list(PDUList* list) {
    pthread_mutex_lock(&list->lock);
    qsort(list->data, list->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_pdu);
    pthread_mutex_unlock(&list->lock);
}

void free_pdu_list(PDUList* list) {
    if (list) {
        pthread_mutex_destroy(&list->lock);
        free(list->data);
        free(list);
    }
}

void populate_pdu_list(PDUList* list, int n_elements) {
    srand(time(NULL));
    for (int i = 0; i < n_elements && i < MAX_ELEMENTS; ++i) {
