            pdu.rx_ue_information_tag = update.node_info.rx_ue_information_tag;
            pdu.rnti = update.node_info.rnti;
            pdu.crc_indication_rel8_tag.crcflag = rand() % 2;
            add_vertex(graph, pdu);
        } else if (update.type == NODE_DELETION) {
            remove_vertex(graph, update.node_index);
        } else if (update.type == EDGE_UPDATE) {
            unsigned char weight = rand() % 10;
            add_edge(graph, update.edge_info.from, update.edge_info.to, weight);
        }
    }
}

int main() {
    Graph *graph = create_graph();
    populate_nfa_pi_list_and_create_graph(&graph, 1000);

    handle_dynamic_updates(graph);

    return 0;
}
