        log_message(0, "Null pointer provided for output parameters.");
        return ERROR_NULL_POINTER;
    }

    *list = NULL;
    *count = 0;

    // Allocate memory for the maximum number of structures
    NFAPI_CRC_INDICATION_PDU_T* tempList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!tempList) {
