#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>
#include <netdb.h>
#include <time.h>

#define MAX_HOSTNAMES 500
#define CACHE_SIZE 1024

typedef struct {
    int RNTI;
    uint8_t RX_UE_INFORMATION_TAG[32];
    uint8_t CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CacheNode {
    char hostname[256];
    in_addr_t ip_address;
    time_t last_accessed;
    struct CacheNode *next;
} CacheNode;

typedef struct {
    CacheNode *head;
    int size;
    pthread_mutex_t lock;
} LRUCache;

LRUCache cache = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

int populateNFandProcessDNS(NFAPI_CRC_INDICATION_PDU_T **nfa_list, size_t *nfa_count) {
    if (!nfa_list || !nfa_count) return -1;

    int input_integers[10000000];
    int max_value = INT_MIN;
    size_t num_integers = 0;
    char line[256];

    // Read integers from standard input
    while (fgets(line, sizeof(line), stdin)) {
        if (sscanf(line, "%d", &input_integers[num_integers]) == 1) {
            if (input_integers[num_integers] > max_value) {
                max_value = input_integers[num_integers];
            }
            num_intergers++;
        }
    }

    // Create and populate NFAPI_CRC_INDICATION_PDU_T structures
    *nfa_list = malloc(num_integers * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*nfa_list) return -1;
    *nfa_count = num_integers;

    for (size_t i = 0; i < num_integers; ++i) {
        (*nfa_list)[i].RNTI = rand() % 65536;
        memset((*nfa_list)[i].RX_UE_INFORMATION_TAG, rand() % 256, sizeof((*nfa_list)[i].RX_UE_INFORMATION_TAG));
        memset((*nfa_list)[i].CRC_INDICATION_REL8_TAG, rand() % 2, sizeof((*nfa_list)[i].CRC_INDICATION_REL8_TAG));
    }

    // DNS resolution setup
    struct hostent *host;
    char hostnames[MAX_HOSTNAMES][256];
    u_char ip_addresses[MAX_HOSTNAMES][4];
    pthread_t threads[MAX_HOSTNAMES];
    int resolved_count = 0;

    void* dns_resolution(void* arg) {
        int index = *(int*)arg;
        free(arg);

        // Check cache
        pthread_mutex_lock(&cache.lock);
        CacheNode *current = cache.head;
        while (current) {
            if (strcmp(current->hostname, hostnames[index]) == 0) {
                memcpy(ip_addresses + index, &current->ip_address, sizeof(in_addr_t));
                current->last_accessed = time(NULL);
                pthread_mutex_unlock(&cache.lock);
                return NULL;
            }
            current = current->next;
        }
        pthread_mutex_unlock(&cache.lock);

        // Perform DNS resolution
        int retries = 0;
        while (retries < 5) {
            host = gethostbyname(hostnames[index]);
            if (host && host->h_addrtype == AF_INET) {
                memcpy(ip_addresses + index, host->h_addr, sizeof(in_addr_t));

                // Update cache
                pthread_mutex_lock(&cache.lock);
                CacheNode *new_node = malloc(sizeof(CacheNode));
                strcpy(new_node->hostname, hostnames[index]);
                new_node->ip_address = *(in_addr_t*)host->h_addr;
                new_node->last_accessed = time(NULL);

                // Insert at head
                new_node->next = cache.head;
                cache.head = new_node;

                if (cache.size >= CACHE_SIZE) {
                    CacheNode *temp = cache.head;
                    cache.head = cache.head->next;
                    free(temp);
                } else {
                    cache.size++;
                }
                pthread_mutex_unlock(&cache.lock);

                break;
            }

            retries++;
            sleep(1 << retries); // Exponential backoff
        }

        if (retries == 5) {
            fprintf(stderr, "Failed to resolve hostname: %s\n", hostnames[index]);
        } else {
            resolved_count++;
        }
        return NULL;
    }

    for (int i = 0; i < MAX_HOSTNAMES; ++i) {
        int *index = malloc(sizeof(int));
        if (!index) continue;
        *index = i;

        // Simulate hostname assignment
        snprintf(hostnames[i], sizeof(hostnames[i]), "hostname%d.example.com", i);

        pthread_create(&threads[i], NULL, dns_resolution, index);
    }

    for (int i = 0; i < MAX_HOSTNAMES; ++i) {
        if (threads[i]) {
            pthread_join(threads[i], NULL);
        }
    }

    // Log results
    FILE *log_file = fopen("dns_log.txt", "a");
    if (log_file) {
        for (int i = 0; i < resolved_count; ++i) {
            fprintf(log_file, "Hostname: %s, IP: %s\n",
                    hostnames[i], inet_ntoa(*(in_addr_t*)ip_addresses[i]));
        }
        fclose(log_file);
    }

    // Cleanup cache
    pthread_mutex_lock(&cache.lock);
    while (cache.head) {
        CacheNode *temp = cache.head;
        cache.head = cache.head->next;
        free(temp);
    }
    cache.size = 0;
    pthread_mutex_unlock(&cache.lock);

    return max_value;
}
