    graph->edges[src] = (Edge **)realloc(graph->edges[src], (++(graph->numEdges[src])) * sizeof(Edge *));
    graph->edges[src][graph->numEdges[src] - 1] = (Edge *)malloc(sizeof(Edge));
    graph->edges[src][graph->numEdges[src] - 1]->src = src;
