    // Add edge if it does not exist
    if (i == graph[ue1].edge_count) {
        graph[ue1].edges = realloc(graph[ue1].edges, (graph[ue1].edge_count + 1) * sizeof(Edge));
        graph[ue1].edges[graph[ue1].edge_count++] = (Edge){.from_ue = ue1, .to_ue = ue2, .weight = new_weight};
    }

    // Ensure bidirectional edge
    for (size_t j = 0; j < graph[ue2].edge_count; ++j) {
        if (graph[ue2].edges[j].to_ue == ue1) {
            graph[ue2].edges[j].weight = new_weight;
