#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    uint32_t checksum;
    pthread_mutex_t lock;
} LinkedList;

uint32_t calculate_checksum(LinkedList* list) {
    uint32_t cs = 0;
    Node* current = list->head;

    while (current != NULL) {
        cs += current->data.RX_UE_INFORMATION_TAG;
        cs ^= current->data.RNTI;
        cs += current->data.CRC_INDICATION_REL8_TAG.CRCFLAG;

        current = current->next;
    }
    return cs;
}

void* integrity_checker(void* arg) {
    LinkedList* list = (LinkedList*)arg;

    while (1) {
        sleep(5); // Check every 5 seconds, adjust based on performance needs
        pthread_mutex_lock(&list->lock);

        uint32_t current_checksum = calculate_checksum(list);
        if (current_checksum != list->checksum) {
            fprintf(stderr, "Integrity check failed!\n");
            break;
        }

        pthread_mutex_unlock(&list->lock);
    }

    return NULL;
}

LinkedList* create_linked_list(size_t n) {
    LinkedList* list = malloc(sizeof(LinkedList));
    if (!list) {
        perror("Failed to allocate memory for linked list");
        return NULL;
    }

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);

    Node** current_ptr = &(list->head);

    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < n; ++i) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            fprintf(stderr, "Memory allocation failed at node %zu\n", i);
            break;
        }

        new_node->data.RX_UE_INFORMATION_TAG = rand();
        new_node->data.RNTI = rand() & 0xFFFF; // Simulate a valid RNTI
        new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        pthread_mutex_lock(&list->lock);

        *current_ptr = new_node;
        current_ptr = &(new_node->next);

        pthread_mutex_unlock(&list->lock);
    }

    list->checksum = calculate_checksum(list);

    // Start background integrity checker
    pthread_t checker_thread;
    if (pthread_create(&checker_thread, NULL, integrity_checker, (void*)list) != 0) {
        perror("Failed to create integrity checker thread");
        return NULL;
    }
    pthread_detach(checker_thread);

    return list;
}

void free_linked_list(LinkedList* list) {
    Node* current = list->head;

    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

This code snippet provides a C function for dynamically allocating and initializing a linked list of `NFAPI_CRC_INDICATION_PDU_T` structures. It includes thread-safe mechanisms using mutexes, periodic integrity checks via a background thread, and robust error handling for memory allocation failures. Adjust the sleep interval in the `integrity_checker` function to balance between performance impact and checking frequency.']

