#include <iostream>
#include <string>
#include <vector>
#include <mutex>
#include <fstream>
#include <nlohmann/json.hpp> // Include JSON library (e.g., nlohmann/json)

// Using a namespace alias for convenience
namespace json = nlohmann;

class logEntry {
public:
    std::string timestamp;
    int error_code;
    std::string message;

    // Convert to JSON object
    json toJson() const {
        return {{"timestamp", timestamp}, {"error_code", error_code}, {"message", message}};
    }

    // Create from JSON object
    static logEntry fromJson(const json& j) {
        logEntry entry;
        entry.timestamp = j.at("timestamp").get<std::string>();
        entry.error_code = j.at("error_code").get<int>();
        entry.message = j.at("message").get<std::string>();
        return entry;
    }
};

class LogManager {
private:
    std::vector<logEntry> logs;
    mutable std::mutex mtx; // Mutex for thread safety

public:
    void addLog(const logEntry& entry) {
        std::lock_guard<std::mutex> lock(mtx);
        logs.push_back(entry);
    }

    bool removeLogByTimestamp(const std::string& timestamp) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = std::remove_if(logs.begin(), logs.end(),
            [&timestamp](const logEntry& entry) { return entry.timestamp == timestamp; });
        if (it != logs.end()) {
            logs.erase(it, logs.end());
            return true;
        }
        return false;
    }

    logEntry getMostRecentLog() const {
        std::lock_guard<std::mutex> lock(mtx);
        if (!logs.empty())
            return logs.back();
        throw std::runtime_error("No logs available");
    }

    void serializeToJson(const std::string& filename) const {
        std::lock_guard<std::mutex> lock(mtx);
        json j = json::array();

        for (const auto& log : logs)
            j.push_back(log.toJson());

        std::ofstream file(filename);
        if (file.is_open()) {
            file << j.dump(4); // Pretty-print JSON with indentation
            file.close();
        } else {
            throw std::runtime_error("Failed to open file for writing");
        }
    }

    void deserializeFromJson(const std::string& filename) {
        std::lock_guard<std::mutex> lock(mtx);
        std::ifstream file(filename);

        if (file.is_open()) {
            json j;
            file >> j;

            logs.clear();
            for (const auto& item : j)
                logs.push_back(logEntry::fromJson(item));

            file.close();
        } else {
            throw std::runtime_error("Failed to open file for reading");
        }
    }

    // Additional methods can be added here for future expansion and optimizations
};

// Usage Example:
int main() {
    LogManager manager;

    // Adding log entries
    manager.addLog({"2023-10-04T14:48:00Z", 404, "Page not found"});
    manager.addLog({"2023-10-05T16:20:30Z", 500, "Internal server error"});

    try {
        // Serialize to JSON
        manager.serializeToJson("logs.json");

        // Deserialize from JSON
        LogManager newManager;
        newManager.deserializeFromJson("logs.json");

        // Get the most recent log entry
        logEntry latest = newManager.getMostRecentLog();
        std::cout << "Latest Log: " << latest.timestamp << ", " << latest.error_code << ", "
                  << latest.message << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
```

