#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

int insert_or_update(CRCList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == pdu.RNTI) {
            current->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
            printf("Updated RNTI: %d\n", pdu.RNTI);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failure
    }

    new_node->data = pdu;
    new_node->next = list->head;
    new_node->prev = NULL;

    if (list->head != NULL) {
        list->head->prev = new_node;
    }
    list->head = new_node;

    printf("Inserted RNTI: %d\n", pdu.RNTI);
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void iterate_forward(CRCList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        callback(current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void iterate_reverse(CRCList* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&list->lock);

    Node* current = NULL;
    for (current = list->head; current && current->next; current = current->next);
    while (current) {
        callback(current->data);
        current = current->prev;
    }

    pthread_mutex_unlock(&list->lock);
}

void serialize_list(CRCList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(filename, "wb");
    if (!file) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    Node* current = list->head;
    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

void deserialize_list(CRCList* list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE* file = fopen(filename, "rb");
    if (!file) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T pdu;
    while (fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        insert_or_update(list, pdu);
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}

void log_operation(const char* operation) {
    printf("Log: %s\n", operation); // Simple logging mechanism
}

int main() {
    CRCList* list = create_list();
    if (!list) return -1;

    NFAPI_CRC_INDICATION_PDU_T pdu1 = { .RX_UE_INFORMATION_TAG = 1, .RNTI = 100, .CRC_INDICATION_REL8_TAG = 5 };
    insert_or_update(list, pdu1);

    NFAPI_CRC_INDICATION_PDU_T pdu2 = { .RX_UE_INFORMATION_TAG = 2, .RNTI = 101, .CRC_INDICATION_REL8_TAG = 6 };
    insert_or_update(list, pdu2);

    iterate_forward(list, [](NFAPI_CRC_INDICATION_PDU_T data) {
        printf("Forward: RNTI %d\n", data.RNTI);
    });

    iterate_reverse(list, [](NFAPI_CRC_INDICATION_PDU_T data) {
        printf("Reverse: RNTI %d\n", data.RNTI);
    });

    serialize_list(list, "list.dat");
    deserialize_list(list, "list.dat");

    log_operation("Completed operations");

    // Cleanup
    pthread_mutex_destroy(&list->lock);
    free(list);

    return 0;
}
```

### Key Points:
- **Thread Safety**: Mutexes are used to ensure thread-safe access to the list.
- **Unique RNTI**: The function checks for existing RNTIs and updates if found, otherwise inserts a new node.
- **Iteration**: Supports both forward and reverse iteration with callbacks.
- **Persistence**: Serialization and deserialization functions save and load the list state.
- **Logging**: Simple logging is implemented to track operations.']

