    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    uint32_t checksum;
    size_t count;
} LinkedList;

uint32_t calculateChecksum(Node* node) {
    // Simple checksum calculation
    uint32_t checksum = 0;
    while (node != NULL) {
        checksum += node->data.RX_UE_INFORMATION_TAG +
                    node->data.RNTI + node->data.CRC_INDICATION_REL8_TAG.CRCFLAG;
        node = node->next;
    }
    return checksum;
}

void* validateList(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    pthread_mutex_lock(&list->lock);
    uint32_t currentChecksum = calculateChecksum(list->head);
    if (currentChecksum == list->checksum) {
        printf("Validation successful.\n");
    } else {
        fprintf(stderr, "Validation failed!\n");
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void initAndValidateList(LinkedList* list) {
    srand(time(NULL));
    Node* current = NULL;
    for (size_t i = 0; i < MAX_NODES; ++i) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed!\n");
            break;
        }
        newNode->data.RX_UE_INFORMATION_TAG = rand();
        newNode->data.RNTI = rand() & 0xFFFF;
        newNode->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        newNode->next = NULL;

        if (list->head == NULL) {
            list->head = newNode;
        } else {
            current->next = newNode;
        }
        current = newNode;
    }

    pthread_mutex_init(&list->lock, NULL);
    uint32_t initialChecksum = calculateChecksum(list->head);
    list->checksum = initialChecksum;

    // Simulate periodic validation
    pthread_t thread;
    for (int i = 0; i < 10; ++i) {
        pthread_create(&thread, NULL, validateList, list);
        pthread_join(thread, NULL);
    }
}

void cleanup(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

int main() {
    LinkedList list = {NULL, PTHREAD_MUTEX_INITIALIZER, 0, 0};
    initAndValidateList(&list);
    cleanup(&list);
    return 0;
}
