#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>

// Define the structure for CRC indication PDU
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;  // Randomly set flag
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for the linked list
struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
};

typedef struct {
    struct Node* head;
    pthread_mutex_t lock;
    size_t node_count;
} ThreadSafeLinkedList;

#define MAX_NODES 10000

ThreadSafeLinkedList* create_list() {
    ThreadSafeLinkedList* list = (ThreadSafeLinkedList*)malloc(sizeof(ThreadSafeLinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->node_count = 0;
    return list;
}

int add_node(ThreadSafeLinkedList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
    if (!new_node) return -1;

    pthread_mutex_lock(&list->lock);
    if (list->node_count >= MAX_NODES) {
        free(new_node);
        pthread_mutex_unlock(&list->lock);
        return -2;  // List is full
    }

    new_node->data = pdu;
    new_node->next = list->head;
    list->head = new_node;
    list->node_count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void remove_node(ThreadSafeLinkedList* list, uint32_t rnti) {
    pthread_mutex_lock(&list->lock);

    struct Node *current = list->head, *prev = NULL;

    while (current != NULL && current->data.RNTI != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;  // Node not found
    }

    if (prev == NULL) {  // Removing head
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    list->node_count--;

    pthread_mutex_unlock(&list->lock);
}

void* integrity_check(void* arg) {
    ThreadSafeLinkedList* list = (ThreadSafeLinkedList*)arg;
    while (1) {
        sleep(10);  // Check every 10 seconds

        pthread_mutex_lock(&list->lock);

        struct Node *current = list->head;
        uint32_t checksum = 0;

        while (current != NULL) {
            checksum += current->data.RX_UE_INFORMATION_TAG +
                        current->data.RNTI + 
                        current->data.CRC_INDICATION_REL8_TAG;
            current = current->next;
        }

        printf("Checksum: %u\n", checksum);

        pthread_mutex_unlock(&list->lock);
    }
    return NULL;
}

void start_background_check(ThreadSafeLinkedList* list) {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, integrity_check, list)) {
        fprintf(stderr, "Error creating background check thread\n");
        exit(1);
    }
    pthread_detach(thread_id);  // Detach the thread
}

void destroy_list(ThreadSafeLinkedList* list) {
    pthread_mutex_lock(&list->lock);

    struct Node *current = list->head;
    while (current != NULL) {
        struct Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    ThreadSafeLinkedList* list = create_list();
    if (!list) {
        fprintf(stderr, "Failed to create linked list\n");
        return 1;
    }

    start_background_check(list);

    // Example: Add a node
    NFAPI_CRC_INDICATION_PDU_T pdu = {1234, 5678, 0x01, rand() % 2};
    if (add_node(list, pdu) != 0) {
        fprintf(stderr, "Failed to add node\n");
    }

    // Cleanup
    destroy_list(list);
    return 0;
}
```

