static int failed_dns_resolutions = 0;

StatusCode resolve_hostname(const char *hostname, u_char *ip_buffer) {
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        failed_dns_resolutions++;
        return FAILURE;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        addr = &(ipv4->sin_addr);
        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        strncpy((char *)ip_buffer, ipstr, INET_ADDRSTRLEN);
        break;
    }

    freeaddrinfo(res);
    success_dns_resolutions++;
    return SUCCESS;
}

StatusCode processNFAPIAndDNS(const char *hostname, NFAPI_CRC_INDICATION_PDU_T **pdu_list) {
    u_char ip_address[INET_ADDRSTRLEN];
    unsigned int i;
    StatusCode status = FAILURE;

    pthread_mutex_lock(&mutex);

    // Rate limiting logic
    time_t now = time(NULL);
    int idx = (ip_address[0] % 256); // Simplified index for rate limiting

    if (now - last_request_time[idx] < 1) {
        if (++request_count[idx] > MAX_REQUESTS_PER_SECOND) {
            pthread_mutex_unlock(&mutex);
            return FAILURE;
        }
    } else {
        request_count[idx] = 0; // Reset counter every second
    }

    last_request_time[idx] = now;

    // Resolve hostname to IP
    status = resolve_hostname(hostname, ip_address);

    if (status == SUCCESS) {
        *pdu_list = malloc(MAX_DNS_QUERIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*pdu_list == NULL) {
            pthread_mutex_unlock(&mutex);
            return FAILURE;
        }

        // Construct NFAPI_CRC_INDICATION_PDU_T list
        for (i = 0; i < MAX_DNS_QUERIES; i++) {
            (*pdu_list)[i].RX_UE_INFORMATION_TAG = rand();
            (*pdu_list)[i].RNTI = rand();
            (*pdu_list)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        }
    }

    pthread_mutex_unlock(&mutex);
    return status;
}

void log_dns_statistics() {
    printf("Successful DNS resolutions: %d\n", success_dns_resolutions);
    printf("Failed DNS resolutions: %d\n", failed_dns_resolutions);
}
