#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

// Structure Definitions
typedef struct {
    uint16_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    uint32_t RNTI;
    uint16_t RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Random Number Generator
uint32_t custom_rng_state = 0;

void seed_rng(uint32_t seed) {
    custom_rng_state = seed;
}

uint16_t generate_random_crcflag() {
    custom_rng_state = (custom_rng_state * 1664525u + 1013904223u) & 0xFFFFFFFF;
    return (uint16_t)(custom_rng_state >> 16);
}

// Linked List with Thread Safety
typedef struct {
    Node* head;
    size_t size;
    pthread_mutex_t lock;
    const size_t max_size;
} CRCList;

void init_crc_list(CRCList* list, size_t max_size) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->max_size = max_size;
}

int add_to_crc_list(CRCList* list, uint32_t rnti, uint16_t rx_ue_info_tag) {
    if (pthread_mutex_lock(&list->lock)) return -1;

    if (list->size >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        return -2; // List is full
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation failed
    }

    new_node->data.RNTI = rnti;
    new_node->data.RX_UE_INFORMATION_TAG = rx_ue_info_tag;
    new_node->data.CRC_INDICATION_REL8_TAG.CRCFLAG = generate_random_crcflag();
    new_node->next = list->head;
    list->head = new_node;
    list->size++;

    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

void free_crc_list(CRCList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->size = 0;
    pthread_mutex_destroy(&list->lock);
}

// Example Usage
int main() {
    CRCList crc_list;
    const size_t max_size = 100;
    init_crc_list(&crc_list, max_size);

    seed_rng(12345); // Set seed for reproducibility

    for (uint32_t i = 0; i < max_size + 10; ++i) {
        int result = add_to_crc_list(&crc_list, i, i % 100);
        if (result == -2) {
            printf("Reached maximum list size.\n");
        } else if (result != 0) {
            fprintf(stderr, "Error adding element to the list.\n");
        }
    }

    free_crc_list(&crc_list);

    return 0;
}
