    DATA_PROCESSOR_T* data_processors;
    struct NFAPI_TX_COMMAND_PDU_T *prev, *next;
} NFAPI_TX_COMMAND_PDU_T;

typedef struct {
    NFAPI_TX_COMMAND_PDU_T *head, *tail;
    size_t count;
    pthread_mutex_t lock;
} NFAPI_DoublyLinkedList;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int randomize_fields(TRANSMISSION_CONFIG_REL15_TAG *tag) {
    tag->TX_MODE = rand() % 3;  // Assuming TX_MODE has 3 possible values
    tag->CHANNEL_BANDWIDTH = (rand() % 5 + 1) * 10;  // Example bandwidth options in MHz
    return 0;
}

void init_list(NFAPI_DoublyLinkedList *list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

int add_to_list(NFAPI_DoublyLinkedList *list, NFAPI_TX_COMMAND_PDU_T *pdu) {
    if (list->count >= MAX_ELEMENTS) {
        log_error("Maximum number of elements reached.");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    pdu->prev = list->tail;
    pdu->next = NULL;

    if (list->tail) {
        list->tail->next = pdu;
    } else {
        list->head = pdu;
    }
    list->tail = pdu;
    list->count++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_list(NFAPI_DoublyLinkedList *list) {
    NFAPI_TX_COMMAND_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_TX_COMMAND_PDU_T *next = current->next;
        free(current->data_processors);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

int populate_structure(NFAPI_DoublyLinkedList *list, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        NFAPI_TX_COMMAND_PDU_T *pdu = malloc(sizeof(NFAPI_TX_COMMAND_PDU_T));
        if (!pdu) {
            log_error("Memory allocation failed.");
            return -1;
        }

        pdu->ue_info_tag.RRC_INSTANCE_ID = i + 1;
        randomize_fields(&pdu->transmission_config_rel15_tag);

        pdu->data_processor_count = rand() % 10 + 1; // Random number of data processors
        pdu->data_processors = malloc(pdu->data_processor_count * sizeof(DATA_PROCESSOR_T));
        if (!pdu->data_processors) {
            log_error("Memory allocation failed for data processors.");
            free(pdu);
            return -1;
        }

        if (add_to_list(list, pdu)) {
            free(pdu->data_processors);
            free(pdu);
            return -1;
        }
    }
    return 0;
}

void validate_memory_release(NFAPI_DoublyLinkedList *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_TX_COMMAND_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->data_processors == NULL || current->prev || current->next == NULL) {
            log_error("Memory validation failed.");
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    NFAPI_DoublyLinkedList list;
    init_list(&list);

    if (populate_structure(&list, 50) != 0) {  // Example with 50 elements
        log_error("Failed to populate structure.");
        free_list(&list);
        return EXIT_FAILURE;
    }

    validate_memory_release(&list);
    free_list(&list);

    return EXIT_SUCCESS;
}
