['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define INITIAL_SIZE 10
#define MAX_RESIZE_RATE 5
#define GARBAGE_COLLECTION_INTERVAL 30 // seconds

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    time_t last_access_time[INITIAL_SIZE];
} CRCArray;

CRCArray crc_array = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void initialize_crc_array() {
    crc_array.data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    crc_array.capacity = INITIAL_SIZE;
    for (size_t i = 0; i < INITIAL_SIZE; ++i) {
        crc_array.last_access_time[i] = time(NULL);
    }
}

void resize_crc_array() {
    size_t new_capacity = crc_array.capacity * MAX_RESIZE_RATE;
    NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(crc_array.data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data) {
        memset(new_data + crc_array.capacity, 0, (new_capacity - crc_array.capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        for (size_t i = crc_array.capacity; i < new_capacity; ++i) {
            crc_array.last_access_time[i] = time(NULL);
        }
        crc_array.data = new_data;
        crc_array.capacity = new_capacity;
    } else {
        fprintf(stderr, "Failed to resize array\n");
    }
}

void add_crc_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&crc_array.lock);

    if (crc_array.count >= crc_array.capacity) {
        resize_crc_array();
    }

    crc_array.data[crc_array.count] = *pdu;
    crc_array.last_access_time[crc_array.count] = time(NULL);
    ++crc_array.count;

    pthread_mutex_unlock(&crc_array.lock);
}

void periodic_garbage_collection() {
    while (1) {
        sleep(GARBAGE_COLLECTION_INTERVAL);

        pthread_mutex_lock(&crc_array.lock);

        time_t now = time(NULL);
        for (size_t i = 0; i < crc_array.count; ++i) {
            if (difftime(now, crc_array.last_access_time[i]) > GARBAGE_COLLECTION_INTERVAL) {
                memset(&crc_array.data[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
                crc_array.last_access_time[i] = time(NULL);
            }
        }

        pthread_mutex_unlock(&crc_array.lock);
    }
}

void log_performance() {
    pthread_mutex_lock(&crc_array.lock);

    printf("Current count: %zu\n", crc_array.count);
    printf("Current capacity: %zu\n", crc_array.capacity);

    pthread_mutex_unlock(&crc_array.lock);
}

size_t get_memory_usage() {
    return sizeof(CRCArray) + crc_array.capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T);
}

void export_state(const char* filename, int compress) {
    pthread_mutex_lock(&crc_array.lock);

    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        pthread_mutex_unlock(&crc_array.lock);
        return;
    }

    size_t data_size = crc_array.count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    fwrite(crc_array.data, 1, data_size, file);

    fclose(file);

    pthread_mutex_unlock(&crc_array.lock);
}

void update_crc_pdu(size_t index, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&crc_array.lock);

    if (index < crc_array.count) {
        crc_array.data[index] = *pdu;
        crc_array.last_access_time[index] = time(NULL);
    }

    pthread_mutex_unlock(&crc_array.lock);
}

int main() {
    initialize_crc_array();

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T pdu = {1, 2, rand() % 256};
    add_crc_pdu(&pdu);

    log_performance();
    printf("Memory Usage: %zu bytes\n", get_memory_usage());

    export_state("export.dat", 0);

    pthread_t gc_thread;
    if (pthread_create(&gc_thread, NULL, (void*)periodic_garbage_collection, NULL) != 0) {
        fprintf(stderr, "Failed to create garbage collection thread\n");
    }

    return 0;
}
