void readFloatingPointNumbers(float **numbers, size_t *count) {
    size_t capacity = 10;
    *numbers = malloc(capacity * sizeof(float));
    if (*numbers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    *count = 0;
    float number;
    while (scanf("%f", &number) == 1) {
        if (*count >= capacity) {
            capacity *= 2;
            *numbers = realloc(*numbers, capacity * sizeof(float));
            if (*numbers == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                exit(EXIT_FAILURE);
            }
        }
        (*numbers)[*count] = number;
        ++(*count);
    }

    // Handle end-of-file or input errors
    if (feof(stdin)) {
        printf("End of input reached.\n");
    } else if (ferror(stdin)) {
        fprintf(stderr, "Error reading input.\n");
        exit(EXIT_FAILURE);
    }
}

