#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

// Define the structure for CRC indication.
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for doubly linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

// Doubly linked list structure
typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t lock; // Mutex for thread safety
} CRCList;

CRCList* create_list() {
    CRCList* list = (CRCList*)malloc(sizeof(CRCList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void free_list(CRCList* list);

// Function to append a new element
bool append_element(CRCList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (!list || (list->count >= 10000)) return false;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return false;

    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (!list->head) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        Node* current = list->head;
        while (current && data.RNTI > current->data.RNTI) {
            if (current->next == NULL) break;
            current = current->next;
        }
        if (!current->prev) { // Insert at head
            newNode->next = list->head;
            list->head->prev = newNode;
            list->head = newNode;
        } else if (current->next == NULL) { // Insert at tail
            list->tail->next = newNode;
            newNode->prev = list->tail;
            list->tail = newNode;
        } else { // Insert in middle
            current->prev->next = newNode;
            newNode->prev = current->prev;
            newNode->next = current;
            current->prev = newNode;
        }
    }
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return true;
}

// Function to remove an element by index
bool remove_element(CRCList* list, size_t index) {
    if (!list || index >= list->count) return false;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    for (size_t i = 0; i < index && current; ++i) {
        current = current->next;
    }

    if (!current) { // Should never happen due to earlier check
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    if (current->prev) {
        current->prev->next = current->next;
    } else {
        list->head = current->next; // Removing head
    }

    if (current->next) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev; // Removing tail
    }

    free(current);
    list->count--;
    pthread_mutex_unlock(&list->lock);
    return true;
}

// Function to reset CRCFLAG for all elements
void reset_crcflag(CRCList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current) {
        current->data.CRCFLAG = false;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to get the total number of elements
size_t get_count(CRCList* list) {
    if (!list) return 0;

    pthread_mutex_lock(&list->lock);
    size_t count = list->count;
    pthread_mutex_unlock(&list->lock);
    return count;
}

// Freeing the entire list and its nodes
void free_list(CRCList* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Simulate getting data from an external source
NFAPI_CRC_INDICATION_PDU_T get_external_data() {
    NFAPI_CRC_INDICATION_PDU_T data;
    // Placeholder: In real application, retrieve these values from the external source.
    data.RX_UE_INFORMATION_TAG = rand();
    data.RNTI = rand() % 10000; // Simulating RNTI assignment
    data.CRCFLAG = rand() % 2 == 0;
    return data;
}

// Function to validate list integrity
bool validate_list(CRCList* list) {
    if (!list) return false;

    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    int expected_count = 0;

    while (current && (expected_count < list->count)) {
        // Placeholder: Validate RX_UE_INFORMATION_TAG and RNTI as needed.
        if (!current) break; // Safety check
        if (current->prev && current->data.RNTI <= current->prev->data.RNTI) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }

        current = current->next;
        expected_count++;
    }

    bool result = (expected_count == list->count) && (!current);
    pthread_mutex_unlock(&list->lock);
    return result;
}

// Main function to demonstrate functionality
int main() {
    CRCList* my_list = create_list();
    if (!my_list) {
        fprintf(stderr, "Failed to create list.\n");
        return 1;
    }

    for (int i = 0; i < 10000; ++i) {
        NFAPI_CRC_INDICATION_PDU_T data = get_external_data();
        if (!append_element(my_list, data)) {
            fprintf(stderr, "Failed to append element %d.\n", i);
        }
    }

    printf("Total elements: %zu\n", get_count(my_list));

    reset_crcflag(my_list);
    printf("CRCFLAG reset for all elements.\n");

    if (validate_list(my_list)) {
        printf("List integrity validated successfully.\n");
    } else {
        fprintf(stderr, "List validation failed.\n");
    }

    free_list(my_list);
    return 0;
}
