typedef struct {
    char *filePath;
    char *metadata;
} ImageFile;

typedef struct {
    ImageFile **files;
    size_t count;
    pthread_mutex_t mutex;
} ImageBatch;

ImageBatch* createImageBatch(size_t initialSize) {
    ImageBatch *batch = (ImageBatch *)malloc(sizeof(ImageBatch));
    if (!batch) return NULL;

    batch->files = (ImageFile **)calloc(initialSize, sizeof(ImageFile *));
    if (!batch->files) {
        free(batch);
        return NULL;
    }

    batch->count = 0;
    pthread_mutex_init(&batch->mutex, NULL);
    return batch;
}

int addImageToBatch(ImageBatch *batch, const char *filePath) {
    pthread_mutex_lock(&batch->mutex);

    if (batch->count >= batch->capacity) {
        size_t newCapacity = batch->capacity ? batch->capacity * 2 : 4;
        ImageFile **newFiles = (ImageFile **)realloc(batch->files, newCapacity * sizeof(ImageFile *));
        if (!newFiles) {
            pthread_mutex_unlock(&batch->mutex);
            return -1;
        }
        batch->files = newFiles;
        batch->capacity = newCapacity;
    }

    ImageFile *file = (ImageFile *)malloc(sizeof(ImageFile));
    if (!file) {
        pthread_mutex_unlock(&batch->mutex);
        return -1;
    }

    file->filePath = strdup(filePath);
    file->metadata = NULL; // Placeholder for metadata

    batch->files[batch->count++] = file;

    pthread_mutex_unlock(&batch->mutex);
    return 0;
}

void freeImageBatch(ImageBatch *batch) {
    if (!batch) return;

    pthread_mutex_lock(&batch->mutex);

    for (size_t i = 0; i < batch->count; ++i) {
        free(batch->files[i]->filePath);
        free(batch->files[i]->metadata);
        free(batch->files[i]);
    }

    free(batch->files);
    pthread_mutex_unlock(&batch->mutex);
    pthread_mutex_destroy(&batch->mutex);
    free(batch);
}

void processImage(ImageFile *file) {
    // Simulate processing
    char *timestamp = strdup("2023-10-01T12:00:00Z");
    char *author = strdup("Unknown Author");
    char *log = strdup("Processed successfully");

    file->metadata = malloc(strlen(timestamp) + strlen(author) + strlen(log) + 50);
    if (!file->metadata) {
        log_error("Memory allocation failed for metadata");
        free(timestamp);
        free(author);
        free(log);
        return;
    }

    sprintf(file->metadata, "Timestamp: %s\nAuthor: %s\nLog: %s",
            timestamp, author, log);

    free(timestamp);
    free(author);
    free(log);
}

void* processBatch(void *arg) {
    ImageBatch *batch = (ImageBatch *)arg;

    for (size_t i = 0; i < batch->count; ++i) {
        processImage(batch->files[i]);
    }

    return NULL;
}

int generateComprehensiveReport(const char **imagePaths, size_t numImages) {
    ImageBatch *batch = createImageBatch(0);
    if (!batch) {
        log_error("Failed to create image batch");
        return -1;
    }

    for (size_t i = 0; i < numImages; ++i) {
        if (addImageToBatch(batch, imagePaths[i]) != 0) {
            freeImageBatch(batch);
            log_error("Failed to add image to batch");
            return -1;
        }
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, processBatch, (void *)batch) != 0) {
        log_error("Failed to create processing thread");
        freeImageBatch(batch);
        return -1;
    }

    pthread_join(thread, NULL);

    // Validate processing
    for (size_t i = 0; i < batch->count; ++i) {
        if (!batch->files[i]->metadata) {
            log_error("Processing failed for image");
            freeImageBatch(batch);
            return -1;
        }
    }

    log_info("All images processed successfully");

    freeImageBatch(batch);
    return 0;
}

// Example usage
int main() {
    const char *imagePaths[] = {"image1.jpg", "image2.png", "image3.bmp"};
    size_t numImages = sizeof(imagePaths) / sizeof(imagePaths[0]);

    if (generateComprehensiveReport(imagePaths, numImages) != 0) {
        log_error("Failed to generate report");
    }

    return 0;
}
