// Initialize the log
void init_log(NetworkEventLog* log, size_t initial_capacity) {
    log->entries = (NetworkEventLogEntry*)malloc(initial_capacity * sizeof(NetworkEventLogEntry));
    log->capacity = initial_capacity;
    log->size = 0;
    pthread_mutex_init(&log->lock, NULL);
}

// Insert a new entry
void insert_entry(NetworkEventLog* log, NetworkEventLogEntry entry) {
    pthread_mutex_lock(&log->lock);

    if (log->size == log->capacity) {
        size_t new_capacity = log->capacity * 2;
        log->entries = (NetworkEventLogEntry*)realloc(log->entries, new_capacity * sizeof(NetworkEventLogEntry));
        log->capacity = new_capacity;
    }

    log->entries[log->size++] = entry;

    pthread_mutex_unlock(&log->lock);
}

// Delete an entry by index
void delete_entry(NetworkEventLog* log, size_t index) {
    if (index >= log->size) return;

    pthread_mutex_lock(&log->lock);

    memmove(&log->entries[index], &log->entries[index + 1], (log->size - index - 1) * sizeof(NetworkEventLogEntry));
    log->size--;

    pthread_mutex_unlock(&log->lock);
}

// Modify an entry by index
void modify_entry(NetworkEventLog* log, size_t index, NetworkEventLogEntry new_entry) {
    if (index >= log->size) return;

    pthread_mutex_lock(&log->lock);

    log->entries[index] = new_entry;

    pthread_mutex_unlock(&log->lock);
}

// Filter entries by timestamp
void filter_by_timestamp(NetworkEventLog* log, time_t start_time, time_t end_time, NetworkEventLogEntry** filtered_entries) {
    size_t count = 0;

    for (size_t i = 0; i < log->size; i++) {
        if (log->entries[i].timestamp >= start_time && log->entries[i].timestamp <= end_time) {
            count++;
        }
    }

    *filtered_entries = (NetworkEventLogEntry*)malloc(count * sizeof(NetworkEventLogEntry));

    size_t j = 0;
    for (size_t i = 0; i < log->size; i++) {
        if (log->entries[i].timestamp >= start_time && log->entries[i].timestamp <= end_time) {
            (*filtered_entries)[j++] = log->entries[i];
        }
    }
}

// Sort entries by timestamp or event ID
void sort_entries(NetworkEventLog* log, int by_timestamp) {
    pthread_mutex_lock(&log->lock);

    qsort(log->entries, log->size, sizeof(NetworkEventLogEntry), (by_timestamp ? 
        [](const void* a, const void* b) { return ((NetworkEventLogEntry*)a)->timestamp - ((NetworkEventLogEntry*)b)->timestamp; } :
        [](const void* a, const void* b) { return ((NetworkEventLogEntry*)a)->eventID - ((NetworkEventLogEntry*)b)->eventID; }));

    pthread_mutex_unlock(&log->lock);
}

// Cleanup the log
void cleanup_log(NetworkEventLog* log) {
    pthread_mutex_lock(&log->lock);

    free(log->entries);
    pthread_mutex_unlock(&log->lock);
    pthread_mutex_destroy(&log->lock);
}
