// Dynamic array structure with thread safety
typedef struct {
    TrafficEvent** events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;  // Mutex for synchronizing access
} TrafficEventManager;

// Initialize the traffic event manager
TrafficEventManager* init_manager(size_t initial_capacity) {
    TrafficEventManager* manager = (TrafficEventManager*)malloc(sizeof(TrafficEventManager));
    if (!manager) return NULL;

    manager->events = (TrafficEvent**)calloc(initial_capacity, sizeof(TrafficEvent*));
    if (!manager->events) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

// Check and expand capacity
int ensure_capacity(TrafficEventManager* manager, size_t new_count) {
    if (new_count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        TrafficEvent** new_events = (TrafficEvent**)realloc(manager->events, new_capacity * sizeof(TrafficEvent*));
        if (!new_events) return -1;  // Memory allocation failure

        manager->events = new_events;
        manager->capacity = new_capacity;

        return 0;
    }
    return 0;
}

// Add a new event
int add_event(TrafficEventManager* manager, uint64_t timestamp, EventType type, uint32_t id) {
    pthread_mutex_lock(&manager->lock);

    // Check for duplicate ID
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->id == id) {
            pthread_mutex_unlock(&manager->lock);
            return -1;  // Duplicate event ID
        }
    }

    // Ensure capacity
    if (ensure_capacity(manager, manager->count + 1) != 0) {
        pthread_mutex_unlock(&manager->lock);
        return -2;  // Memory allocation failure
    }

    TrafficEvent* new_event = (TrafficEvent*)malloc(sizeof(TrafficEvent));
    if (!new_event) {
        pthread_mutex_unlock(&manager->lock);
        return -3;  // Memory allocation failure
    }

    new_event->timestamp = timestamp;
    new_event->type = type;
    new_event->id = id;
    manager->events[manager->count++] = new_event;

    pthread_mutex_unlock(&manager->lock);
    return 0;  // Success
}

// Update an existing event by ID
int update_event(TrafficEventManager* manager, uint32_t id, uint64_t timestamp, EventType type) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i]->id == id) {
            TrafficEvent* event = manager->events[i];
            event->timestamp = timestamp;
            event->type = type;

            pthread_mutex_unlock(&manager->lock);
            return 0;  // Success
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1;  // Event ID not found
}

// Retrieve events within a specified time range
TrafficEvent** get_events_in_range(TrafficEventManager* manager, uint64_t start_time, uint64_t end_time, size_t* result_count) {
    pthread_mutex_lock(&manager->lock);

    *result_count = 0;
    TrafficEvent** temp_array = (TrafficEvent**)malloc(manager->count * sizeof(TrafficEvent*));
    if (!temp_array) {
        pthread_mutex_unlock(&manager->lock);
        return NULL;  // Memory allocation failure
    }

    for (size_t i = 0; i < manager->count; ++i) {
        TrafficEvent* event = manager->events[i];
        if (event->timestamp >= start_time && event->timestamp <= end_time) {
            temp_array[(*result_count)++] = event;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return temp_array;  // Caller is responsible for freeing this array
}

// Free the manager and its resources
void free_manager(TrafficEventManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->events[i]);
    }
    free(manager->events);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

