    LogNode* current = log->head;
    while (current) {
        if ((event_id_filter == 0 || current->data.event_id == event_id_filter) &&
            (start_time == 0 || current->data.timestamp >= start_time) &&
            (end_time == 0 || current->data.timestamp <= end_time)) {
