    pthread_mutex_lock(&log->lock);
    LogNode* current = log->head;
    while (current) {
        if (current->data.event_id == event_id) {
            free(current->data.description);
            current->data.description = strdup(new_description);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&log->lock);
}

void delete_entry_by_index(EventLog* log, size_t index) {
    pthread_mutex_lock(&log->lock);
    LogNode **current = &log->head;
    for (size_t i = 0; *current && i < index; ++i) {
        current = &(*current)->next;
    }
    if (*current) {
        LogNode* to_delete = *current;
        *current = to_delete->next;
        free_node(to_delete);
    }
    pthread_mutex_unlock(&log->lock);
}

void delete_entry_by_event_id(EventLog* log, int event_id) {
    pthread_mutex_lock(&log->lock);
    LogNode **current = &log->head;
    while (*current) {
        if ((*current)->data.event_id == event_id) {
            LogNode* to_delete = *current;
            *current = to_delete->next;
            free_node(to_delete);
            break;
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&log->lock);
}

int save_log_to_file(const EventLog* log, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) return -1;

    pthread_mutex_lock(&log->lock);
    LogNode* current = log->head;
    while (current) {
        fprintf(file, "%ld,%d,%s\n", current->data.timestamp,
                current->data.event_id, current->data.description);
        current = current->next;
    }
    pthread_mutex_unlock(&log->lock);

    fclose(file);
    return 0;
}

int load_log_from_file(EventLog* log, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    pthread_mutex_lock(&log->lock);
    LogNode* current = log->head;
    while (current && fscanf(file, "%ld,%d,%ms", &current->data.timestamp,
                             &current->data.event_id, &current->data.description) == 3) {
        current = current->next;
    }
    pthread_mutex_unlock(&log->lock);

    fclose(file);
    return 0;
}

void destroy_log(EventLog* log) {
    pthread_mutex_lock(&log->lock);
    LogNode* current = log->head;
    while (current) {
        LogNode* to_delete = current;
        current = current->next;
        free_node(to_delete);
    }
    pthread_mutex_unlock(&log->lock);
    pthread_mutex_destroy(&log->lock);
}
