int compare_by_timestamp(const void *a, const void *b) {
    NetworkEventLogEntry *entry_a = (NetworkEventLogEntry *)a;
    NetworkEventLogEntry *entry_b = (NetworkEventLogEntry *)b;
    return entry_a->timestamp - entry_b->timestamp;
}

int compare_by_event_id(const void *a, const void *b) {
    NetworkEventLogEntry *entry_a = (NetworkEventLogEntry *)a;
    NetworkEventLogEntry *entry_b = (NetworkEventLogEntry *)b;
    return entry_a->event_id - entry_b->event_id;
}

// Implementations
void init_log_array(LogArray *log, size_t initial_capacity) {
    pthread_mutex_init(&log->lock, NULL);
    log->entries = malloc(initial_capacity * sizeof(NetworkEventLogEntry));
    if (!log->entries) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    log->count = 0;
    log->capacity = initial_capacity;
}

int insert_entry(LogArray *log, const NetworkEventLogEntry *entry) {
    pthread_mutex_lock(&log->lock);

    if (log->count == log->capacity) {
        size_t new_capacity = log->capacity * 2;
        NetworkEventLogEntry *new_entries = realloc(log->entries, new_capacity * sizeof(NetworkEventLogEntry));
        if (!new_entries) {
            perror("Failed to reallocate memory");
            pthread_mutex_unlock(&log->lock);
            return -1;
        }
        log->entries = new_entries;
        log->capacity = new_capacity;
    }

    memcpy(log->entries + log->count, entry, sizeof(NetworkEventLogEntry));
    log->count++;
    pthread_mutex_unlock(&log->lock);
    return 0;
}

int delete_entry_by_id(LogArray *log, int event_id) {
    pthread_mutex_lock(&log->lock);

    for (size_t i = 0; i < log->count; ++i) {
        if (log->entries[i].event_id == event_id) {
            memmove(log->entries + i, log->entries + i + 1, (log->count - i - 1) * sizeof(NetworkEventLogEntry));
            log->count--;
            pthread_mutex_unlock(&log->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&log->lock);
    return -1;
}

int modify_entry(LogArray *log, int event_id, const NetworkEventLogEntry *new_entry) {
    pthread_mutex_lock(&log->lock);

    for (size_t i = 0; i < log->count; ++i) {
        if (log->entries[i].event_id == event_id) {
            memcpy(log->entries + i, new_entry, sizeof(NetworkEventLogEntry));
            pthread_mutex_unlock(&log->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&log->lock);
    return -1;
}

void filter_log_entries(LogArray *log, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&log->lock);

    size_t new_count = 0;
    for (size_t i = 0; i < log->count; ++i) {
        if (log->entries[i].timestamp >= start_time && log->entries[i].timestamp <= end_time) {
            log->entries[new_count++] = log->entries[i];
        }
    }

    log->count = new_count;
    pthread_mutex_unlock(&log->lock);
}

void sort_log_entries(LogArray *log, int (*cmp_func)(const void *, const void *)) {
    pthread_mutex_lock(&log->lock);

    qsort(log->entries, log->count, sizeof(NetworkEventLogEntry), cmp_func);

    pthread_mutex_unlock(&log->lock);
}

void free_log_array(LogArray *log) {
    pthread_mutex_destroy(&log->lock);
    free(log->entries);
}

// LTE message implementations
void init_lte_messages(LTE_DL_CCCH_Message_Type1_T **messages, size_t count) {
    *messages = malloc(count * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!*messages) {
        perror("Failed to allocate memory for LTE messages");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        (*messages)[i].encoder = initialize_encoder(); // Assume this function exists
        (*messages)[i].message.type = rand() % NUM_NAS_MESSAGE_TYPES;
        generate_message_content(&(*messages)[i].message); // Assume this function exists
    }
}

void free_lte_messages(LTE_DL_CCCH_Message_Type1_T *messages, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        destroy_encoder(&messages[i].encoder); // Assume this function exists
    }
    free(messages);
}
