typedef struct record {
    int value;
    char *name;
    long offset_ref;
} Record;

typedef struct node {
    Record *record;
    struct node *next;
} Node;

Node* initialize_arrays_and_records(size_t n) {
    if (n == 0) return NULL;

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    // Allocate memory for arrays
    long *offsets = malloc(n * sizeof(long));
    int *keys = malloc(n * sizeof(int));
    Record **records = malloc(n * sizeof(Record*));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Populate arrays with random values
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = rand() % 1001;
        keys[i] = rand() % 1000 + 1;

        // Allocate and initialize record
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            for (size_t j = 0; j <= i; ++j) free(records[j]);
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        records[i]->value = rand() % 2001 - 1000;

        char *name = malloc(20); // Enough for "record_999\0"
        if (!name) {
            free(records[i]);
            for (size_t j = 0; j < i; ++j) free(records[j]);
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        snprintf(name, 20, "record_%zu", i);
        records[i]->name = name;
        records[i]->offset_ref = offsets[i];
    }

    // Initialize linked list
    Node *head = NULL, *current = NULL;

    for (size_t i = 0; i < n; ++i) {
        Node *new_node = malloc(sizeof(Node));
        if (!new_node) {
            while (head) {
                Node *temp = head;
                head = head->next;
                free(temp->record->name);
                free(temp->record);
                free(temp);
            }
            for (size_t j = 0; j < n; ++j) free(records[j]);
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        new_node->record = records[i];
        new_node->next = NULL;

        if (!head) {
            head = new_node;
        } else {
            current->next = new_node;
        }
        current = new_node;
    }

    // Free arrays
    free(offsets);
    free(keys);
    free(records);

    return head;
}

void cleanup_linked_list(Node *head) {
    while (head) {
        Node *temp = head;
        head = head->next;
        free(temp->record->name);
        free(temp->record);
        free(temp);
    }
}
