#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <dns_sd.h>
#include <time.h>

#define MAX_HOSTNAMES 10
#define DNS_CACHE_SIZE 100

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char hostname[256];
    char ip_address[INET6_ADDRSTRLEN];
    time_t timestamp;
    int in_use;
} DNSCacheEntry;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t dns_cache_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t list_cond = PTHREAD_COND_INITIALIZER;

static NFAPI_CRC_INDICATION_PDU_T* nfa_pdu_list = NULL;
static int pdu_count = 0;
static DNSCacheEntry dns_cache[DNS_CACHE_SIZE];
static char predefined_hostnames[MAX_HOSTNAMES][256] = {"example.com", "test.org"};
static int M; // Configurable parameter for maximum concurrent operations

void initialize_dns_cache() {
    pthread_mutex_lock(&dns_cache_mutex);
    for (int i = 0; i < DNS_CACHE_SIZE; ++i) {
        memset(dns_cache[i].hostname, 0, sizeof(dns_cache[i].hostname));
        memset(dns_cache[i].ip_address, 0, sizeof(dns_cache[i].ip_address));
        dns_cache[i].timestamp = 0;
        dns_cache[i].in_use = 0;
    }
    pthread_mutex_unlock(&dns_cache_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu() {
    pthread_mutex_lock(&list_mutex);

    if (pdu_count == 0) {
        int needed_size = M * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(nfa_pdu_list, needed_size);

        if (!new_list) {
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }

        nfa_pdu_list = new_list;
        pdu_count = M;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &nfa_pdu_list[--pdu_count];

    // Initialize with random CRCFLAG
    pdu->RX_UE_INFORMATION_TAG = rand() % 256;
    pdu->RNTI = rand() % 65536;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu->CRCFLAG = rand() & 1;

    pthread_mutex_unlock(&list_mutex);
    return pdu;
}

void release_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!pdu) return;

    // No explicit deallocation needed since we reuse from a pre-allocated list
    pthread_mutex_lock(&list_mutex);
    ++pdu_count;
    pthread_cond_signal(&list_cond);
    pthread_mutex_unlock(&list_mutex);
}

void dns_resolution_worker() {
    while (1) {
        char *resolved_ips[MAX_HOSTNAMES];
        int num_resolved = 0;

        for (int i = 0; i < MAX_HOSTNAMES && num_resolved < M; ++i) {
            pthread_mutex_lock(&dns_cache_mutex);

            DNSCacheEntry* entry = NULL;
            for (int j = 0; j < DNS_CACHE_SIZE; ++j) {
                if (!strcmp(predefined_hostnames[i], dns_cache[j].hostname) &&
                    time(NULL) - dns_cache[j].timestamp < 300) { // 5 minutes validity
                    resolved_ips[num_resolved++] = dns_cache[j].ip_address;
                    entry = &dns_cache[j];
                    break;
                }
            }

            if (!entry) {
                for (int j = 0; j < DNS_CACHE_SIZE && !entry; ++j) {
                    if (!dns_cache[j].in_use) {
                        entry = &dns_cache[j];
                        strncpy(entry->hostname, predefined_hostnames[i], sizeof(entry->hostname));
                        entry->timestamp = time(NULL);
                        entry->in_use = 1;
                        break;
                    }
                }

                if (entry && !strcmp(predefined_hostnames[i], entry->hostname)) {
                    DNSServiceRef sdref;
                    dns_service_resolve_hostname(sdref, predefined_hostnames[i],
                                                 kDNSServiceFlagsShareConnection,
                                                 kDNSType_A, NULL,
                                                 dns_resolution_callback, entry);
                }
            }

            pthread_mutex_unlock(&dns_cache_mutex);

            if (num_resolved >= M) {
                break; // Limit concurrent DNS requests
            }
        }

        sleep(10); // Interval between DNS resolution cycles
    }
}

void dns_resolution_callback(DNSServiceRef sdref,
                             DNSServiceFlags flags,
                             uint32_t interfaceIndex,
                             DNSServiceErrorType errorCode,
                             const char *fullname,
                             const char *hostname,
                             uint16_t port,
                             uint16_t txtLen,
                             const unsigned char *txtRecord,
                             void *context) {
    if (errorCode != kDNSServiceErr_NoError) return;

    DNSCacheEntry* entry = (DNSCacheEntry*)context;
    pthread_mutex_lock(&dns_cache_mutex);

    if (entry->in_use && !strcmp(entry->hostname, hostname)) {
        inet_ntop(AF_INET, &port, entry->ip_address, INET6_ADDRSTRLEN);
        entry->timestamp = time(NULL);
    }

    entry->in_use = 0;
    pthread_mutex_unlock(&dns_cache_mutex);

    DNSServiceRefDeallocate(sdref);
}

void initialize_system(int max_concurrent_ops) {
    M = max_concurrent_ops;
    srand(time(NULL));

    // Initialize the PDU list
    nfa_pdu_list = malloc(M * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfa_pdu_list) exit(EXIT_FAILURE);
    pdu_count = M;

    initialize_dns_cache();

    pthread_t dns_thread;
    pthread_create(&dns_thread, NULL, (void*)dns_resolution_worker, NULL);

    pthread_detach(dns_thread); // Detach the DNS thread to run independently
}

void cleanup_system() {
    free(nfa_pdu_list);
    nfa_pdu_list = NULL;
}
