#include <unistd.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    unsigned char CRC_INDICATION_REL8_TAG[10];
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_indications(size_t count) {
    if (count == 0)
        return NULL;

    NFAPI_CRC_INDICATION_PDU_T* indications = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < count; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        indications[i].RNTI = rand() % 65536;
        memset(indications[i].CRC_INDICATION_REL8_TAG, rand() % 256, sizeof(indications[i].CRC_INDICATION_REL8_TAG));
        indications[i].CRCFLAG = (rand() % 2) ? 1 : 0;
    }

    return indications;
}

void delete_log_files(const char* path) {
    DIR *dir;
    struct dirent *entry;

    if ((dir = opendir(path)) == NULL) {
        perror("Failed to open directory");
        exit(EXIT_FAILURE);
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char filepath[256];
        snprintf(filepath, sizeof(filepath), "%s/%s", path, entry->d_name);
        unlink(filepath);
    }

    closedir(dir);
}

void execute_command(const char* command, const char* args[], const char* dir) {
    FILE *logFile = fopen("/var/log/app/output.log", "w");
    if (!logFile) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    FILE *errLogFile = fopen("/var/log/app/error.log", "w");
    if (!errLogFile) {
        fclose(logFile);
        perror("Failed to open error log file");
        exit(EXIT_FAILURE);
    }

    pid_t pid = fork();
    if (pid == 0) { // Child process
        char *argv[] = {"sh", "-c", strdup(command), NULL};
        execv("/bin/sh", argv);

        fclose(logFile);
        fclose(errLogFile);
        exit(EXIT_FAILURE);
    } else if (pid < 0) {
        perror("Fork failed");
        fclose(logFile);
        fclose(errLogFile);
        exit(EXIT_FAILURE);
    } else { // Parent process
        int status;
        waitpid(pid, &status, 0);

        FILE* execOutput = popen(command, "r");
        if (execOutput) {
            char buffer[1024];
            while (fgets(buffer, sizeof(buffer), execOutput) != NULL)
                fprintf(logFile, "%s", buffer);
            pclose(execOutput);
        }

        if (WIFEXITED(status)) {
            int exit_status = WEXITSTATUS(status);
            fprintf(errLogFile, "Command exited with status %d\n", exit_status);
        } else if (WIFSIGNALED(status)) {
            int signal_num = WTERMSIG(status);
            fprintf(errLogFile, "Command killed by signal %d\n", signal_num);
        }

        fclose(logFile);
        fclose(errLogFile);
    }
}

int main() {
    size_t nfa_count = 1000; // example count
    NFAPI_CRC_INDICATION_PDU_T* indications = generate_nfa_indications(nfa_count);

    delete_log_files("/var/log/app");

    const char *command = "ls -l";
    const char *args[] = {NULL};
    execute_command(command, args, NULL);

    free(indications);
    return 0;
}
