typedef struct {
    UEIdentityTag ue_identity_tag;
    RRCConnectionReconfigurationMessage rrc_message;
    SecurityContext security_context;
} UEConnectionStatusUpdate;

// Define a node for the linked list
struct ListNode {
    UEConnectionStatusUpdate data;
    struct ListNode* next;
};

// Define the list structure with thread-safe mechanisms
typedef struct {
    struct ListNode* head;
    pthread_mutex_t lock; // Mutex for thread safety
} ConnectionList;

// Function to generate random keys (simplified example)
void generate_random_security_context(SecurityContext* context) {
    // Simple random number generation for illustration
    context->KeySetIdentifier = rand() % 1000;
}

// Initialize the connection list
ConnectionList* create_connection_list() {
    ConnectionList* list = malloc(sizeof(ConnectionList));
    if (list == NULL) {
        fprintf(stderr, "Failed to allocate memory for connection list\n");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to check if a SecurityContext is unique in the list
int is_unique_security_context(ConnectionList* list, SecurityContext context) {
    struct ListNode* current = list->head;
    while (current != NULL) {
        if (current->data.security_context.KeySetIdentifier == context.KeySetIdentifier)
            return 0; // Not unique
        current = current->next;
    }
    return 1; // Unique
}

// Function to add a new UEConnectionStatusUpdate ensuring uniqueness and thread safety
int add_connection_status_update(ConnectionList* list, UEIdentityTag ue_identity_tag,
                                 RRCConnectionReconfigurationMessage rrc_message) {
    pthread_mutex_lock(&list->lock);

    SecurityContext context;
    generate_random_security_context(&context);

    // Ensure the security context is unique
    while (!is_unique_security_context(list, context)) {
        generate_random_security_context(&context);
    }

    UEConnectionStatusUpdate new_entry = { .ue_identity_tag = ue_identity_tag,
                                           .rrc_message = rrc_message,
                                           .security_context = context };

    struct ListNode* new_node = malloc(sizeof(struct ListNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Failed to allocate memory for list node\n");
        return -1; // Memory allocation failure
    }
    new_node->data = new_entry;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to free the connection list and its nodes
void free_connection_list(ConnectionList* list) {
    struct ListNode* current = list->head;
    while (current != NULL) {
        struct ListNode* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Example main function to demonstrate usage
int main() {
    // Initialize random number generator for key generation
    srand(time(NULL));

    ConnectionList* list = create_connection_list();
    if (list == NULL) return -1;

    // Add some entries (example usage)
    UEIdentityTag tag;
    RRCConnectionReconfigurationMessage message;

    add_connection_status_update(list, tag, message);

    // Free the resources
    free_connection_list(list);

    return 0;
}
