void add_metric_to_list(NetworkPerformanceMetrics **head, NetworkPerformanceMetrics *new_metric);
void cleanup_outdated_metrics(NetworkPerformanceMetrics **head, time_t current_time);
void delete_metrics(NetworkPerformanceMetrics *metric);

// Function to initialize and populate the linked list
void* manage_metrics(void *arg) {
    NetworkPerformanceMetrics *head = NULL;

    while (1) {
        pthread_mutex_lock(&list_mutex);

        // Simulate adding a new metric every second for demonstration
        time_t current_time = time(NULL);
        Measurement measurements[MAX_MEASUREMENTS] = { {"latency", 50.0}, {"throughput", 100.0} };
        int num_measurements = 2;
        NetworkPerformanceMetrics *new_metric = create_metrics(rand(), measurements, num_measurements);

        if (new_metric) {
            add_metric_to_list(&head, new_metric);
            log_addition(new_metric);
        }

        // Cleanup outdated metrics based on retention policy
        cleanup_outdated_metrics(&head, current_time - retention_policy_seconds);

        pthread_mutex_unlock(&list_mutex);

        sleep(1);  // Simulate periodic operation every second
    }

    return NULL;
}

NetworkPerformanceMetrics* create_metrics(unsigned long session_id, Measurement measurements[], int num_measurements) {
    if (num_measurements > MAX_MEASUREMENTS) return NULL;

    NetworkPerformanceMetrics *metric = (NetworkPerformanceMetrics *)malloc(sizeof(NetworkPerformanceMetrics));
    if (!metric) return NULL;

    metric->timestamp = time(NULL);
    metric->session_id = session_id;
    metric->num_measurements = num_measurements;
    metric->measurements = (Measurement *)malloc(num_measurements * sizeof(Measurement));

    for (int i = 0; i < num_measurements; ++i) {
        if (!validate_measurement(measurements[i])) continue;
        metric->measurements[i] = measurements[i];
    }

    metric->next = NULL;

    return metric;
}

void add_metric_to_list(NetworkPerformanceMetrics **head, NetworkPerformanceMetrics *new_metric) {
    new_metric->next = *head;
    *head = new_metric;
}

void cleanup_outdated_metrics(NetworkPerformanceMetrics **head, time_t cutoff_time) {
    NetworkPerformanceMetrics *current = *head;
    NetworkPerformanceMetrics *prev = NULL;

    while (current != NULL) {
        if (current->timestamp < cutoff_time) {
            NetworkPerformanceMetrics *to_delete = current;
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            log_deletion(to_delete);
            delete_metrics(to_delete);

            current = current->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

void delete_metrics(NetworkPerformanceMetrics *metric) {
    free(metric->measurements);
    free(metric);
}

int validate_measurement(Measurement measurement) {
    if (strcmp(measurement.type, "latency") == 0 && measurement.value > 100.0) {
        // Correct or skip
        return 0;  // Skip for this example
    }
    // Add more validation rules as needed

