    while (1) {
        pthread_mutex_lock(&list_mutex);
        retention_policy_seconds = rand() % 7200 + 3600;  // Randomly change retention policy between 1 and 2 hours
        pthread_mutex_unlock(&list_mutex);

        sleep(300);  // Adjust every 5 minutes for demonstration purposes
    }
}

