#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    // Define GTPv2_PDU structure as per your protocol specifications
} GTPv2_PDU;

typedef struct {
    // Define TLVEncoder structure with necessary encoding functionalities
} TLVEncoder;

typedef struct {
    TLVEncoder encoder;
    GTPv2_PDU pdu;
    time_t last_accessed;
} GTPV2_Message;

typedef struct LRU_Node {
    int message_type;  // Message type identifier for cache management
    GTPV2_Message *message;
    struct LRU_Node *prev, *next;
} LRU_Node;

typedef struct {
    LRU_Node *head, *tail;
    size_t capacity;
    pthread_mutex_t lock;
} LRUCache;

// Function prototypes
LRUCache* create_cache(size_t capacity);
void destroy_cache(LRUCache *cache);
GTPV2_Message* get_message_from_pool(int message_type);  // Mock function to retrieve messages from pool
void log_error(const char *error_msg);                   // Mock logging function

static void cache_evict(LRUCache *cache) {
    if (cache->head) {
        LRU_Node *evict_node = cache->tail;
        if (evict_node == cache->head) {
            cache->head = cache->tail = NULL;
        } else {
            cache->tail = evict_node->prev;
            cache->tail->next = NULL;
        }
        free(evict_node);
    }
}

GTPV2_Message* get_message(LRUCache *cache, int message_type) {
    pthread_mutex_lock(&cache->lock);

    LRU_Node *current = cache->head;
    while (current) {
        if (current->message_type == message_type) {
            // Move accessed node to head
            if (current != cache->head) {
                if (current == cache->tail) {
                    cache->tail = current->prev;
                    cache->tail->next = NULL;
                } else {
                    current->prev->next = current->next;
                    current->next->prev = current->prev;
                }
                current->next = cache->head;
                current->prev = NULL;
                cache->head->prev = current;
                cache->head = current;
            }

            // Update last accessed time
            current->message->last_accessed = time(NULL);
            pthread_mutex_unlock(&cache->lock);
            return current->message;
        }
        current = current->next;
    }

    // Not found, fetch from pool and add to cache
    GTPV2_Message *new_message = get_message_from_pool(message_type);
    if (!new_message) {
        log_error("Failed to initialize message");
        pthread_mutex_unlock(&cache->lock);
        return NULL;
    }

    LRU_Node *new_node = (LRU_Node *)malloc(sizeof(LRU_Node));
    new_node->message = new_message;
    new_node->message_type = message_type;
    new_node->next = cache->head;
    new_node->prev = NULL;

    if (!cache->head) {
        cache->tail = new_node;
    } else {
        cache->head->prev = new_node;
    }
    cache->head = new_node;

    // Evict the least recently used item if cache is full
    if (LRU_NodeCount(cache) > cache->capacity) {
        cache_evict(cache);
    }

    pthread_mutex_unlock(&cache->lock);
    return new_message;
}

size_t LRU_NodeCount(LRUCache *cache) {
    size_t count = 0;
    LRU_Node *current = cache->head;
    while (current) {
        ++count;
        current = current->next;
    }
    return count;
}

LRUCache* create_cache(size_t capacity) {
    LRUCache *cache = (LRUCache *)malloc(sizeof(LRUCache));
    if (!cache) return NULL;

    cache->head = cache->tail = NULL;
    cache->capacity = capacity;
    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void destroy_cache(LRUCache *cache) {
    LRU_Node *current = cache->head;
    while (current) {
        LRU_Node *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

// Additional functions for dynamic message type registration, logging integration,
// and asynchronous processing would be implemented here.

int main() {
    // Example usage
    LRUCache *cache = create_cache(10);

    int message_type1 = 1;  // Example message type
    GTPV2_Message *message1 = get_message(cache, message_type1);

    if (message1) {
        printf("Message retrieved successfully\n");
    } else {
        printf("Failed to retrieve message\n");
    }

    destroy_cache(cache);
    return 0;
}
```

