    if (!new_pdu) return NULL;
    new_pdu->crc_tag.RX_UE_INFORMATION_TAG = rand(); // Example of setting a random RX_UE_INFORMATION_TAG
    new_pdu->crc_tag.RNTI = RNTI;
    new_pdu->next = NULL;
    return new_pdu;
}

void add_pdu(CRC_Indication_List *list, unsigned int RNTI) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *previous = NULL;

    while (current != NULL && current->crc_tag.RNTI != RNTI) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) { // RNTI not found, add new
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = create_pdu(RNTI);
        if (!new_pdu) {
            pthread_mutex_unlock(&list->lock);
            return; // Handle allocation error gracefully
        }

        if (previous == NULL) { // Empty list case
            list->head = new_pdu;
        } else {
            previous->next = new_pdu;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void update_pdu(CRC_Indication_List *list, unsigned int RNTI) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (current != NULL && current->crc_tag.RNTI != RNTI) {
        current = current->next;
    }

    if (current != NULL) { // PDU found, update it
        current->crc_tag.RX_UE_INFORMATION_TAG = rand(); // Example of setting a new random value
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_pdu(CRC_Indication_List *list, unsigned int RNTI) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *previous = NULL;

    while (current != NULL && current->crc_tag.RNTI != RNTI) {
        previous = current;
        current = current->next;
    }

    if (current != NULL) { // PDU found, remove it
        if (previous == NULL) { // Head of the list case
            list->head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
