#include <stdio.h>
#include <stdlib.h>
import stdatomic.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    // Define the structure fields as needed
    int id;
    char data[256];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    atomic_size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    FILE *backup_file;
} DynamicList;

// Initialize the dynamic list
void init_dynamic_list(DynamicList *list, const char *filename) {
    list->elements = NULL;
    atomic_store(&list->count, 0);
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);

    // Open backup file for serialization/deserialization
    list->backup_file = fopen(filename, "wb+");
    if (!list->backup_file) {
        perror("Failed to open backup file");
        exit(EXIT_FAILURE);
    }
}

// Resize the dynamic array
void resize_dynamic_list(DynamicList *list, size_t new_capacity) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) {
        perror("Failed to resize dynamic list");
        exit(EXIT_FAILURE);
    }

    if (new_capacity > list->capacity) {
        for (size_t i = list->capacity; i < new_capacity; ++i) {
            new_elements[i] = (NFAPI_CRC_INDICATION_PDU_T){0};  // Initialize new elements
        }
    }

    list->elements = new_elements;
    list->capacity = new_capacity;

    pthread_mutex_unlock(&list->lock);
}

// Add an element to the dynamic list
int add_element(DynamicList *list, const NFAPI_CRC_INDICATION_PDU_T *element) {
    if (atomic_load(&list->count) >= MAX_ELEMENTS) {
        fprintf(stderr, "Maximum elements reached\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    if (list->capacity == 0 || atomic_load(&list->count) >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 16 : list->capacity * 2;
        if (new_capacity > MAX_ELEMENTS) new_capacity = MAX_ELEMENTS;
        resize_dynamic_list(list, new_capacity);
    }

    list->elements[atomic_fetch_add(&list->count, 1)] = *element;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Serialize the dynamic list to a file
int serialize_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    if (fseek(list->backup_file, 0, SEEK_SET)) {
        perror("Failed to seek backup file");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    size_t count = atomic_load(&list->count);
    fwrite(&count, sizeof(size_t), 1, list->backup_file);
    fwrite(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, list->backup_file);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Deserialize the dynamic list from a file
int deserialize_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    size_t count;
    if (fread(&count, sizeof(size_t), 1, list->backup_file) != 1) {
        perror("Failed to read backup file");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    resize_dynamic_list(list, count);
    fread(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, list->backup_file);

    atomic_store(&list->count, count);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Periodic synchronization with an external data source
void *sync_with_external_source(DynamicList *list) {
    while (1) {
        // Implement logic to update the list from an external data source

        sleep(10);  // Example: Sync every 10 seconds
    }
}

// Cleanup resources
void cleanup_dynamic_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);

    free(list->elements);
    fclose(list->backup_file);

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
