typedef struct {
    int frequency;
    int bandwidth;
} CarrierInfo;

typedef struct {
    int cellID;
    double rssi;
} NeighborCellInfo;

typedef struct {
    time_t timestamp;
    int rssi;
    double snr;
    CarrierInfo* carrierInfo;
    NeighborCellInfo** neighborCells;
    size_t neighborCount;
} CellMeasurementResult;

typedef struct {
    CellMeasurementResult** results;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

void log_action(const char* action, const char* description) {
    printf("%s: %s\n", action, description);
}

CarrierInfo* create_carrier_info(int frequency, int bandwidth) {
    CarrierInfo* carrier = malloc(sizeof(CarrierInfo));
    if (!carrier) return NULL;
    carrier->frequency = frequency;
    carrier->bandwidth = bandwidth;
    log_action("CREATE", "CarrierInfo created");
    return carrier;
}

void destroy_carrier_info(CarrierInfo* carrier) {
    if (carrier) {
        log_action("DESTROY", "CarrierInfo destroyed");
        free(carrier);
    }
}

NeighborCellInfo* create_neighbor_cell_info(int cellID, double rssi) {
    NeighborCellInfo* neighbor = malloc(sizeof(NeighborCellInfo));
    if (!neighbor) return NULL;
    neighbor->cellID = cellID;
    neighbor->rssi = rssi;
    log_action("CREATE", "NeighborCellInfo created");
    return neighbor;
}

void destroy_neighbor_cell_info(NeighborCellInfo* neighbor) {
    if (neighbor) {
        log_action("DESTROY", "NeighborCellInfo destroyed");
        free(neighbor);
    }
}

DynamicArray* init_dynamic_array(size_t initial_size) {
    DynamicArray* array = malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    pthread_mutex_init(&array->lock, NULL);
    array->count = 0;
    array->results = malloc(initial_size * sizeof(CellMeasurementResult*));
    if (!array->results) {
        free(array);
        return NULL;
    }
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        for (size_t i = 0; i < array->count; ++i) {
            if (array->results[i]) {
                if (array->results[i]->carrierInfo) destroy_carrier_info(array->results[i]->carrierInfo);
                for (size_t j = 0; j < array->results[i]->neighborCount; ++j) {
                    if (array->results[i]->neighborCells[j]) destroy_neighbor_cell_info(array->results[i]->neighborCells[j]);
                }
                free(array->results[i]->neighborCells);
                free(array->results[i]);
            }
        }
        free(array->results);
        pthread_mutex_destroy(&array->lock);
        log_action("DESTROY", "DynamicArray destroyed");
        free(array);
    }
}

int add_measurement_result(DynamicArray* array, CellMeasurementResult* result) {
    if (!array || !result) return -1;

    pthread_mutex_lock(&array->lock);

    size_t new_count = array->count + 1;
    CellMeasurementResult** new_results = realloc(array->results, new_count * sizeof(CellMeasurementResult*));
    if (!new_results) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Insufficient memory
    }

    result->carrierInfo = create_carrier_info(1800, 20); // Example values
    if (!result->carrierInfo) {
        free(new_results);
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    size_t neighbor_count = 3; // Example count
    result->neighborCells = malloc(neighbor_count * sizeof(NeighborCellInfo*));
    if (!result->neighborCells) {
        destroy_carrier_info(result->carrierInfo);
        free(new_results);
        pthread_mutex_unlock(&array->lock);
        return -1;
    }

    for (size_t i = 0; i < neighbor_count; ++i) {
        result->neighborCells[i] = create_neighbor_cell_info(i + 100, -80.0 + i); // Example values
        if (!result->neighborCells[i]) {
            while (--i >= 0) destroy_neighbor_cell_info(result->neighborCells[i]);
            free(result->neighborCells);
            destroy_carrier_info(result->carrierInfo);
            free(new_results);
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
    }

    result->neighborCount = neighbor_count;
    array->results = new_results;
    array->results[array->count] = result;
    ++array->count;

    pthread_mutex_unlock(&array->lock);
    return 0; // Success
}
