void initialize_pdu_list(size_t n) {
    pthread_mutex_lock(&list_lock);

    pdu_list.pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list.pdus) {
        log_event("Memory allocation failed for PDU list");
        return;
    }

    pdu_list.count = 0;

