                break;
            } catch (...) {
                retry_count++;
                if (retry_count >= RETRY_LIMIT) {
                    log_event("Failed to create PDU after retries");
                    continue; // Skip this record on persistent failure
                }
                usleep(retry_interval_ms * 1000);
            }
        }

        if (retry_count < RETRY_LIMIT) {
            pdu_list.count++;
        } else {
            total_attempts--; // Adjust attempts count for failed creations
        }
    }

    pthread_mutex_unlock(&list_lock);
}

// Function to deallocate the list
void free_pdu_list() {
    pthread_mutex_lock(&list_lock);

    if (pdu_list.pdus) {
        free(pdu_list.pdus);
        pdu_list.pdus = NULL;
    }

    pdu_list.count = 0;

    pthread_mutex_unlock(&list_lock);
}

