// Constants
#define RETENTION_PERIOD_SECONDS 3600 // Example retention period
#define LOG_BUFFER_SIZE 1024

typedef struct Measurement {
    double value;
} Measurement;

typedef struct NetworkPerformanceMetrics {
    time_t timestamp;
    char session_id[64];
    Measurement *measurements;
    size_t measurement_count;
    struct NetworkPerformanceMetrics *prev;
    struct NetworkPerformanceMetrics *next;
} NetworkPerformanceMetrics;

// Doubly linked list structure
typedef struct {
    NetworkPerformanceMetrics *head;
    NetworkPerformanceMetrics *tail;
    pthread_mutex_t lock;
    time_t retention_time;
    void* custom_allocator; // Placeholder for a custom allocator, e.g., a memory pool
} PerformanceMetricsList;

// Logger function
void log_message(const char* message) {
    static char buffer[LOG_BUFFER_SIZE];
    snprintf(buffer, LOG_BUFFER_SIZE, "%s\n", message);
    printf("%s", buffer); // For simplicity using printf to log messages
}

// Custom memory allocator functions (simplified)
void* custom_malloc(size_t size) {
    return malloc(size); // Replace with optimized allocation logic
}

void custom_free(void *ptr) {
    free(ptr); // Replace with optimized deallocation logic
}

// Initialize list
PerformanceMetricsList* init_performance_metrics_list(time_t retention_time) {
    PerformanceMetricsList* list = (PerformanceMetricsList*)custom_malloc(sizeof(PerformanceMetricsList));
    if (!list) {
        log_message("Failed to allocate memory for the performance metrics list");
        return NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->retention_time = retention_time;
    // Initialize custom allocator if needed
    return list;
}

// Add metric to list
void add_metric(PerformanceMetricsList* list, const char* session_id, time_t timestamp, Measurement *measurements, size_t count) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetrics* new_metric = (NetworkPerformanceMetrics*)custom_malloc(sizeof(NetworkPerformanceMetrics));
    if (!new_metric) {
        log_message("Failed to allocate memory for a new metric");
        pthread_mutex_unlock(&list->lock);
        return;
    }

    strcpy(new_metric->session_id, session_id);
    new_metric->timestamp = timestamp;
    new_metric->measurements = (Measurement*)custom_malloc(count * sizeof(Measurement));
    if (!new_metric->measurements) {
        log_message("Failed to allocate memory for measurements");
        custom_free(new_metric);
        pthread_mutex_unlock(&list->lock);
        return;
    }
    memcpy(new_metric->measurements, measurements, count * sizeof(Measurement));
    new_metric->measurement_count = count;
    new_metric->prev = list->tail;
    new_metric->next = NULL;

    if (list->tail) {
        list->tail->next = new_metric;
    } else {
        list->head = new_metric;
    }
    list->tail = new_metric;

    pthread_mutex_unlock(&list->lock);
}

// Periodic cleanup function
void* cleanup_old_metrics(void* arg) {
    PerformanceMetricsList* list = (PerformanceMetricsList*)arg;
    while (1) {
        time_t now = time(NULL);

        pthread_mutex_lock(&list->lock);

        NetworkPerformanceMetrics *current = list->head, *to_delete = NULL;

        while (current) {
            if ((now - current->timestamp) > list->retention_time) {
                to_delete = current;
                current = current->next;

                if (to_delete->prev)
                    to_delete->prev->next = to_delete->next;
                else
                    list->head = to_delete->next;

                if (to_delete->next)
                    to_delete->next->prev = to_delete->prev;
                else
                    list->tail = to_delete->prev;

                custom_free(to_delete->measurements);
                custom_free(to_delete);

            } else {
                current = current->next;
            }
        }

        pthread_mutex_unlock(&list->lock);
        sleep(60); // Run cleanup every minute
    }
    return NULL;
}

// Query metrics by session ID
NetworkPerformanceMetrics* query_metrics_by_session_id(PerformanceMetricsList *list, const char* session_id) {
    NetworkPerformanceMetrics *current = list->head;

    pthread_mutex_lock(&list->lock);

    while (current) {
        if (strcmp(current->session_id, session_id) == 0) {
            pthread_mutex_unlock(&list->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}

// Destroy list and free resources
void destroy_performance_metrics_list(PerformanceMetricsList *list) {
    NetworkPerformanceMetrics *current = list->head, *tmp;

    pthread_mutex_lock(&list->lock);

    while (current) {
        tmp = current;
        current = current->next;

        custom_free(tmp->measurements);
        custom_free(tmp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    custom_free(list);
}

// Example usage
int main() {
    // Initialize performance metrics list with a retention period of 1 hour (3600 seconds)
    PerformanceMetricsList* metrics_list = init_performance_metrics_list(RETENTION_PERIOD_SECONDS);

    if (!metrics_list) return -1;

    // Start cleanup thread
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, cleanup_old_metrics, metrics_list);

    // Add some dummy metrics for demonstration purposes (normally you'd fill these dynamically)
    Measurement sample_measurements[] = {{123.45}, {678.90}};
    add_metric(metrics_list, "session_1", time(NULL), sample_measurements, 2);

    // Query example
    NetworkPerformanceMetrics* queried_metrics = query_metrics_by_session_id(metrics_list, "session_1");
    if (queried_metrics) {
        printf("Queried session: %s\n", queried_metrics->session_id);
    }

    sleep(120); // Run for a while before cleaning up resources

    destroy_performance_metrics_list(metrics_list);

    pthread_cancel(cleanup_thread); // Stop the cleanup thread
    pthread_join(cleanup_thread, NULL);

    return 0;
}
```

