typedef struct {
    long offset;
    int key;
    int value;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} RecordList;

void initRandom(int min, int max) {
    srand(time(NULL));
}

int getRandomValue(int min, int max) {
    return rand() % (max - min + 1) + min;
}

RecordList* createRecordList() {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroyRecordList(RecordList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addOrUpdateRecord(RecordList* list, int key, long offset) {
    pthread_mutex_lock(&list->lock);

    // Check if the record exists
    Node** curr = &list->head;
    while (*curr != NULL) {
        if ((*curr)->record.key == key) {
            (*curr)->record.offset = offset;
            (*curr)->record.value = getRandomValue(0, 100); // Example range [0, 100]
            pthread_mutex_unlock(&list->lock);
            return 1; // Updated
        }
        curr = &(*curr)->next;
    }

    // Add new record
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    newNode->record.key = key;
    newNode->record.offset = offset;
    newNode->record.value = getRandomValue(0, 100); // Example range [0, 100]
    newNode->next = *curr;
    *curr = newNode;

    pthread_mutex_unlock(&list->lock);
    return 0; // Added
}

int removeRecordByKey(RecordList* list, int key) {
    pthread_mutex_lock(&list->lock);

    Node** curr = &list->head;
    while (*curr != NULL) {
        if ((*curr)->record.key == key) {
            Node* temp = *curr;
            *curr = (*curr)->next;
            free(temp);
            pthread_mutex_unlock(&list->lock);
            return 0; // Removed
        }
        curr = &(*curr)->next;
    }

    pthread_mutex_unlock(&list->lock);
    return -1; // Not found
}

Record* findRecordByKey(RecordList* list, int key) {
    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current != NULL) {
        if (current->record.key == key) {
            Record* result = &current->record;
            pthread_mutex_unlock(&list->lock);
            return result; // Found
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL; // Not found
}
```

This implementation uses a linked list as the underlying data structure, providing thread safety with mutex locks. It allows adding, updating, and removing records by key while ensuring unique keys are maintained. The integer values of records are initialized randomly within a specified range to ensure variability. Memory management is handled carefully to prevent leaks, and error handling is integrated into operations. This design balances efficiency and usability, making it suitable for integration into larger systems.']

