        return (*(int*)b - *(int*)a);
    });

    if (count == 0) {
        log_error("No valid positive integers provided.");
    }

    return count;
}

size_t allocate_and_initialize(NFAPI_CRC_INDICATION_PDU_T **array, size_t num_elements) {
    *array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        log_error("Memory allocation failed for CRC indication array.");
        return 0;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for (size_t i = 0; i < num_elements; ++i) {
        pthread_mutex_lock(&mutex);

        (*array)[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        (*array)[i].RNTI = rand() % 1000 + 1;
        (*array)[i].CRC_INDICATION_REL8_TAG = rand() % 10 + 1;
        (*array)[i].timestamp = time(NULL);
        (*array)[i].sequence_number = i;
        (*array)[i].cell_identity = rand() % 256;
        (*array)[i].CRCFLAG = (rand() & 0x7FF) | 0x8000; // Apply specific bit masking

        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    return num_elements;
}

void free_resources(NFAPI_CRC_INDICATION_PDU_T *array, int **inputs, size_t input_count) {
    if (array) {
        free(array);
    }
    for (size_t i = 0; i < input_count; ++i) {
        if (inputs[i]) {
            free(inputs[i]);
        }
    }
}

