typedef struct Node {
    LTE_ENB_NODE_STATUS status;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t node_count;
    int successful_operations;
    int failed_operations;
} ENB_LIST;

ENB_LIST* enb_list_init() {
    ENB_LIST* list = (ENB_LIST*)malloc(sizeof(ENB_LIST));
    if (!list) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->node_count = 0;
    list->successful_operations = 0;
    list->failed_operations = 0;

    return list;
}

void enb_list_destroy(ENB_LIST* list) {
    if (!list) return;

    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

int enb_list_add(ENB_LIST* list, LTE_ENB_NODE_STATUS status) {
    if (!list || !status) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        list->failed_operations++;
        return -1;
    }

    pthread_mutex_lock(&list->lock);
    new_node->status = status;
    new_node->next = list->head;
    list->head = new_node;
    list->node_count++;

    pthread_mutex_unlock(&list->lock);
    list->successful_operations++;
    return 0;
}

int enb_list_remove(ENB_LIST* list, int enb_id) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head, *prev = NULL;
    while (current && current->status.enb_id != enb_id) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        list->failed_operations++;
        return -1;
    }

    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }

    free(current);
    list->node_count--;

    pthread_mutex_unlock(&list->lock);
    list->successful_operations++;
    return 0;
}

int enb_list_update(ENB_LIST* list, int enb_id, LTE_ENB_NODE_STATUS new_status) {
    if (!list || !new_status) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    while (current && current->status.enb_id != enb_id) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list->lock);
        list->failed_operations++;
        return -1;
    }

    current->status = new_status;

    pthread_mutex_unlock(&list->lock);
    list->successful_operations++;
    return 0;
}

int enb_list_query(ENB_LIST* list, int (*predicate)(LTE_ENB_NODE_STATUS), void** result_buffer, size_t buffer_size) {
    if (!list || !predicate || !result_buffer) return -1;

    pthread_mutex_lock(&list->lock);

    Node *current = list->head;
    size_t count = 0;
    while (current && count < buffer_size) {
        if (predicate(current->status)) {
            if (count >= buffer_size) {
                pthread_mutex_unlock(&list->lock);
                list->failed_operations++;
                return -1; // Buffer overflow
            }
            ((LTE_ENB_NODE_STATUS*)*result_buffer)[count++] = current->status;
        }
        current = current->next;
    }

    if (count == 0) {
        pthread_mutex_unlock(&list->lock);
        list->failed_operations++;
        return -1; // No match found
    }

    pthread_mutex_unlock(&list->lock);
    *result_buffer = realloc(*result_buffer, count * sizeof(LTE_ENB_NODE_STATUS));
    if (!*result_buffer) {
        list->failed_operations++;
        return -1;
    }
    list->successful_operations++;
    return (int)count;
}

// Example predicate function
int uptime_predicate(LTE_ENB_NODE_STATUS status) {
    return status.uptime > 3600; // Uptime greater than an hour
}
