        fprintf(stderr, "Requested entries exceed maximum allowed.\n");
        *status = -1;
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = NULL;
    unsigned int tags[MAX_ENTRIES] = {0};
    size_t current_size = 0;

    srand(time(NULL));

