            array[i].RX_UE_INFORMATION_TAG = new_tag;
            array[i].RNTI = rand() % 65536;
            array[i].CRC_FLAG = rand() % 2;
        }

        if (validate_structures(array, n_entries)) {
            current_size = n_entries;
            break;
        } else {
            fprintf(stderr, "Duplicate tags found. Retrying...\n");
            free(array);
            array = NULL;
        }
    }

    if (current_size != n_entries) {
        fprintf(stderr, "Failed to initialize structures after 3 retries.\n");
        *status = -1;
        return NULL;
    }

    perform_memory_stress_test(array, n_entries);

    printf("Memory usage and performance metrics:\n");
    printf("Total allocated memory: %zu bytes\n", n_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    printf("Initialization successful.\n");

    *status = 0;
    return array;
}

