                    memcpy(tag_cache->tags_cache + tag_cache->cache_size, new_tags, new_size * sizeof(uint16_t));
                    tag_cache->cache_size += new_size;
                }
                pthread_mutex_unlock(&tag_cache->lock);
            }

            pthread_mutex_lock(&tag_cache->lock);
            if (tag_cache->cache_size > 0) {
                array[i].RX_UE_INFORMATION_TAG = tag_cache->tags_cache[--(tag_cache->cache_size)];
                pthread_mutex_unlock(&tag_cache->lock);

                uint16_t rnti = fetch_rnti(retry);
                array[i].RNTI = rnti;

                // Generate a random CRC flag
                srand(time(NULL) + i);  // Seed with time and index for variability
                array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
            } else {
                pthread_mutex_unlock(&tag_cache->lock);
                retry++;
                if (retry > MAX_RETRY) return NULL;  // Handle retries exceeding max limit
            }
        } while (tag_cache->cache_size == 0);

    }

    return array;
}

