#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UE_TAG;

typedef struct {
    UE_TAG ue_tag;
    uint8_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    UE_TAG rx_ue_information_tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum { DEBUG, INFO, ERROR } LogLevel;

#define LOG_FILE "nfa_crc_log.txt"

static pthread_rwlock_t list_lock = PTHREAD_RWLOCK_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *head = NULL;
static size_t element_count = 0;
static float total_crcflag_value = 0.0f;

void log_message(LogLevel level, const char *format, ...) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) return;

    const char *level_str = (level == DEBUG) ? "DEBUG" : (level == INFO) ? "INFO" : "ERROR";
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    va_list args;
    va_start(args, format);
    fprintf(log_file, "[%s] [%s] ", timestamp, level_str);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    va_end(args);

    fclose(log_file);
}

void add_element(UE_TAG ue_tag, int rnti) {
    pthread_rwlock_wrlock(&list_lock);

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        log_message(ERROR, "Memory allocation failed for new node.");
        pthread_rwlock_unlock(&list_lock);
        return;
    }

    new_node->rx_ue_information_tag = ue_tag;
    new_node->rnti = rnti;
    new_node->crc_indication_rel8_tag.CRCFLAG = rand() % 2; // Random CRCFLAG
    total_crcflag_value += new_node->crc_indication_rel8_tag.CRCFLAG;

    new_node->next = head;
    head = new_node;
    element_count++;

    log_message(INFO, "Added new element with RX_UE_INFORMATION_TAG=%d and RNTI=%d", ue_tag.RX_UE_INFORMATION_TAG, rnti);

    pthread_rwlock_unlock(&list_lock);
}

void remove_duplicates() {
    pthread_rwlock_wrlock(&list_lock);

    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *runner = current->next;
        while (runner) {
            if ((current->rx_ue_information_tag.RX_UE_INFORMATION_TAG == runner->rx_ue_information_tag.RX_UE_INFORMATION_TAG) &&
                (current->rnti == runner->rnti)) {
                NFAPI_CRC_INDICATION_PDU_T *temp = runner;
                current->next = runner->next;
                free(temp);
                element_count--;
            }
            runner = runner->next;
        }
        current = current->next;
    }

    log_message(INFO, "Removed duplicates from the list.");
    pthread_rwlock_unlock(&list_lock);
}

void clear_list() {
    pthread_rwlock_wrlock(&list_lock);

    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    head = NULL;
    element_count = 0;
    total_crcflag_value = 0.0f;

    log_message(INFO, "Cleared the list.");
    pthread_rwlock_unlock(&list_lock);
}

void log_statistics() {
    pthread_rwlock_rdlock(&list_lock);

    float average_crcflag = (element_count > 0) ? (total_crcflag_value / element_count) : 0;
    log_message(DEBUG, "Total elements: %zu, Average CRCFLAG value: %.2f", element_count, average_crcflag);

    pthread_rwlock_unlock(&list_lock);
}

void initialize_list() {
    srand(time(NULL));
    log_message(INFO, "Initialized the list management system.");
}

int main() {
    initialize_list();

    // Simulate adding elements
    for (int i = 0; i < 10; ++i) {
        UE_TAG ue_tag = { .RX_UE_INFORMATION_TAG = rand(), .RNTI = rand() % 100 };
        add_element(ue_tag, ue_tag.RNTI);
    }

    // Log statistics
    log_statistics();

    // Remove duplicates
    remove_duplicates();

    // Clear the list
    clear_list();

    return 0;
}
```

