    uint8_t CRC_INDICATION_REL8_TAG[32];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DynamicArray;

typedef struct {
    FILE *log_file;
    pthread_mutex_t log_mutex;
} Logger;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->mutex, NULL);
    pthread_cond_init(&array->cond, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    if (array) {
        free(array->data);
        pthread_mutex_destroy(&array->mutex);
        pthread_cond_destroy(&array->cond);
        free(array);
    }
}

void resize_if_needed(DynamicArray *array, size_t new_size) {
    if (new_size > array->capacity) {
        size_t new_capacity = new_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(array->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!new_data) {
            perror("Failed to resize dynamic array");
            exit(EXIT_FAILURE);
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
}

void log_operation(Logger *logger, const char *operation, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&logger->log_mutex);
    fprintf(logger->log_file, "%s: RX_UE_INFORMATION_TAG=%u, RNTI=%u\n", operation, pdu.RX_UE_INFORMATION_TAG, pdu.RNTI);
    pthread_mutex_unlock(&logger->log_mutex);
}

Logger* create_logger(const char *filename) {
    Logger *logger = malloc(sizeof(Logger));
    logger->log_file = fopen(filename, "a");
    if (!logger->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&logger->log_mutex, NULL);
    return logger;
}

void destroy_logger(Logger *logger) {
    fclose(logger->log_file);
    pthread_mutex_destroy(&logger->log_mutex);
    free(logger);
}

int validate_pdu(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Implement checksum or other validation logic
    return 1; // Assume valid for this example
}

void add_element(DynamicArray *array, Logger *logger, const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!validate_pdu(pdu)) {
        printf("Invalid PDU received\n");
        return;
    }

    pthread_mutex_lock(&array->mutex);
    resize_if_needed(array, array->size + 1);
    memcpy(&array->data[array->size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->size++;
    log_operation(logger, "Added", *pdu);
    pthread_mutex_unlock(&array->mutex);
}

void update_element(DynamicArray *array, Logger *logger, uint16_t rnti, const NFAPI_CRC_INDICATION_PDU_T *new_pdu) {
    if (!validate_pdu(new_pdu)) {
        printf("Invalid PDU received\n");
        return;
    }

    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].RNTI == rnti) {
            memcpy(&array->data[i], new_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            log_operation(logger, "Updated", *new_pdu);
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynamicArray *array, uint16_t rnti) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].RNTI == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            memcpy(result, &array->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&array->mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return NULL;
}

void remove_element(DynamicArray *array, Logger *logger, uint16_t rnti) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i].RNTI == rnti) {
            log_operation(logger, "Removed", array->data[i]);
            memmove(&array->data[i], &array->data[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array->size - i - 1));
            array->size--;
            break;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void batch_add_elements(DynamicArray *array, Logger *logger, const NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count) {
    pthread_mutex_lock(&array->mutex);
    resize_if_needed(array, array->size + count);
    memcpy(&array->data[array->size], pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    array->size += count;
    for (size_t i = 0; i < count; ++i) {
        log_operation(logger, "Batch Added", pdus[i]);
    }
    pthread_mutex_unlock(&array->mutex);
}

void batch_remove_elements(DynamicArray *array, Logger *logger, const uint16_t *rntis, size_t count) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size;) {
        int found = 0;
        for (size_t j = 0; j < count; ++j) {
            if (array->data[i].RNTI == rntis[j]) {
                log_operation(logger, "Batch Removed", array->data[i]);
                memmove(&array->data[i], &array->data[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array->size - i - 1));
                array->size--;
                found = 1;
                break;
            }
        }
        if (!found) {
            ++i;
        }
    }
    pthread_mutex_unlock(&array->mutex);
}

void integrity_check(DynamicArray *array) {
    // Implement a lightweight heuristic to determine when full checks are necessary
    size_t expected_size = array->size;  // Assume accurate, but implement more complex logic as needed

    if (expected_size != array->size) {
        printf("Integrity check failed: mismatched sizes\n");
    }

    for (size_t i = 0; i < array->size - 1; ++i) {
        if (array->data[i].RNTI == array->data[i + 1].RNTI) {
            printf("Integrity check found duplicate RNTI: %u\n", array->data[i].RNTI);
        }
    }

    // Additional checks for CRC values, etc.
}

void handle_capacity_limit(DynamicArray *array) {
    if (array->size >= MAX_ELEMENTS) {
        printf("Warning: approaching maximum capacity of elements\n");
    }
}

int main() {
    DynamicArray *array = create_dynamic_array();
    Logger *logger = create_logger("operation_log.txt");

