    if (file != NULL) {
        fprintf(file, "%s\n", message);
        fclose(file);
    }
    pthread_mutex_unlock(&lock);
}

int find_largest_integer(int *arr, size_t n) {
    int largest = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

