        pdus[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Random CRCFLAG
    }
}

void process_input(int max_array_size, size_t num_pdus, const char *log_file) {
    int *arr = NULL;
    size_t n = 0;

    printf("Enter integers separated by spaces: ");
    char buffer[1024];
    if (fgets(buffer, sizeof(buffer), stdin) != NULL) {
        char *token = strtok(buffer, " \n");
        while (token != NULL && n < max_array_size) {
            errno = 0;
            long val = strtol(token, NULL, 10);
            if (errno == ERANGE || val > INT_MAX || val < INT_MIN) {
                log_error(log_file, "Invalid integer value encountered.");
                break;
            }
            arr = realloc(arr, (n + 1) * sizeof(int));
            if (arr == NULL) {
                log_error(log_file, "Memory allocation failed.");
                free(arr);
                return;
            }
            arr[n++] = val;
            token = strtok(NULL, " \n");
        }
    }

    if (n == 0) {
        log_error(log_file, "Empty input list received.");
        free(arr);
        return;
    }

    int largest = find_largest_integer(arr, n);
    printf("Largest integer: %d\n", largest);

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
        log_error(log_file, "Memory allocation failed for PDUs.");
    } else {
        generate_crc_indications(pdus, num_pdus);
        free(pdus); // Free after use
    }

    free(arr);
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <max_array_size> <num_pdus> <log_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    size_t max_array_size = strtoul(argv[1], NULL, 10);
    size_t num_pdus = strtoul(argv[2], NULL, 10);
