    snprintf(nas_msg->content, sizeof(nas_msg->content), "Random Content %d", rand());
}

// Function to process CCCH and CRC PDU
void* process_CCCH_and_CRC_PDU(void *arg) {
    size_t num_messages = *((size_t*) arg);
    LTE_DL_CCCH_Message_Type1_T *ccch_messages = malloc(num_messages * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!ccch_messages) {
        perror("Failed to allocate memory for CCCH messages");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *crc_pdus = malloc(num_messages * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_pdus) {
        perror("Failed to allocate memory for CRC PDUs");
        free(ccch_messages);
        return NULL;
    }

    pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < num_messages; ++i) {
        ccch_messages[i].encoder.sequence_number = rand();
        generate_random_nas_message(&ccch_messages[i].nas_message);

        crc_pdus[i].crc_tag.RX_UE_INFORMATION_TAG = rand();
        crc_pdus[i].crc_tag.RNTI = rand();
        crc_pdus[i].crc_tag.CRCFLAG = (rand() % 2) ? 1 : 0;

        // Logging mechanism
        pthread_mutex_lock(&log_mutex);
        time_t current_time = time(NULL);
        printf("[%ld] Thread ID: %lu - Processed CCCH message #%zu with CRCFLAG: %d\n",
               current_time, (unsigned long)pthread_self(), i, crc_pdus[i].crc_tag.CRCFLAG);
        pthread_mutex_unlock(&log_mutex);

        // Simulate a delay for processing
        usleep(1000);
    }

    free(ccch_messages);
    free(crc_pdus);
    pthread_mutex_destroy(&log_mutex);

    return NULL;
}

int main() {
    const size_t num_threads = 4;
    const size_t messages_per_thread = 10;

    pthread_t threads[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, process_CCCH_and_CRC_PDU, &messages_per_thread)) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
```

