['Below is a C implementation for managing dynamic arrays of `MAC_CONTEXT_T` structures with thread safety, periodic purging, statistics, and integration handling:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_COMMANDS 1000

typedef struct {
    int command_id;
    time_t timestamp; // For latency calculation
} MAC_COMMAND;

typedef struct {
    char config_data[256]; // Placeholder for LMAC_CONFIG data
    time_t creation_time;
} LMAC_CONFIG;

typedef struct {
    LMAC_CONFIG lmac_config;
    MAC_COMMAND commands[MAX_COMMANDS];
    int command_count;
    pthread_mutex_t lock; // For thread safety
} MAC_CONTEXT_T;

typedef struct {
    MAC_CONTEXT_T *contexts;
    size_t count;
    size_t capacity;
    pthread_mutex_t contexts_lock;
    pthread_cond_t not_empty;
    pthread_t purge_thread;
    int age_threshold;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity, int age_threshold) {
    DynamicArray *array = malloc(sizeof(DynamicArray));
    array->contexts = calloc(initial_capacity, sizeof(MAC_CONTEXT_T));
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->contexts_lock, NULL);
    pthread_cond_init(&array->not_empty, NULL);
    pthread_mutex_init(&array->contexts[0].lock, NULL); // Initialize all locks
    for (size_t i = 1; i < initial_capacity; ++i) {
        pthread_mutex_init(&array->contexts[i].lock, NULL);
    }
    array->age_threshold = age_threshold;
    pthread_create(&array->purge_thread, NULL, purge_outdated_configs, array);
    return array;
}

void free_dynamic_array(DynamicArray *array) {
    pthread_cancel(array->purge_thread);
    for (size_t i = 0; i < array->count; ++i) {
        pthread_mutex_destroy(&array->contexts[i].lock);
    }
    pthread_mutex_destroy(&array->contexts_lock);
    pthread_cond_destroy(&array->not_empty);
    free(array->contexts);
    free(array);
}

static void* purge_outdated_configs(void *arg) {
    DynamicArray *array = (DynamicArray *)arg;
    while (1) {
        sleep(60); // Run every 60 seconds
        time_t now = time(NULL);
        pthread_mutex_lock(&array->contexts_lock);
        for (size_t i = 0; i < array->count;) {
            if ((now - array->contexts[i].lmac_config.creation_time) > array->age_threshold) {
                remove_context(array, i);
            } else {
                ++i;
            }
        }
        pthread_mutex_unlock(&array->contexts_lock);
    }
}

void add_context(DynamicArray *array, MAC_CONTEXT_T context) {
    pthread_mutex_lock(&array->contexts_lock);
    if (array->count == array->capacity) {
        array->capacity *= 2;
        array->contexts = realloc(array->contexts, array->capacity * sizeof(MAC_CONTEXT_T));
    }
    for (size_t i = 0; i < MAX_COMMANDS; ++i) {
        pthread_mutex_init(&array->contexts[array->count].lock, NULL);
    }
    array->contexts[array->count++] = context;
    pthread_cond_signal(&array->not_empty);
    pthread_mutex_unlock(&array->contexts_lock);
}

void remove_context(DynamicArray *array, size_t index) {
    if (index < array->count) {
        pthread_mutex_lock(&array->contexts[index].lock);
        pthread_mutex_destroy(&array->contexts[index].lock);
        for (size_t i = index; i < array->count - 1; ++i) {
            array->contexts[i] = array->contexts[i + 1];
        }
        --array->count;
        pthread_mutex_unlock(&array->contexts_lock);
    }
}

void add_command(DynamicArray *array, size_t context_index, MAC_COMMAND command) {
    if (context_index < array->count && array->contexts[context_index].command_count < MAX_COMMANDS) {
        pthread_mutex_lock(&array->contexts[context_index].lock);
        array->contexts[context_index].commands[array->contexts[context_index].command_count++] = command;
        pthread_mutex_unlock(&array->contexts[context_index].lock);
    }
}

void remove_command(DynamicArray *array, size_t context_index, int command_id) {
    if (context_index < array->count) {
        pthread_mutex_lock(&array->contexts[context_index].lock);
        for (int i = 0; i < array->contexts[context_index].command_count; ++i) {
            if (array->contexts[context_index].commands[i].command_id == command_id) {
                for (int j = i; j < array->contexts[context_index].command_count - 1; ++j) {
                    array->contexts[context_index].commands[j] = array->contexts[context_index].commands[j + 1];
                }
                --array->contexts[context_index].command_count;
                break;
            }
        }
        pthread_mutex_unlock(&array->contexts[context_index].lock);
    }
}

MAC_COMMAND* get_command(DynamicArray *array, size_t context_index, int command_id) {
    if (context_index < array->count) {
        pthread_mutex_lock(&array->contexts[context_index].lock);
        for (int i = 0; i < array->contexts[context_index].command_count; ++i) {
            if (array->contexts[context_index].commands[i].command_id == command_id) {
                MAC_COMMAND *cmd = &array->contexts[context_index].commands[i];
                pthread_mutex_unlock(&array->contexts[context_index].lock);
                return cmd;
            }
        }
        pthread_mutex_unlock(&array->contexts[context_index].lock);
    }
    return NULL;
}

void print_statistics(DynamicArray *array) {
    size_t total_commands = 0;
    double total_latency = 0.0;
    time_t now = time(NULL);

    pthread_mutex_lock(&array->contexts_lock);
    for (size_t i = 0; i < array->count; ++i) {
        pthread_mutex_lock(&array->contexts[i].lock);
        total_commands += array->contexts[i].command_count;
        for (int j = 0; j < array->contexts[i].command_count; ++j) {
            double latency = difftime(now, array->contexts[i].commands[j].timestamp);
            if (latency > 0) {
                total_latency += latency;
            }
        }
        pthread_mutex_unlock(&array->contexts[i].lock);
    }
    pthread_mutex_unlock(&array->contexts_lock);

    printf("Active contexts: %zu\n", array->count);
    printf("Total commands processed: %zu\n", total_commands);
    if (total_commands > 0) {
        printf("Average command latency: %.2f seconds\n", total_latency / total_commands);
    } else {
        printf("Average command latency: N/A\n");
    }
}
```

### Key Points:
- **Thread Safety**: Each `MAC_CONTEXT_T` has a mutex lock to ensure thread safety during operations.
- **Purge Mechanism**: A separate thread periodically purges outdated configurations based on the age threshold.
- **Statistics**: The function calculates and prints statistics about active contexts, total commands processed, and average command latency.
- **Memory Management**: Efficient memory allocation and deallocation are handled using `malloc`, `realloc`, and `free`.
- **Scalability**: The dynamic array doubles its capacity when needed, allowing it to scale with the number of contexts.']

