static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static size_t max_structures = 100; // Default value, configurable
static LTE_DL_CCCH_Message_Type1_T *messages = NULL;
static size_t current_size = 0;

void configure_max_structures(size_t new_max) {
    pthread_mutex_lock(&lock);
    if (new_max != max_structures) {
        max_structures = new_max;
        printf("Max structures configured to: %zu\n", max_structures);
    }
    pthread_mutex_unlock(&lock);
}

size_t get_random_message_type() {
    return rand() % MAX_MESSAGE_TYPES + 1; // Random type between 1 and MAX_MESSAGE_TYPES
}

void generate_nas_message(NAS_Message *message) {
    message->message_type = get_random_message_type();
    snprintf(message->content, sizeof(message->content), "Random content for type %d", message->message_type);
}

int initialize_messages(size_t num_structures) {
    pthread_mutex_lock(&lock);

    if (num_structures > max_structures) {
        fprintf(stderr, "Requested structures exceed maximum limit.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    LTE_DL_CCCH_Message_Type1_T *new_messages = realloc(messages, num_structures * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!new_messages) {
        fprintf(stderr, "Memory allocation failed.\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    for (size_t i = 0; i < num_structures; ++i) {
        new_messages[i].encoder.initialized = 1; // Simulate TLVEncoder initialization
        generate_nas_message(&new_messages[i].nas_message);
    }

    messages = new_messages;
    current_size = num_structures;

    pthread_mutex_unlock(&lock);

    printf("Successfully initialized %zu structures.\n", num_structures);
    return 0;
}

void health_check_and_reinitialize() {
    pthread_mutex_lock(&lock);

    for (size_t i = 0; i < current_size; ++i) {
        if (!messages[i].encoder.initialized) {
            printf("Re-initializing structure at index %zu\n", i);
            messages[i].encoder.initialized = 1;
            generate_nas_message(&messages[i].nas_message);
        }
    }

    pthread_mutex_unlock(&lock);
}

void free_messages() {
    pthread_mutex_lock(&lock);

    if (messages) {
        free(messages);
        messages = NULL;
        current_size = 0;
        printf("Memory deallocated for structures.\n");
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    srand(time(NULL));
    configure_max_structures(150); // Example configuration
    initialize_messages(50);

    health_check_and_reinitialize();

    free_messages();
    return 0;
}
