['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <stdint.h>
#include <string.h>

#define MAX_STRUCTS 10000
#define MEMORY_POOL_SIZE (MAX_STRUCTS * sizeof(NFAPI_CRC_INDICATION_PDU_T))
#define ALIGNMENT 16

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char *pool;
    size_t pool_size;
    pthread_mutex_t lock;
    unsigned long seed;
} MemoryPool;

static int random_seed = 0;

void set_random_seed(unsigned long new_seed) {
    random_seed = new_seed;
}

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;

    mp->pool_size = ((size + ALIGNMENT - 1) / ALIGNMENT) * ALIGNMENT; // Align to 16 bytes
    mp->pool = (char*)aligned_alloc(ALIGNMENT, mp->pool_size);
    if (!mp->pool) {
        free(mp);
        return NULL;
    }

    pthread_mutex_init(&mp->lock, NULL);
    mp->seed = random_seed ? random_seed : time(NULL);

    return mp;
}

void* memory_pool_allocate(MemoryPool* mp, size_t size) {
    if (!mp || !size) return NULL;

    pthread_mutex_lock(&mp->lock);

    char *current = mp->pool;
    size_t aligned_size = ((size + ALIGNMENT - 1) / ALIGNMENT) * ALIGNMENT; // Align to 16 bytes

    for (char *end = mp->pool + mp->pool_size - aligned_size; current < end; current += aligned_size) {
        if (*(uint64_t*)current == UINT64_MAX) { // Check the alignment block's first value for validity
            *(uint64_t*)current = UINT64_MAX;
            pthread_mutex_unlock(&mp->lock);
            return (void*)(current + sizeof(uint64_t)); // Skip over the control word
        }
    }

    pthread_mutex_unlock(&mp->lock);
    return NULL; // Pool full
}

void memory_pool_free(MemoryPool* mp, void *ptr) {
    if (!mp || !ptr) return;

    ptr = (char*)ptr - sizeof(uint64_t); // Move back to control word

    pthread_mutex_lock(&mp->lock);
    *(uint64_t*)ptr = 0; // Mark as free
    pthread_mutex_unlock(&mp->lock);
}

void* populate_structs(MemoryPool *mp, int num_structs) {
    if (!mp || num_structs <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *structs = (NFAPI_CRC_INDICATION_PDU_T*)memory_pool_allocate(mp, num_structs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structs) return NULL;

    for (int i = 0; i < num_structs; ++i) {
        structs[i].RX_UE_INFORMATION_TAG = rand_r(&mp->seed); // Simulating external data source
        structs[i].RNTI = rand_r(&mp->seed);
        memset(structs[i].CRC_INDICATION_REL8_TAG, 0, sizeof(structs[i].CRC_INDICATION_REL8_TAG));
        structs[i].CRCFLAG = (rand_r(&mp->seed) % 2); // Randomly set CRCFLAG
    }

    return (void*)structs;
}

int main() {
    MemoryPool *mp = create_memory_pool(MEMORY_POOL_SIZE);
    if (!mp) {
        fprintf(stderr, "Memory pool creation failed.\n");
        return EXIT_FAILURE;
    }

    int num_structs = 1000; // Example number of structures to populate
    void* structs = populate_structs(mp, num_structs);
    if (!structs) {
        fprintf(stderr, "Failed to populate structures.\n");
        destroy_memory_pool(mp);
        return EXIT_FAILURE;
    }

    // Simulate work with the data

    destroy_memory_pool(mp);
    return EXIT_SUCCESS;
}

void destroy_memory_pool(MemoryPool* mp) {
    if (mp) {
        pthread_mutex_destroy(&mp->lock);
        free(mp->pool);
        free(mp);
    }
}
