#define MAX_ELEMENTS 100

// Function to initialize linked list with unique RNTIs and random CRCFLAGS
NFAPI_CRC_INDICATION_PDU_T* init_linked_list(int N, int M) {
    if (M > MAX_ELEMENTS || N > M) return NULL;

    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *current = NULL;

    for (int i = 1; i <= N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            // Free previously allocated nodes
            while (head != NULL) {
                NFAPI_CRC_INDICATION_PDU_T *temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;  // Allocation failure
        }

        new_node->RX_UE_INFORMATION_TAG = rand();  // Assign random or specific values as needed
        new_node->RNTI = i;
        new_node->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;  // Randomly set CRCFLAG to 0 or 1

        new_node->next = NULL;

        if (head == NULL) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    return head;
}

// Function to print the linked list
void print_linked_list(NFAPI_CRC_INDICATION_PDU_T* head) {
