    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        TX_CELL_CONTEXT_T **new_array = realloc(array->contexts, new_capacity * sizeof(TX_CELL_CONTEXT_T *));

        if (!new_array) {
            pthread_rwlock_unlock(&array->rwlock);
            return -1; // Memory allocation failed
        }

        memset(new_array + array->capacity, 0, (new_capacity - array->capacity) * sizeof(TX_CELL_CONTEXT_T *));
