} TX_CELL_CONTEXT_T;

typedef struct {
    TX_CELL_CONTEXT_T *cellContexts;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Initialize the dynamic array
void initDynamicArray(DynamicArray *arr) {
    arr->capacity = INITIAL_CAPACITY;
    arr->count = 0;
    arr->cellContexts = malloc(arr->capacity * sizeof(TX_CELL_CONTEXT_T));
    pthread_mutex_init(&arr->lock, NULL);
}

// Resize the dynamic array when needed
void resizeDynamicArray(DynamicArray *arr) {
    size_t newCapacity = arr->capacity * 2;
    TX_CELL_CONTEXT_T *newContexts = realloc(arr->cellContexts, newCapacity * sizeof(TX_CELL_CONTEXT_T));
    if (newContexts) {
        arr->cellContexts = newContexts;
        arr->capacity = newCapacity;
    } else {
        fprintf(stderr, "Failed to resize dynamic array.\n");
    }
}

// Validate RX_UE_INFORMATION_TAG and RNTI
int validateTagAndRnti(uint16_t rxUeTag, uint16_t rnti) {
    return (rxUeTag <= MAX_RX_UE_TAG && rnti <= MAX_RNTI);
}

// Add a new NFAPI_CRC_INDICATION_PDU_T structure
void addCrcIndication(DynamicArray *arr, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&arr->lock);

    if (validateTagAndRnti(pdu->RX_UE_INFORMATION_TAG, pdu->RNTI)) {
        if (arr->count == arr->capacity) {
            resizeDynamicArray(arr);
        }

        // Populate TX_CELL_CONTEXT_T structure
        TX_CELL_CONTEXT_T context;
        // Assume phyParams and cellId are initialized properly here

        // Add the context to the array
        arr->cellContexts[arr->count++] = context;

    } else {
        fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG or RNTI: %u, %u\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI);
    }

    pthread_mutex_unlock(&arr->lock);
}

// Logging function
void logAllocationAttempt(size_t capacity) {
    printf("Attempting allocation with capacity: %zu\n", capacity);
}

// Get current allocation status
size_t getCurrentAllocatedCount(const DynamicArray *arr) {
    return arr->count;
}

size_t getAvailableSlots(const DynamicArray *arr) {
    return arr->capacity - arr->count;
}

// Cleanup resources
void freeDynamicArray(DynamicArray *arr) {
    pthread_mutex_destroy(&arr->lock);
    free(arr->cellContexts);
}
