} LogEntry;

typedef struct LogSystem {
    pthread_mutex_t lock;
    LogEntry **entries;
    size_t capacity;
    size_t count;
    size_t retention_size; // Configurable retention policy
    // External system dependencies would be declared here.
} LogSystem;

LogSystem* initialize_log_system(size_t initial_capacity, size_t retention_size) {
    LogSystem *system = malloc(sizeof(LogSystem));
    pthread_mutex_init(&system->lock, NULL);
    system->capacity = initial_capacity;
    system->retention_size = retention_size;
    system->count = 0;
    system->entries = malloc(initial_capacity * sizeof(LogEntry*));

    return system;
}

void log_request(LogSystem *system, const char *request_id, const char *http_method, const char *url,
                 int status_code, const char *json_payload) {
    pthread_mutex_lock(&system->lock);

    // Resize if necessary
    if (system->count == system->capacity) {
        system->capacity *= 2;
        LogEntry **new_entries = realloc(system->entries, system->capacity * sizeof(LogEntry*));
        if (!new_entries) {
            fprintf(stderr, "Failed to resize log entries.\n");
            pthread_mutex_unlock(&system->lock);
            return;
        }
        system->entries = new_entries;
    }

    LogEntry *entry = malloc(sizeof(LogEntry));
    entry->request_id = strdup(request_id);
    time(&entry->timestamp);
    strncpy(entry->http_method, http_method, sizeof(entry->http_method) - 1);
    strncpy(entry->url, url, sizeof(entry->url) - 1);
    entry->status_code = status_code;

    json_object *payload = json_tokener_parse(json_payload);
    if (!payload) {
        fprintf(stderr, "Invalid JSON payload.\n");
        free(entry->request_id);
        free(entry);
        pthread_mutex_unlock(&system->lock);
        return;
    }
    entry->payload = payload;

    system->entries[system->count++] = entry;

    // Prune old entries based on retention policy
    if (system->count > system->retention_size) {
        LogEntry *oldest_entry = system->entries[0];
        free(oldest_entry->request_id);
        json_object_put(oldest_entry->payload);  // Free JSON object
        free(oldest_entry);

        memmove(system->entries, &system->entries[1], (system->count - 1) * sizeof(LogEntry*));
        system->count--;
    }

    pthread_mutex_unlock(&system->lock);
}

// Mockup of a non-blocking export mechanism to an external analytics platform.
void start_log_export_thread(void (*export_func)(LogSystem*)) {
    // Launch a separate thread for log export
    pthread_t export_thread;
    if (pthread_create(&export_thread, NULL, (void *(*)(void *))export_func, NULL) != 0) {
        fprintf(stderr, "Failed to create log export thread.\n");
    }
}

// Mock function that would handle exporting logs.
void* export_logs_to_analytics(void *arg) {
    LogSystem *system = (LogSystem*) arg;

    while (1) { // A simplified loop for continuous operation
        pthread_mutex_lock(&system->lock);

        // Process and send logs in batches to minimize I/O
        if (system->count > 0) {
            // Export logic here, e.g., serialize batch of logs
            // Handle network interruptions gracefully
        }

        pthread_mutex_unlock(&system->lock);

        // Sleep for a short duration before next export cycle
        usleep(100000);  // 100 milliseconds
    }

    return NULL;
}

void shutdown_log_system(LogSystem *system) {
    if (system) {
        pthread_mutex_lock(&system->lock);

        // Free all entries
        for (size_t i = 0; i < system->count; ++i) {
            free(system->entries[i]->request_id);
            json_object_put(system->entries[i]->payload);  // Free JSON object
            free(system->entries[i]);
        }

        free(system->entries);
        pthread_mutex_unlock(&system->lock);

        pthread_mutex_destroy(&system->lock);
        free(system);
    }
}

