#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct {
    unsigned int RNTI;
    unsigned char CRCFLAG; // Assume it's a byte for simplicity
} NFAPI_CRC_INDICATION_REL8_TAG;

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
} UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    UE_INFORMATION_TAG ue_info_tag;
    unsigned int RNTI;
    NFAPI_CRC_INDICATION_REL8_TAG crc_info_rel8;
    time_t timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    pthread_mutex_t lock;
    unsigned int purge_threshold_seconds;
} CRC_Indication_List;

// Function prototypes
void list_init(CRC_Indication_List *list);
int add_entry(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T *entry);
void remove_entry(CRC_Indication_List *list, unsigned int RNTI);
NFAPI_CRC_INDICATION_PDU_T* find_entry(CRC_Indication_List *list, unsigned int RNTI);
int purge_old_entries(CRC_Indication_List *list);
void clear_list(CRC_Indication_List *list);
char* export_to_json(const CRC_Indication_List *list);
char* export_to_csv(const CRC_Indication_List *list);

// List initialization
void list_init(CRC_Indication_List *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    list->purge_threshold_seconds = 3600; // Default to one hour
}

// Add an entry safely with RNTI check and timestamping
int add_entry(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->lock);

    if (find_entry(list, entry->RNTI)) {
        fprintf(stderr, "Duplicate RNTI: %u\n", entry->RNTI);
        pthread_mutex_unlock(&list->lock);
        return -1; // Duplicate RNTI
    }

    entry->timestamp = time(NULL);

    if (!list->head) {
        list->head = list->tail = entry;
    } else {
        list->tail->next = entry;
        entry->prev = list->tail;
        list->tail = entry;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Remove an entry by RNTI
void remove_entry(CRC_Indication_List *list, unsigned int RNTI) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *entry = find_entry(list, RNTI);
    if (entry) {
        if (entry->prev) entry->prev->next = entry->next;
        if (entry->next) entry->next->prev = entry->prev;

        if (list->head == entry) list->head = entry->next;
        if (list->tail == entry) list->tail = entry->prev;

        free(entry);
    }

    pthread_mutex_unlock(&list->lock);
}

// Find an entry by RNTI
NFAPI_CRC_INDICATION_PDU_T* find_entry(CRC_Indication_List *list, unsigned int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        if (current->RNTI == RNTI) return current;
        current = current->next;
    }
    return NULL;
}

// Purge entries older than the threshold
int purge_old_entries(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->lock);

    time_t now = time(NULL);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head, *tmp;

    while (current) {
        if ((now - current->timestamp) > list->purge_threshold_seconds) {
            tmp = current;
            current = current->next;

            remove_entry(list, tmp->RNTI);
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Clear the list
void clear_list(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head, *tmp;

    while (current) {
        tmp = current;
        current = current->next;
        free(tmp);
    }

    list->head = list->tail = NULL;

    pthread_mutex_unlock(&list->lock);
}

// Export the list to JSON
char* export_to_json(const CRC_Indication_List *list) {
    // Implementation details for exporting to JSON using a dynamic string buffer
    char *json_str = malloc(4096); // Example size, adjust as necessary

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    strcpy(json_str, "[");
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (current) {
        if (current != list->head) strcat(json_str, ", ");
        sprintf(json_str + strlen(json_str), "{\"RNTI\":%u,\"CRCFLAG\":%u,\"timestamp\":%ld}", 
                current->RNTI, current->crc_info_rel8.CRCFLAG, current->timestamp);

        current = current->next;
    }

    strcat(json_str, "]");
    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);

    return json_str;
}

// Export the list to CSV
char* export_to_csv(const CRC_Indication_List *list) {
    // Implementation details for exporting to CSV using a dynamic string buffer
    char *csv_str = malloc(4096); // Example size, adjust as necessary

    pthread_mutex_lock((pthread_mutex_t*)&list->lock);

    strcpy(csv_str, "RNTI,CRCFLAG,Timestamp\n");
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;

    while (current) {
        sprintf(csv_str + strlen(csv_str), "%u,%u,%ld\n", 
                current->RNTI, current->crc_info_rel8.CRCFLAG, current->timestamp);

        current = current->next;
    }

    pthread_mutex_unlock((pthread_mutex_t*)&list->lock);

    return csv_str;
}
