#define LOCK_FREE_STRATEGY 2

typedef struct {
    unsigned int RNTI;
    char RX_UE_INFORMATION_TAG[64];
} CRC_INDICATION_REL8_TAG;

typedef struct {
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    unsigned char CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    pthread_rwlock_t lock;
    size_t capacity;
} CRC_Indication_List;

void init_crc_indication_list(CRC_Indication_List *list, size_t initial_capacity) {
    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = initial_capacity;
    pthread_rwlock_init(&list->lock, NULL);
}

void free_crc_indication_list(CRC_Indication_List *list) {
    if (list->elements) {
        free(list->elements);
        list->elements = NULL;
    }
    pthread_rwlock_destroy(&list->lock);
}

int resize_crc_indication_list(CRC_Indication_List *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) {
        return -1; // Memory allocation failed
    }
    list->elements = new_elements;
    list->capacity = new_capacity;
    return 0;
}

int add_crc_indication_pdu(CRC_Indication_List *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_rwlock_wrlock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        if (new_capacity > MAX_ELEMENTS) {
            pthread_rwlock_unlock(&list->lock);
            return -1; // Reached maximum capacity
        }
        if (resize_crc_indication_list(list, new_capacity)) {
            pthread_rwlock_unlock(&list->lock);
            return -1; // Failed to resize
        }
    }

    list->elements[list->count++] = pdu;
    pthread_rwlock_unlock(&list->lock);
    return 0;
}

void serialize_to_file(CRC_Indication_List *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    pthread_rwlock_rdlock(&list->lock);
    fwrite(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), list->count, file);
    pthread_rwlock_unlock(&list->lock);

    fclose(file);
}

void deserialize_from_file(CRC_Indication_List *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    size_t element_count;
    fseek(file, 0, SEEK_END);
    element_count = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    rewind(file);

    pthread_rwlock_wrlock(&list->lock);
    if (resize_crc_indication_list(list, element_count)) {
        fclose(file);
        return; // Failed to resize
    }

    fread(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T), element_count, file);
    list->count = element_count;
    pthread_rwlock_unlock(&list->lock);

    fclose(file);
}

void create_and_initialize_structures(CRC_Indication_List *list, size_t n) {
    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        snprintf(pdu.crc_indication_rel8_tag.RX_UE_INFORMATION_TAG, sizeof(pdu.crc_indication_rel8_tag.RX_UE_INFORMATION_TAG), "UE_%zu", i);
        pdu.crc_indication_rel8_tag.RNTI = rand() % 0xFFFFF; // Example RNTI
        pdu.CRCFLAG = rand() & 1; // Randomly set CRCFLAG

        if (add_crc_indication_pdu(list, pdu) != 0) {
            fprintf(stderr, "Failed to add structure at index %zu\n", i);
            break;
        }
    }

    printf("Successfully created %zu structures.\n", list->count);
}

void monitor_usage(CRC_Indication_List *list) {
    pthread_rwlock_rdlock(&list->lock);
    size_t active_elements = list->count;
    size_t memory_usage = sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity;
    pthread_rwlock_unlock(&list->lock);

    printf("Active elements: %zu, Memory usage: %zu bytes\n", active_elements, memory_usage);
}

int main() {
    CRC_Indication_List list;
    init_crc_indication_list(&list, 1000); // Initial capacity

    create_and_initialize_structures(&list, MAX_ELEMENTS);

    serialize_to_file(&list, "crc_data.bin");
    deserialize_from_file(&list, "crc_data.bin");

    monitor_usage(&list);

    free_crc_indication_list(&list);
    return 0;
}
