    if (max_count == 0) {
        fprintf(stderr, "Max count cannot be zero.\n");
        return -1;
    }

    pthread_mutex_init(&manager->lock, NULL);
    manager->data_array = malloc(max_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->data_array) {
        perror("Failed to allocate memory for data array");
        pthread_mutex_destroy(&manager->lock);
        return -1;
    }

    manager->count = 0;
    manager->max_count = max_count;
    manager->max_CRCFLAG = INT_MIN;
    manager->min_CRCFLAG = INT_MAX;

    srand(time(NULL)); // Seed the random number generator

    return 0; // Success
}

// Finalize the CRC manager, freeing resources
void finalize_crc_manager(CRCManager *manager) {
    free(manager->data_array);
    pthread_mutex_destroy(&manager->lock);
}

// Update RX_UE_INFORMATION_TAG and RNTI for all elements in a thread-safe manner
int update_crc_values(CRCManager *manager, unsigned int new_RX_UE_INFORMATION_TAG, unsigned int new_RNTI) {
    if (!manager) {
        fprintf(stderr, "CRC manager is NULL.\n");
        return -1;
    }

    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        manager->data_array[i].RX_UE_INFORMATION_TAG = new_RX_UE_INFORMATION_TAG;
        manager->data_array[i].RNTI = new_RNTI;

        int crc_flag = generate_random_CRCFLAG();
        manager->data_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crc_flag;

        if (crc_flag > manager->max_CRCFLAG) {
            manager->max_CRCFLAG = crc_flag;
        }
        if (crc_flag < manager->min_CRCFLAG) {
            manager->min_CRCFLAG = crc_flag;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

// Example usage
