#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_TABLE_SIZE 16

typedef struct Record {
    int key;
    int value;
    char *string;
    struct Record *next;
    struct Record *prev;
} Record;

typedef struct HashNode {
    Record *record;
    struct HashNode *next;
} HashNode;

typedef struct HashTable {
    HashNode **buckets;
    size_t size;
    size_t count;
} HashTable;

HashTable* createHashTable() {
    HashTable *table = malloc(sizeof(HashTable));
    table->size = INITIAL_TABLE_SIZE;
    table->count = 0;
    table->buckets = calloc(table->size, sizeof(HashNode *));
    return table;
}

unsigned int hashFunction(int key, size_t tableSize) {
    return (unsigned int)(key % tableSize);
}

void resizeHashTable(HashTable *table);

Record* createRecord(int key, int value, const char *str) {
    Record *record = malloc(sizeof(Record));
    if (!record) return NULL;

    record->key = key;
    record->value = value;

    size_t length = strlen(str);
    record->string = malloc(length + 1);
    if (!record->string) {
        free(record);
        return NULL;
    }
    strcpy(record->string, str);

    record->next = NULL;
    record->prev = NULL;

    return record;
}

void insertRecord(HashTable *table, Record *record) {
    unsigned int index = hashFunction(record->key, table->size);
    HashNode *node = malloc(sizeof(HashNode));
    if (!node) {
        free(record->string);
        free(record);
        return;
    }

    node->record = record;
    node->next = table->buckets[index];
    if (table->buckets[index]) {
        table->buckets[index]->prev = node;
    }
    table->buckets[index] = node;
    table->count++;

    if ((float)table->count / table->size > 0.75) {
        resizeHashTable(table);
    }
}

void freeRecord(Record *record) {
    if (record) {
        free(record->string);
        free(record);
    }
}

void freeHashTable(HashTable *table) {
    for (size_t i = 0; i < table->size; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            HashNode *next = node->next;
            freeRecord(node->record);
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

void resizeHashTable(HashTable *table) {
    size_t newSize = table->size * 2;
    HashNode **newBuckets = calloc(newSize, sizeof(HashNode *));
    if (!newBuckets) return;

    for (size_t i = 0; i < table->size; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            unsigned int newIndex = hashFunction(node->record->key, newSize);
            HashNode *next = node->next;

            node->next = newBuckets[newIndex];
            if (newBuckets[newIndex]) {
                newBuckets[newIndex]->prev = node;
            }
            newBuckets[newIndex] = node;

            node = next;
        }
    }

    free(table->buckets);
    table->buckets = newBuckets;
    table->size = newSize;
}

Record* generateRandomString() {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    size_t stringSize = rand() % 100 + 1;
    char *str = malloc(stringSize + 1);
    if (!str) return NULL;

    for (size_t i = 0; i < stringSize; ++i) {
        str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    str[stringSize] = '\0';

    return createRecord(rand(), rand(), str);
}

void initializeRecords(HashTable *table, int numRecords) {
    srand(time(NULL));
    for (int i = 0; i < numRecords; ++i) {
        Record *record = generateRandomString();
        if (!record) break;
        insertRecord(table, record);
    }
}

// Function to iterate over records in the hash table
void traverseHashTable(HashTable *table, void (*func)(Record*)) {
    for (size_t i = 0; i < table->size; ++i) {
        HashNode *node = table->buckets[i];
        while (node) {
            func(node->record);
            node = node->next;
        }
    }
}

// Example function to demonstrate iteration
void printRecord(Record *record) {
    if (record) {
        printf("Key: %d, Value: %d, String: %s\n", record->key, record->value, record->string);
    }
}

int main() {
    HashTable *table = createHashTable();
    initializeRecords(table, 50);

    traverseHashTable(table, printRecord);

    freeHashTable(table);
    return 0;
}
