SystemState* initialize_system_state(size_t N) {
    SystemState *state = (SystemState *)malloc(sizeof(SystemState));
    if (!state) return NULL;

    pthread_mutex_init(&state->mutex, NULL);

    state->nfaCount = state->srsCount = state->phyTxFrameCount = N;
    state->complexNumbers = (complex double *)malloc(MAX_COMPLEX_NUMBERS * sizeof(complex double));

    // Allocate memory for structures
    state->nfaPduArray = (NFAPI_CRC_INDICATION_PDU_T *)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    state->srsPduArray = (LTE_ENB_SRS_PDU_T *)calloc(N, sizeof(LTE_ENB_SRS_PDU_T));
    state->phyTxFrameArray = (LTE_PHY_TX_FRAME_T *)malloc(N * sizeof(LTE_PHY_TX_FRAME_T));

    if (!state->nfaPduArray || !state->srsPduArray || !state->phyTxFrameArray || !state->complexNumbers) {
        destroy_system_state(state);
        return NULL;
    }

