void read_and_process_complex_numbers(SystemState *state) {
    size_t count = 0;
    while (scanf("%lf%lf", &creal(state->complexNumbers[count]), &cimag(state->complexNumbers[count])) == 2 && count < MAX_COMPLEX_NUMBERS) {
        count++;
    }

    if (count > 0) {
        float min_magnitude = find_smallest_magnitude_complex(state->complexNumbers, count);
        printf("Smallest magnitude: %f\n", min_magnitude);
    }
}

float find_smallest_magnitude_complex(complex double *numbers, size_t count) {
    float min_magnitude = cabs(numbers[0]);
    for (size_t i = 1; i < count; ++i) {
        float magnitude = cabs(numbers[i]);
        if (magnitude < min_magnitude) {
            min_magnitude = magnitude;
        }
    }
    return min_magnitude;
}

void generate_pdu_structures(SystemState *state, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        state->nfaPduArray[i].RX_UE_INFORMATION_TAG = rand();
