        state->nfaPduArray[i].CRC_INDICATION_REL8_TAG.CRCFLAG = crcFlag;
        if (crcFlag < state->minCRCFLAG) state->minCRCFLAG = crcFlag;
        if (crcFlag > state->maxCRCFLAG) state->maxCRCFLAG = crcFlag;
        pthread_mutex_unlock(&state->mutex);

        state->srsPduArray[i].SRS_MEASUREMENT_TAG = rand();
        state->srsPduArray[i].RNTI = rand() % 65535;
        state->srsPduArray[i].SRS_SUBFRAME_INFO_TAG.SRS_FLAG = rand() % 2;
    }
}

void populate_phy_tx_frame_structures(SystemState *state) {
    for (size_t i = 0; i < state->phyTxFrameCount; ++i) {
        state->phyTxFrameArray[i].RF_TX_FRAME_TAG = rand();

        for (int j = 0; j < 10; ++j) { // Assuming 10 symbols per frame
            state->phyTxFrameArray[i].RF_TX_SYMBOL_TAG[j].quality_metric = ((float)rand() / RAND_MAX) * 100.0f;
        }
    }
}

// Example usage:
int main() {
