    SystemState *state = initialize_system_state(N);

    if (state) {
        read_and_process_complex_numbers(state);

        printf("Min CRCFLAG: %d, Max CRCFLAG: %d\n", state->minCRCFLAG, state->maxCRCFLAG);
        destroy_system_state(state);
    } else {
        fprintf(stderr, "Failed to initialize system state.\n");
    }

    return 0;
}
