#define MAX_RNTI 0xFFFFFFFF // Example upper bound for valid RNTI values

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG; // Randomly set
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t used;
    size_t capacity;
} DynamicArray;

void initArray(DynamicArray *a, size_t initialCapacity) {
    a->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    a->used = 0;
    a->capacity = initialCapacity;
}

bool addElement(DynamicArray *a, NFAPI_CRC_INDICATION_PDU_T element) {
    if (element.RNTI == 0 || element.RNTI > MAX_RNTI) return false; // Validate RNTI
    if (a->used >= a->capacity) { 
        size_t newCapacity = a->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *tempArray = realloc(a->array, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!tempArray) return false; // Handle reallocation failure
        a->array = tempArray;
        a->capacity = newCapacity;
    }
    a->array[a->used++] = element;
    return true;
}

int compareByRNTI(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *elemA = (NFAPI_CRC_INDICATION_PDU_T *)a;
    NFAPI_CRC_INDICATION_PDU_T *elemB = (NFAPI_CRC_INDICATION_PDU_T *)b;
    return (elemA->RNTI - elemB->RNTI);
}

void sortArray(DynamicArray *a) {
    qsort(a->array, a->used, sizeof(NFAPI_CRC_INDICATION_PDU_T), compareByRNTI);
}

bool serializeArrayToFile(const DynamicArray *a, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return false;

    // Error handling with logging
    if (fwrite(&a->used, sizeof(size_t), 1, file) != 1 || 
        fwrite(a->array, sizeof(NFAPI_CRC_INDICATION_PDU_T), a->used, file) != a->used) {
        perror("Error writing to file");
        fclose(file);
        return false;
    }

    fclose(file);
    return true;
}

void freeArray(DynamicArray *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->capacity = 0;
}

// Example usage
int main() {
    DynamicArray array;
    initArray(&array, 10);

    // Simulate adding elements with random CRCFLAG
