#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    int value;
    struct Record* prev;
    struct Record* next;
} Record;

typedef struct DoublyLinkedList {
    Record* head;
    Record* tail;
    pthread_mutex_t lock;
    size_t length;
    const int minValue;
    const int maxValue;
} DoublyLinkedList;

DoublyLinkedList* init_list(int minVal, int maxVal) {
    DoublyLinkedList* list = malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->length = 0;
    list->minValue = minVal;
    list->maxValue = maxVal;

    return list;
}

int add_record(DoublyLinkedList* list, long offset, int key) {
    if (!list) return -1;

    pthread_mutex_lock(&list->lock);

    Record* newRecord = malloc(sizeof(Record));
    if (!newRecord) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    newRecord->offset = offset;
    newRecord->key = key;
    newRecord->value = rand() % (list->maxValue - list->minValue + 1) + list->minValue;
    newRecord->prev = NULL;
    newRecord->next = NULL;

    if (!list->head) {
        list->head = newRecord;
        list->tail = newRecord;
    } else {
        list->tail->next = newRecord;
        newRecord->prev = list->tail;
        list->tail = newRecord;
    }

    list->length++;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void cleanup_records(DoublyLinkedList* list, long retentionPeriod) {
    if (!list) return;

    time_t now = time(NULL);
    pthread_mutex_lock(&list->lock);

    Record *current = list->head, *temp;

    while (current) {
        temp = current;
        current = current->next;

        // Assuming offset is a timestamp for simplicity
        if ((now - temp->offset) > retentionPeriod) {
            if (temp->prev) temp->prev->next = temp->next;
            else list->head = temp->next;

            if (temp->next) temp->next->prev = temp->prev;
            else list->tail = temp->prev;

            free(temp);
            list->length--;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void monitor_usage(DoublyLinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    printf("Current memory usage: %zu bytes\n", sizeof(Record) * list->length);
    // Additional monitoring logic can be added here

    pthread_mutex_unlock(&list->lock);
}

void destroy_list(DoublyLinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Record* current = list->head;
    while (current) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    srand(time(NULL));

    DoublyLinkedList* list = init_list(0, 100);
    if (!list) return -1;

    for (long i = 0; i < 10; ++i) {
        add_record(list, time(NULL), i);
    }

    cleanup_records(list, 3600); // Example retention period
    monitor_usage(list);

    destroy_list(list);
    return 0;
}
```

This code initializes a doubly-linked list with thread-safe operations and includes functions for adding records, cleaning up old records based on a retention policy, monitoring memory usage, and destroying the list. It uses mutexes to ensure thread safety during concurrent access.']

