typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set CRC flag, needs validation
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ARRAY_SIZE 1000
#define CACHE_SIZE 10

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array[MAX_ARRAY_SIZE];
    size_t count;
    pthread_mutex_t lock;
} DynamicArray;

// Simulated external data source function
int fetch_data_from_source(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Simulate fetching logic and potential delays/interruptions
    srand(time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand() % 100; // Example tag
    pdu->RNTI = (rand() % 65535) + 1;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 50; // Example CRC tag
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

    // Simulate data source availability with a random chance of failure
    return (rand() % 10) > 1;
}

// Validate RNTI and CRCFLAG
int validate_pdu(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu->RNTI == 0 || pdu->RX_UE_INFORMATION_TAG <= 0) return 0; // Invalid RNTI or tag
    return 1;
}

// Cache mechanism for CRCFLAG validation results
typedef struct {
    int crcFlags[CACHE_SIZE];
    size_t count;
} CRCFlagCache;

int cache_crcflag(CRCFlagCache *cache, int crcflag) {
    if (cache->count < CACHE_SIZE) {
        cache->crcFlags[cache->count++] = crcflag;
        return 1;
    }
    // Simple LRU eviction policy
    memmove(cache->crcFlags, cache->crcFlags + 1, sizeof(int) * (CACHE_SIZE - 1));
    cache->crcFlags[CACHE_SIZE - 1] = crcflag;
    return 0; // Eviction occurred
}

int get_cached_crcflag(CRCFlagCache *cache, int crcflag) {
    for (size_t i = 0; i < cache->count; ++i) {
        if (cache->crcFlags[i] == crcflag) return 1;
    }
    return 0;
}

// Add an element to the dynamic array
int add_element(DynamicArray *dynArray, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&dynArray->lock);

    if (dynArray->count >= MAX_ARRAY_SIZE) {
        fprintf(stderr, "Error: Array is full\n");
        pthread_mutex_unlock(&dynArray->lock);
        return -1;
    }

    // Validate PDU
    if (!validate_pdu(pdu)) {
        fprintf(stderr, "Error: Invalid PDU\n");
        pthread_mutex_unlock(&dynArray->lock);
        return -1;
    }

    dynArray->array[dynArray->count] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynArray->array[dynArray->count]) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        pthread_mutex_unlock(&dynArray->lock);
        return -1;
    }
    memcpy(dynArray->array[dynArray->count], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dynArray->count++;

    pthread_mutex_unlock(&dynArray->lock);
    return 0;
}

// Sort the array based on RNTI
void sort_array(DynamicArray *dynArray) {
    pthread_mutex_lock(&dynArray->lock);

    // Simple insertion sort for demonstration (can be replaced with a more efficient algorithm)
    for (size_t i = 1; i < dynArray->count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *temp = dynArray->array[i];
        size_t j = i;
        while (j > 0 && dynArray->array[j - 1]->RNTI > temp->RNTI) {
            dynArray->array[j] = dynArray->array[j - 1];
            --j;
        }
        dynArray->array[j] = temp;
    }

    pthread_mutex_unlock(&dynArray->lock);
}

// Serialize the dynamic array to a file
int serialize_array(DynamicArray *dynArray, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1;

    size_t count = dynArray->count;
    fwrite(&count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < count; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = dynArray->array[i];
        if (!fwrite(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
            fprintf(stderr, "Error: Serialization failed\n");
            fclose(file);
            return -1;
        }
    }

    fclose(file);
    return 0;
}

// Initialize dynamic array
void init_dynamic_array(DynamicArray *dynArray) {
    dynArray->count = 0;
    pthread_mutex_init(&dynArray->lock, NULL);
}

// Free resources of the dynamic array
void free_dynamic_array(DynamicArray *dynArray) {
    for (size_t i = 0; i < dynArray->count; ++i) {
        free(dynArray->array[i]);
    }
    pthread_mutex_destroy(&dynArray->lock);
}

int main() {
    DynamicArray dynArray;
    init_dynamic_array(&dynArray);

    NFAPI_CRC_INDICATION_PDU_T pdu;

    while (fetch_data_from_source(&pdu)) {
        if (!get_cached_crcflag(NULL, pdu.CRCFLAG)) { // Assume cache is initialized
            if (add_element(&dynArray, &pdu) == 0) {
                printf("Added PDU with RNTI: %u\n", pdu.RNTI);
            }
        } else {
            printf("Cached CRCFLAG for current PDU.\n");
        }
    }

    sort_array(&dynArray);

    if (serialize_array(&dynArray, "array_data.bin") != 0) {
        fprintf(stderr, "Serialization failed\n");
    }

    free_dynamic_array(&dynArray);
    return 0;
}
