} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    int identifier;
    float metric;
} CachedData;

int store_to_distributed_system(const NFAPI_CRC_INDICATION_PDU_T *data, int id, float metric) {
    // Simulate storing to a distributed system with retries
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (rand() % 10 > 2) { // Simulating random success/failure
            return 0; // Success
        }
        printf("Retry %d for storing data id %d...\n", attempt + 1, id);
    }
    return -1; // Failure after retries
}

float get_metric_from_data_source() {
    // Simulate retrieving metric from a data source with possible delays or failures
    if (rand() % 10 < 2) { // Simulating random failure
        return -1;
    }
    return rand() / (float)RAND_MAX * 100; // Return a random float value as metric
}

void* process_and_store(void* arg) {
    CachedData* cached_data = (CachedData*)arg;

    if (cached_data->metric < 0) { // Retry fetching data source in case of failure
        cached_data->metric = get_metric_from_data_source();
        if (cached_data->metric < 0) {
            free(cached_data);
            return NULL;
        }
    }

    if (store_to_distributed_system(&cached_data->data, cached_data->identifier, cached_data->metric) != 0) {
        printf("Failed to store data id %d after retries.\n", cached_data->identifier);
        free(cached_data);
        return NULL;
    }

    free(cached_data);
    pthread_exit(NULL);
}

void populate_and_store_crc_indications(int N, int (*data_source)(int, int)) {
    if (N <= 0) return; // Handle invalid input

    srand(time(NULL)); // Seed random number generator

    pthread_t threads[N];

    for (int i = 0; i < N; ++i) {
        CachedData* cached_data = malloc(sizeof(CachedData));
        if (!cached_data) {
            perror("Failed to allocate memory");
            return;
        }

        // Initialize the data
        cached_data->data.RX_UE_INFORMATION_TAG = rand() % 1000; // Assign a random RX_UE_INFORMATION_TAG
        cached_data->data.RNTI = i + 1; // Example RNTI, could be based on input parameters
        cached_data->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1; // Randomly set CRCFLAG

        cached_data->identifier = i;

        cached_data->metric = get_metric_from_data_source();

        if (pthread_create(&threads[i], NULL, process_and_store, cached_data) != 0) {
            perror("Failed to create thread");
            free(cached_data);
        }
    }

    for (int i = 0; i < N; ++i) {
        pthread_join(threads[i], NULL);
    }
}
