#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1024
#define CONFIG_FILE "config.txt"
#define TIMEOUT_THRESHOLD 300 // seconds

typedef struct {
    time_t timestamps[10];
    int count;
} PacketTimestamps;

typedef struct {
    int connection_id;
    char state[20];
    time_t last_active_time;
    PacketTimestamps recent_packets;
} TCP_STATE_T;

typedef struct Node {
    TCP_STATE_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} ConnectionPool;

ConnectionPool pool = {NULL, PTHREAD_MUTEX_INITIALIZER};

int load_config(const char* filename, ConnectionPool* pool);
void cleanup_inactive_connections(ConnectionPool* pool);
int add_connection(ConnectionPool* pool, TCP_STATE_T* new_conn);
TCP_STATE_T* get_most_recently_active(ConnectionPool* pool);

int initialize_pool() {
    if (load_config(CONFIG_FILE, &pool) != 0) {
        return -1;
    }
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, (void*)cleanup_inactive_connections, (void*)&pool);
    pthread_detach(cleanup_thread);
    return 0;
}

int load_config(const char* filename, ConnectionPool* pool) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    char line[256];
    int connection_id;
    char state[20];
    time_t last_active_time;

    pthread_mutex_lock(&pool->lock);
    while (fgets(line, sizeof(line), file)) {
        if (sscanf(line, "%d %s %ld", &connection_id, state, &last_active_time) != 3) continue;

        Node* current = pool->head;
        int exists = 0;
        while (current) {
            if (current->data.connection_id == connection_id) {
                exists = 1;
                break;
            }
            current = current->next;
        }

        if (!exists) {
            TCP_STATE_T new_conn = {connection_id, "", last_active_time, {{0}, 0}};
            strcpy(new_conn.state, state);
            add_connection(pool, &new_conn);
        }
    }
    pthread_mutex_unlock(&pool->lock);

    fclose(file);
    return 0;
}

void cleanup_inactive_connections(ConnectionPool* pool) {
    while (1) {
        sleep(60); // run every minute
        time_t current_time = time(NULL);

        Node* prev = NULL;
        Node* current = pool->head;

        pthread_mutex_lock(&pool->lock);
        while (current) {
            if ((current_time - current->data.last_active_time) > TIMEOUT_THRESHOLD) {
                if (prev) {
                    prev->next = current->next;
                } else {
                    pool->head = current->next;
                }
                Node* to_delete = current;
                current = current->next;
                free(to_delete);
            } else {
                prev = current;
                current = current->next;
            }
        }
        pthread_mutex_unlock(&pool->lock);
    }
}

int add_connection(ConnectionPool* pool, TCP_STATE_T* new_conn) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return -1;

    node->data = *new_conn;
    node->next = NULL;

    pthread_mutex_lock(&pool->lock);
    node->next = pool->head;
    pool->head = node;
    pthread_mutex_unlock(&pool->lock);

    return 0;
}

TCP_STATE_T* get_most_recently_active(ConnectionPool* pool) {
    TCP_STATE_T* most_recent = NULL;

    pthread_mutex_lock(&pool->lock);
    Node* current = pool->head;
    time_t max_time = 0;

    while (current) {
        if (current->data.last_active_time > max_time) {
            max_time = current->data.last_active_time;
            most_recent = &current->data;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&pool->lock);

    return most_recent;
}
