    size_t element_count;
    bool has_backup;
} data_block;

void init_random() {
    srand((unsigned)time(NULL));
}

int generate_random(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record* allocate_records(size_t count, int range_min, int range_max) {
    record *records = malloc(count * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].value = generate_random(range_min, range_max);
    }

    return records;
}

node* create_node(double num_val, const char *text, int type) {
    node *new_node = malloc(sizeof(node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for node.\n");
        exit(EXIT_FAILURE);
    }

    new_node->number_value = num_val;
    strncpy(new_node->text, text, sizeof(new_node->text) - 1);
    new_node->text[sizeof(new_node->text) - 1] = '\0';
    new_node->type = type;
    new_node->active = true;

    return new_node;
}

data_block* allocate_data_blocks(size_t block_count, size_t node_count_per_block) {
    data_block *blocks = malloc(block_count * sizeof(data_block));
    if (!blocks) {
        fprintf(stderr, "Memory allocation failed for data blocks.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < block_count; ++i) {
        node **nodes = calloc(node_count_per_block, sizeof(node *));
        if (!nodes) {
            fprintf(stderr, "Memory allocation failed for nodes in block %zu.\n", i);
            exit(EXIT_FAILURE);
        }

        blocks[i].nodes = nodes;
        blocks[i].element_count = 0; // Initially empty
        blocks[i].has_backup = false;

        // Simulating node creation (in a real-world scenario, you would fill this with actual logic)
        for (size_t j = 0; j < node_count_per_block; ++j) {
            if ((double)rand() / RAND_MAX > 0.5) {  // Randomly decide on type
                nodes[j] = create_node((double)generate_random(1, 100), "Sample text", 1);
            } else {
                nodes[j] = create_node((double)generate_random(1, 100), "", 0);
            }
        }

        blocks[i].element_count = node_count_per_block;
    }

    return blocks;
}

void free_records(record *records, size_t count) {
    free(records);
}

void free_data_blocks(data_block *blocks, size_t block_count) {
    for (size_t i = 0; i < block_count; ++i) {
        if (!blocks[i].has_backup) { // Only free nodes if no backup is present
            for (size_t j = 0; j < blocks[i].element_count; ++j) {
                free(blocks[i].nodes[j]);
            }
        }
        free(blocks[i].nodes);
    }
    free(blocks);
}

