#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <time.h>

#define MAX_IP_LENGTH 16
#define TIMESTAMP_RANGE_START 0
#define TIMESTAMP_RANGE_END (60 * 60) // Example: One hour range

typedef enum {
    PROTOCOL_TCP,
    PROTOCOL_UDP
} ProtocolType;

typedef struct {
    char ip[MAX_IP_LENGTH];
    ProtocolType protocol;
    time_t timestamp;
} NetworkPacket;

// Hash map for fast duplicate detection
#define HASH_MAP_SIZE 1024

typedef struct HashNode {
    char ip[MAX_IP_LENGTH];
    ProtocolType protocol;
    struct HashNode* next;
} HashNode;

HashNode* hash_map[HASH_MAP_SIZE];
pthread_mutex_t hash_map_locks[HASH_MAP_SIZE];

unsigned int hash_function(char* ip, ProtocolType protocol) {
    unsigned int hash = 0;
    for (int i = 0; ip[i] != '\0'; i++) {
        hash = (hash * 31 + ip[i]) % HASH_MAP_SIZE;
    }
    return hash ^ protocol;
}

void init_hash_map() {
    for (int i = 0; i < HASH_MAP_SIZE; i++) {
        hash_map[i] = NULL;
        pthread_mutex_init(&hash_map_locks[i], NULL);
    }
}

void free_hash_map() {
    for (int i = 0; i < HASH_MAP_SIZE; i++) {
        HashNode* node = hash_map[i];
        while (node) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
        pthread_mutex_destroy(&hash_map_locks[i]);
    }
}

int is_valid_ip(char* ip) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ip, &(sa.sin_addr)) != 0;
}

int parse_log_file(const char* filename, NetworkPacket** packets, size_t* count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    init_hash_map();
    pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    int status = 0;
    char log_issues[1024] = {0};

    char line[256];
    NetworkPacket* packet_list = NULL;
    size_t packet_count = 0;

    while (fgets(line, sizeof(line), file)) {
        NetworkPacket packet = {0};
        if (sscanf(line, "%15[^ ] %d %ld", packet.ip, &packet.protocol, &packet.timestamp) != 3) {
            strcat(log_issues, "Malformed entry: ");
            strcat(log_issues, line);
            continue;
        }

        if (!is_valid_ip(packet.ip)) {
            strcat(log_issues, "Invalid IP address: ");
            strcat(log_issues, packet.ip);
            strcat(log_issues, "\n");
            continue;
        }

        if (packet.timestamp < TIMESTAMP_RANGE_START || packet.timestamp > TIMESTAMP_RANGE_END) {
            char issue[256];
            snprintf(issue, sizeof(issue), "Timestamp out of range for %s\n", packet.ip);
            strcat(log_issues, issue);
            continue;
        }

        unsigned int hash_index = hash_function(packet.ip, packet.protocol);
        pthread_mutex_lock(&hash_map_locks[hash_index]);

        HashNode* node = hash_map[hash_index];
        while (node) {
            if (strcmp(node->ip, packet.ip) == 0 && node->protocol == packet.protocol) {
                pthread_mutex_unlock(&hash_map_locks[hash_index]);
                break;
            }
            node = node->next;
        }

        if (!node) {
            HashNode* new_node = malloc(sizeof(HashNode));
            strcpy(new_node->ip, packet.ip);
            new_node->protocol = packet.protocol;
            new_node->next = hash_map[hash_index];
            hash_map[hash_index] = new_node;

            pthread_mutex_lock(&log_lock);
            *packet_count += 1;
            packet_list = realloc(packet_list, sizeof(NetworkPacket) * (*packet_count));
            memcpy(&packet_list[*packet_count - 1], &packet, sizeof(NetworkPacket));
            pthread_mutex_unlock(&log_lock);

        } else {
            status = 0; // Duplicate found
        }

        pthread_mutex_unlock(&hash_map_locks[hash_index]);
    }

    fclose(file);
    free_hash_map();

    *packets = packet_list;
    *count = packet_count;

    if (status == 0) {
        printf("Log Issues:\n%s\n", log_issues);
    }

    return status;
}

int main() {
    NetworkPacket* packets = NULL;
    size_t count = 0;
    int result = parse_log_file("network.log", &packets, &count);

    if (result == 0) {
        printf("Packets parsed successfully. Count: %zu\n", count);
    } else {
        printf("Failed to parse packets.\n");
    }

    free(packets);
    return 0;
}
