#include <pthread.h>
#include <string.h>

// Define the TCP_CONNECTION structure.
typedef struct {
    int socket_id;
    char *connection_data; // Placeholder for actual connection data
} TCP_CONNECTION;

// Node in the hash table
typedef struct ConnectionNode {
    TCP_CONNECTION tcp_connection;
    struct ConnectionNode* next;
} ConnectionNode;

#define TABLE_SIZE 1024

// Hash Table to manage connections
typedef struct {
    ConnectionNode** buckets;
    pthread_mutex_t *locks;
} ConnectionHashTable;

ConnectionHashTable* create_connection_table() {
    ConnectionHashTable* table = malloc(sizeof(ConnectionHashTable));
    table->buckets = calloc(TABLE_SIZE, sizeof(ConnectionNode*));
    table->locks = malloc(TABLE_SIZE * sizeof(pthread_mutex_t));

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_init(&table->locks[i], NULL);
    }
    return table;
}

unsigned int hash(int socket_id) {
    return socket_id % TABLE_SIZE;
}

void add_connection(ConnectionHashTable* table, TCP_CONNECTION connection) {
    unsigned int index = hash(connection.socket_id);
    pthread_mutex_lock(&table->locks[index]);

    ConnectionNode* new_node = malloc(sizeof(ConnectionNode));
    new_node->tcp_connection = connection;
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    pthread_mutex_unlock(&table->locks[index]);
}

TCP_CONNECTION* get_connection(ConnectionHashTable* table, int socket_id) {
    unsigned int index = hash(socket_id);
    pthread_mutex_lock(&table->locks[index]);

    ConnectionNode* node = table->buckets[index];
    while (node != NULL) {
        if (node->tcp_connection.socket_id == socket_id) {
            TCP_CONNECTION* conn = malloc(sizeof(TCP_CONNECTION));
            *conn = node->tcp_connection;
            pthread_mutex_unlock(&table->locks[index]);
            return conn; // Caller should free this
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
    return NULL; // Not found
}

void update_connection(ConnectionHashTable* table, TCP_CONNECTION connection) {
    unsigned int index = hash(connection.socket_id);
    pthread_mutex_lock(&table->locks[index]);

    ConnectionNode* node = table->buckets[index];
    while (node != NULL) {
        if (node->tcp_connection.socket_id == connection.socket_id) {
            memcpy(&(node->tcp_connection), &connection, sizeof(TCP_CONNECTION));
            break;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->locks[index]);
}

void cleanup_connection_table(ConnectionHashTable* table) {
    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_lock(&table->locks[i]);

        ConnectionNode* node = table->buckets[i];
        while (node != NULL) {
            ConnectionNode* temp = node;
            node = node->next;
            free(temp);
        }

        pthread_mutex_unlock(&table->locks[i]);
    }

    for (int i = 0; i < TABLE_SIZE; ++i) {
        pthread_mutex_destroy(&table->locks[i]);
    }
    free(table->buckets);
    free(table->locks);
    free(table);
}

// Example usage
int main() {
    ConnectionHashTable* table = create_connection_table();

    TCP_CONNECTION conn1 = { .socket_id = 101, .connection_data = "Data for socket 101" };
    add_connection(table, conn1);

    TCP_CONNECTION* retrieved_conn = get_connection(table, 101);
    if (retrieved_conn != NULL) {
        printf("Retrieved: %s\n", retrieved_conn->connection_data);
        free(retrieved_conn);
    }

    cleanup_connection_table(table);
    return 0;
}
