void initialize_and_populate_ccch_messages(LTE_DL_CCCH_Message_Type1_T** message_array,
                                           size_t* array_size, int max_capacity) {
    if (*array_size > max_capacity || *array_size == 0) {
        log_error("Invalid array size.");
        return;
    }

    LTE_DL_CCCH_Message_Type1_T* new_message_array = (LTE_DL_CCCH_Message_Type1_T*)malloc(*array_size * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!new_message_array) {
        log_error("Memory allocation failed. Falling back to reduced capacity.");
        *array_size = MIN_CAPACITY;
        new_message_array = (LTE_DL_CCCH_Message_Type1_T*)malloc(*array_size * sizeof(LTE_DL_CCCH_Message_Type1_T));
        if (!new_message_array) {
            log_error("Reduced memory allocation also failed.");
            return;
        }
    }

    for (size_t i = 0; i < *array_size; ++i) {
        pthread_mutex_lock(&array_lock);

        if (!fetch_message_type()) { // Handle potential data source failure
            log_error("Failed to fetch message type.");
            pthread_mutex_unlock(&array_lock);
            continue;
        }

        new_message_array[i].message.type = rand() % 256;  // Randomly generate message type
        populate_message_content(&new_message_array[i].message);

        if (!new_message_array[i].encoder.init()) {  // Hypothetical encoder initialization function
            log_error("Failed to initialize TLVEncoder.");
            pthread_mutex_unlock(&array_lock);
            continue;
        }

        pthread_mutex_unlock(&array_lock);

        pthread_mutex_lock(&stats_counter.lock);
        stats_counter.success_count++;
        pthread_mutex_unlock(&stats_counter.lock);
    }

    if (*message_array) {
        free(*message_array);
    }
    *message_array = new_message_array;
}

int query_success_count() {
    int count;
    pthread_mutex_lock(&stats_counter.lock);
    count = stats_counter.success_count;
    pthread_mutex_unlock(&stats_counter.lock);
    return count;
}

int query_failure_count() {
    int count;
    pthread_mutex_lock(&stats_counter.lock);
    count = stats_counter.failure_count;
    pthread_mutex_unlock(&stats_counter.lock);
    return count;
}
