['Below is a C code implementation that addresses the described requirements. This code leverages standard libraries for MD5 hashing, uses Redis as an in-memory key-value store, implements rate limiting with token bucket algorithm, utilizes multi-threading for concurrency, and incorporates logging mechanisms. The code also includes placeholder structures and functions for NFAPI_CRC_INDICATION_PDU_T creation and CRC flag setting.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/md5.h>
#include <time.h>
#include <unistd.h>
#include <hiredis/hiredis.h>
#include <errno.h>

#define MAX_INPUT_LENGTH 1024
#define NUM_THREADS 8
#define RATE_LIMIT_BUCKET_SIZE 1000

typedef struct {
    unsigned char rx_ue_information_tag[16];
    int rnti;
    unsigned char crc_indication_rel8_tag[16];
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables for Redis and rate limiting
redisContext *redis_ctx = NULL;
unsigned long long token_bucket = RATE_LIMIT_BUCKET_SIZE;
pthread_mutex_t bucket_lock = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void* process_input_strings(void* arg);
void md5_hash(const char* input, unsigned char* output);
void store_in_cache(const char* key, const unsigned char* hash_value);
void log_metrics(const char* metric_name, double value);
NFAPI_CRC_INDICATION_PDU_T create_nfa_pdu(int rnti, float crc_prob_dist);

// Rate limiting token refill function
void refill_tokens() {
    while (1) {
        sleep(1); // Refill every second
        pthread_mutex_lock(&bucket_lock);
        if (token_bucket < RATE_LIMIT_BUCKET_SIZE) {
            token_bucket++;
        }
        pthread_mutex_unlock(&bucket_lock);
    }
}

// Main processing function
int main(int argc, char* argv[]) {
    pthread_t threads[NUM_THREADS];
    pthread_t rate_limiter_thread;

    // Initialize Redis connection
    redis_ctx = redisConnect("127.0.0.1", 6379);
    if (redis_ctx->err) {
        fprintf(stderr, "Redis connection error: %s\n", redis_ctx->errstr);
        return EXIT_FAILURE;
    }

    // Start rate limiter thread
    pthread_create(&rate_limiter_thread, NULL, (void*)refill_tokens, NULL);

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, process_input_strings, NULL);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    redisFree(redis_ctx);
    return EXIT_SUCCESS;
}

void* process_input_strings(void* arg) {
    char input[MAX_INPUT_LENGTH];
    unsigned char hash[MD5_DIGEST_LENGTH];
    while (fgets(input, sizeof(input), stdin)) {
        // Trim newline character
        size_t len = strlen(input);
        if (len > 0 && input[len - 1] == '\n') {
            input[--len] = '\0';
        }

        pthread_mutex_lock(&bucket_lock);
        if (token_bucket > 0) {
            token_bucket--;
            pthread_mutex_unlock(&bucket_lock);

            md5_hash(input, hash);
            store_in_cache(input, hash);

            NFAPI_CRC_INDICATION_PDU_T pdu = create_nfa_pdu(rand() % 10000, 0.5); // Example RNTI and probability

        } else {
            pthread_mutex_unlock(&bucket_lock);
            usleep(100000); // Wait for tokens to refill
        }
    }
    return NULL;
}

void md5_hash(const char* input, unsigned char* output) {
    MD5((unsigned char*)input, strlen(input), output);
}

void store_in_cache(const char* key, const unsigned char* hash_value) {
    redisReply *reply = (redisReply *)redisCommand(redis_ctx, "SET %s %b", key, hash_value, MD5_DIGEST_LENGTH);
    if (reply->type == REDIS_REPLY_ERROR) {
        fprintf(stderr, "Redis SET error: %s\n", reply->str);
    }
    freeReplyObject(reply);
}

NFAPI_CRC_INDICATION_PDU_T create_nfa_pdu(int rnti, float crc_prob_dist) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    memset(&pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Simulate generating RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG
    rand_r(&rnti); // Seed with rnti for demonstration purposes
    for (int i = 0; i < sizeof(pdu.rx_ue_information_tag); i++) {
        pdu.rx_ue_information_tag[i] = rand() % 256;
    }

    float random_value = ((float)rand()) / RAND_MAX;
    int crc_flag = (random_value < crc_prob_dist);
    for (int i = 0; i < sizeof(pdu.crc_indication_rel8_tag); i++) {
        pdu.crc_indication_rel8_tag[i] = (crc_flag ? 1 : 0) * rand() % 256;
    }

    pdu.rnti = rnti;
    return pdu;
}

void log_metrics(const char* metric_name, double value) {
    // Implement logging mechanism here
    printf("Metric: %s, Value: %.2f\n", metric_name, value);
}
```

### Key Points:
- **Concurrency**: The code uses pthreads to handle multiple input strings concurrently.
- **Rate Limiting**: A token bucket algorithm is implemented for rate limiting, with a separate thread managing the refill of tokens.
- **MD5 Hashing**: Utilizes OpenSSL's MD5 functions for hashing.
- **Redis Integration**: Stores hashes in Redis for distributed caching.
- **NFAPI_CRC_INDICATION_PDU_T Structure**: Simulates creation and population based on probabilistic CRC flag setting.
- **Logging**: Placeholder function to log metrics, which can be expanded with a proper logging library.

This code is designed to handle high loads efficiently while maintaining scalability and resilience. Adjustments may be needed for specific environments or additional features.']

