record* allocate_and_populate_records(int N, const char *hostname) {
    if (N <= 0) return NULL; // Handle invalid input

    // Allocate memory for the records array
    record *records = malloc(N * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    // Allocate memory for IP address storage (IPv4 and IPv6)
    u_char ip_storage[16];

    memset(records, 0, N * sizeof(record)); // Initialize allocated memory

    // Populate each record
    for (int i = 0; i < N; ++i) {
        records[i].offset = 42L;          // Predetermined offset value
        records[i].key = 7;               // Predetermined key value
        records[i].value = rand() % 100;  // Random value between 0 and 99
    }

    // DNS resolution with retry logic
    int retries = 3;
    struct addrinfo hints, *res = NULL;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;

    while (retries-- > 0) {
        if (getaddrinfo(hostname, NULL, &hints, &res) == 0) {
            break; // Success
        }
        sleep(1); // Wait before retrying
    }

    if (!res) {
        perror("Failed to resolve hostname");
        free(records);
        return NULL;
    }

    // Copy the resolved IP address into ip_storage
