['```c
#include <stdio.h>
#include <stdlib.h>
import time

typedef struct {
    int RNTI;
    int CRCFLAG;  // Random flag for CRC indication
} CRC_INDICATION_REL8_TAG;

typedef struct {
    int priorityLevel;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} RX_UE_INFORMATION_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    int rnti;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom random number generator
int custom_random() {
    static unsigned long int seed = time(NULL);
    seed ^= (seed << 21);
    seed ^= (seed >> 35);
    seed ^= (seed << 4);
    return (seed & 0x7FFFFFFF);
}

// Function to create a new node
NFAPI_CRC_INDICATION_PDU_T* create_node(int rnti, int pdu_tag) {
    NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    node->rxUeInformationTag.priorityLevel = custom_random() % 10; // Assign random priority
    node->rxUeInformationTag.crcIndicationRel8Tag.CRCFLAG = (custom_random() % 2 == 0);
    node->rnti = rnti;
    node->next = NULL;
    node->prev = NULL;

    return node;
}

// Function to insert a node based on priority
void insert_node(NFAPI_CRC_INDICATION_PDU_T **head, NFAPI_CRC_INDICATION_PDU_T *newNode) {
    if (!*head || newNode->rxUeInformationTag.priorityLevel < (*head)->rxUeInformationTag.priorityLevel) {
        newNode->next = *head;
        if (*head) (*head)->prev = newNode;
        *head = newNode;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = *head;
        while (current->next && current->next->rxUeInformationTag.priorityLevel <= newNode->rxUeInformationTag.priorityLevel) {
            current = current->next;
        }
        newNode->next = current->next;
        if (current->next) current->next->prev = newNode;
        current->next = newNode;
        newNode->prev = current;
    }
}

// Function to free the list
void free_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *temp;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

// Function to check for cycles using Floyd's Tortoise and Hare algorithm
int has_cycle(NFAPI_CRC_INDICATION_PDU_T *head) {
    if (!head || !head->next) return 0;

    NFAPI_CRC_INDICATION_PDU_T *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return 1; // Cycle detected
    }
    return 0;
}

// Main function to create and manage the doubly-linked list
NFAPI_CRC_INDICATION_PDU_T* create_nfa_crc_indication_list(int N, int M) {
    if (M <= 0 || M > N) {
        fprintf(stderr, "Invalid value for M\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    for (int i = 1; i <= N && M > 0; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *newNode = create_node(i, -1); // pdu_tag not used here
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            free_list(head);
            return NULL;
        }

        insert_node(&head, newNode);
        M--;
    }

    if (has_cycle(head)) {
        fprintf(stderr, "Cycle detected in the list\n");
        free_list(head);
        return NULL;
    }

    return head;
}

// Example usage
int main() {
    int N = 10; // Total possible RNTIs
    int M = 5;  // Number of elements to add

    NFAPI_CRC_INDICATION_PDU_T *list = create_nfa_crc_indication_list(N, M);

    if (list) {
        NFAPI_CRC_INDICATION_PDU_T *current = list;
        while (current) {
            printf("RNTI: %d, Priority: %d\n", current->rnti, current->rxUeInformationTag.priorityLevel);
            current = current->next;
        }

        free_list(list);
    }

    return 0;
}
```

This code implements a doubly-linked list of `NFAPI_CRC_INDICATION_PDU_T` structures with the specified features and constraints. It includes error handling, priority-based insertion, cycle detection, and memory management.']

