typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
} NFAPI_CRC_INDICATION_PDU_T;

bool is_unique(uint32_t rnti, uint32_t *rntis, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (rntis[i] == rnti) {
            return false;
        }
    }
    return true;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(size_t n, size_t *out_count) {
    if (n > MAX_NFPI || out_count == NULL) {
        fprintf(stderr, "Invalid input: number of elements exceeds maximum or null output count.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    uint32_t rntis[n];
    size_t unique_count = 0;

    for (size_t i = 0; i < n; ++i) {
        // Generate random RNTI
        uint32_t rnti = rand() % 0xFFFFF + 1;

        if (!is_unique(rnti, rntis, unique_count)) {
            fprintf(stderr, "Duplicate RNTI detected: %u\n", rnti);
            continue;
        }

        // Populate the structures
        list[unique_count].rx_ue_info.RNTI = rnti;

        list[unique_count].rx_ue_info.crc_tag = (CRC_INDICATION_REL8_TAG *)malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!list[unique_count].rx_ue_info.crc_tag) {
            fprintf(stderr, "Memory allocation failed for CRC tag.\n");
            --i; // Attempt to retry with this index
            continue;
        }

        list[unique_count].rx_ue_info.crc_tag->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        rntis[unique_count] = rnti;
        unique_count++;
    }

    *out_count = unique_count;

    return list;
}

void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T *list, size_t count) {
    if (!list) return;

    for (size_t i = 0; i < count; ++i) {
        if (list[i].rx_ue_info.crc_tag) {
            free(list[i].rx_ue_info.crc_tag);
        }
    }

    free(list);
}

int main() {
    size_t n_elements = 10000;
    size_t unique_count;

    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_crc_indication_pdu_list(n_elements, &unique_count);

    if (pdu_list) {
        printf("Created %zu unique NFAPI_CRC_INDICATION_PDU_T structures.\n", unique_count);
        free_crc_indication_pdu_list(pdu_list, unique_count);
    }

    return 0;
}
```

### Key Points:
- **Memory Management**: The function uses dynamic memory allocation and ensures all allocated memory is freed properly to prevent leaks.
- **Error Handling**: Checks for null pointers and out-of-bounds access are included. Memory allocation failures are handled gracefully with error messages.
- **Unique RNTI Check**: Uses a helper function `is_unique` to ensure no duplicate RNTIs are added to the list, logging duplicates as required.
- **Efficiency Considerations**: The algorithm is designed to handle up to 10,000 elements efficiently. It avoids unnecessary allocations when duplicates are detected.']

