    printf("Failed to resolve: %s\n", hostname);
}

char* get_cached_ip(const char *hostname) {
    for (int i = 0; i < cache_count; ++i) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            return dns_cache[i].resolved_ip;
        }
    }
    return NULL;
}

void add_to_cache(const char *hostname, const char *ip) {
    if (cache_count < CACHE_SIZE) {
        strncpy(dns_cache[cache_count].hostname, hostname, sizeof(dns_cache[cache_count].hostname));
        strncpy(dns_cache[cache_count].resolved_ip, ip, sizeof(dns_cache[cache_count].resolved_ip));
        cache_count++;
    }
}

void rate_limit_dns_lookups() {
    static int lookups_this_second = 0;
    static time_t last_reset_time;

    if (time(NULL) != last_reset_time) {
        lookups_this_second = 0;
        last_reset_time = time(NULL);
    }

    while (lookups_this_second >= MAX_DNS_LOOKUPS_PER_SECOND) {
        usleep(100000); // Sleep for 100ms
        if (time(NULL) != last_reset_time) {
            lookups_this_second = 0;
            last_reset_time = time(NULL);
        }
    }
    lookups_this_second++;
}

char* resolve_hostname_to_ip(const char *hostname) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    rate_limit_dns_lookups();

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        log_failed_resolution(hostname);
        return NULL;
    }

    char *ip_address = NULL;
    for (p = res; p != NULL; p = p->ai_next) {
        ip_address = inet_ntoa(((struct sockaddr_in *)p->ai_addr)->sin_addr);
        if (ip_address) break;
    }
    freeaddrinfo(res);

    return ip_address;
}

TCP_CONNECTION* initialize_tcp_connections(const char *hostnames[], int num_hosts, TCP_CONNECTION **array_size) {
    *array_size = malloc(num_hosts * sizeof(TCP_CONNECTION));

    for (int i = 0; i < num_hosts; ++i) {
        char *client_ip = get_cached_ip(hostnames[i]);
        if (!client_ip) {
            client_ip = resolve_hostname_to_ip(hostnames[i]);
            if (client_ip) {
                add_to_cache(hostnames[i], client_ip);
            }
        }

        TCP_CONNECTION conn;
        strcpy(conn.client_ip, client_ip ? client_ip : "0.0.0.0");
        strcpy(conn.server_ip, "192.168.1.1"); // Example server IP
        conn.connection_status = (client_ip != NULL) ? 1 : 0;

        (*array_size)[i] = conn;
    }

    return *array_size;
}
