    sprintf(new_name, "nfa_crc_log_%ld.txt", (long)current_time);
    rename("nfa_crc_log.txt", new_name);

    log_file = fopen("nfa_crc_log.txt", "a");
}

void log_message(const char* message) {
    static size_t current_size = 0;

    pthread_mutex_lock(&mutex); // Ensure thread-safe file access

    if (current_size >= LOG_FILE_SIZE) {
        rotate_log_file();
        current_size = 0;
    }

    fprintf(log_file, "%s\n", message);
    fflush(log_file);

    current_size += strlen(message) + 1; // +1 for newline

    pthread_mutex_unlock(&mutex); // Release mutex
}

bool create_structure(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* new_struct = NULL;

    pthread_mutex_lock(&mutex);

    if (available_count > 0) {
        for (int i = 0; i < MAX_STRUCTURES; ++i) {
            if (!pool[i]) {
                new_struct = pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

                // Initialize the structure
                new_struct->ID = rand(); // Example ID generation
                new_struct->crc_tag.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
                new_struct->crc_tag.RNTI = RNTI;
                new_struct->crc_tag.CRCFLAG = rand() % 2 == 0;

                --available_count;

                log_message("Structure created successfully");

                pthread_cond_signal(&cond_var); // Signal other threads waiting for a structure
                pthread_mutex_unlock(&mutex);
                return true;
            }
        }
    }

    log_message("Failed to create structure: pool full");

    pthread_mutex_unlock(&mutex);

    return false;
}

void release_structure(NFAPI_CRC_INDICATION_PDU_T* struct_ptr) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < MAX_STRUCTURES; ++i) {
        if (pool[i] == struct_ptr) {
            free(pool[i]);
            pool[i] = NULL;

            ++available_count;

            log_message("Structure released");

            pthread_cond_signal(&cond_var); // Signal other threads waiting for a structure
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}

