    fprintf(stderr, "Warning: %s\n", message);
}

CRCIndicationManager* init_crc_indication_manager(size_t initial_capacity) {
    CRCIndicationManager* manager = (CRCIndicationManager*)malloc(sizeof(CRCIndiationManager));
    if (!manager) {
        log_error("Failed to allocate memory for CRCIndicationManager");
        return NULL;
    }

    manager->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        log_error("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T array");
