    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->array[i].RNTI == rnti) {
            log_error("Duplicate RNTI detected");
            return -1;
        }
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_STRUCTURES) {
            log_warning("Memory limit reached, cannot add more structures");
            return -1;
        }

        NFAPI_CRC_INDICATION_PDU_T* temp_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_array) {
            log_error("Failed to reallocate memory for NFAPI_CRC_INDICATION_PDU_T array");
            return -1;
        }
        manager->array = temp_array;
        manager->capacity = new_capacity;
    }

    int index = manager->count++;
    manager->array[index].RX_UE_INFORMATION_TAG = ue_id;
    manager->array[index].RNTI = rnti;

    srand((unsigned int)time(NULL) + index);
    manager->array[index].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

    return 0;
}

void free_crc_indication_manager(CRCIndicationManager* manager) {
    if (manager) {
        if (manager->array) {
            free(manager->array);
        }
        free(manager);
    }
}

