['```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
import "time.h"  // Assuming this is a way to get time information

#define MAX_THREADS 10
#define QUEUE_SIZE 50

typedef struct {
    int task_id;
    int priority_level;
    void (*task_handler)(void*);
    void* data;
} Task;

typedef struct Node {
    Task task;
    struct Node* next;
} Node;

typedef struct {
    Node* front;
    Node* rear;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
    int count;
} TaskQueue;

TaskQueue queue = {NULL, NULL, PTHREAD_MUTEX_INITIALIZER, PTHREAD_COND_INITIALIZER, PTHREAD_COND_INITIALIZER, 0};

typedef struct {
    pthread_t thread_id;
    int active;
} WorkerThread;

WorkerThread workers[MAX_THREADS];
int running_threads = 0;

void log_task(const Task* task, const char* status) {
    time_t now = time(NULL);
    printf("Task ID: %d | Time: %s | Priority: %d | Status: %s\n", 
           task->task_id, ctime(&now), task->priority_level, status);
}

void enqueue_task(TaskQueue* queue, Task task) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;

    pthread_mutex_lock(&queue->lock);

    while (queue->count == QUEUE_SIZE) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }

    new_node->task = task;
    new_node->next = NULL;
    if (queue->rear == NULL) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
    queue->count++;

    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);

    log_task(&task, "Enqueued");
}

Task dequeue_task(TaskQueue* queue) {
    pthread_mutex_lock(&queue->lock);

    while (queue->count == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }

    Node* temp = queue->front;
    Task task = temp->task;

    queue->front = queue->front->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);

    queue->count--;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);

    log_task(&task, "Dequeued");

    return task;
}

void* worker_function(void* arg) {
    while (1) {
        Task task = dequeue_task(&queue);

        // Limit the number of active tasks
        if (!task.task_handler || running_threads >= MAX_THREADS) continue;

        running_threads++;
        task.task_handler(task.data);
        running_threads--;

        log_task(&task, "Completed");
    }
    return NULL;
}

void init_workers() {
    for (int i = 0; i < MAX_THREADS; i++) {
        workers[i].active = 1;
        pthread_create(&workers[i].thread_id, NULL, worker_function, NULL);
    }
}

void shutdown_workers() {
    for (int i = 0; i < MAX_THREADS; i++) {
        if (workers[i].active) {
            pthread_cancel(workers[i].thread_id);
            workers[i].active = 0;
        }
    }
}

// Example task handler function
void example_task_handler(void* data) {
    // Process the task data here
}

int main() {
    init_workers();

    Task tasks[] = {
        {1, 10, example_task_handler, NULL},
        {2, 5, example_task_handler, NULL},
        {3, 8, example_task_handler, NULL}
    };

    for (int i = 0; i < sizeof(tasks)/sizeof(tasks[0]); i++) {
        enqueue_task(&queue, tasks[i]);
    }

    // To shutdown gracefully
    shutdown_workers();

    return 0;
}
```']

