    if (session_manager.log_file == NULL || ftell(session_manager.log_file) >= MAX_LOG_SIZE) {
        fclose(session_manager.log_file);
        session_manager.log_file = fopen("session_log.txt", "a");
    }
    if (session_manager.log_file != NULL) {
        fprintf(session_manager.log_file, "%s\n", message);
        fflush(session_manager.log_file);
    }
    pthread_mutex_unlock(&session_manager.mutex);
}

void* manage_sessions(void* arg) {
    while (1) {
        int new_max = get_dynamic_max_structures();
        pthread_mutex_lock(&session_manager.mutex);
        session_manager.max_structures = new_max;
        if (session_manager.count < session_manager.capacity && session_manager.count < session_manager.max_structures) {
            NFAPI_CRC_INDICATION_PDU_T* structure = &session_manager.structures[session_manager.count++];
            structure->RX_UE_INFORMATION_TAG = rand();
            structure->RNTI = rand();
            structure->CRC_INDICATION_REL8_TAG = rand() % 256;
            structure->CRCFLAG = rand() % 2;
            log_message("Structure created successfully.");
        } else if (session_manager.count >= session_manager.capacity) {
            size_t new_capacity = session_manager.capacity * 2;
            NFAPI_CRC_INDICATION_PDU_T* new_structures = realloc(session_manager.structures, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (new_structures != NULL) {
                session_manager.structures = new_structures;
                session_manager.capacity = new_capacity;
                log_message("Increased capacity.");
            } else {
                log_message("Failed to increase capacity.");
            }
        }
        pthread_mutex_unlock(&session_manager.mutex);
        sleep(POLL_INTERVAL);
    }
}

void initialize_session_manager() {
    session_manager.structures = malloc(10 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (session_manager.structures == NULL) {
        log_message("Failed to allocate initial structures.");
    } else {
        session_manager.capacity = 10;
        session_manager.count = 0;
        session_manager.log_file = fopen("session_log.txt", "w");
        pthread_t manager_thread;
        pthread_create(&manager_thread, NULL, manage_sessions, NULL);
        pthread_detach(manager_thread);
    }
}

void cleanup_session_manager() {
    if (session_manager.structures != NULL) {
        free(session_manager.structures);
    }
    if (session_manager.log_file != NULL) {
        fclose(session_manager.log_file);
    }
}

int main() {
    srand(time(NULL));
    initialize_session_manager();

    // Simulate operation
    sleep(30); // Run for 30 seconds

    cleanup_session_manager();
    return 0;
}
