        array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_sessions * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        used_RNTIs = (uint16_t *)calloc(max_sessions, sizeof(uint16_t));

        if (!array || !used_RNTIs) {
