### JavaScript Module for Script Management

```javascript
class ScriptManager {
    constructor() {
        this.scriptQueue = [];
        this.isRunning = false;
        this.logs = [];
    }

    addScript(url, order) {
        this.scriptQueue.push({ url, order });
        this.scriptQueue.sort((a, b) => a.order - b.order);
        console.log(`Added script: ${url} at position ${order}`);
    }

    executeScripts() {
        if (this.isRunning) return;
        this.isRunning = true;

        const runNextScript = () => {
            if (this.scriptQueue.length === 0) {
                this.isRunning = false;
                console.log("All scripts executed.");
                return;
            }

            const scriptInfo = this.scriptQueue.shift();
            this.loadAndExecute(scriptInfo.url, error => {
                if (error) {
                    this.logs.push(`Error loading ${scriptInfo.url}: ${error}`);
                } else {
                    this.logs.push(`Successfully executed ${scriptInfo.url}`);
                }
                runNextScript(); // Proceed to the next script
            });
        };

        runNextScript();
    }

    loadAndExecute(url, callback) {
        const script = document.createElement('script');
        script.src = url;

        script.onload = () => callback(null);
        script.onerror = (errorEvent) => callback(errorEvent);

        document.head.appendChild(script);
    }

    getLogs() {
        return this.logs;
    }
}

// Usage
const scriptManager = new ScriptManager();
scriptManager.addScript("https://example.com/script1.js", 2);
scriptManager.addScript("https://example.com/script2.js", 1);
scriptManager.executeScripts();

setInterval(() => {
    console.log(scriptManager.getLogs());
}, 5000); // Log every 5 seconds for demonstration
```

