        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
}

void resize_list(DynamicList *list) {
    size_t new_capacity = list->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        perror("Failed to resize the dynamic list");
        exit(EXIT_FAILURE);
    }
    list->data = new_data;
    list->capacity = new_capacity;
}

void add_pdu(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        resize_list(list);
    }

    validate_rnti(pdu.rnti);
    pdu.crc_indication_rel8_tag.crc_indicator = calculate_checksum(&pdu);

    list->data[list->size++] = pdu;

    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->lock);
}

void *thread_function(void *arg) {
    DynamicList *list = (DynamicList *)arg;

    // Example: Add a new PDU
    NFAPI_CRC_INDICATION_PDU_T pdu = { .rnti = 1234 };
    add_pdu(list, pdu);

    return NULL;
}

int main() {
    DynamicList list;
    initialize_list(&list, INITIAL_LIST_SIZE);

    pthread_t threads[5];

    for (int i = 0; i < 5; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &list) != 0) {
            perror("Failed to create a thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(list.data);
