// Initialize and populate the array
LTE_DL_CCCH_Message_Type1_T* initAndPopulateArray(size_t *arraySize, size_t maxMemoryUsage) {
    if (*arraySize == 0) *arraySize = INITIAL_ARRAY_SIZE;

    LTE_DL_CCCH_Message_Type1_T *messages = NULL;
    int currentSize = *arraySize;

    // Allocate initial memory
    messages = (LTE_DL_CCCH_Message_Type1_T *)malloc(currentSize * sizeof(LTE_DL_CCCH_Message_Type1_T));
    if (!messages) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    while (currentSize * sizeof(LTE_DL_CCCH_Message_Type1_T) < maxMemoryUsage) {
        pthread_mutex_lock(&arrayMutex);

        for (size_t i = 0; i < currentSize; ++i) {
            messages[i].encoder.encoderContext = malloc(sizeof(void*)); // Placeholder
            if (!messages[i].encoder.encoderContext) {
                perror("Failed to allocate encoder context");
                pthread_mutex_unlock(&arrayMutex);
                return NULL;
            }

            messages[i].nasMessage.messageType = getRandomMessageType();
            generateRandomMessageContent(messages[i].nasMessage.messageContent, sizeof(messages[i].nasMessage.messageContent));

            if (!validateNASMessage(&messages[i].nasMessage)) {
                // Handle invalid message: free the partially initialized structure
                pthread_mutex_unlock(&arrayMutex);
                printf("Invalid NAS Message at index %zu. Freeing resources.\n", i);

                for (size_t j = 0; j <= i; ++j) {
                    free(messages[j].encoder.encoderContext);
                }
                free(messages);
                *arraySize = currentSize;
                return NULL;
            }

            // Encode message using TLVEncoder
        }

        pthread_mutex_unlock(&arrayMutex);

        monitorSystemResources();

        if (currentSize * sizeof(LTE_DL_CCCH_Message_Type1_T) >= maxMemoryUsage) {
            break;
        }

        // Grow the array
        currentSize += GROWTH_INCREMENT;
        LTE_DL_CCCH_Message_Type1_T* newMessages = realloc(messages, currentSize * sizeof(LTE_DL_CCCH_Message_Type1_T));
        if (!newMessages) {
            perror("Failed to reallocate memory");
            free(messages);
            pthread_mutex_unlock(&arrayMutex);
            return NULL;
        }
        messages = newMessages;
    }

    *arraySize = currentSize;
    return messages;
}

// Clean-up function
void cleanup(LTE_DL_CCCH_Message_Type1_T* messages, size_t arraySize) {
    for (size_t i = 0; i < arraySize; ++i) {
        free(messages[i].encoder.encoderContext);
    }
    free(messages);
}
