#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a custom structure for LTE measurement reports.
typedef struct {
    int global_identifier;
    int measurement_identity;
    int signal_strength_indicator;
    time_t timestamp;
} MeasurementReport;

// Comparator function to sort by timestamp
int compare_timestamps(const void *a, const void *b) {
    MeasurementReport *reportA = (MeasurementReport *)a;
    MeasurementReport *reportB = (MeasurementReport *)b;
    return (reportA->timestamp > reportB->timestamp) - (reportA->timestamp < reportB->timestamp);
}

// Initialize and populate an array of measurement reports
int initialize_measurement_reports(MeasurementReport **reports, size_t count, int *data, size_t data_count) {
    if (!reports || !data || data_count % 4 != 0) return -1; // Basic validation

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Allocate memory for reports
    *reports = (MeasurementReport *)malloc(count * sizeof(MeasurementReport));
    if (*reports == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    size_t i, valid_count = 0;
    pthread_mutex_lock(&lock);

    // Populate the measurement reports
    for (i = 0; i < data_count && valid_count < count; i += 4) {
        if ((data[i] <= 0 || data[i+1] <= 0 || data[i+2] < -120 || data[i+2] > 30)) continue; // Validate data

        (*reports)[valid_count].global_identifier = data[i];
        (*reports)[valid_count].measurement_identity = data[i+1];
        (*reports)[valid_count].signal_strength_indicator = data[i+2];
        (*reports)[valid_count].timestamp = data[i+3];

        valid_count++;
    }

    pthread_mutex_unlock(&lock);

    // Sort the reports by timestamp
    qsort(*reports, valid_count, sizeof(MeasurementReport), compare_timestamps);

    pthread_mutex_destroy(&lock);

    return (int)valid_count; // Return number of valid entries
}

// Example usage with a main function for testing purposes
int main() {
    MeasurementReport *reports;
    int data[] = {1, 101, -50, time(NULL), 2, 102, -70, time(NULL)+100, 3, 103, -90, time(NULL)-200};
    size_t data_count = sizeof(data) / sizeof(data[0]);

    int valid_reports = initialize_measurement_reports(&reports, 10, data, data_count);

    if (valid_reports > 0) {
        for (int i = 0; i < valid_reports; ++i) {
            printf("ID: %d, Measure ID: %d, Signal Strength: %d, Timestamp: %ld\n",
                   reports[i].global_identifier,
                   reports[i].measurement_identity,
                   reports[i].signal_strength_indicator,
                   reports[i].timestamp);
        }
    }

    free(reports);

    return 0;
}
```

