    }

    while (active_threads > 0) {
        sleep(1); // Wait for all messages to be processed
    }

    db_disconnect();

    free(messages);
    free(crc_indications);
}

// Resize array dynamically as needed
void resize_array_if_needed(int current_size) {
    if (current_size >= message_count * 2 && current_size <= MAX_MESSAGES) {
