    if (manager->ImageArray != NULL) free(manager->ImageArray);

    manager->ImageArray = (Image*) calloc(num_images, sizeof(Image));
    if (!manager->ImageArray) {
        LOG_BASIC(manager, "Failed to allocate Image array.");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }

    for (size_t i = 0; i < num_images; ++i) {
        manager->ImageArray[i].width = rand() % 1920 + 640; // Random width between 640 and 2560
        manager->ImageArray[i].height = rand() % 1080 + 480; // Random height between 480 and 2160
        size_t pixel_size = manager->ImageArray[i].width * manager->ImageArray[i].height;

        manager->ImageArray[i].Pixel = (unsigned char*) malloc(pixel_size);
        if (!manager->ImageArray[i].Pixel) {
            LOG_BASIC(manager, "Failed to allocate Pixel data for image.");
            free_image_array(manager); // Cleanup on failure
            pthread_mutex_unlock(&manager->lock);
            return -1;
