#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RNTIS 10

typedef struct {
    int ue_id;
    int rntis[MAX_RNTIS];
    int num_rntis;
    int valid_cqi;
} UEContextInfo;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    void *data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    pthread_mutex_t lock;
} List;

// Function to create a new list
List* create_list() {
    List *list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to destroy the list and free memory
void destroy_list(List *list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to add data to the list
int add_to_list(List *list, void *data) {
    pthread_mutex_lock(&list->lock);

    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to find UEContextInfo by ue_id
UEContextInfo* find_ue_context(List *ue_list, int ue_id) {
    pthread_mutex_lock(&ue_list->lock);

    Node *current = ue_list->head;
    while (current != NULL) {
        UEContextInfo *context = (UEContextInfo*)current->data;
        if (context->ue_id == ue_id) {
            pthread_mutex_unlock(&ue_list->lock);
            return context;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&ue_list->lock);
    return NULL;
}

// Function to add or update UEContextInfo
int manage_ue_context(List *ue_list, int ue_id, int rntis[], int num_rntis, int valid_cqi) {
    pthread_mutex_lock(&ue_list->lock);

    UEContextInfo *context = find_ue_context(ue_list, ue_id);
    if (context) {
        memcpy(context->rntis, rntis, sizeof(int) * num_rntis);
        context->num_rntis = num_rntis;
        context->valid_cqi = valid_cqi;
    } else {
        context = (UEContextInfo*)malloc(sizeof(UEContextInfo));
        if (!context) {
            pthread_mutex_unlock(&ue_list->lock);
            return -1;
        }
        context->ue_id = ue_id;
        memcpy(context->rntis, rntis, sizeof(int) * num_rntis);
        context->num_rntis = num_rntis;
        context->valid_cqi = valid_cqi;
        add_to_list(ue_list, context);
    }

    pthread_mutex_unlock(&ue_list->lock);
    return 0;
}

