        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

// Initializes the linked list
LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        log_error("Failed to allocate memory for linked list");
        return NULL;
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    performance_monitor_start();
    return list;
}

// Appends or updates a node based on RNTI
void append_or_update_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T new_data) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node** current = &list->head;
    while (*current) {
        if ((*current)->data.RNTI == new_data.RNTI) {
            // Update existing node
            (*current)->data.CRC_INDICATION_REL8_TAG.CRCFLAG = new_data.CRC_INDICATION_REL8_TAG.CRCFLAG;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = &(*current)->next;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_error("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = new_data;
    new_node->next = NULL;
    *current = new_node;

    pthread_mutex_unlock(&list->lock);
}

// Retrieves a node based on RNTI
NFAPI_CRC_INDICATION_PDU_T* retrieve_node(LinkedList* list, uint16_t rnti) {
    if (!list) return NULL;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        if (current->data.RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return &current->data;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

// Clears the linked list
void clear_linked_list(LinkedList* list) {
    if (!list) return;

    pthread_mutex_lock(&list->lock);

    Node* current = list->head;
    while (current) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;

    pthread_mutex_unlock(&list->lock);
}

// Destroys the linked list
void destroy_linked_list(LinkedList* list) {
    if (!list) return;

    clear_linked_list(list);

    pthread_mutex_destroy(&list->lock);
    free(list);
    performance_monitor_stop();
}

