#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Forward declaration of the metrics structure.
typedef struct Measurement {
    double latency;
    double throughput;
    double packet_loss;
} Measurement;

typedef struct NetworkPerformanceMetric {
    time_t timestamp;
    int session_id;
    size_t num_measurements;
    Measurement *measurements;
    struct NetworkPerformanceMetric *next;
} NetworkPerformanceMetric;

// Linked list structure
typedef struct {
    NetworkPerformanceMetric *head;
    pthread_mutex_t lock;
    size_t size_threshold;
    time_t retention_time;
    void (*log_callback)(const char*);
} PerformanceMetricsList;

// Function to initialize the linked list
void init_performance_metrics_list(PerformanceMetricsList *list, 
                                   size_t size_threshold, 
                                   time_t retention_time, 
                                   void (*log_callback)(const char*)) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
    list->size_threshold = size_threshold;
    list->retention_time = retention_time;
    list->log_callback = log_callback;
}

// Function to insert a new metric
void insert_metric(PerformanceMetricsList *list,
                   int session_id,
                   size_t num_measurements,
                   Measurement measurements[]) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetric *new_metric = malloc(sizeof(NetworkPerformanceMetric));
    if (!new_metric) {
        perror("Failed to allocate memory");
        return;
    }

    new_metric->timestamp = time(NULL);
    new_metric->session_id = session_id;
    new_metric->num_measurements = num_measurements;
    new_metric->measurements = malloc(sizeof(Measurement) * num_measurements);
    if (!new_metric->measurements) {
        perror("Failed to allocate memory");
        free(new_metric);
        pthread_mutex_unlock(&list->lock);
        return;
    }

    for (size_t i = 0; i < num_measurements; ++i) {
        new_metric->measurements[i] = measurements[i];
    }

    new_metric->next = list->head;
    list->head = new_metric;

    if (list->log_callback) {
        char log_msg[256];
        sprintf(log_msg, "Inserted metric for session %d", session_id);
        list->log_callback(log_msg);
    }

    pthread_mutex_unlock(&list->lock);

    // Check size and potentially trigger cleanup
    pthread_mutex_lock(&list->lock);
    if (list_size(list) > list->size_threshold) {
        perform_cleanup(list);
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to calculate the current size of the linked list
size_t list_size(PerformanceMetricsList *list) {
    size_t size = 0;
    NetworkPerformanceMetric *current = list->head;

    while (current != NULL) {
        ++size;
        current = current->next;
    }

    return size;
}

// Function to perform cleanup based on retention policy
void perform_cleanup(PerformanceMetricsList *list) {
    time_t now = time(NULL);
    NetworkPerformanceMetric **ptr = &list->head;

    while (*ptr != NULL) {
        NetworkPerformanceMetric *entry = *ptr;

        if (now - entry->timestamp > list->retention_time) {
            *ptr = entry->next;  // Remove the metric

            free(entry->measurements);
            free(entry);

            if (list->log_callback) {
                char log_msg[256];
                sprintf(log_msg, "Cleaned up outdated metric for session %d", entry->session_id);
                list->log_callback(log_msg);
            }
        } else {
            ptr = &entry->next;
        }
    }
}

// Function to remove a specific metric
void delete_metric(PerformanceMetricsList *list, int session_id) {
    pthread_mutex_lock(&list->lock);

    NetworkPerformanceMetric **ptr = &list->head;

    while (*ptr != NULL) {
        NetworkPerformanceMetric *entry = *ptr;

        if (entry->session_id == session_id) {
            *ptr = entry->next;  // Remove the metric

            free(entry->measurements);
            free(entry);

            if (list->log_callback) {
                char log_msg[256];
                sprintf(log_msg, "Deleted metric for session %d", session_id);
                list->log_callback(log_msg);
            }
            pthread_mutex_unlock(&list->lock);
            return;
        } else {
            ptr = &entry->next;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

// Configuration interface
void set_retention_policy(PerformanceMetricsList *list, time_t retention_time) {
    pthread_mutex_lock(&list->lock);
    list->retention_time = retention_time;
    pthread_mutex_unlock(&list->lock);
}

void set_size_threshold(PerformanceMetricsList *list, size_t size_threshold) {
    pthread_mutex_lock(&list->lock);
    list->size_threshold = size_threshold;
    pthread_mutex_unlock(&list->lock);
}

// Example logging function
void log_to_console(const char* message) {
    printf("%s\n", message);
}

int main() {
    PerformanceMetricsList metrics_list;

    init_performance_metrics_list(
        &metrics_list,
        100,  // size threshold
        60 * 60,  // retention time (1 hour)
        log_to_console);

    Measurement measurements[] = {{10.0, 20.0, 5.0}};

    insert_metric(&metrics_list, 1, 1, measurements);
    delete_metric(&metrics_list, 1);

    set_retention_policy(&metrics_list, 30 * 60);  // 30 minutes
    set_size_threshold(&metrics_list, 200);

    return 0;
}
