#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

#define MAX_STRUCTURES 1000000
#define STRUCTURE_LIMIT (1024 * 1024) // 1 MiB per structure

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG; // Randomly set to 0 or 1
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    uint64_t allocation_count;
    double total_allocation_time; // in microseconds
    uint32_t seed;
    int logging_enabled;
} CRCManager;

static void *allocate_memory(size_t size);
static void free_memory(void *ptr, size_t size);

CRCManager* create_crc_manager(uint32_t custom_seed, int enable_logging) {
    CRCManager *manager = (CRCManager*)malloc(sizeof(CRCManager));
    if (!manager) return NULL;

    manager->array = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->allocation_count = 0;
    manager->total_allocation_time = 0.0;
    manager->seed = custom_seed ? custom_seed : time(NULL);
    manager->logging_enabled = enable_logging;

    srand(manager->seed);
    return manager;
}

int resize_array(CRCManager *manager, size_t new_capacity) {
    if (new_capacity > MAX_STRUCTURES)
        return -1; // Exceeds maximum allowed structures

    NFAPI_CRC_INDICATION_PDU_T *new_array = allocate_memory(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) return -1;

    size_t elements_to_copy = manager->count < new_capacity ? manager->count : new_capacity;
    memcpy(new_array, manager->array, elements_to_copy * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    free_memory(manager->array, manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->array = new_array;
    manager->capacity = new_capacity;

    if (manager->logging_enabled) {
        printf("Array resized to %zu elements.\n", new_capacity);
    }

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* add_crc_pdu(CRCManager *manager) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        if (resize_array(manager, manager->capacity ? manager->capacity * 2 : 1)) {
            pthread_mutex_unlock(&manager->lock);
            return NULL; // Failed to resize
        }
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &manager->array[manager->count++];
    pdu->RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
    pdu->RNTI = rand() % UINT16_MAX;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu->CRCFLAG = rand() % 2;

    manager->allocation_count++;

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    // Simulate allocation time (in reality, this would be part of the resize logic)
    clock_gettime(CLOCK_MONOTONIC, &end);

    double elapsed = (end.tv_sec - start.tv_sec) * 1e6 + (end.tv_nsec - start.tv_nsec) / 1e3;
    manager->total_allocation_time += elapsed;

    if (manager->logging_enabled) {
        printf("Added PDU at index %zu. Total allocated: %zu\n", manager->count - 1, manager->allocation_count);
    }

    pthread_mutex_unlock(&manager->lock);

    return pdu;
}

void free_crc_manager(CRCManager *manager) {
    if (manager) {
        free_memory(manager->array, manager->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

static void *allocate_memory(size_t size) {
    void *ptr = aligned_alloc(64, size); // Align to cache line
    if (!ptr)
        perror("Memory allocation failed");
    return ptr;
}

static void free_memory(void *ptr, size_t size) {
    if (ptr)
        free(ptr);
}
```

### Explanation:

1. **CRCManager**: Manages the array of structures with a mutex for thread safety.
2. **create_crc_manager**: Initializes the manager and allows setting a custom seed for randomness.
3. **resize_array**: Doubles the capacity when needed, reallocating memory efficiently.
4. **add_crc_pdu**: Adds a new structure to the managed array, resizing if necessary, and logs allocation details.
5. **free_crc_manager**: Cleans up resources, freeing allocated memory.
6. **allocate_memory/free_memory**: Allocates aligned memory to optimize cache usage.

This implementation is designed for high concurrency with minimal fragmentation while logging performance metrics.']

