    snprintf(msg.content, sizeof(msg.content), "Random content %d", msg.message_type);
    return msg;
}

FiveG_RRC_InitialUEMessage *get_cached_message() {
    pthread_mutex_lock(&cache_lock);
    if (cache_count > 0) {
        FiveG_RRC_InitialUEMessage *msg = &cache[--cache_count];
