        return NULL;
    }
    memset(new_array + current_size, 0, (new_size - current_size) * sizeof(FiveG_RRC_InitialUEMessage));
    message_array = new_array;
    current_size = new_size;
    return new_array;
}

int initialize_messages(size_t num_elements) {
