        return -1;
    }

    pthread_mutex_lock(&array_mutex);
    for (size_t i = 0; i < num_elements; ++i) {
        FiveG_RRC_InitialUEMessage *msg = get_cached_message();
        if (!msg) {
            msg = &message_array[i];
        }

        if (initialize_encoder(&msg->encoder)) {
            log_error("Failed to initialize encoder");
            pthread_mutex_unlock(&array_mutex);
            return -1;
        }

        msg->rrc_message = generate_random_message();

        cache_message(msg); // Cache the message for reuse
    }
    pthread_mutex_unlock(&array_mutex);

    return 0;
}

void resize_messages(size_t new_size) {
    if (new_size > current_size) {
        initialize_messages(new_size);
    } else if (new_size < current_size) {
        size_t elements_to_free = current_size - new_size;
        for (size_t i = new_size; i < current_size; ++i) {
            cache_message(&message_array[i]);
        }
        message_array = realloc(message_array, new_size * sizeof(FiveG_RRC_InitialUEMessage));
        if (!message_array) {
            log_error("Memory reallocation failed");
            return;
        }
        current_size = new_size;
    }
}

void free_resources() {
    pthread_mutex_lock(&array_mutex);
    for (size_t i = 0; i < current_size; ++i) {
        cache_message(&message_array[i]);
    }
    pthread_mutex_unlock(&array_mutex);

    free(message_array);
    message_array = NULL;

