typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

#define MAX_MEMORY_USAGE 1024 * 1024 // Example memory quota per thread
#define MAX_DNS_ATTEMPTS 3

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

bool check_memory_usage(size_t size) {
    return size <= MAX_MEMORY_USAGE;
}

int dns_resolution(const char* hostname, u_char ip[4]) {
    struct addrinfo hints, *res, *p;
    int attempts = 0;
    time_t start_time;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    while (attempts < MAX_DNS_ATTEMPTS) {
        attempts++;
        start_time = time(NULL);

        int status = getaddrinfo(hostname, NULL, &hints, &res);
        if (status == 0) {
            for (p = res; p != NULL; p = p->ai_next) {
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                memcpy(ip, &(ipv4->sin_addr), sizeof(struct in_addr));
                break;
            }
            freeaddrinfo(res);
            printf("DNS resolution for %s succeeded. Time taken: %ld seconds\n", hostname, time(NULL) - start_time);
            return 0; // Success
        } else {
            log_error(gai_strerror(status));
        }
    }

    log_error("Max DNS attempts exceeded.");
    return -1; // Failure after max attempts
}

Node* create_node(unsigned short rnti, bool crc_flag) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node || !check_memory_usage(sizeof(Node))) {
        free(node);
        log_error("Memory allocation failed for new node.");
        exit(EXIT_FAILURE);
    }
    node->data.rx_ue_information_tag.RNTI = rnti;
    node->data.crc_indication_rel8_tag.CRCFLAG = crc_flag;
    node->next = NULL;
    return node;
}

Node* create_linked_list(unsigned int N, unsigned int M) {
    if (N > M) {
        log_error("Specified number of elements exceeds the maximum allowed.");
        exit(EXIT_FAILURE);
    }

    Node* head = NULL;
    Node** current = &head;

    for (unsigned int i = 1; i <= N; ++i) {
        bool crc_flag = rand() % 2 == 0;
        *current = create_node(i, crc_flag);
        current = &((*current)->next);
    }
    return head;
}

void free_linked_list(Node* head) {
    Node* tmp;
    while (head != NULL) {
        tmp = head;
        head = head->next;
        free(tmp);
    }

    if (head == NULL) {
        printf("All memory successfully deallocated.\n");
    } else {
        log_error("Memory deallocation failed.");
    }
}

void print_linked_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("RNTI: %u, CRCFLAG: %s\n", current->data.rx_ue_information_tag.RNTI,
               current->data.crc_indication_rel8_tag.CRCFLAG ? "true" : "false");
        current = current->next;
    }
}

void* process_list(void* arg) {
    Node* head = (Node*)arg;

    pthread_mutex_lock(&list_mutex);
    print_linked_list(head);
    pthread_mutex_unlock(&list_mutex);

    free_linked_list(head);
    return NULL;
}

int main() {
    srand(time(NULL));

    unsigned int N = 5; // Number of elements
    unsigned int M = 10; // Maximum limit

    Node* list = create_linked_list(N, M);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, process_list, (void*)list) != 0) {
        log_error("Failed to create thread.");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread_id, NULL);

    u_char ip[4];
    dns_resolution("example.com", ip);
    printf("IP Address: %s\n", inet_ntoa(*(struct in_addr*)ip));

    return 0;
}
