    uint16_t RNTI;
    int CRCFLAG; // Randomly generated value
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    CRC_INDICATION_REL8_TAG *crc_tags;
    size_t count;
    unsigned long ref_count;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize a single CRC_INDICATION_PDU structure
NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu(size_t tag_count) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->crc_tags = (CRC_INDICATION_REL8_TAG*)calloc(tag_count, sizeof(CRC_INDICATION_REL8_TAG));
    if (!pdu->crc_tags) {
        free(pdu);
        return NULL;
    }

    pdu->count = tag_count;
    pdu->ref_count = 1;

    // Initialize CRC tags
    for (size_t i = 0; i < tag_count; ++i) {
        pdu->crc_tags[i].RX_UE_INFORMATION_TAG = rand() % 10000; // Example tag generation
        pdu->crc_tags[i].RNTI = i * 10 + rand() % 10;
        pdu->crc_tags[i].CRCFLAG = rand() & 1; // Randomly set CRCFLAG to 0 or 1
    }

    return pdu;
}

// Reference counting functions
void retain_crc_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu) ++pdu->ref_count;
}

void release_crc_pdu(NFAPI_CRC_INDICATION_PDU_T **pdu_ptr) {
    if (!*pdu_ptr) return;

    NFAPI_CRC_INDICATION_PDU_T *pdu = *pdu_ptr;
    --pdu->ref_count;

    if (pdu->ref_count == 0) {
        free(pdu->crc_tags);
        free(pdu);
        *pdu_ptr = NULL;
    }
}

// Function to manage a pool of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** manage_crc_pdu_pool(size_t N, size_t tag_count_per_pdu) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T **pool = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!pool) return NULL;

    for (size_t i = 0; i < N; ++i) {
        pool[i] = create_crc_pdu(tag_count_per_pdu);
        if (!pool[i]) {
            // Clean up already allocated PDUs in case of failure
            for (size_t j = 0; j < i; ++j) {
                release_crc_pdu(&pool[j]);
            }
            free(pool);
            return NULL;
        }
    }

    return pool;
}

// Example usage
int main() {
    size_t N = 5;
    size_t tag_count_per_pdu = 3;

    NFAPI_CRC_INDICATION_PDU_T **pdu_pool = manage_crc_pdu_pool(N, tag_count_per_pdu);
    if (!pdu_pool) {
        printf("Failed to allocate PDU pool.\n");
        return -1;
    }

    // Use the PDUs
    for (size_t i = 0; i < N; ++i) {
        retain_crc_pdu(pdu_pool[i]); // Increase ref count

        // Access CRC tags
        for (size_t j = 0; j < tag_count_per_pdu; ++j) {
            printf("PDU[%zu] TAG[%zu]: RX_UE_INFORMATION_TAG=%u, RNTI=%hu, CRCFLAG=%d\n",
                   i, j, pdu_pool[i]->crc_tags[j].RX_UE_INFORMATION_TAG,
                   pdu_pool[i]->crc_tags[j].RNTI, pdu_pool[i]->crc_tags[j].CRCFLAG);
        }

        release_crc_pdu(&pdu_pool[i]); // Decrease ref count
    }

    free(pdu_pool);
    return 0;
}
