#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_ARRAYS 100
#define MAX_ELEMENTS 10000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    pthread_mutex_t lock;
} PDUArray;

// Global array of pointers to manage multiple arrays
PDUArray* pdu_arrays[MAX_ARRAYS];
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize a new PDU array with the specified number of elements
int initialize_pdu_array(size_t num_elements) {
    if (num_elements > MAX_ELEMENTS || num_elements == 0) return -1;

    pthread_mutex_lock(&global_lock);

    for (int i = 0; i < MAX_ARRAYS; ++i) {
        if (!pdu_arrays[i]) {
            PDUArray* array = malloc(sizeof(PDUArray));
            if (!array) {
                pthread_mutex_unlock(&global_lock);
                return -1;
            }
            array->data = calloc(num_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!array->data) {
                free(array);
                pthread_mutex_unlock(&global_lock);
                return -1;
            }
            array->size = num_elements;
            pthread_mutex_init(&array->lock, NULL);

            pdu_arrays[i] = array;

            // Release the global lock before entering individual array locks
            pthread_mutex_unlock(&global_lock);
            return i;  // Return index of allocated array
        }
    }

    pthread_mutex_unlock(&global_lock);
    return -1;  // No space left for new arrays
}

// Function to update an element in a specific PDU array
int update_pdu_element(int array_index, size_t element_index, const NFAPI_CRC_INDICATION_PDU_T* new_data) {
    if (array_index < 0 || array_index >= MAX_ARRAYS || !pdu_arrays[array_index]) return -1;

    pthread_mutex_lock(&pdu_arrays[array_index]->lock);

    if (element_index >= pdu_arrays[array_index]->size) {
        pthread_mutex_unlock(&pdu_arrays[array_index]->lock);
        return -1;
    }

    memcpy(&pdu_arrays[array_index]->data[element_index], new_data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&pdu_arrays[array_index]->lock);
    return 0;
}

// Function to delete an element in a specific PDU array
int delete_pdu_element(int array_index, size_t element_index) {
    if (array_index < 0 || array_index >= MAX_ARRAYS || !pdu_arrays[array_index]) return -1;

    pthread_mutex_lock(&pdu_arrays[array_index]->lock);

    if (element_index >= pdu_arrays[array_index]->size) {
        pthread_mutex_unlock(&pdu_arrays[array_index]->lock);
        return -1;
    }

    memset(&pdu_arrays[array_index]->data[element_index], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_unlock(&pdu_arrays[array_index]->lock);
    return 0;
}

// Function to free a specific PDU array
void free_pdu_array(int array_index) {
    if (array_index < 0 || array_index >= MAX_ARRAYS || !pdu_arrays[array_index]) return;

    pthread_mutex_lock(&global_lock);

    pthread_mutex_lock(&pdu_arrays[array_index]->lock);
    free(pdu_arrays[array_index]->data);
    pthread_mutex_destroy(&pdu_arrays[array_index]->lock);
    free(pdu_arrays[array_index]);

    pdu_arrays[array_index] = NULL;
    pthread_mutex_unlock(&global_lock);
}

// Main function to demonstrate usage
int main() {
    int array_idx = initialize_pdu_array(1000);

    if (array_idx < 0) {
        fprintf(stderr, "Failed to allocate PDU Array\n");
        return EXIT_FAILURE;
    }

    // Example data update and deletion
    NFAPI_CRC_INDICATION_PDU_T example_data = {1234, 5678, {.CRCFLAG = 1}};
    update_pdu_element(array_idx, 0, &example_data);

    delete_pdu_element(array_idx, 0);

    free_pdu_array(array_idx);
    return EXIT_SUCCESS;
}
