    SensorNetworkPDU* network = (SensorNetworkPDU*)malloc(sizeof(SensorNetworkPDU));
    if (!network) return NULL;

    network->head = NULL;
    pthread_mutex_init(&network->lock, NULL);
    return network;
}

int add_sensor_node(SensorNetworkPDU* network, int id, time_t timestamp,
                    int validity_flag, float temp_threshold, float humidity_threshold) {
    if (!network || !pthread_mutex_lock(&network->lock)) return -1;

    SensorNode* new_node = (SensorNode*)malloc(sizeof(SensorNode));
    if (!new_node) {
        pthread_mutex_unlock(&network->lock);
        return -1;
