    new_node->timestamp = timestamp;
    new_node->data_validity_flag = validity_flag;
    new_node->temperature_threshold = temp_threshold;
    new_node->humidity_threshold = humidity_threshold;
    new_node->next = network->head;

    network->head = new_node;
    pthread_mutex_unlock(&network->lock);
    return 0;
}

int remove_sensor_node(SensorNetworkPDU* network, int id) {
    if (!network || !pthread_mutex_lock(&network->lock)) return -1;

    SensorNode *current = network->head, *prev = NULL;
    while (current && current->ID != id) {
        prev = current;
        current = current->next;
    }

    if (!current) { // Node not found
        pthread_mutex_unlock(&network->lock);
        return -1;
    }

    if (!prev)
        network->head = current->next; // Remove head
    else
        prev->next = current->next;

    free(current);
    pthread_mutex_unlock(&network->lock);
    return 0;
}

void free_sensor_network(SensorNetworkPDU* network) {
    if (!network) return;

    SensorNode *current = network->head, *next_node;
    while (current) {
        next_node = current->next;
        free(current);
        current = next_node;
    }

    pthread_mutex_destroy(&network->lock);
    free(network);
}

// Example usage
