#include <time.h>

#define MAX_NODES 50000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int ID;
    time_t timestamp;
    float temperature;
    float humidity;
    int data_validity_flag;
    // Add more attributes as needed
} SensorNode;

typedef struct {
    SensorNode *nodes;
    size_t node_count;
    pthread_mutex_t lock;
} SensorNetworkPDU;

// Function prototypes
void initialize_sensor_network(SensorNetworkPDU *network, size_t initial_size);
void update_thresholds(float *temp_threshold, float *humidity_threshold);
void add_node(SensorNetworkPDU *network, const SensorNode *node);
void remove_node(SensorNetworkPDU *network, int node_id);
void free_sensor_network(SensorNetworkPDU *network);

// Function to initialize the sensor network
void initialize_sensor_network(SensorNetworkPDU *network, size_t initial_size) {
    pthread_mutex_init(&network->lock, NULL);
    network->node_count = 0;
    network->nodes = (SensorNode *)malloc(initial_size * sizeof(SensorNode));
    if (!network->nodes) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

// Function to update thresholds dynamically
void update_thresholds(float *temp_threshold, float *humidity_threshold) {
    // Simulate fetching data from an API
    srand(time(NULL));
    *temp_threshold = 20.0 + (rand() % 15); // Random threshold between 20 and 35
    *humidity_threshold = 40.0 + (rand() % 30); // Random threshold between 40 and 70
}

// Function to add a node to the network
void add_node(SensorNetworkPDU *network, const SensorNode *node) {
    pthread_mutex_lock(&network->lock);
    if (network->node_count < MAX_NODES) {
        network->nodes[network->node_count++] = *node;
    } else {
        fprintf(stderr, "Maximum node limit reached\n");
    }
    pthread_mutex_unlock(&network->lock);
}

// Function to remove a node from the network
void remove_node(SensorNetworkPDU *network, int node_id) {
    pthread_mutex_lock(&network->lock);
    for (size_t i = 0; i < network->node_count; ++i) {
        if (network->nodes[i].ID == node_id) {
            for (size_t j = i; j < network->node_count - 1; ++j) {
                network->nodes[j] = network->nodes[j + 1];
            }
            --network->node_count;
            break;
        }
    }
    pthread_mutex_unlock(&network->lock);
}

// Function to free the sensor network
void free_sensor_network(SensorNetworkPDU *network) {
    pthread_mutex_lock(&network->lock);
    free(network->nodes);
    pthread_mutex_unlock(&network->lock);
    pthread_mutex_destroy(&network->lock);
}

// Main function for demonstration purposes
int main() {
    SensorNetworkPDU network;
    initialize_sensor_network(&network, 1000);

    update_thresholds(NULL, NULL); // Example usage

    SensorNode node = {1, time(NULL), 25.5, 55.0, 1};
    add_node(&network, &node);

    remove_node(&network, 1);
    free_sensor_network(&network);

    return 0;
}
